```javascript
/**
 * Asynchronous reduce function for an array of numbers.
 * 
 * @param {number[]} arr - The array of numbers to be reduced.
 * @param {number} initialValue - The initial value for the reduction.
 * @param {function} callback - A function that takes two arguments: the accumulated value and the current number.
 * @returns {Promise<number>} - A promise that resolves with the final reduced value or rejects with an error message.
 */
async function asyncReduce(arr, initialValue, callback) {
  if (!Array.isArray(arr)) throw new Error("Input is not a valid array");
  if (typeof callback !== 'function') throw new TypeError("Callback must be a function");

  let accumulated = initialValue;

  const processNext = async () => {
    for (let i = 0; i < arr.length; i++) {
      try {
        // Check for non-numeric values
        if (typeof arr[i] !== 'number') throw new Error(`Invalid element at index ${i}: ${arr[i]} is not a number`);

        accumulated = await callback(accumulated, arr[i]);
      } catch (error) {
        return Promise.reject(error);
      }
    }

    return accumulated;
  };

  // Use promise-based approach to handle asynchronous reduction
  try {
    return await processNext();
  } catch (error) {
    return Promise.reject(`Reduction error: ${error.message}`);
  }
}

// Example test cases

(async () => {
  const callback = async (acc, num) => new Promise((resolve) =>
    setTimeout(() => resolve(acc + num), 10)
  );

  try {
    console.log(await asyncReduce([1, 2, 3, 4], 0, callback)); // Should print 10
    console.log(await asyncReduce([], 5, callback)); // Should print 5 (empty array case)
    console.log(await asyncReduce([1, 'a', 3], 0, callback)); // Should throw an error
  } catch (error) {
    console.error(error.message);
  }
})();
```

### Explanation:

- **Error Handling**: Checks are made for non-array inputs and non-function callbacks. Each element is validated to ensure it's a number during processing.
- **Asynchronous Processing**: The reduction operation uses `async/await` with promises, allowing asynchronous behavior while iterating over the array.
- **Test Cases**: Demonstrates normal functionality as well as handling of edge cases like empty arrays and non-numeric values.

```php
<?php

// Autoload vendor dependencies
require 'vendor/autoload.php';

use Psr\Log\LoggerInterface;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

/**
 * Setup logger for the application.
 */
function setupLogger(): LoggerInterface {
    $logger = new Logger('app');
    $logger->pushHandler(new StreamHandler(__DIR__ . '/logs/app.log', Logger::DEBUG));

    return $logger;
}

// Initialize Logger
$logger = setupLogger();

/**
 * Fetch environment variable safely with a default fallback.
 */
function getEnv($key, $default = null) {
    global $logger;

    try {
        return getenv($key) ?: $default;
    } catch (Exception $e) {
        $logger->error("Failed to retrieve ENV[$key]: " . $e->getMessage());
        return $default;
    }
}

/**
 * Load configuration settings from a file or cache.
 */
function loadConfiguration(): array {
    global $logger;

    $env = getEnv('ENV', 'production');
    $configCacheFile = __DIR__ . "/cache/config_{$env}.php";

    // Attempt to load cached configuration
    if (file_exists($configCacheFile)) {
        try {
            return require $configCacheFile;
        } catch (Exception $e) {
            $logger->error("Failed to load cached config: " . $e->getMessage());
        }
    }

    // Load from configuration file or external database
    $config = loadConfigurationFromSource($env);

    // Cache the configuration for future use
    cacheConfiguration($env, $config);

    return $config;
}

/**
 * Load configuration from a source.
 */
function loadConfigurationFromSource(string $env): array {
    global $logger;

    try {
        if ($env === 'production') {
            // Example: Fetch config from an external database for production
            return fetchConfigFromDatabase();
        } else {
            // Use local configuration files for other environments
            $configFile = __DIR__ . "/config/{$env}.php";

            if (!file_exists($configFile)) {
                throw new Exception("Configuration file not found: {$configFile}");
            }

            return require $configFile;
        }
    } catch (Exception $e) {
        $logger->critical("Failed to load configuration for environment [$env]: " . $e->getMessage());
        exit(1);
    }
}

/**
 * Fetch configuration settings from a database.
 */
function fetchConfigFromDatabase(): array {
    global $logger;

    try {
        // Example: PDO connection setup
        $dsn = 'mysql:host=db_host;dbname=app_db';
        $pdo = new PDO($dsn, 'username', 'password');

        $stmt = $pdo->query('SELECT * FROM configurations WHERE environment = :environment');
        $stmt->execute([':environment' => getEnv('ENV', 'production')]);

        return $stmt->fetch(PDO::FETCH_ASSOC);
    } catch (PDOException $e) {
        $logger->error("Database connection failed: " . $e->getMessage());
        exit(1);
    }
}

/**
 * Cache the configuration settings.
 */
function cacheConfiguration(string $env, array $config): void {
    global $logger;

    try {
        $cacheFile = __DIR__ . "/cache/config_{$env}.php";
        file_put_contents($cacheFile, '<?php return ' . var_export($config, true) . ';');
    } catch (Exception $e) {
        $logger->warning("Failed to cache configuration: " . $e->getMessage());
    }
}

/**
 * Clean up temporary files or data.
 */
function cleanupResources(): void {
    global $logger;

    try {
        $tempFiles = glob(__DIR__ . '/cache/*.tmp');
        foreach ($tempFiles as $file) {
            unlink($file);
        }
    } catch (Exception $e) {
        $logger->warning("Cleanup failed: " . $e->getMessage());
    }
}

// Load and configure application
$config = loadConfiguration();

// Application setup based on configuration...
// ...

// Clean up resources at the end of script execution
cleanupResources();
