```javascript
async function fetchScriptContent(src) {
  try {
    const response = await fetch(src);
    if (!response.ok) throw new Error(`Network error: ${response.statusText}`);
    return await response.text();
  } catch (error) {
    console.error(`Error fetching script from ${src}:`, error.message);
    return null;
  }
}

function renderScriptTag(scriptContent, type, key) {
  const nonce = 'yourNonceValue'; // Replace with your actual nonce value if needed
  return `<script src="${scriptContent.src}" type="${type}" key="${key}"${nonce ? ` nonce="${nonce}"` : ''}></script>`;
}

async function renderFooterScripts(scripts) {
  const cache = new Map();

  for (const script of scripts) {
    if (!script.src && !script.code || typeof script.type !== 'string' || typeof script.key !== 'string') {
      console.warn(`Invalid script object:`, script);
      continue;
    }

    let scriptContent;
    if (script.src) {
      if (cache.has(script.src)) {
        scriptContent = cache.get(script.src);
      } else {
        const fetchedContent = await fetchScriptContent(script.src);
        if (fetchedContent !== null) {
          cache.set(script.src, scriptContent = `<script src="${script.src}" type="text/javascript"></script>`);
        }
      }
    } else {
      scriptContent = `<script>${script.code}</script>`;
    }

    if (scriptContent) {
      document.querySelector('footer').innerHTML += renderScriptTag(scriptContent, script.type, script.key);
    }
  }

  return Array.from(cache.values()).join('');
}

// Example usage
(async () => {
  const scripts = [
    { src: 'https://external-script.com/script.js', type: 'text/javascript', key: 'external-script' },
    { code: '<script>alert("Hello World!");</script>', type: 'text/javascript', key: 'inline-script' }
  ];

  console.log(await renderFooterScripts(scripts));
})();
