<?php

function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
    // Database credentials and configurations
    $dbHost = 'localhost';
    $dbName = 'your_database_name';
    $dbUser = 'your_db_user';
    $dbPass = 'your_db_password';

    try {
        // Establish a database connection using PDO
        $pdo = new PDO("mysql:host=$dbHost;dbname=$dbName", $dbUser, $dbPass);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Check rate limit: 5 updates per IP address per minute
        $rateLimitTimeframe = 60;
        $maxUpdatesPerTimeframe = 5;

        $stmt = $pdo->prepare("SELECT COUNT(*) FROM update_log WHERE ip_address = :ip AND modified_date >= (NOW() - INTERVAL :minutes MINUTE)");
        $stmt->execute([':ip' => $ipAddress, ':minutes' => $rateLimitTimeframe]);
        $updateCount = $stmt->fetchColumn();

        if ($updateCount >= $maxUpdatesPerTimeframe) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        // Begin transaction
        $pdo->beginTransaction();

        // Fetch current status for comparison
        $currentStatusStmt = $pdo->prepare("SELECT status FROM clinics WHERE id = :id");
        $currentStatusStmt->execute([':id' => $clinicId]);
        $currentStatus = $currentStatusStmt->fetchColumn();

        // Update clinic status if different from the new status
        if ($currentStatus !== $newStatus) {
            $updateClinicStmt = $pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
            $updateClinicStmt->execute([':status' => $newStatus, ':ip' => $ipAddress, ':id' => $clinicId]);

            // Log the update action
            $logUpdateStmt = $pdo->prepare("INSERT INTO update_log (clinic_id, status, ip_address, modified_date) VALUES (:clinic_id, :status, :ip, NOW())");
            $logUpdateStmt->execute([':clinic_id' => $clinicId, ':status' => $newStatus, ':ip' => $ipAddress]);

            // Notify external API if the status is "closed" or "emergency"
            if (in_array($newStatus, ['closed', 'emergency'])) {
                notifyExternalAPI($clinicId, $newStatus);
            }

            // Commit transaction
            $pdo->commit();
        } else {
            // Rollback if no changes were made
            $pdo->rollBack();
        }
    } catch (Exception $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack(); // Ensure rollback on any failure during the transaction
        }

        // Log error (implement your own logging mechanism)
        error_log($e->getMessage());

        // Return a user-friendly message or handle gracefully
        echo "An error occurred: " . $e->getMessage();
    }
}

function notifyExternalAPI($clinicId, $status) {
    $apiUrl = 'https://external-api.example.com/notify';
    $payload = json_encode(['clinic_id' => $clinicId, 'status' => $status]);

    try {
        // Prepare and send the request
        $ch = curl_init($apiUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
        curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);

        $response = curl_exec($ch);

        if (curl_errno($ch)) {
            throw new Exception(curl_error($ch));
        }

        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        if ($httpCode !== 200) {
            throw new Exception("API request failed with HTTP status code " . $httpCode);
        }
    } catch (Exception $e) {
        // Log the API error and handle it gracefully
        error_log('Failed to notify external API: ' . $e->getMessage());
    } finally {
        curl_close($ch);
    }
}

?>
