use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};
use rustc_driver::{catch_with_error, Compilation, Config};
use log::{info, warn, error};
use sys_info;

// Placeholder for the remote build server API integration
fn upload_to_build_server(summary: &str, errors: &[String]) {
    // Implement API call to upload summary and errors
}

struct CompilationSummary {
    total_time: Duration,
    peak_memory_usage: u64,
    warnings: Vec<String>,
    errors: Vec<String>,
}

fn compile_directory(dir_path: &Path) -> Result<CompilationSummary, String> {
    let start_time = Instant::now();
    let mut summary = CompilationSummary {
        total_time: Duration::new(0, 0),
        peak_memory_usage: 0,
        warnings: vec![],
        errors: vec![],
    };

    // Custom log hook
    fn custom_log_hook(message: &str) {
        match message {
            "Warning" => info!("Compilation warning: {}", message),
            "Error" => error!("Compilation error: {}", message),
            _ => warn!("Other log: {}", message),
        }
    }

    let mut config = Config::default();
    config.rustc_options.push("log=info".into());

    // Custom compilation function
    fn custom_compile(file_path: &Path) -> Result<(), String> {
        catch_with_error(move |compiler_args| {
            compiler_args.main_args.push("--crate-type=lib");
            let output = compiler_args.compile();
            match output {
                Ok(Compilation { messages, .. }) => {
                    for message in messages.iter() {
                        custom_log_hook(&message.message);
                    }
                    if !messages.iter().all(|m| m.severity == rustc_driver::MessageSeverity::Note) {
                        Err("Compilation failed with warnings/errors".into())
                    } else {
                        Ok(())
                    }
                },
                Err(e) => Err(format!("Compilation error: {:?}", e)),
            }
        }, &config)
    }

    // Read directory and compile each .rs file
    if dir_path.is_dir() {
        for entry in fs::read_dir(dir_path).map_err(|e| format!("Failed to read directory: {}", e))? {
            let path = entry.map_err(|e| format!("Failed to access entry: {}", e))?.path();
            if path.extension().and_then(std::ffi::OsStr::to_str) == Some("rs") {
                if let Err(e) = custom_compile(&path) {
                    summary.errors.push(format!("Error in {}: {}", path.display(), e));
                }
            }
        }
    }

    // Measure total time
    summary.total_time = start_time.elapsed();

    // Measure peak memory usage
    match sys_info::mem_info() {
        Ok(mem_info) => {
            if let Some(usage) = mem_info.ram_used {
                summary.peak_memory_usage = usage;
            }
        },
        Err(_) => error!("Failed to get memory info"),
    }

    // Upload results to build server
    upload_to_build_server(
        &format!(
            "Total Time: {:?}, Peak Memory Usage: {} bytes",
            summary.total_time,
            summary.peak_memory_usage
        ),
        &summary.errors,
    );

    Ok(summary)
}

fn main() {
    let dir_path = Path::new("path/to/directory");
    match compile_directory(dir_path) {
        Ok(summary) => println!("Compilation successful: {:?}", summary),
        Err(e) => eprintln!("Failed to compile directory: {}", e),
    }
}
