```php
<?php

class PasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()';

    public function generateRandomString($length) {
        if (!$this->validateCharacterSet($this->characterSet)) {
            throw new Exception("Invalid character set.");
        }

        $charactersLength = strlen($this->characterSet);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[random_int(0, $charactersLength - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        if (!$this->validateCharacterSet($this->characterSet)) {
            throw new Exception("Invalid character set.");
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        $uppercase = preg_match('@[A-Z]@', $characterSet);
        $lowercase = preg_match('@[a-z]@', $characterSet);
        $digits = preg_match('@[\d]@', $characterSet);
        $specialChars = preg_match('@[!@#$%^&*()]@', $characterSet);

        return ($uppercase && $lowercase && $digits && $specialChars);
    }

    public function setSaltRoundCount($rounds) {
        if (!is_int($rounds) || $rounds < 4) { // Bcrypt minimum cost is 4
            throw new Exception("Invalid salt round count. It must be an integer greater than or equal to 4.");
        }

        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        if ($this->hashedPassword === null) {
            throw new Exception("No password has been set to reset.");
        }

        $randomString = $this->generateRandomString(12); // Example length for a random string
        $this->hashPassword($randomString);
    }
}

?>
