```rust
use std::env;
use std::fs::{self, create_dir};
use std::io;
use std::path::{PathBuf, Path};
use std::sync::{Arc, Mutex};
use log::{error, info};

fn manage_directory(env_var: &str) -> Result<(), io::Error> {
    // Retrieve the existing directory path from the environment variable
    let current_path = env::var(env_var).ok();

    if let Some(existing_dir) = current_path {
        // Path exists, check if it is valid and still a directory
        if !PathBuf::from(&existing_dir).is_dir() {
            error!("Existing directory for '{}' does not exist or is no longer a directory.", env_var);
            return Err(io::Error::new(io::ErrorKind::Other, "Invalid directory"));
        }
    } else {
        // No existing path, create new directory and set environment variable
        let temp_dir = tempfile::Builder::new().prefix("temp_dir_").tempdir()?;

        if let Ok(ref mut env_map) = Arc::get_mut(&mut ENV_MAP.lock().unwrap()) {
            // Ensure the creation of a unique temporary directory and clean up old ones
            while let Some((key, value)) = env_map.iter().next() {
                if !PathBuf::from(value).exists() {
                    env_map.remove(key);
                } else {
                    break;
                }
            }

            // Set new path in the environment map for tracking
            env_map.insert(env_var.to_string(), temp_dir.path().to_str().unwrap().to_string());
        }

        info!("Created and set environment variable '{}' to '{}'", env_var, temp_dir.path());

        // Set the actual environment variable
        env::set_var(env_var, temp_dir.path().display().to_string())?;
    }

    Ok(())
}

// Shared state across threads for tracking environment paths
lazy_static! {
    static ref ENV_MAP: Arc<Mutex<HashMap<String, String>>> = Arc::new(Mutex::new(HashMap::new()));
}

fn main() -> Result<(), io::Error> {
    env_logger::init();

    // Example usage of the manage_directory function in a multi-threaded context
    let handles: Vec<_> = (0..10).map(|_| {
        std::thread::spawn(|| {
            if let Err(e) = manage_directory("MY_ENV_VAR") {
                error!("Failed to manage directory: {}", e);
            }
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }

    Ok(())
}
```

### Explanation
- The function `manage_directory` checks if the environment variable is already set. If so, it validates that path.
- It uses a temporary directory creation to ensure atomicity and avoid race conditions when setting new directories.
- A shared map (`ENV_MAP`) tracks all environments' paths, allowing for cleanup of unused directories.
- This setup ensures efficient operation in concurrent scenarios by using `Arc` and `Mutex`.
- Error handling is integrated with logging to track issues.

This code should be included in a Rust project where the `tempfile`, `lazy_static`, and `log` crates are added as dependencies. Ensure you initialize the logger, typically via an environment variable like `RUST_LOG`.

