fn process_directory(path: &PathBuf, optimize: bool) -> Result<(), String> {
    let mut files_to_process = VecDeque::new();
    files_to_process.push_back(path.to_path_buf());

    while let Some(dir) = files_to_process.pop_front() {
        if dir.is_dir() {
            for entry in fs::read_dir(&dir).map_err(|e| e.to_string())? {
                let path = entry.map_err(|e| e.to_string())?.path();
                if path.is_dir() || path.extension().and_then(std::ffi::OsStr::to_str) == Some("rs") {
                    files_to_process.push_back(path);
                }
