            let functions = parse_rust_file(&dir)
                .map_err(|e| format!("Failed to parse file '{}': {}", dir.display(), e))?;

            for function in functions {
                debug!("Parsed function: {:?}", function);
                match generate_llvm_ir(&function, optimize) {
