                }
            }
        } else {
            error!("Skipping non-Rust file: {:?}", dir);
        }
    }

    Ok(())
}

fn process_directory_in_parallel(path: &PathBuf, optimize: bool) -> Result<(), String> {
    let path_arc = Arc::new(Mutex::new(vec![path.to_path_buf()]));
    let results = thread::scope(|s| {
        (0..4).map(|_| {
            let path_arc_clone = Arc::clone(&path_arc);
            s.spawn(move |_| {
                if let Ok(mut paths) = path_arc_clone.lock() {
                    while let Some(dir) = paths.pop() {
                        match process_directory(&dir, optimize.clone()) {
                            Ok(_) => {},
                            Err(e) => error!("Error processing directory '{}': {}", dir.display(), e),
                        }
                    }
                }
            })
        }).collect::<Vec<_>>()
    }).map_err(|_| "Thread panicked".to_string())?;

    results
}

fn main() {
    let path = PathBuf::from("src");
    let optimize = true; // Configuration option

    if let Err(e) = process_directory_in_parallel(&path, optimize) {
        error!("Failed to process directory: {}", e);
    }
}
