```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Helper function to capitalize first letter of each word
void capitalizeWords(char *str) {
    if (str == NULL) return;
    int inWord = 0;

    while (*str) {
        if (!inWord && isalpha((unsigned char)*str)) {
            *str = toupper((unsigned char)*str);
            inWord = 1;
        } else if (isalpha((unsigned char)*str)) {
            *str = tolower((unsigned char)*str);
        } else {
            inWord = 0;
        }
        str++;
    }
}

// Helper function to trim specified words from the start and end
char* trimWords(char *str, const char **words, int wordCount) {
    if (str == NULL || words == NULL) return NULL;

    // Trim from beginning
    while (*str && anyMatch(str, words, wordCount)) {
        str += strlen(*str);
        while (*str == ' ') str++;
    }

    // Trim from end
    char *end = str + strlen(str) - 1;
    while (end >= str && *end == ' ') end--;

    int newLength = end - str + 1;

    if (newLength <= 0) return strdup("");

    char *trimmedStr = malloc(newLength + 1);
    if (!trimmedStr) return NULL;
    strncpy(trimmedStr, str, newLength);
    trimmedStr[newLength] = '\0';

    return trimmedStr;
}

// Check if the string matches any of the words
int anyMatch(const char *str, const char **words, int wordCount) {
    for (int i = 0; i < wordCount; ++i) {
        if (strcmp(str, words[i]) == 0)
            return 1;
    }
    return 0;
}

char* trimAndCapitalize(char *inputStr, size_t sizeLimit, const char **words, int wordCount) {
    if (inputStr == NULL || words == NULL || sizeLimit == 0) return NULL;

    // Trim specified words
    char *trimmedStr = trimWords(inputStr, words, wordCount);
    if (!trimmedStr) return NULL;

    size_t trimmedLen = strlen(trimmedStr);

    // Check against size limit
    if (trimmedLen + 1 > sizeLimit) {
        free(trimmedStr);
        return NULL;
    }

    // Capitalize first letter of each word
    capitalizeWords(trimmedStr);

    char *result = strdup(trimmedStr);
    free(trimmedStr); // Free the trimmed string

    if (!result) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    return result;
}
