#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <semaphore.h>
#include <pthread.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t *semaphores[MAX_SEMAPHORES];
    char names[MAX_SEMAPHORES][256];
    int count;
    pthread_mutex_t lock;
} SemaphoreManager;

SemaphoreManager *init_semaphore_manager() {
    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->count = 0;
    sem_init(&manager->lock, 0, 1);
    return manager;
}

int create_semaphore(SemaphoreManager *manager, const char *name) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->count >= MAX_SEMAPHORES || strcmp(manager->names[i], name) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->semaphores[i] == NULL) {
            sem_t *sem = sem_open(name, O_CREAT | O_EXCL, 0644, 0);
            if (sem == SEM_FAILED) {
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }

            manager->semaphores[i] = sem;
            strncpy(manager->names[i], name, sizeof(manager->names[i]) - 1);
            manager->count++;
            pthread_mutex_unlock(&manager->lock);

            log_operation("Created semaphore", name);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int delete_semaphore(SemaphoreManager *manager, const char *name) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->semaphores[i] != NULL && strcmp(manager->names[i], name) == 0) {
            sem_close(manager->semaphores[i]);
            sem_unlink(name);
            manager->semaphores[i] = NULL;
            manager->count--;

            pthread_mutex_unlock(&manager->lock);

            log_operation("Deleted semaphore", name);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int increment_semaphore(SemaphoreManager *manager, const char *name) {
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->semaphores[i] != NULL && strcmp(manager->names[i], name) == 0) {
            pthread_mutex_lock(&manager->lock);
            sem_post(manager->semaphores[i]);
            pthread_mutex_unlock(&manager->lock);

            log_operation("Incremented semaphore", name);
            return 0;
        }
    }

    return -1;
}

int decrement_semaphore(SemaphoreManager *manager, const char *name) {
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->semaphores[i] != NULL && strcmp(manager->names[i], name) == 0) {
            pthread_mutex_lock(&manager->lock);
            if (sem_trywait(manager->semaphores[i]) != 0) {
                log_error("Failed to decrement semaphore", name, errno);
                pthread_mutex_unlock(&manager->lock);
                return -1;
            }
            pthread_mutex_unlock(&manager->lock);

            log_operation("Decremented semaphore", name);
            return 0;
        }
    }

    return -1;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < MAX_SEMAPHORES; ++i) {
        if (manager->semaphores[i] != NULL) {
            sem_close(manager->semaphores[i]);
            sem_unlink(manager->names[i]);
            manager->semaphores[i] = NULL;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void log_operation(const char *operation, const char *name) {
    printf("Log: %s - %s\n", operation, name);
}

void log_error(const char *error_message, const char *name, int error_code) {
    fprintf(stderr, "Error: %s - %s (errno: %d)\n", error_message, name, error_code);
}
