#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* expandStringWithSlash(const char *input, size_t sizeLimit) {
    if (!input || strlen(input) >= sizeLimit) {
        printf("Invalid input or size limit exceeded.\n");
        return NULL;
    }

    size_t requiredSize = strlen(input) + 2; // +1 for slash and \0
    char *result = (char *)malloc(requiredSize);

    if (!result) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    strcpy(result, input);
    result[strlen(input)] = '/';
    result[requiredSize - 1] = '\0';

    return result;
}

int main() {
    char* result;

    result = expandStringWithSlash("hello", 10);
    if (result) {
        printf("%s\n", result); // Should print "hello/"
        free(result);
    } else {
        printf("Input string exceeded size limit or error occurred.\n");
    }

    result = expandStringWithSlash("", 10);
    if (result) {
        printf("%s\n", result); // Should print "/"
        free(result);
    } else {
        printf("Empty string provided.\n");
    }

    result = expandStringWithSlash(NULL, 10);
    if (result) {
        printf("%s\n", result); // Should not happen
        free(result);
    } else {
        printf("Null pointer provided.\n");
    }

    return 0;
}
