#include <string.h>
#include <pthread.h>

#define LOG_ERROR(...) fprintf(stderr, __VA_ARGS__)
#define SUCCESS 0
#define FAILURE -1

// Configuration structure for cryptographic primitives
typedef struct {
    const char* primitive_name;
    int is_cipher; // 1 if cipher, 0 if digest/other
} CryptoConfig;

// Predefined list of supported primitives (for verification)
const char* supported_primitives[] = {
    "aes-128-cbc", "aes-256-cbc", "camellia-128-cbc",
    "md5", "sha1", "rsa"
};
const int num_supported_primitives = sizeof(supported_primitives) / sizeof(supported_primitives[0]);

// Function to load configuration from a file
int load_config(const char* config_file, CryptoConfig** configs) {
    // Placeholder for loading configurations (e.g., from a JSON/YAML/ini file)
    // This example assumes an array is manually populated
    *configs = malloc(3 * sizeof(CryptoConfig)); // Example size
    (*configs)[0] = (CryptoConfig){ .primitive_name = "aes-128-cbc", .is_cipher = 1 };
    (*configs)[1] = (CryptoConfig){ .primitive_name = "md5", .is_cipher = 0 };
    (*configs)[2] = (CryptoConfig){ .primitive_name = "rsa", .is_cipher = 0 };
    return SUCCESS;
}

// Mutex for thread safety
pthread_mutex_t lib_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_crypto_primitives() {
    CryptoConfig* configs = NULL;
    int config_count = load_config("crypto_config.txt", &configs);

    if (config_count == FAILURE) {
        LOG_ERROR("Failed to load configuration.\n");
        return;
    }

    for (int i = 0; i < config_count; ++i) {
        pthread_mutex_lock(&lib_mutex);

        const char* primitive_name = configs[i].primitive_name;

        // Check if the primitive is supported
        int supported = 0;
        for (int j = 0; j < num_supported_primitives; ++j) {
            if (strcmp(primitive_name, supported_primitives[j]) == 0) {
                supported = 1;
                break;
            }
        }

        if (!supported) {
            LOG_ERROR("Unsupported primitive: %s\n", primitive_name);
            pthread_mutex_unlock(&lib_mutex);
            continue;
        }

        int result;
        if (configs[i].is_cipher) {
            // Add cipher
            result = EVP_add_cipher(EVP_aes_128_cbc(), 0); // Example for AES-128-CBC
            if (result != SUCCESS) {
                LOG_ERROR("Failed to add cipher: %s, error code: %d\n", primitive_name, result);
            }
        } else {
            // Add digest or other primitives
            result = EVP_add_digest(EVP_md5(), 0); // Example for MD5
            if (result != SUCCESS) {
                LOG_ERROR("Failed to add digest/other: %s, error code: %d\n", primitive_name, result);
            }
        }

        pthread_mutex_unlock(&lib_mutex);
    }

    free(configs);

    // Verify that all added primitives are successful
    for (int i = 0; i < config_count; ++i) {
        const char* primitive_name = configs[i].primitive_name;
        int found = 0;
        for (int j = 0; j < num_supported_primitives; ++j) {
            if (strcmp(primitive_name, supported_primitives[j]) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            LOG_ERROR("Verification failed for primitive: %s\n", primitive_name);
        } else {
            printf("Successfully added and verified primitive: %s\n", primitive_name);
        }
    }
}

// Unit test example (using a simple assert function)
void run_unit_tests() {
    // Example unit tests
    int aes_added = EVP_add_cipher(EVP_aes_128_cbc(), 0) == SUCCESS;
    if (!aes_added) {
        LOG_ERROR("AES-128-CBC failed to add.\n");
    }
}

int main() {
    add_crypto_primitives();
    run_unit_tests();

    return EXIT_SUCCESS;
}
