// Rust Code (lib.rs)

use std::env;
use std::fs::{self, DirEntry};
use std::ffi::CString;
use std::os::raw::c_char;

#[no_mangle]
pub extern "C" fn rust_create_and_set_directory(directory_name: *const c_char) -> *mut c_char {
    let directory_cstr = unsafe { CString::from_raw(directory_name as *mut _) };
    let dir_name = match directory_cstr.to_str() {
        Ok(name) => name,
        Err(_) => return std::ptr::null_mut(),
    };

    // Check if environment variable is set
    if let Ok(existing_path) = env::var("DIRECTORY_PATH") {
        CString::new(existing_path).unwrap().into_raw()
    } else {
        match fs::create_dir(dir_name) {
            Ok(_) => {
                // Set the environment variable for the session
                env::set_var("DIRECTORY_PATH", dir_name);
                let full_path = format!("{}/{}", env::current_dir().unwrap().display(), dir_name);
                CString::new(full_path).unwrap().into_raw()
            },
            Err(_) => std::ptr::null_mut(),
        }
    }
}

