                        disjointPairCount++;
                    }
                }

                long endTime = System.currentTimeMillis();
                System.out.println("Time taken for pair (" + array[i] + ", " + array[j] + "): " + (endTime - startTime) + " ms");
            }
        }

        return disjointPairCount;
    }

    public static void main(String[] args) {
        int[] inputArray = {4, 7, 10, 6, 9};
        System.out.println("Number of disjoint pairs: " + countDisjointPairs(inputArray));
    }
