    static char* sampleWords[] = {"the", "and", "of", "to", "a"};
    *count = sizeof(sampleWords) / sizeof(sampleWords[0]);
    return sampleWords;
}

// Helper function to capitalize the first letter of each word.
void capitalizeWords(char* str) {
    if (str == NULL) return;

    int inWord = 0;
    while (*str != '\0') {
        if (!isspace((unsigned char)*str)) {
            if (!inWord) {
                *str = toupper((unsigned char)*str);
                inWord = 1;
            }
        } else {
            inWord = 0;
        }
        str++;
    }
}

// Function to trim words from the start and end of a string.
char* trimWords(char* input, const char** words, int wordCount) {
    if (input == NULL || words == NULL) return NULL;

    // Trim leading words
    char *start = input;
    while (*start != '\0') {
        int i;
        for (i = 0; i < wordCount; i++) {
            size_t len = strlen(words[i]);
            if (strncmp(start, words[i], len) == 0 && 
                (start[len] == ' ' || start[len] == '\0')) {
                start += len + 1;
                break;
            }
        }
        if (i == wordCount) break; // Not a match
    }

    // Trim trailing words
    char *end = input + strlen(input);
    while (end > start) {
        int i;
        for (i = 0; i < wordCount; i++) {
            size_t len = strlen(words[i]);
            if (strncmp(end - len, words[i], len) == 0 && 
                ((end[-len-1] == ' ') || (end == start + len))) {
                end -= len + 1;
                break;
            }
        }
        if (i == wordCount) break; // Not a match
    }

    size_t newLength = end - start + 1;
    char* trimmedStr = malloc(newLength);
    if (trimmedStr != NULL) {
        strncpy(trimmedStr, start, newLength - 1);
        trimmedStr[newLength - 1] = '\0';
    }
    return trimmedStr;
}

// Main function to trim and capitalize a string.
char* dynamicTrimAndCapitalize(char* input, int sizeLimit) {
    if (input == NULL || sizeLimit <= 0) return NULL;

    int wordCount;
    const char** words = fetchWordList(&wordCount);
    if (words == NULL) return NULL;

    // Calculate the average length of words
    int totalLength = 0;
    for (int i = 0; i < wordCount; i++) {
        totalLength += strlen(words[i]);
    }
    int avgWordLength = totalLength / wordCount;

    // Adjust size limit based on word list and average word length
    int adjustedSizeLimit = sizeLimit - (wordCount * avgWordLength);

    char* trimmedStr = trimWords(input, words, wordCount);
    if (trimmedStr == NULL) return NULL;

    capitalizeWords(trimmedStr);

    if (strlen(trimmedStr) > adjustedSizeLimit) {
        free(trimmedStr);
        return NULL;
    }

    return trimmedStr;
}

int main() {
    char input[] = "the quick brown fox jumps over the lazy dog";
    int sizeLimit = 50;

    char* result = dynamicTrimAndCapitalize(input, sizeLimit);
    if (result != NULL) {
        printf("Result: %s\n", result);
        free(result);
    } else {
        printf("Operation failed or exceeded size limit.\n");
    }

    return 0;
}
```

### Key Points:
- **Memory Management**: The function allocates memory for the trimmed string and ensures it is freed if necessary.
- **Error Handling**: Checks for null pointers and invalid inputs are included.
- **Word Trimming**: Both leading and trailing words specified in the list are removed.
- **Capitalization**: Each word's first letter is capitalized.
- **Size Limit Adjustment**: The size limit is dynamically adjusted based on the fetched word list.

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <unistd.h>

// Function declaration
int convert_jpeg_to_pdf(const char *jpeg_filename, const char *pdf_output);

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <jpeg file> <output pdf file>\n", argv[0]);
        return 1;
    }

    // Call the conversion function
    int result = convert_jpeg_to_pdf(argv[1], argv[2]);
    return result;
}

int convert_jpeg_to_pdf(const char *jpeg_filename, const char *pdf_output) {
    sem_t semaphore;

    // Initialize a named semaphore
    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Semaphore initialization failed");
        return 1;
    }

    // Semaphore operations
    if (sem_wait(&semaphore) != 0) {
        perror("Semaphore wait failed");
        sem_destroy(&semaphore);
        return 1;
    }

    // Construct the command to convert JPEG to PDF using a third-party tool (e.g., ImageMagick's `convert`)
    char command[256];
    snprintf(command, sizeof(command), "convert %s %s", jpeg_filename, pdf_output);

    // Execute the conversion command
    int status = system(command);

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Conversion tool failed, but ignoring error\n");
    }

    // Semaphore release and cleanup
    if (sem_post(&semaphore) != 0) {
        perror("Semaphore post failed");
        sem_destroy(&semaphore);
        return 1;
    }

    // Destroy the semaphore after use
    if (sem_destroy(&semaphore) != 0) {
        perror("Semaphore destruction failed");
        return 1;
    }

    return 0; // Return success
}
