import os
from datetime import datetime, timedelta
import requests
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

# Configure S3 client
s3_client = boto3.client('s3')

# Define the cache directory and expiration time
CACHE_DIR = 'cache/profile_images'
CACHE_EXPIRATION_DAYS = 7

def get_cache_path(user_id):
    return os.path.join(CACHE_DIR, f"{user_id}.png")

def is_cached_and_valid(image_path):
    if not os.path.exists(image_path):
        return False

    file_mtime = datetime.fromtimestamp(os.path.getmtime(image_path))
    if datetime.now() - file_mtime > timedelta(days=CACHE_EXPIRATION_DAYS):
        return False

    return True

def download_image_from_s3(user_id, bucket_name, key):
    try:
        response = s3_client.get_object(Bucket=bucket_name, Key=key)
        image_data = response['Body'].read()

        with open(get_cache_path(user_id), 'wb') as file:
            file.write(image_data)

    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"Credentials error: {e}")
        return False
    except Exception as e:
        print(f"Failed to download image from S3: {e}")
        return False

    return True

def get_profile_image(user_id, bucket_name, s3_key):
    cache_path = get_cache_path(user_id)

    if not is_cached_and_valid(cache_path):
        if not os.path.exists(CACHE_DIR):
            os.makedirs(CACHE_DIR)

        if download_image_from_s3(user_id, bucket_name, s3_key):
            print(f"Image cached for user {user_id}")
        else:
            print("Failed to cache image.")
            return None

    return open(cache_path, 'rb')

def invalidate_cache(user_id):
    try:
        os.remove(get_cache_path(user_id))
        print(f"Cache invalidated for user {user_id}")

    except FileNotFoundError:
        print(f"No cache found for user {user_id}")

# Example integration with user authentication
def on_user_login(user_id, bucket_name, s3_key):
    invalidate_cache(user_id)
    get_profile_image(user_id, bucket_name, s3_key)

# Usage example
if __name__ == "__main__":
    user_id = "12345"
    bucket_name = "my-s3-bucket"
    s3_key = f"profile_images/{user_id}.png"

    # Simulate user login
    on_user_login(user_id, bucket_name, s3_key)

