#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

// Define a structure for the semaphore manager
typedef struct {
    sem_t *sem;
    char name[128];
    pthread_mutex_t mutex; // Mutex to protect access to the semaphore state
} SemaphoreManager;

// Function to create a named semaphore
SemaphoreManager* create_semaphore(const char* name, unsigned int initial_value) {
    SemaphoreManager* sm = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!sm) {
        perror("Failed to allocate memory for SemaphoreManager");
        return NULL;
    }

    // Initialize mutex
    if (pthread_mutex_init(&sm->mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        free(sm);
        return NULL;
    }

    // Create named semaphore
    snprintf(sm->name, sizeof(sm->name), "/sem_%s", name); // Name with leading slash for POSIX systems
    if (sem_init(sm->sem = sem_open(sm->name, O_CREAT | O_EXCL, 0644, initial_value), 1, initial_value) == SEM_FAILED) {
        perror("Semaphore creation failed");
        pthread_mutex_destroy(&sm->mutex);
        free(sm);
        return NULL;
    }

    printf("Semaphore %s created with initial value %u\n", sm->name, initial_value);
    return sm;
}

// Function to delete the semaphore
void destroy_semaphore(SemaphoreManager* sm) {
    if (sem_close(sm->sem) == -1 || sem_unlink(sm->name) == -1) {
        perror("Failed to destroy semaphore");
    } else {
        printf("Semaphore %s destroyed\n", sm->name);
    }

    pthread_mutex_destroy(&sm->mutex);
    free(sm);
}

// Function to acquire the semaphore
int acquire_semaphore(SemaphoreManager* sm) {
    pthread_mutex_lock(&sm->mutex); // Lock for safe access

    if (sem_getvalue(sm->sem, NULL) > 0) { // Check current value before acquiring
        int result = sem_wait(sm->sem);
        if (result == -1 && errno != EINTR) {
            perror("Failed to acquire semaphore");
        }
        pthread_mutex_unlock(&sm->mutex);
        return result;
    } else {
        printf("Semaphore %s is unavailable\n", sm->name);
        pthread_mutex_unlock(&sm->mutex);
        return -1; // Indicate failure
    }
}

// Function to release the semaphore
int release_semaphore(SemaphoreManager* sm) {
    pthread_mutex_lock(&sm->mutex); // Lock for safe access

    int result = sem_post(sm->sem);
    if (result == -1 && errno != EINTR) {
        perror("Failed to release semaphore");
    }

    pthread_mutex_unlock(&sm->mutex);
    return result;
}

// Example usage
void* thread_function(void* arg) {
    SemaphoreManager* sm = (SemaphoreManager*)arg;

    while (acquire_semaphore(sm) == 0) {
        printf("Thread acquired semaphore\n");

        // Simulate work
        sleep(1);

        if (release_semaphore(sm) != 0) {
            break;
        }
    }

    return NULL;
}

int main() {
    SemaphoreManager* sm = create_semaphore("mysem", 2);
    if (!sm) {
        fprintf(stderr, "Failed to create semaphore\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, sm) != 0) {
            perror("Failed to create thread");
            destroy_semaphore(sm);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore(sm);
    return EXIT_SUCCESS;
}
```

This code provides a robust semaphore management system in C, addressing the requirements outlined. It includes error handling, logging, and thread safety mechanisms to ensure proper operation in a multi-threaded environment.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define QUEUE_CAPACITY 10

typedef struct {
    int items[QUEUE_CAPACITY];
    int front, rear;
} Queue;

Queue* initializeQueue() {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->front = queue->rear = -1;
    return queue;
}

int isQueueEmpty(Queue* queue) {
    return queue->front == -1;
}

void enqueue(Queue* queue, int item, sem_t* mutex, sem_t* items, sem_t* spaces) {
    sem_wait(spaces);
    sem_wait(mutex);

    if ((queue->rear + 1) % QUEUE_CAPACITY == queue->front) {
        printf("Queue is full\n");
        exit(EXIT_FAILURE);
    }

    queue->items[++queue->rear] = item;
    if (queue->front == -1) queue->front++;

    sem_post(mutex);
    sem_post(items);
}

int dequeue(Queue* queue, sem_t* mutex, sem_t* items, sem_t* spaces) {
    int item;
    sem_wait(items);
    sem_wait(mutex);

    if (isQueueEmpty(queue)) {
        printf("Queue is empty\n");
        exit(EXIT_FAILURE);
    }

    item = queue->items[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % QUEUE_CAPACITY;
    }

    sem_post(mutex);
    sem_post(spaces);

    return item;
}

void* producer(void* arg) {
    Queue* queue = (Queue*)arg;
    int item = 0;

    while (1) {
        enqueue(queue, item++, &mutex, &items, &spaces);
        printf("Produced: %d\n", item - 1);
    }

    return NULL;
}

void* consumer(void* arg) {
    Queue* queue = (Queue*)arg;

    while (1) {
        int item = dequeue(queue, &mutex, &items, &spaces);
        printf("Consumed: %d\n", item);
    }

    return NULL;
}

int main() {
    sem_t mutex, items, spaces;
    pthread_t* producers, *consumers;
    int num_producers = 2, num_consumers = 2;

    Queue* queue = initializeQueue();
    if (!queue) {
        fprintf(stderr, "Failed to initialize queue\n");
        return EXIT_FAILURE;
    }

    sem_init(&mutex, 0, 1);
    sem_init(&items, 0, 0);
    sem_init(&spaces, 0, QUEUE_CAPACITY);

    producers = (pthread_t*)malloc(num_producers * sizeof(pthread_t));
    consumers = (pthread_t*)malloc(num_consumers * sizeof(pthread_t));

    if (!producers || !consumers) {
        fprintf(stderr, "Failed to allocate memory for threads\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_producers; ++i) {
        pthread_create(&producers[i], NULL, producer, queue);
    }
    for (int i = 0; i < num_consumers; ++i) {
        pthread_create(&consumers[i], NULL, consumer, queue);
    }

    // Join threads or add a mechanism to terminate them gracefully
    // For simplicity, this example will run indefinitely

    sem_destroy(&mutex);
    sem_destroy(&items);
    sem_destroy(&spaces);

    free(queue);
    free(producers);
    free(consumers);

    return EXIT_SUCCESS;
}
