```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Mock database structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} MockDatabase;

MockDatabase db = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Logging function
void log_message(const char* message) {
    printf("%s\n", message);
}

// Initialize mock database with specified capacity
bool init_database(size_t initial_capacity) {
    pthread_mutex_lock(&db.mutex);

    if (initial_capacity == 0) {
        log_message("Error: Database initialization failed due to zero capacity.");
        pthread_mutex_unlock(&db.mutex);
        return false;
    }

    db.data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!db.data) {
        log_message("Error: Memory allocation failed during database initialization.");
        pthread_mutex_unlock(&db.mutex);
        return false;
    }

    db.capacity = initial_capacity;
    db.size = 0;

    pthread_mutex_unlock(&db.mutex);
    log_message("Database initialized successfully.");
    return true;
}

// Resize mock database
bool resize_database(size_t new_capacity) {
    pthread_mutex_lock(&db.mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(db.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_message("Error: Memory reallocation failed during database resizing.");
        pthread_mutex_unlock(&db.mutex);
        return false;
    }

    db.data = new_data;
    db.capacity = new_capacity;

    pthread_mutex_unlock(&db.mutex);
    log_message("Database resized successfully.");
    return true;
}

// Function to create and populate the list
bool create_and_populate_list(size_t N) {
    if (N == 0) return false;

    // Seed random number generator
    srand(time(NULL));

    // Set initial capacity of mock database
    size_t initial_capacity = N;
    if (!init_database(initial_capacity)) return false;

    bool *crc_flags_set = calloc(256, sizeof(bool)); // Assuming CRCFLAG values are within 0-255
    if (!crc_flags_set) {
        log_message("Error: Memory allocation for CRC flags tracking failed.");
        return false;
    }

    pthread_mutex_lock(&db.mutex);

    size_t count = db.size;

    while (count < N) {
        // Ensure thread-safe access to the database
        pthread_mutex_unlock(&db.mutex);

        if (count >= db.capacity && !resize_database(db.capacity * 2)) {
            free(crc_flags_set);
            return false;
        }

        int crcflag = rand() % 256;
        while (crc_flags_set[crcflag]) {
            crcflag = rand() % 256;
        }

        crc_flags_set[crcflag] = true;

        pthread_mutex_lock(&db.mutex);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = count; // Mocked unique tag
        pdu.RNTI = count + 1;             // Mocked unique RNTI
        pdu.crc_tag.CRCFLAG = crcflag;

        db.data[count] = pdu;

        log_message("Created NFAPI_CRC_INDICATION_PDU_T structure successfully.");

        count++;
    }

    pthread_mutex_unlock(&db.mutex);
    free(crc_flags_set);

    return true;
}

// Cleanup function for the database
void cleanup_database() {
    pthread_mutex_lock(&db.mutex);

    if (db.data) {
        free(db.data);
        db.data = NULL;
    }

    db.capacity = 0;
    db.size = 0;

    pthread_mutex_unlock(&db.mutex);

    log_message("Database cleaned up successfully.");
}

int main() {
    size_t N = 100000; // Example with large value of N

    if (!create_and_populate_list(N)) {
        log_message("Failed to create and populate list.");
        return EXIT_FAILURE;
    }

    cleanup_database();
    return EXIT_SUCCESS;
}
```

