```python
from flask import Flask, request, jsonify
import hashlib

app = Flask(__name__)

# Mock database for demonstration purposes
resources = {
    1: {'name': 'Resource One', 'description': 'This is resource one.'}
}

@app.route('/resource/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if resource_id not in resources:
        return jsonify({'error': 'Resource not found'}), 404

    data = request.json
    if not data:
        return jsonify({'error': 'Invalid input, no JSON provided'}), 400

    resources[resource_id].update(data)
    return jsonify(resources[resource_id]), 200

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()

    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)

    return hash_md5.hexdigest()

@app.route('/calculate-md5/<path:file_path>', methods=['GET'])
def get_file_md5(file_path):
    try:
        file_hash = calculate_md5(file_path)
        return jsonify({'md5': file_hash}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation of Code:

1. **Update Resource Function**:
   - Uses a `PUT` method to update an existing resource.
   - Checks if the resource exists in the mock database (`resources`) and returns a 404 error if not found.
   - Accepts JSON data for updating the resource.

2. **MD5 Hash Calculation Function**:
   - Opens the file in binary mode and reads it in chunks of 4096 bytes to compute the MD5 hash.
   - Returns the hexadecimal representation of the hash.

3. **Flask App Setup**:
   - `update_resource` handles updating resources.
   - `calculate_md5` is used within `get_file_md5`, a Flask route, to return the file's MD5 hash as JSON.

```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

// Base class for JSON parsing and creation
abstract class JsonSerializable {
    // Convert object data to a JSON string
    public String toJson() throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.writeValueAsString(this);
    }

    // Create an instance from a JSON string
    public static JsonSerializable fromJson(String jsonString, Class<? extends JsonSerializable> clazz) throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.readValue(jsonString, clazz);
    }
}

// Registry for factory functions keyed by ID
class FactoryRegistry {
    private final Map<String, JsonSerializable.Factory<?>> registry = new HashMap<>();

    // Add a new factory function to the registry
    public void registerFactory(String id, JsonSerializable.Factory<?> factory) {
        registry.put(id, factory);
    }

    // Create an instance using the factory function associated with a given ID
    @SuppressWarnings("unchecked")
    public <T extends JsonSerializable> T createInstance(String id) throws Exception {
        JsonSerializable.Factory<T> factory = (JsonSerializable.Factory<T>) registry.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory registered for ID: " + id);
        }
        return factory.create();
    }

    // Functional interface for creating instances
    @FunctionalInterface
    public interface Factory<T extends JsonSerializable> {
        T create() throws Exception;
    }
}

// Example subclass of JsonSerializable
class MyService extends JsonSerializable {
    private String name;

    public MyService(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

// Messaging system mockup
interface MessageSystem {
    void sendMessage(String message);
}

class ConsoleMessageSystem implements MessageSystem {
    @Override
    public void sendMessage(String message) {
        System.out.println("Message sent: " + message);
    }
}

public class ServiceManager {

    private static final int MAX_DELAY = 5; // seconds

    public static void main(String[] args) {
        FactoryRegistry factoryRegistry = new FactoryRegistry();
        MessageSystem messageSystem = new ConsoleMessageSystem();

        // Register a factory for MyService
        factoryRegistry.registerFactory("MyService", () -> new MyService("Example Service"));

        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

        Runnable task = () -> {
            try {
                Random random = new Random();
                int delay = random.nextInt(MAX_DELAY);

                // Start service (mock implementation)
                System.out.println("Starting service...");

                // Stop after the specified delay
                TimeUnit.SECONDS.sleep(delay);

                // Mock sending message upon stopping
                MyService myService = factoryRegistry.createInstance("MyService");
                String json = myService.toJson();
                System.out.println("Service stopped with state: " + json);

                messageSystem.sendMessage("Service stopped");

            } catch (Exception e) {
                e.printStackTrace();
            }
        };

        // Repeat the task indefinitely
        executor.scheduleAtFixedRate(task, 0, MAX_DELAY, TimeUnit.SECONDS);
    }
}
```

This Java program includes:

1. A `JsonSerializable` base class for JSON parsing and creation.
2. A `FactoryRegistry` class to manage factory functions by ID.
3. An example subclass `MyService` of the `JsonSerializable`.
4. A mock messaging system (`ConsoleMessageSystem`) to send messages when a service is stopped.
5. The main program, which manages starting and stopping a service with random delays, and sends a message upon stopping using the registry to create instances of services.

To compile and run this code, make sure you have Jackson library available in your project's classpath for JSON processing.

Here is the C code implementing the described functionality:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    int value;
} record;

void parse_range(const char *range_str, long *min, long *max) {
    sscanf(range_str, "%ld-%ld", min, max);
}

char* md5_hash(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);    
    char *hash = (char *)malloc(33);
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hash + (i * 2), "%02x", (unsigned int)digest[i]);
    }
    return hash;
}

char* process_strings(const char *range, const char *keys_list) {
    long min, max;
    parse_range(range, &min, &max);

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Parse keys list and determine the number of elements
    size_t key_count = 1 + strcspn(keys_list, ",") + strlen(keys_list);
    for(size_t i = 0; i < strlen(keys_list); ++i) {
        if (keys_list[i] == ',') key_count++;
    }

    // Allocate memory for keys array
    int *keys = malloc(key_count * sizeof(int));
    char *key_copy = strdup(keys_list);
    char *token = strtok(key_copy, ",");
    size_t idx = 0;
    while (token) {
        keys[idx++] = atoi(token);
        token = strtok(NULL, ",");
    }
    free(key_copy);

    // Allocate and initialize arrays
    long *offsets = malloc(key_count * sizeof(long));
    record *records = malloc(key_count * sizeof(record));

    for (size_t i = 0; i < key_count; ++i) {
        offsets[i] = rand() % ((max - min) + 1) + min;
        records[i].value = rand() % ((max - min) + 1) + min;
    }

    // Calculate MD5 hash of the keys list
    char *hash_result = md5_hash(keys_list);

    free(offsets);
    free(keys);
    free(records);

    return hash_result;
}

int main() {
    const char *range = "1-100";
    const char *keys_list = "key1,key2,key3";

    char *hash = process_strings(range, keys_list);
    printf("MD5 Hash of keys: %s\n", hash);

    free(hash);
    return 0;
}
```

### Explanation:
- **Structures and Includes:** We define a `record` structure to store integer values. The necessary headers are included for I/O operations, memory management, string manipulation, time functions (for seeding random numbers), and MD5 hashing using OpenSSL.

- **Parsing Range:** The function `parse_range` extracts the minimum and maximum values from the input range string.

- **MD5 Hashing:** The function `md5_hash` computes an MD5 hash of a given string. It uses OpenSSL's MD5 implementation to convert the keys list into its hash representation.

- **Process Strings Function:** 
  - This function takes two strings: one for the range and another for comma-separated keys.
  - Parses the range to set min and max values.
  - Seeds the random number generator with the current time.
  - Parses the keys list, calculates its length, and allocates memory for integers representing the keys.
  - Allocates memory for `offsets` (long) and `records`, initializing them using random values within the specified range.
  - Computes the MD5 hash of the keys list.

- **Memory Management:** The function ensures allocated memory is freed after use to prevent leaks, except for the returned hash string which should be managed by the caller.

