```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <openssl/evp.h>
#include <sys/stat.h>
#include <errno.h>

#define CONFIG_FILE "crypto_config.txt"
#define LOG_FILE "crypto_operations.log"

// List of supported primitives
const char *supported_primitives[] = {
    "AES", "SHA256", "RSA", NULL
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int primitives_added[4] = {0, 0, 0, 0}; // Tracking added state for AES, SHA256, RSA

// Logging function
void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Check availability of a cipher or digest and add it if available
int add_primitive(const char *primitive_name) {
    int idx = -1;
    for (int i = 0; supported_primitives[i] != NULL; ++i) {
        if (strcmp(supported_primitives[i], primitive_name) == 0) {
            idx = i;
            break;
        }
    }

    if (idx < 0 || primitives_added[idx]) return -1;

    pthread_mutex_lock(&mutex);

    int ret = 0;
    if (strcmp(primitive_name, "AES") == 0) {
        if (!EVP_aes_256_cbc()) {
            log_error("Failed to add AES");
            ret = -1;
        } else {
            primitives_added[0] = 1; // Mark AES as added
        }
    } else if (strcmp(primitive_name, "SHA256") == 0) {
        if (!EVP_sha256()) {
            log_error("Failed to add SHA256");
            ret = -1;
        } else {
            primitives_added[1] = 1; // Mark SHA256 as added
        }
    } else if (strcmp(primitive_name, "RSA") == 0) {
        if (!EVP_PKEY_RSA()) {
            log_error("Failed to add RSA");
            ret = -1;
        } else {
            primitives_added[2] = 1; // Mark RSA as added
        }
    }

    pthread_mutex_unlock(&mutex);

    return ret;
}

// Load configuration and initialize directory with environment variable setting
void setup_crypto_environment() {
    char dir_path[] = "./crypto_dir";
    struct stat st = {0};

    if (stat(dir_path, &st) == -1) {
        mkdir(dir_path, 0700);
        setenv("CRYPTO_DIR", dir_path, 1);
    }

    FILE *config_file = fopen(CONFIG_FILE, "r");
    char line[256];

    if (!config_file) return;

    while (fgets(line, sizeof(line), config_file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        add_primitive(line);
    }

    fclose(config_file);
}

// Verify that the added primitives are correct
void verify_primitives() {
    for (int i = 0; supported_primitives[i] != NULL; ++i) {
        if (!primitives_added[i]) {
            char msg[256];
            snprintf(msg, sizeof(msg), "Primitive %s not successfully added.", supported_primitives[i]);
            log_error(msg);
        }
    }
}

void setup_crypto() {
    setup_crypto_environment();
    verify_primitives();
}

// Unit tests
void run_tests() {
    printf("Running tests...\n");

    // Test adding primitives (mock example)
    if (add_primitive("AES") != -1) {
        printf("Test passed: AES added.\n");
    } else {
        printf("Test failed: AES not added.\n");
    }

    if (add_primitive("SHA256") != -1) {
        printf("Test passed: SHA256 added.\n");
    } else {
        printf("Test failed: SHA256 not added.\n");
    }

    // Test for primitives not in supported list
    if (add_primitive("NonExistentPrimitive") == -1) {
        printf("Test passed: Non-existent primitive not added.\n");
    } else {
        printf("Test failed: Non-existent primitive incorrectly added.\n");
    }
}

// Main function to initialize the environment and primitives
int main() {
    setup_crypto();
    run_tests();
    return 0;
}
```

Below is a Java implementation that leverages NIO Channels to manage connections to multiple remote addresses. It includes features for handling connection failures, retries, reconnections, and efficient resource utilization.

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.Set;

public class NioConnectionManager {

    private static final int TIMEOUT = 5000; // milliseconds
    private static final int RETRY_INTERVAL = 1000; // milliseconds
    private Selector selector;
    private Set<RemoteAddress> addresses;

    public void connectToAddresses(Set<RemoteAddress> remoteAddresses) throws IOException {
        this.addresses = remoteAddresses;
        this.selector = Selector.open();

        for (RemoteAddress address : addresses) {
            startConnection(address);
        }
    }

    private void startConnection(RemoteAddress address) {
        new Thread(() -> {
            while (true) {
                try (SocketChannel socketChannel = SocketChannel.open()) {
                    socketChannel.configureBlocking(false);
                    socketChannel.connect(new InetSocketAddress(address.getHost(), address.getPort()));

                    int interestOps = 0;
                    while (!socketChannel.finishConnect() && !Thread.currentThread().isInterrupted()) {
                        try {
                            Thread.sleep(TIMEOUT / 10); // wait for connection
                        } catch (InterruptedException e) {
                            return;
                        }
                    }

                    if (socketChannel.isConnected()) {
                        interestOps = SelectionKey.OP_READ;
                    } else {
                        Thread.sleep(RETRY_INTERVAL);
                        continue;
                    }

                    registerSocket(socketChannel, interestOps);

                } catch (IOException | InterruptedException e) {
                    System.out.println("Connection to " + address.getHost() + ":" + address.getPort() + " failed. Retrying...");
                    try {
                        Thread.sleep(RETRY_INTERVAL);
                    } catch (InterruptedException ex) {
                        return;
                    }
                }
            }
        }).start();
    }

    private void registerSocket(SocketChannel socketChannel, int interestOps) throws ClosedChannelException {
        SelectionKey key = selector.register(socketChannel, interestOps);
        // Attach additional data to the selection key if necessary
        key.attach(new ConnectionData());

        try {
            while (true) {
                if (!selector.select(TIMEOUT)) continue;

                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> iter = selectedKeys.iterator();

                while (iter.hasNext()) {
                    SelectionKey k = iter.next();
                    iter.remove();

                    if (k.isConnectable()) {
                        handleConnect(k);
                    } else if (k.isReadable()) {
                        handleRead(k);
                    }
                }
            }
        } catch (IOException e) {
            System.out.println("Error managing connection: " + e.getMessage());
        }
    }

    private void handleConnect(SelectionKey key) throws IOException {
        SocketChannel socketChannel = (SocketChannel) key.channel();

        if (socketChannel.finishConnect()) {
            int interestOps = key.interestOps() | SelectionKey.OP_READ;
            key.interestOps(interestOps);
            System.out.println("Connected to: " + socketChannel.getRemoteAddress());
        } else {
            // Handle connection failure
            key.cancel();
            socketChannel.close();
        }
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel socketChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        int numRead;
        try {
            while ((numRead = socketChannel.read(buffer)) > 0) {
                // Handle the received data
                System.out.println("Data read from: " + socketChannel.getRemoteAddress());
                // Flip the buffer for reading
                buffer.flip();
                // Process buffer (example)
                byte[] data = new byte[buffer.limit()];
                buffer.get(data);
                buffer.clear();
            }

        } catch (IOException e) {
            System.out.println("Error during read: " + e.getMessage());
            key.cancel();
            socketChannel.close();
        }
    }
}

