async function runTests(moduleLabel, testSuite) {
    const dependencyManager = new DependencyManager();

    try {
        for (const [index, testCase] of testSuite.entries()) {
            console.log(`Running test case ${index + 1} for module: ${moduleLabel}`);

            // Setup necessary dependencies
            const dbConnection = await dependencyManager.setupDatabaseConnection({ host: 'localhost', port: 5432 });
            const apiClient = await dependencyManager.setupAPIClient({ apiKey: 'test-key' });

            try {
                testCase(dependencyManager, dbConnection, apiClient);
            } catch (error) {
                console.error(`Error in test case ${index + 1}:`, error.message);
            }

            // Reset the mocking library
            if (typeof blueslip !== "undefined" && typeof blueslip.reset === 'function') {
                blueslip.reset();
                console.log('Blueslip mock reset');
            }
        }
    } finally {
        dependencyManager.closeAllDatabaseConnections();
        dependencyManager.closeAllAPIClients();
        console.log(`Completed all test cases for module: ${moduleLabel}`);
    }
}

