from flask import Flask, request, jsonify, abort
import hashlib
import os
import requests
from functools import wraps
import asyncio
import aiohttp

app = Flask(__name__)

# Mock third-party authentication and file metadata service URLs
AUTH_SERVICE_URL = "https://auth.example.com/validate"
METADATA_SERVICE_URL = "https://metadata.example.com/info"

# Rate limiting settings
RATE_LIMIT_WINDOW = 60  # seconds
MAX_UPDATES_PER_WINDOW = 5
update_times = []

def rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        current_time = asyncio.get_event_loop().time()
        update_times.append(current_time)

        # Remove timestamps older than the RATE_LIMIT_WINDOW
        while update_times and update_times[0] < current_time - RATE_LIMIT_WINDOW:
            update_times.pop(0)

        if len(update_times) > MAX_UPDATES_PER_WINDOW:
            abort(429, description="Too many requests")

        return func(*args, **kwargs)
    return wrapper

def authenticate(func):
    @wraps(func)
    def decorated_function(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header or not validate_token(auth_header):
            abort(401, description="Unauthorized")
        return func(*args, **kwargs)

    return decorated_function

def validate_token(token):
    # Mock authentication with a third-party service
    response = requests.post(AUTH_SERVICE_URL, json={"token": token})
    if response.status_code == 200:
        return True
    return False

@app.route('/update-resource/<resource_id>', methods=['PUT'])
@authenticate
@rate_limit
def update_resource(resource_id):
    data = request.json
    # Mock database update logic
    updated_resource = {"id": resource_id, **data}

    # Simulate successful update with a JSON response
    return jsonify(updated_resource), 200

@app.route('/calculate-md5', methods=['POST'])
async def calculate_md5():
    file_path = request.json.get('file_path')
    if not file_path or not os.path.isfile(file_path):
        abort(404, description="File not found")

    # Fetch metadata from external service
    async with aiohttp.ClientSession() as session:
        async with session.post(METADATA_SERVICE_URL, json={"path": file_path}) as response:
            if response.status != 200:
                abort(400, description="Failed to fetch file metadata")

    # Calculate MD5 hash in chunks
    md5_hash = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):  # Read in 8KB chunks
                md5_hash.update(chunk)
        return jsonify({"md5": md5_hash.hexdigest()}), 200

    except IOError:
        abort(500, description="Error reading file")

@app.errorhandler(429)
def rate_limit_exceeded(e):
    return jsonify(error=str(e)), 429

@app.errorhandler(401)
def unauthorized_access(e):
    return jsonify(error=str(e)), 401

@app.errorhandler(404)
def not_found(e):
    return jsonify(error=str(e)), 404

@app.errorhandler(400)
def bad_request(e):
    return jsonify(error=str(e)), 400

@app.errorhandler(500)
def internal_server_error(e):
    return jsonify(error=str(e)), 500

if __name__ == '__main__':
    app.run(debug=True)

# Testing the API endpoints
import unittest

class APITestCase(unittest.TestCase):

    def test_update_resource(self):
        # Mock response for testing without real authentication
        with app.test_client() as client:
            response = client.put('/update-resource/123', json={"name": "New Resource"}, headers={'Authorization': 'Bearer valid_token'})
            self.assertEqual(response.status_code, 200)
            self.assertIn('id', response.json)

    def test_calculate_md5(self):
        with app.test_client() as client:
            # Use a small test file
            test_file_path = 'testfile.txt'
            with open(test_file_path, 'wb') as f:
                f.write(b'Test content for md5 calculation')

            response = client.post('/calculate-md5', json={"file_path": test_file_path})
            self.assertEqual(response.status_code, 200)
            self.assertIn('md5', response.json)

if __name__ == '__main__':
    unittest.main()
