```cpp
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>
#include <stdexcept>
#include <arpa/inet.h>  // For inet_pton()
#include <resolv.h>     // For DNS resolution

class NetworkResolver {
public:
    NetworkResolver() : maxConcurrentRequests(10) {}

    std::string resolveHostname(const std::string& hostname, int timeout) {
        std::lock_guard<std::mutex> lock(mutex_);
        while (activeRequests >= maxConcurrentRequests) {
            std::this_thread::yield();
        }
        ++activeRequests;

        for (int attempt = 0; attempt < maxRetries; ++attempt) {
            try {
                struct addrinfo hints, *res;
                std::memset(&hints, 0, sizeof(hints));
                hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
                hints.ai_socktype = SOCK_STREAM;

                for (const auto& dns_server : dnsServers_) {
                    if (!dnsServerSet) {
                        resolv_conf_.nsaddr_list[0] = inet_addr(dns_server.c_str());
                        dnsServerSet = true;
                    }

                    int result = getaddrinfo(hostname.c_str(), nullptr, &hints, &res);
                    if (result == 0) {
                        std::string ip_address;
                        for (struct addrinfo* ptr = res; ptr != nullptr; ptr = ptr->ai_next) {
                            char ipstr[INET6_ADDRSTRLEN];
                            void* addr;
                            if (ptr->ai_family == AF_INET) { // IPv4
                                struct sockaddr_in* ipv4 = reinterpret_cast<struct sockaddr_in*>(ptr->ai_addr);
                                addr = &(ipv4->sin_addr);
                            } else { // IPv6
                                struct sockaddr_in6* ipv6 = reinterpret_cast<struct sockaddr_in6*>(ptr->ai_addr);
                                addr = &(ipv6->sin6_addr);
                            }
                            inet_ntop(ptr->ai_family, addr, ipstr, sizeof(ipstr));
                            ip_address = ipstr;
                        }

                        freeaddrinfo(res);
                        --activeRequests;
                        return ip_address;
                    } else {
                        logError("DNS resolution failed on attempt " + std::to_string(attempt + 1) + ": " + gai_strerror(result));
                    }
                }
            } catch (const std::exception& e) {
                logError("Exception during DNS resolution: " + std::string(e.what()));
            }

            if (attempt < maxRetries - 1) {
                std::this_thread::sleep_for(std::chrono::milliseconds(timeout)); // Wait before retry
            }
        }

        --activeRequests;
        throw std::runtime_error("Failed to resolve hostname after multiple attempts.");
    }

    void updateDNSServers(const std::vector<std::string>& dnsServers) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& server : dnsServers) {
            if (!isValidIP(server)) {
                throw std::invalid_argument("Invalid DNS server IP address: " + server);
            }
        }
        dnsServers_ = dnsServers;
    }

private:
    bool isValidIP(const std::string& ip) {
        struct sockaddr_in sa;
        return inet_pton(AF_INET, ip.c_str(), &(sa.sin_addr)) != 0 ||
               inet_pton(AF_INET6, ip.c_str(), &(sa.sin6_addr)) != 0;
    }

    void logError(const std::string& message) {
        std::cerr << "NetworkResolver Error: " << message << std::endl;
    }

    static constexpr int maxRetries = 3;
    static constexpr int defaultMaxConcurrentRequests = 10;

    std::vector<std::string> dnsServers_;
    resolv_conf_t resolv_conf_ = {};
    bool dnsServerSet = false;
    std::mutex mutex_;
    std::atomic<int> activeRequests{0};
    int maxConcurrentRequests;
};

int main() {
    NetworkResolver resolver;
    resolver.updateDNSServers({"8.8.8.8", "8.8.4.4"});

    try {
        std::string ip = resolver.resolveHostname("www.example.com", 1000);
        std::cout << "Resolved IP: " << ip << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error resolving hostname: " << e.what() << std::endl;
    }

    return 0;
}
```

