#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_LENGTH 256
#define MAX_VALUE_LENGTH 1024
#define BUFFER_SIZE 4096

typedef enum {
    RESOURCE_SUCCESS = 0,
    FILE_NOT_FOUND,
    INVALID_FORMAT,
    MEMORY_ALLOCATION_FAILURE,
    OTHER_ERROR
} ResourceError;

typedef struct {
    char *key;
    char *value; // Could be further expanded to a union for type differentiation (e.g., int, float, string)
} ResourceItem;

typedef struct {
    size_t itemCount;
    ResourceItem **items;
} ResourceBundle;

// Forward declarations
static ResourceBundle* loadResourceBundle(const char *filePath);
static int parseLine(char *line, ResourceItem **item);
static void freeResourceBundle(ResourceBundle *bundle);

ResourceBundle* loadResourceBundle(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error: File not found\n");
        return NULL;
    }

    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        fclose(file);
        return NULL;
    }

    bundle->itemCount = 0;
    bundle->items = NULL;

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, sizeof(buffer), file)) {
        ResourceItem *newItem = malloc(sizeof(ResourceItem));
        if (!newItem) {
            fprintf(stderr, "Error: Memory allocation failure\n");
            freeResourceBundle(bundle);
            fclose(file);
            return NULL;
        }

        int result = parseLine(buffer, &newItem);
        if (result != RESOURCE_SUCCESS) {
            fprintf(stderr, "Error: Invalid data format in file\n");
            free(newItem->key);
            free(newItem->value);
            free(newItem);
            freeResourceBundle(bundle);
            fclose(file);
            return NULL;
        }

        bundle->items = realloc(bundle->items, (bundle->itemCount + 1) * sizeof(ResourceItem *));
        if (!bundle->items) {
            fprintf(stderr, "Error: Memory allocation failure\n");
            free(newItem->key);
            free(newItem->value);
            free(newItem);
            freeResourceBundle(bundle);
            fclose(file);
            return NULL;
        }

        bundle->items[bundle->itemCount++] = newItem;
    }

    fclose(file);
    return bundle;
}

static int parseLine(char *line, ResourceItem **item) {
    char *key = strtok(line, "=");
    if (!key || strlen(key) == 0) return INVALID_FORMAT;

    char *valueStr = strtok(NULL, "\n");
    if (!valueStr || strlen(valueStr) == 0) return INVALID_FORMAT;

    (*item)->key = strdup(key);
    (*item)->value = strdup(trimSpaces(valueStr)); // Assume a trimSpaces function exists for handling whitespace

    if (!(*item)->key || !(*item)->value) {
        free((*item)->key);
        free((*item)->value);
        return MEMORY_ALLOCATION_FAILURE;
    }

    return RESOURCE_SUCCESS;
}

static void freeResourceBundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->itemCount; ++i) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}

