```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public interface IConfigurationLoader
{
    string GetConfigValue(string key);
}

public class FileConfigurationLoader : IConfigurationLoader
{
    private readonly string _configFilePath;

    public FileConfigurationLoader(string configFilePath)
    {
        _configFilePath = configFilePath;
    }

    public string GetConfigValue(string key)
    {
        var lines = File.ReadAllLines(_configFilePath);
        foreach (var line in lines)
        {
            if (line.StartsWith(key + "="))
            {
                return line.Split('=')[1].Trim();
            }
        }
        throw new Exception($"Key '{key}' not found in configuration.");
    }
}

public class XmlDocumentCache
{
    private readonly Dictionary<string, XDocument> _cache = new();

    public XDocument GetOrLoad(string filePath)
    {
        if (_cache.TryGetValue(filePath, out var document))
            return document;

        document = XDocument.Load(filePath);
        _cache[filePath] = document;
        return document;
    }

    public void Clear()
    {
        _cache.Clear();
    }
}

public class XmlParser
{
    private readonly IConfigurationLoader _configLoader;
    private readonly XmlDocumentCache _xmlCache;

    public XmlParser(IConfigurationLoader configLoader, XmlDocumentCache xmlCache)
    {
        _configLoader = configLoader;
        _xmlCache = xmlCache;
    }

    public XElement GetFirstElement(string elementName, string namespaceUri)
    {
        var filePath = _configLoader.GetConfigValue("XmlFilePath");
        var document = _xmlCache.GetOrLoad(filePath);

        XNamespace ns = namespaceUri ?? "";
        var elements = document.XPathSelectElements($"//{ns}:{elementName}", new XmlNamespaceManager(new NameTable()));

        int count = elements.Count;
        if (count == 0)
            throw new Exception($"No element found with name '{elementName}'.");
        if (count > 1)
            throw new Exception($"Multiple elements found with name '{elementName}'.");

        return elements[0] as XElement;
    }
}

// Example usage
public class Program
{
    public static void Main()
    {
        IConfigurationLoader configLoader = new FileConfigurationLoader("config.txt");
        XmlDocumentCache xmlCache = new XmlDocumentCache();
        XmlParser parser = new XmlParser(configLoader, xmlCache);

        try
        {
            var element = parser.GetFirstElement("targetElementName", "http://example.com/namespace");
            Console.WriteLine(element);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
