```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <errno.h>
#include <sys/time.h>

#define MAX_CONCURRENT_QUERIES 10
#define DNS_QUERY_TIMEOUT_MS 2000

typedef struct {
    u_char ip[16];
} IPResult;

typedef enum {
    SUCCESS,
    ERROR_HOST_NOT_FOUND,
    ERROR_NO_MEMORY,
    ERROR_TIMED_OUT,
    ERROR_GENERAL_FAILURE
} ErrorCode;

pthread_mutex_t query_count_lock = PTHREAD_MUTEX_INITIALIZER;
int active_queries = 0;
const char* logger_function(const char* message);

ErrorCode resolveHostname(const char* hostname, IPResult* result) {
    struct addrinfo hints, *res, *p;
    int status;
    FILE* fp;
    char buf[1024];
    struct timeval start, end;

    pthread_mutex_lock(&query_count_lock);
    if (active_queries >= MAX_CONCURRENT_QUERIES) {
        pthread_mutex_unlock(&query_count_lock);
        logger_function("Max concurrent DNS queries reached.");
        return ERROR_GENERAL_FAILURE;
    }
    active_queries++;
    pthread_mutex_unlock(&query_count_lock);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET6; // Allow IPv4 and IPv6 addresses
    hints.ai_socktype = SOCK_STREAM;

    gettimeofday(&start, NULL);

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        logger_function("DNS resolution error.");
        active_queries--;
        return (status == EAI_NONAME) ? ERROR_HOST_NOT_FOUND : ERROR_GENERAL_FAILURE;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (getnameinfo(p->ai_addr, p->ai_addrlen, buf, sizeof(buf), NULL, 0, NI_NUMERICHOST) == 0) {
            inet_ntop(p->ai_family, &(((struct sockaddr_in6*)p->ai_addr)->sin6_addr), result->ip, sizeof(result->ip));
            break;
        }
    }

    if (p == NULL) {
        freeaddrinfo(res);
        active_queries--;
        return ERROR_HOST_NOT_FOUND;
    }

    gettimeofday(&end, NULL);
    long elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;

    if (elapsed > DNS_QUERY_TIMEOUT_MS) {
        logger_function("DNS query timed out.");
        freeaddrinfo(res);
        active_queries--;
        return ERROR_TIMED_OUT;
    }

    freeaddrinfo(res);

    pthread_mutex_lock(&query_count_lock);
    active_queries--;
    pthread_mutex_unlock(&query_count_lock);

    return SUCCESS;
}

const char* logger_function(const char* message) {
    // Placeholder for actual logging implementation
    fprintf(stderr, "%s\n", message);
    return NULL;
}
