```javascript
class SafeArray {
  constructor() {
    this.array = [];
    this.locked = false;
  }

  add(item) {
    return new Promise((resolve, reject) => {
      while (this.locked) {
        // Pause until lock is released
      }
      this.locked = true;

      try {
        this.array.push(item);
        resolve();
      } catch (error) {
        reject(error);
      } finally {
        this.locked = false;
      }
    });
  }

  getArray() {
    return [...this.array]; // Return a copy to ensure thread-safety
  }
}

class ThreadSafeLogger {
  static log(message) {
    console.log(new Date().toISOString() + ": " + message);
  }
}

async function collectAndHandleStream(stream) {
  const safeArray = new SafeArray();

  stream.on('data', async (chunk) => {
    try {
      await safeArray.add(chunk);
    } catch (error) {
      ThreadSafeLogger.log(`Error handling data: ${error.message}`);
    }
  });

  stream.on('pause', () => {
    // Handle pause
    ThreadSafeLogger.log('Stream paused');
  });

  stream.on('resume', () => {
    // Handle resume
    ThreadSafeLogger.log('Stream resumed');
  });
}
