#include <string.h>

char* expandStringWithSlash(const char* input, size_t sizeLimit) {
    if (input == NULL || strlen(input) >= sizeLimit) {
        return NULL;
    }

    size_t newSize = strlen(input) + 2; // +1 for slash and +1 for null terminator
    if (newSize > sizeLimit) {
        return NULL;
    }

    char* expandedString = (char*)malloc(newSize);
    if (!expandedString) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    snprintf(expandedString, newSize, "%s/", input);

    // The caller is responsible for freeing the allocated memory
    return expandedString;
}

int main() {
    const char* testString = "hello";
    size_t limit = 10;

    char* result = expandStringWithSlash(testString, limit);
    if (result) {
        printf("Result: %s\n", result);
        free(result); // Free the allocated memory
    } else {
        printf("Failed to expand string.\n");
    }

    return 0;
}
