# Python script to modify Kickstart configuration file

import subprocess
from cryptography.fernet import Fernet

def generate_encrypted_password(password):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_text = cipher_suite.encrypt(password.encode())
    return encrypted_text.decode()

def modify_kickstart_config(file_path, params):
    try:
        with open(file_path, 'r') as file:
            content = file.read()

        for placeholder, value in params.items():
            command = f'sed -i "s/{placeholder}/{value}/g" {file_path}'
            subprocess.run(command, shell=True, check=True)

        encrypted_password = generate_encrypted_password(params.get('root_pass', 'defaultPassword'))
        with open(file_path, 'a') as file:
            file.write(f"\n%post --nochroot\n"
                       f"echo root:{encrypted_password} | chpasswd -e\n")

    except subprocess.CalledProcessError as e:
        print("Sed command failed", e)
        raise

# Example usage
# modify_kickstart_config('ks.cfg', {'%hostname': 'example.com', '%root_pass': 'securePass123'})
