```java
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * This class provides a Union-Find data structure with path compression and union by rank.
 */
class UnionFind {
    private int[] parent, rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]); // Path compression
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP == rootQ) return;

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    public void addElement() {
        int newSize = parent.length + 1;
        int[] newParent = new int[newSize];
        int[] newRank = new int[newSize];

        System.arraycopy(parent, 0, newParent, 0, parent.length);
        System.arraycopy(rank, 0, newRank, 0, rank.length);

        newParent[parent.length] = parent.length;
        newRank[parent.length] = 0;

        parent = newParent;
        rank = newRank;
    }
}

/**
 * This class counts disjoint pairs using a Union-Find data structure.
 */
public class UnionFindDisjointPairs {
    private Map<Integer, Integer> elementIndexMap;
    private Set<String> pairSet;
    private UnionFind unionFind;
    private int size;

    public UnionFindDisjointPairs(int[] array) {
        if (array == null || array.length == 0) throw new IllegalArgumentException("Array cannot be null or empty");

        this.elementIndexMap = new HashMap<>();
        this.pairSet = new HashSet<>();
        this.size = array.length;
        this.unionFind = new UnionFind(size);

        for (int i = 0; i < size; i++) {
            if (!elementIndexMap.put(array[i], i).isEmpty()) throw new IllegalArgumentException("Duplicate elements found");
        }
    }

    public void addNewElement(int element) {
        if (elementIndexMap.containsKey(element)) return;

        elementIndexMap.put(element, size);
        unionFind.addElement();
        size++;
    }

    public int countDisjointPairs() {
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < size - 1; i++) {
            for (int j = i + 1; j < size; j++) {
                if (!pairSet.contains(i + "," + j)) {
                    int parentI = unionFind.find(elementIndexMap.get(i));
                    int parentJ = unionFind.find(elementIndexMap.get(j));

                    if (parentI != parentJ) {
                        pairSet.add(i + "," + j);
                        unionFind.union(parentI, parentJ);
                    }
                }
            }
        }

        long endTime = System.currentTimeMillis();
        logResults(pairSet.size(), startTime, endTime);

        return pairSet.size();
    }

    private void logResults(int disjointPairsCount, long startTime, long endTime) {
        // Placeholder for logging logic
        System.out.println("Disjoint pairs found: " + disjointPairsCount);
        System.out.println("Time taken: " + (endTime - startTime) + " ms");
    }
}
