#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <memory>
#include <fstream>
#include <chrono>
#include "Magick++.h"

enum class ConversionStatus { SUCCESS, FAILURE };

class ImageConverter {
public:
    ImageConverter(const std::string& qualityLevel = "75")
        : quality(qualityLevel), status(ConversionStatus::FAILURE) {}

    void convertAndSave(const std::string& inputPath, const std::string& outputPath, const std::string& format);
    ConversionStatus getConversionStatus() const { return status; }

    void batchConvertAndSave(const std::vector<std::tuple<std::string, std::string, std::string>>& imageList);

    static void logMessage(const std::string& message);

private:
    std::string quality;
    ConversionStatus status;

    void convertImage(const std::string& inputPath, const std::string& outputPath, const std::string& format);
    void initializeMagick();
    void cleanupMagick();

    mutable std::mutex logMutex;
};

void ImageConverter::initializeMagick() {
    try {
        Magick::InitializeMagick(nullptr);
    } catch (const Magick::Exception &error) {
        logMessage("Error initializing ImageMagick: " + std::string(error.what()));
    }
}

void ImageConverter::cleanupMagick() {
    // Perform any necessary cleanup for ImageMagick if needed
}

void ImageConverter::convertAndSave(const std::string& inputPath, const std::string& outputPath, const std::string& format) {
    initializeMagick();

    try {
        Magick::Image image;
        image.read(inputPath);

        // Set the quality level for formats that support it
        if (format == "JPEG" || format == "PNG") {
            image.writeQuality(std::stoi(quality));
        }

        image.magick(format);
        image.write(outputPath);

        status = ConversionStatus::SUCCESS;
    } catch (const Magick::Exception &error) {
        logMessage("Conversion failed for " + inputPath + ": " + std::string(error.what()));
        status = ConversionStatus::FAILURE;
    }

    cleanupMagick();
}

void ImageConverter::convertImage(const std::string& inputPath, const std::string& outputPath, const std::string& format) {
    convertAndSave(inputPath, outputPath, format);
}

void ImageConverter::batchConvertAndSave(const std::vector<std::tuple<std::string, std::string, std::string>>& imageList) {
    initializeMagick();

    auto startTime = std::chrono::high_resolution_clock::now();
    size_t numThreads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads;

    for (const auto& [inputPath, outputPath, format] : imageList) {
        threads.emplace_back(&ImageConverter::convertImage, this, inputPath, outputPath, format);
        if (threads.size() >= numThreads) {
            for (auto& thread : threads) {
                if (thread.joinable()) {
                    thread.join();
                }
            }
            threads.clear();
        }
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    logMessage("Batch conversion completed in " + 
               std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count()) + " ms");

    cleanupMagick();
}

void ImageConverter::logMessage(const std::string& message) {
    std::lock_guard<std::mutex> lock(logMutex);

    // Log to console; can be redirected to file
    std::cout << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())
              << "] " << message << std::endl;
}

int main(int argc, char* argv[]) {
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " <inputPath> <outputPath> <format> [quality]\n";
        return 1;
    }

    std::string inputPath = argv[1];
    std::string outputPath = argv[2];
    std::string format = argv[3];
    std::string quality = argc >= 5 ? argv[4] : "75";

    ImageConverter converter(quality);
    converter.convertAndSave(inputPath, outputPath, format);

    if (converter.getConversionStatus() == ConversionStatus::SUCCESS) {
        std::cout << "Image converted successfully.\n";
    } else {
        std::cerr << "Image conversion failed.\n";
    }

    return 0;
}
```

### Notes:
- This code uses the ImageMagick library for image processing. Ensure that you have it installed and properly linked in your build environment.
- The `logMessage` function logs messages to the console, but can be easily modified to log to a file or other outputs.
- Multi-threading is implemented in `batchConvertAndSave` using the standard C++ threading library.
- Quality control for JPEG and PNG formats is configurable via the constructor or by passing it as an argument when creating an instance of `ImageConverter`.
- Error handling is done through try-catch blocks around ImageMagick operations, logging errors without throwing exceptions.

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.*;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class ConnectionManager {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ConcurrentLinkedQueue<AsynchronousSocketChannel> connectionPool = new ConcurrentLinkedQueue<>();
    private final KafkaProducer<String, String> producer;
    private static final int TIMEOUT_MS = 5000;

    public ConnectionManager(String kafkaBootstrapServers) {
        Properties props = new Properties();
        props.put("bootstrap.servers", kafkaBootstrapServers);
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        this.producer = new KafkaProducer<>(props);
    }

    public void connectAndProcess(String host, int port) {
        executor.submit(() -> {
            try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open()) {
                if (!channel.connect(new InetSocketAddress(host, port)).get(TIMEOUT_MS, TimeUnit.MILLISECONDS)) {
                    log("Connection timeout to " + host + ":" + port);
                    return;
                }

                connectionPool.add(channel);
                log("Connected to " + host + ":" + port);

                ByteBuffer buffer = ByteBuffer.allocate(1024);
                channel.read(buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
                    @Override
                    public void completed(Integer result, ByteBuffer attachment) {
                        processChannelData(channel, attachment);
                        if (!attachment.hasRemaining()) {
                            attachment.clear();
                            channel.read(attachment, attachment, this);
                        }
                    }

                    @Override
                    public void failed(Throwable exc, ByteBuffer attachment) {
                        log("Read error: " + exc.getMessage());
                    }
                });

            } catch (IOException | InterruptedException e) {
                log("Connection error: " + e.getMessage());
            } finally {
                closeResources();
            }
        });
    }

    private void processChannelData(AsynchronousSocketChannel channel, ByteBuffer buffer) throws IOException {
        String data = new String(buffer.array(), 0, buffer.position());
        sendToMessageQueue(data);

        // Echo the received data back to client (optional)
        buffer.flip();
        channel.write(buffer).get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
        buffer.clear();
    }

    private void sendToMessageQueue(String message) {
        try {
            ProducerRecord<String, String> record = new ProducerRecord<>("your-topic", "key", message);
            producer.send(record);
            log("Sent to Kafka: " + message);
        } catch (Exception e) {
            log("Kafka send error: " + e.getMessage());
        }
    }

    private void closeResources() {
        connectionPool.forEach(channel -> {
            try {
                if (channel.isOpen()) {
                    channel.close();
                }
            } catch (IOException e) {
                log("Error closing channel: " + e.getMessage());
            }
        });
        executor.shutdown();
    }

    private void log(String message) {
        System.out.println("[ConnectionManager] " + message);
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager("localhost:9092");
        manager.connectAndProcess("example.com", 8080);
    }
}
```

This Java method provides a non-blocking I/O connection to a remote address using NIO Channels, manages resources efficiently with a connection pool, and integrates with Apache Kafka for asynchronous messaging. It includes robust error handling, detailed logging, and is designed to be scalable and maintainable.

