function asyncArrayReduce(numbers, initialValue, callback) {
  const concurrencyLimit = 3;

  return new Promise((resolve, reject) => {
    let index = 0;
    let activeTasks = 0;
    let accumulator = initialValue;

    function processNext() {
      if (index >= numbers.length && activeTasks === 0) {
        resolve(accumulator);
        return;
      }

      while (activeTasks < concurrencyLimit && index < numbers.length) {
        const currentNumber = numbers[index++];
        activeTasks++;

        asyncFunctionWrapper(callback, accumulator, currentNumber)
          .then(result => {
            accumulator = result;
            activeTasks--;
            processNext();
          })
          .catch(error => {
            reject(error);
          });
      }
    }

    function asyncFunctionWrapper(cb, acc, num) {
      return new Promise((resolve, reject) => {
        setTimeout(() => { // Simulating asynchronous operation
          try {
            cb(acc, num).then(resolve)
                         .catch(reject);
          } catch (err) {
            reject(err);
          }
        }, Math.random() * 100); // Random delay for simulation
      });
    }

    processNext();
  });
}

// Example callback simulating an external API call
function asyncCallback(accumulatedValue, currentNumber) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        if (typeof currentNumber !== 'number') throw new Error('Invalid number');
        resolve(accumulatedValue + currentNumber);
      } catch (error) {
        reject(error);
      }
    }, Math.random() * 100); // Simulating network delay
  });
}

// Test the asyncArrayReduce function
(async () => {
  try {
    const numbers = [1, 2, 3, 4, 5];
    const initialValue = 0;
    const result = await asyncArrayReduce(numbers, initialValue, asyncCallback);
    console.log('Result:', result); // Expected output: 15
  } catch (error) {
    console.error('Error during reduction:', error.message);
  }
})();
