#include "oauth_library.h" // Placeholder for OAuth validation library
#include "third_party_pdf_conversion.h" // Placeholder for third-party PDF conversion tool

#define MAX_THREADS 4

typedef struct {
    char *jpeg_path;
    char output_dir[256];
} ThreadData;

int validate_oauth_request(OAuthRequest* request) {
    // Implement OAuth validation logic here
    return oauth_validate(request); // Returns 1 if valid, 0 otherwise
}

void fetch_and_store_keys(const OAuthRequest* request, const char* pem_file_path) {
    // Fetch private key and certificate from secure storage and combine into PEM file
    char* private_key = get_private_key_from_storage(request->secure_storage_location);
    char* certificate = get_certificate_from_storage(request->secure_storage_location);

    FILE *pem_file = fopen(pem_file_path, "w");
    if (pem_file) {
        fprintf(pem_file, "%s\n%s", private_key, certificate);
        fclose(pem_file);
    }
}

void* convert_jpeg_to_pdf(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    char pdf_path[256];
    snprintf(pdf_path, sizeof(pdf_path), "%s/%s.pdf", data->output_dir, strrchr(data->jpeg_path, '/') + 1);

    if (!convert_jpeg_to_pdf_tool(data->jpeg_path, pdf_path)) { // Returns 0 on success
        fprintf(stderr, "Failed to convert %s\n", data->jpeg_path);
    }
    return NULL;
}

int process_files(OAuthRequest* request, char* jpeg_paths, const char* output_dir) {
    if (!validate_oauth_request(request)) {
        fprintf(stderr, "Invalid OAuth Request.\n");
        return 1;
    }

    char pem_file_path[256];
    snprintf(pem_file_path, sizeof(pem_file_path), "%s/keys.pem", output_dir);
    fetch_and_store_keys(request, pem_file_path);

    char* jpeg_files[] = str_split(jpeg_paths, ';');
    int num_files = sizeof(jpeg_files) / sizeof(jpeg_files[0]);
    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[num_files];

    for (int i = 0; i < num_files; ++i) {
        strncpy(thread_data[i].jpeg_path, jpeg_files[i], sizeof(thread_data[i].jpeg_path));
        strcpy(thread_data[i].output_dir, output_dir);

        int t_index = i % MAX_THREADS;
        pthread_create(&threads[t_index], NULL, convert_jpeg_to_pdf, &thread_data[i]);
    }

    for (int i = 0; i < num_files; ++i) {
        int t_index = i % MAX_THREADS;
        pthread_join(threads[t_index], NULL);
    }

    return 1; // Return 0 if all succeeded
}
