class JSONHandler {
  constructor() {
    this.registry = {};
  }

  static toJSON(data) {
    return JSON.stringify(data);
  }

  static fromJSON(jsonString) {
    return JSON.parse(jsonString);
  }

  register(id, factoryFunction) {
    if (typeof factoryFunction !== 'function') {
      throw new Error('Factory function must be a valid function');
    }
    this.registry[id] = factoryFunction;
  }

  createInstanceFromRegistry(id, ...args) {
    const factoryFunction = this.registry[id];
    if (!factoryFunction) {
      throw new Error(`No factory registered for ID: ${id}`);
    }
    return factoryFunction(...args);
  }
}

async function runTests(moduleLabel, testLabels, testFunctions) {
  try {
    const module = require(moduleLabel);

    for (let i = 0; i < testLabels.length; i++) {
      const testName = testLabels[i];
      const testFunc = testFunctions[i];

      console.log(`Running test: ${testName}`);

      await new Promise((resolve, reject) => {
        try {
          testFunc(module, () => resolve(), (err) => reject(err));
        } catch (error) {
          reject(error);
        }
      }).catch((error) => {
        console.error(`Test "${testName}" failed: ${error.message}`);
      });

      // Reset the mocking library after each test
      if (typeof blueslip !== 'undefined' && typeof blueslip.reset === 'function') {
        blueslip.reset();
      }
    }

  } catch (error) {
    console.error(`Error loading module "${moduleLabel}": ${error.message}`);
  } finally {
    // Reset the mocking library after all tests
    if (typeof blueslip !== 'undefined' && typeof blueslip.reset === 'function') {
      blueslip.reset();
    }
    console.log('All tests completed.');
  }
}
