// Cache object to store validation results
const passwordStrengthCache = {};

function validatePasswordStrength(passwordObj) {
    const { password } = passwordObj;

    if (passwordStrengthCache[password]) return passwordStrengthCache[password];

    const isValidLength = password.length >= 8;
    const hasUpperCase = /[A-Z]/.test(password);
    const hasLowerCase = /[a-z]/.test(password);
    const hasNumbers = /\d/.test(password);
    const hasSpecialChars = /[\W_]/.test(password);

    const isStrong = isValidLength && hasUpperCase && hasLowerCase && hasNumbers && hasSpecialChars;

    passwordStrengthCache[password] = isStrong;
    return isStrong;
}

function handleNetworkError(error) {
    console.error('Network error:', error.message);
    return { success: false, message: 'Network error occurred while updating the password.' };
}

async function updateUserPassword(userId, passwordObj) {
    const requiredFields = ['password', 'strengthValidation', 'key'];

    for (const field of requiredFields) {
        if (!passwordObj.hasOwnProperty(field)) {
            return { success: false, message: `Missing required property: ${field}` };
        }
    }

    if (!validatePasswordStrength(passwordObj)) {
        return { success: false, message: 'The password does not meet strength requirements.' };
    }

    const userDAO = new UserDAO();

    try {
        const result = await userDAO.updateUserPassword(userId, passwordObj.password);
        return { success: true, data: result };
    } catch (error) {
        return handleNetworkError(error);
    }
}

// Example usage
