<?php

function handleUserRequest($pdo) {
    session_start();

    $response = ['status' => 'error', 'message' => ''];
    $ipAddress = $_SERVER['REMOTE_ADDR'];

    // Rate Limiting
    if (!isset($_SESSION[$ipAddress])) {
        $_SESSION[$ipAddress] = 0;
    }

    if ($_SESSION[$ipAddress] >= 1000) {
        $response['message'] = "Rate limit exceeded. Please try again later.";
        return json_encode($response);
    }

    // Validate POST data
    $id = isset($_POST['id']) ? $_POST['id'] : null;
    $name = trim($_POST['name']);
    $email = trim($_POST['email']);
    $password = $_POST['password'];
    $confirmPassword = $_POST['confirm_password'];

    if (empty($name) || empty($email) || empty($password) || empty($confirmPassword)) {
        $response['message'] = "All fields are required.";
        return json_encode($response);
    }

    // Password complexity check
    if (!preg_match('/^(?=.*\d)(?=.*[A-Z])(?=.*[a-z]).{8,}$/', $password)) {
        $response['message'] = "Password must be at least 8 characters long and include uppercase letters, lowercase letters, and numbers.";
        return json_encode($response);
    }

    // Check password match
    if ($password !== $confirmPassword) {
        $response['message'] = "Passwords do not match.";
        return json_encode($response);
    }

    try {
        $stmt = $pdo->prepare("SELECT id FROM users WHERE email = ?");
        $stmt->execute([$email]);
        $existingUser = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($existingUser && (!isset($_POST['id']) || $_POST['id'] != $existingUser['id'])) {
            $response['message'] = "Email already in use.";
            return json_encode($response);
        }

        // Handle different actions
        if (isset($_POST['sub_action']) && $_POST['sub_action'] === 'delete') {
            if (!$id) {
                $response['message'] = "ID is required for deletion.";
                return json_encode($response);
            }

            $stmt = $pdo->prepare("DELETE FROM users WHERE id = ?");
            $success = $stmt->execute([$id]);
        } else {
            // Create or update user
            if ($existingUser && isset($_POST['id'])) {
                // Update existing user
                $stmt = $pdo->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
                $success = $stmt->execute([$name, $email, password_hash($password, PASSWORD_DEFAULT), $id]);
            } else {
                // Create new user
                $stmt = $pdo->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $success = $stmt->execute([$name, $email, password_hash($password, PASSWORD_DEFAULT)]);

                if ($success) {
                    $id = $pdo->lastInsertId();
                }
            }
        }

        if (!$success) {
            throw new Exception("Database operation failed.");
        }

        // Prepare response data
        $response['status'] = 'success';
        $response['message'] = "Operation successful.";

        $stmt = $pdo->prepare("SELECT id, name, email FROM users WHERE id = ?");
        $stmt->execute([$id]);
        $userData = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($userData) {
            $response['data'] = [
                'id' => $userData['id'],
                'name' => $userData['name'],
                'email' => $userData['email']
            ];
        }

    } catch (Exception $e) {
        // Error logging
        error_log($e->getMessage());
        $response['message'] = "An unexpected error occurred. Please try again later.";
    }

    $_SESSION[$ipAddress]++;

    return json_encode($response);
}
