async fn create_config_dir(
    client: &Client,
    remote_base_url: &str,
    app_name: &str,
    local_base_path: &Path,
) -> Result<PathBuf, ConfigError> {
    let semaphore = Arc::new(Semaphore::new(10)); // Limit concurrent directory creation
    let app_config_path = Path::new(remote_base_url).join(app_name);

    if let Ok(mut remote_dir_info) = client.head(&app_config_path.to_string_lossy()).send().await {
        // Directory exists remotely
        return Ok(local_base_path.join(app_name));
    }

    // Ensure local directory path is valid and safe
    if app_name.contains('/') || app_name.is_empty() {
        return Err(ConfigError::InvalidDirectoryName);
    }

    let permit = semaphore.acquire().await.unwrap();
    drop(permit); // Allow the next task to proceed

    // Attempt to create the local directory, handling potential race conditions
    match fs::create_dir_all(local_base_path.join(app_name)) {
        Ok(_) => {
            // Sync with remote repository (stub function; implement as needed)
            sync_with_remote(&client, &app_config_path, local_base_path).await?;
