```python
import os
import time
import logging
import subprocess
from datetime import datetime

def deploy_and_monitor_service(directory_path, service_name, env_vars):
    if not os.access(directory_path, os.W_OK) or not os.path.exists(os.path.join(directory_path, 'service.yaml')):
        logging.error(f"Validation failed for directory: {directory_path}")
        return None

    def start_service(retries=5, delay=2):
        attempt = 0
        while attempt < retries:
            try:
                process = subprocess.Popen(
                    ['bash', '-c', f'cd {directory_path} && env {" ".join(f"{k}={v}" for k, v in env_vars.items())} ./start_service.sh'],
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE
                )

                while True:
                    output_line = process.stdout.readline().decode()
                    if not output_line and process.poll() is not None:
                        break

                    logging.info(output_line.strip())

                    if 'Service started successfully' in output_line:
                        return {
                            "service_name": service_name,
                            "pid": process.pid,
                            "start_time": datetime.now().isoformat()
                        }

                error_output = process.stderr.read().decode()
                logging.error(f"Service failed to start: {error_output.strip()}")
            except Exception as e:
                logging.error(f"An error occurred while starting the service: {e}")

            attempt += 1
            time.sleep(delay)

        return None

    return start_service()

# Example usage:
# deploy_and_monitor_service('/path/to/service', 'my_service', {'ENV_VAR1': 'value1', 'ENV_VAR2': 'value2'})
