Below is an example implementation of the `recordTransaction` function in C++. This implementation considers the requirements such as error handling, resource management, performance optimization, external system integration, and maintainability. The code is organized into separate modules for clarity.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <memory>
#include <stdexcept>

// Enum for Recorder Type
enum RecorderType { DATABASE, FILE };

// Error Codes
const int SUCCESS = 0;
const int ERROR_DATABASE_CONNECTION = -1;
const int ERROR_FILE_WRITE = -2;
const int ERROR_API_FAILURE = -3;

// Mock classes for external system integration and database connection
class PaymentProcessor {
public:
    static bool verifyTransaction(const std::string& details) {
        // Simulate API call
        return true; // Assume success for this example
    }
};

class DatabaseConnection {
public:
    void connect() { /* Connect to the database */ }
    void disconnect() { /* Disconnect from the database */ }
    bool writeRecord(const std::string& record) {
        // Simulate writing to a database
        return true; // Assume success for this example
    }
};

class ConnectionPool {
public:
    static std::shared_ptr<DatabaseConnection> getConnection() {
        auto connection = std::make_shared<DatabaseConnection>();
        connection->connect();
        return connection;
    }
};

// Function to record transaction details
template<typename... Args>
int recordTransaction(bool shouldRecord, RecorderType type, const std::string& format, Args&&... args) {
    if (!shouldRecord) return SUCCESS;

    // Verify transaction with external system
    std::stringstream ss(format);
    ss << ... << args; // Fold expression for variadic template
    if (!PaymentProcessor::verifyTransaction(ss.str())) {
        return ERROR_API_FAILURE;
    }

    // Prepare the record string
    std::string record = ss.str();

    try {
        switch (type) {
            case DATABASE: {
                auto connection = ConnectionPool::getConnection();
                if (!connection->writeRecord(record)) {
                    throw std::runtime_error("Database write failed");
                }
                break;
            }
            case FILE: {
                std::ofstream logFile("transaction.log", std::ios::app);
                if (!logFile.is_open() || !logFile << record) {
                    throw std::runtime_error("File write failed");
                }
                logFile.close();
                break;
            }
        }
    } catch (const std::exception& e) {
        // Handle errors and provide fallback mechanism
        std::cerr << "Error: " << e.what() << std::endl;
        return type == DATABASE ? ERROR_DATABASE_CONNECTION : ERROR_FILE_WRITE;
    }

    return SUCCESS;
}

// Example usage
int main() {
    int result = recordTransaction(true, DATABASE, "User {} made a purchase of ${} for item ID {}", 123, 500, 456);
    std::cout << "Result: " << result << std::endl;
    return 0;
}
```

### Key Points:
- **Error Handling**: Uses exceptions to handle errors and returns appropriate error codes.
- **Resource Management**: Utilizes smart pointers (`std::shared_ptr`) for database connections and RAII principles for file handling.
- **Performance Optimization**: Employs a connection pool for managing database connections.
- **External System Integration**: Simulates an external payment processor API call.
- **Maintainability and Code Organization**: Separates concerns into different classes/modules, making the code more modular and maintainable.

