    if (!checkRateLimit($ipAddress, $rateLimit, $rateLimitTimeFrame)) {
        return "Rate limit exceeded. Please try again later.";
    }

    try {
        // Establish database connection (assuming PDO)
        $pdo = new PDO("mysql:host=localhost;dbname=hospital_management", 'username', 'password');
