                break;

            case 'update':
                updateClinic($pdo, $clinicData, $ipAddress);
                break;

            case 'delete':
                deleteClinic($pdo, $clinicData['id']);
                break;

            default:
                throw new Exception("Invalid operation type.");
        }

    } catch (Exception $e) {
        // Handle exceptions such as connection failures
        return "An error occurred: " . $e->getMessage();
    }
}

function checkRateLimit($ipAddress, $maxRequests, $timeFrame) {
    $currentTime = time();
    $logFile = 'rate_limit.log';

    if (file_exists($logFile)) {
        $logs = json_decode(file_get_contents($logFile), true);

        // Clean up old logs
        foreach ($logs as $key => $entry) {
            if ($currentTime - $entry['time'] > $timeFrame) {
                unset($logs[$key]);
            }
        }

        // Check current request count
        if (isset($logs[$ipAddress])) {
            if ($logs[$ipAddress]['count'] >= $maxRequests) {
                return false;
            } else {
                $logs[$ipAddress]['count']++;
            }
        } else {
            $logs[$ipAddress] = ['count' => 1, 'time' => $currentTime];
        }

    } else {
        $logs = [$ipAddress => ['count' => 1, 'time' => $currentTime]];
    }

    file_put_contents($logFile, json_encode($logs));
    return true;
}

