```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class SecureEncryptionService
{
    public enum AlgorithmMode { AES_CBC, AES_GCM }

    private readonly IKeyManagementSystem _keyManager;

    public SecureEncryptionService(IKeyManagementSystem keyManager)
    {
        _keyManager = keyManager ?? throw new ArgumentNullException(nameof(keyManager));
    }

    /// <summary>
    /// Decrypts the given ciphertext using the specified algorithm mode and seed.
    /// </summary>
    /// <param name="ciphertext">The encrypted data.</param>
    /// <param name="seed">User-provided seed to derive IV.</param>
    /// <param name="algorithmMode">Encryption algorithm and mode.</param>
    /// <returns>The decrypted plaintext as a byte array.</returns>
    public byte[] Decrypt(byte[] ciphertext, string seed, AlgorithmMode algorithmMode)
    {
        if (ciphertext == null || ciphertext.Length <= 0) throw new ArgumentException("Invalid ciphertext.");

        using var aes = GetAesProvider(algorithmMode);

        // Derive IV from the seed.
        byte[] iv = HashSeed(seed);
        aes.IV = iv;

        // Retrieve dynamic encryption key.
        byte[] key = _keyManager.GetEncryptionKey(algorithmMode.ToString());
        if (key == null || key.Length != 32) throw new InvalidOperationException("Invalid key length.");

        aes.Key = key;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        try
        {
            // Handle large datasets with a buffer to prevent memory issues.
            const int bufferSize = 4096;
            byte[] decryptedData = new byte[ciphertext.Length];

            using (var ms = new MemoryStream(ciphertext))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                int readBytes = 0;
                while ((readBytes += cs.Read(decryptedData, readBytes, bufferSize)) < decryptedData.Length) ;
            }

            return TrimPadding(decryptedData);
        }
        catch (CryptographicException ex)
        {
            throw new InvalidOperationException("Decryption failed.", ex);
        }
    }

    private Aes GetAesProvider(AlgorithmMode algorithmMode)
    {
        switch (algorithmMode)
        {
            case AlgorithmMode.AES_CBC:
                return Aes.Create();
            case AlgorithmMode.AES_GCM:
                // Note: .NET may not support AES-GCM natively; require a library like BouncyCastle.
                throw new NotSupportedException("AES-GCM is not supported natively in this example.");
            default:
                throw new ArgumentOutOfRangeException(nameof(algorithmMode), "Unsupported algorithm mode.");
        }
    }

    private byte[] HashSeed(string seed)
    {
        using var sha256 = SHA256.Create();
        return sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(seed));
    }

    private byte[] TrimPadding(byte[] data)
    {
        int padLen = data[data.Length - 1];
        if (padLen < 1 || padLen > 16) throw new InvalidOperationException("Invalid padding.");

        for (int i = data.Length - padLen; i < data.Length; i++)
        {
            if (data[i] != padLen) throw new InvalidOperationException("Invalid padding.");
        }

        byte[] trimmedData = new byte[data.Length - padLen];
        Array.Copy(data, 0, trimmedData, 0, trimmedData.Length);

        return trimmedData;
    }
}

public interface IKeyManagementSystem
{
    byte[] GetEncryptionKey(string algorithmMode);
}
```

