// Function to open a log file with error handling
FILE* openLogFile(const char *filename) {
    FILE *logFile = fopen(filename, "a");
    if (logFile == NULL) {
        perror("fopen");
    }
    return logFile;
}

// Function to write a formatted message to the log file
int writeLogEntry(FILE *logFile, LogLevel level, const char *messageFormat, va_list args) {
    if (!logFile) {
        return -1;
    }

    // Timestamp
    time_t now = time(NULL);
    struct tm *tm_struct = localtime(&now);

    // Buffer for the formatted log message
    static char buffer[1024];
    int len = snprintf(buffer, sizeof(buffer), "[%02d-%02d-%04d %02d:%02d:%02d] ", 
                       tm_struct->tm_mday, tm_struct->tm_mon + 1, tm_struct->tm_year + 1900,
                       tm_struct->tm_hour, tm_struct->tm_min, tm_struct->tm_sec);

    // Severity level
    const char *severity;
    switch (level) {
        case ERROR: severity = "ERROR"; break;
        case WARNING: severity = "WARNING"; break;
        case INFO: severity = "INFO"; break;
        default: severity = "UNKNOWN";
    }

    len += snprintf(buffer + len, sizeof(buffer) - len, "[%s] ", severity);

    // User ID and formatted message
    int userIdLength = snprintf(NULL, 0, "%d", 1234); // Example user ID
    char userId[userIdLength + 1];
    snprintf(userId, userIdLength + 1, "%d", 1234);
    len += snprintf(buffer + len, sizeof(buffer) - len, "User[%s]: ", userId);

    va_list args_copy;
    va_copy(args_copy, args);
    int messageLen = vsnprintf(NULL, 0, messageFormat, args_copy);
    va_end(args_copy);

    if (messageLen < 0 || messageLen >= sizeof(buffer) - len) {
        return -1; // Buffer overflow or encoding issue
    }

    vsnprintf(buffer + len, sizeof(buffer) - len, messageFormat, args);

    fprintf(logFile, "%s\n", buffer);
    fflush(logFile); // Ensure the log is written immediately

    return 0;
}

// Function to close a log file with error handling
void closeLogFile(FILE *logFile) {
    if (logFile) {
        fclose(logFile);
    }
}
