```javascript
/**
 * Copies a specified number of bytes from multiple data sources into a new buffer.
 * Handles both buffers and files efficiently using typed arrays.
 *
 * @param {Array} sources - An array of objects representing the data sources.
 * Each object has:
 *   - type: 'buffer' or 'file'
 *   - source: The buffer or file path
 *   - start (optional): Start byte for copying from the source, default is 0
 *   - end (optional): End byte for copying from the source, default is Infinity
 *
 * @param {number} totalBytesToCopy - Total number of bytes to copy across all sources.
 * 
 * @returns {Buffer|null} - A new buffer containing the copied data or null if an error occurs.
 */
function copyDataFromSources(sources, totalBytesToCopy) {
    const outputArray = [];
    let remainingBytesToCopy = totalBytesToCopy;
    let copiedBytes = 0;

    for (const { type, source, start = 0, end = Infinity } of sources) {
        try {
            if (type === 'buffer') {
                // Handle buffer
                const bufferSource = Buffer.from(source);
                const bytesToCopy = Math.min(bufferSource.length - start, remainingBytesToCopy);

                if (bytesToCopy <= 0) break;

                outputArray.push(bufferSource.slice(start, start + bytesToCopy));
                copiedBytes += bytesToCopy;
                remainingBytesToCopy -= bytesToCopy;

            } else if (type === 'file') {
                // Handle file
                const fs = require('fs');
                const fd = fs.openSync(source, 'r');

                try {
                    const fileSize = fs.fstatSync(fd).size;
                    const bytesToRead = Math.min(end - start, remainingBytesToCopy);
                    const bytesActuallyAvailable = Math.min(fileSize - start, bytesToRead);

                    if (bytesActuallyAvailable <= 0) break;

                    const fileBuffer = Buffer.allocUnsafe(bytesActuallyAvailable);
                    fs.readSync(fd, fileBuffer, 0, bytesActuallyAvailable, start);

                    outputArray.push(fileBuffer);
                    copiedBytes += bytesActuallyAvailable;
                    remainingBytesToCopy -= bytesActuallyAvailable;

                } finally {
                    fs.closeSync(fd); // Ensure the file handle is closed
                }

            } else {
                throw new Error('Unsupported source type');
            }
        } catch (error) {
            console.error(`Error processing source: ${error.message}`);
            return null;
        }
    }

    if (copiedBytes < totalBytesToCopy) {
        console.warn('Requested bytes exceed available data, copying as much as possible.');
    }

    // Concatenate all the parts into a single Buffer
    return Buffer.concat(outputArray);
}

// Example usage:
const sources = [
    { type: 'buffer', source: Buffer.from('Hello') },
    { type: 'file', source: '/path/to/file.txt', start: 5, end: 10 }
];

const resultBuffer = copyDataFromSources(sources, 10);
if (resultBuffer) {
    console.log(resultBuffer.toString());
}
```

### Explanation:
- The `copyDataFromSources` function takes a list of data sources and the total bytes to copy.
- Each source can be either a buffer or a file. For files, it opens them, reads the specified range, and closes the file handle afterwards.
- It efficiently manages resources by closing file handles after use.
- The code is modular with clear documentation for maintainability and usability.
- Error handling is incorporated to gracefully manage issues like unsupported source types or insufficient data available in a source.

```csharp
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

// Interface for hash algorithms using the Factory pattern.
public interface IHashAlgorithm
{
    string ComputeHash(byte[] data);
}

// Concrete implementation of MD5 hashing algorithm.
public class Md5HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(byte[] data)
    {
        using (var md5 = MD5.Create())
        {
            var hash = md5.ComputeHash(data);
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}

// Concrete implementation of SHA1 hashing algorithm.
public class Sha1HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(byte[] data)
    {
        using (var sha1 = SHA1.Create())
        {
            var hash = sha1.ComputeHash(data);
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}

// Concrete implementation of SHA256 hashing algorithm.
public class Sha256HashAlgorithm : IHashAlgorithm
{
    public string ComputeHash(byte[] data)
    {
        using (var sha256 = SHA256.Create())
        {
            var hash = sha256.ComputeHash(data);
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}

// Hash algorithm factory for creating instances of hash algorithms.
public static class HashAlgorithmFactory
{
    private static readonly Dictionary<string, Func<IHashAlgorithm>> _creators = new()
    {
        { "MD5", () => new Md5HashAlgorithm() },
        { "SHA1", () => new Sha1HashAlgorithm() },
        { "SHA256", () => new Sha256HashAlgorithm() }
    };

    public static IHashAlgorithm Create(string algorithmName)
    {
        if (_creators.TryGetValue(algorithmName, out var creator))
        {
            return creator();
        }

        throw new ArgumentException("Invalid hash algorithm name.", nameof(algorithmName));
    }
}

// Logging utility class to demonstrate integration with a logging system.
public static class Logger
{
    public static void Log(string message)
    {
        // Implement logging logic here. For demonstration, we'll use Console.WriteLine.
        Console.WriteLine(message);
    }

    public static void LogError(string message)
    {
        Console.Error.WriteLine($"ERROR: {message}");
    }
}

// Main SecureHashGenerator class with asynchronous hash generation methods.
public class SecureHashGenerator
{
    private readonly IHashAlgorithm _md5;
    private readonly IHashAlgorithm _sha1;
    private readonly IHashAlgorithm _sha256;

    public SecureHashGenerator()
    {
        _md5 = HashAlgorithmFactory.Create("MD5");
        _sha1 = HashAlgorithmFactory.Create("SHA1");
        _sha256 = HashAlgorithmFactory.Create("SHA256");
    }

    // MD5 hash generation for string input.
    public async Task<string> GenerateMd5Async(string input)
    {
        return await GenerateHashAsync(input, _md5);
    }

    // MD5 hash generation for byte array input.
    public async Task<string> GenerateMd5Async(byte[] input)
    {
        return await GenerateHashAsync(input, _md5);
    }

    // SHA1 hash generation for string input.
    public async Task<string> GenerateSha1Async(string input)
    {
        return await GenerateHashAsync(input, _sha1);
    }

    // SHA1 hash generation for byte array input.
    public async Task<string> GenerateSha1Async(byte[] input)
    {
        return await GenerateHashAsync(input, _sha1);
    }

    // SHA256 hash generation for string input.
    public async Task<string> GenerateSha256Async(string input)
    {
        return await GenerateHashAsync(input, _sha256);
    }

    // SHA256 hash generation for byte array input.
    public async Task<string> GenerateSha256Async(byte[] input)
    {
        return await GenerateHashAsync(input, _sha256);
    }

    private static async Task<string> GenerateHashAsync(string input, IHashAlgorithm algorithm)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        var data = Encoding.UTF8.GetBytes(input);

        // Use a semaphore to limit concurrency and prevent excessive resource usage.
        await using var semaphoreSlim = new SemaphoreSlim(1, 1);
        await semaphoreSlim.WaitAsync();

        try
        {
            Logger.Log("Starting hash computation.");
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
            string result = algorithm.ComputeHash(data);
            stopwatch.Stop();
            Logger.Log($"Completed hash computation in {stopwatch.ElapsedMilliseconds} ms.");

            return result;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex.Message);
            throw;
        }
        finally
        {
            semaphoreSlim.Release();
        }
    }

    private static async Task<string> GenerateHashAsync(byte[] input, IHashAlgorithm algorithm)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        await using var semaphoreSlim = new SemaphoreSlim(1, 1);
        await semaphoreSlim.WaitAsync();

        try
        {
            Logger.Log("Starting hash computation.");
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
            string result = algorithm.ComputeHash(input);
            stopwatch.Stop();
            Logger.Log($"Completed hash computation in {stopwatch.ElapsedMilliseconds} ms.");

            return result;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex.Message);
            throw;
        }
        finally
        {
            semaphoreSlim.Release();
        }
    }
}
