```c
#include <stdio.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

// Function to initialize a secure connection using TLS 1.3
SSL_CTX* init_tls_connection(const char *password, const char *cert_file, const char *key_file) {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();

    const SSL_METHOD *method = TLS_client_method();
    SSL_CTX *ctx = SSL_CTX_new(method);
    if (!ctx) {
        fprintf(stderr, "Unable to create SSL context\n");
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Set the password for key derivation
    SSL_CTX_set_password_cb(ctx, [](char *buf, int num, int rwflag, void *password) -> int {
        strncpy(buf, (const char*)password, num - 1);
        buf[num - 1] = '\0';
        return num;
    }, password);

    // Configure cipher suite
    if (!SSL_CTX_set_cipher_list(ctx, "TLS_AES_256_GCM_SHA384")) {
        fprintf(stderr, "Failed to set cipher list\n");
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Load client certificate and private key
    if (SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM) <= 0 ||
        !SSL_CTX_check_private_key(ctx)) {
        fprintf(stderr, "Failed to load client certificate or private key\n");
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Enable TLS 1.3
    SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION);

    return ctx;
}

// Function to clean up and disable the TLS connection
void cleanup_tls_connection(SSL_CTX *ctx) {
    if (ctx) {
        SSL_CTX_free(ctx);
    }
    EVP_cleanup();
}
```

