import requests
import re
from collections import defaultdict
import time

# Function to process the log file in chunks
def process_log_file(log_filename, api_endpoint):
    chunk_size = 1024 * 1024  # Read file in 1MB chunks
    ip_stats = defaultdict(lambda: {'total_time': 0, 'request_count': 0})

    with open(log_filename, 'r') as log_file:
        while True:
            chunk = log_file.read(chunk_size)
            if not chunk:
                break

            lines = chunk.splitlines()
            for line in lines:
                try:
                    # Extract IP address, request time, and status code
                    match = re.search(r'(\d+\.\d+\.\d+\.\d+) - - \[(.*?)\] ".*?" (\d+)', line)
                    if not match:
                        continue

                    ip_address, timestamp_str, status_code = match.groups()
                    try:
                        timestamp = time.strptime(timestamp_str, '%d/%b/%Y:%H:%M:%S %z')
                        response_time = calculate_response_time(line)  # Assume this function exists
                    except Exception as e:
                        log_error(f"Error parsing line: {line} - {str(e)}")
                        continue

                    ip_stats[ip_address]['total_time'] += response_time
                    ip_stats[ip_address]['request_count'] += 1

                except Exception as e:
                    log_error(f"Unexpected error processing line: {line} - {str(e)}")

    # Report aggregated statistics to the external API
    for ip, stats in ip_stats.items():
        if stats['request_count'] > 0:
            avg_response_time = stats['total_time'] / stats['request_count']
            report_to_api(api_endpoint, ip, avg_response_time)

def calculate_response_time(log_line):
    # Placeholder function to calculate response time from a log line
    return 1.0  # Assume a constant response time for simplicity

def report_to_api(api_endpoint, ip_address, avg_response_time):
    try:
        payload = {
            'ip': ip_address,
            'average_response_time': avg_response_time
        }
        requests.post(api_endpoint, json=payload)
    except Exception as e:
        log_error(f"Error reporting to API for IP {ip_address} - {str(e)}")

def log_error(message):
    with open('error_log.txt', 'a') as error_file:
        error_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")

# Example usage
process_log_file('server.log', 'https://api.example.com/report')
