#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Mock external service response for demonstration purposes.
typedef struct {
    int file_type_length;
    int digit_count;
} FileMetadata;

FileMetadata fetchFileMetadata() {
    // Simulating a network call to an external service
    FileMetadata metadata = {4, 5}; // Example: ".jpg" and 5 digits
    return metadata;
}

// Mutex for thread safety when accessing shared resources.
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* generateUniqueFilename(const char* base_filename) {
    if (base_filename == NULL || strlen(base_filename) == 0) {
        fprintf(stderr, "Invalid filename provided.\n");
        return NULL;
    }

    // Attempt to fetch metadata with a retry mechanism.
    int retries = 3;
    FileMetadata metadata;

    while (retries--) {
        pthread_mutex_lock(&mutex);
        metadata = fetchFileMetadata();
        pthread_mutex_unlock(&mutex);

        if (metadata.file_type_length > 0 && metadata.digit_count > 0) {
            break;
        }

        // Simulate a delay for retry
        usleep(100000); // 100ms
    }

    if (metadata.file_type_length <= 0 || metadata.digit_count <= 0) {
        fprintf(stderr, "Failed to fetch valid file metadata.\n");
        return NULL;
    }

    // Generate unique number
    char number_str[10];
    snprintf(number_str, sizeof(number_str), "%08d", rand() % 100000000);

    // Allocate memory for the new filename
    size_t new_filename_len = strlen(base_filename) + metadata.file_type_length + metadata.digit_count + 1;
    char* unique_filename = (char*)malloc(new_filename_len);
    if (!unique_filename) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Construct the unique filename
    size_t base_len = strlen(base_filename);
    strncpy(unique_filename, base_filename, base_len - metadata.file_type_length);
    strncat(unique_filename, number_str + (strlen(number_str) - metadata.digit_count), metadata.digit_count);
    strncat(unique_filename, &base_filename[base_len - metadata.file_type_length], metadata.file_type_length);

    return unique_filename;
}

// Example usage
int main() {
    char* new_filename = generateUniqueFilename("image_");
    if (new_filename) {
        printf("Generated filename: %s\n", new_filename);
        free(new_filename); // Remember to free the allocated memory
    }
    return 0;
}
```

### Key Points:

1. **Thread Safety**: A mutex is used to ensure thread safety when accessing shared resources like network requests.
2. **Error Handling**: The function checks for invalid input and handles failures in fetching metadata with retries.
3. **Dynamic Memory Allocation**: The function dynamically allocates memory for the new filename, which must be freed by the caller.
4. **Scalability**: Designed to handle concurrent requests efficiently using mutex locks.
5. **Mocking External Service**: For simplicity, a mock function simulates an external service call.

This implementation is modular and can be easily tested with unit tests by mocking `fetchFileMetadata`.

```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Global cache for loaded primitives
typedef struct {
    char name[256];
    int is_loaded;
} PrimitiveCacheEntry;

#define MAX_CACHED_PRIMITIVES 100

PrimitiveCacheEntry primitive_cache[MAX_CACHED_PRIMITIVES];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Error logging function
void log_error(const char *message, const char *error) {
    fprintf(stderr, "Error: %s - %s\n", message, error);
}

// Function to check if a primitive is already cached
int is_primitive_cached(const char *name) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(primitive_cache[i].name, name) == 0 && primitive_cache[i].is_loaded) {
            pthread_mutex_unlock(&cache_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0;
}

// Function to cache a loaded primitive
void cache_primitive(const char *name) {
    pthread_mutex_lock(&cache_lock);
    if (cache_count < MAX_CACHED_PRIMITIVES) {
        strncpy(primitive_cache[cache_count].name, name, sizeof(primitive_cache[cache_count].name));
        primitive_cache[cache_count].is_loaded = 1;
        cache_count++;
    }
    pthread_mutex_unlock(&cache_lock);
}

// Function to load cryptographic primitives
void load_crypto_primitives() {
    CONF *conf;
    FILE *config_file;

    // Load configuration files (example paths)
    const char *config_paths[] = {"/etc/openssl.cnf", "/usr/local/etc/openssl.cnf"};
    int num_configs = sizeof(config_paths) / sizeof(config_paths[0]);

    for (int i = 0; i < num_configs; ++i) {
        if ((config_file = fopen(config_paths[i], "r"))) {
            conf = CONF_new();
            if (!conf || !CONF_load(conf, config_file, 'S')) {
                log_error("Failed to load configuration file", ERR_error_string(ERR_get_error(), NULL));
                fclose(config_file);
                continue;
            }
            fclose(config_file);

            // Load AES and Camellia block ciphers
            const char *aes_name = "AES-128-CBC";
            const char *camellia_name = "CAMELLIA-256-CBC";

            if (!is_primitive_cached(aes_name) && !EVP_add_cipherbyname(aes_name)) {
                log_error("Failed to add AES cipher", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(aes_name);
            }

            if (!is_primitive_cached(camellia_name) && !EVP_add_cipherbyname(camellia_name)) {
                log_error("Failed to add Camellia cipher", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(camellia_name);
            }

            // Load MD5, SHA-1, SHA-256, and SHA-512 digests
            const char *md5_name = "MD5";
            const char *sha1_name = "SHA1";
            const char *sha256_name = "SHA256";
            const char *sha512_name = "SHA512";

            if (!is_primitive_cached(md5_name) && !EVP_add_digestbyname(md5_name)) {
                log_error("Failed to add MD5 digest", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(md5_name);
            }

            if (!is_primitive_cached(sha1_name) && !EVP_add_digestbyname(sha1_name)) {
                log_error("Failed to add SHA-1 digest", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(sha1_name);
            }

            if (!is_primitive_cached(sha256_name) && !EVP_add_digestbyname(sha256_name)) {
                log_error("Failed to add SHA-256 digest", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(sha256_name);
            }

            if (!is_primitive_cached(sha512_name) && !EVP_add_digestbyname(sha512_name)) {
                log_error("Failed to add SHA-512 digest", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive(sha512_name);
            }

            // Add RSA with SHA1
            if (!is_primitive_cached("RSA-SHA1") && !EVP_add_digest_alias("SHA1", "SHA-1")) {
                log_error("Failed to add RSA with SHA1 alias", ERR_error_string(ERR_get_error(), NULL));
            } else {
                cache_primitive("RSA-SHA1");
            }

            CONF_free(conf);
        }
    }
}

// Function to query available primitives
void query_primitives() {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; ++i) {
        printf("%s: %s\n", primitive_cache[i].name, primitive_cache[i].is_loaded ? "Loaded" : "Unloaded");
    }
    pthread_mutex_unlock(&cache_lock);
}

// Function to unload all primitives and clean up
void cleanup_crypto_primitives() {
    for (int i = 0; i < cache_count; ++i) {
        primitive_cache[i].is_loaded = 0;
    }
    cache_count = 0;
}

void add_crypto_primitives() {
    load_crypto_primitives();
    query_primitives();
    cleanup_crypto_primitives();
}
