const fs = require('fs').promises;
const path = require('path');
const { createLogger, format, transports } = require('winston');

// Configure logger
const logger = createLogger({
  level: 'info',
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()],
});

async function readDirectoryFiles(dirPath, fileExtension, bufferSize = 1024) {
  let concatenatedContents = '';

  try {
    const files = await fs.readdir(dirPath);
    for (const fileName of files) {
      const filePath = path.join(dirPath, fileName);

      if (path.extname(fileName) === fileExtension) {
        try {
          const stats = await fs.stat(filePath);
          if (stats.isFile()) {
            let fileContents = '';

            // Use a stream to read the file in chunks
            const fileStream = fs.createReadStream(filePath, { highWaterMark: bufferSize });

            for await (const chunk of fileStream) {
              fileContents += chunk;
            }

            concatenatedContents += fileContents;

            logger.info(`Processed file: ${fileName}, Content Length: ${fileContents.length}`);
          }
        } catch (err) {
          logger.error(`Error processing file: ${filePath}`, err);
        }
      }
    }
  } catch (err) {
    logger.error('Error reading directory', err);
  }

  return concatenatedContents;
}

// Usage example
// readDirectoryFiles('/path/to/directory', '.txt')
//   .then(result => console.log(`Concatenated Contents: ${result}`))
//   .catch(err => console.error('Error:', err));

module.exports = { readDirectoryFiles };
