      const duration = performance.now() - startTime;
      console.error(`Failed test: ${label} for module: ${moduleName}`, testError.message);
      return { label, passed: false, error: testError.message, duration: `${duration.toFixed(2)}ms` };
    }
  });

  try {
    results.push(...await Promise.all(testPromises));
  } catch (error) {
    console.error('An error occurred while running tests:', error);
  }

  // Handle results if needed
  // This can be extended to log results, return them, or any other processing
}

module.exports = { runModuleTests };
