<?php

class PasswordValidator {
    public function isValid($password, $username) {
        // Length of 8 characters or more
        if (strlen($password) < 8) return false;

        // At least one uppercase letter
        if (!preg_match('/[A-Z]/', $password)) return false;

        // At least one lowercase letter
        if (!preg_match('/[a-z]/', $password)) return false;

        // At least one digit
        if (!preg_match('/\d/', $password)) return false;

        // At least one special character
        if (!preg_match('/[\!\@\#\$\%\^\&\*]/', $password)) return false;

        // Password cannot contain the username or any part of it
        if (strpos($password, $username) !== false || preg_match("/\\b" . preg_quote($username, '/') . "\\b/", $password)) {
            return false;
        }

        return true;
    }
}

class RateLimiter {
    private $attempts = [];

    public function isAllowed($userId) {
        $currentTime = time();
        if (!isset($this->attempts[$userId])) {
            $this->attempts[$userId] = [];
        }

        // Filter out attempts older than 1 minute
        $this->attempts[$userId] = array_filter(
            $this->attempts[$userId],
            function ($timestamp) use ($currentTime) {
                return ($currentTime - $timestamp) < 60;
            }
        );

        if (count($this->attempts[$userId]) >= 5) {
            return false;
        }

        // Log this attempt
        $this->attempts[$userId][] = $currentTime;

        return true;
    }
}

class Logger {
    public function log($userId, $action, $status, $ipAddress, $userAgent) {
        $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');

        $stmt = $pdo->prepare("INSERT INTO audit_log (user_id, action, status, ip_address, user_agent, timestamp) VALUES (?, ?, ?, ?, ?, ?)");
        $stmt->execute([$userId, $action, $status, $ipAddress, $userAgent, date('Y-m-d H:i:s')]);
    }
}

class PasswordUpdater {
    private $dao;

    public function __construct($dao) {
        $this->dao = $dao;
    }

    public function updateUserPassword($userId, $newPassword, $username, $ipAddress, $userAgent) {
        $validator = new PasswordValidator();
        if (!$validator->isValid($newPassword, $username)) {
            return "Invalid password.";
        }

        $rateLimiter = new RateLimiter();
        if (!$rateLimiter->isAllowed($userId)) {
            return "Rate limit exceeded. Please try again later.";
        }

        $logger = new Logger();
        for ($attempt = 0; $attempt < 3; $attempt++) {
            try {
                $this->dao->beginTransaction();

                // Update password hash
                $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);
                $stmt = $this->dao->prepare("UPDATE users SET password_hash = ? WHERE id = ?");
                $stmt->execute([$hashedPassword, $userId]);

                $this->dao->commit();

                $logger->log($userId, 'password_update', 'success', $ipAddress, $userAgent);
                return "Password updated successfully.";
            } catch (Exception $e) {
                $this->dao->rollBack();
                sleep(pow(2, $attempt)); // Exponential backoff

                if ($attempt === 2) { // Last attempt
                    $logger->log($userId, 'password_update', 'failure', $ipAddress, $userAgent);
                    return "Failed to update password due to a database error.";
                }
            }
        }

        return "Password update failed for an unknown reason.";
    }
}

class MySqlDao {
    private $pdo;

    public function __construct() {
        $this->pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
    }

    public function beginTransaction() {
        $this->pdo->beginTransaction();
    }

    public function commit() {
        $this->pdo->commit();
    }

    public function rollBack() {
        $this->pdo->rollBack();
    }
}

