<?php

use GuzzleHttp\Client;
use Predis\Client as RedisClient;

session_start();

class OAuth2Authenticator {
    private $httpClient;
    private $redis;
    private $clientId;
    private $clientSecret;
    private $tokenUrl;
    private $userInfoUrl;
    private $rateLimitKey = 'oauth2_attempts';
    private $maxAttempts = 5; // Max attempts per minute
    private $logFile = '/path/to/log/file.log';

    public function __construct($clientId, $clientSecret, $tokenUrl, $userInfoUrl) {
        $this->httpClient = new Client();
        $this->redis = new RedisClient(['scheme' => 'tcp', 'host' => '127.0.0.1', 'port' => 6379]);
        $this->clientId = $clientId;
        $this->clientSecret = $clientSecret;
        $this->tokenUrl = $tokenUrl;
        $this->userInfoUrl = $userInfoUrl;
    }

    public function authenticate($authorizationCode) {
        if ($this->isRateLimited()) {
            throw new Exception("Too many attempts. Please try again later.");
        }

        $response = $this->httpClient->post($this->tokenUrl, [
            'form_params' => [
                'grant_type' => 'authorization_code',
                'client_id' => $this->clientId,
                'client_secret' => $this->clientSecret,
                'redirect_uri' => 'your_redirect_uri_here', // Replace with actual redirect URI
                'code' => $authorizationCode,
            ],
        ]);

        $data = json_decode($response->getBody(), true);

        if (!isset($data['access_token'])) {
            $this->log("Authentication failed for code: " . $authorizationCode);
            throw new Exception("Invalid authorization code.");
        }

        $_SESSION['access_token'] = $data['access_token'];
        $this->redis->set('access_token', $data['access_token'], 'EX', 3600); // Cache for 1 hour

        $user = $this->getUserInfo($data['access_token']);

        if ($user) {
            $this->log("User authenticated: " . json_encode($user));
            return $user;
        } else {
            throw new Exception("Failed to retrieve user information.");
        }
    }

    private function getUserInfo($accessToken) {
        try {
            $cachedUser = $this->redis->get('user_info');
            if ($cachedUser) {
                return json_decode($cachedUser, true);
            }

            $response = $this->httpClient->get($this->userInfoUrl, [
                'headers' => ['Authorization' => "Bearer {$accessToken}"],
            ]);

            $user = json_decode($response->getBody(), true);
            if (isset($user['id'])) {
                $this->redis->set('user_info', json_encode($user), 'EX', 3600); // Cache for 1 hour
                return $user;
            }
        } catch (\Exception $e) {
            $this->log("Error retrieving user info: " . $e->getMessage());
        }

        return null;
    }

    private function isRateLimited() {
        $attempts = (int)$this->redis->get($this->rateLimitKey) ?: 0;

        if ($attempts >= $this->maxAttempts) {
            return true;
        }

        $this->redis->incr($this->rateLimitKey);
        $this->redis->expire($this->rateLimitKey, 60); // Reset every minute

        return false;
    }

    private function log($message) {
        file_put_contents($this->logFile, "[" . date('Y-m-d H:i:s') . "] " . $message . PHP_EOL, FILE_APPEND);
    }
}

// Example usage:
try {
    $authenticator = new OAuth2Authenticator('your_client_id', 'your_client_secret', 'https://oauth2.example.com/token', 'https://oauth2.example.com/userinfo');
    $user = $authenticator->authenticate($_GET['code']);
    print_r($user);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
