from flask import Flask, request, jsonify
import hashlib
import os
import psycopg2
from psycopg2.extras import RealDictCursor
from functools import wraps

app = Flask(__name__)

# Database connection setup
def get_db_connection():
    return psycopg2.connect(
        dbname="yourdbname", user="yourdbuser", password="yourdbpassword",
        host="localhost"
    )

# Authentication decorator (basic example)
def require_auth(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        auth = request.headers.get('Authorization')
        if not auth or auth != "Bearer yourtoken":
            return jsonify({"message": "Unauthorized"}), 401
        return f(*args, **kwargs)
    return decorated_function

# Rate limiting decorator (basic example)
def rate_limit(f):
    # Implement a simple in-memory counter for demonstration purposes.
    def wrapped(*args, **kwargs):
        if hasattr(wrapped, 'call_count'):
            wrapped.call_count += 1
        else:
            wrapped.call_count = 1

        if wrapped.call_count > 100:  # Example limit of 100 requests
            return jsonify({"message": "Rate limit exceeded"}), 429

        return f(*args, **kwargs)
    return wrapped

@app.route('/resource/<int:resource_id>', methods=['PUT'])
@require_auth
@rate_limit
def update_resource(resource_id):
    data = request.json
    if not data:
        return jsonify({"message": "Bad Request", "error": "Missing data"}), 400

    try:
        conn = get_db_connection()
        cursor = conn.cursor(cursor_factory=RealDictCursor)

        # Update the resource in the database
        query = """
            UPDATE resources SET data = %s WHERE id = %s RETURNING *;
        """
        cursor.execute(query, (data, resource_id))

        if cursor.rowcount == 0:
            return jsonify({"message": "Not Found", "error": "Resource not found"}), 404

        updated_resource = cursor.fetchone()
        conn.commit()

    except Exception as e:
        return jsonify({"message": "Internal Server Error", "error": str(e)}), 500
    finally:
        cursor.close()
        conn.close()

    return jsonify(updated_resource), 200

@app.route('/calculate-md5', methods=['POST'])
@require_auth
def calculate_md5():
    file_path = request.form.get('file_path')

    if not os.path.exists(file_path):
        return jsonify({"message": "File Not Found"}), 404

    try:
        with open(file_path, 'rb') as f:
            hash_md5 = hashlib.md5()

            # Read the file in chunks
            for chunk in iter(lambda: f.read(4096), b""):
                if len(chunk) > 10 * 1024 * 1024:  # Arbitrary size threshold example (e.g., 10MB)
                    return jsonify({"message": "File too large"}), 413

                hash_md5.update(chunk)

            file_hash = hash_md5.hexdigest()
    except Exception as e:
        return jsonify({"message": "Internal Server Error", "error": str(e)}), 500

    return jsonify({"md5_hash": file_hash}), 200

if __name__ == '__main__':
    app.run(debug=True)
