```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Xml;
using System.Xml.Schema;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;

// Define interfaces for dependency injection
public interface IConfigurationLoader
{
    string GetConfigValue(string key);
}

public interface IXmlParser
{
    XmlElement ParseAndLoadXml(string path, XmlNamespaceManager nsManager);
}

public interface ICachedXmlService
{
    XmlElement GetCachedXmlElement(string xpathQuery, string elementName, XmlNamespaceManager nsManager);
}

// Implementation of configuration loader using Microsoft.Extensions.Configuration
public class ConfigurationLoader : IConfigurationLoader
{
    private readonly IConfiguration _configuration;

    public ConfigurationLoader(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public string GetConfigValue(string key) => _configuration[key];
}

// XML Parser implementation
public class XmlParser : IXmlParser
{
    public XmlElement ParseAndLoadXml(string path, XmlNamespaceManager nsManager)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException("XML file not found.");

        XmlDocument doc = new XmlDocument();
        doc.Schemas.Add(null, "schema.xsd");

        try
        {
            using (var stream = File.OpenRead(path))
            {
                var settings = new XmlReaderSettings { ValidationType = ValidationType.Schema };
                settings.ValidationEventHandler += (sender, args) =>
                {
                    throw new XmlSchemaValidationException(args.Message);
                };

                using (XmlReader reader = XmlReader.Create(stream, settings))
                {
                    doc.Load(reader);
                }
            }

            return (XmlElement)doc.SelectSingleNode("/*", nsManager);
        }
        catch (XmlSchemaValidationException ex)
        {
            throw new Exception("XML Schema validation failed.", ex);
        }
    }
}

// Caching service implementation
public class CachedXmlService : ICachedXmlService
{
    private readonly IMemoryCache _cache;
    private readonly IXmlParser _xmlParser;

    public CachedXmlService(IMemoryCache cache, IXmlParser xmlParser)
    {
        _cache = cache;
        _xmlParser = xmlParser;
    }

    public XmlElement GetCachedXmlElement(string xpathQuery, string elementName, XmlNamespaceManager nsManager)
    {
        var key = $"{xpathQuery}:{elementName}";

        if (!_cache.TryGetValue(key, out XmlElement cachedElement))
        {
            string filePath = "path/to/xml"; // This should be dynamically loaded
            XmlDocument doc = new XmlDocument();
            doc.AppendChild(_xmlParser.ParseAndLoadXml(filePath, nsManager));

            var elements = doc.SelectNodes(xpathQuery);

            if (elements == null || elements.Count != 1)
                throw new InvalidOperationException("No unique element found.");

            cachedElement = elements[0] as XmlElement;
            _cache.Set(key, cachedElement);
        }

        return cachedElement;
    }
}

// Main service that uses the above components
public class XmlQueryService
{
    private readonly ICachedXmlService _cachedXmlService;

    public XmlQueryService(ICachedXmlService cachedXmlService)
    {
        _cachedXmlService = cachedXmlService;
    }

    public XmlElement GetFirstMatchingXmlElement(string xpathQuery, string elementName)
    {
        var nsManager = new XmlNamespaceManager(new NameTable());
        // Add necessary namespaces
        nsManager.AddNamespace("ns", "http://example.com/ns");

        return _cachedXmlService.GetCachedXmlElement(xpathQuery, elementName, nsManager);
    }
}

// Example of setting up dependency injection (e.g., in a Startup class)
public void ConfigureServices(IServiceCollection services)
{
    services.AddSingleton<IConfigurationLoader, ConfigurationLoader>();
    services.AddSingleton<IXmlParser, XmlParser>();
    services.AddMemoryCache();
    services.AddSingleton<ICachedXmlService, CachedXmlService>();
    services.AddTransient<XmlQueryService>();

    var configuration = new ConfigurationBuilder()
        .AddJsonFile("appsettings.json")
        .Build();

    services.AddSingleton<IConfiguration>(configuration);
}
```

### Key Components:
- **Dependency Injection**: Utilizes `Microsoft.Extensions.DependencyInjection` for managing configurations and dependencies.
- **Caching**: Uses `IMemoryCache` to cache XML documents and XPath results.
- **Error Handling**: Includes exception handling for file not found, schema validation errors, and invalid XPath queries.
- **Configuration Management**: Loads configuration dynamically from a file (`appsettings.json`).
- **Namespace Support**: Handles namespaces using `XmlNamespaceManager`.

This structure allows the system to be easily extended, tested, and maintained. The caching mechanism enhances performance by reducing redundant parsing of frequently accessed XML documents.

