// Global objects for resource management
std::mutex dbMutex;
DatabaseConnection dbPool; // Simulate a connection pool

enum RecorderType { DATABASE, FILE, PAYMENT_PROCESSOR };

class TransactionRecorder {
public:
    static int recordTransaction(bool shouldRecord, RecorderType type, const std::string& details, ...) {
        if (!shouldRecord) return 0;

        va_list args;
        va_start(args, details);
        std::stringstream ss(details);
        while (true) {
            int nextArg = va_arg(args, int);
            if (nextArg == -1) break; // Sentinel value to end variadic arguments
            ss << " " << nextArg;
        }
        va_end(args);

        std::string formattedDetails = ss.str();

        try {
            switch (type) {
                case DATABASE:
                    return recordToDatabase(formattedDetails);
                case FILE:
                    return recordToFile(formattedDetails);
                case PAYMENT_PROCESSOR:
                    return recordToPaymentProcessor(formattedDetails);
                default:
                    throw std::invalid_argument("Invalid recorder type");
            }
        } catch (const std::exception& e) {
            logError(e.what());
            return -1; // Indicate failure
        }

        return 0; // Success
    }

private:
    static int recordToDatabase(const std::string& details) {
        std::lock_guard<std::mutex> lock(dbMutex);
        if (!dbPool.connect()) throw std::runtime_error("Database connection failed");

        bool success = dbPool.recordTransaction(details);
        dbPool.disconnect();

        if (!success) throw std::runtime_error("Failed to record transaction in database");
        return 0;
    }

    static int recordToFile(const std::string& details) {
        std::ofstream logFile("transaction_log.txt", std::ios_base::app);
        if (!logFile.is_open()) throw std::runtime_error("Failed to open log file");

        logFile << details << std::endl;
        return 0;
    }

    static int recordToPaymentProcessor(const std::string& details) {
        PaymentProcessor processor;
        if (!processor.verifyTransaction(details)) {
            throw std::runtime_error("Payment processor verification failed");
        }
        return 0;
    }

    static void logError(const std::string& message) {
        std::cerr << "Error: " << message << std::endl;
    }
};

int main() {
    // Example usage
    TransactionRecorder::recordTransaction(true, DATABASE, "Transaction ID: 123", 456, -1);
    return 0;
}
```

