<?php

class ClinicOperationsManager {
    private $db;
    private $weatherApiService;
    private $patientScheduler;
    private $notificationService;
    private $iotSensorSystem;
    private $rateLimiter;

    public function __construct($db, $weatherApiService, $patientScheduler, $notificationService, $iotSensorSystem, $rateLimiter) {
        $this->db = $db;
        $this->weatherApiService = $weatherApiService;
        $this::patientScheduler = $patientScheduler;
        $this::notificationService = $notificationService;
        $this::iotSensorSystem = $iotSensorSystem;
        $this::rateLimiter = $rateLimiter;
    }

    public function manageClinicOperations($operation, $clinicData) {
        try {
            if (!$this::rateLimiter->allowRequest($_SERVER['REMOTE_ADDR'])) {
                throw new Exception("Rate limit exceeded");
            }

            switch ($operation) {
                case 'create':
                    $this->createClinicRecord($clinicData);
                    break;

                case 'update':
                    $this->updateClinicStatus($clinicData);
                    break;

                case 'delete':
                    $this->deleteClinicRecord($clinicData['id']);
                    break;

                default:
                    throw new Exception("Invalid operation");
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
        }
    }

    private function createClinicRecord($data) {
        // Logic to create a clinic record
        $this::db->beginTransaction();

        try {
            $stmt = $this::db->prepare("INSERT INTO clinics (name, location, capacity, status) VALUES (?, ?, ?, ?)");
            $stmt->execute([$data['name'], $data['location'], $data['capacity'], 'open']);

            $clinicId = $this::db->lastInsertId();
            // Additional setup like scheduling and notifications
            $this::notificationService->sendNotification("New clinic created: " . $data['name']);

            $this::db->commit();
        } catch (Exception $e) {
            $this::db->rollBack();
            error_log($e->getMessage());
        }
    }

    private function updateClinicStatus($data) {
        // Logic to update clinic status
        $this::db->beginTransaction();

        try {
            $stmt = $this::db->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=NOW() WHERE id=?");
            $stmt->execute([$data['status'], $_SERVER['REMOTE_ADDR'], $data['id']]);

            if ($data['status'] === 'closed' || $data['status'] === 'emergency') {
                // Notify external API and emergency team
                $this::notificationService->sendNotification("Clinic status changed to " . $data['status']);

                // Update occupancy levels from IoT sensor data
                $occupancyData = $this::iotSensorSystem->getOccupancy($data['id']);
                if ($this::validateIoTData($occupancyData)) {
                    $stmt = $this::db->prepare("UPDATE clinics SET occupancy_level=? WHERE id=?");
                    $stmt->execute([$occupancyData['level'], $data['id']]);
                }
            } elseif ($data['status'] === 'open') {
                // Reschedule canceled appointments
                $this::patientScheduler->rescheduleCanceledAppointments($data['id']);
            }

            $this::db->commit();
        } catch (Exception $e) {
            $this::db->rollBack();
            error_log($e->getMessage());
        }
    }

    private function deleteClinicRecord($clinicId) {
        // Logic to delete a clinic record
        try {
            $stmt = $this::db->prepare("DELETE FROM clinics WHERE id=?");
            $stmt->execute([$clinicId]);

            // Clean up appointments and sensor data
            $this::patientScheduler->cleanupAppointments($clinicId);
            $this::iotSensorSystem->cleanupSensorData($clinicId);

            error_log("Clinic record deleted: " . $clinicId);
        } catch (Exception $e) {
            error_log($e->getMessage());
        }
    }

    private function validateIoTData($data) {
        // Logic to validate IoT sensor data
        return isset($data['level']) && is_numeric($data['level']);
    }
}

// Dependency injections for services would be handled elsewhere in the application

?>
```

