public class WebsiteManager
{
    private static readonly object _lock = new object();
    private static readonly ConcurrentDictionary<string, bool> SiteNames = new();

    public static void AddAndStartWebsite(string directoryPath, string siteName)
    {
        try
        {
            ValidateDirectory(directoryPath);

            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
                throw new FileNotFoundException("Web.Config file is missing in the specified directory.");

            var uniqueSiteName = GetUniqueSiteName(siteName);

            var siteConfig = RetrieveSiteConfiguration(uniqueSiteName);

            LogAction($"Adding and starting website: {uniqueSiteName}");
            StartSiteProcess(directoryPath, uniqueSiteName, siteConfig);

        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            HandleErrorsGracefully(ex);
        }
    }

    private static void ValidateDirectory(string directoryPath)
    {
        if (!Directory.Exists(directoryPath) || !HasAccess(directoryPath))
            throw new DirectoryNotFoundException($"The specified path '{directoryPath}' is not valid or accessible.");
    }

    private static bool HasAccess(string path)
    {
        try
        {
            FileIOPermission permission = new(FileIOPermission(FileIOPermissionAccess.Read, path));
            permission.Demand();
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }

    private static string GetUniqueSiteName(string siteName)
    {
        lock (_lock)
        {
            int counter = 1;
            var uniqueName = siteName;

            while (SiteNames.ContainsKey(uniqueName))
            {
                uniqueName = $"{siteName}{counter++}";
            }

            SiteNames.TryAdd(uniqueName, true);
            return uniqueName;
        }
    }

    private static dynamic RetrieveSiteConfiguration(string siteName)
    {
        // Simulate retrieving configuration from a database
        var config = new { PortNumber = 8080, StartupParameters = "--start" };
        return config;
    }

    private static void StartSiteProcess(string directoryPath, string siteName, dynamic siteConfig)
    {
        int retryCount = 3;
        while (retryCount-- > 0)
        {
            try
            {
                var processStartInfo = new ProcessStartInfo("dotnet", $"run --project {directoryPath} {siteConfig.StartupParameters}")
                {
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    CreateNoWindow = true,
                    WorkingDirectory = directoryPath,
                    EnvironmentVariables =
                    {
                        ["PORT"] = siteConfig.PortNumber.ToString()
                    }
                };

                using var process = Process.Start(processStartInfo);
                LogAction($"Started website '{siteName}' on port {siteConfig.PortNumber}.");

                // Wait for the process to exit
                process.WaitForExit();
                break;
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
                Thread.Sleep(1000); // Backoff before retrying
            }
        }
    }

