```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MD5Hasher {

    private final ExecutorService executorService;
    private final ConcurrentMap<String, String> cache;
    private static final Logger logger = Logger.getLogger(MD5Hasher.class.getName());

    public MD5Hasher(int maxThreads, int cacheSize) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.cache = new ConcurrentHashMap<>();
        // Using LinkedHashMap to create a simple LRU Cache
        this.cache = Collections.synchronizedMap(new LinkedHashMap<String, String>() {
            private final int maxSize;

            {
                super();
                maxSize = cacheSize;
            }

            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > maxSize;
            }
        });
    }

    public CompletableFuture<String> computeMD5Hash(String input) {
        if (input == null || input.length() > 1000) {
            logger.log(Level.WARNING, "Invalid input string: null or exceeds length limit");
            return CompletableFuture.failedFuture(new IllegalArgumentException("Invalid input"));
        }

        String cachedValue = cache.get(input);
        if (cachedValue != null) {
            return CompletableFuture.completedFuture(cachedValue);
        }

        return CompletableFuture.supplyAsync(() -> computeMD5HashInternal(input), executorService)
                .exceptionally(ex -> {
                    logger.log(Level.SEVERE, "Error computing MD5 hash", ex);
                    return null;
                })
                .thenApply(hash -> {
                    if (hash != null) {
                        cache.put(input, hash);
                    }
                    return hash;
                });
    }

    private String computeMD5HashInternal(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(input.getBytes());
            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b & 0xff));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "MD5 algorithm not found", e);
            return null;
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    // Unit tests
    public static void main(String[] args) throws ExecutionException, InterruptedException {
        MD5Hasher hasher = new MD5Hasher(4, 10);

        String input1 = "test";
        String input2 = "anotherTest";

        CompletableFuture<String> future1 = hasher.computeMD5Hash(input1);
        CompletableFuture<String> future2 = hasher.computeMD5Hash(input2);

        // Test concurrent access
        for (int i = 0; i < 10; i++) {
            hasher.computeMD5Hash(input1).get();
            hasher.computeMD5Hash(input2).get();
        }

        System.out.println(future1.get()); // Should print the MD5 hash of "test"
        System.out.println(future2.get()); // Should print the MD5 hash of "anotherTest"

        hasher.shutdown();
    }
}
```

### Key Points:
- **ExecutorService**: A fixed thread pool is used to compute hashes concurrently.
- **LRU Cache**: Implemented using a synchronized `LinkedHashMap` for simple LRU eviction.
- **Concurrency**: The cache and the executor service are designed to be thread-safe.
- **Logging**: Uses Java's built-in logging framework (SLF4J can replace it easily).
- **Input Validation**: Checks for null or excessively long input strings.
- **Unit Tests**: Basic tests in `main` method to verify functionality.

