int check_rate_limit() {
    pthread_mutex_lock(&rate_limiter.lock);
    if (rate_limiter.request_count >= rate_limiter.max_requests) {
        pthread_mutex_unlock(&rate_limiter.lock);
        return -1; // Rate limit exceeded
    }
    rate_limiter.request_count++;
    pthread_mutex_unlock(&rate_limiter.lock);
    return 0;
