void reset_rate_limit() {
    pthread_mutex_lock(&rate_limiter.lock);
    rate_limiter.request_count = 0;
    pthread_mutex_unlock(&rate_limiter.lock);
}

// Resource Pooling and Thread Safety
CryptoResources *get_crypto_resources() {
    pthread_mutex_lock(&resource_pool_lock);
    for (int i = 0; i < MAX_THREADS; i++) {
        if (!resource_pool[i].aes_ctx) { // Find an available resource
            resource_pool[i].aes_ctx = EVP_CIPHER_CTX_new();
            resource_pool[i].rsa_keypair = RSA_new();
            MD5_Init(&resource_pool[i].md5_ctx);
            SHA1_Init(&resource_pool[i].sha1_ctx);
            pthread_mutex_unlock(&resource_pool_lock);
            return &resource_pool[i];
        }
    }
    pthread_mutex_unlock(&resource_pool_lock);
    return NULL; // No available resources
}

void release_crypto_resources(CryptoResources *resources) {
    if (resources) {
        EVP_CIPHER_CTX_free(resources->aes_ctx);
        RSA_free(resources->rsa_keypair);
        pthread_mutex_lock(&resource_pool_lock);
        memset(resources, 0, sizeof(CryptoResources));
