class JSONParser {
    constructor() {
        this.factoryRegistry = {};
    }

    static toJSON(data) {
        return JSON.stringify(data);
    }

    static fromJSON(jsonString) {
        return JSON.parse(jsonString);
    }

    registerFactory(id, factoryFn) {
        if (typeof factoryFn !== 'function') {
            throw new Error('Factory must be a function');
        }
        this.factoryRegistry[id] = factoryFn;
    }

    createInstance(id, ...args) {
        const factoryFn = this.factoryRegistry[id];
        if (!factoryFn) {
            throw new Error(`No factory registered for ID: ${id}`);
        }
        return factoryFn(...args);
    }
}

async function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
    const module = require(moduleLabel);

    async function fetchData(source) {
        // Simulate fetching from a source
        return new Promise((resolve) => setTimeout(() => resolve(`Data from ${source}`), 100));
    }

    for (const label of testLabels) {
        try {
            console.log(`Running test: ${label}`);

            const dataPromises = dataSources.map(fetchData);
            const testData = await Promise.all(dataPromises);

            await testFunctions[testLabels.indexOf(label)](module, testData);

        } catch (error) {
            console.error(`Test failed (${label}):`, error);
        } finally {
            try {
                // Resetting the mocking library
                const resetBlueslip = async () => {
                    if (typeof blueslip.reset === 'function') {
                        await blueslip.reset();
                    }
                };

                for (const cleanup of cleanupFunctions) {
                    await cleanup();
                }

                await resetBlueslip();

            } catch (cleanupError) {
                console.error('Cleanup failed:', cleanupError);
            }
        }
    }
}
