using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public interface ICspService
{
    byte[] GetKey(string context);
    byte[] GetIv(string context);
}

public class TripleDesDecryptor
{
    private readonly ICspService _cspService;
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] Iv)> _keyIvCache;

    public TripleDesDecryptor(ICspService cspService)
    {
        _cspService = cspService ?? throw new ArgumentNullException(nameof(cspService));
        _keyIvCache = new ConcurrentDictionary<string, (byte[] Key, byte[] Iv)>();
    }

    public string DecryptMessage(string base64EncodedMessage, string context)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage))
            throw new ArgumentException("Base64 encoded message is required.", nameof(base64EncodedMessage));

        var keyIv = GetKeyAndIv(context);

        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                tdes.Key = keyIv.Key;
                tdes.IV = keyIv.Iv;
                tdes.Mode = CipherMode.CBC;
                tdes.Padding = PaddingMode.PKCS7;

                using (var decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV))
                {
                    byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                    return Encoding.UTF8.GetString(decryptedBytes);
                }
            }
        }
        catch (CryptographicException ex)
        {
            // Log the error and rethrow or handle appropriately
            Console.Error.WriteLine($"Decryption failed: {ex.Message}");
            throw new InvalidOperationException("Failed to decrypt message.", ex);
        }
        catch (FormatException ex)
        {
            // Handle invalid Base64 format
            Console.Error.WriteLine($"Invalid Base64 format: {ex.Message}");
            throw new ArgumentException("The provided string is not a valid Base64 encoded message.", nameof(base64EncodedMessage), ex);
        }
    }

    private (byte[] Key, byte[] Iv) GetKeyAndIv(string context)
    {
        if (_keyIvCache.TryGetValue(context, out var cached))
        {
            return cached;
        }

        byte[] key = _cspService.GetKey(context);
        byte[] iv = _cspService.GetIv(context);

        if (key == null || iv == null)
            throw new InvalidOperationException($"Keys or IVs are missing for context: {context}");

        var result = (_keyIvCache.AddOrUpdate(context, (Key: key, Iv: iv), (_, existing) => existing));
        return result;
    }
}
```

