Below is a basic structure for a high-performance, fault-tolerant semaphore management system in C. This example includes functions for creating, deleting, incrementing (V operation), and decrementing (P operation) semaphores, with considerations for thread safety, logging, and scalability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_SEMAPHORES 100
#define LOG_FILE "semaphore.log"

typedef struct {
    sem_t semaphore;
    pthread_mutex_t lock;
    char name[256];
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int count = 0;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char *operation, const char *name) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", operation, name);
        fclose(log_file);
    }
}

int create_semaphore(const char *name) {
    pthread_mutex_lock(&global_lock);
    if (count >= MAX_SEMAPHORES) {
        log_operation("Error: Max semaphores reached", name);
        return -1;
    }

    int index = count++;
    strcpy(semaphores[index].name, name);
    sem_init(&semaphores[index].semaphore, 0, 0);
    pthread_mutex_init(&semaphores[index].lock, NULL);

    log_operation("Created semaphore", name);
    pthread_mutex_unlock(&global_lock);
    return index;
}

void delete_semaphore(int index) {
    pthread_mutex_lock(&global_lock);
    if (index < 0 || index >= count) {
        log_operation("Error: Invalid semaphore index", semaphores[index].name);
        pthread_mutex_unlock(&global_lock);
        return;
    }

    sem_destroy(&semaphores[index].semaphore);
    pthread_mutex_destroy(&semaphores[index].lock);

    memmove(&semaphores[index], &semaphores[index + 1], (count - index - 1) * sizeof(Semaphore));
    count--;

    log_operation("Deleted semaphore", semaphores[index].name);
    pthread_mutex_unlock(&global_lock);
}

void increment_semaphore(int index) {
    if (index < 0 || index >= count) return;

    pthread_mutex_lock(&semaphores[index].lock);
    sem_post(&semaphores[index].semaphore);
    log_operation("Incremented semaphore", semaphores[index].name);
    pthread_mutex_unlock(&semaphores[index].lock);
}

void decrement_semaphore(int index) {
    if (index < 0 || index >= count) return;

    pthread_mutex_lock(&semaphores[index].lock);
    sem_wait(&semaphores[index].semaphore);
    log_operation("Decremented semaphore", semaphores[index].name);
    pthread_mutex_unlock(&semaphores[index].lock);
}

void print_usage() {
    printf("Usage:\n");
    printf("  create <name>\n");
    printf("  delete <index>\n");
    printf("  increment <index>\n");
    printf("  decrement <index>\n");
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        print_usage();
        return 1;
    }

    const char *command = argv[1];
    int index;

    if (strcmp(command, "create") == 0 && argc == 3) {
        create_semaphore(argv[2]);
    } else if (strcmp(command, "delete") == 0 && sscanf(argv[2], "%d", &index) == 1) {
        delete_semaphore(index);
    } else if (strcmp(command, "increment") == 0 && sscanf(argv[2], "%d", &index) == 1) {
        increment_semaphore(index);
    } else if (strcmp(command, "decrement") == 0 && sscanf(argv[2], "%d", &index) == 1) {
        decrement_semaphore(index);
    } else {
        print_usage();
        return 1;
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for protecting critical sections.
- **Logging**: Logs operations to a file named `semaphore.log`.
- **Error Handling**: Checks for invalid indices and maximum semaphore limits.
- **Command-Line Interface**: Basic interface for managing semaphores.

