```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public interface ICspService
{
    Task<(byte[] Key, byte[] Iv)> FetchKeyAndIvAsync(string contextId);
}

public class DynamicTripleDesDecryptor
{
    private readonly ICspService _cspService;
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] Iv)> _cache = new();
    private readonly int _maxCacheSize;

    public DynamicTripleDesDecryptor(ICspService cspService, int maxCacheSize = 100)
    {
        _cspService = cspService ?? throw new ArgumentNullException(nameof(cspService));
        _maxCacheSize = maxCacheSize;
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage)) throw new ArgumentException("Base64 encoded message cannot be null or empty.", nameof(base64EncodedMessage));
        if (string.IsNullOrEmpty(contextId)) throw new ArgumentException("Context ID cannot be null or empty.", nameof(contextId));

        var cacheKey = contextId;
        if (_cache.TryGetValue(cacheKey, out var cachedKeyIv))
        {
            return Decrypt(base64EncodedMessage, cachedKeyIv.Key, cachedKeyIv.Iv);
        }

        (byte[] key, byte[] iv) = await FetchKeyAndIvWithRetryAsync(contextId);

        string decryptedMessage = Decrypt(base64EncodedMessage, key, iv);

        CacheKeyAndIv(contextId, key, iv);

        return decryptedMessage;
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
        return Task.Run(() => DecryptMessageAsync(base64EncodedMessage, contextId)).GetAwaiter().GetResult();
    }

    private async Task<(byte[] Key, byte[] Iv)> FetchKeyAndIvWithRetryAsync(string contextId, int retries = 3, int delayMilliseconds = 1000)
    {
        for (int attempt = 1; attempt <= retries; attempt++)
        {
            try
            {
                return await _cspService.FetchKeyAndIvAsync(contextId);
            }
            catch (Exception ex) when (attempt < retries)
            {
                Console.WriteLine($"Attempt {attempt} failed: {ex.Message}. Retrying in {delayMilliseconds / 1000} seconds...");
                await Task.Delay(delayMilliseconds);
            }
        }

        throw new Exception("Failed to fetch key and IV after multiple attempts.");
    }

    private void CacheKeyAndIv(string contextId, byte[] key, byte[] iv)
    {
        if (_cache.Count >= _maxCacheSize)
        {
            string oldestKey = null;
            foreach (var cacheItem in _cache)
            {
                if (oldestKey == null || _cache[oldestKey].Timestamp < _cache[cacheItem.Key].Timestamp)
                    oldestKey = cacheItem.Key;
            }

            if (oldestKey != null)
                _cache.TryRemove(oldestKey, out _);
        }

        _cache[contextId] = (key, iv, DateTime.UtcNow);
    }

    private string Decrypt(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        try
        {
            using var des = new TripleDESCryptoServiceProvider
            {
                Key = key,
                Iv = iv,
                Mode = CipherMode.CBC,
                Padding = PaddingMode.PKCS7
            };

            byte[] cipherTextBytes = Convert.FromBase64String(base64EncodedMessage);
            using var decryptor = des.CreateDecryptor(des.Key, des.Iv);

            using var ms = new MemoryStream(cipherTextBytes);
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            using var sr = new StreamReader(cs);

            return sr.ReadToEnd();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption failed: {ex.Message}");
            throw;
        }
    }

    private record CacheItem(byte[] Key, byte[] Iv, DateTime Timestamp);
}
```

```php
<?php

class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cache = [];
    private $logFile = 'password_attempts.log';
    private $loginAttempts = [];
    private $characterSet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;':,.<>?";

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        $characters = $this->validateCharacterSet($this->characterSet);
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, strlen($characters) - 1);
            $randomString .= $characters[$randomIndex];
        }

        $this->cache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $options = ['cost' => max(min((int)$this->saltRoundCount, 31), 12)];
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (
            preg_match('/[A-Z]/', $characterSet) &&
            preg_match('/[a-z]/', $characterSet) &&
            preg_match('/\d/', $characterSet) &&
            preg_match('/[\W_]/', $characterSet)
        ) {
            return $characterSet;
        }

        // Suggest corrected character set if invalid
        return "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;':,.<>?";
    }

    public function setSaltRoundCount($rounds) {
        $this->saltRoundCount = max(min((int)$rounds, 31), 12);
    }

    public function resetPassword() {
        if ($this->hashedPassword !== null) {
            $length = strlen(str_replace('*', '', $this->hashedPassword)); // Exclude salt rounds
            unset($this->cache[$length]);
        }

        $password = $this->generateSecureRandomString(12);
        $this->hashPassword($password);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        $logEntry = sprintf(
            "[%s] IP: %s - Attempt: %s\n",
            date('Y-m-d H:i:s'),
            $ipAddress,
            $result ? 'Success' : 'Failure'
        );

        file_put_contents($this->logFile, $logEntry, FILE_APPEND);
    }

    public function enforceTwoFactorAuthentication() {
        // Simple 2FA mechanism stub
        $code = mt_rand(100000, 999999); // Generate a temporary code
        // Send this code via SMS or email (logic not implemented here)
        return $code;
    }

    public function limitLoginAttemptsPerIp($maxAttempts) {
        $ipAddress = $_SERVER['REMOTE_ADDR'];
        $currentTime = time();

        if (!isset($this->loginAttempts[$ipAddress])) {
            $this->loginAttempts[$ipAddress] = [];
        }

        // Remove outdated attempts
        $this->loginAttempts[$ipAddress] = array_filter(
            $this->loginAttempts[$ipAddress],
            function ($attemptTime) use ($currentTime) {
                return ($currentTime - $attemptTime) < 300; // Keep within last 5 minutes
            }
        );

        if (count($this->loginAttempts[$ipAddress]) >= $maxAttempts) {
            return false; // Block further attempts
        }

        // Record the attempt time
        $this->loginAttempts[$ipAddress][] = $currentTime;
        return true;
    }

    public function sanitizeInput($input) {
        // Example sanitization logic: trim and strip tags
        return htmlspecialchars(trim(strip_tags($input)));
    }
}

