Below is an example C code implementing the described functionality using OpenSSL's cryptographic library. Note that this is a simplified version; actual implementations may require more rigorous error checking, security audits, and optimizations.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 24 // For example, key stretching to DES-EDE3 requires 24 bytes

EVP_CIPHER_CTX *create_cipher_context(const char *cipher_name, int encrypt,
                                      const unsigned char *key, size_t key_len,
                                      const unsigned char *iv, size_t iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    // Key stretching using KDF (e.g., PBKDF2)
    unsigned char derived_key[KEY_SIZE];
    if (key_len < KEY_SIZE) {
        if (!PKCS5_PBKDF2_HMAC(key, key_len, NULL, 0, 1000, EVP_sha256(), KEY_SIZE, derived_key)) {
            fprintf(stderr, "Key derivation failed\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        memcpy(derived_key, key, KEY_SIZE); // Use as-is if already large enough
    }

    int cipher_type = encrypt ? EVP_CIPH_ENCRYPT : EVP_CIPH_DECRYPT;

    if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, derived_key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Additional configuration for other modes
    const char *default_iv = NULL; // For ECB mode
    if (iv && iv_len > 0) {
        default_iv = iv;
    } else if (!iv || iv_len == 8) { // Use random IV if not provided or length is invalid
        unsigned char random_iv[EVP_MAX_IV_LENGTH];
        if (!RAND_bytes(random_iv, EVP_CIPHER_iv_length(EVP_des_ede3_cbc()))) {
            fprintf(stderr, "Error generating random IV\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        default_iv = random_iv;
    }

    // Handle different modes of operation
    switch (cipher_name[0]) {
        case 'E':
            if (!strcmp(cipher_name, "ECB")) {
                if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_ecb(), NULL, derived_key, default_iv)) {
                    fprintf(stderr, "Error initializing ECB mode\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
            } else if (strstr(cipher_name, "CFB")) { // Supports EDE and EDE3
                int cfb_len = iv_len > 8 ? iv_len : 8;
                if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cfb(), NULL, derived_key, default_iv)) {
                    fprintf(stderr, "Error initializing CFB mode\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
            } else if (strstr(cipher_name, "OFB")) { // Add similar handling for OFB
                if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_ofb(), NULL, derived_key, default_iv)) {
                    fprintf(stderr, "Error initializing OFB mode\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
            } else if (strstr(cipher_name, "CTR")) { // Add similar handling for CTR
                if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_ctr(), NULL, derived_key, default_iv)) {
                    fprintf(stderr, "Error initializing CTR mode\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
            } else {
                fprintf(stderr, "Unsupported cipher mode\n");
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            }
            break;

        case 'N':
            if (!strcmp(cipher_name, "NULL")) { // Null encryption
                if (!EVP_EncryptInit_ex(ctx, EVP_des_null(), NULL, derived_key, default_iv)) {
                    fprintf(stderr, "Error initializing null cipher\n");
                    EVP_CIPHER_CTX_free(ctx);
                    return NULL;
                }
            } else {
                fprintf(stderr, "Unsupported cipher mode\n");
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            }
            break;

        default:
            fprintf(stderr, "Invalid cipher name\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
    }

    return ctx;
}

void secure_memzero(void *ptr, size_t len) {
    if (!ptr || len <= 0) return;
    volatile unsigned char *volatile p = (volatile unsigned char *) ptr;
    while (len--) *p++ = 0;
}

int main(int argc, char **argv) {
    const char *cipher_name = "ECB"; // Default cipher
    int encrypt = 1; // Encrypt by default
    size_t key_len = 8; // Example key length
    unsigned char key[] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef}; // Example key

    size_t iv_len = 8;
    unsigned char iv[] = {0x12, 0x34, 0x56, 0x78, 0x90, 0xab, 0xcd, 0xef}; // Default IV

    if (argc > 1) {
        cipher_name = argv[1];
    }
    if (argc > 2) {
        encrypt = atoi(argv[2]);
    }

    EVP_CIPHER_CTX *ctx = create_cipher_context(cipher_name, encrypt, key, key_len, iv, iv_len);
    if (!ctx) return EXIT_FAILURE;

    // Example usage of ctx for encryption/decryption

    secure_memzero(key, sizeof(key));
    EVP_CIPHER_CTX_free(ctx);

    return EXIT_SUCCESS;
}
```

### Key Points:
1. **Key Stretching**: Uses PBKDF2 to derive a key suitable for DES-EDE3.
2. **Multiple Modes**: Supports ECB, EDE, EDE3, CFB, OFB, and NULL modes with default configurations.
3. **Secure Memory Management**: `secure_memzero` function ensures sensitive data is zeroed out securely.
4. **Error Handling**: Includes checks for invalid inputs and error messages.
5. **Performance Considerations**: Uses efficient OpenSSL functions for cryptographic operations.

