```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.Set;
import java.util.concurrent.*;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class NioKafkaServer {
    private final Selector selector;
    private final ExecutorService executorService;
    private final KafkaProducer<String, String> kafkaProducer;
    private final int port;
    private final int maxConnections;

    public NioKafkaServer(int port, int maxConnections) throws IOException {
        this.port = port;
        this.maxConnections = maxConnections;
        this.selector = Selector.open();
        this.executorService = Executors.newCachedThreadPool();
        Properties kafkaProps = new Properties();
        kafkaProps.put("bootstrap.servers", "localhost:9092");
        kafkaProps.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        kafkaProps.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        this.kafkaProducer = new KafkaProducer<>(kafkaProps);
    }

    public void start() throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.socket().bind(new InetSocketAddress(port));
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        while (true) {
            selector.select();

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> iter = selectedKeys.iterator();

            while (iter.hasNext()) {
                SelectionKey key = iter.next();
                if (!key.isValid()) continue;

                if (key.isAcceptable()) {
                    handleAccept(serverSocketChannel);
                } else if (key.isReadable()) {
                    handleRead(key);
                }

                iter.remove();
            }
        }
    }

    private void handleAccept(ServerSocketChannel serverSocketChannel) throws IOException {
        SocketChannel socketChannel = serverSocketChannel.accept();
        if (socketChannel != null) {
            socketChannel.configureBlocking(false);
            socketChannel.register(selector, SelectionKey.OP_READ);

            logConnectionState(socketChannel, "Accepted");
        }
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(256);
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            logConnectionState(channel, "Closed");
            channel.close();
            return;
        }

        String receivedData = new String(buffer.array()).trim();
        handleReceivedData(receivedData, channel);

        buffer.clear();
    }

    private void handleReceivedData(String data, SocketChannel socketChannel) {
        // Process and send to Kafka
        kafkaProducer.send(new ProducerRecord<>("topic", "key", data));

        logConnectionState(socketChannel, "Data Received: " + data);
    }

    private synchronized void logConnectionState(SocketChannel channel, String message) {
        System.out.println("SocketChannel: " + channel.getRemoteAddress() + ", State: " + message);
    }

    public static void main(String[] args) throws IOException {
        NioKafkaServer server = new NioKafkaServer(8080, 1000);
        server.start();
    }
}
```

### Key Points:
- **Non-blocking I/O**: Uses `Selector` and `SocketChannel` for non-blocking operations.
- **Concurrency**: Managed using `ExecutorService`.
- **Asynchronous Communication**: Integrates with Apache Kafka for message queuing.
- **Resource Management**: Channels are closed when no longer needed to prevent leaks.
- **Logging**: Basic logging implemented; can be expanded for more detailed monitoring.
- **Scalability**: Designed to handle multiple connections concurrently.

### Testing and Monitoring:
- Unit tests should mock `KafkaProducer` and verify interactions.
- Integration tests can simulate client connections.
- Real-time monitoring can be integrated using external tools or frameworks.

