using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class TripleDesDecryptor : IDisposable
{
    private readonly ConcurrentDictionary<string, (byte[] key, byte[] iv)> _keyPool = new();
    private readonly IKeyProvider _primaryCSP;
    private readonly IKeyProvider _backupCSP;
    private bool _disposed = false;

    public TripleDesDecryptor(IKeyProvider primaryCsp, IKeyProvider backupCsp)
    {
        _primaryCSP = primaryCsp ?? throw new ArgumentNullException(nameof(primaryCsp));
        _backupCSP = backupCsp;
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string source, int clearanceLevel)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(TripleDesDecryptor));

        // Validate message
        if (!ValidateMessage(base64EncodedMessage))
        {
            AuditLog(source, clearanceLevel, false, "Validation failed.");
            return "Invalid message format.";
        }

        try
        {
            (byte[] key, byte[] iv) = await RetrieveKeyAsync(clearanceLevel);

            // Decrypt the message
            string decryptedMessage = DecryptTripleDes(base64EncodedMessage, key, iv);

            AuditLog(source, clearanceLevel, true, "Decryption successful.");
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            AuditLog(source, clearanceLevel, false, $"Decryption failed: {ex.Message}");
            throw; // Re-throw exception for further handling
        }
    }

    public string DecryptMessage(string base64EncodedMessage, string source, int clearanceLevel)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(TripleDesDecryptor));

        return Task.Run(async () => await DecryptMessageAsync(base64EncodedMessage, source, clearanceLevel)).GetAwaiter().GetResult();
    }

    private async Task<(byte[] key, byte[] iv)> RetrieveKeyAsync(int clearanceLevel)
    {
        var cacheKey = $"{clearanceLevel}-key";

        if (_keyPool.TryGetValue(cacheKey, out var cached))
            return cached;

        (byte[] key, byte[] iv) = await FetchFromCSPAsync(clearanceLevel);

        _keyPool[cacheKey] = (key, iv);

        return (key, iv);
    }

    private async Task<(byte[] key, byte[] iv)> FetchFromCSPAsync(int clearanceLevel)
    {
        try
        {
            var keyProvider = await _primaryCSP.FetchKeyAsync(clearanceLevel);

            if (keyProvider != null) return keyProvider;

            if (_backupCSP == null) throw new InvalidOperationException("Backup CSP not configured.");

            return await _backupCSP.FetchKeyAsync(clearanceLevel);
        }
        catch
        {
            // Handle failover logic or rethrow if necessary
            if (_backupCSP != null)
                return await _backupCSP.FetchKeyAsync(clearanceLevel);

            throw;
        }
    }

    private string DecryptTripleDes(string base64EncodedMessage, byte[] key, byte[] iv)
    {
        using var des = new TripleDESCryptoServiceProvider { Key = key, IV = iv };

        var cipherBytes = Convert.FromBase64String(base64EncodedMessage);

        using var decryptor = des.CreateDecryptor();
        using var ms = new MemoryStream(cipherBytes);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
        using var sr = new StreamReader(cs);

        return sr.ReadToEnd();
    }

    private bool ValidateMessage(string base64EncodedMessage)
    {
        // Implement specific validation logic
        // Example: check if message includes a timestamp and checksum
        try
        {
            Convert.FromBase64String(base64EncodedMessage);
            // Additional checks...
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private void AuditLog(string source, int clearanceLevel, bool success, string message)
    {
        // Implement logging logic
        Console.WriteLine($"[{DateTime.UtcNow}] Source: {source}, Clearance Level: {clearanceLevel}, Success: {success}, Message: {message}");
    }

    public void Dispose()
    {
        if (_disposed) return;

        _keyPool.Clear();
        _primaryCSP?.Dispose();
        _backupCSP?.Dispose();

        _disposed = true;
    }
}

public interface IKeyProvider : IDisposable
{
    Task<(byte[] key, byte[] iv)> FetchKeyAsync(int clearanceLevel);
}
