#include <openssl/evp.h>
#include <openssl/rsa.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for the cryptographic context
typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_MD_CTX *md5_ctx;
    EVP_SHA_CTX *sha_ctx;
    RSA *rsa_key;
} CryptoContext;

// Initialize OpenSSL library
void initialize_openssl() {
    OpenSSL_add_all_algorithms();
}

// Cleanup OpenSSL resources
void cleanup_openssl(CryptoContext *ctx) {
    if (ctx->aes_ctx) EVP_CIPHER_CTX_free(ctx->aes_ctx);
    if (ctx->md5_ctx) EVP_MD_CTX_destroy(ctx->md5_ctx);
    if (ctx->sha_ctx) EVP_SHA_CTX_cleanup(ctx->sha_ctx);
    if (ctx->rsa_key) RSA_free(ctx->rsa_key);
}

// Function to initialize AES context
int init_aes_context(CryptoContext *ctx, const unsigned char *key, int key_len) {
    ctx->aes_ctx = EVP_CIPHER_CTX_new();
    if (!ctx->aes_ctx) return 0;
    if (1 != EVP_EncryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, key, NULL)) return 0;
    return 1;
}

// Function to initialize MD5 context
int init_md5_context(CryptoContext *ctx) {
    ctx->md5_ctx = EVP_MD_CTX_create();
    if (!ctx->md5_ctx) return 0;
    if (1 != EVP_DigestInit_ex(ctx->md5_ctx, EVP_md5(), NULL)) return 0;
    return 1;
}

// Function to initialize SHA context
int init_sha_context(CryptoContext *ctx) {
    ctx->sha_ctx = EVP_SHA_CTX_new();
    if (!ctx->sha_ctx) return 0;
    if (1 != EVP_DigestInit_ex(ctx->sha_ctx, EVP_sha256(), NULL)) return 0;
    return 1;
}

// Function to initialize RSA context
int init_rsa_context(CryptoContext *ctx, const unsigned char *key_data, size_t key_len) {
    ctx->rsa_key = d2i_RSAPrivateKey(NULL, &key_data, key_len);
    if (!ctx->rsa_key) return 0;
    return 1;
}

// Example function to perform AES encryption
int aes_encrypt(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len,
                unsigned char *ciphertext, int *ciphertext_len) {
    if (1 != EVP_EncryptUpdate(ctx->aes_ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) return 0;
    int len;
    if (1 != EVP_EncryptFinal_ex(ctx->aes_ctx, ciphertext + *ciphertext_len, &len)) return 0;
    *ciphertext_len += len;
    return 1;
}

// Function to perform MD5 hashing
int md5_hash(CryptoContext *ctx, const unsigned char *data, size_t data_len,
             unsigned char *md_value) {
    if (1 != EVP_DigestUpdate(ctx->md5_ctx, data, data_len)) return 0;
    unsigned int len = sizeof(md_value);
    if (1 != EVP_DigestFinal_ex(ctx->md5_ctx, md_value, &len)) return 0;
    return 1;
}

// Function to perform SHA hashing
int sha_hash(CryptoContext *ctx, const unsigned char *data, size_t data_len,
             unsigned char *sha_value) {
    if (1 != EVP_DigestUpdate(ctx->sha_ctx, data, data_len)) return 0;
    unsigned int len = sizeof(sha_value);
    if (1 != EVP_DigestFinal_ex(ctx->sha_ctx, sha_value, &len)) return 0;
    return 1;
}

// Thread-safe wrapper for concurrent operations
pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;

void perform_concurrent_operation(void *(*operation)(void *), void *arg) {
    pthread_t thread;
    pthread_mutex_lock(&crypto_mutex);
    if (pthread_create(&thread, NULL, operation, arg) == 0) {
        pthread_detach(thread);
    }
    pthread_mutex_unlock(&crypto_mutex);
}

// Example usage
int main() {
    initialize_openssl();

    CryptoContext ctx = {0};
    unsigned char key[32] = "0123456789abcdef0123456789abcdef"; // Example key

    if (!init_aes_context(&ctx, key, sizeof(key))) {
        fprintf(stderr, "Failed to initialize AES context\n");
        return 1;
    }

    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];
    int len;

    if (aes_encrypt(&ctx, plaintext, strlen((char *)plaintext), ciphertext, &len)) {
        printf("Ciphertext: ");
        for (int i = 0; i < len; i++) printf("%02x", ciphertext[i]);
        printf("\n");
    } else {
        fprintf(stderr, "AES encryption failed\n");
    }

    cleanup_openssl(&ctx);
    EVP_cleanup();
    return 0;
}
```

