using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlDataExtractor
{
    private readonly Dictionary<string, List<object>> cache = new Dictionary<string, List<object>>();

    public List<object> ExtractData(string xmlContent, string xPathExpression)
    {
        if (string.IsNullOrEmpty(xmlContent) || string.IsNullOrEmpty(xPathExpression))
        {
            throw new ArgumentException("XML content and XPath expression must be provided.");
        }

        // Check cache
        if (cache.TryGetValue(xPathExpression, out var cachedResult))
        {
            return cachedResult;
        }

        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.LoadXml(xmlContent);
            XmlNodeList nodes = xmlDoc.SelectNodes(xPathExpression);

            if (nodes == null)
            {
                throw new Exception($"No data found for XPath: {xPathExpression}");
            }

            List<object> results = new List<object>();
            foreach (XmlNode node in nodes)
            {
                if (node.HasChildNodes && node.ChildNodes.Count > 1)
                {
                    // Handle nested structures
                    foreach (XmlNode childNode in node.ChildNodes)
                    {
                        results.Add(ExtractData(childNode.OuterXml, xPathExpression));
                    }
                }
                else
                {
                    results.Add(node.InnerText);
                }
            }

            if (results.Count > 1 && !IsExpectedMultipleResults(xPathExpression))
            {
                throw new Exception($"Multiple matching nodes found for XPath: {xPathExpression}");
            }

            // Cache the result
            cache[xPathExpression] = results;

            return results;
        }
        catch (XPathException ex)
        {
            throw new Exception($"Invalid XPath expression: {ex.Message}", ex);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error extracting data: {ex.Message}");
            return new List<object>();
        }
    }

    private bool IsExpectedMultipleResults(string xPathExpression)
    {
        // Implement logic to determine if multiple results are expected
        // This could be based on a configuration or specific rules for certain XPath expressions
        return false;
    }

