```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_THREADS 4

typedef struct {
    char *jpeg_file;
    char *pdf_file;
} ConversionTask;

void *convert_to_pdf(void *arg) {
    ConversionTask *task = (ConversionTask *)arg;
    char command[1024];

    snprintf(command, sizeof(command), "convert %s %s", task->jpeg_file, task->pdf_file);

    int result = system(command);

    if (result != 0) {
        fprintf(stderr, "Error converting %s to PDF\n", task->jpeg_file);
        pthread_exit((void *)(intptr_t)-1); // Return -1 on failure
    }

    free(task->jpeg_file);
    free(task->pdf_file);
    free(task);

    pthread_exit(NULL); // Success
}

int progress_callback(int current, int total) {
    printf("Conversion progress: %d/%d\n", current, total);
    return 0;
}

int convert_jpegs_to_pdfs(const char *input_dir, const char *output_dir, void (*callback)(int, int)) {
    DIR *dir = opendir(input_dir);
    if (!dir) {
        fprintf(stderr, "Error opening directory: %s\n", input_dir);
        return -1;
    }

    struct dirent *entry;
    ConversionTask *tasks[MAX_THREADS];
    pthread_t threads[MAX_THREADS];
    int total_files = 0, converted_files = 0, failed_conversions = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strcasecmp(entry->d_name + strlen(entry->d_name) - 4, ".jpg") == 0 ||
            strcasecmp(entry->d_name + strlen(entry->d_name) - 5, ".jpeg") == 0) {

            char jpeg_path[256];
            snprintf(jpeg_path, sizeof(jpeg_path), "%s/%s", input_dir, entry->d_name);

            char pdf_path[256];
            snprintf(pdf_path, sizeof(pdf_path), "%s/%.*s.pdf",
                     output_dir,
                     (int)(strlen(entry->d_name) - 4),
                     entry->d_name + strlen(entry->d_name) - 4);

            ConversionTask *task = malloc(sizeof(ConversionTask));
            task->jpeg_file = strdup(jpeg_path);
            task->pdf_file = strdup(pdf_path);

            tasks[total_files] = task;
            total_files++;
        }
    }

    closedir(dir);

    for (int i = 0; i < total_files; ) {
        int threads_started = 0;

        while (threads_started < MAX_THREADS && i < total_files) {
            pthread_create(&threads[threads_started], NULL, convert_to_pdf, tasks[i]);
            threads[threads_started]++;
            i++;
            threads_started++;
        }

        for (int j = 0; j < threads_started; j++) {
            void *status;
            pthread_join(threads[j], &status);
            if ((intptr_t)status == -1) {
                failed_conversions++;
            } else {
                converted_files++;
            }
        }

        if (callback)
            callback(converted_files, total_files);
    }

    return failed_conversions;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_directory> <output_directory>\n", argv[0]);
        return -1;
    }

    int failures = convert_jpegs_to_pdfs(argv[1], argv[2], progress_callback);

    if (failures > 0)
        fprintf(stderr, "%d conversions failed.\n", failures);

    return failures;
}
```

### Notes:
- The code uses the `convert` command from ImageMagick for JPEG to PDF conversion.
- It manages threading using POSIX threads (`pthread`) and handles up to `MAX_THREADS` concurrent conversions.
- Error handling includes logging conversion errors but continues processing other files.
- A simple progress callback informs about the number of converted files.
- Ensure that ImageMagick is installed on your system for this code to work.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <filesystem>
#include <thread>
#include <mutex>
#include <fstream>
#include <unordered_set>
#include <future>

namespace fs = std::filesystem;

struct Script {
    std::string content;
};

void logError(const std::string& message) {
    std::cerr << "Error: " << message << std::endl;
}

int convertJPEGToPDF(const std::string& jpegPath, const std::string& pdfPath) {
    // Simulate third-party tool conversion
    try {
        if (std::system(("convert " + jpegPath + " " + pdfPath).c_str()) != 0) {
            throw std::runtime_error("Conversion failed for " + jpegPath);
        }
        return 0;
    } catch (const std::exception& e) {
        logError(e.what());
        return -1;
    }
}

void renderScriptTag(const Script& script, std::string& htmlContent, int index, std::mutex& lock) {
    std::lock_guard<std::mutex> guard(lock);
    htmlContent += "<script id='script_" + std::to_string(index) + "'>" + script.content + "</script>\n";
}

void processJPEGFiles(const fs::path& dirPath, const std::vector<Script>& scripts,
                      int (*progressCallback)(int, int), std::string& htmlContent) {
    int totalFiles = 0;
    int processedFiles = 0;

    // List all JPEG files
    for (const auto& entry : fs::directory_iterator(dirPath)) {
        if (entry.path().extension() == ".jpg" || entry.path().extension() == ".jpeg") {
            totalFiles++;
        }
    }

    std::unordered_set<std::string> processedJPEGs;
    std::mutex lock;

    for (const auto& entry : fs::directory_iterator(dirPath)) {
        if ((entry.path().extension() == ".jpg" || entry.path().extension() == ".jpeg") &&
            processedJPEGs.insert(entry.path().filename().string()).second) {

            // Convert JPEG to PDF
            std::string pdfPath = dirPath / (entry.path().stem().string() + ".pdf");
            int conversionResult = convertJPEGToPDF(entry.path().string(), pdfPath.string());

            if (conversionResult == 0) {
                processedFiles++;
                progressCallback(processedFiles, totalFiles);
            }

            // Render script tag
            std::async(std::launch::async, renderScriptTag,
                       scripts[processedFiles - 1], std::ref(htmlContent), processedFiles - 1, std::ref(lock));
        }
    }
}

int generateHTMLWithScripts(const fs::path& dirPath, const std::vector<Script>& scripts,
                            int (*progressCallback)(int, int)) {
    if (!fs::exists(dirPath) || !fs::is_directory(dirPath)) {
        logError("Invalid directory path.");
        return -1;
    }

    std::string htmlContent = "<html><body>\n";
    htmlContent += "<footer>";

    std::vector<std::future<void>> futures;

    // Start processing JPEG files
    futures.emplace_back(std::async(std::launch::async, processJPEGFiles,
                                    dirPath, scripts, progressCallback, std::ref(htmlContent)));

    for (auto& fut : futures) {
        fut.get();
    }

    htmlContent += "</footer>\n</body></html>";

    // Save the HTML content to a file or return it as needed
    std::ofstream outFile("output.html");
    if (!outFile.is_open()) {
        logError("Failed to open output file.");
        return -1;
    }
    outFile << htmlContent;

    int failedConversions = totalFiles - processedFiles;
    return failedConversions;
}

// Example progress callback function
