// Base class for JSON parsing and creation
abstract class JsonObjectBase {
    private static final Logger logger = LoggerFactory.getLogger(JsonObjectBase.class);
    protected static final ObjectMapper objectMapper = new ObjectMapper();
    protected static final LoadingCache<String, Object> jsonCache = CacheBuilder.newBuilder()
            .maximumSize(100)
            .build(new CacheLoader<String, Object>() {
                @Override
                public Object load(String key) throws Exception {
                    return objectMapper.readValue(key, getTypeReference());
                }
            });

    private static TypeReference<?> getTypeReference() {
        try {
            // Example: Return a generic reference for demonstration
            return (TypeReference<?>) new TypeToken<Map<String, Object>>() {}.getType();
        } catch (Exception e) {
            logger.error("Failed to get type reference", e);
            return null;
        }
    }

    public abstract String toJson();

    public static JsonObjectBase fromJson(String jsonString, Class<?> clazz) throws IOException {
        try {
            if (jsonCache.get(jsonString)) { // Cache hit
                logger.info("Cache hit for JSON: {}", jsonString);
                return objectMapper.convertValue(jsonObjectCacheGet(jsonString), clazz);
            }

            // Validate JSON schema here (pseudo-code)
            JsonSchemaFactory factory = JsonSchema2Pojo.getInstance();
            SchemaMapper schemaMapper = new SchemaMapper(factory);
            Class<?> generatedClass = schemaMapper.getRegisteredClasses().get(clazz);

            // Example schema validation
            if (generatedClass != null) {
                factory.generate(generatedClass, "schema.json");
            }

            logger.info("JSON parsed and converted to object of class: {}", clazz.getName());
            return objectMapper.readValue(jsonString, clazz);
        } catch (Exception e) {
            logger.error("Failed to parse JSON", e);
            throw new IOException("Invalid JSON format", e);
        }
    }

    private static Object jsonObjectCacheGet(String jsonString) {
        try {
            return jsonCache.get(jsonString);
        } catch (ExecutionException e) {
            logger.error("Error retrieving from cache", e);
            return null;
        }
    }
}

// Factory class with registry and versioning
class FactoryRegistry {
    private static final Logger logger = LoggerFactory.getLogger(FactoryRegistry.class);
    private static final Map<String, Map<Integer, Constructor<? extends JsonObjectBase>>> factoryMap = new ConcurrentHashMap<>();

    public static void register(String id, int version, Constructor<? extends JsonObjectBase> constructor) {
        factoryMap.computeIfAbsent(id, k -> new HashMap<>()).put(version, constructor);
        logger.info("Registered factory for ID: {}, Version: {}", id, version);
    }

    public static JsonObjectBase createInstance(String id, int version, String jsonString) throws Exception {
        if (factoryMap.containsKey(id) && factoryMap.get(id).containsKey(version)) {
            Constructor<? extends JsonObjectBase> constructor = factoryMap.get(id).get(version);
            JsonObjectBase instance = constructor.newInstance();
            return JsonObjectBase.fromJson(jsonString, instance.getClass());
        }
        throw new IllegalArgumentException("No factory registered for ID: " + id + ", Version: " + version);
    }
}

// Service management with thread-safe control
class ServiceManager {
    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);
    private static final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(1);
    private static final Semaphore serviceSemaphore = new Semaphore(5); // Limit concurrent services

    public static void startStopService() {
        Runnable task = () -> {
            try {
                if (serviceSemaphore.tryAcquire()) {
                    logger.info("Starting service");
                    Random random = new Random();
                    int delay = Config.getStartDelayRangeMin() + random.nextInt(Config.getStartDelayRangeMax() - Config.getStartDelayRangeMin());
                    executorService.schedule(() -> stopService(), delay, TimeUnit.MILLISECONDS);
                }
            } catch (Exception e) {
                logger.error("Error managing service", e);
            }
        };

        executorService.scheduleAtFixedRate(task, 0, 1, TimeUnit.SECONDS); // Start a new cycle every second
    }

    private static void stopService() {
        try {
            logger.info("Stopping service");
            // Implement message sending to the messaging system here (pseudo-code)
            // sendMessageToSystem("Service stopped");

            serviceSemaphore.release();
        } catch (Exception e) {
            logger.error("Error stopping service", e);
        }
    }

    public static void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}

