import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StateLoader {
    private static final Logger LOGGER = Logger.getLogger(StateLoader.class.getName());
    private static final int MAX_CACHE_SIZE = 100; // Configurable cache size

    private final ConcurrentHashMap<String, MoSTState> stateCache = new ConcurrentHashMap<>();
    private final ExternalStateService externalStateService; // Assume this is defined elsewhere

    public StateLoader(ExternalStateService service) {
        this.externalStateService = service;
    }

    public MoSTState loadStateFromFile(String fileName) {
        try {
            // Check the cache first
            if (stateCache.containsKey(fileName)) {
                LOGGER.log(Level.INFO, "Cache hit for file: {0}", fileName);
                return stateCache.get(fileName);
            }

            // Check with external service for real-time updates
            MoSTState updatedState = externalStateService.checkForUpdatedState(fileName);
            if (updatedState != null) {
                LOGGER.log(Level.INFO, "Found updated state from external service: {0}", fileName);
                addToCache(fileName, updatedState);
                return updatedState;
            }

            // Load the state object from file
            MoSTState state = loadFromFile(fileName);

            if (state != null) {
                addToCache(fileName, state);
            }

            return state;
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.log(Level.SEVERE, "Error loading state from file: {0}", fileName, e);
            return null;
        }
    }

    private MoSTState loadFromFile(String fileName) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(fileName))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                LOGGER.log(Level.INFO, "Loaded state from file: {0}", fileName);
                return (MoSTState) obj;
            }
        }
        LOGGER.log(Level.WARNING, "File does not contain a valid MoSTState object: {0}", fileName);
        return null;
    }

    private void addToCache(String fileName, MoSTState state) {
        if (stateCache.size() >= MAX_CACHE_SIZE) {
            // Remove the least recently used item; using simple removal strategy for simplicity
            String oldestKey = stateCache.keySet().iterator().next();
            LOGGER.log(Level.INFO, "Evicting {0} from cache", oldestKey);
            stateCache.remove(oldestKey);
        }
        stateCache.put(fileName, state);
    }
}

// Placeholder class definitions to make the code self-contained
class MoSTState implements Serializable {
    // Assume implementation details are here
}

interface ExternalStateService {
    MoSTState checkForUpdatedState(String fileName);
}
