int fetchUserSettings(const char *username, UserSettings *settings) {
    // Simulating network/API call with potential errors
    if (username == NULL || settings == NULL) return -1;  // Invalid pointers

    // Example: Fetching user-specific data based on username
    if (strcmp(username, "userA") == 0) {
        settings->max_length = 100;
        settings->trim_and_capitalize = 1;
        return 0;
    } else if (strcmp(username, "userB") == 0) {
        settings->max_length = 200;
        settings->trim_and_capitalize = 0;
        return 0;
    }

    // Simulate network failure or invalid user
    return -2; 
}

void trimAndCapitalize(char *str) {
    if (str == NULL) return;

    char *end = str + strlen(str) - 1;

    // Trim leading spaces
    while (*str && *str == ' ') str++;

    // Trim trailing spaces
    while (end > str && end[-1] == ' ') end--;

    // Null-terminate after the last non-space character
    *(end + 1) = '\0';

    // Capitalize in place
    for (; *str; ++str) {
        if (*str >= 'a' && *str <= 'z') {
            *str -= ('a' - 'A');
        }
    }
}

char* processUserInput(const char *username, const char *inputString) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (username == NULL || inputString == NULL) return NULL;  // Invalid pointers

    UserSettings settings;
    int apiResult = fetchUserSettings(username, &settings);

    if (apiResult != 0) {
        fprintf(stderr, "Error fetching user settings: %d\n", apiResult);
        return NULL;
    }

    pthread_mutex_lock(&mutex);  // Handle concurrent requests with mutex

    size_t inputLength = strlen(inputString);
    char *processedStr;

    if (inputLength > MAX_INPUT_LENGTH) {
        fprintf(stderr, "Input string too long.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    processedStr = malloc(settings.max_length + 1);

    if (!processedStr) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    strncpy(processedStr, inputString, settings.max_length);
    processedStr[settings.max_length] = '\0';

    if (settings.trim_and_capitalize) {
        trimAndCapitalize(processedStr);
    }

    pthread_mutex_unlock(&mutex);

    // Simulate handling API rate limits by introducing a delay
    // In real-world usage, handle retries and exponential backoff

    return processedStr;
}

int main() {
