            async with self.session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    print(f"Failed to fetch data from {url}, status code: {response.status}")
        except Exception as e:
            print(f"Error fetching stock data from {url}: {e}")

    async def fetch_news_data(self):
        try:
            async with self.session.get(NEWS_API_URL) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    print(f"Failed to fetch news data, status code: {response.status}")
        except Exception as e:
            print(f"Error fetching news data: {e}")

    async def process_stock_data(self):
        tasks = [self.fetch_stock_data(url) for url in STOCK_API_URLS]
        stock_data_list = await asyncio.gather(*tasks)

        # Process the aggregated stock data
        processed_data = self.aggregate_stock_data(stock_data_list)
        return processed_data

    async def stream_real_time_data(self):
        uri = "wss://stream.stockexchange.com"
        async with websockets.connect(uri) as websocket:
            try:
                while True:
                    message = await websocket.recv()
                    stock_update = json.loads(message)
                    # Process real-time data
                    self.handle_realtime_stock_data(stock_update)
            except Exception as e:
                print(f"Error in streaming real-time data: {e}")

    def aggregate_stock_data(self, stock_data_list):
        # Logic to aggregate and process stock data
        aggregated_data = {}
        for data in stock_data_list:
            if data:
                for symbol, details in data.items():
                    if symbol not in aggregated_data:
                        aggregated_data[symbol] = details
                    else:
                        # Merge or update the existing data for the symbol
                        aggregated_data[symbol].update(details)
        return aggregated_data

    def handle_realtime_stock_data(self, stock_update):
        # Handle and process real-time stock updates
        print(f"Real-time update: {stock_update}")

    async def main_loop(self):
        while True:
            await asyncio.gather(
                self.process_stock_data(),
                self.fetch_news_data(),
                self.stream_real_time_data()
            )
            await asyncio.sleep(5)  # Control the frequency of data processing

    def run(self):
        try:
            loop = asyncio.get_event_loop()
            loop.run_until_complete(self.main_loop())
        finally:
            self.session.close()

if __name__ == "__main__":
    tool = StockMarketAnalysisTool()
    tool.run()

