#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define log levels
typedef enum {
    DEBUG,
    INFO,
    ERROR
} LogLevel;

// Logging function prototype
void log_message(LogLevel level, const char *message);

// Connection structure definition
struct Connection {
    char *title;
    int is_established; // 1 if established, 0 otherwise
};

// Mutex for thread safety
pthread_mutex_t connection_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to validate and log the connection and password details
int validate_and_log(const char *password, const struct Connection *conn, void (*callback)(void)) {
    pthread_mutex_lock(&connection_mutex);

    if (password == NULL || strlen(password) == 0) {
        log_message(ERROR, "Password is empty or NULL.");
        pthread_mutex_unlock(&connection_mutex);
        return -1;
    }

    if (conn == NULL || conn->title == NULL || strlen(conn->title) == 0) {
        log_message(ERROR, "Connection title is invalid or empty.");
        pthread_mutex_unlock(&connection_mutex);
        return -2;
    }

    if (!conn->is_established) {
        log_message(ERROR, "Connection not established.");
        pthread_mutex_unlock(&connection_mutex);
        return -3;
    }

    if (callback == NULL || !((void(*)()) callback)) {
        log_message(ERROR, "Callback function is invalid.");
        pthread_mutex_unlock(&connection_mutex);
        return -4;
    }

    // If all checks pass
    log_message(INFO, "All validations passed successfully.");

    // Call the callback function as validation succeeded
    (*callback)();

    pthread_mutex_unlock(&connection_mutex);

    return 0; // Success code
}

// Logging interface stubs for demonstration purposes
void log_message(LogLevel level, const char *message) {
    switch (level) {
        case DEBUG:
            printf("[DEBUG] %s\n", message);
            break;
        case INFO:
            printf("[INFO] %s\n", message);
            break;
        case ERROR:
            printf("[ERROR] %s\n", message);
            break;
    }
}

// Example callback function
void example_callback() {
    printf("Callback function executed.\n");
}
```

