```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;
using System.Xml.Linq;
using System.Xml.XPath;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;

public class XmlElementFinder
{
    private readonly IMemoryCache _cache;
    private readonly IConfiguration _configuration;
    private static readonly TimeSpan CacheDuration = TimeSpan.FromMinutes(10);

    public XmlElementFinder(IMemoryCache cache, IConfiguration configuration)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _configuration = configuration ?? throw new ArgumentNullException(nameof(configuration));
    }

    public (XElement element, Dictionary<string, string> attributes) FindFirstElementWithAttributes(string elementName, string xpathNamespaceManagerKey = null)
    {
        var configPath = _configuration["XmlDocumentPath"];
        if (string.IsNullOrEmpty(configPath))
            throw new ConfigurationErrorsException("XML document path is not configured.");

        XElement xmlDocument;
        if (!_cache.TryGetValue(configPath, out xmlDocument))
        {
            var xmlDoc = XDocument.Load(configPath);
            xmlDocument = xmlDoc.Root ?? throw new XmlException("Root element not found.");
            _cache.Set(configPath, xmlDocument, CacheDuration);
        }

        var namespaceManager = CreateNamespaceManager(xpathNamespaceManagerKey);

        var elements = xmlDocument.XPathSelectElements($"//*[local-name()='{elementName}']", namespaceManager);

        if (elements.Count() == 0)
            throw new ElementNotFoundException($"No element with the name '{elementName}' found.");

        if (elements.Count() > 1)
            throw new MultipleElementsFoundException($"Multiple elements with the name '{elementName}' found.");

        var firstElement = elements.First();
        var attributes = firstElement.Attributes().ToDictionary(attr => attr.Name.LocalName, attr => attr.Value);

        return (firstElement, attributes);
    }

    private XmlNamespaceManager CreateNamespaceManager(string xpathNamespaceManagerKey)
    {
        var namespaces = _configuration.GetSection(xpathNamespaceManagerKey)?.GetChildren() ?? throw new ConfigurationErrorsException("Namespace configuration not found.");

        var namespaceManager = new XmlNamespaceManager(new NameTable());
        foreach (var ns in namespaces)
        {
            if (!string.IsNullOrEmpty(ns.Key) && !string.IsNullOrEmpty(ns.Value))
                namespaceManager.AddNamespace(ns.Key, ns.Value);
        }

        return namespaceManager;
    }
}

public class ElementNotFoundException : Exception
{
    public ElementNotFoundException(string message) : base(message) { }
}

public class MultipleElementsFoundException : Exception
{
    public MultipleElementsFoundException(string message) : base(message) { }
}
```

### Explanation:

1. **Configuration and Caching**: The function uses `IConfiguration` to load the XML document path from a configuration file and `IMemoryCache` for caching parsed documents.

2. **XPath Evaluation with Namespace Support**: It supports XPath queries that can handle namespaces using an optional key for namespace management.

3. **Exception Handling**: Custom exceptions are thrown when no elements or multiple elements are found, ensuring clear error messages.

4. **Resource Management**: Uses `IMemoryCache` to manage cached XML documents and automatically evicts entries after a specified duration.

5. **Modular Design**: The code is organized into separate classes for configuration, parsing, caching, and error handling, following best practices for maintainability.

