import json
import os
import importlib.util
from threading import Lock
from collections import defaultdict
import time

class JSONBase:
    _registry_lock = Lock()
    _factories = {}
    _last_accessed = defaultdict(lambda: time.time())

    @classmethod
    def to_json(cls, data):
        return json.dumps(data)

    @classmethod
    def from_json(cls, json_str):
        try:
            data = json.loads(json_str)
            factory_id = data.get('id')
            if factory_id in cls._factories:
                return cls._factories[factory_id](data)
            raise ValueError("Factory ID not found")
        except (json.JSONDecodeError, KeyError) as e:
            raise ValueError(f"Invalid JSON: {e}")

    @classmethod
    def register_factory(cls, factory_func):
        factory_id = factory_func.__name__

        with cls._registry_lock:
            cls._factories[factory_id] = factory_func
            cls._last_accessed[factory_id] = time.time()

        return factory_func

    @classmethod
    def get_registry(cls):
        with cls._registry_lock:
            # Clean up factories that haven't been accessed for 10 minutes
            current_time = time.time()
            to_remove = [fid for fid, last_access in cls._last_accessed.items() if (current_time - last_access) > 600]
            for fid in to_remove:
                del cls._factories[fid]
                del cls._last_accessed[fid]

        return cls._factories

    @classmethod
    def discover_subclasses(cls, directory):
        with cls._registry_lock:
            for filename in os.listdir(directory):
                if filename.endswith('.py') and not filename.startswith('__'):
                    module_name = filename[:-3]
                    file_path = os.path.join(directory, filename)

                    spec = importlib.util.spec_from_file_location(module_name, file_path)
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)

                    for name in dir(module):
                        obj = getattr(module, name)
                        if isinstance(obj, type) and issubclass(obj, JSONBase) and obj is not JSONBase:
                            cls.register_factory(obj)

    @classmethod
    def save_registry(cls, filepath):
        with cls._registry_lock:
            with open(filepath, 'w') as f:
                json.dump(list(cls._factories.keys()), f)

    @classmethod
    def load_registry(cls, filepath):
        with cls._registry_lock:
            if os.path.exists(filepath):
                with open(filepath, 'r') as f:
                    factory_ids = json.load(f)

                # Reload factories based on their IDs
                for fid in factory_ids:
                    try:
                        module_name, class_name = fid.rsplit('.', 1)
                        module = importlib.import_module(module_name)
                        cls.register_factory(getattr(module, class_name))
                    except (ImportError, AttributeError):
                        continue

# Example subclass registration and usage
class CustomClass(JSONBase):
    def __init__(self, data):
        self.data = data

@JSONBase.register_factory
def create_custom_instance(data):
    return CustomClass(data)

# Usage example
if __name__ == "__main__":
    JSONBase.discover_subclasses(directory='subclasses')
    registry = JSONBase.get_registry()

    # Example JSON string
    json_str = '{"id": "create_custom_instance", "data": {"key": "value"}}'
    instance = JSONBase.from_json(json_str)
    print(instance.data)

    # Save and load registry state
    JSONBase.save_registry('registry.json')
    JSONBase.load_registry('registry.json')
