// Mock function to simulate fetching words from an external source.
int fetchWordsToTrim(char ***wordList) {
    // Example word list for trimming.
    *wordList = malloc(2 * sizeof(char *));
    if (*wordList == NULL) return -1;

    (*wordList)[0] = strdup("example");
    (*wordList)[1] = strdup("test");

    return 2; // Number of words fetched.
}

char* dynamicTrimAndCapitalize(const char *input, int maxConcurrentRequests) {
    if (input == NULL) {
        fprintf(stderr, "Invalid input pointer\n");
        return NULL;
    }

    char **wordList = NULL;
    int wordCount = fetchWordsToTrim(&wordList);
    if (wordCount < 0) {
        fprintf(stderr, "Failed to fetch words for trimming\n");
        return NULL;
    }

    size_t avgWordLength = 0;
    for (int i = 0; i < wordCount; ++i) {
        avgWordLength += strlen(wordList[i]);
    }
    avgWordLength /= wordCount;

    int adjustedSizeLimit = strlen(input) / 2 + avgWordLength * wordCount;

    // Trim words from input
    char *trimmedInput = strdup(input);
    if (trimmedInput == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        for (int i = 0; i < wordCount; ++i) {
            free(wordList[i]);
        }
        free(wordList);
        return NULL;
    }

    char *startPtr = trimmedInput;
    for (int i = 0; i < wordCount; ++i) {
        if (strncmp(startPtr, wordList[i], strlen(wordList[i])) == 0) {
            startPtr += strlen(wordList[i]);
        }
    }

    char *endPtr = startPtr + strlen(startPtr);
    for (int i = 0; i < wordCount; ++i) {
        if (strncmp(endPtr - strlen(wordList[i]), wordList[i], strlen(wordList[i])) == 0) {
            endPtr -= strlen(wordList[i]);
        }
    }

    char *result = strndup(startPtr, endPtr - startPtr + 1);
    for (int i = 0; i < wordCount; ++i) {
        free(wordList[i]);
    }
    free(wordList);

    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(trimmedInput);
        return NULL;
    }

    // Capitalize first letter of each word
    for (char *p = result; *p; ++p) {
        if (*p == ' ') {
            if (*(p + 1)) *(p + 1) = toupper(*(p + 1));
        } else {
            *p = toupper(*p);
        }
    }

    // Check length limit
    if (strlen(result) > adjustedSizeLimit) {
        free(result);
        free(trimmedInput);
        return NULL;
    }

    free(trimmedInput);
    return result;
}
