const fetch = require('node-fetch');
const Semaphore = require('async-mutex').Semaphore;

async function asyncArrayReduce(array, initialValue, callback, options) {
    const { concurrencyLimit = 5, timeout = 5000 } = options || {};
    let semaphore = new Semaphore(concurrencyLimit);
    let accumulatedValue = initialValue;
    let completedOperations = 0;

    const progressCallback = (completed, currentAccumulated) => {
        console.log(`Completed: ${completed}, Current Accumulated Value: ${currentAccumulated}`);
    };

    async function reduceWithSemaphore(index) {
        if (index >= array.length) return accumulatedValue;

        const release = await semaphore.acquire();
        try {
            const startTime = Date.now();

            while ((Date.now() - startTime) < timeout) {
                try {
                    accumulatedValue = await callback(accumulatedValue, array[index], index);
                    completedOperations++;
                    progressCallback(completedOperations, accumulatedValue);
                    break;
                } catch (error) {
                    console.error(`Error at index ${index}:`, error);
                    throw error;
                }
            }

            return reduceWithSemaphore(index + 1);
        } finally {
            release();
        }
    }

    try {
        return await reduceWithSemaphore(0);
    } catch (error) {
        console.error('Reduction failed:', error);
        throw error;
    }
}

// Example usage:
async function exampleCallback(acc, value, index) {
    // Simulate API call with delay
    await new Promise(resolve => setTimeout(resolve, 100));
    return acc + value; // Simple sum reduction for demonstration.
}

(async () => {
    try {
        const result = await asyncArrayReduce([1, 2, 3, 4], 0, exampleCallback, { concurrencyLimit: 2 });
        console.log('Final Result:', result);
    } catch (error) {
        console.error('Error during reduction:', error);
    }
})();
