// configLoader.js
export async function loadConfig(configUrl) {
  const response = await fetch(configUrl);
  if (!response.ok) throw new Error(`Failed to load configuration: ${response.statusText}`);
  return await response.json();
}

// fileLoader.js
export class FileLoader {
  constructor(config, cacheBuster) {
    this.config = config;
    this.cacheBuster = cacheBuster;
    this.fileMap = new Map();
  }

  async loadFile(filePath) {
    if (this.fileMap.has(filePath)) return this.fileMap.get(filePath);

    const url = `${filePath}?${this.cacheBuster}`;
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`Failed to load file: ${filePath}`);

      const script = document.createElement('script');
      script.src = url;
      script.async = true;
      document.head.appendChild(script);

      return new Promise((resolve, reject) => {
        script.onload = () => resolve(url);
        script.onerror = () => reject(new Error(`Failed to execute file: ${filePath}`));
      });
    } catch (error) {
      console.error(error.message);
      throw error;
    }
  }

  async loadFiles(files) {
    for (const file of files) {
      try {
        await this.loadFile(file);
        this.fileMap.set(file, true); // Mark as loaded
      } catch (err) {
        console.warn(`Error loading ${file}: ${err.message}`);
      }
    }
  }

  async loadWithDependencies(files) {
    const orderedFiles = orderFilesByDependency(this.config.dependencies || {}, files);

    for (const file of orderedFiles) {
      await this.loadFiles([file]);
    }
  }
}

function orderFilesByDependency(dependencies, files) {
  let sortedFiles = [];
  const visited = new Set();

  function visit(file) {
    if (!visited.has(file)) {
      dependencies[file] && dependencies[file].forEach(visit);
      visited.add(file);
      sortedFiles.push(file);
    }
  }

  files.forEach(visit);
  return sortedFiles;
}

// hotReloader.js
export class HotReloader {
  constructor(fileLoader) {
    this.fileLoader = fileLoader;
    if (process.env.NODE_ENV === 'development') {
      this.setupHotReload();
    }
  }

  setupHotReload() {
    const script = document.createElement('script');
    script.src = '/hot-reload.js'; // Assume hot-reload.js handles websocket or polling
    document.head.appendChild(script);

    window.addEventListener('message', (event) => {
      if (event.data.type === 'reload') {
        this.fileLoader.loadWithDependencies(event.data.files).catch(console.error);
      }
    });
  }
}

// main.js
import { loadConfig } from './configLoader.js';
import { FileLoader } from './fileLoader.js';
import { HotReloader } from './hotReloader.js';

const environment = process.env.NODE_ENV || 'development';
const cacheBuster = Date.now();

async function initialize(configUrl) {
  try {
    const config = await loadConfig(configUrl);

    if (environment === 'production') {
      console.log('Running in production mode.');
      // Disable hot-reloading and other development features
    }

    const fileLoader = new FileLoader(config, cacheBuster);
    await fileLoader.loadWithDependencies(config.files);

    new HotReloader(fileLoader);

    console.log('All files loaded successfully.');

  } catch (error) {
    console.error(`Initialization failed: ${error.message}`);
    alert(`Error loading resources. Please try again later.`);
  }
}

// Start the application with a configuration URL
initialize('/path/to/config.json');
