def rate_limited(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        user_ip = request.remote_addr
        if not check_rate_limit(user_ip):
            return jsonify({'error': 'Rate limit exceeded'}), 429
        response = func(*args, **kwargs)
        update_rate_limit(user_ip)
        return response
    return wrapper

def check_rate_limit(user_ip):
    now = datetime.now()
    requests_info = rate_limit_cache.get(user_ip, [])
    requests_info = [req for req in requests_info if req > now - timedelta(minutes=1)]
    rate_limit_cache[user_ip] = requests_info

    return len(requests_info) < RATE_LIMIT

def update_rate_limit(user_ip):
    now = datetime.now()
    if user_ip not in rate_limit_cache:
        rate_limit_cache[user_ip] = []
    rate_limit_cache[user_ip].append(now)

