<?php

function handleUserRequest() {
    header('Content-Type: application/json');

    // Rate limiting setup (simple in-memory example)
    session_start();
    $rateLimit = 5;  // Max requests per minute
    $currentTime = time();

    if (!isset($_SESSION['requests'])) {
        $_SESSION['requests'] = [];
    }

    $_SESSION['requests'] = array_filter(
        $_SESSION['requests'],
        function($timestamp) use ($currentTime) {
            return ($timestamp > $currentTime - 60);
        }
    );

    if (count($_SESSION['requests']) >= $rateLimit) {
        echo json_encode(['message' => 'error', 'reason' => 'Rate limit exceeded']);
        exit;
    }

    array_push($_SESSION['requests'], $currentTime);

    // Logging setup
    $logFile = 'user_request.log';

    function logRequest($status, $details = '') {
        global $logFile;
        $entry = sprintf("[%s] %s - %s\n", date('Y-m-d H:i:s'), $status, $details);
        file_put_contents($logFile, $entry, FILE_APPEND);
    }

    // Database connection
    $dsn = 'mysql:host=localhost;dbname=your_database';
    $username = 'your_username';
    $password = 'your_password';

    try {
        $pdo = new PDO($dsn, $username, $password, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC
        ]);

        // Extract request data
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'] ?? '';
        $email = $_REQUEST['email'] ?? '';
        $password = $_REQUEST['password'] ?? '';
        $confirmPassword = $_REQUEST['confirm_password'] ?? '';

        // Validate request
        if (empty($name) || empty($email) || empty($password)) {
            logRequest('ERROR', 'Missing name, email or password');
            echo json_encode(['message' => 'error', 'reason' => 'Missing fields']);
            exit;
        }

        if ($password !== $confirmPassword) {
            logRequest('ERROR', 'Passwords do not match');
            echo json_encode(['message' => 'error', 'reason' => 'Passwords do not match']);
            exit;
        }

        // Sub-action for delete
        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
            if ($id) {
                $stmt = $pdo->prepare('DELETE FROM users WHERE id = :id');
                $result = $stmt->execute([':id' => $id]);

                if ($result) {
                    logRequest('SUCCESS', "Deleted user with ID $id");
                    echo json_encode(['message' => 'success']);
                } else {
                    logRequest('ERROR', "Failed to delete user with ID $id");
                    echo json_encode(['message' => 'error', 'reason' => 'Delete operation failed']);
                }
            } else {
                logRequest('ERROR', 'ID missing for delete action');
                echo json_encode(['message' => 'error', 'reason' => 'Missing ID for deletion']);
            }
            exit;
        }

        // Check if email already exists
        $stmt = $pdo->prepare('SELECT COUNT(*) FROM users WHERE email = :email AND id != :id');
        $stmt->execute([':email' => $email, ':id' => $id]);
        if ($stmt->fetchColumn() > 0) {
            logRequest('ERROR', 'Email already exists');
            echo json_encode(['message' => 'error', 'reason' => 'Email already in use']);
            exit;
        }

        // Create or update user
        if ($id) {
            $stmt = $pdo->prepare(
                'UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id'
            );
            $result = $stmt->execute([':name' => $name, ':email' => $email, ':password' => password_hash($password, PASSWORD_DEFAULT), ':id' => $id]);

            if ($result) {
                logRequest('SUCCESS', "Updated user with ID $id");
                echo json_encode(['message' => 'success']);
            } else {
                logRequest('ERROR', "Failed to update user with ID $id");
                echo json_encode(['message' => 'error', 'reason' => 'Update operation failed']);
            }
        } else {
            $stmt = $pdo->prepare(
                'INSERT INTO users (name, email, password) VALUES (:name, :email, :password)'
            );
            $result = $stmt->execute([
                ':name' => $name,
                ':email' => $email,
                ':password' => password_hash($password, PASSWORD_DEFAULT)
            ]);

            if ($result) {
                logRequest('SUCCESS', "Created new user with email $email");
                echo json_encode(['message' => 'success']);
            } else {
                logRequest('ERROR', 'Failed to create new user');
                echo json_encode(['message' => 'error', 'reason' => 'Creation operation failed']);
            }
        }

    } catch (PDOException $e) {
        logRequest('EXCEPTION', $e->getMessage());
        http_response_code(500);
        echo json_encode(['message' => 'error', 'reason' => 'Database connection error']);
    }
}
