namespace ConfigurationManagerApp
{
    public interface IConfigurationLoader
    {
        (int TileSize, int WorldWidth, int WorldHeight, double CameraSpeed) LoadConfiguration(string[] xmlFiles);
    }

    public class XmlConfigurationLoader : IConfigurationLoader
    {
        public (int TileSize, int WorldWidth, int WorldHeight, double CameraSpeed) LoadConfiguration(string[] xmlFiles)
        {
            var config = new Dictionary<string, string>();
            foreach (var file in xmlFiles)
            {
                try
                {
                    var doc = XDocument.Load(file);
                    foreach (var element in doc.Root.Elements())
                    {
                        config[element.Name.LocalName] = element.Value;
                    }
                }
                catch (Exception ex)
                {
                    Log($"Error loading {file}: {ex.Message}");
                }
            }

            return (
                int.Parse(config["TileSize"] ?? "32"),
                int.Parse(config["WorldWidth"] ?? "1000"),
                int.Parse(config["WorldHeight"] ?? "600"),
                double.Parse(config["CameraSpeed"] ?? "1.5")
            );
        }
    }

    public class ConfigurationService
    {
        private readonly IConfigurationLoader _configLoader;

        public ConfigurationService(IConfigurationLoader configLoader)
        {
            _configLoader = configLoader;
        }

        public void Initialize(string[] xmlFiles)
        {
            var (tileSize, worldWidth, worldHeight, cameraSpeed) = _configLoader.LoadConfiguration(xmlFiles);
            // Use these settings as needed
            Log($"Loaded settings - Tile Size: {tileSize}, World Width: {worldWidth}, World Height: {worldHeight}, Camera Speed: {cameraSpeed}");
        }

        private void Log(string message)
        {
            Console.WriteLine($"{DateTime.Now}: {message}");
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var serviceProvider = new ServiceCollection()
                .AddSingleton<IConfigurationLoader, XmlConfigurationLoader>()
                .BuildServiceProvider();

            var configService = new ConfigurationService(serviceProvider.GetService<IConfigurationLoader>());
            configService.Initialize(new string[] { "config1.xml", "config2.xml" });
        }
    }
}
