use std::env;
use std::fs;
use std::path::Path;
use log::{info, error};

fn create_directory_with_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var = "MY_CUSTOM_DIR";

    if let Ok(path) = env::var(env_var) {
        info!("Environment variable '{}' is already set to '{}'", env_var, path);
    } else {
        match Path::new(dir_name).exists() {
            true => error!("Directory '{}' already exists!", dir_name),
            false => {
                fs::create_dir_all(dir_name)?;
                if let Err(e) = env::set_var(env_var, dir_name) {
                    return Err(Box::new(e));
                }
                info!("Created directory '{}' and set environment variable '{}'", dir_name, env_var);
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::env;

    #[test]
    fn test_create_directory_with_env_var() {
        let dir_name = "test_dir";

        create_directory_with_env_var(dir_name).unwrap();

        if Path::new(&dir_name).exists() {
            fs::remove_dir_all(dir_name).unwrap();
        }

        assert_eq!(env::var("MY_CUSTOM_DIR").ok(), Some(dir_name.to_string()));
    }
}
