```javascript
angular.module('app').controller('DialogController', ['$scope', '$http', '$timeout', function($scope, $http, $timeout) {
  const cache = {};
  const refreshPageSize = 100;

  // Function to send message to parent window
  function sendMessageToParent(field, status) {
    if (window.parent && typeof window.parent.postMessage === 'function') {
      window.parent.postMessage({ field: field, status: status }, '*');
    }
  }

  // Function to handle data refresh for a single field
  function refreshField(field, url) {
    const cacheKey = `${field}-${url}`;

    if (cache[cacheKey] && Date.now() - cache[cacheKey].timestamp < 60000) { // Cache expiry of 1 minute
      $scope[field] = cache[cacheKey].data;
      sendMessageToParent(field, 'success');
      return;
    }

    let page = 0;

    function fetchPage() {
      const paginatedUrl = `${url}?page=${page}&pageSize=${refreshPageSize}`;

      $http.get(paginatedUrl)
        .then(response => {
          // Assuming the API returns data in response.data.items
          if (!cache[cacheKey]) cache[cacheKey] = { data: [] };

          cache[cacheKey].data = cache[cacheKey].data.concat(response.data.items);
          page += 1;

          if (response.data.items.length < refreshPageSize) {
            $scope[field] = cache[cacheKey].data;
            sendMessageToParent(field, 'success');
            return;
          }

          fetchPage();
        })
        .catch(error => {
          console.error(`Error refreshing field ${field}:`, error);
          sendMessageToParent(field, 'failure');
        });
    }

    fetchPage();
  }

  // Main function to refresh multiple fields
  $scope.refreshFields = function(resourceId, urlMap, fieldNames) {
    const logRefreshAttempt = (message) => console.log(`[${new Date().toISOString()}] ${message}`);

    fieldNames.forEach(fieldName => {
      if ($scope.dialogFields && $scope.dialogFields[fieldName]) {
        const fieldUrl = urlMap[fieldName];
        logRefreshAttempt(`Attempting to refresh field: ${fieldName} with URL: ${fieldUrl}`);

        sendMessageToParent(fieldName, 'refreshing');

        // Handle concurrent refresh requests using $q.defer
        let defer = $q.defer();

        (function recursiveRefresh() {
          refreshField(fieldName, fieldUrl).finally(() => {
            if (!defer.promise.$$state.status) {
              defer.resolve(); // Resolve when complete
            }
          });
        })();

        defer.promise.finally(() => logRefreshAttempt(`Finished refreshing field: ${fieldName}`));
      }
    });
  };
}]);
