function asyncReduce(arr, initialValue, callback, options = {}) {
  const { concurrencyLimit = 5 } = options;

  // Convert all string numbers to integers and filter out non-numeric values
  arr = arr.map(item => Number.isInteger(Number(item)) ? parseInt(item) : null).filter(num => num !== null);

  let index = 0;
  let activePromises = [];
  let result = initialValue;
  const resultsCache = new Map();

  // Function to process a single batch of elements
  async function processBatch() {
    while (index < arr.length && activePromises.length < concurrencyLimit) {
      const currentIndex = index++;

      if (resultsCache.has(currentIndex)) {
        result = resultsCache.get(currentIndex);
        console.log(`Progress: ${currentIndex + 1}/${arr.length}`);
        continue;
      }

      try {
        // Create a promise for the current operation
        const promise = new Promise((resolve, reject) => {
          try {
            result = callback(result, arr[currentIndex]);
            resultsCache.set(currentIndex, result);
            console.log(`Processed index ${currentIndex}, current result: ${result}`);
            resolve();
          } catch (error) {
            console.error(`Error processing index ${currentIndex}:`, error.message);
            reject(error);
          }
        });

        activePromises.push(promise.then(() => activePromises.shift()).catch(err => err));
      }
    }

    if (activePromises.length > 0) {
      await Promise.race(activePromises).then(processBatch).catch(console.error);
    } else {
      console.log('Reduction completed.');
    }
  }

  return processBatch().then(() => result).catch(error => {
    console.error('Error during reduction:', error.message);
    throw error;
  });
}

// Example usage:
asyncReduce(
  [1, '2', '3', 4, '5'],
  0,
  (acc, num) => acc + num,
  { concurrencyLimit: 3 }
).then(finalResult => console.log('Final Result:', finalResult))
  .catch(error => console.error('Error in asyncReduce:', error.message));

// Test cases:
function testAsyncReduce() {
  // Edge case: Empty array
  asyncReduce([], 0, (acc, num) => acc + num)
    .then(result => console.assert(result === 0, 'Test failed for empty array'));

  // Edge case: Array with non-numeric values
  asyncReduce([1, 'a', 3, 'b'], 0, (acc, num) => acc + num)
    .then(result => console.assert(result === 4, 'Test failed for non-numeric values'));

  // Large numbers handling
  const largeNumArray = [Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER];
  asyncReduce(largeNumArray, 0, (acc, num) => acc + num)
    .then(result => console.assert(result === Number.MAX_SAFE_INTEGER * 2, 'Test failed for large numbers'));

  // Performance and concurrency test
  const bigArray = Array.from({ length: 10000 }, (_, i) => i);
  asyncReduce(bigArray, 0, (acc, num) => acc + num, { concurrencyLimit: 10 })
    .then(result => console.assert(result === bigArray.reduce((a, b) => a + b), 'Test failed for large array performance'));
}

// Run tests
testAsyncReduce();
