const axios = require('axios');
const AWS = require('aws-sdk');
const stream = require('stream');
const { promisify } = require('util');
const pipeline = promisify(stream.pipeline);
const logger = require('./logger'); // Assuming a custom logger module
const s3Client = new AWS.S3({
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
});

async function uploadFileFromUrl(url, bucketName, keyPrefix) {
  const MAX_RETRIES = 3;
  let attempt = 0;

  while (attempt < MAX_RETRIES) {
    try {
      // Validate URL
      const response = await axios.head(url, { timeout: 5000 });
      if (!['application/pdf', 'image/jpeg', 'image/png'].includes(response.headers['content-type'])) {
        throw new Error('Unsupported file type');
      }

      // Fetch the file as a stream
      const fileStream = axios({
        url,
        responseType: 'stream',
        timeout: 5000,
      }).then(res => res.data);

      // Calculate optimal chunk size and other parameters for uploading
      let fileSize;
      await new Promise((resolve, reject) => {
        response.data.on('response', (res) => {
          fileSize = parseInt(res.headers['content-length'], 10);
          resolve();
        });
      });

      const parallelUploads = Math.min(5, Math.floor(1024 * 1024 * 50 / fileSize)); // Up to 5 uploads or based on file size
      const chunkSize = Math.ceil(fileSize / parallelUploads);

      // Upload the file in chunks using S3 multipart upload
      const multiPartUpload = await s3Client.createMultipartUpload({
        Bucket: bucketName,
        Key: `${keyPrefix}/${Date.now()}`,
      }).promise();

      const uploadPromises = [];

      for (let i = 0; i < parallelUploads; i++) {
        const start = i * chunkSize;
        const end = Math.min(start + chunkSize - 1, fileSize - 1);

        const partNumber = i + 1;

        uploadPromises.push(
          new Promise((resolve, reject) => {
            fileStream
              .pipe(stream.PassThrough({ highWaterMark: chunkSize }))
              .on('error', reject)
              .on('end', async () => resolve(partNumber))
              .pipe(s3Client.uploadPart({
                Bucket: bucketName,
                Key: multiPartUpload.Key,
                PartNumber: partNumber,
                UploadId: multiPartUpload.UploadId,
                Body: fileStream,
                ContentRange: `bytes ${start}-${end}/${fileSize}`,
              }).promise())
              .then(data => {
                multiPartUpload.Parts.push({
                  ETag: data.ETag,
                  PartNumber: partNumber,
                });
                resolve(partNumber);
              })
              .catch(reject)
          })
        );
      }

      await Promise.all(uploadPromises);

      // Complete the multipart upload
      const completedMultiPart = await s3Client.completeMultipartUpload({
        Bucket: bucketName,
        Key: multiPartUpload.Key,
        UploadId: multiPartUpload.UploadId,
        MultipartUpload: {
          Parts: multiPartUpload.Parts,
        },
      }).promise();

      return `https://${bucketName}.s3.amazonaws.com/${completedMultiPart.Location}`;

    } catch (error) {
      logger.error(`Attempt ${attempt + 1} failed: ${error.message}`);
      attempt++;

      if (attempt >= MAX_RETRIES) {
        throw new Error('File upload failed after multiple attempts');
      }

      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000)); // Exponential backoff
    }
  }
}

module.exports = { uploadFileFromUrl };
```

This code provides a robust solution for uploading files from a URL to AWS S3. It handles multiple aspects such as authentication, chunked uploads, retry logic with exponential backoff, and error handling while maintaining performance optimization. Additionally, it uses external libraries like `axios` for HTTP requests, AWS SDK for JavaScript, and Node.js core modules for stream processing. The function returns a promise that resolves or rejects based on the success of the upload operation. Make sure to configure your environment variables (`AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`) before running this code in production.

