    return rsa;
}

// Callback function to handle password input securely
static int pem_password_cb(char *buf, int size, int rwflag, void *userdata) {
    if (size < 1)
        return 0; // Password must fit within buf and have at least 1 character.

    const char *password = userdata;
    strncpy(buf, password, size - 1);
    buf[size - 1] = '\0';
    return strlen(password);
}

// Function to clean up RSA context
void cleanup_rsa_context(RSA *rsa) {
    if (rsa) {
        RSA_free(rsa);
    }
}
