```python
import heapq
from typing import List

class MergeKSortedLists:
    def __init__(self):
        self.heaps = []

    def add_list(self, sorted_list: List[int]):
        """Add a new sorted list to be merged."""
        if not all(isinstance(x, int) for x in sorted_list):
            raise ValueError("All elements must be integers")
        if sorted_list != sorted(sorted_list):
            raise ValueError("Input list is not sorted")
        self.heaps.append((sorted_list[0], iter(sorted_list)))

    def remove_list(self, index: int):
        """Remove a sorted list by its index."""
        if 0 <= index < len(self.heaps):
            del self.heaps[index]
        else:
            raise IndexError("Index out of range")

    def merge(self) -> List[int]:
        """Merge all added lists into one sorted list."""
        result = []
        heap = []

        for value, iterator in self.heaps:
            heapq.heappush(heap, (value, next(iterator, None), iterator))

        while heap:
            smallest_value, next_value, iterator = heapq.heappop(heap)
            if next_value is not None:
                heapq.heappush(heap, (next_value, next(iterator, None), iterator))
            result.append(smallest_value)

        return result

    def throttle_merge(self):
        """Example of a throttled merging process to handle resource load."""
        # Implement logic for throttling based on system load.
        pass

def test_merge_k_sorted_lists():
    merger = MergeKSortedLists()

    try:
        merger.add_list([1, 3, 5])
        merger.add_list([2, 4, 6])
        merged_result = merger.merge()
        assert merged_result == [1, 2, 3, 4, 5, 6]

        merger.remove_list(0)
        merged_result = merger.merge()
        assert merged_result == [2, 4, 6]

        # Test with non-integer input
        try:
            merger.add_list([1.5, 2])
        except ValueError as e:
            assert str(e) == "All elements must be integers"

        # Test with unsorted list
        try:
            merger.add_list([3, 1, 2])
        except ValueError as e:
            assert str(e) == "Input list is not sorted"

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    test_merge_k_sorted_lists()
```

This code defines a class `MergeKSortedLists` that efficiently merges multiple sorted lists of integers using a min-heap. It supports dynamic addition and removal of lists, checks for integer-only inputs, ensures input lists are sorted, and includes unit tests to verify correctness. The code is modular and can be extended with throttling logic as needed.

