// index.js

const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const redis = require('redis');
const rateLimit = require('fastify-rate-limit');
const winston = require('winston');

const config = require('./config'); // Load configuration from a file or environment variables
const { processTextData } = require('./textProcessor');
const { getOldTestamentBooks } = require('./databaseService');

// Connect to MongoDB and Redis
mongoose.connect(config.mongoURI, { useNewUrlParser: true, useUnifiedTopology: true });
const redisClient = redis.createClient({ url: config.redisURL });

// Initialize Express app
const app = express();
app.use(bodyParser.json());
app.use(bodyParser.text({ type: 'text/xml' }));

// Set up logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'service.log' })
  ]
});

// Rate limiting
app.use(rateLimit(config.rateLimitOptions));

// Middleware to parse different input formats
app.post('/process', async (req, res) => {
  try {
    const { textData } = req.body;
    const cacheKey = `booksCount:${textData}`;

    redisClient.get(cacheKey, async (err, cachedResult) => {
      if (cachedResult) {
        return res.json(JSON.parse(cachedResult));
      }

      // Retrieve Old Testament books from database
      const oldTestamentBooks = await getOldTestamentBooks();

      // Process the text data to count book references
      const result = processTextData(textData, oldTestamentBooks);

      // Store result in cache for future requests
      redisClient.setex(cacheKey, config.cacheTTL, JSON.stringify(result));

      res.json(result);
    });
  } catch (error) {
    logger.error(`Error processing data: ${error.message}`);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});
