// textProcessor.js

const oldTestamentBooks = require('./oldTestamentBooks');

function normalizeText(text) {
  return text.replace(/[^a-zA-Z\s]/g, '').toLowerCase();
}

function processTextData(textData, booksList) {
  const normalizedText = normalizeText(textData);
  let bookCounts = {};

  booksList.forEach(book => {
    const regex = new RegExp(`\\b${book}\\b`, 'gi');
    const matches = (normalizedText.match(regex) || []).length;
    if (matches > 0) {
      bookCounts[book] = matches;
    }
  });

  return bookCounts;
}

module.exports = { processTextData };
```

