using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator : IEquatable<RandomValueGenerator>
{
    private float minValue;
    private float maxValue;
    private int callCount = 0;
    private const int MaxCallLimit = 10000; // Example limit

    public RandomValueGenerator(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        minValue = min;
        maxValue = max;

        LogGenerationEvent("RandomValueGenerator initialized.");
    }

    private void CheckCallLimit()
    {
        callCount++;
        if (callCount >= MaxCallLimit)
        {
            ResetCallCounter();
            throw new InvalidOperationException("Exceeded the maximum number of random value generations. Counter reset.");
        }
    }

    private void ResetCallCounter()
    {
        callCount = 0;
    }

    public float GenerateRandomFloatInclusive()
    {
        CheckCallLimit();
        LogGenerationEvent("Generated Random Float (inclusive)");
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomIntegerInclusive()
    {
        CheckCallCounter();
        LogGenerationEvent("Generated Random Integer (inclusive)");
        return Mathf.RoundToInt(UnityEngine.Random.Range(minValue, maxValue));
    }

    public float GenerateRandomFloatExclusive()
    {
        CheckCallLimit();
        LogGenerationEvent("Generated Random Float (exclusive)");
        return UnityEngine.Random.value * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomIntegerExclusive()
    {
        CheckCallCount();
        LogGenerationEvent("Generated Random Integer (exclusive)");
        float exclusiveMax = maxValue - 1e-5f; // Avoiding edge case of max value
        return Mathf.RoundToInt(UnityEngine.Random.Range(minValue, exclusiveMax));
    }

    public List<int> GenerateUniqueRandomIntegers(int n)
    {
        CheckCallCount();

        if (n > (int)(maxValue - minValue + 1))
            throw new ArgumentException("Requested number of unique integers exceeds the range size.");

        HashSet<int> uniqueNumbers = new HashSet<int>();
        while (uniqueNumbers.Count < n)
        {
            int randomNum = Mathf.RoundToInt(UnityEngine.Random.Range(minValue, maxValue));
            if (uniqueNumbers.Add(randomNum)) continue;

            LogGenerationEvent($"Duplicate detected: {randomNum}");
        }

        LogGenerationEvent("Generated list of unique random integers");
        return new List<int>(uniqueNumbers);
    }

    public override string ToString()
    {
        return $"Random Value Range: [{minValue}, {maxValue}]";
    }

    private void LogGenerationEvent(string message)
    {
        // Example integration with an external logging system.
        Debug.Log(message); // Placeholder for actual logging implementation
    }
}
