void manage_kv_store(const char *range_str, const char *keys_str) {
    if (!range_str || !keys_str) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    int range_min, range_max;
    sscanf(range_str, "%d-%d", &range_min, &range_max);

    char *key_list = strdup(keys_str);
    if (!key_list) {
        perror("Memory allocation failed for key list copy");
        return;
    }

    char *token = strtok(key_list, ",");
    int num_keys = 0;

    // Count the number of keys
    while (token) {
        token = strtok(NULL, ",");
        ++num_keys;
    }
    free(key_list);

    if (num_keys == 0 || num_keys > MAX_KEYS) {
        fprintf(stderr, "Invalid number of keys.\n");
        return;
    }

    key_list = malloc(num_keys * sizeof(char*));
    if (!key_list) {
        perror("Memory allocation failed for keys array");
        return;
    }

    key_list = strdup(keys_str);
    if (!key_list) {
        perror("Memory allocation failed for key list copy");
        free(key_list);
        return;
    }

    token = strtok(key_list, ",");
    int index = 0;

    // Populate the keys array
    while (token) {
        key_list[index++] = strdup(token);
        if (!key_list[index - 1]) {
            perror("Memory allocation failed for individual key");
            break;
        }
        token = strtok(NULL, ",");
    }

    free(key_list);

    Record *records = malloc(num_keys * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records array");
        for (int i = 0; i < index; ++i)
            free(key_list[i]);
        return;
    }

    // Assign values and offsets to the keys
    for (int i = 0; i < num_keys && i < index; ++i) {
        int value = rand() % (range_max - range_min + 1) + range_min;
        records[i].value = value;
        records[i].offset = (long)(rand());

        // Retry mechanism for transient failures
        int attempts = 0, max_attempts = 3;
        while (attempts < max_attempts && store_key_value(key_list[i], value)) {
            ++attempts;
        }

        if (attempts == max_attempts) {
            fprintf(stderr, "Failed to store key-value pair after %d attempts.\n", max_attempts);
        }
    }

    for (int i = 0; i < num_keys && i < index; ++i)
        free(key_list[i]);

    free(records);

    // Calculate MD5 hash of the comma-separated keys
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)keys_str, strlen(keys_str), md5_hash);
    char *md5_str = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!md5_str) {
        perror("Memory allocation failed for MD5 string");
        return;
    }

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(md5_str + (i * 2), "%02x", md5_hash[i]);

    printf("MD5 Hash: %s\n", md5_str);
    free(md5_str);
}
