using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Configuration;

public class SiteManager
{
    private static readonly object lockObject = new();
    private const int MaxRetryCount = 3;
    private const int RetryIntervalMilliseconds = 1000;

    public void AddAndStartSite(string directoryPath, string siteName)
    {
        if (!IsValidDirectory(directoryPath))
        {
            LogError("Invalid or inaccessible directory path.");
            throw new InvalidOperationException("The specified directory is invalid or not accessible.");
        }

        string webConfigFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFilePath))
        {
            LogError($"Web.config file missing in {directoryPath}");
            throw new FileNotFoundException("Web.config file does not exist in the specified directory.");
        }

        ValidateWebConfigFile(webConfigFilePath);

        string uniqueSiteName = EnsureUniqueSiteName(directoryPath, siteName);

        var siteSettings = GetSiteSettingsFromDatabase(uniqueSiteName) ?? new SiteSettings();

        int attempt = 0;
        bool startedSuccessfully = false;

        while (attempt < MaxRetryCount && !startedSuccessfully)
        {
            try
            {
                using (var process = StartSiteProcess(directoryPath, uniqueSiteName, siteSettings))
                {
                    if (process != null)
                    {
                        MonitorSiteHealth(process);
                        startedSuccessfully = true;
                    }
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to start site on attempt {attempt + 1}: {ex.Message}");
                Thread.Sleep(RetryIntervalMilliseconds);
            }

            attempt++;
        }

        if (!startedSuccessfully)
        {
            LogError("Failed to start the site after maximum retries.");
            throw new InvalidOperationException("Unable to start the website after several attempts.");
        }
    }

    private bool IsValidDirectory(string directoryPath)
    {
        try
        {
            return Directory.Exists(directoryPath) && HasPermissionToManageSites(directoryPath);
        }
        catch (Exception ex)
        {
            LogError($"Error validating directory: {ex.Message}");
            return false;
        }
    }

    private string EnsureUniqueSiteName(string directoryPath, string siteName)
    {
        lock (lockObject)
        {
            string uniqueName = siteName;
            int counter = 1;

            while (DoesSiteExist(directoryPath, uniqueName))
            {
                uniqueName = $"{siteName}_{counter++}";
            }

            return uniqueName;
        }
    }

    private SiteSettings GetSiteSettingsFromDatabase(string siteName)
    {
        try
        {
            // Simulated database call for demonstration.
            return new SiteSettings { PortNumber = 8080, StartupParameters = "-start" };
        }
        catch (Exception ex)
        {
            LogError($"Failed to retrieve settings from the database: {ex.Message}");
            return null;
        }
    }

    private Process StartSiteProcess(string directoryPath, string siteName, SiteSettings settings)
    {
        try
        {
            var processStartInfo = new ProcessStartInfo("cmd.exe", $"/C start ""{siteName}"" http://localhost:{settings.PortNumber}/")
            {
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
                WorkingDirectory = directoryPath
            };

            var process = new Process { StartInfo = processStartInfo };
            LogAction($"Starting site: {siteName}");
            return process.Start() ? process : null;
        }
        catch (Exception ex)
        {
            LogError($"Failed to start the site process: {ex.Message}");
            throw;
        }
    }

    private void MonitorSiteHealth(Process process)
    {
        try
        {
            while (!process.HasExited)
            {
                var cpuUsage = GetCpuUsage(process.Id);
                var memoryUsage = GetMemoryUsage(process);

                LogAction($"Monitoring site: CPU Usage={cpuUsage}%, Memory Usage={memoryUsage} MB");

                Thread.Sleep(5000); // Monitor every 5 seconds
            }
        }
        catch (Exception ex)
        {
            LogError($"Error monitoring site health: {ex.Message}");
        }
    }

    private void ValidateWebConfigFile(string filePath)
    {
        try
        {
            var content = File.ReadAllText(filePath);
            if (!IsValidXml(content))
            {
                throw new InvalidOperationException("Malformed web.config file.");
            }
        }
        catch (Exception ex)
        {
            LogError($"Validation failed for web.config: {ex.Message}");
            throw;
        }
    }

    private void LogAction(string message) => Console.WriteLine($"{DateTime.Now}: ACTION - {message}");

    private void LogError(string message) => Console.WriteLine($"{DateTime.Now}: ERROR - {message}");

    // Placeholder methods
    private bool HasPermissionToManageSites(string directoryPath) => true;
    private bool DoesSiteExist(string directoryPath, string siteName) => false;
    private float GetCpuUsage(int processId) => 0.5f; // Placeholder value
    private long GetMemoryUsage(Process process) => 100; // Placeholder value
    private bool IsValidXml(string xmlContent) => true;

    class SiteSettings
    {
        public int PortNumber { get; set; }
        public string StartupParameters { get; set; }
    }
}
