// Configuration structure
struct Config {
    std::string apiKey;
    std::string apiEndpoint;
};

// CacheManager class definition
class CacheManager {
public:
    bool getFromCache(const std::string& key, std::string& value);
    void addToCache(const std::string& key, const std::string& value);

private:
    std::unordered_map<std::string, std::string> cache;
};

// Test double for CacheManager
class MockCacheManager : public CacheManager {
public:
    bool getFromCache(const std::string& key, std::string& value) override {
        if (key == "mock_key") {
            value = "cached_data";
            return true; // Simulate cache hit
        }
        return false; // Simulate cache miss
    }

    void addToCache(const std::string& key, const std::string& value) override {}
};

// Function to read configuration from file
Config readConfig(const std::string& configFile) {
    Config config;
    std::ifstream file(configFile);
    if (file.is_open()) {
        std::getline(file, config.apiKey);
        std::getline(file, config.apiEndpoint);
    }
    return config;
}

// Callback function for cURL
size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Fetch weather data from API or cache
bool fetchWeatherData(const Config& config, const std::string& coordinates, CacheManager& cacheManager, 
                      int& requestCount, int& cacheHitCount, int& timeoutCount) {
    std::string cacheKey = "weather_" + coordinates;
    std::string response;

    if (cacheManager.getFromCache(cacheKey, response)) {
        ++cacheHitCount;
        std::cout << "Weather data from cache: " << response << std::endl;
        return true;
    }

    CURL* curl;
    CURLcode res;
    requestCount++;

    curl = curl_easy_init();
    if(curl) {
        std::string url = config.apiEndpoint + "?lat=" + coordinates + "&appid=" + config.apiKey;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        struct curl_slist* headers = nullptr;
        headers = curl_slist_append(headers, "User-Agent: MyWeatherApp/1.0");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);

        res = curl_easy_perform(curl);

        if (res == CURLE_OPERATION_TIMEDOUT) {
            ++timeoutCount;
            std::cout << "Network timeout occurred." << std::endl;
        } else if (res == CURLE_OK) {
            cacheManager.addToCache(cacheKey, response);
            std::cout << "Weather data from API: " << response << std::endl;
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    return res == CURLE_OK;
}

// Main function
int main() {
    Config config = readConfig("config.txt");
    MockCacheManager mockCacheManager;

    int requestCount = 0, cacheHitCount = 0, timeoutCount = 0;

    fetchWeatherData(config, "40.7128,-74.0060", mockCacheManager, requestCount, cacheHitCount, timeoutCount);

    std::cout << "Requests made: " << requestCount << ", Cache hits: " << cacheHitCount << ", Timeouts: " << timeoutCount << std::endl;

    return 0;
}
