// Function to encode data into base64 (simple implementation)
void base64Encode(const unsigned char *data, size_t input_length, char *output) {
    static const char encoding_table[] = 
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    size_t i = 0;
    size_t j = 0;
    unsigned char char_array_3[3];
    unsigned char char_array_4[4];

    while (input_length--) {
        char_array_3[i++] = *(data++);
        if (i == 3) {
            char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
            char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
            char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
            char_array_4[3] = char_array_3[2] & 0x3f;

            for(i = 0; (i <4) ; i++)
                output[j++] = encoding_table[char_array_4[i]];
            i = 0;
        }
    }

    if (i) {
        for(j = i; j < 3; j++)
            char_array_3[j] = '\0';

        char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
        char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
        char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);

        for (j = 0; (j < i + 1); j++)
            output[j++] = encoding_table[char_array_4[j]];

        while((i++ < 3))
            output[j++] = '=';
    }

    output[j] = '\0';
}

FilteredTransactionResult filterAndAuthenticateTransactions(TransactionRequest request) {
    // Step 1: Authenticate the user using OAuth 2.0 client
    const char* oauthClient = authenticate(request.client_id, request.client_secret);
    if (oauthClient == NULL) {
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    // Step 2: Update session with the access token
    globalSessionAccessToken = strdup(oauthClient);

    // Step 3: Filter transactions based on criteria
    FilteredTransactionResult result = filterTransactions(request.transactionAge, request.transactionCountLast3Seconds, request.weightedSum);

    // Step 4: Combine the private key and certificate into a single PEM file
    FILE *privateKeyFile = fopen(result.privateKeyPath, "r");
    FILE *certificateFile = fopen(result.certificatePath, "r");

    if (privateKeyFile == NULL || certificateFile == NULL) {
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    fseek(privateKeyFile, 0, SEEK_END);
    long privateKeySize = ftell(privateKeyFile);
    fseek(privateKeyFile, 0, SEEK_SET);

    fseek(certificateFile, 0, SEEK_END);
    long certificateSize = ftell(certificateFile);
    fseek(certificateFile, 0, SEEK_SET);

    char *combinedData = malloc((size_t)privateKeySize + certificateSize + 2); // +2 for new line and null terminator
    if (!combinedData) {
        fclose(privateKeyFile);
        fclose(certificateFile);
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    fread(combinedData, (size_t)privateKeySize, 1, privateKeyFile);
    combinedData[privateKeySize] = '\n';
    fread(&combinedData[privateKeySize + 1], certificateSize, 1, certificateFile);
    combinedData[privateKeySize + 1 + certificateSize] = '\0';

    fclose(privateKeyFile);
    fclose(certificateFile);

    // Step 5: Encode the combined PEM data into base64
    size_t encodedLength = ((strlen(combinedData) * 4) / 3) + 4; // Calculate buffer size for base64 encoding
    char *encodedPem = malloc(encodedLength);
    if (!encodedPem) {
        free(combinedData);
        return (FilteredTransactionResult){NULL, -1, NULL};
    }

    base64Encode((unsigned char *)combinedData, strlen(combinedData), encodedPem);

    // Clean up
    free(combinedData);

    // Step 6: Return the result with maximum weighted sum and transaction ID
    FilteredTransactionResult finalResult = {encodedPem, (int)result.maxWeightedSum, strdup(result.transactionId)};
    return finalResult;
}
