using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class AsyncDataCopier
{
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> _cache = new();
    private readonly SemaphoreSlim _semaphore;
    private readonly int _maxConcurrentDecryptions;

    public AsyncDataCopier(int maxConcurrentDecryptions)
    {
        _maxConcurrentDecryptions = maxConcurrentDecryptions;
        _semaphore = new SemaphoreSlim(_maxConcurrentDecryptions);
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        await _semaphore.WaitAsync();
        try
        {
            return await RetryPolicy(async () => 
                (await FetchKeysAndIv(contextId)).Decrypt(base64EncodedMessage));
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
        using (_semaphore.Wait())
        {
            return Retry(() => 
                (FetchKeysAndIv(contextId)).Decrypt(base64EncodedMessage));
        }
    }

    private async Task<(byte[] Key, byte[] IV)> FetchKeysAndIv(string contextId)
    {
        if (_cache.TryGetValue(contextId, out var cached))
        {
            return cached;
        }

        // Simulate CSP API call to fetch keys and IVs
        (byte[] key, byte[] iv) = await GetKeyAndIVFromCspAsync(contextId);

        _cache.TryAdd(contextId, (key, iv));
        return (key, iv);
    }

    private async Task<(byte[] Key, byte[] IV)> GetKeyAndIVFromCspAsync(string contextId)
    {
        // Simulate delay for fetching from CSP
        await Task.Delay(100);

        // Example keys and IVs generation
        using var tripleDes = new TripleDESCryptoServiceProvider();
        return (tripleDes.Key, tripleDes.IV);
    }

    private string Decrypt(byte[] key, byte[] iv, string base64EncodedMessage)
    {
        var cipherTextBytes = Convert.FromBase64String(base64EncodedMessage);

        using var tripleDes = new TripleDESCryptoServiceProvider
        {
            Key = key,
            IV = iv
        };

        using var decryptor = tripleDes.CreateDecryptor();
        using var ms = new MemoryStream(cipherTextBytes);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        using var sr = new StreamReader(cs);
        return sr.ReadToEnd();
    }

    private async Task<string> RetryPolicy(Func<Task<string>> operation)
    {
        int retries = 3;
        double delay = 200; // initial delay in milliseconds
        for (int i = 0; i < retries; i++)
        {
            try
            {
                return await operation();
            }
            catch (Exception ex) when (i < retries - 1)
            {
                await Task.Delay((int)(delay * Math.Pow(2, i)));
            }
        }
        throw new InvalidOperationException("Max retry attempts exceeded.");
    }

    private string Retry(Func<string> operation)
    {
        int retries = 3;
        double delay = 200; // initial delay in milliseconds
        for (int i = 0; i < retries; i++)
        {
            try
            {
                return operation();
            }
            catch (Exception ex) when (i < retries - 1)
            {
                Thread.Sleep((int)(delay * Math.Pow(2, i)));
            }
        }
        throw new InvalidOperationException("Max retry attempts exceeded.");
    }

    private struct CachedKeyInfo
    {
        public byte[] Key;
        public byte[] IV;

        public string Decrypt(string base64EncodedMessage)
        {
            return Decrypt(Key, IV, base64EncodedMessage);
        }
    }
}

