public class AsynchronousDataDecryptor : IDisposable
{
    private readonly IConfiguration _configuration;
    private readonly ILogger _logger;
    private readonly IServiceProvider _cspProviderService;

    // Resource Pool for Keys and IVs
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] Iv)> _resourcePool;

    // Semaphore for Rate Limiting
    private readonly SemaphoreSlim _semaphore;

    public AsynchronousDataDecryptor(IServiceProvider cspProviderService)
    {
        _configuration = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json")
            .AddEnvironmentVariables()
            .Build();

        _logger = new LoggerConfiguration()
            .ReadFrom.Configuration(_configuration)
            .CreateLogger();

        _cspProviderService = cspProviderService;
        _resourcePool = new ConcurrentDictionary<string, (byte[] Key, byte[] Iv)>();
        _semaphore = new SemaphoreSlim(int.Parse(_configuration["MaxConcurrentDecryptions"]));
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string clearanceLevel)
    {
        await _semaphore.WaitAsync();

        try
        {
            if (!ValidateMessage(base64EncodedMessage))
            {
                _logger.Warning("Invalid message structure");
                return "Error: Invalid Message Structure";
            }

            var decryptionMethod = _configuration["DecryptionMethod"];
            byte[] key, iv;

            (key, iv) = await FetchKeyAndIVAsync(clearanceLevel);

            if (string.Equals(decryptionMethod, "TripleDES", StringComparison.OrdinalIgnoreCase))
                return await DecryptWithTripleDESAsync(base64EncodedMessage, key, iv);
            else if (string.Equals(decryptionMethod, "AES", StringComparison.OrdinalIgnoreCase))
                return await DecryptWithAESAsync(base64EncodedMessage, key, iv);
            else if (string.Equals(decryptionMethod, "RSA", StringComparison.OrdinalIgnoreCase))
                return await DecryptWithRSAAsync(base64EncodedMessage, key);

            _logger.Error("Unsupported decryption method");
            return null;
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Decryption failed");
            throw; // Re-throw after logging
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<(byte[] Key, byte[] Iv)> FetchKeyAndIVAsync(string clearanceLevel)
    {
        string keyId = $"{clearanceLevel}_key";
        if (!_resourcePool.TryGetValue(keyId, out var resource))
        {
            // Fetch from CSP and cache
            resource = await _cspProviderService.GetKeyAndIVAsync(clearanceLevel);
            _resourcePool[keyId] = resource;
        }

        return resource;
    }

    private bool ValidateMessage(string message)
    {
        // Implement validation logic (e.g., structure, checksums).
        return true; // Placeholder
    }

    private async Task<string> DecryptWithTripleDESAsync(string base64EncodedData, byte[] key, byte[] iv)
    {
        using var des = new TripleDESCryptoServiceProvider();

        des.Key = key;
        des.IV = iv;

        var decryptor = des.CreateDecryptor();
        var cipherTextBytes = Convert.FromBase64String(base64EncodedData);
        var decryptedData = await Task.Run(() => decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length));

        return Encoding.UTF8.GetString(decryptedData).TrimEnd('\0');
    }

    private async Task<string> DecryptWithAESAsync(string base64EncodedData, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();

        aes.Key = key;
        aes.IV = iv;

        var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        var cipherTextBytes = Convert.FromBase64String(base64EncodedData);
        var decryptedData = await Task.Run(() => decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length));

        return Encoding.UTF8.GetString(decryptedData).TrimEnd('\0');
    }

    private async Task<string> DecryptWithRSAAsync(string base64EncodedData, byte[] key)
    {
        using var rsa = new RSACryptoServiceProvider();

        rsa.ImportParameters(new RSAParameters { Modulus = key });

        var cipherTextBytes = Convert.FromBase64String(base64EncodedData);
        var decryptedData = await Task.Run(() => rsa.Decrypt(cipherTextBytes, true));

        return Encoding.UTF8.GetString(decryptedData).TrimEnd('\0');
    }

    public void Dispose()
    {
        _semaphore.Dispose();
        // Clean up resources in _resourcePool if necessary.
    }
}
