// Function to expand the state list in an FSA
void expandStateList(int **stateList, int *numStates, FSA *fsa, void *(*externalDataSource)(void*), State *lastState) {
    pthread_mutex_lock(&lock);

    // Simulate loading new states from external data source
    State *newStates = (State *)externalDataSource(NULL);
    if (!newStates) {
        printf("Error: Failed to load states from the external data source.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    int newSize = *numStates + 100; // Assume 100 new states for demonstration
    State **expandedList = realloc(*stateList, newSize * sizeof(State*));
    if (!expandedList) {
        printf("Error: Memory allocation failed.\n");
        freeFSAStates(newStates);
        pthread_mutex_unlock(&lock);
        return;
    }

    *stateList = expandedList;

    // Append new states to the current list
    for (int i = 0; i < 100; ++i) {
        (*stateList)[*numStates + i] = &newStates[i];
        if (i == 99) {  // Last state in new batch
            lastState->next = &newStates[0];  // Linking to the first new state
        }
    }

    *numStates += 100;
    fsa->transitions = expandedList;  // Updating FSA's transitions

    pthread_mutex_unlock(&lock);

    printf("Expanded State List: %d states now.\n", *numStates);
}

int main() {
    pthread_mutex_init(&lock, NULL);  // Initialize the mutex for thread safety

    int numStates = 10;
    int *stateList = malloc(numStates * sizeof(State*)); // Initial state list with some dummy values
    FSA fsa;
    fsa.num_transitions = 0;

    State initialStates[10] = { {.id = i} for (int i = 0; i < 10; ++i) };
    for (int i = 0; i < numStates; ++i) {
        stateList[i] = &initialStates[i];
    }

    // Create a dummy last state pointing to NULL initially
    State lastState;
    lastState.next = NULL;

    // Example of expanding the state list
    expandStateList(&stateList, &numStates, &fsa, externalDataSourceFunction, &lastState);

    pthread_mutex_destroy(&lock);  // Destroy mutex after use

    free(stateList);
    return 0;
}
