// Define the record structure with an int field
typedef struct {
    int value;
} record;

// Function to simulate querying a database for the number of records needed
int fetch_record_count_from_db() {
    // This function should contain logic to query the external SQL database.
    // For simulation, let's assume it returns 1000 records.
    return 1000; 
}

// Mutex for thread-safe operations during memory allocation and initialization
pthread_mutex_t lock;

void initialize_records(void) {
    int record_count = fetch_record_count_from_db();

    if (record_count <= 0) {
        fprintf(stderr, "Invalid record count fetched from the database.\n");
        return;
    }

    // Allocate memory for arrays of long offsets and int keys
    long *offsets = malloc(record_count * sizeof(long));
    int *keys = malloc(record_count * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets); // Ensure no memory leaks
        free(keys);
        return;
    }

    // Allocate memory for the array of record structures
    record *records = malloc(record_count * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Lock the mutex before accessing shared resources
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; ++i) {
        records[i].value = rand() % 10001; // Random value between 0 and 10000 inclusive
    }

    // Unlock the mutex after completing the operation
    pthread_mutex_unlock(&lock);

    // Here, you would typically return these arrays to be used elsewhere.
    // For demonstration purposes, we'll print the first few values.
    for (int i = 0; i < 10 && i < record_count; ++i) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    // Destroy the mutex after use (if you're not using it elsewhere)
    pthread_mutex_destroy(&lock);
}

int main() {
    // Initialize the mutex before using it
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed.\n");
        return 1;
    }

    initialize_records();

    return 0;
}
