using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;

namespace ConfigLoader
{
    public class Program
    {
        static void Main(string[] args)
        {
            if (args.Length < 3)
            {
                Console.WriteLine("Usage: ConfigLoader <configFilePath> <encryptionKey> <directoryName>");
                return;
            }

            string configFilePath = args[0];
            string encryptionKey = args[1];
            string directoryName = args[2];

            try
            {
                // Load and decrypt the XML file.
                string xmlContent = DecryptFile(configFilePath, encryptionKey);
                XDocument doc = XDocument.Parse(xmlContent);

                // Extract configuration settings.
                int tileSize = (int)doc.Root.Element("TileSize");
                int worldWidth = (int)doc.Root.Element("WorldWidth");
                int worldHeight = (int)doc.Root.Element("WorldHeight");
                float cameraSpeed = (float)doc.Root.Element("CameraSpeed");

                Console.WriteLine($"Tile Size: {tileSize}, World Width: {worldWidth}, World Height: {worldHeight}, Camera Speed: {cameraSpeed}");

                // Call Rust function to create directory and set environment variable.
                CreateDirectoryWithEnv(directoryName);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error: {ex.Message}");
            }
        }

        private static string DecryptFile(string filePath, string key)
        {
            byte[] encryptedData = File.ReadAllBytes(filePath);

            using Aes aesAlg = Aes.Create();
            aesAlg.Key = Encoding.UTF8.GetBytes(key);
            aesAlg.IV = new byte[16]; // Assuming IV is all zeros for simplicity.

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using MemoryStream msDecrypt = new MemoryStream(encryptedData);
            using CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using StreamReader srDecrypt = new StreamReader(csDecrypt);

            return srDecrypt.ReadToEnd();
        }

        [DllImport("rust_lib")]
        private static extern void CreateDirectoryWithEnv(string directoryName);
    }
}
