use std::env;
use std::fs::{self, DirBuilder};
use std::io;
use std::os::unix::prelude::*;

#[no_mangle]
pub extern "C" fn create_directory_with_env(directory_name: &str) {
    let env_var = "MY_APP_DIRECTORY";

    if let Ok(current_path) = env::var(env_var) {
        println!("Using existing directory path from environment: {}", current_path);
    } else {
        match fs::create_dir_all(directory_name) {
            Ok(_) => {
                DirBuilder::new().recursive(true).chmod(0o755).try_for_directory(directory_name)
                    .expect("Failed to set permissions on new directory.");

                env::set_var(env_var, directory_name);
                println!("Created and set environment variable: {}", directory_name);
            }
            Err(e) => {
                eprintln!("Error creating directory '{}': {:?}", directory_name, e);
            }
        }
    }
}

