```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Xml;
using System.Xml.XPath;

// Custom exceptions for specific error handling.
public class FileNotFoundException : Exception {
    public FileNotFoundException(string message) : base(message) { }
}

public class MultipleElementException : Exception {
    public MultipleElementException(string message) : base(message) { }
}

public class XmlParser {
    private readonly string _xmlFilePath;
    private readonly ConcurrentDictionary<string, List<string>> _cache = new();
    private static readonly object LockObject = new();

    // External logger interface
    private ILogger Logger;

    public XmlParser(string xmlFilePath, ILogger logger) {
        _xmlFilePath = xmlFilePath ?? throw new ArgumentNullException(nameof(xmlFilePath));
        Logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public string GetSingleElementValue(string xpathExpression) {
        if (string.IsNullOrWhiteSpace(xpathExpression)) throw new ArgumentException("XPath expression cannot be null or empty.", nameof(xpathExpression));

        try {
            var stopwatch = Stopwatch.StartNew();

            // Check cache first
            if (_cache.TryGetValue(xpathExpression, out List<string> cachedResults)) {
                LogPerformance(stopwatch.ElapsedMilliseconds, xpathExpression);
                if (cachedResults.Count != 1) throw new MultipleElementException($"Multiple or no elements found for XPath '{xpathExpression}'.");
                return cachedResults[0];
            }

            var results = GetElementsValues(xpathExpression);

            lock (LockObject) { // Ensuring thread-safety
                _cache[xpathExpression] = results;
            }

            LogPerformance(stopwatch.ElapsedMilliseconds, xpathExpression);
            if (results.Count == 0) throw new FileNotFoundException($"No element found for XPath '{xpathExpression}'.");
            if (results.Count > 1) throw new MultipleElementException($"Multiple elements found for XPath '{xpathExpression}'.");

            return results[0];
        } catch (Exception ex) {
            Logger.LogException(ex);
            throw;
        }
    }

    public List<string> GetElementsValues(string xpathExpression) {
        if (string.IsNullOrWhiteSpace(xpathExpression)) throw new ArgumentException("XPath expression cannot be null or empty.", nameof(xpathExpression));

        try {
            using var reader = XmlReader.Create(_xmlFilePath);
            var navigator = new XPathDocument(reader).CreateNavigator();

            return navigator.Select(xpathExpression)
                            .Cast<IXmlNode>()
                            .Select(node => node.Value)
                            .ToList();
        } catch (Exception ex) {
            Logger.LogException(ex);
            throw;
        }
    }

    private void LogPerformance(long elapsedMilliseconds, string xpathExpression) {
        // Assuming the logger has a method to log performance metrics
        Logger.Log($"XPath '{xpathExpression}' took {elapsedMilliseconds} ms");
    }
}

// Interface for logging system
public interface ILogger {
    void LogException(Exception ex);
    void Log(string message);
}
