```cpp
#include <jni.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <stdexcept>

class JavaResourceLoader {
public:
    static jobject LoadResourceObject(const std::string& resourcePath, const char* className) {
        JNIEnv* env = GetJNIEnv();

        // Step 1: Load the resource file
        std::ifstream file(resourcePath, std::ios::binary | std::ios::ate);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open resource file.");
        }

        std::streamsize size = file.tellg();
        file.seekg(0, std::ios::beg);

        // Step 2: Read the file into a byte array
        std::vector<char> buffer(size);
        if (!file.read(buffer.data(), size)) {
            throw std::runtime_error("Failed to read resource file.");
        }

        // Step 3: Convert the buffer to a Java byte array
        jbyteArray byteArray = env->NewByteArray(static_cast<jsize>(buffer.size()));
        env->SetByteArrayRegion(byteArray, 0, static_cast<jsize>(buffer.size()), reinterpret_cast<const jbyte*>(buffer.data()));

        // Step 4: Deserialize using Java's ObjectInputStream
        jclass objectInputClass = env->FindClass("java/io/ObjectInputStream");
        if (objectInputClass == nullptr) {
            throw std::runtime_error("ObjectInputStream class not found.");
        }

        jmethodID constructorMethodId = env->GetMethodID(objectInputClass, "<init>", "([B)V");
        jobject objectInputStream = env->NewObject(objectInputClass, constructorMethodId, byteArray);

        if (objectInputStream == nullptr) {
            throw std::runtime_error("Failed to create ObjectInputStream.");
        }

        jclass inputStreamClass = env->GetObjectClass(objectInputStream);
        jmethodID readObjectMethodId = env->GetMethodID(inputStreamClass, "readObject", "()Ljava/lang/Object;");
        jobject deserializedObject = env->CallObjectMethod(objectInputStream, readObjectMethodId);

        if (env->ExceptionCheck()) {
            env->ExceptionDescribe();
            env->ExceptionClear();
            throw std::runtime_error("Deserialization failed.");
        }

        // Step 5: Check class of the deserialized object
        jclass targetClass = env->FindClass(className);
        if (targetClass == nullptr) {
            throw std::runtime_error("Target class not found.");
        }

        jboolean isInstance = env->IsInstanceOf(deserializedObject, targetClass);
        if (!isInstance) {
            throw std::runtime_error("Deserialized object does not match the specified class.");
        }

        // Clean up local references
        env->DeleteLocalRef(byteArray);
        env->DeleteLocalRef(objectInputStream);
        env->DeleteLocalRef(inputStreamClass);

        return deserializedObject;
    }

private:
    static JNIEnv* GetJNIEnv() {
        JavaVM* jvm = nullptr;
        jint result = JNI_GetCreatedJavaVMs(&jvm, 1, nullptr);
        if (result != 0 || jvm == nullptr) {
            throw std::runtime_error("Failed to get the Java VM.");
        }

        JNIEnv* env;
        result = jvm->AttachCurrentThread(reinterpret_cast<void**>(&env), nullptr);
        if (result != 0) {
            throw std::runtime_error("Failed to attach current thread to JVM.");
        }

        return env;
    }
};
```

### Key Points:
- **JNI**: This code uses JNI (Java Native Interface) to interact with Java classes and methods.
- **Error Handling**: Throws `std::runtime_error` for various failure points, such as file operations and class/method lookups.
- **Resource Management**: Properly manages local references and ensures cleanup using `DeleteLocalRef`.
