```rust
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use log::{info, error};
use rayon::prelude::*;
use anyhow::{Result, Context};

fn generate_llvm_ir(directory: &str, log_file: &str, optimization_passes: &[&str]) -> Result<()> {
    // Create a logger to write logs to the specified file
    let _ = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .open(log_file);

    // Set up logging configuration (using env_logger for simplicity here)
    env_logger::builder().add_filter("info").init();

    // Get all `.rs` files in the directory
    let dir_path = PathBuf::from(directory);
    let rs_files: Vec<PathBuf> = fs::read_dir(&dir_path)?
        .filter_map(Result::ok)
        .filter(|entry| entry.path().extension() == Some(std::ffi::OsStr::new("rs")))
        .map(|entry| entry.path())
        .collect();

    // Process each file in parallel
    rs_files.into_par_iter().try_for_each(|file_path| {
        let base_name = file_path.file_stem().unwrap_or_else(|| std::ffi::OsStr::new("unknown")).to_str().unwrap();
        let output_file = dir_path.join(format!("{}.ll", base_name));

        // Parse and compile the Rust source to LLVM IR
        info!("Compiling {} to LLVM IR", file_path.display());
        let ir_output = Command::new("rustc")
            .arg(file_path)
            .arg("--emit=llvm-ir")
            .output()
            .with_context(|| format!("Failed to execute rustc for {}", file_path.display()))?;

        if !ir_output.status.success() {
            error!(
                "{}",
                String::from_utf8_lossy(&ir_output.stderr)
                    .to_string()
                    .context("Error during Rust compilation")
            );
            return Err(anyhow::anyhow!("Rust compilation failed for {:?}", file_path));
        }

        // Write raw LLVM IR to a temporary file
        let tmp_ir_file = dir_path.join(format!("{}_tmp.ll", base_name));
        fs::write(&tmp_ir_file, &ir_output.stdout)?;

        // Optimize the LLVM IR using specified passes
        info!("Optimizing LLVM IR for {}", file_path.display());
        let optimize_command = Command::new("opt")
            .arg("-S") // Output to stdout
            .arg(format!("-o{}", output_file.to_str().unwrap()))
            .arg(tmp_ir_file)
            .args(optimization_passes);

        let optimize_output = optimize_command.output()?;

        if !optimize_output.status.success() {
            error!(
                "{}",
                String::from_utf8_lossy(&optimize_output.stderr)
                    .to_string()
                    .context("Error during LLVM optimization")
            );
            return Err(anyhow::anyhow!("LLVM optimization failed for {:?}", file_path));
        }

        // Clean up temporary file
        fs::remove_file(tmp_ir_file)?;

        info!("Successfully optimized {} to {}", file_path.display(), output_file.display());
        Ok(())
    })
}

fn main() -> Result<()> {
    let directory = "./src";
    let log_file = "compilation.log";
    let optimization_passes = &["-O2", "-strip-debug"]; // Example passes

    generate_llvm_ir(directory, log_file, optimization_passes)?;

    Ok(())
}
```

This code assumes you have `rustc` and `opt` from the LLVM toolchain installed on your system. The function uses Rayon for parallel processing of files, `anyhow` for error handling, and `env_logger` for logging to a file. You may need additional setup to integrate with an external logging system if required. Adjust paths and commands according to your environment.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Min value must be less than Max value.");

        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloatInclusive()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public float GetRandomFloatExclusive()
    {
        return UnityEngine.Random.value * (maxValue - minValue) + minValue;
    }

    public int GetRandomIntegerInRange(int min, int max)
    {
        if (min >= max || min < 0 || max > Int32.MaxValue)
            throw new ArgumentException("Invalid integer range.");

        return UnityEngine.Random.Range(min, max);
    }

    public List<int> GenerateUniqueIntegersList(int size)
    {
        if (size <= 0 || (int)maxValue - (int)minValue + 1 < size)
            throw new ArgumentException("Size is too large for the range or negative.");

        var result = new HashSet<int>();

        while (result.Count < size)
        {
            int randomInt = GetRandomIntegerInRange((int)minValue, (int)maxValue + 1);
            result.Add(randomInt);
        }

        return new List<int>(result);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
```

