    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8;
} NFAPI_CRC_INDICATION_PDU_T;

// Placeholder for logging function
void log_structure_creation(const char *message) {
    printf("%s\n", message);
}

int validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T *structures, int num_structures, int *crc_flag_rules) {
    for (int i = 0; i < num_structures; ++i) {
        if (structures[i].CRC_INDICATION_REL8.CRCFLAG != crc_flag_rules[i]) {
            return -1; // Mismatch found
        }
    }
    return 0; // All matches
}

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    if (num_structures <= 0 || nfalist == NULL || crc_flag_rules == NULL) {
        return -1; // Invalid input
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&lock);

        (*nfalist)[i].CRC_INDICATION_REL8.CRCFLAG = crc_flag_rules[i];

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Created structure %d with CRCFLAG: %d", i, crc_flag_rules[i]);
        log_structure_creation(log_message);

        pthread_mutex_unlock(&lock);
    }

    int validation_result = validate_crc_flags(*nfalist, num_structures, crc_flag_rules);
    if (validation_result != 0) {
        free(*nfalist);
        *nfalist = NULL;
        return -3; // Validation failed
    }

    pthread_mutex_destroy(&lock);

    return 0; // Success
}
