```javascript
const fs = require('fs');
const http = require('http');

async function copyBytesFromSources(sources) {
    const resultBuffer = Buffer.alloc(0);
    let totalCopied = 0;

    for (let { type, path, byteRange } of sources) {
        if (!byteRange || byteRange.length !== 2) {
            throw new Error('Invalid byte range specified');
        }

        let sourceData;
        switch(type) {
            case 'buffer':
                const [start, end] = byteRange;
                const bufferLength = path.length - start;
                const validEnd = Math.min(end || bufferLength, bufferLength);
                if (validEnd < 0) throw new Error('Byte range exceeds available data');

                sourceData = Buffer.from(path.slice(start, validEnd));
                break;

            case 'file':
                try {
                    const stats = await fs.promises.stat(path);
                    const fileSize = stats.size;
                    let [fileStart, fileEnd] = byteRange.map(b => Math.min(Math.max(0, b), fileSize));

                    if (fileStart >= fileEnd) throw new Error('Invalid byte range for file');

                    sourceData = await readFromFile(path, fileStart, fileEnd - fileStart);
                } catch (error) {
                    throw new Error(`Error accessing file: ${error.message}`);
                }
                break;

            case 'http':
                try {
                    const [fileStart, fileEnd] = byteRange;
                    sourceData = await fetchFromHttp(path, fileStart, fileEnd - fileStart);
                } catch (error) {
                    throw new Error(`Error fetching HTTP data: ${error.message}`);
                }
                break;

            default:
                throw new Error('Unsupported source type');
        }

        totalCopied += sourceData.length;
        resultBuffer = Buffer.concat([resultBuffer, sourceData]);
    }

    return resultBuffer;
}

async function readFromFile(filePath, start, length) {
    const fd = await fs.promises.open(filePath, 'r');
    try {
        const buffer = Buffer.allocUnsafe(length);
        let bytesRead = 0;

        while (bytesRead < length) {
            const { bytesRead: currentBytesRead } = await fd.read(buffer, bytesRead, length - bytesRead, start + bytesRead);
            if (currentBytesRead === 0) throw new Error('Premature EOF');
            bytesRead += currentBytesRead;
        }

        return buffer;
    } finally {
        await fd.close();
    }
}

async function fetchFromHttp(url, start, length) {
    return new Promise((resolve, reject) => {
        const options = url.startsWith('http') ? { headers: { Range: `bytes=${start}-${start + length - 1}` }, timeout: 5000 } : {};

        http.get(url, options, (res) => {
            if (res.statusCode === 206 || res.statusCode === 200) {
                const chunks = [];
                let totalBytesRead = 0;

                res.on('data', (chunk) => {
                    chunks.push(chunk);
                    totalBytesRead += chunk.length;
                    if (totalBytesRead > length) res.destroy(); // Stop reading more than needed
                });

                res.on('end', () => {
                    const combinedBuffer = Buffer.concat(chunks).slice(0, length); // Trim to requested length
                    resolve(combinedBuffer);
                });
            } else {
                reject(new Error(`Unexpected status code: ${res.statusCode}`));
            }
        }).on('error', reject);
    });
}

module.exports = copyBytesFromSources;

// Example usage (this should be done in a proper test environment):
/*
(async () => {
    try {
        const data = await copyBytesFromSources([
            { type: 'buffer', path: Buffer.from('Hello World'), byteRange: [0, 5] },
