typedef struct {
    long value;
    long timestamp;
} record;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

record* create_and_initialize_data(long num_elements, int delay_range_min, int delay_range_max, pthread_mutex_t *mutex) {
    if (num_elements <= 0 || delay_range_min < 0 || delay_range_max <= delay_range_min) {
        log_error("Invalid input parameters");
        return NULL;
    }

    long *offsets = malloc(num_elements * sizeof(long));
    int *keys = malloc(num_elements * sizeof(int));
    record *records = malloc(num_elements * sizeof(record));

    if (!offsets || !keys || !records) {
        log_error("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (long i = 0; i < num_elements; ++i) {
        offsets[i] = rand(); // Generate a random offset
        keys[i] = rand() % 10000; // Generate a random key
    }

    long current_time = time(NULL);

    pthread_mutex_lock(mutex);
    for (long i = 0; i < num_elements; ++i) {
        records[i].value = offsets[i]; // Initialize record value
        int delay = rand() % (delay_range_max - delay_range_min + 1) + delay_range_min;
        records[i].timestamp = current_time + delay; // Set timestamp with random delay
    }
    pthread_mutex_unlock(mutex);

    return records;
}

// Usage example:
// Define the mutex outside of threads
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    long num_elements = 10;
    int delay_range_min = 5, delay_range_max = 15;

    record *records = create_and_initialize_data(num_elements, delay_range_min, delay_range_max, &mutex);

    if (records) {
        // Use the records
        free(records);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}
