```javascript
class FileLoader {
    constructor() {
        this.fileQueue = [];
        this.loadingFiles = new Set();
        this.logger = console; // You can replace this with any logging library
    }

    addFile(filePath) {
        if (!this.fileQueue.includes(filePath)) {
            this.fileQueue.push(filePath);
            this.logger.info(`Added file: ${filePath}`);
            this.processQueue();
        }
    }

    removeFile(filePath) {
        const index = this.fileQueue.indexOf(filePath);
        if (index > -1) {
            this.fileQueue.splice(index, 1);
            this.logger.info(`Removed file: ${filePath}`);
        }
    }

    async processQueue() {
        while (this.fileQueue.length > 0 && this.loadingFiles.size < 5) { // Limit concurrent loads
            const filePath = this.fileQueue[0];
            if (!this.loadingFiles.has(filePath)) {
                try {
                    await this.loadAndExecuteFile(filePath);
                } catch (error) {
                    this.logger.error(`Failed to load or execute file: ${filePath}`, error);
                    this.handleFailure(filePath);
                }
            }
        }
    }

    async loadAndExecuteFile(filePath) {
        this.loadingFiles.add(filePath);

        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = filePath;
            script.async = true;

            script.onload = () => {
                this.logger.info(`Successfully loaded file: ${filePath}`);
                this.loadingFiles.delete(filePath);
                this.fileQueue.shift();
                resolve();
                this.processQueue(); // Proceed to next in the queue
            };

            script.onerror = (error) => {
                reject(new Error(`Error loading file: ${filePath}`));
            };

            document.head.appendChild(script);
        });
    }

    handleFailure(filePath) {
        // Implement fallback mechanism or retry strategy here if needed
        this.logger.warn(`Attempting fallback for file: ${filePath}`);
        // Example fallback logic could be re-trying with a different source, etc.
    }

    updateFilesFromConfig(configUrl) {
        fetch(configUrl)
            .then(response => response.json())
            .then(data => {
                const currentFileSet = new Set(this.fileQueue);
                data.files.forEach(filePath => {
                    if (!currentFileSet.has(filePath)) {
                        this.addFile(filePath);
                    }
                });

                // Remove files not present in the updated config
                currentFileSet.forEach(filePath => {
                    if (!data.files.includes(filePath)) {
                        this.removeFile(filePath);
                    }
                });
            })
            .catch(error => {
                this.logger.error('Failed to update files from configuration', error);
            });
    }

    cleanup() {
        // Implement any necessary resource management and cleanup strategies
        while (this.fileQueue.length > 0) {
            const script = document.head.lastChild;
            if (script && script.tagName === 'SCRIPT') {
                document.head.removeChild(script);
            }
        }
    }
}

// Usage example:
const loader = new FileLoader();
loader.addFile('https://example.com/script1.js');
loader.updateFilesFromConfig('https://example.com/config.json');

window.addEventListener('beforeunload', () => {
    loader.cleanup(); // Ensure cleanup on page unload
});
