<?php

// Initialize session for storing OAuth 2.0 access token
session_start();

use GuzzleHttp\Client;
use PDO;

class ClinicAPI {

    private $dbConnection;
    private $client;
    private const RATE_LIMIT = 5; // Max requests per second
    private $lastRequestTimestamps = [];

    public function __construct(PDO $dbConnection) {
        $this->dbConnection = $dbConnection;
        $this->client = new Client([
            'base_uri' => 'https://oauthprovider.com/', // Replace with actual OAuth provider base URI
            'timeout'  => 2.0,
        ]);
    }

    public function authenticateUserAndUpdateClinicStatus($accessToken, $clinicId) {
        if (!$this->isRateLimited()) {
            try {
                $response = $this->client->request('GET', "tokeninfo", [
                    'headers' => ['Authorization' => "Bearer {$accessToken}"]
                ]);

                $data = json_decode($response->getBody(), true);

                // Assuming a valid response structure
                if ($data['active']) {
                    $_SESSION['access_token'] = $accessToken;

                    return $this->updateClinicStatus($clinicId, 'Active');
                } else {
                    throw new Exception('Invalid access token.');
                }
            } catch (Exception $e) {
                // Handle authentication errors
                echo "Authentication failed: ",  $e->getMessage(), "\n";
                return false;
            }
        } else {
            echo "Rate limit exceeded. Please try again later.\n";
            return false;
        }
    }

    private function updateClinicStatus($clinicId, $status) {
        try {
            $ipAddress = $_SERVER['REMOTE_ADDR'];
            $lastModifiedDate = date('Y-m-d H:i:s');

            $stmt = $this->dbConnection->prepare(
                "UPDATE clinic SET status=:status, last_modified_ip=:ip, last_modified_date=:date WHERE id=:id"
            );
            $stmt->execute([
                ':status' => $status,
                ':ip' => $ipAddress,
                ':date' => $lastModifiedDate,
                ':id' => $clinicId
            ]);

            return true;
        } catch (PDOException $e) {
            // Handle database errors
            echo "Database update failed: ",  $e->getMessage(), "\n";
            return false;
        }
    }

    private function isRateLimited() {
        $currentTime = time();

        // Remove timestamps older than one second
        $this->lastRequestTimestamps = array_filter($this->lastRequestTimestamps, function ($timestamp) use ($currentTime) {
            return ($currentTime - $timestamp) < 1;
        });

        if (count($this->lastRequestTimestamps) >= self::RATE_LIMIT) {
            return true;
        }

        // Add the current timestamp and return false
        $this->lastRequestTimestamps[] = $currentTime;
        return false;
    }

    public function getFileMD5Hash($filePath, $privateKeyPath, $certificatePath) {
        try {
            $pemContent = file_get_contents($privateKeyPath) . "\n" .
                          file_get_contents($certificatePath);

            // Save PEM content to a temporary file
            $tempFile = tempnam(sys_get_temp_dir(), 'PEM');
            file_put_contents($tempFile, $pemContent);

            if (!file_exists($filePath)) {
                throw new Exception("File not found.");
            }

            $hash = md5_file($filePath);

            // Read the temporary PEM file in chunks and hash
            $handle = fopen($tempFile, 'rb');
            $md5 = md5('');
            while (!feof($handle)) {
                $data = fread($handle, 8192);
                $md5 = md5($md5 . $data);
            }
            fclose($handle);

            // Clean up the temporary file
            unlink($tempFile);

            return ['fileHash' => $hash, 'pemHash' => $md5];
        } catch (Exception $e) {
            echo "Error hashing file: ",  $e->getMessage(), "\n";
            return false;
        }
    }

}

// Example usage
try {
    // Database connection setup (using PDO)
    $dbConnection = new PDO('mysql:host=localhost;dbname=clinic_db', 'username', 'password');

    // Instantiate the API class
    $api = new ClinicAPI($dbConnection);

    // Authenticate user and update clinic status
    $accessToken = 'example_access_token';
    $clinicId = 1;
    if ($api->authenticateUserAndUpdateClinicStatus($accessToken, $clinicId)) {
        echo "Clinic status updated successfully.\n";
    }

    // Calculate MD5 hash of file along with combined PEM content
    $filePath = '/path/to/your/file.txt';
    $privateKeyPath = '/path/to/private.key';
    $certificatePath = '/path/to/certificate.crt';

    $hashes = $api->getFileMD5Hash($filePath, $privateKeyPath, $certificatePath);
    if ($hashes) {
        echo "File MD5: " . $hashes['fileHash'] . "\n";
        echo "PEM MD5: " . $hashes['pemHash'] . "\n";
    }
} catch (PDOException $e) {
    echo "Connection failed: ",  $e->getMessage(), "\n";
}
