# Rate limiting storage
client_requests = {}

def rate_limit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        client_ip = request.remote_addr
        if client_ip not in client_requests:
            client_requests[client_ip] = []
        requests_log = client_requests[client_ip]

        # Remove old requests beyond 1 hour window
        one_hour_ago = datetime.now() - timedelta(hours=1)
        requests_log[:] = [req_time for req_time in requests_log if req_time > one_hour_ago]

        if len(requests_log) >= 500:
            return jsonify({"status": "error", "message": "Rate limit exceeded"}), 429

        # Log the current request
        requests_log.append(datetime.now())

        return func(*args, **kwargs)
    return wrapper

