                "name" => $data['name'],
                "email" => $data['email']
            ]
        ]);
    } catch (Exception $e) {
        // Handle and log errors
        return $response->withJson([
            "status" => "error",
            "message" => "Failed to create user account due to " . $e->getMessage(),
            "data" => null,
        ], 500);
    }
});

// More routes for update, delete etc.

$app->run();

function validateUserInput($data) {
    // Validate email uniqueness and password complexity
    return !empty($data['email']) && filter_var($data['email'], FILTER_VALIDATE_EMAIL)
           && isset($data['password']) && strlen($data['password']) >= 8;
}

function isUserExists($db, $email) {
    $stmt = $db->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
    $stmt->execute([':email' => $email]);
    return (bool)$stmt->fetchColumn();
}

function logAction($action, $details) {
    // Log user actions for auditing
    file_put_contents('logs/actions.log', json_encode([$action, $details]), FILE_APPEND);
}
