public class TestLoader {

    private static final Logger logger = Logger.getLogger(TestLoader.class.getName());
    private static final int CACHE_MAX_SIZE = 100;
    private final ConcurrentHashMap<String, MoSTState> stateCache = new ConcurrentHashMap<>();

    public void dynamicTestLoader(String moduleName) {
        try (ClassLoader customClassLoader = createCustomClassLoader(moduleName)) {

            // Load and execute tests dynamically
            for (String className : getTestClassNames(customClassLoader)) {
                Class<?> testClass = customClassLoader.loadClass(className);
                Object testInstance = testClass.getDeclaredConstructor().newInstance();

                for (Method method : testClass.getMethods()) {
                    if (method.getName().startsWith("test")) {
                        executeTestMethod(testInstance, method, moduleName);
                    }
                }

                resetBlueslip();
            }

        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error loading tests for module: " + moduleName, e);
        }
    }

    private ClassLoader createCustomClassLoader(String moduleName) throws IOException, URISyntaxException {
        // Implementation to load class files dynamically
        return URLClassLoader.newInstance(new URL[]{new File(moduleName).toURI().toURL()}, getClass().getClassLoader());
    }

    private String[] getTestClassNames(ClassLoader customClassLoader) {
