            throws Exception {

        logger.info("Executing test method: " + method.getName());

        Object state = checkAndUpdateCacheAndLoadState();

        if (state != null) {
            method.invoke(testInstance, state);
        } else {
            logger.warning("No valid MoSTState found for module: " + moduleName);
        }
    }

    private synchronized void resetBlueslip() {
        Mockito.reset(Mockito.mock(Object.class)); // Replace with actual blueslip resetting
    }

    private Object checkAndUpdateCacheAndLoadState() {
        String cacheKey = generateCacheKey();

        if (stateCache.containsKey(cacheKey)) {
            return stateCache.get(cacheKey);
        } else {
            MoSTState state = loadStateFromExternalServiceOrFile();
            if (state != null) {
                updateCache(cacheKey, state);
            }
            return state;
        }
    }

    private String generateCacheKey() {
        // Implementation for generating a unique cache key
        return "uniqueKey";  // Placeholder for actual implementation
    }

    private MoSTState loadStateFromExternalServiceOrFile() {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("state.obj"))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
