    private void updateCache(String key, MoSTState state) {
        if (stateCache.size() >= CACHE_MAX_SIZE) {
            String oldestKey = stateCache.keySet().iterator().next();
            stateCache.remove(oldestKey);
        }
        stateCache.put(key, state);
