import subprocess
from typing import Dict

def modify_kickstart_config(config_path: str, params: Dict[str, str], encrypted_password: str):
    commands = [
        ['sed', '-i', f's/{k}/{v}/g' for k, v in params.items()],
        ['echo', f'\npassword --encrypted {encrypted_password}', '>>', config_path]
    ]

    try:
        for command in commands:
            subprocess.run(command, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to execute sed command: {e}")

