/**
 * Asynchronous reduce function for an array of Pokemon objects.
 *
 * @param {Array} pokemonArray - Array of Pokemon objects.
 * @param {Function} callback - Callback function to determine weaknesses based on type.
 * @param {*} initialValue - Initial value for the reduction.
 * @returns {Promise<string>} A promise resolving to a string representing combined weaknesses or an error message.
 */
async function asyncReducePokemon(pokemonArray, callback, initialValue) {
  const cache = new Map();

  // Helper function to fetch Pokemon data with pagination
  async function fetchPokemonData(index) {
    if (index >= pokemonArray.length) return null;

    try {
      const pokemonName = pokemonArray[index].name;
      let pokemonData;

      if (cache.has(pokemonName)) {
        pokemonData = cache.get(pokemonName);
      } else {
        // Simulated API call
        pokemonData = await simulateApiCall(pokemonName);
        cache.set(pokemonName, pokemonData);
      }

      return { ...pokemonArray[index], ...pokemonData };
    } catch (error) {
      throw new Error(`Error fetching data for Pokemon at index ${index}: ${error.message}`);
    }
  }

  // Simulated API call function
  async function simulateApiCall(name) {
    // Simulate network latency
    await new Promise(resolve => setTimeout(resolve, Math.random() * 100));

    // Mock response
    return { type: 'Fire', level: 50 }; 
  }

  const result = await pokemonArray.reduce(async (accPromise, currentPokemon, index) => {
    try {
      const acc = await accPromise;

      if (!index) return callback(currentPokemon, initialValue);

      const pokemonData = await fetchPokemonData(index);
      if (!pokemonData) return acc;

      return callback(pokemonData, acc);
    } catch (error) {
      throw error;
    }
  }, Promise.resolve(initialValue));

  return result;
}

/**
 * Callback function to determine weaknesses of Pokemon based on type.
 *
 * @param {Object} pokemon - The current Pokemon object.
 * @param {string} weaknesses - Combined string of weaknesses from previous iterations.
 * @returns {string} Updated combined weaknesses string.
 */
function determineWeaknesses(pokemon, weaknesses) {
  let updatedWeaknesses = weaknesses;

  switch (pokemon.type) {
    case 'Fire':
      if (!updatedWeaknesses.includes('Water')) updatedWeaknesses += 'Water ';
      break;
    case 'Water':
      if (!updatedWeaknesses.includes('Electric')) updatedWeaknesses += 'Electric ';
      break;
    case 'Grass':
      if (!updatedWeaknesses.includes('Fire')) updatedWeaknesses += 'Fire ';
      break;
    // Add more cases as needed
  }

  return updatedWeaknesses.trim();
}

// Example usage and test cases
(async () => {
  const pokemonArray = [
    { name: 'Pikachu', type: '', level: 0 },
    { name: 'Charmander', type: '', level: 0 },
    // Add more Pokemon objects as needed for testing
  ];

  try {
    const combinedWeaknesses = await asyncReducePokemon(pokemonArray, determineWeaknesses, '');
    console.log('Combined Weaknesses:', combinedWeaknesses);
  } catch (error) {
    console.error('Error during reduction process:', error.message);
  }
})();
