class ClinicOperationsManager {
    private $dbConnection;
    private $rateLimitCache = [];
    private $maxRateLimitPerHour = 100;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function manageClinicOperations($operation, $data) {
        $ipAddress = $_SERVER['REMOTE_ADDR'];

        if (!$this->checkRateLimit($ipAddress)) {
            return ['error' => 'Rate limit exceeded. Please try again later.'];
        }

        switch ($operation) {
            case 'create':
                return $this->createClinic($data);

            case 'update':
                return $this->updateClinic($data);

            case 'delete':
                return $this->deleteClinic($data['clinic_id']);

            default:
                return ['error' => 'Invalid operation.'];
        }
    }

    private function checkRateLimit($ipAddress) {
        if (!isset($this->rateLimitCache[$ipAddress])) {
            $this->rateLimitCache[$ipAddress] = [
                'count' => 0,
                'timestamp' => time()
            ];
        }

        $currentTime = time();
        if ($currentTime - $this->rateLimitCache[$ipAddress]['timestamp'] > 3600) {
            $this->rateLimitCache[$ipAddress] = ['count' => 1, 'timestamp' => $currentTime];
            return true;
        } elseif ($this->rateLimitCache[$ipAddress]['count'] < $this->maxRateLimitPerHour) {
            $this->rateLimitCache[$ipAddress]['count']++;
            return true;
        }

        return false;
    }

    private function createClinic($data) {
        // Validate clinic name
        if (strlen($data['clinic_name']) > 50 || !$this->isUniqueClinicName($data['clinic_name'])) {
            return ['error' => 'Invalid or duplicate clinic name.'];
        }

        $sql = "INSERT INTO clinics (name, status, location, capacity) VALUES (?, ?, ?, ?)";
        $stmt = $this->dbConnection->prepare($sql);
        if ($stmt && $stmt->execute([$data['clinic_name'], $data['status'], $data['location'], $data['capacity']])) {
            return ['success' => 'Clinic created successfully.'];
        }

        // Handle error, retry logic
        $this->handleError('Create clinic operation failed.');
