```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::path::PathBuf;

// Function to create a log directory with the given name and update the environment variable.
pub fn create_log_directory(log_dir_name: &str) -> Result<PathBuf, String> {
    let env_var = "APP_LOG_DIR";

    // Get the base directory for logs from an environment variable or default to "logs" in the current directory.
    let base_path = env::var(env_var).unwrap_or_else(|_| format!("./{}", log_dir_name)).into();

    // Create a full path by joining the base and log directory name.
    let mut full_log_path = PathBuf::from(base_path);
    full_log_path.push(log_dir_name);

    // Attempt to create the new directory, handling potential errors
    if !full_log_path.exists() {
        match DirBuilder::new().recursive(true).create(&full_log_path) {
            Ok(_) => {
                // Update the environment variable to reflect the newly created log directory.
                env::set_var(env_var, full_log_path.to_string_lossy());

                Ok(full_log_path)
            }
            Err(e) => Err(format!("Failed to create log directory '{}': {}", full_log_path.display(), e)),
        }
    } else {
        // If it already exists, just return the path.
        Ok(full_log_path)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_create_log_directory_success() {
        let result = create_log_directory("test_logs");

        assert!(result.is_ok());
        if let Ok(path) = result {
            assert!(path.exists());
        }
    }

    #[test]
    fn test_create_log_directory_existing_directory() {
        let _ = create_log_directory("existing_test_logs"); // Initial creation
        let result = create_log_directory("existing_test_logs");

        assert!(result.is_ok());
        if let Ok(path) = result {
            assert!(path.exists()); // Should still exist, as it was already created.
        }
    }

    #[test]
    fn test_create_log_directory_error_handling() {
        std::fs::create_dir_all("./error_test_logs").unwrap(); // Simulate lack of permissions
        let result = create_log_directory("error_test_logs");

        assert!(result.is_err());
    }
}
