    time(&currentTime);

    // Check if cooldown period has passed
    if (difftime(currentTime, lastAttackTime) < 1) {
        std::cout << "Cooldown period not yet complete. Please wait.\n";
        return;
    }

    int attackIndex = std::rand() % 3;

    // Get current energy level
    int currentEnergy = getCurrentEnergy();

    if (currentEnergy >= energyCosts[attackIndex]) {
        // Perform the attack
        updateEnergy(-energyCosts[attackIndex]);
        lastAttackTime = currentTime;
        std::cout << "Selected Attack: " << attackIndex + 1 << "\n";
    } else {
        std::cout << "Not enough energy to perform Attack " << attackIndex + 1 << ".\n";
    }
