```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
import System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public interface ICspAdapter
{
    Task<(byte[] Key, byte[] Iv)> RetrieveCryptoMaterialAsync(string contextId);
}

public class SecureMessageHandler
{
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> _cryptoCache = new();
    private readonly ICspAdapter _cspAdapter;

    public SecureMessageHandler(ICspAdapter cspAdapter)
    {
        _cspAdapter = cspAdapter;
    }

    public string DecryptMessage(string base64EncodedMessage, string contextId)
    {
        try
        {
            var (key, iv) = GetCryptoMaterial(contextId);

            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;

                ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                using (var ms = new System.IO.MemoryStream(encryptedBytes))
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedBytes.Length];
                    int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return Encoding.UTF8.GetString(decryptedBytes, 0, bytesRead);
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    public async Task<List<string>> DecryptMessagesAsync(List<string> base64EncodedMessages, string contextId)
    {
        var tasks = new List<Task<string>>();
        foreach (var message in base64EncodedMessages)
        {
            tasks.Add(Task.Run(() => DecryptMessage(message, contextId)));
        }

        try
        {
            return await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private async Task<(byte[] Key, byte[] Iv)> GetCryptoMaterial(string contextId)
    {
        if (_cryptoCache.TryGetValue(contextId, out var cachedValue))
        {
            return cachedValue;
        }

        try
        {
            var (key, iv) = await _cspAdapter.RetrieveCryptoMaterialAsync(contextId);
            _cryptoCache[contextId] = (key, iv);
            return (key, iv);
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private void LogError(Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
        // Additional logging logic here
    }
}

// Example CSP adapter implementation
public class SampleCspAdapter : ICspAdapter
{
    private readonly HttpClient _httpClient = new();

    public async Task<(byte[] Key, byte[] Iv)> RetrieveCryptoMaterialAsync(string contextId)
    {
        try
        {
            // Simulated HTTP call to a CSP endpoint
            var response = await _httpClient.GetAsync($"https://example.com/api/crypto/{contextId}");
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            // Parse and return the key and IV from the content
            return (Encoding.UTF8.GetBytes("sampleKey"), Encoding.UTF8.GetBytes("sampleIV"));
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Network error: {ex.Message}");
            throw;
        }
    }
}

// Usage example (main method or other entry point in a real application)
public class Program
{
    public static async Task Main()
    {
        ICspAdapter cspAdapter = new SampleCspAdapter();
        SecureMessageHandler handler = new SecureMessageHandler(cspAdapter);

        string base64EncodedMessage = "SGVsbG8gV29ybGQ="; // Example Base64 message
        string contextId = "exampleContext";

        try
        {
            string decryptedMessage = handler.DecryptMessage(base64EncodedMessage, contextId);
            Console.WriteLine($"Decrypted Message: {decryptedMessage}");

            List<string> messages = new() { base64EncodedMessage };
            var results = await handler.DecryptMessagesAsync(messages, contextId);

            foreach (var result in results)
            {
                Console.WriteLine($"Asynchronous Decrypted Message: {result}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption failed: {ex.Message}");
        }
    }
}
