<?php

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use Slim\Factory\AppFactory;
use Doctrine\DBAL\DriverManager;
use Redis;

require __DIR__ . '/../vendor/autoload.php';

$app = AppFactory::create();

// Database connection pooling setup
$connectionParams = [
    'dbname' => 'ecommerce_db',
    'user' => 'db_user',
    'password' => 'db_password',
    'host' => 'localhost',
    'port' => 5432,
];
$pool = DriverManager::getConnection($connectionParams);

// Redis cache setup
$redis = new Redis();
$redis->connect('127.0.0.1', 6379);

// Rate limiting setup
function isRateLimited($ip) {
    global $redis;
    $currentMinute = floor(time() / 60);
    $key = "rate_limit_{$ip}_{$currentMinute}";

    if ($currentHour < 18 || $currentHour > 22) { // Off-peak hours
        $limit = 100;
    } else {
        $limit = 500; // Peak hours
    }

    $count = (int)$redis->get($key);
    if ($count >= $limit) {
        return true;
    }
    $redis->incr($key);
    $redis->expire($key, 60);
    return false;
}

// Middleware for rate limiting
$app->add(function (Request $request, Response $response, callable $next) {
    $ip = $request->getServerParams()['REMOTE_ADDR'];
    if (isRateLimited($ip)) {
        return $response->withJson([
            'status' => 'error',
            'message' => 'Too many requests. Please try again later.'
        ], 429);
    }
    return $next($request, $response);
});

// User account management endpoints
$app->post('/user', function (Request $request, Response $response) use ($pool) {
    $data = json_decode($request->getBody()->getContents(), true);

    // Validate email uniqueness and password complexity
    if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
        return $response->withJson([
            'status' => 'error',
            'message' => 'Invalid email format.'
        ], 400);
    }

    $stmt = $pool->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
    $stmt->execute([':email' => $data['email']]);
    if ($stmt->fetchColumn() > 0) {
        return $response->withJson([
            'status' => 'error',
            'message' => 'Email already exists.'
        ], 409);
    }

    // Additional validations and MFA setup...

    // Insert user into database
    $insertStmt = $pool->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
    $insertStmt->execute([
        ':name' => $data['name'],
        ':email' => $data['email'],
        ':password' => password_hash($data['password'], PASSWORD_BCRYPT)
    ]);

    // Log action
    error_log("User created: {$data['email']}");

    // Send email notification
    mail($data['email'], "Account Created", "Welcome to our platform!");

    return $response->withJson([
        'status' => 'success',
        'message' => 'User account created successfully',
        'data' => [
            'id' => $pool->lastInsertId(),
            'name' => $data['name'],
            'email' => $data['email'],
            'subscription_status' => 'inactive'
        ]
    ], 201);
});

$app->put('/user/{id}', function (Request $request, Response $response, array $args) use ($pool) {
    $userId = $args['id'];
    $data = json_decode($request->getBody()->getContents(), true);

    // Validate and update user
