```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <filesystem>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <future>
#include <asio.hpp> // For async DNS resolution
#include <spdlog/spdlog.h>

namespace fs = std::filesystem;

class DirectoryProcessor {
public:
    DirectoryProcessor(const std::string& directory, const std::string& extension,
                       size_t bufferSize, size_t maxFileSize, int concurrentThreads)
        : dir_(directory), ext_(extension), buffer_size_(bufferSize),
          max_file_size_(maxFileSize), concurrent_threads_(concurrentThreads) {

        // Initialize logging
        logger_ = spdlog::stdout_color_mt("console");
    }

    std::string readDirectoryAndResolveHostnames() {
        auto future_result = std::async(std::launch::async, &DirectoryProcessor::processFiles, this);
        return future_result.get();
    }

private:
    std::string dir_;
    std::string ext_;
    size_t buffer_size_;
    size_t max_file_size_;
    int concurrent_threads_;

    std::shared_ptr<spdlog::logger> logger_;

    struct Cache {
        std::unordered_map<std::string, std::string> file_contents;
        std::unordered_map<std::string, std::string> dns_results;

        bool get_content(const std::string& filename, std::string& content) const {
            auto it = file_contents.find(filename);
            if (it != file_contents.end()) {
                content = it->second;
                return true;
            }
            return false;
        }

        bool get_dns_result(const std::string& hostname, std::string& ip_address) const {
            auto it = dns_results.find(hostname);
            if (it != dns_results.end()) {
                ip_address = it->second;
                return true;
            }
            return false;
        }

        void add_content(const std::string& filename, const std::string& content) {
            file_contents[filename] = content;
        }

        void add_dns_result(const std::string& hostname, const std::string& ip_address) {
            dns_results[hostname] = ip_address;
        }
    };

    mutable Cache cache_;
    std::mutex mutex_;

    std::string processFiles() {
        std::vector<std::future<void>> futures;
        size_t file_count = 0;

        for (const auto& entry : fs::directory_iterator(dir_)) {
            if (++file_count > concurrent_threads_) break; // Limit concurrent tasks

            const auto& path = entry.path();
            if (!entry.is_regular_file() || path.extension() != ext_) continue;

            futures.push_back(std::async(std::launch::async, &DirectoryProcessor::processFile, this, path));
        }

        for (auto& future : futures) {
            try {
                future.get();
            } catch (...) {
                // Handle individual task exceptions if needed
            }
        }

        return concatenateResults();
    }

    void processFile(const fs::path& filepath) {
        std::string content;
        if (!cache_.get_content(filepath.string(), content)) {
            if (fs::file_size(filepath) > max_file_size_) {
                logger_->warn("Excluding large file: {}", filepath);
                return;
            }

            std::ifstream file(filepath, std::ios::binary | std::ios::ate);
            if (!file.is_open()) {
                logger_->error("Error opening file: {}", filepath);
                return;
            }

            size_t file_size = file.tellg();
            file.seekg(0);

            content.resize(buffer_size_ > 0 ? buffer_size_ : static_cast<size_t>(file_size));
            file.read(&content[0], content.size());
            cache_.add_content(filepath.string(), content);
        }

        std::string resolved_hostnames;
        resolveHostnames(content, resolved_hostnames);
    }

    void resolveHostnames(const std::string& content, std::string& output) {
        std::istringstream stream(content);
        std::string line;

        while (std::getline(stream, line)) {
            if (auto it = cache_.get_dns_result(line); !it.second.empty()) {
                output += "Resolved: " + line + " -> " + it.second + "\n";
            } else {
                asio::io_context io_context;
                asio::ip::tcp::resolver resolver(io_context);
                auto endpoints = resolver.async_resolve(asio::buffer(line), [](const std::error_code&, const auto&) {});

                io_context.run();

                if (endpoints) {
                    output += "Resolved: " + line + " -> " + endpoints->endpoint().address().to_string() + "\n";
                    cache_.add_dns_result(line, endpoints->endpoint().address().to_string());
                } else {
                    logger_->error("Failed to resolve hostname: {}", line);
                }
            }
        }
    }

    std::string concatenateResults() {
        std::lock_guard<std::mutex> lock(mutex_);

        std::ostringstream result;
        for (const auto& [filename, content] : cache_.file_contents) {
            logger_->info("File processed: {}, Length: {}", filename, content.size());
            result << "Content from " << filename << ": " << content << "\n";
        }

        return result.str();
    }
};

int main() {
    try {
        DirectoryProcessor processor("/path/to/directory", ".txt", 1024 * 1024, 10 * 1024 * 1024, 5);
        std::string result = processor.readDirectoryAndResolveHostnames();
        std::cout << "Processed Results:\n" << result;
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }
    return 0;
}
```

