// Error codes
enum ErrorCode {
    SUCCESS = 0,
    DB_CONNECTION_FAILURE,
    LOG_FILE_WRITE_ERROR,
    PAYMENT_PROCESSING_FAILURE,
    UNDEFINED_ERROR
};

class TransactionRecorder {
public:
    virtual ~TransactionRecorder() = default;
    virtual ErrorCode record(const std::string& transaction) = 0;
};

class DatabaseRecorder : public TransactionRecorder {
private:
    std::mutex db_mutex;
    bool use_connection_pool;

public:
    DatabaseRecorder(bool pool_enabled) : use_connection_pool(pool_enabled) {}

    ErrorCode record(const std::string& transaction) override {
        std::lock_guard<std::mutex> lock(db_mutex);
        // Simulate database connection and recording
        if (!simulateDatabaseConnection()) {
            return DB_CONNECTION_FAILURE;
        }
        // Retry logic with delay
        for (int attempt = 0; attempt < 3; ++attempt) {
            try {
                simulateWriteToDatabase(transaction);
                return SUCCESS;
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
        return DB_CONNECTION_FAILURE;
    }

private:
    bool simulateDatabaseConnection() {
        // Simulate a connection failure
        return true; // or false to simulate failure
    }

    void simulateWriteToDatabase(const std::string& transaction) {
        if (transaction.empty()) throw std::runtime_error("Failed to write");
        // Actual database writing logic here
    }
};

class LogFileRecorder : public TransactionRecorder {
private:
    std::mutex log_mutex;
    std::ofstream log_file;

public:
    LogFileRecorder(const std::string& filename) {
        log_file.open(filename, std::ios::app);
        if (!log_file.is_open()) throw std::runtime_error("Failed to open log file");
    }

    ~LogFileRecorder() {
        if (log_file.is_open()) log_file.close();
    }

    ErrorCode record(const std::string& transaction) override {
        std::lock_guard<std::mutex> lock(log_mutex);
        for (int attempt = 0; attempt < 3; ++attempt) {
            try {
                log_file << transaction << std::endl;
                if (!log_file.good()) throw std::runtime_error("Failed to write");
                return SUCCESS;
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
        return LOG_FILE_WRITE_ERROR;
    }
};

class PaymentProcessorRecorder : public TransactionRecorder {
private:
    thread_local bool api_connected;

public:
    PaymentProcessorRecorder() : api_connected(false) {}

    ErrorCode record(const std::string& transaction) override {
        if (!simulateAPIConnection()) return PAYMENT_PROCESSING_FAILURE;
        // Retry logic with exponential backoff
        for (int attempt = 0; attempt < 3; ++attempt) {
            try {
                simulateProcessPayment(transaction);
                return SUCCESS;
            } catch (...) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << attempt)));
            }
        }
        return PAYMENT_PROCESSING_FAILURE;
    }

private:
    bool simulateAPIConnection() {
        // Simulate API connection
        api_connected = true; // or false to simulate failure
        return true;
    }

    void simulateProcessPayment(const std::string& transaction) {
        if (transaction.empty()) throw std::runtime_error("Failed to process payment");
        // Actual payment processing logic here
    }
};

class TransactionManager {
private:
    std::unique_ptr<TransactionRecorder> recorder;
    std::queue<std::string> transaction_queue;
    std::mutex queue_mutex;

public:
    void setRecorder(std::unique_ptr<TransactionRecorder> new_recorder) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        recorder = std::move(new_recorder);
    }

    ErrorCode recordTransaction(const std::string& event, const std::vector<std::string>& details) {
        std::stringstream ss;
        for (const auto& detail : details) {
            ss << detail << " ";
        }
        ss << event;

        std::lock_guard<std::mutex> lock(queue_mutex);
        transaction_queue.push(ss.str());

        if (!recorder) return UNDEFINED_ERROR;

        while (!transaction_queue.empty()) {
            const auto& transaction = transaction_queue.front();
            ErrorCode result = recorder->record(transaction);
            if (result != SUCCESS) {
                // Fallback mechanism
                static std::unique_ptr<LogFileRecorder> log_recorder;
                if (!log_recorder) log_recorder = std::make_unique<LogFileRecorder>("transactions.log");
                log_recorder->record(transaction);
            }
            transaction_queue.pop();
        }

        return SUCCESS;
    }
};

// Usage example
int main() {
    TransactionManager manager;
    manager.setRecorder(std::make_unique<DatabaseRecorder>(true));

    ErrorCode result = manager.recordTransaction("purchase", {"item1", "item2"});
    if (result != SUCCESS) {
        std::cerr << "Transaction recording failed with error code: " << result << std::endl;
    }

    return 0;
}
