class JSONHandler {
  constructor() {
    this.registry = {};
  }

  toJSON(data) {
    return JSON.stringify(data, (key, value) => {
      if (this.registry[key]) {
        return this.registry[key](value);
      }
      return value;
    });
  }

  fromJSON(jsonString, idKey = 'id') {
    const data = JSON.parse(jsonString);

    if (data[idKey] && this.registry[data[idKey]]) {
      const instance = new this.registry[data[idKey]]();
      for (const key in data) {
        if (key !== idKey) {
          instance[key] = data[key];
        }
      }
      return instance;
    }

    return data;
  }

  register(id, factoryFunction) {
    this.registry[id] = factoryFunction;
  }
}

async function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
  const module = require(moduleLabel);
  let results = [];
  let totalSuccess = 0;
  let totalFailures = 0;

  for (let i = 0; i < testLabels.length; i++) {
    const label = testLabels[i];
    const testFunction = testFunctions[i];
    const dataSource = dataSources[i] || (() => Promise.resolve());
    const cleanupFunction = cleanupFunctions[i] || (() => Promise.resolve());

    console.log(`Running test: ${label}`);

    let attempt = 0;
    const maxRetries = 3;
    const delayBetweenRetries = 1000;

    while (attempt <= maxRetries) {
      try {
        const startTime = performance.now();

        // Fetch data
        const data = await dataSource();

        // Reset mocking library
        blueslip.reset();

        // Run test
        await testFunction(data);

        // Log success
        console.log(`Test passed: ${label}`);
        totalSuccess++;
        break;
      } catch (error) {
        attempt++;

        if (attempt > maxRetries) {
          console.error(`Test failed after retries: ${label}`, error);
          totalFailures++;
        } else {
          console.warn(`Retrying test (${attempt}/${maxRetries}): ${label}`);
          await new Promise(resolve => setTimeout(resolve, delayBetweenRetries));
        }
      } finally {
        const endTime = performance.now();
        const timeTaken = endTime - startTime;
        results.push({ label, status: attempt > maxRetries ? 'failed' : 'passed', time: timeTaken });

        // Cleanup
        try {
          await cleanupFunction();
        } catch (cleanupError) {
          console.error(`Cleanup failed for test: ${label}`, cleanupError);
        }
      }
    }
  }

  // Generate report
  const averageTime = results.reduce((acc, result) => acc + result.time, 0) / results.length;
  console.log('Test Summary:');
  console.log(`Total Tests: ${results.length}`);
  console.log(`Successes: ${totalSuccess}`);
  console.log(`Failures: ${totalFailures}`);
  console.log(`Average Time per Test: ${averageTime.toFixed(2)} ms`);

  return { results, totalSuccess, totalFailures, averageTime };
}

// Caching mechanism
const cache = new Map();

function fetchWithCache(fetchFunction) {
  if (cache.has(fetchFunction.name)) {
    return Promise.resolve(cache.get(fetchFunction.name));
  }

  return fetchFunction().then(data => {
    cache.set(fetchFunction.name, data);
    return data;
  });
}

// JSON Schema Validation
const Ajv = require('ajv');
const ajv = new Ajv();

function validateJSONSchema(jsonData, schema) {
  const validate = ajv.compile(schema);
  if (!validate(jsonData)) {
    throw new Error(`JSON validation failed: ${ajv.errorsText(validate.errors)}`);
  }
}

// Custom serialization and deserialization
function serializeWithFormatting(data, options = {}) {
  return JSON.stringify(data, null, options.indentation || 2);
}

function deserializeWithOrdering(jsonString, order) {
  const data = JSON.parse(jsonString);
  const orderedData = {};

  if (order && Array.isArray(order)) {
    for (const key of order) {
      if (data[key] !== undefined) {
        orderedData[key] = data[key];
      }
    }
  }

  return { ...orderedData, ...data };
}
