Below is a C++ code snippet implementing the described functionality using various libraries for file operations, threading, and third-party tools integration:

```cpp
#include <iostream>
#include <filesystem>
#include <fstream>
#include <thread>
#include <mutex>
#include <vector>
#include <string>
#include <regex>
#include <cstdlib>

namespace fs = std::filesystem;

struct ConversionResult {
    int total;
    int failed;
};

class WebAppIntegration {
public:
    WebAppIntegration(const std::string& imageDir, const std::vector<std::string>& jsModules)
        : imageDirectory(imageDir), javascriptModules(jsModules) {}

    bool integrateAndConvert(std::function<void(int)> progressCallback) {
        try {
            auto images = listImageAssets();
            ConversionResult result;

            // Thread for rendering JavaScript modules
            std::thread jsThread(&WebAppIntegration::renderJavaScript, this);

            // Convert images using separate threads
            int imageCount = static_cast<int>(images.size());
            result.total = imageCount;
            std::vector<std::thread> conversionThreads;

            for (const auto& imagePath : images) {
                conversionThreads.emplace_back(&WebAppIntegration::convertImageToFormats, this, imagePath);
            }

            // Join threads
            jsThread.join();
            for (auto& thread : conversionThreads) {
                thread.join();
            }

            reportProgress(progressCallback, result);

            return result.failed == 0;
        } catch (const std::exception& e) {
            logError("An error occurred: " + std::string(e.what()));
            return false;
        }
    }

private:
    std::string imageDirectory;
    std::vector<std::string> javascriptModules;
    std::mutex mtx;

    std::vector<fs::path> listImageAssets() {
        std::vector<fs::path> images;
        for (const auto& entry : fs::directory_iterator(imageDirectory)) {
            if (isImageFile(entry.path())) {
                images.push_back(entry.path());
            }
        }
        return images;
    }

    bool isImageFile(const fs::path& path) {
        std::regex imageRegex(".*\\.(jpe?g|png|svg)$", std::regex_constants::icase);
        return std::regex_match(path.filename().string(), imageRegex);
    }

    void renderJavaScript() {
        // Simulated rendering of JavaScript modules
        for (const auto& module : javascriptModules) {
            std::lock_guard<std::mutex> lock(mtx);  // Ensure thread safety
            std::cout << "<script src='" << module << "'></script>\n";
        }
    }

    void convertImageToFormats(const fs::path& imagePath) {
        try {
            // Convert to PDF, PNG and SVG using third-party tools (pseudo-code)
            std::system(("convert_to_pdf " + imagePath.string()).c_str());
            std::system(("convert_to_png " + imagePath.string()).c_str());
            std::system(("convert_to_svg " + imagePath.string()).c_str());
        } catch (...) {
            logError("Failed to convert: " + imagePath.string());
        }
    }

    void reportProgress(std::function<void(int)> callback, const ConversionResult& result) {
        int progress = (result.total - result.failed) * 100 / result.total;
        callback(progress);
    }

    void logError(const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety
        std::cerr << message << '\n';
    }
};

int main() {
    WebAppIntegration integration("path/to/images", {"module1.js", "module2.js"});
    integration.integrateAndConvert([](int progress) {
        std::cout << "Progress: " << progress << "%\n";
    });

    return 0;
}
```

**Notes:**

- **Libraries Used**: The code uses C++17's `<filesystem>` for directory operations and `<thread>` for concurrency.
- **Third-party Tools**: External commands (`convert_to_pdf`, `convert_to_png`, etc.) are placeholders; you should replace these with actual command calls to third-party tools like ImageMagick or others.
- **Error Handling**: Errors during conversion are logged without stopping the entire process.
- **Concurrency**: JavaScript rendering and image conversions run on separate threads for parallel execution.
- **Progress Reporting**: A callback mechanism is used to report progress back to the caller.

