// Rate Limiter Class
class RateLimiter {
    private $rateLimit = 5;
    private $timeWindow = 60; // seconds

    public function __construct() {
        if (!isset($_SESSION['requests'])) {
            $_SESSION['requests'] = [];
        }
    }

    public function isAllowed($ip) {
        $currentTime = time();
        if (!isset($_SESSION['requests'][$ip])) {
            $_SESSION['requests'][$ip] = [];
        }

        // Filter out requests outside the time window
        $_SESSION['requests'][$ip] = array_filter(
            $_SESSION['requests'][$ip],
            function($timestamp) use ($currentTime, $this) {
                return ($currentTime - $timestamp) < $this->timeWindow;
            }
        );

        if (count($_SESSION['requests'][$ip]) >= $this->rateLimit) {
            return false;
        }

        $_SESSION['requests'][$ip][] = $currentTime;
        return true;
    }
}

