    global $oauthClient;

    try {
        if ($accessToken = $oauthClient->getAccessToken('authorization_code', ['code' => $code])) {
            $_SESSION['access_token'] = $accessToken;
            $_SESSION['token_expires_at'] = time() + $accessToken->getLifetime();
            return true;
        }
    } catch (Exception $e) {
        // Handle exceptions
    }

    return false;
}

// Update Clinic Status Function
function updateClinicStatus($clinicId, $status, $ipAddress) {
    global $pdo;

    if (!validateInput($clinicId, $status)) {
        return ['error' => 'Invalid input'];
    }

    $stmt = $pdo->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
    try {
        $stmt->execute([$status, $ipAddress, $clinicId]);
        return ['success' => true];
    } catch (Exception $e) {
        // Handle exceptions
        return ['error' => 'Database update failed'];
    }
}

// Calculate File Hash Function
function calculateFileHash($filePath, $chunkSize = 1024 * 1024) { // 1MB
    $hashContext = hash_init('sha256');
    $handle = fopen($filePath, "rb");

    while (!feof($handle)) {
        $data = fread($handle, $chunkSize);
        hash_update($hashContext, $data);
    }

    fclose($handle);
    return hash_final($hashContext);
}

// Validate Input Function
function validateInput($clinicId, $status) {
    if (!is_numeric($clinicId) || !in_array($status, ['open', 'closed'])) {
        return false;
    }
    return true;
}

