use std::env;
use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

fn create_unique_directory(base_name: &str) -> Result<(), String> {
    let env_path = Arc::new(Mutex::new(env::var("DIR_PATH").ok()));

    // Function to get a unique directory path
    fn generate_unique_dir(path: &Path, base_name: &str) -> PathBuf {
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)
            .unwrap_or_else(|_| Duration::from_secs(0))
            .as_secs();
        path.join(format!("{}_{}", base_name, timestamp))
    }

    // Attempt to acquire the environment variable
    if let Ok(mut env_path_guard) = env_path.lock() {
        let dir_path;

        if let Some(ref current_dir) = *env_path_guard {
            dir_path = Path::new(current_dir);

            // Ensure thread safety with a Mutex around directory operations
            fs::create_dir_all(&generate_unique_dir(dir_path, "run")).map_err(|e| e.to_string())?;

            log_operation(format!("Created subdirectory in existing path: {}", current_dir));

        } else {
            dir_path = generate_unique_dir(Path::new(base_name), base_name);

            // Create the new directory
            fs::create_dir_all(dir_path.clone()).map_err(|e| e.to_string())?;

            // Set the environment variable safely with thread lock
            env::set_var("DIR_PATH", dir_path.to_str().unwrap_or_default());

            log_operation(format!("Created new directory and set DIR_PATH: {}", dir_path.display()));
        }

        if let Some(ref current_dir) = *env_path_guard {
            // Delete the temporary subdirectory after logging
            let temp_subdir = generate_unique_dir(Path::new(current_dir), "run");
            fs::remove_dir_all(&temp_subdir).ok();
        }

    } else {
        return Err("Failed to acquire environment variable lock".to_string());
    }

    Ok(())
}

fn log_operation(message: String) -> Result<(), std::io::Error> {
    let mut file = fs::OpenOptions::new()
        .append(true)
        .create(true)
        .open("directory_creation.log")?;

    writeln!(file, "{}", message)?;
    Ok(())
}

fn main() {
    match create_unique_directory("my_base_directory") {
        Ok(_) => println!("Directory operation completed successfully."),
        Err(e) => eprintln!("Error: {}", e),
    }
}
