#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "json-c/json.h"

// Function to verify OAuth2 access token response JSON object
int is_valid_token_response(const char *json_str) {
    struct json_object *parsed_json, *access_token, *expires_in, *token_type, *refresh_token;
    parsed_json = json_tokener_parse(json_str);

    if (!parsed_json) return 0; // Invalid JSON

    access_token = json_object_object_get(parsed_json, "access_token");
    expires_in = json_object_object_get(parsed_json, "expires_in");
    token_type = json_object_object_get(parsed_json, "token_type");

    if (!access_token || !expires_in || !token_type) return 0; // Missing required fields

    char *type_str;
    type_str = (char *)json_object_get_string(token_type);

    if (strcmp(type_str, "Bearer") != 0) return 0; // Invalid token_type

    if (!json_object_is_type(expires_in, json_type_int) || 
        json_object_get_int(expires_in) <= 0) {
        return 0; // expires_in is not a positive integer
    }

    // Optional field: refresh_token can be ignored for validation purposes
    refresh_token = json_object_object_get(parsed_json, "refresh_token");

    json_object_put(parsed_json); // Clean up the JSON object

    return 1; // Valid token response
}
