import java.util.concurrent.Executors;
import java.util.logging.Logger;
import javax.json.bind.Jsonb;
import javax.json.bind.JsonbBuilder;

public class SecurePasswordManager {

    private static final Logger logger = Logger.getLogger(SecurePasswordManager.class.getName());
    private int saltRounds;
    private Map<String, FactoryFunction> registry = new ConcurrentHashMap<>();

    public SecurePasswordManager(int saltRounds) {
        this.saltRounds = saltRounds;
    }

    // Generate a random string
    public String generateRandomString(int length) {
        String characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        StringBuilder result = new StringBuilder(length);
        Random rnd = new Random();
        for (int i = 0; i < length; i++)
            result.append(characters.charAt(rnd.nextInt(characters.length())));
        return result.toString();
    }

    // Hash a password
    public String hashPassword(String password) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashedBytes = md.digest(password.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // Verify a password against its hash
    public boolean verifyPassword(String password, String hashedPassword) throws NoSuchAlgorithmException {
        return hashPassword(password).equals(hashedPassword);
    }

    // Validate character sets in the password
    public boolean validateCharacterSet(String password, char[] validChars) {
        for (char c : password.toCharArray()) {
            boolean valid = false;
            for (char validChar : validChars) {
                if (c == validChar) {
                    valid = true;
                    break;
                }
            }
            if (!valid) return false;
        }
        return true;
    }

