```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using System.Net.Http;
using System.Threading.Tasks;

public class WeatherDataFetcher
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly string _apiKey;
    private readonly string _apiEndpoint;
    private Dictionary<string, string> _cache;
    private int _requestCount;
    private int _cacheHitCount;
    private int _networkTimeouts;

    public WeatherDataFetcher(string configFilePath)
    {
        var config = LoadConfig(configFilePath);
        _apiKey = config["ApiKey"];
        _apiEndpoint = config["ApiEndpoint"];
        _cache = new Dictionary<string, string>();
    }

    public float RandomValueInRange(float min, float max, bool inclusiveMax)
    {
        return inclusiveMax ? UnityEngine.Random.Range(min, max) : UnityEngine.Random.Range(min, max - 0.0001f);
    }

    public List<int> GenerateUniqueRandomIntList(int size, int minValue, int maxValue)
    {
        if (size > (maxValue - minValue + 1))
            throw new ArgumentException("Size is too large for the specified range without duplicates.");

        var randomNumbers = new HashSet<int>();
        while (randomNumbers.Count < size)
        {
            randomNumbers.Add(UnityEngine.Random.Range(minValue, maxValue));
        }
        return randomNumbers.ToList();
    }

    public async Task<string> FetchWeatherDataFromAPI(double latitude, double longitude)
    {
        _requestCount++;
        var cacheKey = $"{latitude}_{longitude}";

        if (_cache.TryGetValue(cacheKey, out string cachedResponse))
        {
            _cacheHitCount++;
            return cachedResponse;
        }

        try
        {
            var responseString = await FetchWeatherDataFromAPI_TestDouble(latitude, longitude);
            _cache[cacheKey] = responseString;
            return responseString;
        }
        catch (TaskCanceledException)
        {
            _networkTimeouts++;
            throw new TimeoutException("Network timeout occurred while fetching weather data.");
        }
    }

    private async Task<string> FetchWeatherDataFromAPI_TestDouble(double latitude, double longitude)
    {
        // Simulating API call
        await Task.Delay(100);  // Simulate network delay
        return "{\"status\":\"success\",\"data\":\"Mocked Weather Data\"}";  // Mocked response
    }

    public override string ToString()
    {
        return $"Requests Made: {_requestCount}, Cache Hits: {_cacheHitCount}, Network Timeouts: {_networkTimeouts}";
    }

    private Dictionary<string, string> LoadConfig(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("Configuration file not found.");

        var config = new Dictionary<string, string>();
        foreach (var line in File.ReadAllLines(filePath))
        {
            var parts = line.Split('=');
            if (parts.Length != 2) continue;
            config[parts[0].Trim()] = parts[1].Trim();
        }

        return config;
    }
}
