<?php

define('ENV', getenv('APP_ENV') ?: 'development');
define('API_URL', 'https://api.example.com/configurations');

/**
 * Fetch configuration from external API with caching.
 */
function fetchConfiguration() {
    $cacheKey = "config_" . ENV;
    $cachedConfig = getCachedConfig($cacheKey);

    if ($cachedConfig) {
        return json_decode($cachedConfig, true);
    }

    try {
        $response = makeApiRequest(API_URL . '/' . ENV);

        if ($response && is_array($response)) {
            cacheConfiguration($cacheKey, json_encode($response));
            logAction("Fetched configuration for " . ENV);
            return $response;
        } else {
            throw new Exception("Invalid API response.");
        }
    } catch (Exception $e) {
        logError($e->getMessage());

        // Fallback to default configurations or cached data
        if ($cachedConfig) {
            logAction("Using cached configuration for " . ENV);
            return json_decode($cachedConfig, true);
        }

        return getDefaultConfiguration();
    }
}

/**
 * Make an API request with error handling.
 */
function makeApiRequest($url) {
    $ch = curl_init();

    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 5); // Handle network latency

    $response = curl_exec($ch);

    if (curl_errno($ch)) {
        throw new Exception('API request failed: ' . curl_error($ch));
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

    if ($httpCode !== 200) {
        throw new Exception("Received non-200 HTTP response code: " . $httpCode);
    }

    curl_close($ch);

    return json_decode($response, true);
}

/**
 * Cache configuration data.
 */
function cacheConfiguration($key, $data) {
    $cacheTTL = 300; // Cache for 5 minutes
    setCache($key, $data, $cacheTTL);
}

/**
 * Retrieve cached configuration.
 */
function getCachedConfig($key) {
    return getCache($key);
}

/**
 * Get default configurations if all else fails.
 */
function getDefaultConfiguration() {
    return [
        'db_host' => 'localhost',
        'db_name' => 'default_db',
        'log_level' => 'error'
    ];
}

/**
 * Log actions and errors for monitoring purposes.
 */
function logAction($message) {
    error_log("[ACTION] " . date('Y-m-d H:i:s') . ": " . $message);
}

function logError($message) {
    error_log("[ERROR] " . date('Y-m-d H:i:s') . ": " . $message);
}

/**
 * Cache storage function implementations.
 */
