import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.KafkaConsumer;

import java.io.IOException;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

public class LogProcessor {
    private final KafkaConsumer<String, String> consumer;
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final Map<String, Function<JsonNode, Object>> metricExtractors = new HashMap<>();
    private final Cache cache = new SimpleCache();

    public LogProcessor(String kafkaBrokers, String topic) {
        Properties props = new Properties();
        props.put("bootstrap.servers", kafkaBrokers);
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        this.consumer = new KafkaConsumer<>(props);
        consumer.subscribe(Collections.singletonList(topic));
    }

    public void registerMetricExtractor(String metricName, Function<JsonNode, Object> extractor) {
        metricExtractors.put(metricName, extractor);
    }

    public void processLogs() {
        while (true) {
            for (ConsumerRecord<String, String> record : consumer.poll(Duration.ofMillis(100))) {
                try {
                    JsonNode log = objectMapper.readTree(record.value());
                    Map<String, Object> metrics = extractMetrics(log);

                    cache.put(record.key(), metrics);
                    checkAlerts(metrics);
                } catch (IOException e) {
                    handleMalformedLog(e, record);
                }
            }
        }
    }

    private Map<String, Object> extractMetrics(JsonNode log) throws IOException {
        Map<String, Object> extractedMetrics = new HashMap<>();
        for (Map.Entry<String, Function<JsonNode, Object>> entry : metricExtractors.entrySet()) {
            try {
                extractedMetrics.put(entry.getKey(), entry.getValue().apply(log));
            } catch (Exception e) {
                System.err.println("Error extracting metric: " + entry.getKey() + ", skipping.");
            }
        }
        return extractedMetrics;
    }

    private void checkAlerts(Map<String, Object> metrics) {
        // Implement alerting logic based on predefined thresholds
        // For example:
        if (metrics.containsKey("responseTime") && (long) metrics.get("responseTime") > 1000) {
            System.out.println("Alert: High response time detected!");
        }
    }

    private void handleMalformedLog(Exception e, ConsumerRecord<String, String> record) {
        System.err.println("Failed to process log with key " + record.key() + ": " + e.getMessage());
        // Optionally implement retry logic or dead-letter queue handling
    }

    public static void main(String[] args) {
        LogProcessor processor = new LogProcessor("localhost:9092", "logs");

        // Register metric extractors
        processor.registerMetricExtractor("responseTime", log -> log.path("responseTime").asLong());
        processor.registerMetricExtractor("status", log -> log.path("status").asInt());

        processor.processLogs();
    }

    interface Cache {
        void put(String key, Map<String, Object> metrics);
        Map<String, Object> get(String key);
    }

    static class SimpleCache implements Cache {
        private final ConcurrentHashMap<String, Map<String, Object>> cache = new ConcurrentHashMap<>();

        @Override
        public void put(String key, Map<String, Object> metrics) {
            cache.put(key, metrics);
        }

        @Override
        public Map<String, Object> get(String key) {
            return cache.getOrDefault(key, Collections.emptyMap());
        }
    }
}
