package configurable_component;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

public abstract class ConfigurableComponent {
    private static final Map<String, Supplier<ConfigurableComponent>> factoryRegistry = new ConcurrentHashMap<>();
    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static void registerFactory(String id, Supplier<ConfigurableComponent> supplier) {
        factoryRegistry.put(id, supplier);
    }

    public static ConfigurableComponent createFromJsonString(String jsonString, String id) throws IOException {
        Map<String, Object> configMap = objectMapper.readValue(jsonString, new TypeReference<Map<String, Object>>() {});
        Supplier<ConfigurableComponent> factory = factoryRegistry.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No registered factory for ID: " + id);
        }
        return factory.get();
    }

    public static void discoverSubclasses(String directory) throws IOException {
        Files.walk(Paths.get(directory))
                .filter(Files::isRegularFile)
                .forEach(path -> {
                    try {
                        String className = path.toString().replace(".class", "").replace("/", ".");
                        Class<?> clazz = Class.forName(className);
                        if (ConfigurableComponent.class.isAssignableFrom(clazz)) {
                            Supplier<ConfigurableComponent> supplier = () -> {
                                try {
                                    return (ConfigurableComponent) clazz.getConstructor(Map.class).newInstance(objectMapper.convertValue(Collections.emptyMap(), new TypeReference<Map<String, Object>>() {}));
                                } catch (Exception e) {
                                    throw new RuntimeException("Failed to instantiate component", e);
                                }
                            };
                            String id = clazz.getSimpleName();
                            factoryRegistry.putIfAbsent(id.toLowerCase(), supplier);
                        }
                    } catch (ClassNotFoundException | InstantiationException | IllegalAccessException | NoSuchMethodException e) {
                        // Handle error appropriately
                    }
                });
    }

    public void loadConfiguration(String filePath) throws IOException {
        Map<String, Object> configMap = objectMapper.readValue(new File(filePath), new TypeReference<Map<String, Object>>() {});
        initialize(configMap);
    }

    public void saveConfiguration(String filePath) throws IOException {
        Map<String, Object> configMap = extractConfig();
        objectMapper.writeValue(new File(filePath), configMap);
    }

    protected abstract void initialize(Map<String, Object> config);

    protected abstract Map<String, Object> extractConfig();

    // Example usage of integrating with external system
    public static void loadFactoriesFromExternalSystem(String apiUrl) {
        try {
            String response = ""; // Call the API and get the response
            List<Map<String, String>> factories = objectMapper.readValue(response, new TypeReference<List<Map<String, String>>>(){});
            for (Map<String, String> factory : factories) {
                String id = factory.get("id");
                String className = factory.get("className");
                Class<?> clazz = Class.forName(className);
                Supplier<ConfigurableComponent> supplier = () -> {
                    try {
                        return (ConfigurableComponent) clazz.getConstructor(Map.class).newInstance(Collections.emptyMap());
                    } catch (Exception e) {
                        throw new RuntimeException("Failed to instantiate component", e);
                    }
                };
                factoryRegistry.putIfAbsent(id.toLowerCase(), supplier);
            }
        } catch (IOException | ClassNotFoundException | InstantiationException | IllegalAccessException | NoSuchMethodException e) {
            // Handle error appropriately
        }
    }

    public static void saveRegistryState(String filePath) throws IOException {
        Map<String, String> registryState = new HashMap<>();
        for (Map.Entry<String, Supplier<ConfigurableComponent>> entry : factoryRegistry.entrySet()) {
            registryState.put(entry.getKey(), entry.getValue().getClass().getName());
        }
        objectMapper.writeValue(new File(filePath), registryState);
    }

    // Clean-up method to be called periodically
    public static void cleanupUnusedFactories() {
        // Implement logic to remove unused factories based on inactivity or other criteria
    }
}

// Example subclass registration and usage
