    public function handleClinicOperations($operationType, $clinicData) {
        // Check rate limiting
        if (!$this->checkRateLimit($_SERVER['REMOTE_ADDR'])) {
            throw new Exception("Rate limit exceeded");
        }

        switch ($operationType) {
            case 'create':
                $this->createClinicRecord($clinicData);
                break;

            case 'update':
                $this->updateClinicStatus($clinicData);
                break;

            case 'delete':
                $this->deleteClinicRecord($clinicData['id']);
                break;

            default:
                throw new Exception("Invalid operation type");
        }
    }

    private function createClinicRecord($data) {
        if (strlen($data['name']) > 50 || in_array(strtolower($data['name']), $this->getProhibitedTerms())) {
            throw new Exception("Invalid clinic name");
        }

        $stmt = $this->db->prepare("INSERT INTO clinics (name, location, capacity) VALUES (?, ?, ?)");
        if (!$stmt->execute([$data['name'], $data['location'], $data['capacity']])) {
            throw new Exception("Database error during creation");
        }
    }

    private function updateClinicStatus($data) {
        $status = $data['status'];
        $id = $data['id'];

        if ($status === 'closed' || $status === 'emergency') {
            $this->handleClosureOperations($id);
        }

        $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
        if (!$stmt->execute([$status, $_SERVER['REMOTE_ADDR'], $id])) {
            throw new Exception("Database error during update");
        }
