        $retryCount = 0;
        while ($retryCount < $this->retryAttempts) {
            try {
                $stmt = $this->db->prepare("DELETE FROM clinics WHERE id = ?");
                if (!$stmt->execute([$clinicId])) {
                    throw new Exception("Database error during deletion");
                }

                // Notify patients
                $affectedPatients = $this->schedulingSystemClient->getAffectedPatients($clinicId);
                foreach ($affectedPatients as $patient) {
                    $alternatives = $this->findNearbyClinics($patient['location']);
                    $this->notificationService->sendNotification($patient, $alternatives);
                }
                break;
            } catch (Exception $e) {
                // Log and retry with exponential backoff
                error_log("Error deleting clinic: " . $e->getMessage());
                sleep(pow(2, $retryCount)); 
                $retryCount++;
            }
        }

        if ($retryCount == $this->retryAttempts) {
            throw new Exception("Failed to delete clinic record after multiple attempts");
        }
    }

