#include <iostream>
#include <string>
#include <chrono>
#include <thread>
#include "WebSocket.hpp"  // Assume this is a WebSocket library that supports TLS

class SecureWebSocket {
public:
    SecureWebSocket(const std::string& server_url, const std::string& client_cert,
                    const std::string& private_key, const std::string& pre_shared_key)
        : server_url_(server_url), client_cert_(client_cert),
          private_key_(private_key), pre_shared_key_(pre_shared_key) {}

    bool initialize() {
        try {
            // Initialize WebSocket context with TLS 1.3 settings
            ws_context_ = std::make_unique<WebSocketContext>(TLS_VERSION_1_3, true);
            ws_context_->set_client_cert(client_cert_, private_key_);
            ws_context_->use_psk(pre_shared_key_);

            if (!ws_context_->connect(server_url_)) {
                throw std::runtime_error("Failed to connect");
            }

            std::cout << "WebSocket connection established\n";
            return true;
        } catch (const std::exception& e) {
            std::cerr << "Initialization error: " << e.what() << '\n';
            return false;
        }
    }

    void send_message(const std::string& message) {
        try {
            ws_context_->send(message);
            std::cout << "Message sent: " << message << "\n";
        } catch (const std::exception& e) {
            std::cerr << "Send error: " << e.what() << '\n';
            reconnect();
        }
    }

    void receive_message() {
        try {
            std::string message = ws_context_->receive();
            if (!message.empty()) {
                std::cout << "Message received: " << message << "\n";
            }
        } catch (const WebSocketException& e) { // Assume this is a specific exception
            if (e.code() == WebSocketErrorCode::ConnectionClosed) {
                reconnect();
            } else {
                std::cerr << "Receive error: " << e.what() << '\n';
            }
        }
    }

    void maintain_heartbeat() {
        while (!stop_heartbeat_) {
            send_message("ping");
            std::this_thread::sleep_for(std::chrono::seconds(30));
        }
    }

    void reconnect() {
        if (ws_context_->is_connected()) {
            ws_context_->close();
        }

        std::cout << "Reconnecting...\n";
        initialize();
    }

    void start_heartbeat() {
        stop_heartbeat_ = false;
        heartbeat_thread_ = std::thread(&SecureWebSocket::maintain_heartbeat, this);
    }

    void stop_heartbeat() {
        stop_heartbeat_ = true;
        if (heartbeat_thread_.joinable()) {
            heartbeat_thread_.join();
        }
    }

    void cleanup() {
        if (ws_context_->is_connected()) {
            ws_context_->close();
        }

        std::cout << "Cleaning up resources\n";
        stop_heartbeat_ = true;
    }

private:
    std::string server_url_;
    std::string client_cert_;
    std::string private_key_;
    std::string pre_shared_key_;
    bool stop_heartbeat_ = false;
    std::thread heartbeat_thread_;
    std::unique_ptr<WebSocketContext> ws_context_;  // Assume WebSocketContext is part of the library
};

int main() {
    SecureWebSocket sWs("wss://example.com", "client_cert.pem", "private_key.pem", "psk");

    if (sWs.initialize()) {
        sWs.start_heartbeat();

        // Send and receive messages
        sWs.send_message("Hello, WebSocket!");
        while (true) {  // Simulate a running service
            sWs.receive_message();
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    }

    // Cleanup resources before exit
    sWs.stop_heartbeat();
    sWs.cleanup();

    return 0;
}
```

