<?php

class DAO {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        try {
            $this->pdo = new PDO($dsn, $username, $password);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            // Handle connection error
        }
    }

    public function updateUserPassword($userId, $newPassword) {
        try {
            // Begin transaction
            $this->pdo->beginTransaction();

            // Validate password
            if (!$this->validatePassword($newPassword)) {
                throw new Exception("Password validation failed.");
            }

            // Check rate limit
            if (!$this->checkRateLimit($userId)) {
                throw new Exception("Rate limit exceeded.");
            }

            // Update password in database
            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $stmt->execute([':password' => $hashedPassword, ':id' => $userId]);

            // Log the update attempt
            $this->logAttempt($userId, true);

            // Commit transaction
            $this->pdo->commit();

        } catch (Exception $e) {
            // Rollback transaction on failure
            $this->pdo->rollBack();
            $this->logAttempt($userId, false, $e->getMessage());

            // Retry logic with exponential backoff
            for ($retry = 1; $retry <= 3; $retry++) {
                sleep(pow(2, $retry));
                try {
                    return $this->updateUserPassword($userId, $newPassword);
                } catch (Exception $re) {
                    if ($retry == 3) {
                        return "Error: " . $re->getMessage();
                    }
                }
            }
        }
    }

    private function validatePassword($password, $username) {
        if (strlen($password) < 8 ||
            !preg_match('/[A-Z]/', $password) ||
            !preg_match('/[a-z]/', $password) ||
            !preg_match('/\d/', $password) ||
            !preg_match('/[\!\@\#\$\%\^\&\*]/', $password) ||
            strpos($password, $username) !== false) {
            return false;
        }
        return true;
    }

    private function checkRateLimit($userId) {
