int encrypt_aes(const unsigned char *plaintext, int plaintext_len,
                const unsigned char *key, const unsigned_char *iv,
                unsigned char *ciphertext, int *ciphertext_len) {

    aes_ctx *aes = malloc(sizeof(aes_ctx));
    if (!aes || !(aes->ctx = EVP_CIPHER_CTX_new())) {
        handle_error(1);
        return 0;
    }

    if (EVP_EncryptInit_ex(aes->ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        handle_error(2);
        EVP_CIPHER_CTX_free(aes->ctx);
        free(aes);
        return 0;
    }

    int len;
    if (EVP_EncryptUpdate(aes->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        handle_error(3);
        EVP_CIPHER_CTX_free(aes->ctx);
        free(aes);
        return 0;
    }
    *ciphertext_len = len;

    int plaintext_len_final;
    if (EVP_EncryptFinal_ex(aes->ctx, ciphertext + len, &plaintext_len_final) != 1) {
        handle_error(4);
        EVP_CIPHER_CTX_free(aes->ctx);
        free(aes);
        return 0;
    }
    *ciphertext_len += plaintext_len_final;

    EVP_CIPHER_CTX_free(aes->ctx);
    free(aes);

    return 1;
}

