async fn runTests(
    moduleLabel: String,
    testLabels: Vec<String>,
    testFunctions: Vec<impl FnOnce() -> task::JoinHandle<Result<(), ()>> + Send + Sync>,
    cleanupFunction: impl FnOnce(PathBuf) + Send + 'static
) {
    let mod_path = format!("path/to/modules/{}.rs", moduleLabel);
    // Simulating require with loading a module (this part would be async as well)

    let paths: Vec<PathBuf> = testLabels.iter().map(|label| {
        PathBuf::from(format!("./test_results/{}", label))
    }).collect();

    let mut handles = vec![];

    for (i, test_fn) in testFunctions.into_iter().enumerate() {
        let path = &paths[i];

        // Ensure atomic directory creation
        tokio::fs::create_dir_all(path.clone()).await.unwrap_or_else(|e| {
            error!("Failed to create directory: {:?}", e);
        });

        handles.push(test_fn());
    }

    for handle in handles {
        match handle.await {
            Ok(()) => info!("Test passed"),
            Err(_) => error!("Test failed"),
        }
    }

    let env_var = std::env::var("TARGET_DIR").unwrap_or_default();
    if !paths.iter().any(|p| p.to_string_lossy() == env_var) {
        cleanupFunction(paths[0].clone());
    }
}

async fn cleanup_function(path: PathBuf) {
    // Implementation of directory removal, keeping only the most recent
    let directories = async_fs::read_dir("./test_results").await.unwrap();
    let mut dir_entries: Vec<PathBuf> = vec![];

    for entry in directories {
        if let Ok(entry) = entry {
            let path = entry.path();
            if path.is_dir() {
                dir_entries.push(path);
            }
        }
    }

    // Sort by last modified time, keep the most recent
    dir_entries.sort_by_key(|p| async_fs::metadata(p).await.unwrap().modified().unwrap());

    for path in &dir_entries[1..] {  // Keep only the first (most recent)
        if let Err(e) = async_fs::remove_dir_all(path).await {
            error!("Failed to remove directory {:?}: {:?}", path, e);
        }
    }

    info!("Cleanup completed");
}
```

