```cpp
#include <iostream>
#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& firstStr, const std::string& secondStr) {
    auto it = flist.before_begin();
    bool found = false;

    for (auto next_it = flist.begin(); next_it != flist.end(); ++next_it) {
        if (*next_it == firstStr) {
            flist.insert_after(next_it, secondStr);
            found = true;
            break;
        }
        it = next_it;
    }

    if (!found) {
        flist.insert_after(it, secondStr);
    }
}

int main() {
    std::forward_list<std::string> myFList = {"apple", "banana", "cherry"};
    insertAfterFirstOccurrence(myFList, "banana", "date");

    for (const auto& str : myFList) {
        std::cout << str << " ";
    }

    return 0;
}
```

