    size_t num_states;
    pthread_mutex_t lock;
} StateList;

typedef struct {
    // Define transitions and state definitions as needed
    int dummy_transition_data;  // Placeholder for transition rules
} FSA;

// Function to expand the state list
void expandStateList(int **state_list, size_t *num_states, FSA *fsa, void *external_source, int last_state) {
    pthread_mutex_lock(&fsa->lock);

    // Simulate external data loading (e.g., from a file or network)
    int new_states[10];  // Placeholder for loaded states
    size_t num_new_states = 5;  // Assume we load 5 new states

    // Check if memory allocation is needed
    *state_list = realloc(*state_list, (*num_states + num_new_states) * sizeof(int));
    if (!*state_list) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&fsa->lock);
        return;
    }

    // Validate and add new states
    for (size_t i = 0; i < num_new_states; ++i) {
        int state_to_add = new_states[i];

        // Simulate state validation
        if (state_to_add > last_state) {  // Simple validation rule
            (*state_list)[*num_states] = state_to_add;
            (*num_states)++;
        }
    }

    // Log the expansion process
    printf("Expanded state list to %zu states\n", *num_states);

    pthread_mutex_unlock(&fsa->lock);
}

// Function to initialize the FSA structure and its mutex
void initFSA(FSA *fsa) {
    fsa->dummy_transition_data = 0;
    pthread_mutex_init(&fsa->lock, NULL);
}

// Example function to clean up resources
void cleanupFSA(StateList *state_list) {
    free(state_list->states);
    pthread_mutex_destroy(&state_list->lock);
}

int main() {
    // Initialize FSA and state list
    FSA fsa;
    initFSA(&fsa);

    StateList state_list = {NULL, 0};
    state_list.states = malloc(10 * sizeof(int));  // Initial allocation
    if (!state_list.states) {
        perror("Failed to allocate initial memory");
        return EXIT_FAILURE;
    }
    state_list.num_states = 0;

    pthread_mutex_init(&state_list.lock, NULL);

    // Simulate expanding the state list
    expandStateList(&state_list.states, &state_list.num_states, &fsa, NULL, -1);

    // Clean up resources
    cleanupFSA(&state_list);
    return EXIT_SUCCESS;
}
