import json
import requests
from datetime import datetime, timedelta
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError
import argparse

# Constants for token management
TOKEN_FILE = 'token.json'
API_URL = 'https://api.example.com/token'

def save_token_to_file(token):
    with open(TOKEN_FILE, 'w') as f:
        json.dump({'access_token': token['access_token'], 'expires_at': token['expires_at']}, f)

def load_token_from_file():
    try:
        with open(TOKEN_FILE, 'r') as f:
            data = json.load(f)
            return {'access_token': data['access_token'], 'expires_at': data['expires_at']}
    except FileNotFoundError:
        return None

def is_token_expired(token):
    expires_at = datetime.fromisoformat(token['expires_at'])
    return datetime.now() >= expires_at

def request_new_token():
    response = requests.post(API_URL, json={'grant_type': 'client_credentials'})
    if response.status_code == 200:
        token_data = response.json()
        token_data['expires_at'] = (datetime.now() + timedelta(seconds=token_data['expires_in'])).isoformat()
        save_token_to_file(token_data)
        return token_data
    else:
        raise Exception("Failed to retrieve new token")

def get_access_token():
    token = load_token_from_file()
    if not token or is_token_expired(token):
        return request_new_token()
    return token

# Argon2 password hashing and verification
class PasswordManager:
    def __init__(self, time_cost=2, memory_cost=102400, parallelism=8, hash_len=16, salt_len=16):
        self.ph = PasswordHasher(
            time_cost=time_cost,
            memory_cost=memory_cost,
            parallelism=parallelism,
            hash_len=hash_len,
            salt_len=salt_len
        )

    def hash_password(self, password):
        return self.ph.hash(password)

    def verify_password(self, hashed, password):
        try:
            self.ph.verify(hashed, password)
            return True
        except VerifyMismatchError:
            return False

def test_token_management():
    token = get_access_token()
    assert 'access_token' in token and 'expires_at' in token
    print("Token management tests passed.")

def test_password_manager():
    pm = PasswordManager()
    password = "securepassword123"
    hashed = pm.hash_password(password)

    # Test correct password verification
    assert pm.verify_password(hashed, password)

    # Test incorrect password verification
    assert not pm.verify_password(hashed, "wrongpassword")

    print("Password manager tests passed.")

def main():
    parser = argparse.ArgumentParser(description="Test token and password management.")
    parser.add_argument('--test-token', action='store_true', help='Run token management tests')
    parser.add_argument('--test-password', action='store_true', help='Run password manager tests')

    args = parser.parse_args()

    if args.test_token:
        test_token_management()

    if args.test_password:
        test_password_manager()

if __name__ == "__main__":
    main()
```

Below is a modular JavaScript application that addresses your requirements. It dynamically loads external scripts, integrates an API for updates, manages dependencies, handles errors robustly, and includes semaphore management.

```javascript
// External API integration and dynamic script loader
class DynamicScriptLoader {
  constructor(apiEndpoint) {
    this.apiEndpoint = apiEndpoint;
    this.loadedScripts = new Set();
    this.dependencyMap = new Map(); // Maps script to its dependencies
  }

  async fetchScriptList() {
    try {
      const response = await fetch(this.apiEndpoint);
      if (!response.ok) throw new Error('Network response was not ok');
      return response.json(); // Assuming JSON format: [{ name: 'script1.js', url: '...' }, ...]
    } catch (error) {
      console.error('Error fetching script list:', error);
      return [];
    }
  }

  async loadScript(scriptName, scriptUrl) {
    if (this.loadedScripts.has(scriptName)) return;

    try {
      const script = document.createElement('script');
      script.src = scriptUrl;
      script.async = true;
      script.onload = () => this.onLoadSuccess(scriptName);
      script.onerror = () => this.onLoadError(scriptName);

      // Check dependencies before loading
      if (this.dependencyMap.has(scriptName)) {
        for (const dependency of this.dependencyMap.get(scriptName)) {
          await this.loadScript(dependency, `https://example.com/${dependency}.js`);
        }
      }

      document.head.appendChild(script);
    } catch (error) {
      console.error(`Error loading script ${scriptName}:`, error);
    }
  }

  onLoadSuccess(scriptName) {
    console.log(`Successfully loaded: ${scriptName}`);
    this.loadedScripts.add(scriptName);
  }

  onLoadError(scriptName) {
    console.error(`Failed to load: ${scriptName}. Attempting fallback.`);
    // Fallback logic if needed
  }

  async initialize() {
    const scripts = await this.fetchScriptList();
    for (const script of scripts) {
      this.dependencyMap.set(script.name, script.dependencies || []);
    }
    for (const script of scripts) {
      await this.loadScript(script.name, script.url);
    }
  }
}

// Semaphore management
class ThreadSafeSemaphore {
  constructor(initialCount) {
    this.count = initialCount;
    this.waitingList = [];
  }

  async acquire() {
    if (this.count > 0) {
      this.count -= 1;
      return true;
    } else {
      await this.waitForAvailableSlot();
      this.count -= 1;
      return false; // Acquired after waiting
    }
  }

  release() {
    this.count += 1;
    if (this.waitingList.length > 0) {
      const resolve = this.waitingList.shift().resolve;
      resolve(true);
    }
  }

  async waitForAvailableSlot() {
    return new Promise(resolve => {
      this.waitingList.push({ resolve });
    });
  }

  currentValue() {
    return this.count;
  }
}

// Logger
class Logger {
  static log(message) {
    console.log(`[${new Date().toISOString()}] ${message}`);
  }

  static error(error) {
    console.error(`[${new Date().toISOString()}] ERROR:`, error);
  }
}

// Example initialization and usage
(async function main() {
  const loader = new DynamicScriptLoader('https://api.example.com/scripts');
  await loader.initialize();

  const semaphore = new ThreadSafeSemaphore(3); // Initial value of 3

  try {
    Logger.log('Starting script loading with semaphore management');

    for (let i = 0; i < 5; i++) {
      const acquireResult = await semaphore.acquire();
      if (acquireResult) {
        Logger.log(`Script load initiated: ${i}`);
        // Simulate a script execution
        setTimeout(() => {
          Logger.log(`Script completed: ${i}`);
          semaphore.release();
        }, Math.random() * 2000);
      } else {
        Logger.error('Failed to acquire semaphore');
      }
    }

  } catch (error) {
    Logger.error(error);
  }
})();
```

### Key Components:
