using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicTextProcessor
{
    private static readonly HttpClient httpClient = new HttpClient();
    private readonly ConcurrentDictionary<string, Func<byte[], string>> hashAlgorithms;
    private const long MaxInputSize = 1_000_000_000; // 1GB

    public LogLevel CurrentLogLevel { get; set; } = LogLevel.Info;

    public DynamicTextProcessor()
    {
        hashAlgorithms = new ConcurrentDictionary<string, Func<byte[], string>>();
        RegisterDefaultHashAlgorithms();
    }

    private void RegisterDefaultHashAlgorithms()
    {
        hashAlgorithms["MD5"] = (data) => ComputeHash(data, MD5.Create());
        hashAlgorithms["SHA1"] = (data) => ComputeHash(data, SHA1.Create());
        hashAlgorithms["SHA256"] = (data) => ComputeHash(data, SHA256.Create());
    }

    public void RegisterAlgorithm(string name, Func<byte[], string> algorithm)
    {
        if (hashAlgorithms.ContainsKey(name))
            throw new ArgumentException("Algorithm already registered.");

        hashAlgorithms[name] = algorithm;
    }

    private static string ComputeHash(byte[] data, HashAlgorithm algorithm)
    {
        var stopwatch = Stopwatch.StartNew();
        byte[] hashBytes = algorithm.ComputeHash(data);
        stopwatch.Stop();

        Log($"Time taken to compute hash: {stopwatch.ElapsedMilliseconds} ms", LogLevel.Debug);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    public string GenerateHash(string name, string input)
    {
        ValidateInput(input);

        if (!hashAlgorithms.TryGetValue(name, out var algorithm))
            throw new ArgumentException("Algorithm not found.");

        byte[] data = Encoding.UTF8.GetBytes(input);
        return algorithm(data);
    }

    public async Task<string> GenerateHashAsync(string name, string input)
    {
        ValidateInput(input);

        if (!hashAlgorithms.TryGetValue(name, out var algorithm))
            throw new ArgumentException("Algorithm not found.");

        byte[] data = Encoding.UTF8.GetBytes(input);

        return await Task.Run(() => algorithm(data));
    }

    public void ProcessUserInput(string userId)
    {
        try
        {
            var settings = FetchUserSettingsAsync(userId).GetAwaiter().GetResult();
            ValidateSettings(settings);

            // Example processing logic using the user's settings.
            string input = "example data";
            if (input.Length > settings.MaxLength) input = TruncateInput(input, settings.MaxLength);
            if (settings.TrimFlag) input = input.Trim();
            if (settings.CapitalizeFlag) input = input.ToUpperInvariant();

            Log($"Processing input for user {userId}: {input}", LogLevel.Info);
        }
        catch (Exception ex)
        {
            Log($"Error processing input: {ex.Message}", LogLevel.Error);
        }
    }

    private async Task<UserSettings> FetchUserSettingsAsync(string userId)
    {
        var response = await httpClient.GetAsync($"https://api.example.com/user/{userId}/settings");

        if (!response.IsSuccessStatusCode)
            throw new HttpRequestException("Failed to fetch user settings.");

        string json = await response.Content.ReadAsStringAsync();
        return Newtonsoft.Json.JsonConvert.DeserializeObject<UserSettings>(json);
    }

    private void ValidateInput(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        if (Encoding.UTF8.GetByteCount(input) > MaxInputSize) 
            throw new ArgumentException("Input size exceeds the maximum limit.");
    }

    private void ValidateSettings(UserSettings settings)
    {
        if (settings.MaxLength < 0 || settings.MaxLength > MaxInputSize)
            throw new ArgumentException("Invalid max length in user settings.");

        // Additional validation checks as necessary.
    }

    private string TruncateInput(string input, int maxLength)
    {
        return input.Length <= maxLength ? input : input.Substring(0, maxLength);
    }

    private void Log(string message, LogLevel level)
    {
        if (level >= CurrentLogLevel)
            Console.WriteLine($"[{DateTime.Now}] [{level}]: {message}");
    }
}

public class UserSettings
{
    public int MaxLength { get; set; }
    public bool TrimFlag { get; set; }
    public bool CapitalizeFlag { get; set; }
}

public enum LogLevel
{
    Debug,
    Info,
    Warning,
    Error
}
