<?php

function handleUserRequest($pdo) {
    header('Content-Type: application/json');

    // Rate Limiting (Basic example, needs a more sophisticated implementation)
    $ip = $_SERVER['REMOTE_ADDR'];
    $rateLimitKey = "rate_limit_{$ip}";
    if (!isset($_SESSION[$rateLimitKey])) {
        $_SESSION[$rateLimitKey] = ['count' => 0, 'timestamp' => time()];
    }
    $currentTime = time();
    $timeDiff = $currentTime - $_SESSION[$rateLimitKey]['timestamp'];

    if ($timeDiff < 60) {
        if ($_SESSION[$rateLimitKey]['count'] >= 1000) {
            return jsonResponse(['status' => 'error', 'message' => 'Rate limit exceeded. Try again later.']);
        }
        $_SESSION[$rateLimitKey]['count']++;
    } else {
        $_SESSION[$rateLimitKey] = ['count' => 1, 'timestamp' => $currentTime];
    }

    // Input validation and sanitization
    $name = filter_var(trim($_POST['name']), FILTER_SANITIZE_STRING);
    $email = filter_var(trim($_POST['email']), FILTER_VALIDATE_EMAIL) ?: '';
    $password = $_POST['password'] ?? '';
    $confirmPassword = $_POST['confirm_password'] ?? '';
    $id = $_POST['id'] ?? null;
    $subAction = $_POST['sub_action'] ?? '';

    if (!$name || !$email || !$password || !$confirmPassword) {
        return jsonResponse(['status' => 'error', 'message' => 'All fields are required.']);
    }

    if ($password !== $confirmPassword) {
        return jsonResponse(['status' => 'error', 'message' => 'Passwords do not match.']);
    }

    // Password complexity validation
    if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) || !preg_match('/[a-z]/', $password) || !preg_match('/\d/', $password)) {
        return jsonResponse(['status' => 'error', 'message' => 'Password must be at least 8 characters long and include uppercase, lowercase letters, and numbers.']);
    }

    // Check for unique email
    if ($subAction !== 'delete') {
        $stmt = $pdo->prepare('SELECT COUNT(*) FROM users WHERE email = ? AND id != ?');
        $stmt->execute([$email, $id]);
        if ($stmt->fetchColumn() > 0) {
            return jsonResponse(['status' => 'error', 'message' => 'Email already exists.']);
        }
    }

    try {
        // Handle sub-actions
        if ($subAction === 'delete') {
            if (!$id) {
                throw new Exception('User ID is required for deletion.');
            }
            $stmt = $pdo->prepare('DELETE FROM users WHERE id = ?');
            $stmt->execute([$id]);

            logAction($email, "Deleted user with ID: {$id}");
            return jsonResponse(['status' => 'success', 'message' => 'User deleted successfully.']);
        }

        // Handle create or update
        if ($id) {
            $stmt = $pdo->prepare('UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?');
            $stmt->execute([$name, $email, password_hash($password, PASSWORD_BCRYPT), $id]);

            logAction($email, "Updated user with ID: {$id}");
            return jsonResponse(['status' => 'success', 'message' => 'User updated successfully.', 'data' => ['id' => $id, 'name' => $name, 'email' => $email]]);
        } else {
            $stmt = $pdo->prepare('INSERT INTO users (name, email, password) VALUES (?, ?, ?)');
            $stmt->execute([$name, $email, password_hash($password, PASSWORD_BCRYPT)]);

            $userId = $pdo->lastInsertId();
            logAction($email, "Created user with ID: {$userId}");
            return jsonResponse(['status' => 'success', 'message' => 'User created successfully.', 'data' => ['id' => $userId, 'name' => $name, 'email' => $email]]);
        }
    } catch (Exception $e) {
        logError($e->getMessage());
        return jsonResponse(['status' => 'error', 'message' => 'An error occurred. Please try again later.']);
    }
}

function jsonResponse($data) {
    echo json_encode($data, JSON_PRETTY_PRINT);
    exit;
}

function logAction($userEmail, $action) {
    // Implement logging logic here
    file_put_contents('logs/actions.log', date('Y-m-d H:i:s') . " - {$userEmail} - {$action}\n", FILE_APPEND);
}

function logError($errorMessage) {
    // Implement error logging logic here
    file_put_contents('logs/errors.log', date('Y-m-d H:i:s') . " - ERROR: {$errorMessage}\n", FILE_APPEND);
}
