#include <iostream>
#include <mutex>
#include <chrono>

class Character {
public:
    int health;
    int energy;
    double distanceToEnemy;

    // Constructor for initialization
    Character(int h, int e, double d) : health(h), energy(e), distanceToEnemy(d) {}

    // Example method to update character state - can be expanded as needed
    void updateState(int newHealth, int newEnergy, double newDistance) {
        std::lock_guard<std::mutex> lock(mutex_);
        health = newHealth;
        energy = newEnergy;
        distanceToEnemy = newDistance;
    }

private:
    mutable std::mutex mutex_; // Mutex for thread-safe state updates
};

class GameMechanics {
public:
    GameMechanics() : lastAttackTime(0), currentCooldown(0) {}

    void selectAttack(Character& character) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto currentTime = getCurrentSeconds();
        if (currentCooldown > 0 && currentTime - lastAttackTime < currentCooldown) {
            std::cout << "All attacks on cooldown. Performing default action." << std::endl;
            std::cout << "Remaining Cooldown: " << (currentCooldown - (currentTime - lastAttackTime)) << " seconds" << std::endl;
            return;
        }

        int attackNumber = chooseAttack(character);
        if (attackNumber == 0) {
            std::cout << "All attacks on cooldown. Performing default action." << std::endl;
        } else {
            executeAttack(attackNumber, currentTime);
        }
    }

private:
    mutable std::mutex mutex_;
    int lastAttackTime; // Tracks when the last attack was used
    int currentCooldown; // Current cooldown period for any attack

    int getCurrentSeconds() const {
        return std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()
        ).count();
    }

    int chooseAttack(const Character& character) {
        if (character.health < 30 && currentCooldown == 0) return 1;
        if (character.energy > 50 && character.distanceToEnemy < 10.0 && currentCooldown == 0) return 2;
        if (currentCooldown == 0) return 3;

        return 0; // No attack possible
    }

    void executeAttack(int attackNumber, int currentTime) {
        switch (attackNumber) {
            case 1:
                currentCooldown = 5;
                break;
            case 2:
                currentCooldown = 7;
                break;
            case 3:
                currentCooldown = 10;
                break;
            default:
                return; // Should not reach here
        }

        lastAttackTime = currentTime;
        std::cout << "Selected Attack: " << attackNumber << std::endl;
        std::cout << "Remaining Cooldown: " << (currentCooldown - (getCurrentSeconds() - lastAttackTime)) << " seconds" << std::endl;
    }
};

// Example unit test function
void testSelectAttack() {
    Character character(100, 60, 8.0);
    GameMechanics mechanics;

    // Initial attack selection
    mechanics.selectAttack(character);

    // Simulate time passing to test cooldown handling
    using namespace std::chrono_literals;
    std::this_thread::sleep_for(6s); 
    mechanics.selectAttack(character); // Should show default action due to cooldown

    character.updateState(25, 60, 8.0); // Low health should trigger Attack 1 if off cooldown
    mechanics.selectAttack(character);

    // More tests can be added as needed...
}

int main() {
    testSelectAttack();
    return 0;
}
