        Thread.currentThread().setName("JsonService");
        logger.info("Starting JsonService...");

        int delay = delayRangeStart + (int)(Math.random() * ((delayRangeEnd - delayRangeStart) + 1));
        scheduler.schedule(this::runService, delay, TimeUnit.SECONDS);
    }

    private void runService() {
        running = true;
        logger.info("JsonService is now running.");

        // Simulate service operations
        while (running) {
            // Process JSON objects...
        }
    }

    public void stop() {
        if (!running) return;

        logger.info("Stopping JsonService...");
        running = false;
        scheduler.shutdown();

        try {
            if (!scheduler.awaitTermination(5, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public String toJson(Object data) throws IOException {
        return objectMapper.writeValueAsString(data);
    }

    public <T> T fromJson(String jsonString, Class<T> clazz) throws IOException {
        if (cache.containsKey(jsonString)) {
            logger.info("Cache hit for JSON string: " + jsonString);
            return cache.get(jsonString);
        }

        JsonNode node = objectMapper.readTree(jsonString);
        validateSchema(node);

        T instance = objectMapper.treeToValue(node, clazz);
        cache.put(jsonString, instance);

        logger.info("Created new instance from JSON.");
        return instance;
    }

    private void validateSchema(JsonNode jsonNode) {
        try {
            JsonSchema schema = objectMapper.getJsonSchemaFactory().generateSchemasForClass(SomeClass.class).iterator().next();
            if (!schema.validate(jsonNode)) {
                throw new IOException("JSON does not match the schema.");
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Schema validation failed.", e);
            throw new RuntimeException(e);
        }
    }

