```csharp
using System;
using System.Diagnostics;
using System.IO;
using System.Net;
using System.Threading.Tasks;

public class SiteManager
{
    private const int MaxRetries = 3;
    private readonly IConfigurationService _configService;
    private readonly ILogger _logger;

    public SiteManager(IConfigurationService configService, ILogger logger)
    {
        _configService = configService;
        _logger = logger;
    }

    public async Task<string> AddAndStartSiteAsync(string directoryPath, string siteName, string mode, params string[] args)
    {
        if (!Directory.Exists(directoryPath) || !IsWritable(directoryPath))
        {
            _logger.Log($"Invalid or unwritable directory: {directoryPath}");
            return null;
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.Log("Web.config file not found.");
            return null;
        }

        int attempt = 0;
        while (attempt < MaxRetries)
        {
            try
            {
                var siteSettings = await _configService.GetSiteSettingsAsync(siteName);
                if (siteSettings == null) 
                    throw new InvalidOperationException("Failed to retrieve site settings.");

                return await StartSiteAsync(directoryPath, siteSettings, mode, args);
            }
            catch (Exception ex)
            {
                attempt++;
                _logger.Log($"Attempt {attempt}: Error starting site - {ex.Message}");
                if (attempt >= MaxRetries) break;
                await Task.Delay(1000); // Retry delay
            }
        }

        return "Failed to start the site after multiple attempts.";
    }

    private async Task<string> StartSiteAsync(string directoryPath, SiteSettings settings, string mode, params string[] args)
    {
        var processStartInfo = new ProcessStartInfo("dotnet", $"run --project {directoryPath} {string.Join(" ", args)}")
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };

        using (var process = new Process { StartInfo = processStartInfo })
        {
            try
            {
                _logger.Log($"Starting site in {mode} mode.");
                await Task.WhenAny(Task.Run(() => process.Start()), Task.Delay(5000)); // Timeout

                if (!process.HasExited)
                    process.Kill();

                return process.StandardOutput.ReadToEnd();
            }
            catch (Exception ex)
            {
                _logger.Log($"Error while starting the site: {ex.Message}");
                throw;
            }
        }
    }

    private bool IsWritable(string path) => Directory.Exists(path) && CanWriteToDirectory(new DirectoryInfo(path));

    private static bool CanWriteToDirectory(DirectoryInfo directory)
    {
        try
        {
            var testFilePath = Path.Combine(directory.FullName, ".test.txt");
            using (File.Create(testFilePath)) { }
            File.Delete(testFilePath);
            return true;
        }
        catch
        {
            return false;
        }
    }
}

public interface IConfigurationService
{
    Task<SiteSettings> GetSiteSettingsAsync(string siteName);
}

public class SiteSettings
{
    public int Port { get; set; }
    public string BindingInformation { get; set; }
}

public interface ILogger
{
    void Log(string message);
}

// Unit Tests (using a test framework like NUnit or xUnit)
public class SiteManagerTests
{
    // Test methods for different scenarios...
}
