# log_processor.py

import json
import requests
from collections import defaultdict
import logging

def process_log_file(file_path, api_endpoint, chunk_size=1024*1024):
    ip_stats = defaultdict(lambda: {'total_time': 0, 'request_count': 0})

    with open(file_path, 'r') as file:
        while True:
            lines = file.readlines(chunk_size)
            if not lines:
                break
            process_lines(lines, ip_stats)

    report_statistics(ip_stats, api_endpoint)

def process_lines(lines, ip_stats):
    for line in lines:
        try:
            parts = parse_log_line(line)
            if parts:
                ip_address, response_time = parts['ip'], float(parts['response_time'])
                status_code = int(parts['status_code'])

                if 200 <= status_code < 300:  # Success codes
                    ip_stats[ip_address]['total_time'] += response_time
                    ip_stats[ip_address]['request_count'] += 1

        except Exception as e:
            logging.error(f"Error processing line: {line}. Error: {str(e)}")

def parse_log_line(line):
    parts = line.split()
    if len(parts) < 9:
        return None
    # Assuming format: IP - - [dd/mmm/yyyy:hh:mm:ss] "GET /path HTTP/1.1" status_code response_time
    ip_address = parts[0]
    response_time = parts[-2].strip(']')
    status_code = parts[-1]

    return {
        'ip': ip_address,
        'response_time': response_time,
        'status_code': status_code
    }

def report_statistics(ip_stats, api_endpoint):
    for ip, stats in ip_stats.items():
        if stats['request_count'] > 0:
            avg_response_time = stats['total_time'] / stats['request_count']
            payload = {
                'ip_address': ip,
                'average_response_time': avg_response_time
            }
            try:
                response = requests.post(api_endpoint, json=payload)
                if not response.ok:
                    logging.error(f"Failed to send data for IP {ip}: {response.text}")
            except Exception as e:
                logging.error(f"Error reporting statistics for IP {ip}. Error: {str(e)}")

if __name__ == "__main__":
    logging.basicConfig(filename='error.log', level=logging.ERROR)
    process_log_file('large_log_file.log', 'https://api.example.com/report')
```

