import json
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

class CryptoConfig:
    def __init__(self, config_path):
        self.config_path = config_path
        self.crypto_list = []

    def load_configuration(self):
        try:
            with open(self.config_path, 'r') as file:
                config_data = json.load(file)
            self.sort_crypto_functions(config_data.get('ciphers', []))
            self.verify_cryptographic_functions()
        except Exception as e:
            logging.error(f"Failed to load configuration: {str(e)}")

    def sort_crypto_functions(self, functions):
        self.crypto_list = sorted(functions)

    def verify_cryptographic_functions(self):
        with ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.verify_function, func): func for func in self.crypto_list}
            for future in as_completed(futures):
                func_name = futures[future]
                try:
                    if not future.result():
                        logging.warning(f"Cryptography function unavailable: {func_name}")
                except Exception as e:
                    logging.error(f"Error verifying function {func_name}: {str(e)}")

    def verify_function(self, func_name):
        # Placeholder for actual verification logic
        available_functions = ['sha256', 'md5', 'aes']  # Example list of available functions

        return func_name in available_functions

    def get_last_entry_sequence_number(self):
        if self.crypto_list:
            last_entry = self.crypto_list[-1]
            try:
                sequence_number = int(last_entry.split('_')[-1])
                return sequence_number
            except ValueError:
                logging.error(f"Failed to extract sequence number from: {last_entry}")
        return None

if __name__ == "__main__":
    logging.basicConfig(filename='crypto_config.log', level=logging.WARNING)
    config = CryptoConfig('config.json')
    config.load_configuration()
    print("Last entry sequence number:", config.get_last_entry_sequence_number())
