Below is a simplified version of a C-based semaphore management library tailored for integration with a high-performance distributed messaging system like Apache Kafka. This example covers basic functionalities such as creation, deletion, synchronization, acquiring, releasing semaphores, error handling, logging, and thread-safety using POSIX semaphores.

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define SEM_PREFIX "/myapp_sem_"
#define LOG_FILE "semaphore_log.txt"

// Logging function
void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Initialize semaphore with given name and initial value
sem_t* create_semaphore(const char *name, int init_value) {
    sem_t *sem = malloc(sizeof(sem_t));
    if (!sem) {
        log_message("Failed to allocate memory for semaphore");
        return NULL;
    }

    char path[256];
    snprintf(path, sizeof(path), "%s%s", SEM_PREFIX, name);

    if (sem_open(path, O_CREAT | O_EXCL, 0644, init_value) == SEM_FAILED) {
        log_message("Failed to create semaphore");
        free(sem);
        return NULL;
    }

    *sem = sem_open(path, 0);
    if (*sem == SEM_FAILED) {
        log_message("Failed to open semaphore");
        free(sem);
        return NULL;
    }

    log_message("Semaphore created successfully");
    return sem;
}

// Delete a semaphore by name
int delete_semaphore(const char *name) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s", SEM_PREFIX, name);

    if (sem_unlink(path) == -1) {
        log_message("Failed to unlink semaphore");
        return -1;
    }

    log_message("Semaphore deleted successfully");
    return 0;
}

// Acquire semaphore
int acquire_semaphore(sem_t *sem) {
    int result = sem_wait(sem);
    if (result != 0 && errno != EINTR) {
        log_message("Failed to acquire semaphore");
        return -1;
    }

    log_message("Semaphore acquired successfully");
    return 0;
}

// Release semaphore
int release_semaphore(sem_t *sem) {
    int result = sem_post(sem);
    if (result != 0) {
        log_message("Failed to release semaphore");
        return -1;
    }

    log_message("Semaphore released successfully");
    return 0;
}

// Close and free a semaphore
void close_semaphore(sem_t **sem) {
    if (sem_close(*sem) == -1) {
        log_message("Failed to close semaphore");
    } else {
        log_message("Semaphore closed successfully");
    }
    sem_unlink((*sem)->name);
    free(*sem);
    *sem = NULL;
}

// Example unit test function for acquiring and releasing a semaphore
void test_semaphore() {
    const char *test_name = "test_sem";
    int init_value = 1;

    log_message("Starting semaphore test");

    sem_t *sem = create_semaphore(test_name, init_value);
    if (!sem) return;

    acquire_semaphore(sem);
    release_semaphore(sem);

    delete_semaphore(test_name);
    close_semaphore(&sem);

    log_message("Semaphore test completed");
}

int main() {
    test_semaphore();
    return 0;
}
```

### Key Features:
- **POSIX Semaphores**: Used for creating, acquiring, and releasing semaphores.
- **Thread-Safety**: Managed through POSIX semaphore operations (`sem_wait`, `sem_post`).
- **Error Handling & Logging**: Logs errors and actions to a file for tracking.
- **Unit Testing**: Simple test function to validate the creation, acquisition, release, and deletion of a semaphore.

### Considerations:
- This is a basic implementation. In production, you would need comprehensive error handling, additional logging levels, more robust testing frameworks (e.g., CMocka), and possibly performance optimizations for high concurrency.
- The library should be extended to handle more complex scenarios like distributed systems coordination beyond what POSIX semaphores offer on a single machine.

This example can serve as a starting point for developing more advanced semaphore management capabilities required by your specific use case.

```javascript
class LRUCache {
    constructor(limit) {
        this.limit = limit;
        this.cache = new Map();
    }

    get(key) {
        if (!this.cache.has(key)) return null;
        const value = this.cache.get(key);
        this.cache.delete(key);
        this.cache.set(key, value);
        return value;
    }

    put(key, value) {
        if (this.cache.has(key)) {
            this.cache.delete(key);
        } else if (this.cache.size === this.limit) {
            this.cache.delete(this.cache.keys().next().value);
        }
        this.cache.set(key, value);
    }
}

