                process.nextTick(() => {
                    if (++activePromises >= concurrency) {
                        semaphore.then(() => executeCallback(semaphore, resolve, reject, initialValue, number));
                    } else {
                        executeCallback(semaphore, resolve, reject, initialValue, number);
                    }
                });
            } catch (error) {
                reject(error);
            }
        })
    }));

    async function executeCallback(releaseSemaphore, resolve, reject, acc, num) {
        try {
            const result = await callback(acc, num);
            if (result instanceof Error) throw result;
            resolve(result);
        } catch (error) {
            reject(error);
        } finally {
            releaseSemaphore();
            semaphore.release();
        }
    }

    let cache = new LRUCache(100); // Example cache size
    const token = process.env.API_TOKEN; // Securely fetched API token

    async function throttledCallback(acc, num) {
        const cachedResult = cache.get(num);
        if (cachedResult !== null) return cachedResult;

        try {
            const result = await simulateApiCall(token, acc, num);
            cache.put(num, result);

            if (progressCallback) {
                progressCallback(queue.filter(item => item.promise.status === "fulfilled").length, acc);
            }

            return result;
        } catch (error) {
            throw error;
        }
    }

    async function simulateApiCall(token, acc, num) {
        // Simulate an external API call
        await new Promise(resolve => setTimeout(resolve, 100)); // Simulated delay

        if (!token) throw new Error("Invalid token");

        return callback(acc, num); // Placeholder for actual async operation
    }

    const results = [];
    while (queue.length > 0) {
        const task = queue.shift();
        results.push(task.promise.then(result => {
            activePromises--;
            return result;
        }).catch(error => {
            activePromises--;
            throw error;
        }));

        if (activePromises < concurrency && semaphore.release) {
            semaphore.release();
        }
    }

    try {
        const finalResult = await Promise.all(results);
        return finalResult.reduce((acc, value) => callback(acc, value));
    } catch (error) {
        return { error };
    }
}

