async function asyncArrayReduce(numbers, initialValue, promiseCallback, maxParallel = 5) {
    const semaphore = new Semaphore(maxParallel);

    let accumulatedValue = initialValue;
    let completedOperations = 0;

    const reduceWithSemaphore = async (number) => {
        await semaphore.acquire();

        try {
            // Simulate API call with Promise-based callback
            return await promiseCallback(accumulatedValue, number);
        } catch (error) {
            throw new Error(`Error in reduction: ${error.message}`);
        } finally {
            completedOperations++;
            console.log(`Progress: Completed operations = ${completedOperations}, Current value = ${accumulatedValue}`);
            semaphore.release();
        }
    };

    for (const number of numbers) {
        try {
            accumulatedValue = await reduceWithSemaphore(number);
        } catch (error) {
            return Promise.reject(error);
        }
    }

    return accumulatedValue;
}

class Semaphore {
    constructor(count) {
        this.count = count;
        this.queue = [];
    }

    async acquire() {
        if (this.count > 0) {
            this.count--;
            return Promise.resolve();
        } else {
            return new Promise(resolve => this.queue.push(() => resolve()));
        }
    }

    release() {
        if (this.queue.length > 0) {
            const nextResolve = this.queue.shift();
            nextResolve();
        } else {
            this.count++;
        }
    }
}
