use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::sync::Mutex;
use redis::AsyncCommands;
use log::{info, warn, error, debug};
use tokio::time::{sleep, Duration};
use futures::future::join_all;

// Define the configuration structure
#[derive(Serialize, Deserialize)]
struct Config {
    update_interval: u64,
}

// Weather response structure based on expected API response format
#[derive(Deserialize)]
struct WeatherResponse {
    location: String,
    temperature: f32,
    condition: String,
}

async fn fetch_weather_data(client: &Client, location: &str) -> Result<WeatherResponse, reqwest::Error> {
    let url = format!("https://api.weather.com/v1/location/{}/observations/current.json", location);

    // Include error handling for connection issues and API failures
    let response = client.get(url).send().await?;
    if !response.status().is_success() {
        return Err(reqwest::Error::new(
            reqwest::StatusCode::INTERNAL_SERVER_ERROR,
            false,
        ));
    }

    let weather_data: WeatherResponse = response.json().await?;
    Ok(weather_data)
}

async fn fetch_config(file_path: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let config_content = tokio::fs::read_to_string(file_path).await?;
    let config: Config = serde_json::from_str(&config_content)?;
    Ok(config)
}

async fn get_weather_data(
    client: Client,
    redis_client: &redis::Client,
    location: String
) -> Result<WeatherResponse, Box<dyn std::error::Error>> {

    let mut con = redis_client.get_async_connection().await?;
    let cache_key = format!("weather_data:{}", location);
    if let Ok(cached_weather): Option<String> = con.get(&cache_key).await? {
        debug!("Cache hit for {}", location);
        return serde_json::from_str(&cached_weather).map_err(|e| e.into());
    }

    match fetch_weather_data(&client, &location).await {
        Ok(weather) => {
            let serialized: String = serde_json::to_string(&weather)?;
            con.set_ex(&cache_key, serialized, 600).await?; // Cache for 10 minutes
            Ok(weather)
        },
        Err(e) => {
            error!("Failed to fetch weather data: {:?}", e);
            Err(Box::new(e))
        }
    }
}

async fn handle_request(client: Client, redis_client: &redis::Client, location: String) -> Option<WeatherResponse> {
    match get_weather_data(client.clone(), redis_client, location).await {
        Ok(weather) => Some(weather),
        Err(_) => None,
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let config_path = "config.json";
    let config = fetch_config(config_path).await.expect("Failed to load configuration");

    info!("Update interval is set to {} seconds", config.update_interval);

    let client = Client::new();
    let redis_client = redis::Client::open("redis://127.0.0.1/").expect("Invalid Redis URL");

    // Shared cache for handling concurrent requests
    let locations: Vec<String> = vec!["New York".to_string(), "London".to_string(), "Tokyo".to_string()];

    loop {
        let tasks = locations.iter().map(|location| handle_request(client.clone(), &redis_client, location.to_string()));

        let results = join_all(tasks).await;

        for result in results {
            if let Some(weather) = result {
                info!("Weather for {}: {}°C - {}", weather.location, weather.temperature, weather.condition);
            } else {
                warn!("Failed to fetch data");
            }
        }

        sleep(Duration::from_secs(config.update_interval)).await;
    }
}
