```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.SSLContext;

public class NIOConnectionManager {

    private final int poolSize;
    private final String[] serverAddresses;
    private final int heartbeatIntervalMillis;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final ExecutorService connectionPool = Executors.newFixedThreadPool(poolSize);
    private final Map<String, SocketChannel> activeConnections = new ConcurrentHashMap<>();
    private final Semaphore connectionSemaphore;
    private final SSLContext sslContext;

    public NIOConnectionManager(int poolSize, String[] serverAddresses, int heartbeatIntervalMillis) throws Exception {
        this.poolSize = poolSize;
        this.serverAddresses = serverAddresses;
        this.heartbeatIntervalMillis = heartbeatIntervalMillis;
        this.connectionSemaphore = new Semaphore(poolSize);
        this.sslContext = SSLContext.getDefault(); // Replace with configured SSLContext
    }

    public void start() throws IOException {
        scheduler.scheduleAtFixedRate(this::performHeartbeat, 0, heartbeatIntervalMillis, TimeUnit.MILLISECONDS);
    }

    private void performHeartbeat() {
        activeConnections.keySet().forEach(address -> {
            SocketChannel channel = activeConnections.get(address);
            if (channel != null && !isConnectionAlive(channel)) {
                retryConnection(address);
            }
        });
    }

    public Future<SocketChannel> getConnection(String serverAddress) throws InterruptedException {
        connectionSemaphore.acquire();
        return connectionPool.submit(() -> {
            try {
                SocketChannel channel = openSecureChannel(serverAddress);
                activeConnections.put(serverAddress, channel);
                return channel;
            } catch (IOException e) {
                connectionSemaphore.release();
                throw new RuntimeException(e);
            }
        });
    }

    private SocketChannel openSecureChannel(String serverAddress) throws IOException {
        InetSocketAddress address = new InetSocketAddress(serverAddress, 443); // Assuming default SSL port
        SocketChannel rawChannel = SocketChannel.open(address);
        return sslContext.wrapSocket(rawChannel.socket(), null, null).getChannel();
    }

    private boolean isConnectionAlive(SocketChannel channel) {
        try {
            ByteBuffer buffer = ByteBuffer.allocate(1);
            return channel.read(buffer) != -1;
        } catch (IOException e) {
            return false;
        }
    }

    private void retryConnection(String serverAddress) {
        connectionPool.submit(() -> {
            try {
                SocketChannel newChannel = openSecureChannel(serverAddress);
                activeConnections.put(serverAddress, newChannel);
                System.out.println("Reconnected to " + serverAddress);
            } catch (IOException e) {
                System.err.println("Failed to reconnect to " + serverAddress);
            } finally {
                connectionSemaphore.release();
            }
        });
    }

    public void stop() {
        scheduler.shutdownNow();
        connectionPool.shutdown();
        activeConnections.values().forEach(channel -> {
            try {
                channel.close();
            } catch (IOException e) {
                // Ignore
            }
        });
    }

    public static void main(String[] args) throws Exception {
        String[] servers = {"server1.example.com", "server2.example.com"};
        NIOConnectionManager manager = new NIOConnectionManager(10, servers, 5000);
        manager.start();

        // Example usage
        Future<SocketChannel> future = manager.getConnection(servers[0]);
        SocketChannel channel = future.get(); // Blocks until a connection is available

        // Use the channel...

        manager.stop();
    }
}
