import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.Future;

public class ConnectionHandler {

    public void establishConnection(String host, int port) {
        try {
            AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();

            Future<Void> future = channel.connect(new InetSocketAddress(host, port));
            while (!future.isDone()) {
                // Handle connection state changes if needed
            }

            boolean isConnected = future.get();  // Blocks until the connection completes

            if (isConnected) {
                System.out.println("Connection established to " + host + ":" + port);
            } else {
                System.err.println("Failed to establish connection.");
            }

            channel.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
