#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "parson.h"  // JSON library for parsing

bool verifyOAuth2Token(const char *jsonString) {
    if (jsonString == NULL) {
        return false;
    }

    JSON_Value *rootValue = json_parse_string(jsonString);
    if (!rootValue) {
        return false;
    }

    JSON_Object *rootObject = json_value_get_object(rootValue);

    // Check for required fields
    const char* access_token = json_object_get_string(rootObject, "access_token");
    int expires_in = json_object_get_number(rootObject, "expires_in");
    const char* token_type = json_object_get_string(rootObject, "token_type");

    if (!access_token || !token_type) {
        goto cleanup;
    }

    // Validate the token type and expiry
    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        goto cleanup;
    }

    // Optionally check for refresh_token but not required
    const char* refresh_token = json_object_get_string(rootObject, "refresh_token");

    json_value_free(rootValue);
    return true;

cleanup:
    json_value_free(rootValue);
    return false;
}
```

