```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');
const { Pool } = require('pg');
const Redis = require('ioredis');
const axios = require('axios'); // Assume integration with Rust HTTP client

// Environment variables or configuration file
const dbConfig = {
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT,
};

const redisClient = new Redis(process.env.REDIS_URL);
const pool = new Pool(dbConfig);

const app = express();

app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
}));

// Middleware for parsing XML and plain text
app.use(async (req, res, next) => {
  if (req.headers['content-type'] === 'application/xml') {
    req.body = await parseXML(req.rawBody);
  } else if (req.headers['content-type'] === 'text/plain') {
    req.body = { content: req.body };
  }
  next();
});

// Get Old Testament books from the database
const getOldTestamentBooks = async () => {
  const cachedBooks = await redisClient.get('old_testament_books');
  if (cachedBooks) return JSON.parse(cachedBooks);

  const result = await pool.query("SELECT book_name FROM old_testament_books");
  const books = result.rows.map(row => row.book_name.toLowerCase().replace(/[\W_]+/g, ''));
  redisClient.set('old_testament_books', JSON.stringify(books), 'EX', 3600); // Cache for an hour
  return books;
};

// Main route to process incoming data streams
app.post('/process', async (req, res) => {
  const oldTestamentBooks = await getOldTestamentBooks();
  const content = req.body.content.toLowerCase().replace(/[\W_]+/g, ' ');

  let bookCount = {};
  for (let book of oldTestamentBooks) {
    const regex = new RegExp(`\\b${book}\\b`, 'g');
    const matches = (content.match(regex) || []).length;
    if (matches > 0) bookCount[book] = matches;
  }

  res.json(bookCount);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

