void TransactionLogger::disconnectFromDatabase() {
    if (dbConnected) {
        // Simulate database disconnection cleanup
        dbConnected = false;
    }
}

bool TransactionLogger::openLogFile() {
    logFile.open("transaction_log.txt", std::ios::app);
    if (logFile.is_open()) {
        logFileOpen = true;
        return true;
    }
    return false;
}

void TransactionLogger::closeLogFile() {
    if (logFileOpen && logFile.is_open()) {
