int TransactionLogger::verifyWithPaymentProcessor(const std::string& processor) {
    // Simulate API call to payment processor
    for (int attempt = 1; attempt <= 3; ++attempt) {
        try {
            if (rand() % 2 == 0) { // Randomly simulate success or failure
                return 0; // Success code
            } else {
                throw std::runtime_error("Payment processor error");
            }
        } catch (...) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * attempt));
        }
    }
    return -1; // Failure code after retries
}

void TransactionLogger::retryWithBackoff(std::function<int()> operation) {
    for (int attempt = 1; attempt <= 3; ++attempt) {
        int result = operation();
        if (result == 0) {
            return;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(100 * attempt));
    }
}

std::optional<int> TransactionLogger::recordTransaction(const std::string& transactionId, const TransactionDetails& details, RecorderType type, const std::string& processor) {
    std::lock_guard<std::mutex> lock(mtx);

    try {
        switch (type) {
            case RecorderType::DATABASE: {
                if (!dbConnected && !connectToDatabase()) {
                    return {1}; // Database connection error code
                }
                logFile << "Recording to database: " << transactionId << std::endl;
                // Simulate database record operation
                break;
            }
            case RecorderType::FILE: {
                if (!logFileOpen && !openLogFile()) {
                    return {2}; // Log file open error code
                }
                logFile << "Recording to file: " << transactionId << std::endl;
                break;
            }
            case RecorderType::PAYMENT_PROCESSOR: {
                auto verifyOperation = [this, processor]() { return this->verifyWithPaymentProcessor(processor); };
                retryWithBackoff(verifyOperation);
                logFile << "Recording to payment processor: " << transactionId << std::endl;
                break;
            }
        }

        // Close resources if necessary
        if (type == RecorderType::DATABASE) {
            disconnectFromDatabase();
        }
        if (type == RecorderType::FILE) {
            closeLogFile();
        }

        return {}; // Success, no error code needed
    } catch (...) {
        return {3}; // General failure code
    }
}
