#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

// Structure to encapsulate a semaphore with RAII principles
typedef struct {
    sem_t *sem;
    int initial_value;
} Semaphore;

// Function prototypes
Semaphore* create_semaphore(int initial_value, int *error_code);
void destroy_semaphore(Semaphore *s, int *error_code);
int increment_semaphore(Semaphore *s, int timeout_ms, int *error_code);
int decrement_semaphore(Semaphore *s, int timeout_ms, int *error_code);
void log_operation(const char* operation, int result);

// Helper function to handle logging
void log_to_external_service(const char* message) {
    // Placeholder for integration with an external logging service.
    printf("LOG: %s\n", message);
}

Semaphore* create_semaphore(int initial_value, int *error_code) {
    Semaphore *semaphore = (Semaphore*)malloc(sizeof(Semaphore));
    if (!semaphore) {
        *error_code = ENOMEM;
        log_operation("create_semaphore failed due to memory allocation error.", 1);
        return NULL;
    }

    semaphore->sem = malloc(sizeof(sem_t));
    if (!semaphore->sem) {
        free(semaphore);
        *error_code = ENOMEM;
        log_operation("create_semaphore failed due to sem_t allocation error.", 1);
        return NULL;
    }

    if (sem_init(semaphore->sem, 0, initial_value) != 0) {
        free(semaphore->sem);
        free(semaphore);
        *error_code = errno;
        log_operation("create_semaphore failed during semaphore initialization.", 1);
        return NULL;
    }

    semaphore->initial_value = initial_value;
    *error_code = 0;
    log_operation("Semaphore created successfully.", 0);

    return semaphore;
}

void destroy_semaphore(Semaphore *s, int *error_code) {
    if (s && s->sem) {
        if (sem_destroy(s->sem)) {
            *error_code = errno;
            log_operation("destroy_semaphore failed during semaphore destruction.", 1);
        } else {
            free(s->sem);
            free(s);
            *error_code = 0;
            log_operation("Semaphore destroyed successfully.", 0);
        }
    }
}

int increment_semaphore(Semaphore *s, int timeout_ms, int *error_code) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts)) {
        *error_code = errno;
        return -1;
    }

    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    int result = sem_timedwait(s->sem, &ts);
    if (result == -1 && errno != ETIMEDOUT) {
        *error_code = errno;
        log_operation("increment_semaphore failed.", 1);
    } else {
        *error_code = 0;
        log_operation("Semaphore incremented successfully.", 0);
    }

    return result == 0 ? 0 : (*error_code == ETIMEDOUT ? -2 : -1);
}

int decrement_semaphore(Semaphore *s, int timeout_ms, int *error_code) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts)) {
        *error_code = errno;
        return -1;
    }

    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    int result = sem_timedpost(s->sem);
    if (result == -1 && errno != ETIMEDOUT) {
        *error_code = errno;
        log_operation("decrement_semaphore failed.", 1);
    } else {
        *error_code = 0;
        log_operation("Semaphore decremented successfully.", 0);
    }

    return result == 0 ? 0 : (*error_code == ETIMEDOUT ? -2 : -1);
}

void log_operation(const char* operation, int result) {
    const char* outcome = result == 0 ? "success" : "failure";
    char message[256];
    snprintf(message, sizeof(message), "%s: %s", operation, outcome);
    log_to_external_service(message);
}
