public class HashAlgorithmWrapper : IDisposable
{
    private readonly HashAlgorithm _algorithm;
    private bool _disposed;

    public HashAlgorithmWrapper(HashAlgorithm algorithm)
    {
        _algorithm = algorithm ?? throw new ArgumentNullException(nameof(algorithm));
    }

    public async Task<byte[]> ComputeHashAsync(Stream inputStream)
    {
        if (inputStream == null) throw new ArgumentNullException(nameof(inputStream));

        using var hashStream = new CryptoStream(inputStream, _algorithm, CryptoStreamMode.Read);
        using var ms = new MemoryStream();
        await hashStream.CopyToAsync(ms);
        return ms.ToArray();
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            _algorithm?.Dispose();
            _disposed = true;
        }
    }
}
```

### Explanation

1. **Factory Pattern**: Each hashing algorithm (`MD5`, `SHA-1`, `SHA-256`) is encapsulated within its own class that implements the `IHashAlgorithmFactory` interface.

2. **Asynchronous Processing**: All methods leverage asynchronous patterns using `Task` and `await`. The `ComputeHashAsync` method in `HashAlgorithmWrapper` utilizes `CryptoStream` for streaming data to the hash algorithm, allowing handling of large files without excessive memory usage.

3. **Hexadecimal Conversion**: The conversion to a hexadecimal string is handled by `BitConverter.ToString`, which formats the byte array into the desired hex format (lowercase).

4. **Resource Management**: Classes implement `IDisposable` where appropriate to ensure proper resource cleanup. This includes releasing `HashAlgorithm` instances and any stream resources.

5. **Extensibility**: The factory pattern allows new hash algorithms to be added easily by implementing the `IHashAlgorithmFactory` interface, without altering existing code.

This design efficiently manages large data processing asynchronously while ensuring that all system resources are properly managed and disposed of after use.

Below is an example implementation in C that addresses your requirements. This program uses pthreads for multithreading, POSIX semaphores for synchronization, and socket programming for network communication with an external semaphore management service.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import <pthread.h>
import <semaphore.h>
import <unistd.h>
import <errno.h>
import <arpa/inet.h>
import <sys/socket.h>

#define BUFFER_SIZE 256
#define MAX_THREADS 10

typedef struct {
    int socket_fd;
    char *service_address;
    int initial_value;
} SemaphoreManager;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphores[MAX_THREADS];

void *manage_semaphore(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager *)arg;
    char buffer[BUFFER_SIZE];
    int retries = 3;

    while (retries > 0) {
        if (connect(manager->socket_fd, (struct sockaddr *)&(manager->service_address), sizeof(manager->service_address)) < 0) {
            pthread_mutex_lock(&log_mutex);
            printf("Connection failed: %s\n", strerror(errno));
            pthread_mutex_unlock(&log_mutex);
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        snprintf(buffer, BUFFER_SIZE, "CREATE %d\n", manager->initial_value);
        if (write(manager->socket_fd, buffer, strlen(buffer)) < 0) {
            pthread_mutex_lock(&log_mutex);
            printf("Write failed: %s\n", strerror(errno));
            pthread_mutex_unlock(&log_mutex);
            retries--;
            close(manager->socket_fd);
            sleep(1); // Wait before retrying
            continue;
        }

        if (read(manager->socket_fd, buffer, BUFFER_SIZE) > 0) {
            pthread_mutex_lock(&log_mutex);
            printf("Service response: %s\n", buffer);
            pthread_mutex_unlock(&log_mutex);
            break;
        } else {
            pthread_mutex_lock(&log_mutex);
            printf("Read failed: %s\n", strerror(errno));
            pthread_mutex_unlock(&log_mutex);
            retries--;
            close(manager->socket_fd);
            sleep(1); // Wait before retrying
        }
    }

    if (retries == 0) {
        pthread_mutex_lock(&log_mutex);
        printf("Failed to manage semaphore after multiple attempts.\n");
        pthread_mutex_unlock(&log_mutex);
    }

    return NULL;
}

void create_semaphore(int initial_value, char *service_address) {
    SemaphoreManager manager = {socket(AF_INET, SOCK_STREAM, 0), service_address, initial_value};
    if (manager.socket_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_semaphore, &manager) != 0) {
        fprintf(stderr, "Thread creation failed: %s\n", strerror(errno));
        close(manager.socket_fd);
        exit(EXIT_FAILURE);
    }
    pthread_join(thread, NULL);
    close(manager.socket_fd);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <initial_value> <service_address>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int initial_value = atoi(argv[1]);
    char *service_address = argv[2];

    create_semaphore(initial_value, service_address);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Multithreading**: Uses pthreads to handle concurrent semaphore operations.
- **Network Communication**: Connects to an external service using TCP sockets.
- **Error Handling**: Implements retries for network failures and logs errors.
- **Logging**: Uses mutexes to ensure thread-safe logging.

