```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class EncryptionService
{
    private static readonly byte[] Key = Convert.FromBase64String("YourBase64EncodedKeyHere");
    private static readonly byte[] IV = Convert.FromBase64String("YourBase64EncodedIVHere");

    public string DecryptAndValidateMessage(string base64EncryptedData)
    {
        try
        {
            // Decode the Base64 input
            byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedData);

            // Extract HMAC from end of encrypted data
            int hmacLength = SHA256.Create().HashSize / 8;
            byte[] hmacReceived = new byte[hmacLength];
            Array.Copy(encryptedBytes, encryptedBytes.Length - hmacLength, hmacReceived, 0, hmacLength);

            // Get the actual encrypted message part excluding HMAC
            byte[] encryptedMessagePart = new byte[encryptedBytes.Length - hmacLength];
            Array.Copy(encryptedBytes, 0, encryptedMessagePart, 0, encryptedBytes.Length - hmacLength);

            using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
            {
                // Decrypt the message
                tdes.Key = Key;
                tdes.IV = IV;
                tdes.Mode = CipherMode.CBC;
                tdes.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);

                using (MemoryStream msDecrypt = new MemoryStream(encryptedMessagePart))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] decryptedBytes = new byte[encryptedMessagePart.Length];
                        int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                        byte[] actualDecryptedBytes = new byte[bytesRead];

                        Array.Copy(decryptedBytes, actualDecryptedBytes, bytesRead);

                        // Compute HMAC on decrypted data using the same key
                        using (HMACSHA256 hmac = new HMACSHA256(Key))
                        {
                            byte[] hmacCalculated = hmac.ComputeHash(actualDecryptedBytes);
                            if (!hmacReceived.SequenceEqual(hmacCalculated))
                            {
                                throw new AuthenticationException("Message authentication failed.");
                            }
                        }

                        // Convert decrypted bytes to string
                        return Encoding.UTF8.GetString(actualDecryptedBytes);
                    }
                }
            }
        }
        catch (FormatException)
        {
            throw new FormatException("Invalid Base64 encoding in input data.");
        }
        catch (CryptographicException ex)
        {
            LogError(ex.Message); // Implement this method to log errors
            throw new Exception("Decryption failed.", ex);
        }
    }

    private void LogError(string message)
    {
        // Implement your logging logic here, e.g., call external API or log to a file/db.
        Console.WriteLine($"[ERROR] {message}");
    }
}

public class AuthenticationException : Exception
{
    public AuthenticationException(string message) : base(message) { }
}
