        string json = JsonConvert.SerializeObject(logData);

        HttpResponseMessage response = await client.PostAsync("https://your-logging-api-endpoint", 
            new StringContent(json, Encoding.UTF8, "application/json"));

        if (!response.IsSuccessStatusCode)
        {
            // Handle the error
            throw new Exception($"Failed to log message status: {response.ReasonPhrase}");
        }
    }
}
