```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');
const EventEmitter = require('events');

// Use the promisified versions for async/await support.
const readFileAsync = util.promisify(fs.readFile);
const readdirAsync = util.promisify(fs.readdir);

class FileSystemCache extends EventEmitter {
  constructor() {
    super();
    this.cache = new Map();
  }

  get(directory) {
    return this.cache.get(directory);
  }

  set(directory, data) {
    this.cache.set(directory, data);
    this.emit('update', directory);
  }
}

const cache = new FileSystemCache();

async function readDirectoryFiles({
  dir,
  extensions = ['.txt'],
  bufferSize = 1024 * 64,
  maxConcurrentReads = 5,
  maxSizeThreshold = Infinity,
  retryConfig = { attempts: 3, backoff: 100 },
  recursive = false
}) {
  let cacheData = cache.get(dir);

  if (cacheData) return cacheData;

  const logFileActivity = async (filename, contentLength) => {
    console.log(`Processing file: ${filename}, Length: ${contentLength}`);
  };

  const shouldRetry = (error, attempt, maxAttempts) =>
    attempt < maxAttempts && error.code === 'EAGAIN';

  const retryReadFile = async (filePath, encoding, bufferSize, retries) => {
    let attempt = 0;
    while (attempt <= retries) {
      try {
        return await readFileAsync(filePath, { encoding, highWaterMark: bufferSize });
      } catch (error) {
        if (!shouldRetry(error, attempt, retries)) throw error;
        await new Promise(res => setTimeout(res, retryConfig.backoff * Math.pow(2, attempt)));
        attempt++;
      }
    }
  };

  const readFileWithLimit = async (filePath) => {
    const stats = await util.promisify(fs.stat)(filePath);
    if (stats.size > maxSizeThreshold) return null;

    const content = await retryReadFile(filePath, 'utf8', bufferSize, retryConfig.attempts);
    logFileActivity(path.basename(filePath), content ? Buffer.byteLength(content) : 0);

    return content;
  };

  const readDirectoryRecursively = async (currentDir, filesList = []) => {
    const entries = await readdirAsync(currentDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue; // Handle symbolic links as needed.

      const fullPath = path.join(currentDir, entry.name);

      if (entry.isDirectory() && recursive) {
        filesList = await readDirectoryRecursively(fullPath, filesList);
      } else if (entry.isFile()) {
        if (extensions.some(ext => fullPath.endsWith(ext))) {
          filesList.push(fullPath);
        }
      }
    }
    return filesList;
  };

  const processFiles = async (filePaths) => {
    const results = [];
    const semaphore = new Array(maxConcurrentReads).fill(true);

    for (const filePath of filePaths) {
      await new Promise((resolve) => {
        (async () => {
          while (!semaphore.some(val => val)) {
            await new Promise(resolveMicroTask => setImmediate(resolveMicroTask));
          }

          const index = semaphore.indexOf(true);
          if (index !== -1) {
            semaphore[index] = false;

            readFileWithLimit(filePath)
              .then(content => {
                if (content) results.push(content);
              })
              .catch(error => console.error(`Error reading file ${filePath}:`, error))
              .finally(() => {
                semaphore[index] = true;
                resolve();
              });
          }
        })();
      });
    }

    return results.join('\n');
  };

  try {
    const filePaths = await readDirectoryRecursively(dir);
    cache.set(dir, await processFiles(filePaths));
    return cache.get(dir);
  } catch (error) {
    console.error(`Error processing directory ${dir}:`, error);
    throw error;
  }
}

