char* combine_key_cert_into_pem(const char* private_key_path, const char* cert_path) {
    FILE *key_file, *cert_file;
    char *combined_pem = malloc(4096);

    key_file = fopen(private_key_path, "rb");
    if (key_file == NULL) {
        fprintf(stderr, "Private key file missing\n");
        return NULL;
    }

    cert_file = fopen(cert_path, "rb");
    if (cert_file == NULL) {
        fprintf(stderr, "Certificate file missing\n");
        fclose(key_file);
        return NULL;
    }

    // Read and combine files into one PEM
    fread(combined_pem, 1, sizeof(combined_pem), key_file);
    strcat(combined_pem, "\n-----END PRIVATE KEY-----\n");
    fseek(cert_file, 0, SEEK_SET);  // Reset file pointer for certificate read
    fread(combined_pem + strlen(combined_pem), 1, sizeof(combined_pem) - strlen(combined_pem), cert_file);

    fclose(key_file);
    fclose(cert_file);

    return combined_pem;
}

void* handle_transaction(void* transaction_data) {
    // Placeholder for actual implementation handling a single transaction
    char *session_id = NULL;
    if (authenticate_user("client_credentials", &session_id) != 0) {
        fprintf(stderr, "Authentication failed\n");
        return NULL;
    }

    const char* transaction_id = (const char*)transaction_data;

    if (!validate_transaction(transaction_id)) {
        fprintf(stderr, "Invalid or duplicate transaction ID: %s\n", transaction_id);
        free(session_id);
        return NULL;
    }

    SocketChannel channel = SocketChannel.open();
    try {
        InetSocketAddress address = new InetSocketAddress("remote_address", 8080);
        if (channel.connect(address) == false) {
            fprintf(stderr, "Failed to connect using NIO Channel\n");
            channel.close();
            free(session_id);
            return NULL;
        }

        KafkaProducer<String, String> producer = new KafkaProducer<>(/* Kafka configuration */);
        send_message_to_kafka(producer, "transaction_topic", transaction_id);

        update_metrics_distributed_db("sample_metric_data");

        char *pem_data = combine_key_cert_into_pem("path/to/private_key.pem", "path/to/certificate.pem");
        if (pem_data != NULL) {
            // Handle the combined PEM data
            free(pem_data);
        }

    } catch (IOException e) {
        fprintf(stderr, "IO Error: %s\n", e.toString().c_str());
    } finally {
        try {
            channel.close();
        } catch (IOException e) {
            fprintf(stderr, "Error closing NIO Channel: %s\n", e.toString().c_str());
        }
        free(session_id);
    }

    return NULL;
}

void processTransactions(const char** transaction_ids, int num_transactions) {
    pthread_t threads[num_transactions];

    for (int i = 0; i < num_transactions; ++i) {
        if (pthread_create(&threads[i], NULL, handle_transaction, (void*)transaction_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < num_transactions; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    const char* transactions[] = { "txid_1", "txid_2", "txid_3" };
    processTransactions(transactions, 3);

    return 0;
}
