```java
import java.util.*;
import java.security.KeyPairGenerator;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class NetworkPacketProcessor {

    private static String accessToken = null;
    private final long SLIDING_WINDOW_DURATION_MS = 60000; // e.g., 1 minute window
    private Deque<NetworkPacket> packetWindow = new LinkedList<>();
    private int filteredPacketsCount = 0;
    private int totalPacketCount = 0;
    private double totalPacketSize = 0.0;

    public static class NetworkPacket {
        String packetId;
        int size;
        String sourceIp;
        int destPort;
        long arrivalTime; // in milliseconds
        byte[] privateKey;
        byte[] certificate;

        // Constructor, getters and setters are assumed to be implemented here.
    }

    public synchronized void authenticate(String clientId, String clientSecret) {
        if (accessToken == null || accessTokenExpired()) {
            // Simulate an OAuth 2.0 token request
            accessToken = "new_access_token"; // Replace with actual authentication logic
            System.out.println("Authenticated and obtained access token.");
        }
    }

    private boolean accessTokenExpired() {
        // Implement logic to check if the access token is expired.
        return false;
    }

    public synchronized String filterAndProcessNetworkPackets(List<NetworkPacket> packets, int minSize, 
                                                             String allowedSourceIp, int allowedDestPort,
                                                             long currentTime) throws NoSuchAlgorithmException {

        authenticate("client_id", "client_secret");

        for (NetworkPacket packet : packets) {
            totalPacketCount++;
            if (packet.size >= minSize && 
                allowedSourceIp.equals(packet.sourceIp) && 
                packet.destPort == allowedDestPort &&
                currentTime - packet.arrivalTime <= SLIDING_WINDOW_DURATION_MS) {

                packetWindow.add(packet);
                totalPacketSize += packet.size;
            } else {
                filteredPacketsCount++;
            }

            // Maintain the sliding window
            while (!packetWindow.isEmpty() && 
                   (currentTime - packetWindow.peek().arrivalTime > SLIDING_WINDOW_DURATION_MS)) {
                NetworkPacket oldest = packetWindow.poll();
                totalPacketSize -= oldest.size;
            }
        }

        int maxPacketSize = 0;
        String maxPacketId = null;

        for (NetworkPacket packet : packetWindow) {
            if (packet.size > maxPacketSize) {
                maxPacketSize = packet.size;
                maxPacketId = packet.packetId;
            }
        }

        // Combine private key and certificate into a PEM file
        StringBuilder pemFileContent = new StringBuilder();
        for (NetworkPacket packet : packetWindow) {
            String privateKeyPem = Base64.getEncoder().encodeToString(packet.privateKey);
            String certificatePem = Base64.getEncoder().encodeToString(packet.certificate);

            pemFileContent.append("-----BEGIN PRIVATE KEY-----\n")
                          .append(privateKeyPem).append("\n")
                          .append("-----END PRIVATE KEY-----\n");

            pemFileContent.append("-----BEGIN CERTIFICATE-----\n")
                          .append(certificatePem).append("\n")
                          .append("-----END CERTIFICATE-----\n");
        }

        String encodedPem = Base64.getEncoder().encodeToString(pemFileContent.toString().getBytes());

        // Metrics output for debugging purposes
        System.out.println("Filtered Packets: " + filteredPacketsCount);
        System.out.println("Total Packet Count: " + totalPacketCount);
        if (packetWindow.size() > 0) {
            double averageSize = totalPacketSize / packetWindow.size();
            System.out.println("Average Packet Size in Window: " + averageSize);
        }

        return maxPacketId != null ? maxPacketId : "No valid packets found.";
    }
}
