```rust
use reqwest::Client;
use tokio::time::{self, Duration};
use std::env;
use std::collections::HashMap;
use serde::{Deserialize, Serialize};
use async_trait::async_trait;

#[derive(Debug, Deserialize)]
struct WeatherData {
    current: CurrentWeather,
    forecast: Vec<Forecast>,
}

#[derive(Debug, Deserialize)]
struct CurrentWeather {
    temperature: f32,
    description: String,
}

#[derive(Debug, Deserialize)]
struct Forecast {
    dt: i64,
    temp: f32,
    description: String,
}

#[async_trait]
trait WeatherApi {
    async fn fetch_weather(&self, city: &str) -> Result<WeatherData, reqwest::Error>;
}

struct OpenWeatherMap {
    client: Client,
    api_key: String,
}

#[async_trait]
impl WeatherApi for OpenWeatherMap {
    async fn fetch_weather(&self, city: &str) -> Result<WeatherData, reqwest::Error> {
        let url = format!(
            "https://api.openweathermap.org/data/2.5/forecast?q={}&appid={}",
            city, self.api_key
        );
        let response = self.client.get(url).send().await?.json::<WeatherData>().await?;
        Ok(response)
    }
}

struct WeatherStack {
    client: Client,
    api_key: String,
}

#[async_trait]
impl WeatherApi for WeatherStack {
    async fn fetch_weather(&self, city: &str) -> Result<WeatherData, reqwest::Error> {
        let url = format!(
            "http://api.weatherstack.com/forecast?access_key={}&query={}",
            self.api_key, city
        );
        let response = self.client.get(url).send().await?.json::<WeatherData>().await?;
        Ok(response)
    }
}

struct AccuWeather {
    client: Client,
    api_key: String,
}

#[async_trait]
impl WeatherApi for AccuWeather {
    async fn fetch_weather(&self, city: &str) -> Result<WeatherData, reqwest::Error> {
        let url = format!(
            "http://dataservice.accuweather.com/forecasts/v1/daily/1day/{}/apikey/{}",
            city, self.api_key
        );
        let response = self.client.get(url).send().await?.json::<WeatherData>().await?;
        Ok(response)
    }
}

struct WeatherService {
    apis: Vec<Box<dyn WeatherApi>>,
    cache: HashMap<String, WeatherData>,
}

impl WeatherService {
    fn new() -> Self {
        let client = Client::new();
        let open_weather_map = OpenWeatherMap { client.clone(), api_key: "your_openweathermap_api_key".into() };
        let weather_stack = WeatherStack { client.clone(), api_key: "your_weatherstack_api_key".into() };
        let accu_weather = AccuWeather { client, api_key: "your_accuwheather_api_key".into() };

        Self {
            apis: vec![
                Box::new(open_weather_map),
                Box::new(weather_stack),
                Box::new(accu_weather),
            ],
            cache: HashMap::new(),
        }
    }

    async fn get_weather(&mut self, city: &str) -> Result<WeatherData, reqwest::Error> {
        if let Some(data) = self.cache.get(city) {
            return Ok(data.clone());
        }

        for api in &self.apis {
            match api.fetch_weather(city).await {
                Ok(data) => {
                    self.cache.insert(city.to_string(), data.clone());
                    return Ok(data);
                }
                Err(_) => continue,
            }
        }

        Err(reqwest::Error::new(
            reqwest::StatusCode::SERVICE_UNAVAILABLE,
            "All APIs failed",
        ))
    }

    async fn periodic_cache_update(&mut self, interval: Duration) {
        loop {
            for city in self.cache.keys().cloned() {
                let _ = self.get_weather(&city).await;
            }
            time::sleep(interval).await;
        }
    }
}

async fn main_logic(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    if args.len() != 2 {
        eprintln!("Usage: {} <city>", args[0]);
        return Ok(());
    }

    let city = &args[1];
    let mut weather_service = WeatherService::new();

    tokio::spawn(async move {
        weather_service.periodic_cache_update(Duration::from_secs(3600)).await;
    });

    match weather_service.get_weather(city).await {
        Ok(data) => {
            println!("Current: {} °C, {}", data.current.temperature, data.current.description);
            for forecast in data.forecast.iter() {
                println!(
                    "{}: {} °C, {}",
                    chrono::NaiveDateTime::from_timestamp(forecast.dt as i64 * 1000, 0),
                    forecast.temp,
                    forecast.description
                );
            }
        }
        Err(e) => eprintln!("Failed to fetch weather data: {}", e),
    }

    Ok(())
}

#[tokio::main]
async fn main() {
    if let Err(e) = main_logic(&env::args()).await {
        eprintln!("Error: {}", e);
    }
}
