```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define CHUNK 16384

void print_usage() {
    printf("Usage: file_counter [-c] [-d] [-o output_file] input_file1 [input_file2 ...]\n");
}

int process_file(FILE *file, int compress, int decompress, FILE *output) {
    if (compress && decompress) return 0; // Can't do both

    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    unsigned char in[CHUNK];
    unsigned char out[CHUNK];

    int ret, flush;
    int lines = 0;

    if (compress) {
        ret = deflateInit(&strm, Z_DEFAULT_COMPRESSION);
        if (ret != Z_OK) return 0;
        flush = Z_NO_FLUSH;
        while ((ret = fread(in, 1, CHUNK, file)) > 0 || flush == Z_FINISH) {
            strm.next_in = in;
            strm.avail_in = ret;
            do {
                strm.next_out = out;
                strm.avail_out = CHUNK;
                ret = deflate(&strm, flush);
                if (output) fwrite(out, 1, CHUNK - strm.avail_out, output);
            } while (strm.avail_out == 0);
            if (ret != Z_STREAM_END) break;
        }
    } else if (decompress) {
        ret = inflateInit(&strm);
        if (ret != Z_OK) return 0;
        flush = Z_NO_FLUSH;
        while ((ret = fread(in, 1, CHUNK, file)) > 0 || flush == Z_FINISH) {
            strm.next_in = in;
            strm.avail_in = ret;
            do {
                strm.next_out = out;
                strm.avail_out = CHUNK;
                ret = inflate(&strm, flush);
                if (output) fwrite(out, 1, CHUNK - strm.avail_out, output);
            } while (strm.avail_out == 0);
            if (ret != Z_STREAM_END) break;
        }
    } else {
        char buffer[CHUNK];
        while (fgets(buffer, sizeof(buffer), file)) {
            lines++;
        }
        if (output && !compress && !decompress) rewind(file); // Rewind to output again
    }

    if (compress) deflateEnd(&strm);
    if (decompress) inflateEnd(&strm);

    return lines;
}

int main(int argc, char *argv[]) {
    int c;
    int compress = 0, decompress = 0;
    FILE *output_file = stdout;
    char *output_filename = NULL;

    while ((c = getopt(argc, argv, "cdo:")) != -1) {
        switch (c) {
            case 'c':
                compress = 1;
                break;
            case 'd':
                decompress = 1;
                break;
            case 'o':
                output_filename = optarg;
                break;
            default:
                print_usage();
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: No input file provided.\n");
        print_usage();
        return EXIT_FAILURE;
    }

    if (output_filename) {
        output_file = fopen(output_filename, "wb");
        if (!output_file) {
            perror("Failed to open output file");
            return EXIT_FAILURE;
        }
    }

    int total_lines = 0;
    for (int i = optind; i < argc; i++) {
        FILE *input_file = fopen(argv[i], "rb");
        if (!input_file) {
            perror("Error opening input file");
            continue;
        }

        int lines = process_file(input_file, compress, decompress, output_file);
        fclose(input_file);

        total_lines += lines;

        printf("%s: %d lines\n", argv[i], lines);
    }

    if (output_filename) {
        fclose(output_file);
    }

    printf("Total lines processed: %d\n", total_lines);

    return EXIT_SUCCESS;
}
