```rust
use std::sync::{Arc, Mutex};
use std::collections::VecDeque;
use std::fs::{self, File};
use std::io::{self, Write};
use std::env;
use std::path::PathBuf;
use std::thread;
use std::time::{Duration, Instant};

use serde::Deserialize;
use log::{info, warn, error};
use tokio::runtime::Runtime;

#[derive(Deserialize)]
struct Config {
    max_log_files: usize,
    cleanup_interval: Duration,
    path_format: String,
    health_check_threshold: u64,
}

struct LogFileManager {
    config: Config,
    pending_requests: Arc<Mutex<VecDeque<String>>>,
    log_path: PathBuf,
}

impl LogFileManager {
    fn new(config: Config, log_path: PathBuf) -> Self {
        let _ = fs::create_dir_all(&log_path);
        LogFileManager {
            config,
            pending_requests: Arc::new(Mutex::new(VecDeque::new())),
            log_path,
        }
    }

    fn create_log_file(&self, server_id: &str, client_request: &str) -> io::Result<()> {
        let timestamp = chrono::Utc::now().format("%Y%m%d%H%M%S").to_string();
        let filename = format!(
            "{}-{}-{}.log",
            self.config.path_format.replace("{server_id}", server_id),
            timestamp,
            client_request.replace(" ", "_")
        );

        let file_path = self.log_path.join(filename);
        let mut file = File::create(&file_path)?;

        // Atomically update environment variable
        env::set_var("CURRENT_LOG_FILE", &file_path);

        // Log creation
        info!("Created log file: {}", file_path.display());

        // Notify monitoring system
        Self::notify_monitoring_system(&format!("Log created: {}", filename))?;

        Ok(())
    }

    fn cleanup_old_logs(&self) -> io::Result<()> {
        let mut files = fs::read_dir(self.log_path)?
            .filter_map(Result::ok)
            .collect::<Vec<_>>();

        // Sort by modification time
        files.sort_by_key(|entry| entry.metadata().map(|meta| meta.modified()).unwrap_or(Instant::now()));

        while files.len() > self.config.max_log_files {
            let file = files.remove(0);
            if let Ok(metadata) = file.metadata() {
                if metadata.is_file() {
                    fs::remove_file(file.path())?;
                    info!("Deleted old log file: {}", file.path().display());
                    Self::notify_monitoring_system(&format!("Log deleted: {:?}", file.file_name()))?;
                }
            }
        }

        Ok(())
    }

    fn notify_monitoring_system(message: &str) -> io::Result<()> {
        // HTTP notification
        if let Err(e) = reqwest::blocking::get("http://monitoring-system/api/notify") {
            warn!("HTTP notification failed: {}", e);
        }

        // WebSocket notification
        if let Ok(mut ws_stream) = tokio_tungstenite::connect_async("ws://monitoring-system/ws").await? {
            ws_stream.send(tokio_tungstenite::tungstenite::Message::Text(message.to_string())).await?;
        }

        Ok(())
    }
}

fn main() -> io::Result<()> {
    env_logger::init();

    let config = Config {
        max_log_files: 10,
        cleanup_interval: Duration::from_secs(60),
        path_format: "{server_id}-{timestamp}.log".to_string(),
        health_check_threshold: 1000,
    };

    let log_manager = LogFileManager::new(config, PathBuf::from("/var/log/myapp"));

    // Spawn background thread for periodic cleanup
    thread::spawn(move || {
        let rt = Runtime::new().unwrap();
        loop {
            rt.block_on(async {
                if let Err(e) = log_manager.cleanup_old_logs() {
                    error!("Cleanup failed: {}", e);
                }
            });
            thread::sleep(config.cleanup_interval);
        }
    });

    // Simulate concurrent log creation
    for server_id in ["server1", "server2", "server3"] {
        let manager_clone = log_manager.clone();
        thread::spawn(move || {
            if let Err(e) = manager_clone.create_log_file(server_id, "client_request_1") {
                error!("Log creation failed: {}", e);
            }
        });
    }

    Ok(())
}

#[cfg(test)]
mod tests {
