    #[test]
    fn test_create_and_cleanup_logs() -> io::Result<()> {
        let config = Config {
            max_log_files: 2,
            cleanup_interval: Duration::from_secs(1),
            path_format: "{server_id}-{timestamp}.log".to_string(),
            health_check_threshold: 1000,
        };

        let log_manager = LogFileManager::new(config, PathBuf::from("/tmp/myapp_logs"));

        log_manager.create_log_file("test_server", "client_request_1")?;
        log_manager.create_log_file("test_server", "client_request_2")?;
        log_manager.create_log_file("test_server", "client_request_3")?;

        // Simulate cleanup
        log_manager.cleanup_old_logs()?;

        let files = fs::read_dir("/tmp/myapp_logs")?.collect::<Result<Vec<_>, io::Error>>()?;

        assert_eq!(files.len(), 2);

        Ok(())
    }
}
