```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    long value;
    long timestamp;
} Record;

typedef struct RecordType {
    char* type_name;
    size_t size;
} RecordType;

typedef struct CacheNode {
    int key;
    void* data;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    pthread_mutex_t lock;
    CacheNode* head;
    CacheNode* tail;
    size_t capacity;
    int count;
} LRUCache;

// Forward declarations
void flush_to_database(void** records, int num_records);
LRUCache* create_cache(size_t capacity);
void cache_set(LRUCache* cache, int key, void* data);
void* cache_get(LRUCache* cache, int key);
void delete_cache(LRUCache* cache);

// Function to generate and initialize arrays
int generate_and_initialize_arrays(long** offsets, int** keys, Record*** records, size_t num_elements,
                                   RecordType** record_types, int num_record_types) {
    pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays
    *offsets = (long*)malloc(num_elements * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -1;
    }

    *keys = (int*)malloc(num_elements * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return -1;
    }

    *records = (Record**)malloc(num_elements * sizeof(Record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }

    // Initialize random seed
    srand(time(NULL));

    // Generate random values and timestamps
    for (size_t i = 0; i < num_elements; ++i) {
        (*offsets)[i] = rand();

        (*keys)[i] = rand() % 100;

        Record* record = (Record*)malloc(sizeof(Record));
        if (record == NULL) {
            fprintf(stderr, "Memory allocation failed for record.\n");
            return -1;
        }

        record->value = rand();
        record->timestamp = time(NULL) + (rand() % 100);

        (*records)[i] = record;
    }

    // Create cache
    LRUCache* cache = create_cache(num_elements);

    if (cache == NULL) {
        fprintf(stderr, "Cache creation failed.\n");
        return -1;
    }

    // Periodically flush records to the database
    pthread_t db_thread;
    pthread_create(&db_thread, NULL, (void*)flush_to_database, *records);

    // Example cache usage
    for (size_t i = 0; i < num_elements; ++i) {
        cache_set(cache, (*keys)[i], (*records)[i]);
    }

    return 0;
}

// Cache functions
LRUCache* create_cache(size_t capacity) {
    LRUCache* cache = malloc(sizeof(LRUCache));
    if (cache == NULL) {
        fprintf(stderr, "Memory allocation failed for cache.\n");
        return NULL;
    }

    pthread_mutex_init(&cache->lock, NULL);
    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    cache->count = 0;

    return cache;
}

void cache_set(LRUCache* cache, int key, void* data) {
    pthread_mutex_lock(&cache->lock);

    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for cache node.\n");
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    node->key = key;
    node->data = data;

    // If the node already exists
    CacheNode* current = cache->head;
    while (current) {
        if (current->key == key) {
            free(current->data);  // Free existing data
            current->data = data;  // Update with new data

            // Move to front
            if (current != cache->head) {
                if (current == cache->tail) {
                    cache->tail = current->prev;
                    cache->tail->next = NULL;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                }

                current->next = cache->head;
                current->prev = NULL;
                cache->head->prev = current;
                cache->head = current;
            }

            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->next;
    }

    // Add new node
    node->next = cache->head;
    if (cache->head != NULL) {
        cache->head->prev = node;
    }
    cache->head = node;

    if (cache->tail == NULL) {
        cache->tail = node;
    } else if (cache->count >= cache->capacity) {
        // Evict least recently used
        CacheNode* lru = cache->tail;
        cache->tail = cache->tail->prev;
        if (cache->tail) {
            cache->tail->next = NULL;
        }

        free(lru->data);
        free(lru);
    } else {
        ++cache->count;
    }

    pthread_mutex_unlock(&cache->lock);
}

void* cache_get(LRUCache* cache, int key) {
    pthread_mutex_lock(&cache->lock);

    CacheNode* current = cache->head;
    while (current) {
        if (current->key == key) {
            // Move to front
            if (current != cache->head) {
                if (current == cache->tail) {
                    cache->tail = current->prev;
                    cache->tail->next = NULL;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                }

                current->next = cache->head;
                current->prev = NULL;
                cache->head->prev = current;
                cache->head = current;
            }

            pthread_mutex_unlock(&cache->lock);
            return current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void delete_cache(LRUCache* cache) {
    CacheNode* current = cache->head;
    while (current != NULL) {
        CacheNode* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Dummy function to simulate flushing records to a database
void* flush_to_database(void** records, int num_records) {
    // Simulate database operations and periodic flushing
    while (1) {
        sleep(5);  // Flush every 5 seconds

        pthread_mutex_t db_lock;
        pthread_mutex_init(&db_lock, NULL);

        for (int i = 0; i < num_records; ++i) {
            if (records[i] != NULL) {
                pthread_mutex_lock(&db_lock);

                printf("Flushing record %d to database.\n", i);

                // Simulate database operation
                usleep(100000);  // Simulated delay

                pthread_mutex_unlock(&db_lock);
            }
        }

        pthread_mutex_destroy(&db_lock);
    }
}

int main() {
    long* offsets;
    int* keys;
    Record** records;

    size_t num_elements = 10; // Example number of elements
    RecordType* record_types[1];
    record_types[0] = (RecordType*)malloc(sizeof(RecordType));
    if (!record_types[0]) {
        fprintf(stderr, "Memory allocation failed for record type.\n");
        return -1;
    }
    strcpy(record_types[0]->type_name, "BasicRecord");
    record_types[0]->size = sizeof(Record);

    int status = generate_and_initialize_arrays(&offsets, &keys, &records, num_elements,
                                                (RecordType**)record_types, 1);
    if (status != 0) {
        fprintf(stderr, "Failed to initialize arrays.\n");
        return -1;
    }

    // Cleanup
    for (size_t i = 0; i < num_elements; ++i) {
        free(records[i]);
    }

    free(offsets);
    free(keys);
    free(records);

    delete_cache(create_cache(num_elements));

    free(record_types[0]);

    return 0;
}
