// Source file: crypto_library.c

#include "crypto_library.h"
#include <openssl/err.h>
#include <openssl/pem.h>
#include <openssl/bio.h>
#include <openssl/ssl.h>
#include <pthread.h>

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

CryptoContext* crypto_init(const char *provider) {
    // Initialize contexts based on provider
    CryptoContext *ctx = malloc(sizeof(CryptoContext));
    ctx->aes_ctx = EVP_CIPHER_CTX_new();
    ctx->md5_ctx = EVP_MD_CTX_create();
    ctx->sha1_ctx = EVP_MD_CTX_create();

    // Setup provider-specific configurations if needed

    return ctx;
}

void crypto_cleanup(CryptoContext *ctx) {
    pthread_mutex_lock(&lock);
    EVP_CIPHER_CTX_free(ctx->aes_ctx);
    EVP_MD_CTX_destroy(ctx->md5_ctx);
    EVP_MD_CTX_destroy(ctx->sha1_ctx);
    free(ctx);
    pthread_mutex_unlock(&lock);
}

int aes_encrypt(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len,
                unsigned char *ciphertext, const unsigned char *key, const unsigned char *iv) {
    // Implementation of AES encryption
    EVP_CIPHER_CTX_init(ctx->aes_ctx);
    if (1 != EVP_EncryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx->aes_ctx, ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx->aes_ctx, ciphertext + len, &len)) {
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_cleanup(ctx->aes_ctx);
    return ciphertext_len;
}

int aes_decrypt(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                unsigned char *plaintext, const unsigned char *key, const unsigned char *iv) {
    // Implementation of AES decryption
    EVP_CIPHER_CTX_init(ctx->aes_ctx);
    if (1 != EVP_DecryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx->aes_ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx->aes_ctx, plaintext + len, &len)) {
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_cleanup(ctx->aes_ctx);
    return plaintext_len;
}

void compute_md5(CryptoContext *ctx, const unsigned char *data, size_t len, unsigned char digest[16]) {
    // Implementation of MD5 computation
    EVP_MD_CTX_init(ctx->md5_ctx);
    if (1 != EVP_DigestInit_ex(ctx->md5_ctx, EVP_md5(), NULL)) {
        return;
    }

    if (1 != EVP_DigestUpdate(ctx->md5_ctx, data, len)) {
        return;
    }
    unsigned int md_len;
    if (1 != EVP_DigestFinal_ex(ctx->md5_ctx, digest, &md_len)) {
        return;
    }

    EVP_MD_CTX_cleanup(ctx->md5_ctx);
}

void compute_sha1(CryptoContext *ctx, const unsigned char *data, size_t len, unsigned char digest[20]) {
    // Implementation of SHA1 computation
    EVP_MD_CTX_init(ctx->sha1_ctx);
    if (1 != EVP_DigestInit_ex(ctx->sha1_ctx, EVP_sha1(), NULL)) {
        return;
    }

    if (1 != EVP_DigestUpdate(ctx->sha1_ctx, data, len)) {
        return;
    }
    unsigned int md_len;
    if (1 != EVP_DigestFinal_ex(ctx->sha1_ctx, digest, &md_len)) {
        return;
    }

    EVP_MD_CTX_cleanup(ctx->sha1_ctx);
}

int rsa_sign_sha1(const unsigned char *data, size_t data_len, unsigned char *signature,
                  unsigned int *siglen, EVP_PKEY *pkey) {
    // Implementation of RSA signing with SHA1
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx || !EVP_DigestSignInit(mdctx, NULL, EVP_sha1(), NULL, pkey)) {
        return -1;
    }

    if (!EVP_DigestSignUpdate(mdctx, data, data_len)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    *siglen = 0;
    if (!EVP_DigestSignFinal(mdctx, signature, siglen)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }
    EVP_MD_CTX_free(mdctx);
    return 0;
}

int rsa_verify_sha1(const unsigned char *data, size_t data_len, const unsigned char *sigbuf,
                    unsigned int siglen, EVP_PKEY *pub_key) {
    // Implementation of RSA verification with SHA1
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (!mdctx || !EVP_DigestVerifyInit(mdctx, NULL, EVP_sha1(), NULL, pub_key)) {
        return -1;
    }

    if (!EVP_DigestVerifyUpdate(mdctx, data, data_len)) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    int result = EVP_DigestVerifyFinal(mdctx, sigbuf, siglen);
    EVP_MD_CTX_free(mdctx);
    return result;
}

