Below is a Python implementation for a dynamic data aggregation service that integrates multiple external APIs to fetch and merge real-time sorted integer streams into a single consolidated sorted stream. This solution uses multithreading to handle varying data rates from different APIs and prioritizes data consistency and fault tolerance.

```python
import threading
import queue
import requests
from heapq import heappush, heappop
import time

class APIClient:
    def __init__(self, url):
        self.url = url

    def fetch_stream(self):
        try:
            response = requests.get(self.url)
            response.raise_for_status()
            return [int(x) for x in response.text.split()]
        except (requests.RequestException, ValueError) as e:
            print(f"Error fetching data from {self.url}: {e}")
            return []

class DataAggregator:
    def __init__(self):
        self.data_streams = queue.PriorityQueue()
        self.lock = threading.Lock()

    def add_stream(self, stream_data, source_id):
        for number in stream_data:
            with self.lock:
                heappush(self.data_streams.queue, (number, source_id))

    def get_sorted_stream(self):
        sorted_list = []
        while not self.data_streams.empty():
            number, _ = self.data_streams.get()
            sorted_list.append(number)
        return sorted(sorted_list)

class StreamManager:
    def __init__(self, api_clients, throttle_rate=1.0):
        self.api_clients = api_clients
        self.aggregator = DataAggregator()
        self.throttle_rate = throttle_rate

    def fetch_and_aggregate(self):
        threads = []

        for source_id, client in enumerate(self.api_clients):
            thread = threading.Thread(target=self.fetch_data, args=(client, source_id))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        return self.aggregator.get_sorted_stream()

    def fetch_data(self, api_client, source_id):
        while True:
            data_stream = api_client.fetch_stream()
            if not data_stream:
                break
            self.aggregator.add_stream(data_stream, source_id)

            time.sleep(1 / self.throttle_rate)  # Throttling to prevent resource exhaustion

def main():
    api_urls = [
        "http://example.com/api/stream1",
        "http://example.com/api/stream2",
        "http://example.com/api/stream3"
    ]

    api_clients = [APIClient(url) for url in api_urls]
    manager = StreamManager(api_clients, throttle_rate=0.5)
    sorted_stream = manager.fetch_and_aggregate()
    print("Consolidated Sorted Stream:", sorted_stream)

if __name__ == "__main__":
    main()
```

### Key Components:

1. **APIClient**: Handles API requests and fetches integer streams from given URLs.
2. **DataAggregator**: Uses a priority queue to efficiently merge incoming data into a single sorted stream.
3. **StreamManager**: Manages fetching and aggregating data from multiple APIs using multithreading and includes throttling mechanisms.

### Notes:

- Error handling is included for API failures.
- Throttling mechanism prevents excessive resource use by controlling the fetch rate.
- The design allows easy scaling with more APIs by adding new `APIClient` instances to `api_clients`.
- This implementation assumes that data from each API can be fetched continuously and merged in real-time.

