import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

// Packet class to represent a network packet.
class NetworkPacket {
    private final long size;
    private final String sourceIP;
    private final int destinationPort;
    private final Instant arrivalTime;
    private final String payloadContent;

    public NetworkPacket(long size, String sourceIP, int destinationPort, Instant arrivalTime, String payloadContent) {
        this.size = size;
        this.sourceIP = sourceIP;
        this.destinationPort = destinationPort;
        this.arrivalTime = arrivalTime;
        this.payloadContent = payloadContent;
    }

    public long getSize() { return size; }
    public String getSourceIP() { return sourceIP; }
    public int getDestinationPort() { return destinationPort; }
    public Instant getArrivalTime() { return arrivalTime; }
    public String getPayloadContent() { return payloadContent; }
}

// Sliding window implementation using a list.
class SlidingWindow<T> {
    private final List<T> window;
    private final int maxSize;

    public SlidingWindow(int maxSize) {
        this.maxSize = maxSize;
        this.window = new ArrayList<>();
    }

    public void add(T element) {
        if (window.size() >= maxSize) {
            window.remove(0);
        }
        window.add(element);
    }

    public Iterator<T> iterator() {
        return window.iterator();
    }

    public int size() { return window.size(); }
}

// Logging utility
class Logger {
    public static void log(String message) {
        System.out.println(message); // In practice, replace with a more robust logging system.
    }
}

// PacketProcessor class handles packet filtering and metrics management.
public class PacketProcessor {

    private final SlidingWindow<NetworkPacket> slidingWindow;
    private int totalPackets = 0;
    private int filteredPackets = 0;
    private double averageSize = 0.0;

    public PacketProcessor(int windowSize) {
        this.slidingWindow = new SlidingWindow<>(windowSize);
    }

    // Process incoming network packets.
    public void processPacket(NetworkPacket packet, long minSize, String allowedSourceIP,
                              int[] allowedPorts, Instant startTime, String keywordInPayload) {

        totalPackets++;

        if (packet.getSize() < minSize || !packet.getSourceIP().equals(allowedSourceIP) ||
            isDestinationPortNotAllowed(packet.getDestinationPort(), allowedPorts) ||
            packet.getArrivalTime().isBefore(startTime) || 
            !packet.getPayloadContent().contains(keywordInPayload)) {

            filteredPackets++;
            Logger.log("Packet filtered: " + reasonForFiltering(packet));
        } else {
            slidingWindow.add(packet);
            updateAverageSize(packet.getSize());
            storePacketMetadata(packet); // Store packet metadata in the database.
        }
    }

    private boolean isDestinationPortNotAllowed(int destinationPort, int[] allowedPorts) {
        for (int port : allowedPorts) {
            if (port == destinationPort) return false;
        }
        return true;
    }

    private void updateAverageSize(long size) {
        averageSize = slidingWindow.size() > 0 ?
                ((averageSize * (slidingWindow.size() - 1)) + size) / slidingWindow.size() : size;
    }

    private String reasonForFiltering(NetworkPacket packet) {
        return "Reasons: "
            + (packet.getSize() < minSize ? "Size too small; " : "")
            + (!packet.getSourceIP().equals(allowedSourceIP) ? "Invalid source IP; " : "")
            + (isDestinationPortNotAllowed(packet.getDestinationPort(), allowedPorts) ? "Port not allowed; " : "")
            + (packet.getArrivalTime().isBefore(startTime) ? "Arrived too early; " : "")
            + (!packet.getPayloadContent().contains(keywordInPayload) ? "Keyword missing; " : "");
    }

    private void storePacketMetadata(NetworkPacket packet) {
        String url = "jdbc:your_database_url";
        String user = "username";
        String password = "password";

        try (Connection connection = DriverManager.getConnection(url, user, password)) {
            String sql = "INSERT INTO PacketMetadata (size, sourceIP, destinationPort, arrivalTime, payloadContent) VALUES (?, ?, ?, ?, ?)";

            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setLong(1, packet.getSize());
                statement.setString(2, packet.getSourceIP());
                statement.setInt(3, packet.getDestinationPort());
                statement.setTimestamp(4, java.sql.Timestamp.from(packet.getArrivalTime()));
                statement.setString(5, packet.getPayloadContent());

                statement.executeUpdate();
            }
        } catch (SQLException e) {
            Logger.log("Database error: " + e.getMessage());
        }
    }

    // Admin interface for real-time statistics.
    public void displayStatistics() {
        Logger.log(String.format("Total Packets: %d, Filtered Packets: %d, Average Size: %.2f",
                totalPackets, filteredPackets, averageSize));
    }

    // Main method for testing purposes.
    public static void main(String[] args) {
        PacketProcessor processor = new PacketProcessor(100);

        // Simulated packet processing
        NetworkPacket packet1 = new NetworkPacket(1500, "192.168.1.1", 80,
                Instant.now(), "Example payload containing keyword");
        long minSize = 1000;
        String allowedSourceIP = "192.168.1.1";
        int[] allowedPorts = {80, 443};
        Instant startTime = Instant.now().minusSeconds(30);
        String keywordInPayload = "keyword";

        processor.processPacket(packet1, minSize, allowedSourceIP, allowedPorts, startTime, keywordInPayload);

        // Display current statistics
        processor.displayStatistics();
    }
}
