Below is a simplified version of a C program implementing DES ciphers with ECB, EDE, EDE3, CFB modes, and null encryption for testing purposes. It includes key derivation and basic error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/evp.h>

#define DEFAULT_IV_LEN 8

void handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

static void des_encrypt_decrypt(unsigned char *input, unsigned char *output, int len, DES_key_schedule *ks1, DES_key_schedule *ks2, DES_key_schedule *ks3, int encrypt, int mode, const unsigned char *iv, int iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_error("Failed to create cipher context");

    int key_len;
    switch (mode) {
        case 1: // ECB
            key_len = encrypt ? DES_ECB_encrypt(input, output, len, ks1) : DES_ECB_decrypt(input, output, len, ks1);
            break;
        case 2: // EDE
            key_len = encrypt ? DES_ede3_cbc_encrypt(input, output, len, ks1, ks2, ks3, iv, encrypt) : DES_ede3_cbc_encrypt(input, output, len, ks1, ks2, ks3, iv, !encrypt);
            break;
        case 3: // CFB
            key_len = EVP_CIPHER_CTX_init(ctx);
            if (!key_len || EVP_EncryptInit_ex(ctx, EVP_des_cfb(), NULL, encrypt ? ks1 : ks2, iv) <= 0)
                handle_error("Failed to initialize cipher context");
            key_len = EVP_CipherUpdate(ctx, output, &len, input, len);
            if (key_len <= 0)
                handle_error("Cipher update failed");
            break;
        case 4: // Null encryption
            memcpy(output, input, len);
            return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input> <output> <key> <mode> [iv]\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *fin = fopen(argv[1], "rb");
    if (!fin) handle_error("Failed to open input file");

    FILE *fout = fopen(argv[2], "wb");
    if (!fout) {
        fclose(fin);
        handle_error("Failed to open output file");
    }

    unsigned char key[8];
    if (strlen(argv[3]) != 8)
        handle_error("Key must be 8 bytes long");

    memcpy(key, argv[3], 8);

    DES_cblock ckey;
    memcpy(ckey, key, sizeof(ckey));

    DES_key_schedule ks1, ks2, ks3;
    if (DES_set_key_checked(&ckey, &ks1) != 0)
        handle_error("Failed to set first DES key");
    if (strlen(argv[3]) > 8) {
        if (DES_set_key_checked(ckey, &ks2) != 0 || DES_set_key_checked(ckey, &ks3) != 0)
            handle_error("Failed to set additional DES keys for EDE/ED3");
    }

    int mode = atoi(argv[4]);
    unsigned char iv[DEFAULT_IV_LEN];
    if (argc == 6) {
        strncpy((char *)iv, argv[5], DEFAULT_IV_LEN);
    } else {
        memset(iv, 0, DEFAULT_IV_LEN);
    }

    fseek(fin, 0L, SEEK_END);
    long input_size = ftell(fin);
    rewind(fin);

    unsigned char *input = malloc(input_size);
    if (!input) handle_error("Failed to allocate memory for input");
    fread(input, 1, input_size, fin);

    unsigned char *output = malloc(input_size + EVP_MAX_BLOCK_LENGTH);
    if (!output) {
        free(input);
        handle_error("Failed to allocate memory for output");
    }

    int encrypt = mode >= 0; // Positive mode indicates encryption
    des_encrypt_decrypt(input, output, input_size, &ks1, strlen(argv[3]) > 8 ? &ks2 : NULL, strlen(argv[3]) > 16 ? &ks3 : NULL, encrypt, mode, iv, DEFAULT_IV_LEN);

    fwrite(output, 1, input_size, fout);

    free(input);
    free(output);
    fclose(fin);
    fclose(fout);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Error Handling**: Uses `handle_error` for basic error reporting.
- **Memory Management**: Allocates memory for input/output and frees it after use.
- **Cipher Modes**: Supports ECB, EDE/ED3 (via OpenSSL), and CFB modes. Null encryption is a simple memcpy.
- **Key Derivation**: Uses DES keys directly; expandable for longer keys using more complex KDFs.
- **IV Handling**: Allows user-specified IV length with default of 8 bytes.

### Note:
This code uses OpenSSL for cryptographic operations, which must be linked during compilation (`gcc -o des_utility des_utility.c -lssl -lcrypto`). Ensure OpenSSL is installed and properly configured in your environment.

