import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.messaging.Message;
import org.springframework.messaging.MessageChannel;

public class WebSocketLoggingHandlerAdapter implements ChannelInterceptor {

    private static final Logger logger = LoggerFactory.getLogger(WebSocketLoggingHandlerAdapter.class);

    @Override
    public Message<?> preSend(Message<?> message, MessageChannel channel) {
        StompHeaderAccessor accessor = StompHeaderAccessor.wrap(message);
        logger.info("Message received: {}", accessor.getMessage());
        return message;
    }
}

