```rust
use reqwest::Client;
use serde::{Deserialize, Serialize};
use tokio::sync::Mutex;
use redis_async::AsyncCommands;
use std::collections::HashMap;
use std::time::Duration;
use tokio::time::sleep;

#[derive(Serialize, Deserialize)]
struct WeatherConfig {
    api_url: String,
    update_interval_seconds: u64,
}

#[derive(Deserialize)]
struct DroneMission {
    region: String,
}

#[derive(Debug)]
struct WeatherData {
    temperature: f32,
    humidity: f32,
    wind_speed: f32,
}

async fn fetch_weather_data(client: &Client, api_url: &str, token: &str) -> Result<WeatherData, reqwest::Error> {
    let response = client.get(api_url)
        .bearer_auth(token)
        .send()
        .await?;

    if !response.status().is_success() {
        return Err(reqwest::Error::new(
            reqwest::StatusCode::from_u16(response.status().as_u16()).unwrap(),
            reqwest::ErrorKind::Status,
            "Non-successful status code",
        ));
    }

    let weather: WeatherData = response.json().await?;
    Ok(weather)
}

async fn get_cached_weather_data(redis_conn: &mut redis_async::RedisConnection, region: &str) -> Result<WeatherData, redis_async::RedisError> {
    let data: Option<String> = redis_conn.get(region).await?;
    match data {
        Some(data) => serde_json::from_str(&data).map_err(|_| redis_async::RedisError::new(0)),
        None => Ok(WeatherData { temperature: 0.0, humidity: 0.0, wind_speed: 0.0 }), // default
    }
}

async fn cache_weather_data(redis_conn: &mut redis_async::RedisConnection, region: &str, data: &WeatherData) -> Result<(), redis_async::RedisError> {
    let serialized = serde_json::to_string(data)?;
    redis_conn.setex(region, Duration::from_secs(60 * 5), serialized).await // cache for 5 minutes
}

async fn update_weather_for_missions(
    client: Client,
    config_file_path: &str,
    api_token: &str,
    redis_url: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let config_data = tokio::fs::read_to_string(config_file_path).await?;
    let config: WeatherConfig = serde_json::from_str(&config_data)?;

    let mut redis_conn = redis_async::Client::open(redis_url.to_owned()).unwrap().get_async_connection().await?;

    loop {
        // Simulate getting missions
        let missions: Vec<DroneMission> = vec![]; // Replace with actual dynamic mission retrieval

        for mission in missions.iter() {
            match get_cached_weather_data(&mut redis_conn, &mission.region).await {
                Ok(weather) => println!("Weather data for {} from cache: {:?}", mission.region, weather),
                Err(_) => {
                    let weather_data = fetch_weather_data(&client, &format!("{}/{}", config.api_url, mission.region), api_token).await?;

                    // Cache the fetched data
                    cache_weather_data(&mut redis_conn, &mission.region, &weather_data).await?;

                    println!("Fetched and cached weather for {}: {:?}", mission.region, weather_data);
                }
            }
        }

        sleep(Duration::from_secs(config.update_interval_seconds)).await;
    }
}

#[tokio::main]
async fn main() {
    let api_token = "your_api_token";
    let redis_url = "redis://127.0.0.1/";
    let config_file_path = "config.json";

    if let Err(e) = update_weather_for_missions(
        reqwest::Client::new(),
        config_file_path,
        api_token,
        redis_url,
    ).await {
        eprintln!("Error: {}", e);
    }
}
```

