const app = express();
app.use(bodyParser.json());

// MongoDB connection setup
const mongoUrl = 'mongodb://localhost:27017/bibleDB';
let db;
MongoClient.connect(mongoUrl, { useNewUrlParser: true, useUnifiedTopology: true }, (err, client) => {
  if (err) throw err;
  logger.info('Connected to MongoDB');
  db = client.db();
});

// Redis cache setup
const redis = new Redis();

// Fetch books from the database or cache
async function getBooksFromCache() {
  const cachedBooks = await redis.get('bible_books');
  if (cachedBooks) return JSON.parse(cachedBooks);

  const collection = db.collection('books');
  const books = await collection.find({}).toArray();

  // Cache the result
  await redis.set('bible_books', JSON.stringify(books), 'EX', 3600);
  logger.info('Books cached in Redis');

  return books;
}

// Text processing to count book references using regex
async function processText(text, books) {
  const bookRegex = new RegExp(`\\b(${books.map(book => book.name.replace(/[\W_]+/g, '\\w*'))})\\b`, 'gi');
  let matches = text.matchAll(bookRegex);

  const count = {};
  for (const match of matches) {
    if (!count[match[0]]) count[match[0]] = 1;
    else count[match[0]]++;
  }

  return count;
}

// API endpoint to process incoming data
app.post('/process', async (req, res) => {
  try {
    const text = req.body.text || '';
    if (!text) throw new Error('No text provided');

    // Get list of books from cache or database
    const books = await getBooksFromCache();

    // Process the incoming text
    const bookCounts = await processText(text, books);

    res.json(bookCounts);
  } catch (error) {
    logger.error(`Error processing request: ${error.message}`);
    res.status(500).send('Internal Server Error');
  }
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

