```csharp
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.SignalR;

public class PageUpdateController : Controller
{
    private readonly IElementService _elementService;
    private readonly IUserPermissionService _userPermissionService;
    private readonly IHubContext<PageRefreshHub> _hubContext;

    public PageUpdateController(IElementService elementService, IUserPermissionService userPermissionService, IHubContext<PageRefreshHub> hubContext)
    {
        _elementService = elementService ?? throw new ArgumentNullException(nameof(elementService));
        _userPermissionService = userPermissionService ?? throw new ArgumentNullException(nameof(userPermissionService));
        _hubContext = hubContext ?? throw new ArgumentNullException(nameof(hubContext));
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId) || string.IsNullOrWhiteSpace(htmlContent))
        {
            return Json(new { success = false, message = "Invalid input parameters." });
        }

        var userId = User.Identity.Name; // Assuming the user's identity is available

        if (!_userPermissionService.HasUpdatePermission(userId, pageSectionId, elementId))
        {
            return Json(new { success = false, message = "Permission denied." });
        }

        try
        {
            bool updateResult = await _elementService.TryUpdateElementAsync(elementId, htmlContent);

            if (!updateResult)
            {
                return Json(new { success = false, message = "Failed to update element due to concurrency conflict or other error." });
            }

            await _hubContext.Clients.All.SendAsync("RefreshPage");

            return Json(new { success = true, message = "Element updated successfully." });
        }
        catch (Exception ex)
        {
            // Log exception details for diagnostics
            // e.g., Logger.LogError(ex, "Failed to update element.");

            return Json(new { success = false, message = "An unexpected error occurred. Please try again later." });
        }
    }
}

// Assume these interfaces are implemented elsewhere

public interface IElementService
{
    Task<bool> TryUpdateElementAsync(string elementId, string htmlContent);
}

public interface IUserPermissionService
{
    bool HasUpdatePermission(string userId, string pageSectionId, string elementId);
}
