    if (count > MAX_STRUCTURES) {
        log_message("Error: Requested size exceeds maximum limit.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed.");
        return -1;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < count; ++i) {
        // Simulating unique CRCFLAG generation
        list[i].CRCFLAG = rand() % UINT_MAX;

        // Simple conflict resolution example: ensure uniqueness
        for (size_t j = 0; j < i; ++j) {
            if (list[j].CRCFLAG == list[i].CRCFLAG) {
                log_message("Conflict in CRC flag generation.");
                --i;
                break;
