import subprocess
import hashlib

def validate_password(encrypted_password, hash_value):
    # Example validation logic using SHA256 for demonstration purposes
    if hashlib.sha256(encrypted_password.encode()).hexdigest() != hash_value:
        raise ValueError("Password validation failed.")

def modify_kickstart_config(input_file, output_file, placeholders, encrypted_password, expected_hash):
    try:
        with open(input_file, 'r') as file:
            content = file.read()

        for placeholder, value in placeholders.items():
            content = content.replace(f'{{{placeholder}}}', value)

        validate_password(encrypted_password, expected_hash)

        new_content = f"{content}\nnew_password={encrypted_password}"

        with open(output_file, 'w') as file:
            file.write(new_content)

    except subprocess.CalledProcessError as e:
        print(f"Subprocess error: {e}")
    except ValueError as ve:
        print(ve)
    except Exception as ex:
        print(f"An unexpected error occurred: {ex}")

def execute_sed_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result.stdout.decode()
    except subprocess.CalledProcessError as e:
        print(f"Sed command failed with error: {e.stderr.decode()}")
        raise

# Example usage
input_file = 'kickstart.cfg'
output_file = 'new_kickstart.cfg'
placeholders = {'USERNAME': 'testuser', 'HOSTNAME': 'example.com'}
encrypted_password = 'encrypted_password_here'
expected_hash = 'expected_hash_of_encrypted_password'

modify_kickstart_config(input_file, output_file, placeholders, encrypted_password, expected_hash)
