// Assuming these structures are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

extern void log_structure_creation(NFAPI_CRC_INDICATION_PDU_T *structure);
extern int validate_structure(NFAPI_CRC_INDICATION_PDU_T *structure, int crc_flag_rules[]);

int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Memory allocation for the list of structures
    *nfalist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return -1;
    }

    for (int i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&lock);

        // Populate each structure
        (*nfalist)[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1; // Example range
        (*nfalist)[i].RNTI = rand() % 5000 + 1; // Example range

        int crc_flag_index = (rand() % num_structures) % sizeof(crc_flag_rules) / sizeof(int);
        if (crc_flag_rules[crc_flag_index] == 1) {
            (*nfalist)[i].CRCFLAG = 1;
        } else {
            (*nfalist)[i].CRCFLAG = 0;
        }

        // Log the creation of each structure
        log_structure_creation(&(*nfalist)[i]);

        pthread_mutex_unlock(&lock);

        // Validate the populated structure
        if (!validate_structure(&(*nfalist)[i], crc_flag_rules)) {
            fprintf(stderr, "Validation failed for structure at index %d\n", i);
        }
    }

    pthread_mutex_destroy(&lock);
    return 0;
}

int read_and_find_max(int *array, int array_size, int *max) {
    if (array == NULL || max == NULL || array_size <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    *max = array[0];
    for (int i = 1; i < array_size; ++i) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &array[i]);

        if (array[i] > *max) {
            *max = array[i];
        }
    }

    printf("The largest integer is: %d\n", *max);
    return 0;
}
