#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function prototypes for external dependencies
int callSpellCheckService(const char *word);

// Helper function to trim words from the start or end of a string
char* trimWords(char *str, const char **words_to_trim, int count, int trim_start) {
    char *result = strdup(str);
    if (!result) return NULL;

    for (int i = 0; i < count; ++i) {
        char *word_to_trim = words_to_trim[i];
        size_t word_len = strlen(word_to_trim);

        while ((trim_start && result[0] == ' ') || (!trim_start && strstr(result + strlen(result) - word_len, word_to_trim))) {
            if (trim_start) {
                // Trim from start
                memmove(result, result + word_len + 1, strlen(result) + 1);
            } else {
                // Trim from end
                char *end = result + strlen(result) - word_len;
                if (*(end + word_len) == ' ') *(end + word_len) = '\0';
                else return NULL; // Malformed string (no space before word to trim)
            }
        }
    }

    return result;
}

// Helper function to capitalize words in a string
char* capitalizeWords(char *str, int (*spellCheck)(const char *)) {
    size_t len = strlen(str);
    char *result = malloc(len + 1);
    if (!result) return NULL;

    int i, j;
    for (i = 0, j = 0; i < len; ++i) {
        // Capitalize each word
        if ((str[i] == ' ' || i == 0) && islower(str[i + 1])) {
            result[j++] = toupper(str[i + 1]);
            ++i;

            // Spell check the capitalized word
            int start = (i > 1) ? j - strlen(&result[j - strlen(&str[i])]) : 0;
            char *word = &result[start];
            while (j < len && isalnum(str[i])) {
                result[j++] = str[i++];
            }
            result[j] = '\0'; // Null-terminate word for spell check
            if (!spellCheck(word)) {
                free(result);
                return NULL; // Spell-check failed
            }
        } else {
            result[j++] = str[i];
        }
    }

    result[j] = '\0';
    return result;
}

char* trimAndCapitalize(char *input, int size_limit, const char **words_to_trim, int count) {
    if (!input || !size_limit || !words_to_trim || count <= 0) {
        // Invalid input handling
        fprintf(stderr, "Invalid input.\n");
        return NULL;
    }

    char *trimmed_start = trimWords(input, words_to_trim, count, 1);
    if (!trimmed_start) {
        free(trimmed_start);
        return NULL; // Error in trimming start
    }

    char *trimmed_end = trimWords(trimmed_start, words_to_trim, count, 0);
    free(trimmed_start); // Free temporary allocation

    if (!trimmed_end) {
        fprintf(stderr, "Invalid input for end trimming.\n");
        return NULL; // Error in trimming end
    }

    int trimmed_len = strlen(trimmed_end);

    if (trimmed_len > size_limit) {
        free(trimmed_end);
        return NULL; // Exceeds size limit
    }

    char *capitalized = capitalizeWords(trimmed_end, callSpellCheckService);
    free(trimmed_end); // Free temporary allocation

    if (!capitalized) {
        fprintf(stderr, "Capitalization or spell-checking failed.\n");
        return NULL;
    }

    return capitalized;
}

