```java
import java.nio.charset.Charset;
import java.security.MessageDigest;
import java.util.concurrent.*;
import java.util.logging.Logger;
import org.slf4j.LoggerFactory;

public class HashingService {
    private static final Logger logger = LoggerFactory.getLogger(HashingService.class);

    private final ExecutorService executor;
    private final ConcurrentHashMap<String, String> cache;
    private final int maxCacheSize;

    public HashingService(int threadPoolSize, int cacheSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
        this.cache = new LinkedHashMap<String, String>(cacheSize, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > maxCacheSize;
            }
        };
        this.maxCacheSize = cacheSize;
    }

    public CompletableFuture<String> computeHash(String input, String encodingType, boolean useSHA256) throws IllegalArgumentException {
        if (input == null || input.length() > 1000) {
            throw new IllegalArgumentException("Input string must not be null or exceed 1000 characters.");
        }

        return CompletableFuture.supplyAsync(() -> {
            try {
                Charset charset = Charset.forName(encodingType);
                MessageDigest digest;

                if (useSHA256) {
                    digest = MessageDigest.getInstance("SHA-256");
                } else {
                    digest = MessageDigest.getInstance("MD5");
                }

                byte[] hashBytes = digest.digest(input.getBytes(charset));
                StringBuilder hexString = new StringBuilder(2 * hashBytes.length);
                for (byte b : hashBytes) {
                    String hex = Integer.toHexString(0xff & b);
                    if (hex.length() == 1) {
                        hexString.append('0');
                    }
                    hexString.append(hex);
                }

                return hexString.toString();
            } catch (Exception e) {
                logger.error("Error computing hash: ", e);
                throw new RuntimeException(e);
            }
        }, executor).thenApply(hash -> {
            synchronized (cache) {
                cache.put(input, hash);
                if (logger.isInfoEnabled()) {
                    logger.info("Computed and cached hash for input: {}", input);
                }
                return hash;
            }
        }).exceptionally(ex -> {
            logger.error("Exception during hash computation", ex);
            throw new CompletionException(ex);
        });
    }

    public static void main(String[] args) {
        // Example usage
        HashingService service = new HashingService(10, 100);

        try {
            String input = "example";
            CompletableFuture<String> futureMD5 = service.computeHash(input, "UTF-8", false);
            String md5Hash = futureMD5.get();
            System.out.println("MD5: " + md5Hash);

            CompletableFuture<String> futureSHA256 = service.computeHash(input, "UTF-8", true);
            String sha256Hash = futureSHA256.get();
            System.out.println("SHA-256: " + sha256Hash);
        } catch (Exception e) {
            logger.error("Error in main method", e);
        }
    }
}

// Unit Tests (Using JUnit)
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class HashingServiceTest {

    private final HashingService hashingService = new HashingService(10, 100);

    @Test
    public void testMD5Hash() throws Exception {
        String input = "example";
        String result = hashingService.computeHash(input, "UTF-8", false).get();
        assertNotNull(result);
        assertEquals("1a79a4d60de6718e8e5b326e338ae533", result);
    }

    @Test
    public void testSHA256Hash() throws Exception {
        String input = "example";
        String result = hashingService.computeHash(input, "UTF-8", true).get();
        assertNotNull(result);
        assertEquals("8843d7f924a82901cc5e91c4026eb97891194a4b7d16aa5da0e1a7fb8ca9b2bc", result);
    }

    @Test
    public void testNullInput() {
        Exception exception = assertThrows(IllegalArgumentException.class, () -> hashingService.computeHash(null, "UTF-8", false));
        assertEquals("Input string must not be null or exceed 1000 characters.", exception.getMessage());
    }

    @Test
    public void testLongInput() throws Exception {
        String input = new String(new char[1001]).replace('\0', 'a');
        assertThrows(IllegalArgumentException.class, () -> hashingService.computeHash(input, "UTF-8", false));
    }
}
```

**Notes:**
- The provided solution includes a non-blocking thread pool and cache implementation using `LinkedHashMap` to handle LRU eviction.
- Logging is done via SLF4J for error handling.
- Cache size and thread pool size are configurable through the constructor.
- A basic unit test setup using JUnit5 is included. Further tests should cover concurrency, Redis integration, rate limiting, etc., based on application requirements.
- External components like Redis caching or rate limiting frameworks (e.g., Guava's RateLimiter) can be integrated as needed.
