class DataProcessor:
    def __init__(self, config_path):
        self.config = self.load_config(config_path)
        self.sensor_queues = defaultdict(queue.Queue)
        self.lock = threading.Lock()
        self.running = True
        self.event_detector = EventDetector(self.config['event_thresholds'])
        # Initialize logging
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    def load_config(self, path):
        with open(path, 'r') as file:
            return yaml.safe_load(file)

    def start_processing(self):
        for sensor_id in self.config['sensor_ids']:
            threading.Thread(target=self.sensor_data_handler, args=(sensor_id,), daemon=True).start()

        threading.Thread(target=self.data_aggregator, daemon=True).start()
        threading.Thread(target=self.monitor_and_log, daemon=True).start()

    def stop_processing(self):
        self.running = False

    def sensor_data_handler(self, sensor_id):
        retry_count = 0
        while self.running:
            try:
                data_packet = SensorAPI.get_sensor_data(sensor_id)
                if not self.validate_data(data_packet):
                    logging.warning(f"Invalid data received from {sensor_id}: {data_packet}")
                    continue

                with self.lock:
                    self.sensor_queues[sensor_id].put(data_packet)

                retry_count = 0
            except Exception as e:
                logging.error(f"Error fetching data for sensor {sensor_id}: {str(e)}")
                if retry_count < self.config['max_retries']:
                    time.sleep(self.config['retry_delay'])
                    retry_count += 1
                else:
                    logging.error(f"Failed to reconnect after max retries for sensor {sensor_id}.")

    def data_aggregator(self):
        while self.running:
            aggregated_data = {}
            for sensor_id, q in self.sensor_queues.items():
                try:
                    if not q.empty():
                        data_packet = q.get()
                        aggregated_data[sensor_id] = data_packet
                except queue.Empty:
                    continue

            if aggregated_data:
                transformed_data = self.transform_data(aggregated_data)
                self.store_data(transformed_data)

                events = self.event_detector.detect_events(transformed_data)
                for event in events:
                    logging.info(f"Event detected: {event}")

    def validate_data(self, data_packet):
        # Implement validation logic
        return True

    def transform_data(self, aggregated_data):
        # Apply filters and transformations
        return aggregated_data

    def store_data(self, transformed_data):
        # Optimize storage with secure methods (e.g., batching)
        SecureStorage.store(transformed_data)

    def monitor_and_log(self):
        while self.running:
            logging.info("Monitoring system status...")
            time.sleep(10)  # Log every 10 seconds

if __name__ == "__main__":
    processor = DataProcessor(config_path='config.yaml')
    try:
        processor.start_processing()
        # Simulate long-running process
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
