```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class MessageDecryptor {

    private static final String AES_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final String HMAC_SHA256_ALGORITHM = "HmacSHA256";

    public static void main(String[] args) {
        // Example usage
        String jsonInput = "[{\"encryptedMessage\": \"...\", \"key\": \"...\", \"iv\": \"...\", \"hmac\": \"...\", \"sender\": \"...\", \"recipient\": \"...\", \"timestamp\": 1234567890}]";

        try {
            String result = decryptAndValidateMessages(jsonInput);
            System.out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static String decryptAndValidateMessages(String jsonInput) throws JsonProcessingException, InterruptedException {
        ObjectMapper objectMapper = new ObjectMapper();
        List<EncryptedMessage> messages = objectMapper.readValue(jsonInput, EncryptedMessage[].class);

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<FutureDecryptionResult> results = executor.invokeAll(
                messages.stream()
                        .map(message -> (Callable<FutureDecryptionResult>) () -> decryptAndValidate(message))
                        .collect(Collectors.toList())
        );

        List<DecryptedMessageResponse> responses = new ArrayList<>();
        for (FutureDecryptionResult result : results) {
            responses.add(result.get());
        }

        executor.shutdown();

        return objectMapper.writeValueAsString(responses);
    }

    private static FutureDecryptionResult decryptAndValidate(EncryptedMessage message) {
        try {
            byte[] keyBytes = Base64.getDecoder().decode(message.getKey());
            Key key = new SecretKeySpec(keyBytes, 0, 16, "AES");

            byte[] ivBytes = Base64.getDecoder().decode(message.getIv());
            IvParameterSpec iv = new IvParameterSpec(ivBytes);

            Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, key, iv);
            String decryptedMessage = new String(cipher.doFinal(Base64.getDecoder().decode(message.getEncryptedMessage())), StandardCharsets.UTF_8);

            Mac mac = Mac.getInstance(HMAC_SHA256_ALGORITHM);
            mac.init(key);
            byte[] expectedHmacBytes = Base64.getDecoder().decode(message.getHmac());
            boolean isValid = MessageDigest.isEqual(mac.doFinal(decryptedMessage.getBytes(StandardCharsets.UTF_8)), expectedHmacBytes);

            return new FutureDecryptionResult(
                    message.getSender(),
                    message.getRecipient(),
                    message.getTimestamp(),
                    decryptedMessage,
                    isValid
            );
        } catch (Exception e) {
            // Log error details for debugging
            e.printStackTrace();
            return new FutureDecryptionResult(message.getSender(), message.getRecipient(), message.getTimestamp(), null, false);
        }
    }

    static class EncryptedMessage {
        private String encryptedMessage;
        private String key;
        private String iv;
        private String hmac;
        private String sender;
        private String recipient;
        private long timestamp;

        // Getters and setters
        // ...
    }

    static class FutureDecryptionResult {
        private final String sender;
        private final String recipient;
        private final long timestamp;
        private final String decryptedMessage;
        private final boolean isValid;

        public FutureDecryptionResult(String sender, String recipient, long timestamp, String decryptedMessage, boolean isValid) {
            this.sender = sender;
            this.recipient = recipient;
            this.timestamp = timestamp;
            this.decryptedMessage = decryptedMessage;
            this.isValid = isValid;
        }

        // Getters
        // ...
    }

    static class DecryptedMessageResponse {
        private final String sender;
        private final String recipient;
        private final long timestamp;
        private final String decryptedMessage;
        private final boolean validationStatus;

        public DecryptedMessageResponse(String sender, String recipient, long timestamp, String decryptedMessage, boolean validationStatus) {
            this.sender = sender;
            this.recipient = recipient;
            this.timestamp = timestamp;
            this.decryptedMessage = decryptedMessage;
            this.validationStatus = validationStatus;
        }

        // Getters
        // ...
    }
}
