import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class Deserializer {
    private static final Map<String, Class<?>> CLASS_CACHE = new HashMap<>();

    public static <T> T deserialize(byte[] data) throws RuntimeException {
        if (data == null || data.length == 0) {
            throw new RuntimeException("Input byte array is null or empty.");
        }

        try (ObjectInputStream ois = createObjectInputStream(data)) {
            Object obj = ois.readObject();
            validateSchema(obj);
            return (T) obj;
        } catch (IOException | ClassNotFoundException e) {
            handleDeserializationException(e, data);
        }
        return null; // This line should never be reached due to RuntimeException
    }

    private static ObjectInputStream createObjectInputStream(byte[] data) throws IOException, ClassNotFoundException {
        Class<?> clazz = findClassFromCache(data.getClass().getName());
        if (clazz == null) {
            throw new ClassNotFoundException("Class not found for deserialization.");
        }

        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais) {
            @Override
            protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                String name = (String) desc.getName();
                Class<?> cls = CLASS_CACHE.get(name);
                if (cls == null) {
                    cls = super.resolveClass(desc); // Attempt to load class normally
                    CLASS_CACHE.put(name, cls);
                }
                return cls;
            }
        };

        ois.setObjectInputFilter(
            filterInfo -> {
                String className = filterInfo.serialClassName();
                Class<?> allowedClass = findClassFromCache(className);
                if (allowedClass == null) {
                    logError("Unauthorized class during deserialization: " + className);
                    return ObjectInputFilter.Status.REJECTED;
                }
                return ObjectInputFilter.Status.ALLOWED;
            }
        );

        return ois;
    }

    private static Class<?> findClassFromCache(String name) {
        return CLASS_CACHE.computeIfAbsent(name, clsName -> {
            try {
                return Class.forName(clsName);
            } catch (ClassNotFoundException e) {
                logError("Failed to load class from cache: " + clsName, e);
                return null;
            }
        });
    }

    private static void validateSchema(Object obj) throws RuntimeException {
        // Placeholder for schema validation logic
        // Fetch the schema from an external system and perform validation on 'obj'
        boolean isValid = true; // Simulated validity check

        if (!isValid) {
            throw new RuntimeException("Deserialized object does not match predefined schema.");
        }
    }

    private static void handleDeserializationException(Exception e, byte[] data) throws RuntimeException {
        logError("Deserialization failed for input data.", e);
        throw new RuntimeException("Failed to deserialize object: " + e.getMessage());
    }

    private static void logError(String message, Exception e) {
        System.err.println(message);
        if (e != null) {
            e.printStackTrace(System.err);
        }
    }

    private static void logError(String message) {
        System.err.println(message);
    }
}
