#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Supported file types and their corresponding digit count options
typedef struct {
    const char *extension;
    int digitCount;
} FileType;

const FileType supportedFileTypes[] = {
    {".txt", 5},
    {".jpg", 3},
    {".png", 3},
    {".pdf", 5}
};

// Log error messages to an external system (dummy implementation here)
void logError(const char *message) {
    // Replace with actual logging mechanism
    fprintf(stderr, "Error: %s\n", message);
}

int isValidExtension(const char *filename, const FileType types[], int numTypes) {
    for (int i = 0; i < numTypes; ++i) {
        if (strstr(filename, types[i].extension) != NULL) {
            return types[i].digitCount;
        }
    }
    logError("Unsupported file type or missing extension.");
    return -1;
}

void parseFilename(const char *input, char **name, char **extension) {
    const char *dot = strrchr(input, '.');
    if (!dot || dot == input) {
        logError("Invalid filename: no extension found.");
        *name = strdup(input);
        *extension = NULL;
        return;
    }

    size_t nameLen = dot - input;
    *name = strndup(input, nameLen);
    *extension = strdup(dot);
}

void modifyFilename(const char *input, const char *fileTypeOption) {
    char *name = NULL, *extension = NULL;
    parseFilename(input, &name, &extension);

    if (!extension) {
        free(name);
        return;
    }

    int digitCount = isValidExtension(extension, supportedFileTypes, sizeof(supportedFileTypes) / sizeof(FileType));
    if (digitCount < 0) {
        free(name);
        free(extension);
        return;
    }

    char newFilename[256];
    sprintf(newFilename, "%s_%03d%s", name, rand() % 1000, fileTypeOption);

    printf("Modified Filename: %s\n", newFilename);

    // Free allocated memory
    free(name);
    if (extension) {
        free(extension);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <filename> <fileTypeOption>\n", argv[0]);
        return EXIT_FAILURE;
    }

    modifyFilename(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Performance**: The function minimizes string copies by using `strndup` and `strdup`.
- **Error Handling**: Logs errors for invalid filenames, missing extensions, or unsupported file types.
- **Resource Management**: Frees all dynamically allocated memory.
- **User Experience**: Accepts command-line arguments for filename and file type options.
- **Maintainability**: Functions are modular with meaningful variable names and comments.
- **Edge Case Management**: Handles edge cases like filenames without an extension, starting with a dot, or empty strings.

