```php
<?php

class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRounds = 12;
    private $passwordAttemptsLog = [];
    private $generatedStringsCache = [];

    public function generateSecureRandomString($length) {
        if (isset($this->generatedStringsCache[$length]) && 
            (time() - $this->generatedStringsCache[$length]['timestamp']) < 3600) {
            return $this->generatedStringsCache[$length]['string'];
        }

        $charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_+=<>?';
        if (!$this->validateCharacterSet($charset)) {
            $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%'; // Fallback
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[random_int(0, strlen($charset) - 1)];
        }

        $this->generatedStringsCache[$length] = ['string' => $randomString, 'timestamp' => time()];

        return $randomString;
    }

    public function hashPassword($password) {
        static $attemptsCount = 0;
        static $lastAttemptTime = 0;

        if ($this->rateLimitExceeded()) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        $hashed = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRounds]);
        $this->hashedPassword = $hashed;

        // Reset attempts count on successful hash
        $attemptsCount = 0;
        return $hashed;
    }

    private function rateLimitExceeded() {
        global $attemptsCount, $lastAttemptTime;

        if ((time() - $lastAttemptTime) < 60 && $attemptsCount >= 100) {
            return true;
        }

        if ((time() - $lastAttemptTime) >= 60) {
            $attemptsCount = 0;
            $lastAttemptTime = time();
        }

        $attemptsCount++;
        return false;
    }

    public function checkPassword($password) {
        $result = password_verify($password, $this->hashedPassword);

        if (!$result) {
            $this->logPasswordAttempts($_SERVER['REMOTE_ADDR'], 'failure');
        } else {
            $this->logPasswordAttempts($_SERVER['REMOTE_ADDR'], 'success');
        }

        return $result;
    }

    private function logPasswordAttempts($ipAddress, $result) {
        if (!isset($this->passwordAttemptsLog[$ipAddress])) {
            $this->passwordAttemptsLog[$ipAddress] = [];
        }

        array_push($this->passwordAttemptsLog[$ipAddress], ['timestamp' => time(), 'result' => $result]);
        // Ensure only the last 100 attempts are kept
        if (count($this->passwordAttemptsLog[$ipAddress]) > 100) {
            array_shift($this->passwordAttemptsLog[$ipAddress]);
        }
    }

    public function validateCharacterSet($characterSet) {
        return preg_match('/[A-Z]/', $characterSet)
            && preg_match('/[a-z]/', $characterSet)
            && preg_match('/\d/', $characterSet)
            && preg_match('/[\W_]/', $characterSet);
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRounds = $rounds;
        } else {
            throw new InvalidArgumentException("Salt rounds must be between 12 and 31.");
        }
    }

    public function resetPassword() {
        $newPassword = $this->generateSecureRandomString(16);
        $this->hashPassword($newPassword);

        // Invalidate cache for the previous length
        foreach ($this->generatedStringsCache as $length => $value) {
            unset($this->generatedStringsCache[$length]);
        }

        // Clear password attempts log
        $this->passwordAttemptsLog = [];
    }

    public function logPasswordAttemptsToDB($ipAddress, $result) {
        // Placeholder for actual database interaction.
        file_put_contents('password_attempts_log.txt', json_encode([$ipAddress => ['timestamp' => time(), 'result' => $result]]) . PHP_EOL, FILE_APPEND);
    }

    private function searchAndFilterLogs($searchCriteria = []) {
        // Example of searching logs based on given criteria
        if (file_exists('password_attempts_log.txt')) {
            $logs = file_get_contents('password_attempts_log.txt');
            return json_decode($logs, true);
        }

        return [];
    }

    public function adjustSaltRoundsBasedOnStrength($password) {
        // Example logic for adjusting salt rounds
        $strength = strlen(preg_replace('/[^A-Za-z0-9]/', '', $password));
        if ($strength > 12) {
            $this->setSaltRoundCount(18);
        } elseif ($strength > 8) {
            $this->setSaltRoundCount(15);
        } else {
            $this->setSaltRoundCount(12);
        }
    }
}
