```cpp
#include <forward_list>
#include <string>
#include <functional>
#include <iostream>
#include <mutex>
#include <locale>
#include <codecvt>

// A thread-safe logger for operation details.
class Logger {
public:
    static void log(const std::string& message) {
        // Use a mutex to ensure thread safety in logging
        std::lock_guard<std::mutex> lock(mutex_);
        std::cout << message << std::endl;
    }

private:
    static std::mutex mutex_;
};

std::mutex Logger::mutex_;

// A function that inserts a string after the first occurrence of another string.
template <typename Allocator = std::allocator<char>>
void insert_after_first_occurrence(
    std::forward_list<std::string, Allocator>& flist,
    const std::string& target,
    const std::string& to_insert,
    std::function<bool(const std::string&, const std::string&)> compare_func = 
        [](const std::string& a, const std::string& b) { return a == b; }) {

    std::lock_guard<std::mutex> lock(mutex_); // Ensure thread safety

    auto it = flist.begin();
    bool found = false;

    while (it != flist.end()) {
        if (compare_func(*it, target)) {
            found = true;
            break;
        }
        ++it;
    }

    if (found) {
        it = std::next(it); // Move to the element after the matched one
        flist.insert_after(std::prev(it), to_insert);
        Logger::log("Inserted '" + to_insert + "' after first occurrence of '" + target + "'.");
    } else {
        flist.push_back(to_insert);
        Logger::log("Target '" + target + "' not found. Inserted at end: '" + to_insert + "'.");
    }
}

// Example usage with a custom case-insensitive comparator
void example_usage() {
    std::locale loc;
    auto case_insensitive_compare = [&loc](const std::string& a, const std::string& b) {
        return std::use_facet<std::ctype<char>>(loc).eq(std::toupper(a[0]), std::toupper(b[0])) &&
               a == b; // Simplified for single character comparison
    };

    std::forward_list<std::string> mylist = {"apple", "banana", "cherry"};

    insert_after_first_occurrence(mylist, "Banana", "kiwi", case_insensitive_compare);

    for (const auto& str : mylist) {
        std::cout << str << std::endl;
    }
}

int main() {
    example_usage();
    return 0;
}
```

### Key Points:
- The function uses `std::forward_list` iterators to efficiently traverse and modify the list.
- A mutex is used for thread safety when accessing shared resources like logs.
- Custom comparison functions allow flexibility in how strings are compared (e.g., case-insensitive).
- Logging provides operation feedback, which aids debugging and monitoring.
- The code handles international character sets by using locale-based comparisons where necessary.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>

#define MAX_IMAGES 100

int convert_images_to_pdf(const char *directory_path, const char *output_file_name, char image_files[][256], int num_images) {
    sem_t semaphore;
    DIR *dir;
    struct dirent *entry;
    char command[1024];
    int result = 1;

    // Create a semaphore with an initial value
    if (sem_init(&semaphore, 0, num_images) != 0) {
        perror("Semaphore initialization failed");
        return 1;
    }

    // Open the directory
    dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        sem_destroy(&semaphore);
        return 1;
    }

    for (int i = 0; i < num_images && result == 1; ++i) {
        snprintf(command, sizeof(command), "convert %s/%s %s.%d.pdf", directory_path, image_files[i], output_file_name, i + 1);

        // Wait on the semaphore
        sem_wait(&semaphore);

        if (system(command) != 0) {
            perror("Image conversion failed");
            result = 1;
        } else {
            snprintf(command, sizeof(command), "pdftk %s.%d.pdf cat output combined.pdf", output_file_name, i + 1);
            if (i == 0) {
                // Initialize the first PDF
                snprintf(command, sizeof(command), "mv %s.1.pdf %s", output_file_name, output_file_name);
            } else {
                result = system(command) != 0 ? 1 : 0;
            }
        }

        // Post on the semaphore
        sem_post(&semaphore);

        // Remove individual PDF after merging
        snprintf(command, sizeof(command), "rm -f %s.%d.pdf", output_file_name, i + 1);
        system(command);
    }

    closedir(dir);

    // Rename combined.pdf to output file name
    snprintf(command, sizeof(command), "mv combined.pdf %s/%s.pdf", directory_path, output_file_name);
    if (system(command) != 0) {
        perror("Failed to rename combined PDF");
        result = 1;
    }

    // Destroy the semaphore
    sem_destroy(&semaphore);

    return result == 0 ? 0 : 1;
}
```

This code creates a semaphore to manage concurrent access when processing images. It reads from a directory, converts image files (using ImageMagick's `convert` command), merges them into a single PDF using `pdftk`, and handles cleanup operations. The function returns 0 for success or 1 if any operation fails. Note that you need to ensure both `ImageMagick` and `PDFtk` are installed on your system.

