### SSH Connection Management with JSch

```java
import com.jcraft.jsch.*;

public class SSHManager {
    private Session session;

    public void connect(String username, String password, String host, int port) throws JSchException {
        if (session != null && session.isConnected()) {
            session.disconnect();
        }

        JSch jsch = new JSch();
        session = jsch.getSession(username, host, port);
        session.setPassword(password);

        session.setConfig("StrictHostKeyChecking", "no");
        session.connect();
    }

    public void disconnect() throws JSchException {
        if (session != null && session.isConnected()) {
            session.disconnect();
        }
    }

    public ChannelExec executeCommand(String command) throws JSchException, IOException {
        ChannelExec channel = (ChannelExec) session.openChannel("exec");
        channel.setCommand(command);
        channel.connect();

        return channel;
    }
}
```

### Deployment Manager

```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DeploymentManager {

    private final ExecutorService executorService;

    public DeploymentManager(int concurrencyLevel) {
        executorService = Executors.newFixedThreadPool(concurrencyLevel);
    }

    public void deployToServer(String serverInfo, String dockerCommand) {
        executorService.submit(() -> {
            try (SSHManager sshManager = new SSHManager()) {
                sshManager.connect(serverInfo.username(), serverInfo.password(), 
                                  serverInfo.host(), serverInfo.port());

                ChannelExec channel = sshManager.executeCommand(dockerCommand);
                // Handle output and errors
                channel.getInputStream().close();
                channel.getErrorStream().close();

                sshManager.disconnect();
            } catch (Exception e) {
                // Log error and retry logic
            }
        });
    }

    public void shutdown() {
        executorService.shutdown();
    }
}
```

