using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Data.SqlClient;

[Serializable]
public class CustomDataStructure
{
    // Define properties according to your schema.
}

public interface IDataValidator<T>
{
    bool Validate(T data);
}

public class BinaryFileHandler<T> where T : new()
{
    private readonly string _filePath;
    private readonly IDataValidator<T> _validator;
    private readonly string _connectionString;

    public BinaryFileHandler(string filePath, IDataValidator<T> validator, string connectionString)
    {
        _filePath = filePath;
        _validator = validator;
        _connectionString = connectionString;
    }

    public T LoadData()
    {
        if (!File.Exists(_filePath))
            throw new FileNotFoundException("Binary file not found.");

        try
        {
            using (var stream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.None))
            {
                var formatter = new BinaryFormatter();
                return (T)formatter.Deserialize(stream);
            }
        }
        catch (SerializationException ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

    public void SaveData(T data)
    {
        if (!_validator.Validate(data))
        {
            throw new InvalidOperationException("Validation failed for the custom data structure.");
        }

        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        // Persist changes to the database.
                        UpdateDatabase(data, connection, transaction);

                        using (var stream = new FileStream(_filePath, FileMode.Create, FileAccess.Write, FileShare.None))
                        {
                            var formatter = new BinaryFormatter();
                            formatter.Serialize(stream, data);
                        }

                        transaction.Commit();
                    }
                    catch
                    {
                        transaction.Rollback();
                        throw;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

    private void UpdateDatabase(T data, SqlConnection connection, SqlTransaction transaction)
    {
        // Implement database update logic here.
    }

    private void LogError(string message)
    {
        try
        {
            using (var logStream = new FileStream("error_log.txt", FileMode.Append, FileAccess.Write))
            {
                var writer = new StreamWriter(logStream);
                writer.WriteLine($"{DateTime.Now}: {message}");
                writer.Close();
            }
        }
        catch
        {
            // Handle logging failure gracefully.
        }
    }
}

