```php
<?php

class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRounds = 12;
    private $cache = [];
    private const MIN_SALT_ROUNDS = 12;
    private const MAX_SALT_ROUNDS = 31;
    private const CHARACTER_SET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:',.<>?";
    private $logFilePath = 'password_attempts.log';

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        $characterSet = self::CHARACTER_SET;
        if (!$this->validateCharacterSet($characterSet)) {
            throw new Exception("Invalid character set");
        }

        $randomString = '';
        $maxIndex = strlen($characterSet) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[random_int(0, $maxIndex)];
        }

        $this->cache[$length] = $randomString;

        return $randomString;
    }

    public function hashPassword($password) {
        if (strlen($password) === 0) {
            throw new Exception("Password cannot be empty");
        }
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRounds]);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        $hasUpper = preg_match('/[A-Z]/', $characterSet);
        $hasLower = preg_match('/[a-z]/', $characterSet);
        $hasDigit = preg_match('/\d/', $characterSet);
        $hasSpecial = preg_match('/[\W_]/', $characterSet);

        return $hasUpper && $hasLower && $hasDigit && $hasSpecial;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < self::MIN_SALT_ROUNDS || $rounds > self::MAX_SALT_ROUNDS) {
            throw new Exception("Invalid salt rounds count");
        }
        $this->saltRounds = $rounds;
    }

    public function resetPassword() {
        if (empty($this->hashedPassword)) {
            throw new Exception("No password to reset");
        }

        $passwordLength = strlen(base64_decode($this->generateSecureRandomString(10)));
        unset($this->cache[$passwordLength]);

        $newPassword = $this->generateSecureRandomString(12);
        $this->hashPassword($newPassword);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        $logEntry = sprintf("[%s] IP: %s Result: %s\n", date('Y-m-d H:i:s'), $ipAddress, $result ? 'Success' : 'Failure');
        file_put_contents($this->logFilePath, $logEntry, FILE_APPEND);
    }

    public function enforceTwoFactorAuthentication() {
        // Simulate sending a 2FA code
        $code = rand(100000, 999999);

        echo "A two-factor authentication code has been sent: $code\n";
        return $this->validate2FACode($code); 
    }

    private function validate2FACode($inputCode) {
        // Simulate the validation process
        $correctCode = rand(100000, 999999);

        return $inputCode === $correctCode;
    }
}

// Example usage:
$passwordManager = new AdvancedPasswordManager();
$passwordManager->setSaltRoundCount(14);
$passwordManager->hashPassword('SecurePass123!');
echo "Password is valid: " . ($passwordManager->checkPassword('SecurePass123!') ? 'Yes' : 'No');

``` 

