// Function to process the string adaptively
char* adaptiveStringProcessor(const char *input, size_t max_size, const char *token, void (*progress_callback)(int, double, double)) {
    if (!input || !max_size || !token) return NULL;

    WordList word_list;
    int fetch_result = fetchWordList(&word_list, token);
    if (fetch_result != 0) return NULL; // Handle fetch error

    size_t total_word_length = 0;
    for (int i = 0; i < word_list.count; ++i) {
        total_word_length += strlen(word_list.words_to_remove[i]);
    }

    // Estimate system load and adjust max_size
    // For simplicity, simulate with a random factor here
    double system_load_factor = 1.0 + (rand() % 10 / 100.0);
    size_t adjusted_max_size = max_size - total_word_length;
    if (adjusted_max_size < 20) { // Minimal size to hold meaningful data
        free(word_list.words_to_remove); // Assuming dynamic allocation in real scenario
        return NULL;
    }

    char *result = malloc(adjusted_max_size + 1);
    if (!result) {
        free(word_list.words_to_remove);
        return NULL; // Memory allocation failure
    }

    const char *start = input;
    size_t current_length = 0;

    // Process the string by removing specified words from start and end
    while (*start && total_word_length > 0) {
        int match = 1;
        for (int i = 0; i < word_list.count && match; ++i) {
            if (strncmp(start, word_list.words_to_remove[i], strlen(word_list.words_to_remove[i])) == 0 &&
                (isspace(*(start + strlen(word_list.words_to_remove[i]))) || *(start + strlen(word_list.words_to_remove[i])) == '\0')) {
                start += strlen(word_list.words_to_remove[i]);
                total_word_length -= strlen(word_list.words_to_remove[i]) + 1; // Include space
                match = 0;
            }
        }
        if (match) break; // No more words to remove at the beginning
    }

    const char *end = input + strlen(input);
    while (*end && total_word_length > 0) {
        int match = 1;
        for (int i = 0; i < word_list.count && match; ++i) {
            if (strncmp(end - strlen(word_list.words_to_remove[i]) - 1, word_list.words_to_remove[i], strlen(word_list.words_to_remove[i])) == 0 &&
                (*(end - strlen(word_list.words_to_remove[i])) == ' ' || *(end - strlen(word_list.words_to_remove[i])) == '\0')) {
                end -= (strlen(word_list.words_to_remove[i]) + 1);
                total_word_length -= strlen(word_list.words_to_remove[i]) + 1; // Include space
                match = 0;
            }
        }
        if (match) break; // No more words to remove at the end
    }

    size_t result_length = start - input + end - start;

    if (result_length > adjusted_max_size) {
        free(result);
        free(word_list.words_to_remove);
        return NULL;
    }

    strncpy(result, start, end - start);
    result[end - start] = '\0';

    // Capitalize words in the remaining string
    capitalizeWords(result);

    // Log progress using callback
    if (progress_callback) {
        double completed_percentage = 100.0 * ((double)(end - input) / strlen(input));
        time_t current_time = time(NULL);
        double estimated_remaining_time = system_load_factor * ((double)(current_time % 60) + 1); // Mocked value
        progress_callback(completed_percentage, adjusted_max_size, estimated_remaining_time);
    }

    free(word_list.words_to_remove);

    return result;
}

// Example usage of the function with a callback for progress reporting
void progressCallback(int completed_operations, double accumulated_value, double remaining_time) {
    printf("Completed Operations: %d\n", completed_operations);
    printf("Accumulated Value: %.2f\n", accumulated_value);
    printf("Estimated Remaining Time: %.2fs\n", remaining_time);
}

int main() {
