    pthread_t threads[MAX_PARALLEL_OPERATIONS];

    for (int i = 0; i < MAX_PARALLEL_OPERATIONS; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))adaptiveStringProcessor, (void *)input);
        sem_wait(&semaphore); // Ensure we don't exceed the parallel operations limit
    }

    for (int i = 0; i < MAX_PARALLEL_OPERATIONS; ++i) {
