import asyncio
import aiohttp
from base64 import b64decode
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives import hashes
import os
import logging
import json

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class AsynchronousDataAggregator:
    def __init__(self, rate_limit: int):
        self.rate_limit = rate_limit
        self.semaphore = asyncio.Semaphore(rate_limit)

    async def fetch_data(self, session, source_info):
        url = source_info['url']
        method = source_info['method'].lower()
        identifier = source_info['identifier']

        try:
            async with self.semaphore, session.request(method, url) as response:
                if response.status == 200:
                    data = await response.json()
                    return (identifier, data)
                else:
                    logger.error(f"Failed to fetch {url}: Status code {response.status}")
                    return (identifier, None)
        except Exception as e:
            logger.error(f"Exception occurred while fetching {url}: {e}")
            return (identifier, None)

    async def aggregate_data(self, sources, initial_dict):
        async with aiohttp.ClientSession() as session:
            tasks = [self.fetch_data(session, source) for source in sources]
            results = await asyncio.gather(*tasks)
            for identifier, data in results:
                if data is not None:
                    initial_dict[identifier] = data
        return initial_dict

    async def decrypt_message(self, encrypted_msg, method, clearance_level):
        # Fetch keys and IVs from CSP based on the method and clearance level
        key_info = self.get_key_from_csp(method, clearance_level)
        if not key_info:
            logger.error(f"Failed to retrieve key for {method} at clearance level {clearness_level}")
            return None

        try:
            decrypted_data = await asyncio.to_thread(self.decrypt_with_method, encrypted_msg, method, **key_info)
            return decrypted_data
        except Exception as e:
            logger.error(f"Decryption failed: {e}")
            return None

    def get_key_from_csp(self, method, clearance_level):
        # Simulated fetching key and IV based on the chosen CSP
        # Assume config.json or environment variables are used to determine settings
        csp_config = self.load_csp_config()
        if method not in csp_config:
            logger.error(f"Method {method} not supported by any configured CSP")
            return None

        # Logic to select appropriate key and IV based on the clearance level
        keys_ivs = csp_config[method]
        if str(clearance_level) in keys_ivs:
            return keys_ivs[str(clearance_level)]

        logger.error(f"No key found for {method} at clearance level {clearance_level}")
        return None

    def load_csp_config(self):
        # Load configuration from a file or environment
        try:
            with open('config.json') as config_file:
                return json.load(config_file)
        except FileNotFoundError:
            logger.error("Configuration file not found, falling back to environment variables")
            return {
                'DES': {'1': {'key': os.getenv('DES_KEY_1'), 'iv': os.getenv('DES_IV_1')}},
                'AES': {'2': {'key': os.getenv('AES_KEY_2'), 'iv': os.getenv('AES_IV_2')}},
                'RSA': {'3': {'private_key_pem': os.getenv('RSA_PRIVATE_KEY_PEM')}}
            }

    def decrypt_with_method(self, encrypted_msg, method, **kwargs):
        if method == "DES":
            key = b64decode(kwargs['key'])
            iv = b64decode(kwargs['iv'])
            cipher = Cipher(algorithms.TripleDES(key), modes.CBC(iv), backend=default_backend())

        elif method == "AES":
            key = b64decode(kwargs['key'])
            iv = b64decode(kwargs['iv'])
            cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())

        elif method == "RSA":
            private_key = rsa.RSAPrivateKey.from_pem(kwargs['private_key_pem'].encode())
            encrypted_msg_bytes = b64decode(encrypted_msg)
            return private_key.decrypt(
                encrypted_msg_bytes,
                padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=None)
            ).decode('utf-8')

        else:
            logger.error(f"Unsupported decryption method: {method}")
            return None

        decryptor = cipher.decryptor()
        decrypted_padded_msg = decryptor.update(b64decode(encrypted_msg)) + decryptor.finalize()

        # Unpadding
        pad_len = decrypted_padded_msg[-1]
        return decrypted_padded_msg[:-pad_len].decode('utf-8')

# Example usage:
