Below is a modular cryptographic library in C that supports various DES cipher modes: ECB, EDE, EDE3, CFB, and null encryption for testing purposes. This implementation uses dynamic loading of shared libraries to integrate seamlessly with an existing application stack.

```c
// des_library.h

#ifndef DES_LIBRARY_H
#define DES_LIBRARY_H

#include <stdint.h>
#include <stdbool.h>

typedef enum {
    MODE_ECB,
    MODE_EDE,
    MODE_EDE3,
    MODE_CFB,
    MODE_NULL
} CipherMode;

typedef struct {
    void *handle;
    void (*encrypt)(uint8_t *input, size_t input_len, uint8_t *output);
    void (*decrypt)(uint8_t *input, size_t input_len, uint8_t *output);
} CipherModeHandler;

CipherModeHandler* load_cipher_mode(CipherMode mode);
void unload_cipher_mode(CipherModeHandler *handler);
bool encrypt_data(CipherModeHandler *handler, const uint8_t *data, size_t data_len, uint8_t *encrypted);
bool decrypt_data(CipherModeHandler *handler, const uint8_t *data, size_t data_len, uint8_t *decrypted);

#endif // DES_LIBRARY_H
```

```c
// des_library.c

#include "des_library.h"
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>

static void* load_shared_lib(const char *lib_path) {
    return dlopen(lib_path, RTLD_NOW | RTLD_LOCAL);
}

CipherModeHandler* load_cipher_mode(CipherMode mode) {
    const char *library_name;
    CipherModeHandler *handler = malloc(sizeof(CipherModeHandler));
    if (!handler) {
        fprintf(stderr, "Failed to allocate memory for cipher handler.\n");
        return NULL;
    }

    switch (mode) {
        case MODE_ECB:
            library_name = "./libdes_ecb.so";
            break;
        case MODE_EDE:
            library_name = "./libdes_ede.so";
            break;
        case MODE_EDE3:
            library_name = "./libdes_ede3.so";
            break;
        case MODE_CFB:
            library_name = "./libdes_cfb.so";
            break;
        case MODE_NULL:
            handler->handle = NULL;
            return handler; // Null mode doesn't require a shared lib
        default:
            fprintf(stderr, "Invalid cipher mode.\n");
            free(handler);
            return NULL;
    }

    handler->handle = load_shared_lib(library_name);
    if (!handler->handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        free(handler);
        return NULL;
    }

    *(void **)(&handler->encrypt) = dlsym(handler->handle, "encrypt");
    *(void **)(&handler->decrypt) = dlsym(handler->handle, "decrypt");

    const char *dlsym_error = dlerror();
    if (dlsym_error) {
        fprintf(stderr, "Failed to load functions: %s\n", dlsym_error);
        unload_cipher_mode(handler);
        return NULL;
    }

    return handler;
}

void unload_cipher_mode(CipherModeHandler *handler) {
    if (!handler || !handler->handle) return;

    dlclose(handler->handle);
    free(handler);
}

bool encrypt_data(CipherModeHandler *handler, const uint8_t *data, size_t data_len, uint8_t *encrypted) {
    if (!handler || !handler->encrypt) {
        fprintf(stderr, "Invalid handler or missing encryption function.\n");
        return false;
    }

    handler->encrypt((uint8_t *)data, data_len, encrypted);
    return true;
}

bool decrypt_data(CipherModeHandler *handler, const uint8_t *data, size_t data_len, uint8_t *decrypted) {
    if (!handler || !handler->decrypt) {
        fprintf(stderr, "Invalid handler or missing decryption function.\n");
        return false;
    }

    handler->decrypt((uint8_t *)data, data_len, decrypted);
    return true;
}
```

### Shared Libraries for Each Mode

Each mode (ECB, EDE, EDE3, CFB) requires a corresponding shared library implementing `encrypt` and `decrypt` functions.

