// Forward declarations for logging and caching utilities
void logMessage(const std::string& message);
bool cacheHitCheck(double latitude, double longitude);
std::string getCachedData(double latitude, double longitude);
void cacheData(double latitude, double longitude, const std::string& data);

class NetworkClient {
public:
    virtual ~NetworkClient() = default;
    virtual bool FetchDataFromApi(const std::string& url, std::string& response) = 0;
};

// TestDouble for NetworkClient
class MockNetworkClient : public NetworkClient {
public:
    MockNetworkClient(bool shouldSucceed)
        : shouldSucceed_(shouldSucceed) {}

    bool FetchDataFromApi(const std::string& url, std::string& response) override {
        if (shouldSucceed_) {
            response = "{\"weather\": \"sunny\"}";
            logMessage("API call successful");
            return true;
        } else {
            logMessage("API call failed");
            return false;
        }
    }

private:
    bool shouldSucceed_;
};

// Actual implementation of NetworkClient
class RealNetworkClient : public NetworkClient {
public:
    bool FetchDataFromApi(const std::string& url, std::string& response) override {
        CURL* curl = curl_easy_init();
        if (!curl) return false;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        CURLcode res = curl_easy_perform(curl);
        bool success = (res == CURLE_OK);

        if (!success) {
            logMessage("Network error occurred");
        }

        curl_easy_cleanup(curl);
        return success;
    }

private:
    static size_t WriteCallback(void* contents, size_t size, size_t nmemb, std::string* s) {
        size_t newLength = size * nmemb;
        try {
            s->append((char*)contents, newLength);
        } catch (std::bad_alloc& e) {
            return 0;
        }
        return newLength;
    }
};

// Cache implementation
class WeatherCache {
public:
    static const int CACHE_EXPIRY_TIME = 300; // 5 minutes

    bool isCached(double latitude, double longitude) {
        auto it = cache_.find(std::make_pair(latitude, longitude));
        if (it != cache_.end()) {
            if ((std::time(nullptr) - it->second.timestamp) < CACHE_EXPIRY_TIME) {
                logMessage("Cache hit");
                return true;
            } else {
                logMessage("Cache expired");
                cache_.erase(it);
            }
        }
        logMessage("Cache miss");
        return false;
    }

    void storeInCache(double latitude, double longitude, const std::string& data) {
        cache_[std::make_pair(latitude, longitude)] = {data, std::time(nullptr)};
        logMessage("Data cached");
    }

    std::string getCachedData(double latitude, double longitude) {
        auto it = cache_.find(std::make_pair(latitude, longitude));
        return it->second.data;
    }

private:
    struct CacheEntry {
        std::string data;
        time_t timestamp;
    };

    using CacheMap = std::unordered_map<std::pair<double, double>, CacheEntry>;
    CacheMap cache_;
};

// Logging function
void logMessage(const std::string& message) {
    std::cout << "[LOG] " << message << std::endl;
}

// Main program logic
int main() {
    // Set up test conditions
    MockNetworkClient mockSuccess(true);
    MockNetworkClient mockFailure(false);

    double latitude = 40.7128;  // Example coordinates (New York)
    double longitude = -74.0060;

    std::string apiResponse;
    WeatherCache weatherCache;

    if (!cacheHitCheck(latitude, longitude)) {
        if (!mockSuccess.FetchDataFromApi("http://api.weather.com", apiResponse)) {
            mockFailure.FetchDataFromApi("http://api.weather.com", apiResponse);
        }
        cacheData(latitude, longitude, apiResponse);
    } else {
        std::cout << "Using cached data: " << getCachedData(latitude, longitude) << std::endl;
    }

    return 0;
}

bool cacheHitCheck(double latitude, double longitude) {
    static WeatherCache weatherCache; // Singleton pattern for demonstration
    return weatherCache.isCached(latitude, longitude);
}

void cacheData(double latitude, double longitude, const std::string& data) {
    static WeatherCache weatherCache; // Singleton pattern for demonstration
    weatherCache.storeInCache(latitude, longitude, data);
}

std::string getCachedData(double latitude, double longitude) {
    static WeatherCache weatherCache; // Singleton pattern for demonstration
    return weatherCache.getCachedData(latitude, longitude);
}
