```java
import java.io.OutputStream;
import java.io.PrintWriter;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class DisjointPairsCounter {

    public static int countDisjointPairs(int[] array) throws Exception {
        if (array == null || array.length > 100000) {
            throw new IllegalArgumentException("Array size is invalid.");
        }
        if (containsDuplicates(array)) {
            throw new IllegalArgumentException("Array contains duplicate elements.");
        }

        UnionFind uf = new UnionFind(array.length);
        int disjointPairsCount = 0;

        long startTime;
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                startTime = System.currentTimeMillis();
                if (uf.find(i) != uf.find(j)) {
                    disjointPairsCount++;
                    uf.union(i, j);
                }
                logExecutionTime(System.currentTimeMillis() - startTime);

                // Simulate API logging for each pair check
                sendApiLog(disjointPairsCount, i, j);
            }
        }

        return disjointPairsCount;
    }

    private static boolean containsDuplicates(int[] array) {
        int n = array.length;
        int[] count = new int[n + 1];
        Arrays.fill(count, 0);

        for (int num : array) {
            if (num < 0 || num > n) {
                throw new IllegalArgumentException("Array contains invalid elements.");
            }
            if (++count[num] > 1) {
                return true;
            }
        }
        return false;
    }

    private static void logExecutionTime(long durationMillis) {
        System.out.println("Check took " + durationMillis + " milliseconds");
    }

    private static void sendApiLog(int disjointPairsCount, int i, int j) throws Exception {
        String url = "http://example.com/api/log";  // Replace with actual endpoint
        HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        connection.setRequestProperty("Content-Type", "application/json");

        String jsonPayload = String.format("{\"disjointPairsCount\": %d, \"pairChecked\": [\"%d\", \"%d\"]}", 
                                           disjointPairsCount, i, j);

        try (OutputStream os = connection.getOutputStream()) {
            byte[] input = jsonPayload.getBytes(StandardCharsets.UTF_8);
            os.write(input, 0, input.length);
        }

        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new Exception("Failed to log data. HTTP error code: " + responseCode);
        }
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]); // Path compression
            }
            return parent[p];
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);

            if (rootP == rootQ) return;

            // Union by rank
            if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }

    public static void main(String[] args) {
        try {
            int[] array = {1, 2, 3, 4, 5};
            System.out.println("Disjoint Pairs Count: " + countDisjointPairs(array));
        } catch (Exception e) {
            System.err.println(e.getMessage());
        }
    }
}
```

### Explanation
- The `countDisjointPairs` method is the main function that calculates disjoint pairs using a Union-Find structure.
- **Union-Find Class**: Implements path compression and union by rank for efficient performance.
- **Error Handling**: Checks for invalid array size, duplicates, and out-of-bound elements.
- **API Integration**: Logs operations to an external API endpoint with JSON payloads.
- **Concurrency Consideration**: While thread safety is considered in design, actual concurrency handling might require further modifications based on specific use cases.

