import java.io.IOException;
import java.util.Random;
import java.util.logging.*;

public class ServiceManager {

    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private boolean running = true;
    private int consecutiveFailures = 0;
    private static final int MAX_CONSECUTIVE_FAILURES = 3;

    public static void main(String[] args) {
        setupLogger();
        ServiceManager manager = new ServiceManager();

        // Command-line interface to start, stop, and configure the program
        while (manager.running) {
            System.out.println("Enter command: start | stop | exit");
            String command = System.console().readLine();

            switch (command.toLowerCase()) {
                case "start":
                    manager.startService();
                    break;
                case "stop":
                    manager.stopService();
                    break;
                case "exit":
                    manager.running = false;
                    break;
                default:
                    logger.warning("Unknown command: " + command);
            }
        }

        logger.info("Exiting program.");
    }

    private void setupLogger() {
        try {
            LogManager.getLogManager().readConfiguration(ServiceManager.class.getResourceAsStream("/logging.properties"));
            Handler fileHandler = new FileHandler("service_manager.log", 1024 * 1024, 3, true);
            Logger rootLogger = Logger.getLogger("");
            rootLogger.addHandler(fileHandler);
        } catch (IOException e) {
            System.err.println("Failed to setup logger configuration: " + e.getMessage());
        }
    }

    private void startService() {
        try {
            int delayInterval = fetchConfiguredDelay();
            Thread.sleep(delayInterval);
            if (startServiceLogic()) {
                consecutiveFailures = 0;
                logger.info("Service started successfully.");
            } else {
                handleFailure();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.severe("Service interrupted: " + e.getMessage());
        } catch (Exception e) {
            logger.severe("Error starting service: " + e.getMessage());
        }
    }

    private boolean startServiceLogic() throws Exception {
        // Simulate service logic
        Random random = new Random();
        return random.nextBoolean(); // Randomly simulate success/failure for illustration
    }

    private void stopService() {
        try {
            sendStopMessageToMessagingSystem();
            logger.info("Service stopped and message sent.");
        } catch (Exception e) {
            logger.severe("Error stopping service: " + e.getMessage());
        }
    }

    private void handleFailure() {
        consecutiveFailures++;
        if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
            running = false;
            logger.severe("Maximum consecutive failures reached. Stopping the program.");
        } else {
            logger.warning("Service failed to start. Attempt " + consecutiveFailures);
        }
    }

    private void sendStopMessageToMessagingSystem() {
        // Simulate sending a message to a messaging system
        System.out.println("Sending stop message to messaging system...");
    }

    private int fetchConfiguredDelay() {
        // Simulate fetching delay interval from configuration management system
        Random random = new Random();
        return 1000 + random.nextInt(5000); // Return a random delay between 1 and 5 seconds
    }
}
