async function runUnitTests(moduleLabel, testSuite) {
    const maxConcurrentRequests = 5;
    let runningTests = 0;

    // Helper function to control the rate limit for concurrent tests.
    async function executeWithRateLimit(testFunc, testName) {
        return new Promise((resolve, reject) => {
            (async () => {
                while (runningTests >= maxConcurrentRequests) {
                    await new Promise(resolve => setTimeout(resolve, 100)); // Wait and retry
                }
                runningTests++;

                console.log(`Executing ${testName} in module: ${moduleLabel}`);
                try {
                    await testFunc();
                    console.log(`${testName}: PASSED`);
                } catch (error) {
                    console.error(`${testName}: FAILED with error`, error);
                } finally {
                    runningTests--;
                    // Resetting the mocking library
                    blueslip.reset(); 
                    resolve();
                }
            })();
        });
    }

    const testPromises = testSuite.map((testFunc, index) => {
        const testName = `Test Case ${index + 1}`;
        return executeWithRateLimit(testFunc, testName);
    });

    console.log(`Starting tests for module: ${moduleLabel}`);

    try {
        await Promise.all(testPromises);
        console.log(`All tests completed successfully for module: ${moduleLabel}`);
    } catch (error) {
        console.error('An error occurred during test execution:', error);
    }
}

