<?php

session_start();

function performClinicUpdate($oauthClient, $clinicID, $newStatus, $clientIP) {
    // Step 1: Authenticate User using OAuth 2.0
    try {
        if (!isset($_SESSION['access_token'])) {
            // Assuming oauthClient is a properly configured OAuth client instance.
            $_SESSION['state'] = bin2hex(random_bytes(32));
            $authUrl = $oauthClient->getAuthorizationUrl(['state' => $_SESSION['state']]);

            // Redirect to auth URL
            header('Location: ' . $authUrl);
            exit;
        } else {
            if (isset($_GET['state']) && $_GET['state'] === $_SESSION['state']) {
                $accessToken = $oauthClient->getAccessToken();
                $_SESSION['access_token'] = $accessToken->getToken();
            } else {
                throw new Exception('Invalid state token, possible CSRF detected.');
            }
        }
    } catch (Exception $e) {
        logError("Authentication Error: " . $e->getMessage());
        return generatePEMMessage("Authentication Failed");
    }

    // Step 2: Transactional Update in Database
    try {
        $pdo = new PDO('mysql:host=your_host;dbname=your_db', 'username', 'password');
        $pdo->beginTransaction();

        // Fetch Active Clinic IDs from External API
        $activeClinicIDs = fetchActiveClinicIDs();

        if (!in_array($clinicID, $activeClinicIDs)) {
            throw new Exception("Invalid Clinic ID.");
        }

        // Validate IP Address range (Example validation logic)
        if (!validateIPAddress($clientIP, '192.168.1.0', '192.168.1.255')) {
            throw new Exception("Unauthorized IP address.");
        }

        // Generate unique identifier for log entry
        $updateLogID = uniqid('log_', true);

        // Update Database
        $stmt = $pdo->prepare("
            UPDATE clinic_table SET status = :status, last_modified_ip = :ip, 
            last_modified_date = NOW() WHERE clinic_id = :clinicID
        ");
        $stmt->execute([':status' => $newStatus, ':ip' => $clientIP, ':clinicID' => $clinicID]);

        // Commit Transaction
        $pdo->commit();
    } catch (Exception $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }
        logError("Database Update Error: " . $e->getMessage());
        return generatePEMMessage("Update Failed");
    }

    // Return Success Message in PEM format
    return generatePEMMessage("Update Successful");

}

function fetchActiveClinicIDs() {
    // Mocked function to simulate external API call for active clinic IDs
    return [1, 2, 3, 4]; // Example IDs
}

function validateIPAddress($ip, $startRange, $endRange) {
    // Basic IP range validation
    return (ip2long($ip) >= ip2long($startRange)) && (ip2long($ip) <= ip2long($endRange));
}

function logError($message) {
    error_log(date('Y-m-d H:i:s') . " - ERROR: $message", 3, 'error.log');
}

function generatePEMMessage($message) {
    return "-----BEGIN SUCCESS MESSAGE-----\n$message\n-----END SUCCESS MESSAGE-----";
}
