```javascript
// Helper Functions

function fetchScriptWithRetry(url, retries = 3) {
    return new Promise((resolve, reject) => {
        const attemptFetch = (remainingRetries) => {
            fetch(url)
                .then(response => response.text())
                .then(data => resolve(data))
                .catch(error => {
                    if (remainingRetries > 0) {
                        console.warn(`Retrying fetch for ${url}: attempts left ${remainingRetries}`);
                        attemptFetch(remainingRetries - 1);
                    } else {
                        reject(new Error(`Failed to fetch script from ${url} after multiple retries`));
                    }
                });
        };
        attemptFetch(retries);
    });
}

async function validateScriptKey(key) {
    try {
        const response = await fetch('https://external-api.com/validateScriptKeys');
        const validKeys = await response.json();
        return validKeys.includes(key);
    } catch (error) {
        console.error(`Error validating script key ${key}:`, error);
        return false;
    }
}

async function getScriptMetadata(key) {
    try {
        const response = await fetch(`https://config-service.com/metadata/${key}`);
        return response.json();
    } catch (error) {
        console.error(`Error fetching metadata for script key ${key}:`, error);
        return null;
    }
}

function sanitizeHTML(html) {
    // Use a DOM parser to prevent XSS attacks
    const tempDiv = document.createElement('div');
    tempDiv.textContent = html;
    return tempDiv.innerHTML;
}

// Main Function

async function renderFooterScripts(scripts) {
    if (!Array.isArray(scripts)) {
        throw new Error("Input must be an array of script objects");
    }

    const validScripts = [];
    for (const scriptObj of scripts) {
        const { src, type, key } = scriptObj;

        // Validate required properties
        if (!src || !type || !key) {
            console.warn(`Skipping invalid script object: ${JSON.stringify(scriptObj)}`);
            continue;
        }

        // Check script key validity
        if (!(await validateScriptKey(key))) {
            console.warn(`Invalid script key: ${key}. Skipping.`);
            continue;
        }

        // Fetch metadata (e.g., fallback URL)
        const metadata = await getScriptMetadata(key);

        validScripts.push({ src, type, key, metadata });
    }

    let scriptsHTML = '';

    for (const { src, type, key, metadata } of validScripts) {
        try {
            let scriptContent;

            // Check cache first
            if (sessionStorage.getItem(src)) {
                scriptContent = sessionStorage.getItem(src);
            } else {
                const cachedScript = localStorage.getItem(src);

                if (cachedScript) {
                    scriptContent = cachedScript;
                } else {
                    scriptContent = await fetchScriptWithRetry(src);

                    // Cache the fetched content
                    sessionStorage.setItem(src, scriptContent);
                    localStorage.setItem(src, scriptContent);
                }
            }

            if (!scriptContent.trim()) {
                console.warn(`Empty script content for ${src}. Skipping.`);
                continue;
            }

            const sanitizedContent = sanitizeHTML(scriptContent);

            scriptsHTML += `
                <script type="${type}">
                    ${sanitizedContent}
                </script>
            `;

        } catch (error) {
            console.error(`Error processing script ${key} from ${src}:`, error);
            if (metadata && metadata.fallbackUrl) {
                try {
                    const fallbackScript = await fetchScriptWithRetry(metadata.fallbackUrl);

                    if (!fallbackScript.trim()) {
                        console.warn(`Empty fallback script content for ${metadata.fallbackUrl}. Skipping.`);
                        continue;
                    }

                    scriptsHTML += `
                        <script type="${type}">
                            ${sanitizeHTML(fallbackScript)}
                        </script>
                    `;
                } catch (fallbackError) {
                    console.error(`Failed to fetch fallback script from ${metadata.fallbackUrl}:`, fallbackError);
                }
            }
        }
    }

    return `<footer>${scriptsHTML}</footer>`;
}

// Unit Tests

describe('renderFooterScripts', () => {
    it('should render valid scripts correctly', async () => {
        const mockScripts = [
            { src: 'https://example.com/script1.js', type: 'application/javascript', key: 'validKey1' },
            // Add more test cases as needed
        ];

        document.body.innerHTML = `<div id="footer"></div>`;

        const result = await renderFooterScripts(mockScripts);
        document.getElementById('footer').innerHTML = result;

        expect(document.querySelectorAll('script').length).toBeGreaterThan(0);
    });

    it('should skip invalid scripts', async () => {
        const mockScripts = [
            { src: '', type: 'application/javascript', key: 'invalidKey1' },
            // Add more test cases as needed
        ];

        document.body.innerHTML = `<div id="footer"></div>`;

        const result = await renderFooterScripts(mockScripts);
        document.getElementById('footer').innerHTML = result;

        expect(document.querySelectorAll('script').length).toBe(0);
    });

    // More tests can be added to cover different scenarios
});
