use std::env;
use std::fs;
use std::path::PathBuf;
use std::collections::HashMap;
use xmlparser::{Document, Node};
use xpath2rs::XPathContext;

struct ParserCache {
    cache: HashMap<String, Vec<Node>>,
}

impl ParserCache {
    fn new() -> Self {
        Self { cache: HashMap::new() }
    }

    fn get(&self, query: &str) -> Option<&Vec<Node>> {
        self.cache.get(query)
    }

    fn insert(&mut self, query: String, nodes: Vec<Node>) {
        self.cache.insert(query, nodes);
    }
}

fn create_directory_and_set_env(var_name: &str, dir_name: &str) -> Result<PathBuf, std::io::Error> {
    if let Ok(path_str) = env::var(var_name) {
        return Ok(PathBuf::from(&path_str));
    }

    let new_dir = PathBuf::from(dir_name);
    fs::create_dir_all(&new_dir)?;
    env::set_var(var_name, new_dir.to_string_lossy());
    Ok(new_dir)
}

fn parse_xml_with_xpath(xml_data: &str, xpath_expression: &str, cache: &mut ParserCache) -> Result<Vec<Node>, String> {
    if let Some(cached_result) = cache.get(xpath_expression) {
        return Ok(cached_result.clone());
    }

    match Document::parse(&xml_data) {
        Ok(doc) => {
            let mut xpath_context = XPathContext::new();
            let result = doc.eval_xpath(&mut xpath_context, xpath_expression);

            match result {
                Ok(nodes) if nodes.len() > 1 => Err("Multiple matching nodes found".to_string()),
                Ok(nodes) if nodes.is_empty() => Err("No data found".to_string()),
                Ok(nodes) => {
                    cache.insert(xpath_expression.to_string(), nodes.clone());
                    Ok(nodes)
                }
                Err(err) => Err(format!("XPath error: {}", err)),
            }
        },
        Err(err) => Err(format!("XML parsing error: {:?}", err)),
    }
}

fn external_api_validation(data: &[Node]) -> bool {
    // Placeholder for integrating with an external API
    true
}

fn main() -> Result<(), String> {
    let xml_data = r#"<root><child><subchild>data</subchild></child></root>"#;
    let xpath_expression = "//subchild";
    let env_var_name = "MY_ENV_VAR";
    let dir_name = "my_directory";

    let mut cache = ParserCache::new();

    let directory_path = create_directory_and_set_env(env_var_name, dir_name).map_err(|err| err.to_string())?;

    println!("Using or created directory at: {:?}", directory_path);

    match parse_xml_with_xpath(xml_data, xpath_expression, &mut cache) {
        Ok(nodes) => {
            if external_api_validation(&nodes) {
                for node in nodes {
                    println!("Extracted data: {:?}", node.content());
                }
            } else {
                return Err("Data validation failed".to_string());
            }
        },
        Err(err) => return Err(format!("Error during parsing: {}", err)),
    }

    Ok(())
}
