import requests

class Product:
    def __init__(self, name, category, price, quantity):
        self.name = name
        self.category = category
        self.price = price
        self.quantity = quantity

def get_risks_from_api(category):
    api_url = f"https://api.example.com/risk_assessment?category={category}"
    try:
        response = requests.get(api_url)
        response.raise_for_status()
        return response.json().get('risks', 'No detailed risks found')
    except requests.RequestException:
        return "API request failed, unable to fetch detailed risks"

def determine_risks(product):
    category_risk_lookup = {
        'electronics': 'high',
        'food': 'medium',
        'clothing': 'low',
        # Add more categories as needed
    }

    base_risk_level = category_risk_lookup.get(product.category.lower(), 'unknown')

    additional_risks = get_risks_from_api(product.category)

    if product.price > 1000:
        base_risk_level = 'high'
    elif product.quantity < 10 and base_risk_level != 'high':
        base_risk_level = 'medium'

    return f"Base Risk Level: {base_risk_level}. Additional Risks: {additional_risks}"

# Example usage:
product = Product(name="Smartphone", category="electronics", price=1200, quantity=5)
risks = determine_risks(product)
