```php
<?php

class AdvancedWebPageManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cache = [];
    private $passwordAttempts = [];
    private $twoFactorEnabled = false;
    private $maxLoginAttemptsPerIp = 5;
    private $loginAttemptWindow = 300; // 5 minutes in seconds

    public function generateSecureRandomString($length, $characterSet) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        $validCharacterSet = $this->validateCharacterSet($characterSet);
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, strlen($validCharacterSet) - 1);
            $randomString .= $validCharacterSet[$randomIndex];
        }

        $this->cache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        if (!isset($this->hashedPassword)) {
            $options = ['cost' => $this->saltRoundCount];
            $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);
        }
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (preg_match('/[A-Z]/', $characterSet) && preg_match('/[a-z]/', $characterSet)
            && preg_match('/\d/', $characterSet) && preg_match('/[\W_]/', $characterSet)) {
            return $characterSet;
        }

        // Fallback mechanism
        return 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()';
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        }
    }

    public function resetPassword() {
        unset($this->cache);
        $newPassword = $this->generateSecureRandomString(16, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()');
        $options = ['cost' => $this->saltRoundCount];
        $this->hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT, $options);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Log to a file (append mode)
        $logEntry = sprintf("[%s] IP: %s - Result: %s\n", date('Y-m-d H:i:s'), $ipAddress, $result ? 'Success' : 'Failure');
        file_put_contents('password_attempts.log', $logEntry, FILE_APPEND);
    }

    public function enforceTwoFactorAuthentication() {
        if ($this->twoFactorEnabled) {
            // Implement simple 2FA logic
            $code = rand(100000, 999999);
            // Send code via SMS or email (pseudo-code)
            echo "2FA Code: " . $code;
        }
    }

    public function limitLoginAttemptsPerIp($ipAddress) {
        if (!isset($this->passwordAttempts[$ipAddress])) {
            $this->passwordAttempts[$ipAddress] = ['count' => 0, 'timestamp' => time()];
        }

        $currentAttempt = &$this->passwordAttempts[$ipAddress];

        if (time() - $currentAttempt['timestamp'] > $this->loginAttemptWindow) {
            $currentAttempt['count'] = 1;
            $currentAttempt['timestamp'] = time();
            return false; // Allow login attempt
        }

        if ($currentAttempt['count'] < $this->maxLoginAttemptsPerIp) {
            $currentAttempt['count']++;
            return false; // Allow login attempt
        }

        return true; // Block further attempts
    }

    public function sanitizeInput($input) {
        return htmlspecialchars(strip_tags(trim($input)));
    }
}
```

