          for (let fieldName of fieldNamesToRefresh) {
            const dialogField = dialogFields.find(field => field.name === fieldName);
            if (!dialogField) continue;

            if (!recentResultsCache[fieldName]) {
              recentResultsCache[fieldName] = await dbService.fetchDataByResourceId(resourceId, fieldName);
            }

            // Send refresh status message to parent window
            window.parent.postMessage({status: 'refreshing', resourceId, fieldName}, '*');

            try {
              const response = await this.refreshResource(resourceId, dialogField.url, recentResultsCache[fieldName]);

              if (response.success) {
                dialogField.data = response.data;
                // Update last access time in DB
                dbService.updateLastAccessTime(resourceId, fieldName);
              }
            } catch (err) {
              console.error(`Error refreshing resource ${resourceId}:`, err);
              this.log(LOG_FILE_PATH, 'error', `Failed to refresh resource: ${resourceId}`);
            }

            // Send success message to parent window
            window.parent.postMessage({status: 'refreshed', resourceId, fieldName}, '*');
          }
        }
      } catch (err) {
        console.error('Error in refreshFieldsAndManageDirectories:', err);
      }
    };

    this.createDirectoryWithEnvVar = async (dirName) => {
      const envVarName = `MY_APP_DIR_${dirName}`;
      let dirPath = process.env[envVarName];

      if (!dirPath) {
        dirPath = path.join(os.homedir(), 'my_app', dirName);
        try {
          await fs.promises.mkdir(dirPath, { recursive: true });
          process.env[envVarName] = dirPath;
          this.log(LOG_FILE_PATH, 'info', `Directory created and env set: ${dirName}`);

          // Record metadata in external DB
          dbService.recordMetadata({ dirName, creationTime: new Date(), lastAccessed: null, status: 'active' });
        } catch (err) {
          console.error(`Error creating directory ${dirName}:`, err);
          this.log(LOG_FILE_PATH, 'error', `Failed to create directory: ${dirName}`);
        }
      }

      return dirPath;
    };

    this.cleanupOldDirectories = async () => {
      try {
        const metadata = await dbService.fetchDirectoryMetadata();

        if (metadata.length > MAX_DIRS) {
          const sortedByLastAccessed = metadata.sort((a, b) => a.lastAccessTime - b.lastAccessTime);
          const dirsToDelete = sortedByLastAccessed.slice(0, -(MAX_DIRS));

          for (const dirMeta of dirsToDelete) {
            try {
              await fs.promises.rmdir(dirMeta.path, { recursive: true });
              dbService.deleteMetadata(dirMeta.id);
              this.log(LOG_FILE_PATH, 'info', `Deleted old directory: ${dirMeta.name}`);
            } catch (err) {
              console.error(`Error deleting directory ${dirMeta.name}:`, err);
              this.log(LOG_FILE_PATH, 'warn', `Failed to delete directory: ${dirMeta.name}`);
            }
          }
        }
      } catch (err) {
        console.error('Error during cleanup:', err);
        this.log(LOG_FILE_PATH, 'error', 'Cleanup process failed');
      }
    };

    this.startPeriodicCleanup = () => {
      $interval(this.cleanupOldDirectories.bind(this), CLEANUP_INTERVAL_MS);
    };

    this.refreshResource = async (resourceId, url, cachedData) => {
      // Implement resource refreshing logic here
