```rust
use std::env;
use tokio::fs;
use serde::{Deserialize, Serialize};
use serde_json::json;
use log::{info, error};
use lazy_static::lazy_static;
use once_cell::sync::Lazy;
use simple_logger::SimpleLogger;

#[derive(Serialize, Deserialize)]
struct Config {
    database_url: String,
    cache_enabled: bool,
}

// Cache for configuration settings
static CONFIG_CACHE: Lazy<Cache> = Lazy::new(|| Cache::new());

struct Cache {
    config: Option<Config>,
}

impl Cache {
    fn new() -> Self {
        Cache { config: None }
    }

    async fn get_or_load(&mut self, path: &str) -> Result<&Config, Box<dyn std::error::Error>> {
        if let Some(config) = &self.config {
            Ok(config)
        } else {
            let contents = fs::read_to_string(path).await?;
            let config: Config = serde_json::from_str(&contents)?;
            self.config = Some(config.clone());
            Ok(&self.config.as_ref().unwrap())
        }
    }

    fn clear_cache(&mut self) {
        self.config = None;
    }
}

async fn load_config() -> Result<Config, Box<dyn std::error::Error>> {
    let config_path = "config.json";
    CONFIG_CACHE.get_or_load(config_path).await
}

async fn setup_environment(env: &str) {
    match env {
        "development" => info!("Running in development mode"),
        "staging" => info!("Running in staging mode"),
        "production" => info!("Running in production mode"),
        _ => error!("Unknown environment"),
    }
}

async fn execute_function(args: Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    let env = env::var("ENV").unwrap_or_else(|_| "development".to_string());
    setup_environment(&env).await;

    match args.get(1) {
        Some(func_name) => match func_name.as_str() {
            "run" => info!("Executing run function"),
            "test" => info!("Executing test function"),
            _ => error!("Unknown function: {}", func_name),
        },
        None => error!("No function specified"),
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    SimpleLogger::new().init().unwrap();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        error!("No command line arguments provided");
        return Err("Missing arguments".into());
    }

    let config = load_config().await?;

    // Set environment variables
    env::set_var("DATABASE_URL", &config.database_url);
    info!("Database URL set from configuration");

    execute_function(args).await?;

    CONFIG_CACHE.clear_cache();
    Ok(())
}
```

