    private static Dictionary<string, string> cache = new Dictionary<string, string>();
    private const int MaxParallelOperations = 5;

    public static async Task<object> SendByteArrayToDatabaseAndTrimCapitalize(byte[] inputBytes, Action<int, int, string> progressCallback)
    {
        try
        {
            semaphore = new SemaphoreSlim(MaxParallelOperations);

            if (inputBytes == null)
                throw new ArgumentNullException(nameof(inputBytes));

            string inputData = System.Text.Encoding.UTF8.GetString(inputBytes);
            List<string> wordsToTrim = await FetchWordsToTrimAsync();

            int sizeLimit = CalculateSizeLimit(wordsToTrim, inputData.Length / (wordsToTrim.Count > 0 ? wordsToTrim.Count : 1));
            string trimmedAndCapitalized = TrimAndCapitalize(inputData, wordsToTrim);

            if (trimmedAndCapitalized.Length > sizeLimit)
                return null;

            progressCallback?.Invoke(100, 0, "Completed");

            return trimmedAndCapitalized;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
            return null;
        }
    }

    private static async Task<List<string>> FetchWordsToTrimAsync()
    {
        string cacheKey = "wordsToTrim";
        if (cache.TryGetValue(cacheKey, out string cachedResult))
        {
            return new List<string>(cachedResult.Split(','));
        }

        await semaphore.WaitAsync();

        try
        {
            var response = await httpClient.GetAsync("https://api.example.com/trimWords", HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();

            string result = await response.Content.ReadAsStringAsync();
            cache[cacheKey] = result;
            return new List<string>(result.Split(','));
        }
        finally
        {
            semaphore.Release();
        }
    }

    private static int CalculateSizeLimit(List<string> wordsToTrim, double averageWordLength)
    {
        // Adjust size limit based on word list length and average word length
        return Math.Max(10, (int)(wordsToTrim.Count * averageWordLength * 1.5));
    }

    private static string TrimAndCapitalize(string input, List<string> wordsToTrim)
    {
        foreach (var word in wordsToTrim)
        {
            if (input.StartsWith(word))
                input = input.Substring(word.Length);

            if (input.EndsWith(word))
                input = input.Substring(0, input.Length - word.Length);
        }

        string result = Regex.Replace(input, @"\b\w", m => m.Value.ToUpper());

        return result;
    }
}
```

### Key Points:
- **SemaphoreSlim** is used to control concurrency when fetching words.
- **HttpClient** with caching optimizes external API calls.
- **Error Handling**: Includes checks for null input and exception handling.
- **Memory Management**: Ensures proper disposal of resources (e.g., `HttpClient`).
- **Progress Callback**: Reports progress via a delegate.
- **Size Limit Calculation**: Dynamically adjusts based on word list characteristics.

