enum class LogLevel { INFO, DEBUG, ERROR };

class TransactionLogger {
public:
    TransactionLogger(const std::string& config)
        : config_(config), logLevel_(LogLevel::INFO) {}

    ~TransactionLogger() {
        shutdown();
    }

    void setLogLevel(LogLevel level) {
        std::lock_guard<std::mutex> lock(mutex_);
        logLevel_ = level;
    }

    bool recordTransaction(const std::string& transactionData);

private:
    void workerThread();

    std::string config_;
    LogLevel logLevel_;
    std::queue<std::shared_ptr<Transaction>> transactionQueue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<std::thread> workers_;
    bool stop_ = false;

    void shutdown() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    bool shouldLog(LogLevel level) const {
        return static_cast<int>(level) >= static_cast<int>(logLevel_);
    }

    void logToFile(const std::string& data);
    void logToDatabase(const std::string& data);
    void logToPaymentSystem(const std::string& data);

    template<typename Func>
    bool retryOperation(Func operation, int retries = 3, int delay_ms = 100) {
        for (int attempt = 0; attempt < retries; ++attempt) {
            if (operation()) {
                return true;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms));
        }
        return false;
    }
};

bool TransactionLogger::recordTransaction(const std::string& transactionData) {
    auto transaction = std::make_shared<Transaction>(transactionData);
    {
        std::lock_guard<std::mutex> lock(mutex_);
        transactionQueue_.push(transaction);
    }
    cv_.notify_one();
    return true; // Assuming enqueue is always successful
}

void TransactionLogger::workerThread() {
    while (true) {
        std::shared_ptr<Transaction> transaction;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return stop_ || !transactionQueue_.empty(); });
            if (stop_ && transactionQueue_.empty()) break;

            transaction = transactionQueue_.front();
            transactionQueue_.pop();
        }

        if (config_ == "file") {
            logToFile(transaction->data());
        } else if (config_ == "database") {
            logToDatabase(transaction->data());
        } else if (config_ == "payment_system") {
            logToPaymentSystem(transaction->data());
        }
    }
}

