```java
import com.fasterxml.jackson.databind.ObjectMapper;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.CacheManager;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class JwtService {

    private final ObjectMapper objectMapper;
    private final CacheManager cacheManager;
    private final ExternalApiTokenClient tokenRevocationClient;

    @Autowired
    public JwtService(ObjectMapper objectMapper, CacheManager cacheManager, ExternalApiTokenClient tokenRevocationClient) {
        this.objectMapper = objectMapper;
        this.cacheManager = cacheManager;
        this.tokenRevocationClient = tokenRevocationClient;
    }

    private Map<String, String> loadConfig(String configFilePath) throws IOException {
        return objectMapper.readValue(Files.newBufferedReader(Paths.get(configFilePath)), Map.class);
    }

    public UserClaims processJwt(String jwtToken, String issuer, List<String> audiences, String configFilePath) 
            throws Exception {

        if (isTokenRevoked(jwtToken)) {
            throw new SecurityException("Token has been revoked");
        }

        // Check cache first
        Optional<UserClaims> cachedClaims = getCachedUserClaims(jwtToken);
        if (cachedClaims.isPresent()) {
            return cachedClaims.get();
        }

        // Validate the JWT
        Jws<Claims> claimsJws = Jwts.parserBuilder()
                .setSigningKey(Keys.hmacShaKeyFor(loadConfig(configFilePath).get("jwtSecret").getBytes()))
                .build()
                .parseClaimsJws(jwtToken);

        validateIssuerAndAudience(claimsJws, issuer, audiences);

        // Extract user information
        UserClaims userClaims = new UserClaims(
                claimsJws.getBody().getSubject(),
                (List<String>) claimsJws.getBody().get("roles"),
                claimsJws.getBody().getExpiration()
        );

        // Cache the validated JWT
        cacheUserClaims(jwtToken, userClaims);

        return userClaims;
    }

    private boolean isTokenRevoked(String jwtToken) {
        return tokenRevocationClient.isRevoked(jwtToken);
    }

    private Optional<UserClaims> getCachedUserClaims(String jwtToken) {
        Cache cache = cacheManager.getCache("jwt-cache");
        UserClaims claims = (UserClaims) cache.get(jwtToken, String.class);
        if (claims != null) {
            return Optional.of(claims);
        }
        return Optional.empty();
    }

    private void cacheUserClaims(String jwtToken, UserClaims userClaims) {
        Cache cache = cacheManager.getCache("jwt-cache");
        cache.put(jwtToken, userClaims.toString());
    }

    private void validateIssuerAndAudience(Jws<Claims> claimsJws, String issuer, List<String> audiences) throws Exception {
        if (!issuer.equals(claimsJws.getBody().getIssuer())) {
            throw new SecurityException("Invalid token: Issuer does not match");
        }
        boolean validAudience = audiences.stream().anyMatch(aud -> aud.equals(claimsJws.getBody().getAudience()));
        if (!validAudience) {
            throw new SecurityException("Invalid token: Audience does not match");
        }
    }

}

class UserClaims {

    private final String username;
    private final List<String> roles;
    private final java.util.Date expiration;

    public UserClaims(String username, List<String> roles, java.util.Date expiration) {
        this.username = username;
        this.roles = roles;
        this.expiration = expiration;
    }

    // Getters and potentially other methods

}

interface ExternalApiTokenClient {

    boolean isRevoked(String jwtToken);

}
