using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;

public class DynamicTripleDesDecryptor
{
    private readonly ICryptoServiceProvider _cryptoProvider;
    private readonly ConcurrentQueue<string> _decryptionQueue = new();
    private readonly int _timeoutSeconds;
    private readonly ILogger _logger;

    public DynamicTripleDesDecryptor(ICryptoServiceProvider cryptoProvider, int timeoutSeconds, ILogger logger)
    {
        _cryptoProvider = cryptoProvider ?? throw new ArgumentNullException(nameof(cryptoProvider));
        _timeoutSeconds = timeoutSeconds;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public void EnqueueDecryptionRequest(string encryptedMessage)
    {
        _decryptionQueue.Enqueue(encryptedMessage);
    }

    private string FetchKeyAndIV(string contextId)
    {
        try
        {
            var keyData = _cryptoProvider.GetKey(contextId);
            ValidateKey(keyData.Key);
            ValidateIV(keyData.IV);

            // Log for audit purposes
            _logger.Log($"Fetched Key and IV for context: {contextId}");
            return JsonConvert.SerializeObject(keyData);
        }
        catch (Exception ex)
        {
            _logger.LogError("Error fetching key/IV", ex);
            throw;
        }
    }

    private void ValidateKey(byte[] key)
    {
        if (key.Length != 24) // Triple DES requires a 192-bit key
        {
            throw new CryptographicException("Invalid key length.");
        }
    }

    private void ValidateIV(byte[] iv)
    {
        if (iv.Length != 8) // Triple DES requires an 8-byte IV
        {
            throw new CryptographicException("Invalid IV length.");
        }
    }

    public string DecryptMessage(string contextId, string encryptedMessage)
    {
        var keyData = JsonConvert.DeserializeObject<KeyIVPair>(FetchKeyAndIV(contextId));

        using (var des = TripleDES.Create())
        {
            des.Key = keyData.Key;
            des.IV = keyData.IV;

            var buffer = Convert.FromBase64String(encryptedMessage);
            var decryptedBytes = des.CreateDecryptor().TransformFinalBlock(buffer, 0, buffer.Length);

            // Check for resource leaks
            GC.Collect();
            GC.WaitForPendingFinalizers();

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    public void ProcessQueue()
    {
        while (_decryptionQueue.TryDequeue(out var message))
        {
            try
            {
                // Example contextId usage
                string decryptedMessage = DecryptMessage("exampleContext", message);
                _logger.Log($"Decrypted Message: {decryptedMessage}");
            }
            catch (Exception ex)
            {
                _logger.LogError("Error processing decryption request", ex);
            }
        }
    }

    private string DeriveKey(byte[] masterKey, string contextId)
    {
        using var sha256 = SHA256.Create();
        return sha256.ComputeHash(Encoding.UTF8.GetBytes(contextId + ":" + Convert.ToBase64String(masterKey)));
    }
}

public interface ICryptoServiceProvider
{
    KeyIVPair GetKey(string contextId);
}

public class KeyIVPair
{
    public byte[] Key { get; set; }
    public byte[] IV { get; set; }
}

public interface ILogger
{
    void Log(string message);
    void LogError(string message, Exception ex);
}
