<?php

class FilePasswordManager {
    private $hashedPassword = '';
    private $saltRoundCount;
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
    private $cache = [];
    private $passwordAttemptsLogPath = '/path/to/password_attempts.log';

    public function __construct($saltRoundCount = 12) {
        $this->setSaltRoundCount($saltRoundCount);
    }

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        if (!$this->validateCharacterSet($this->characterSet)) {
            $this->characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?';
        }

        $randomString = '';
        $maxIndex = strlen($this->characterSet) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[random_int(0, $maxIndex)];
        }

        $this->cache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $options = ['cost' => $this->saltRoundCount];
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (preg_match('/[A-Z]/', $characterSet) &&
            preg_match('/[a-z]/', $characterSet) &&
            preg_match('/\d/', $characterSet) &&
            preg_match('/[\W_]/', $characterSet)) {
            return true;
        }
        // Fallback mechanism can be implemented here if needed.
        return false;
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            throw new InvalidArgumentException('Salt round count must be between 12 and 31.');
        }
    }

    public function resetPassword() {
        $newRandomString = $this->generateSecureRandomString(16); // Example length
        $this->hashPassword($newRandomString);
        unset($this->cache[array_search(strlen($newRandomString), array_keys($this->cache))]);
    }

    private function logPasswordAttempts($ipAddress, $result) {
        $logEntry = sprintf("[%s] IP: %s - Result: %s\n", date('Y-m-d H:i:s'), $ipAddress, $result ? 'Success' : 'Failure');

        file_put_contents(
            $this->passwordAttemptsLogPath,
            $logEntry,
            FILE_APPEND | LOCK_EX
        );
    }

    public function calculateFileMD5($filePath) {
        if (!file_exists($filePath)) {
            throw new InvalidArgumentException('File does not exist.');
        }

        return hash_file('md5', $filePath);
    }
}
