#include <nlohmann/json.hpp>

namespace fs = std::filesystem;

class DynamicFileProcessor {
public:
    using MetadataMap = std::map<std::string, std::string>;

    DynamicFileProcessor(const std::string& configFilePath, const std::string& authToken)
        : configFilePath_(configFilePath), authToken_(authToken) {}

    void ProcessFiles(int maxParallelOperations, bool followSymlinks);

private:
    struct FileEntry {
        fs::path filePath;
        MetadataMap metadataKeys;
    };

    struct ProcessResult {
        bool success;
        std::string message;
        std::vector<fs::path> processedFilePaths;
    };

    static const int CacheSize = 100;

    void LoadConfig();
    void FetchMetadata(const FileEntry& fileEntry, MetadataMap& fetchedMetadata);
    void ExecuteCommandAsync(const fs::path& filePath, const std::string& command);
    void ProcessFile(const FileEntry& fileEntry, MetadataMap& metadata);
    void RenameOriginalConfig();
    void LogAction(const std::string& action);
    void ErrorCallback(const std::string& error);

    // Helper functions
    bool IsSymbolicLink(const fs::path& path) const;
    void CacheMetadata(const std::string& cacheKey, MetadataMap&& metadata);
    MetadataMap GetCachedMetadata(const std::string& cacheKey);

    std::string configFilePath_;
    std::vector<FileEntry> filesToProcess_;
    std::string authToken_;

    std::mutex mtx_;
    std::condition_variable cv_;
    int maxParallelOperations_ = 0;

    // Cache
    std::map<std::string, MetadataMap> metadataCache_;
};

void DynamicFileProcessor::LoadConfig() {
    std::ifstream configFile(configFilePath_);
    if (!configFile.is_open()) {
        ErrorCallback("Failed to open config file");
        return;
    }

    nlohmann::json jsonConfig;
    configFile >> jsonConfig;

    for (const auto& entry : jsonConfig["files"]) {
        FileEntry fileEntry;
        fileEntry.filePath = fs::path(entry["file_path"]);
        for (const auto& key : entry["metadata_keys"].items()) {
            fileEntry.metadataKeys[key.key()] = key.value();
        }
        filesToProcess_.push_back(fileEntry);
    }
}

void DynamicFileProcessor::FetchMetadata(const FileEntry& fileEntry, MetadataMap& fetchedMetadata) {
    // Simulating fetching metadata from an external service
    std::string cacheKey = fileEntry.filePath.string() + authToken_;
    if (auto cachedData = GetCachedMetadata(cacheKey)) {
        fetchedMetadata = std::move(cachedData);
        return;
    }

    for (const auto& key : fileEntry.metadataKeys) {
        // Simulate API call and response
        fetchedMetadata[key.first] = "FetchedValueFor_" + key.second;  // Dummy data
    }

    CacheMetadata(cacheKey, std::move(fetchedMetadata));
}

void DynamicFileProcessor::ExecuteCommandAsync(const fs::path& filePath, const std::string& command) {
    auto task = [filePath, command]() {
        int status = system((command + " " + filePath.string()).c_str());
        if (status != 0) {
            ErrorCallback("Failed to execute command for file: " + filePath.string());
        }
    };

    std::thread(task).detach();
}

void DynamicFileProcessor::ProcessFile(const FileEntry& fileEntry, MetadataMap& metadata) {
    // Example operation based on metadata
    if (metadata["file_size"] == "LargeValue") {
        fs::rename(fileEntry.filePath, fileEntry.filePath.string() + ".processed");
    }

    ExecuteCommandAsync(fileEntry.filePath, "dummy_command");  // Replace with actual command
}

void DynamicFileProcessor::RenameOriginalConfig() {
    auto timestamp = std::chrono::system_clock::now().time_since_epoch();
    auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(timestamp).count();
    fs::path newFileName = configFilePath_ + "." + std::to_string(millis) + ".processed";
    fs::rename(configFilePath_, newFileName);
}

void DynamicFileProcessor::LogAction(const std::string& action) {
    // Log the action to a file or console
    std::cout << "LOG: " << action << std::endl;
}

void DynamicFileProcessor::ErrorCallback(const std::string& error) {
    std::cerr << "ERROR: " << error << std::endl;
}

bool DynamicFileProcessor::IsSymbolicLink(const fs::path& path) const {
    return fs::is_symlink(path);
}

void DynamicFileProcessor::CacheMetadata(const std::string& cacheKey, MetadataMap&& metadata) {
    std::lock_guard<std::mutex> lock(mtx_);
    if (metadataCache_.size() >= CacheSize) {
        metadataCache_.erase(metadataCache_.begin());
    }
    metadataCache_[cacheKey] = std::move(metadata);
}

DynamicFileProcessor::MetadataMap DynamicFileProcessor::GetCachedMetadata(const std::string& cacheKey) {
    std::lock_guard<std::mutex> lock(mtx_);
    auto it = metadataCache_.find(cacheKey);
    if (it != metadataCache_.end()) {
        MetadataMap cachedData = std::move(it->second);
        metadataCache_.erase(it);
        return cachedData;
    }
    return {};
}

void DynamicFileProcessor::ProcessFiles(int maxParallelOperations, bool followSymlinks) {
    LoadConfig();
    if (filesToProcess_.empty()) {
        ErrorCallback("No files to process");
        return;
    }

    std::vector<std::future<void>> futures;

    for (const auto& fileEntry : filesToProcess_) {
        if (!followSymlinks && IsSymbolicLink(fileEntry.filePath)) {
            LogAction("Skipping symbolic link: " + fileEntry.filePath.string());
            continue;
        }

        MetadataMap fetchedMetadata;
        FetchMetadata(fileEntry, fetchedMetadata);
        futures.push_back(std::async(std::launch::async, [this, &fileEntry, &fetchedMetadata]() {
            ProcessFile(fileEntry, fetchedMetadata);
        }));

        if (maxParallelOperations > 0 && futures.size() >= maxParallelOperations) {
            for (auto& future : futures) {
                future.get();
            }
            futures.clear();
        }

        LogAction("Processed file: " + fileEntry.filePath.string());
    }

    // Ensure all async operations complete
    for (auto& future : futures) {
        future.get();
    }

    RenameOriginalConfig();
}

// Main function to test the class functionality
int main() {
    DynamicFileProcessor processor("config.json", "valid_auth_token");
    processor.ProcessFiles(5, true);  // Example usage with max 5 parallel operations and following symlinks
    return 0;
}
