namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Laravel\Socialite\Facades\Socialite;
use Illuminate\Support\Facades\Auth;
use Carbon\Carbon;

class AuthController extends Controller
{
    public function authenticate(Request $request)
    {
        // Rate limiting logic
        if ($this->isRateLimited($request->ip())) {
            return response()->json(['error' => 'Too many requests'], 429);
        }

        try {
            $user = Socialite::driver('idp')->stateless()->user();
            Auth::loginUsingId($user->getId());

            // Store access token in session with expiration
            $token = $this->generateAccessToken();
            session(['access_token' => $token, 'expires_at' => Carbon::now()->addMinutes(10)]);

            return response()->json(['message' => 'Authentication successful', 'token' => $token]);

        } catch (\Exception $e) {
            // Handle exceptions
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }

    private function isRateLimited($ip)
    {
        $attempts = cache()->get("auth_attempts_{$ip}", []);
        if (count($attempts) >= 10 && now()->diffInMinutes(end($attempts)) < 1) {
            return true;
        }
        $attempts[] = now();
        cache()->put("auth_attempts_{$ip}", array_slice($attempts, -10), 60);
        return false;
    }

    private function generateAccessToken()
    {
        // Generate a secure token
        return bin2hex(random_bytes(16));
    }
}

