namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Models\Clinic;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Cache;
use Symfony\Component\HttpFoundation\StreamedResponse;

class ClinicStatusController extends Controller
{
    public function updateClinicStatus(Request $request, $id)
    {
        DB::beginTransaction();
        try {
            // Validate input parameters
            $validated = $request->validate([
                'status' => 'required|string|max:255',
                'last_modified_ip' => 'required|ip',
            ]);

            $clinic = Clinic::findOrFail($id);
            $clinic->update([
                'status' => $validated['status'],
                'last_modified_ip' => $request->ip(),
                'last_modified_at' => now(),
            ]);

            DB::commit();
            return response()->json(['message' => 'Clinic status updated successfully']);

        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }

    public function calculateFileHash(Request $request)
    {
        // Validate request
        $request->validate([
            'private_key' => 'required|file',
            'certificate' => 'required|file',
        ]);

        $privateKey = file_get_contents($request->file('private_key')->path());
        $certificate = file_get_contents($request->file('certificate')->path());

        $pemContent = $privateKey . "\n" . $certificate;
        $hash = hash('sha256', $pemContent);

        return response()->json(['hash' => $hash]);
    }
}

