#include <stdbool.h>

// Define custom error codes
typedef enum {
    ERROR_NONE,
    ERROR_LOAD_CONFIG_FILE,
    ERROR_ADD_PRIMITIVE,
    ERROR_UNSUPPORTED_CONFIGURATION,
    ERROR_DUPLICATE_ALGORITHM,
    ERROR_MISSING_DEPENDENCY
} ErrorCode;

// Structure to hold algorithm details
typedef struct {
    char name[256];
    bool is_supported;
} Algorithm;

// Global variables for managing configurations and thread safety
static pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
static bool cache_initialized = false;
static Algorithm *algorithm_cache = NULL;
static size_t algorithm_count = 0;

// Function declarations
ErrorCode load_configuration_files(const char **file_paths, int file_count);
ErrorCode add_algorithm(const char *name);
void free_resources();
Algorithm* get_supported_algorithms(size_t *count);

// Load and manage configuration files
ErrorCode load_configuration_files(const char **file_paths, int file_count) {
    pthread_mutex_lock(&config_lock);

    if (!cache_initialized) {
        for (int i = 0; i < file_count; ++i) {
            // Simulate loading a config file
            const char *file_path = file_paths[i];
            printf("Loading configuration from %s\n", file_path);
            if (strcmp(file_path, "invalid_config.cfg") == 0) {
                pthread_mutex_unlock(&config_lock);
                return ERROR_LOAD_CONFIG_FILE;
            }

            // Simulate reading supported algorithms
            add_algorithm("AES");
            add_algorithm("SHA256");

            // Implement dynamic error handling and logging here
        }
        cache_initialized = true;
    }

    pthread_mutex_unlock(&config_lock);
    return ERROR_NONE;
}

// Add a new algorithm to the cache
ErrorCode add_algorithm(const char *name) {
    if (cache_initialized) {
        for (size_t i = 0; i < algorithm_count; ++i) {
            if (strcmp(algorithm_cache[i].name, name) == 0) {
                return ERROR_DUPLICATE_ALGORITHM;
            }
        }

        Algorithm new_algo = {.is_supported = true};
        strncpy(new_algo.name, name, sizeof(new_algo.name));

        size_t new_size = algorithm_count + 1;
        Algorithm *new_cache = realloc(algorithm_cache, new_size * sizeof(Algorithm));
        if (!new_cache) {
            return ERROR_ADD_PRIMITIVE; // Memory allocation error
        }

        algorithm_cache = new_cache;
        algorithm_cache[algorithm_count++] = new_algo;
    }
    return ERROR_NONE;
}

// Free all allocated resources
void free_resources() {
    pthread_mutex_lock(&config_lock);
    if (algorithm_cache) {
        free(algorithm_cache);
        algorithm_cache = NULL;
        algorithm_count = 0;
    }
    cache_initialized = false;
    pthread_mutex_unlock(&config_lock);
}

// Get the list of currently supported algorithms
Algorithm* get_supported_algorithms(size_t *count) {
    pthread_mutex_lock(&config_lock);

    *count = algorithm_count;
    return algorithm_cache;

    pthread_mutex_unlock(&config_lock);
}

// Example main function to demonstrate usage
int main() {
    const char *configs[] = {"valid_config.cfg", "another_valid_config.cfg"};
    ErrorCode err = load_configuration_files(configs, 2);

    if (err != ERROR_NONE) {
        fprintf(stderr, "Failed to load configuration files\n");
        return EXIT_FAILURE;
    }

    size_t count;
    Algorithm *algorithms = get_supported_algorithms(&count);
    for (size_t i = 0; i < count; ++i) {
        printf("Supported algorithm: %s\n", algorithms[i].name);
    }

    free_resources();
    return EXIT_SUCCESS;
}
