### C Semaphore Management System

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100
#define WORD_LIST_FETCH_SIZE 10

typedef struct {
    sem_t semaphore;
    char name[256];
} NamedSemaphore;

NamedSemaphore semaphores[MAX_SEMAPHORES];
int num_semaphores = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation) {
    printf("Operation: %s\n", operation);
}

// Create a new named semaphore
int create_semaphore(const char* name, int initial_value) {
    pthread_mutex_lock(&lock);
    if (num_semaphores >= MAX_SEMAPHORES) {
        log_operation("Semaphore creation failed: limit reached");
        return -1;
    }

    sem_init(&semaphores[num_semaphores].semaphore, 0, initial_value);
    strncpy(semaphores[num_semaphores].name, name, sizeof(semaphores[0].name) - 1);
    num_semaphores++;
    pthread_mutex_unlock(&lock);

    log_operation("Semaphore created");
    return 0;
}

// Delete a named semaphore
int delete_semaphore(const char* name) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_destroy(&semaphores[i].semaphore);
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(NamedSemaphore) * (num_semaphores - i - 1));
            num_semaphores--;
            pthread_mutex_unlock(&lock);

            log_operation("Semaphore deleted");
            return 0;
        }
    }
    pthread_mutex_unlock(&lock);

    log_operation("Semaphore deletion failed: not found");
    return -1;
}

// Increment a semaphore
int increment_semaphore(const char* name) {
    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_post(&semaphores[i].semaphore);
            log_operation("Semaphore incremented");
            return 0;
        }
    }

    log_operation("Increment failed: not found");
    return -1;
}

// Decrement a semaphore
int decrement_semaphore(const char* name) {
    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_wait(&semaphores[i].semaphore);
            log_operation("Semaphore decremented");
            return 0;
        }
    }

    log_operation("Decrement failed: not found");
    return -1;
}

// Dynamic trim and capitalize function
char* dynamic_trim_and_capitalize(char* input, int* size_limit) {
    char* words[WORD_LIST_FETCH_SIZE];
    for (int i = 0; i < WORD_LIST_FETCH_SIZE; ++i) {
        // Simulate asynchronous fetching of words
        words[i] = strdup("dummy_word");
    }

    // Adjust size limit based on fetched words
    int average_length = 0;
    for (int i = 0; i < WORD_LIST_FETCH_SIZE && words[i]; ++i) {
        average_length += strlen(words[i]);
    }
    if (WORD_LIST_FETCH_SIZE > 0) {
        average_length /= WORD_LIST_FETCH_SIZE;
        *size_limit -= average_length;
    }

    // Trim and capitalize
    char* result = strdup(input);
    for (int i = 0; i < WORD_LIST_FETCH_SIZE && words[i]; ++i) {
        char* pos = strstr(result, words[i]);
        if (pos) {
            memmove(pos, pos + strlen(words[i]), strlen(pos + strlen(words[i])) + 1);
        }
    }

    // Capitalize
    for (char* p = result; *p; ++p) {
        if (*p >= 'a' && *p <= 'z') {
            *p -= 32;
        }
    }

    int length = strlen(result);
    if (length > *size_limit) {
        free(result);
        return NULL;
    }

    return result;
}
