### JavaScript Asynchronous Array Reduction

```javascript
async function asyncArrayReduce(array, initialValue, callback, concurrencyLimit, progressCallback) {
    let index = 0;
    const semaphore = new Semaphore(concurrencyLimit);

    async function reduceHelper(accumulator, currentIndex) {
        if (currentIndex >= array.length) return accumulator;

        await semaphore.acquire();

        try {
            const newValue = await callback(accumulator, array[currentIndex], currentIndex, array);
            progressCallback(currentIndex + 1, newValue);
            return reduceHelper(newValue, currentIndex + 1)
                .finally(() => semaphore.release());
        } catch (error) {
            console.error("Error during reduction:", error);
            throw error;
        }
    }

    try {
        const result = await reduceHelper(initialValue, index);
        return result;
    } catch (error) {
        console.error("Reduction failed:", error);
        return Promise.reject(error);
    }
}

class Semaphore {
    constructor(maxConcurrency) {
        this.maxConcurrency = maxConcurrency;
        this.currentConcurrency = 0;
        this.queue = [];
    }

    async acquire() {
        if (this.currentConcurrency < this.maxConcurrency) {
            ++this.currentConcurrency;
            return Promise.resolve();
        } else {
            let promise = new Promise(resolve => this.queue.push(resolve));
            await promise;
            return this.acquire();
        }
    }

    release() {
        if (this.queue.length > 0) {
            const resolve = this.queue.shift();
            resolve();
        } else {
            --this.currentConcurrency;
        }
    }
}
```

This C implementation provides a semaphore management system with functions to create, delete, increment, and decrement semaphores. The JavaScript code implements an asynchronous array reduction function using promises and semaphores for concurrency control. Both implementations include logging and error handling to ensure robustness and fault tolerance.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_THREADS 10

typedef struct {
    char *input_dir;
    char *pattern;
    char *output_pdf;
    int dpi;
    void (*progress_callback)(int, int);
} ConversionTask;

typedef struct {
    ConversionTask *task;
    int index;
    char *file_path;
    int result;
} ThreadData;

void* convert_image_to_pdf(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    char command[256];

    snprintf(command, sizeof(command), "convert %s -density %d output_%d.png", data->file_path, data->task->dpi, data->index);
    int result = system(command);

    if (result != 0) {
        fprintf(stderr, "Error converting image: %s\n", data->file_path);
        data->result = 1;
    } else {
        snprintf(command, sizeof(command), "convert -page A4+0+0 output_%d.png +append result.pdf", data->index);
        result = system(command);

        if (result != 0) {
            fprintf(stderr, "Error appending to PDF: %s\n", data->file_path);
            data->result = 1;
        }
    }

    free(data->file_path);
    free(data);

    return NULL;
}

int list_images(char *input_dir, char *pattern, char **image_paths, int max_images) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    int count = 0;

    if ((dir = opendir(input_dir)) == NULL) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL && count < max_images) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", input_dir, entry->d_name);

        if (stat(path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
            // Simple pattern match for case-insensitivity
            if (strstr(strlwr(entry->d_name), strlwr(pattern))) {
                image_paths[count] = strdup(path);
                count++;
            }
        }
    }

    closedir(dir);
    return count;
}

int convert_images_to_pdf(ConversionTask *task) {
    char **image_paths = malloc(1000 * sizeof(char*));
    int num_images = list_images(task->input_dir, task->pattern, image_paths, 1000);

    if (num_images < 1) {
        fprintf(stderr, "No matching images found.\n");
        free(image_paths);
        return 1;
    }

    pthread_t threads[MAX_THREADS];
    ThreadData *thread_data[MAX_IMAGES];

    int i, failed_conversions = 0;

    for (i = 0; i < num_images; ++i) {
        while ((i % MAX_THREADS) != 0 && i > 0) {
            // Wait for any thread to finish
            pthread_join(threads[(i - 1) % MAX_THREADS], NULL);
        }

        ThreadData *data = malloc(sizeof(ThreadData));
        data->task = task;
        data->index = i;
        data->file_path = strdup(image_paths[i]);
        data->result = 0;

        thread_data[i] = data;
        pthread_create(&threads[i % MAX_THREADS], NULL, convert_image_to_pdf, data);

        if (task->progress_callback) {
            task->progress_callback(i + 1, num_images);
        }
    }

    // Wait for remaining threads to finish
    for (i = num_images - (num_images % MAX_THREADS); i < num_images; ++i) {
        pthread_join(threads[i % MAX_THREADS], NULL);
        failed_conversions += thread_data[i]->result;
    }

    free(image_paths);

    return failed_conversions;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_dir> <pattern> <output_pdf>\n", argv[0]);
        return 1;
    }

    ConversionTask task = { .input_dir = argv[1], .pattern = argv[2], .output_pdf = argv[3], .dpi = 300 };

    int failed_conversions = convert_images_to_pdf(&task);

    if (failed_conversions > 0) {
        fprintf(stderr, "Conversion completed with %d errors.\n", failed_conversions);
        return 1;
    }

    printf("All images converted successfully to PDF.\n");
    return 0;
}
```

