using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Net.Http;
using Newtonsoft.Json;

public class AsyncAesCbcInitiate
{
    private static readonly SemaphoreSlim _semaphore = new(5); // Limit to 5 concurrent tasks
    private static ConcurrentDictionary<string, string> _cache = new();
    private static readonly HttpClient _httpClient = new();

    public async Task<object> InitiateAsync(IEnumerable<XDocument> xmlDocuments, object initialValue, Options options)
    {
        try
        {
            var results = await Task.WhenAll(xmlDocuments.Select(doc => ProcessDocumentAsync(doc, initialValue, options)));
            return results.Aggregate(initialValue, (current, result) => AggregateResults(current, result));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during initiation: {ex.Message}");
            throw;
        }
    }

    private async Task<object> ProcessDocumentAsync(XDocument doc, object accumulator, Options options)
    {
        var tasks = new List<Task>();

        foreach (var path in options.XPathExpressions)
        {
            var cachedResult = _cache.GetOrAdd(path, _ => ExtractData(doc, path));
            if (!cachedResult.Any())
                throw new Exception($"No data found for XPath: {path}");

            foreach (var element in cachedResult)
            {
                tasks.Add(ProcessElementAsync(element, options));
            }
        }

        await Task.WhenAll(tasks);

        return accumulator;
    }

    private IEnumerable<XElement> ExtractData(XDocument doc, string xpath)
    {
        var elements = doc.XPathSelectElements(xpath);
        if (elements.Count() > 1)
            throw new Exception($"Multiple nodes found for XPath: {xpath}");

        return elements;
    }

    private async Task ProcessElementAsync(XElement element, Options options)
    {
        await _semaphore.WaitAsync();

        try
        {
            var data = ValidateDataWithApi(element.Value, options.ApiToken);
            ReportProgress(options.ProgressCallback, data);
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<object> ValidateDataWithApi(string data, string token)
    {
        using var requestContent = new StringContent(JsonConvert.SerializeObject(new { Data = data }), System.Text.Encoding.UTF8, "application/json");
        var request = new HttpRequestMessage(HttpMethod.Post, "https://api.example.com/validate")
        {
            Content = requestContent
        };
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

        using var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, 
            CancellationToken.None.WithTimeout(TimeSpan.FromSeconds(10)));

        if (!response.IsSuccessStatusCode)
            throw new Exception($"API validation failed: {response.ReasonPhrase}");

        return await response.Content.ReadAsStringAsync();
    }

    private void ReportProgress(Action<object> callback, object data)
    {
        callback?.Invoke(data);
    }

    private static object AggregateResults(object current, object result)
    {
        // Define how to aggregate results
        return result; 
    }
}

public class Options
{
    public List<string> XPathExpressions { get; set; } = new();
    public string ApiToken { get; set; }
    public Action<object> ProgressCallback { get; set; }
}

public static class CancellationTokenExtensions
{
    public static async Task WithTimeout(this Task task, TimeSpan timeout)
    {
        if (timeout == TimeSpan.Zero) return;
        var tcs = new TaskCompletionSource<bool>();
        var timer = new Timer(_ => tcs.TrySetResult(true), null, timeout, Timeout.InfiniteTimeSpan);
        await Task.WhenAny(task, tcs.Task).ConfigureAwait(false);
        timer.Dispose();
    }
}
