public class DynamicConfigUpdater
{
    private readonly IDatabaseService _databaseService;
    private readonly ILogger _logger;
    private const string ThemeCacheDirectory = "ThemeCache";

    public DynamicConfigUpdater(IDatabaseService databaseService, ILogger logger)
    {
        _databaseService = databaseService ?? throw new ArgumentNullException(nameof(databaseService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UpdateUserConfigurationAsync(string userId, string configName, string newValue)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(userId) || string.IsNullOrWhiteSpace(configName))
            {
                _logger.LogError("Invalid input parameters.");
                throw new ArgumentException("User ID and configuration name must be provided.");
            }

            var cacheKey = $"{userId}:{configName}";

            // Validate current config value exists
            bool configExists = await _databaseService.ExistsAsync(cacheKey);
            if (!configExists)
            {
                _logger.LogWarning($"Configuration '{configName}' for user '{userId}' does not exist.");
                throw new KeyNotFoundException("Configuration not found.");
            }

            // Ensure thread safety and handle concurrent updates
            using (await _databaseService.AcquireLockAsync(cacheKey))
            {
                var currentConfig = await _databaseService.GetAsync<string>(cacheKey);

                if (currentConfig == newValue)
                {
                    _logger.LogInformation($"No update needed for '{configName}' as the value is already set.");
                    return;
                }

                // Update configuration
                await _databaseService.SetAsync(cacheKey, newValue);

                _logger.LogDebug($"Configuration '{configName}' updated successfully for user '{userId}'.");
            }
        }
        catch (MemoryAllocationException ex)
        {
            _logger.LogError("Memory allocation error during update.", ex);
            throw;
        }
        catch (HttpRequestException ex) when ((ex as HttpRequestException)?.Status == System.Net.HttpStatusCode.RequestTimeout)
        {
            _logger.LogWarning("Network timeout occurred while updating configuration.", ex);
            // Implement retry logic if necessary
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while updating the configuration: {ex.Message}", ex);
            throw;
        }

        // Parse and store PNG from cache root
        StoreThemeImage(userId, configName);
    }

    private void StoreThemeImage(string userId, string configName)
    {
        try
        {
            var imagePath = Path.Combine("CacheRoot", $"{userId}_{configName}.png");
            if (File.Exists(imagePath))
            {
                var themeCachePath = Path.Combine(ThemeCacheDirectory, $"{userId}_{configName}.png");
                File.Copy(imagePath, themeCachePath);

                _logger.LogInformation($"PNG file stored in theme cache for user '{userId}'.");
            }
        }
        catch (IOException ex)
        {
            _logger.LogError("Error occurred while storing PNG image.", ex);
            throw;
        }
    }
}

// Interface definitions for DatabaseService and Logger
public interface IDatabaseService : IDisposable
{
    Task<bool> ExistsAsync(string key);
    Task<T> GetAsync<T>(string key);
    Task SetAsync<T>(string key, T value);
