```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_THREADS 10

typedef struct {
    char *pattern;
    char *output_dir;
    int dpi;
} ConversionConfig;

typedef void (*ProgressCallback)(int current, int total);

// Function prototypes
void convertImagesToPDF(const char *pattern, const char *output_dir, int dpi, ProgressCallback progress);
void* imageProcessingThread(void* arg);
void handleConversionErrors(int error_code);

void convertImagesToPDF(const char *pattern, const char *output_dir, int dpi, ProgressCallback progress) {
    DIR *dir;
    struct dirent *entry;
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    if ((dir = opendir(output_dir)) == NULL) {
        perror("Error opening directory");
        return;
    }

    int total_images = 0;
    char **image_files = NULL;

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, pattern) && 
            (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg") ||
             strstr(entry->d_name, ".png") || strstr(entry->d_name, ".gif"))) {

            total_images++;
            image_files = realloc(image_files, sizeof(char*) * total_images);
            if (!image_files) {
                perror("Memory allocation error");
                closedir(dir);
                return;
            }
            image_files[total_images - 1] = strdup(entry->d_name);
        }
    }

    closedir(dir);

    if (total_images == 0) {
        printf("No images found matching the pattern.\n");
        return;
    }

    for (int i = 0; i < total_images; ++i) {
        if (thread_count >= MAX_THREADS) {
            for (int j = 0; j < MAX_THREADS; ++j) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }

        ConversionConfig *config = malloc(sizeof(ConversionConfig));
        config->pattern = pattern;
        config->output_dir = output_dir;
        config->dpi = dpi;

        pthread_create(&threads[thread_count++], NULL, imageProcessingThread, (void*)config);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    progress(total_images, total_images);

    // Free allocated memory
    for (int i = 0; i < total_images; ++i) {
        free(image_files[i]);
    }
    free(image_files);
}

void* imageProcessingThread(void* arg) {
    ConversionConfig *config = (ConversionConfig*)arg;
    char command[1024];

    // Construct the conversion command
    snprintf(command, sizeof(command), "convert -density %d \"%s/%s\" \"%s/output.pdf\"",
             config->dpi, config->output_dir, config->pattern, config->output_dir);

    int status = system(command);
    if (status != 0) {
        handleConversionErrors(status);
    }

    free(config);
    return NULL;
}

void handleConversionErrors(int error_code) {
    // Log the error
    fprintf(stderr, "Error during conversion: %d\n", error_code);
}
