        } catch (Exception $e) {
            logAttempt($username, false, $e->getMessage());
            usleep(pow(2, $attempts) * 100000); // Exponential backoff
            $attempts++;
        }
    }

    throw new PasswordUpdateException("Failed to update password after several attempts.");
}

