    if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) ||
        !preg_match('/[a-z]/', $password) || !preg_match('/\d/', $password) ||
        !preg_match('/[\W_]/', $password) || strpos(strtolower($password), strtolower($username)) !== false) {
        return false;
    }
    return true;
}

