    for (const auto& trans : transactions) {
        if ((std::chrono::duration_cast<std::chrono::seconds>(now - trans.timestamp).count() <= 10) &&
            (trans.weightedSum > maxWeightedSum)) {
            maxWeightedSum = trans.weightedSum;
            bestTransaction = trans;
        }
    }

    // Record the transaction
    if (!shouldRecord) return SUCCESS;

    int errorCode = SUCCESS;
    std::unique_lock<std::mutex> lock(mtx);

    try {
        switch (type) {
            case RecorderType::DATABASE: {
                DatabaseRecorder dbRecorder;
                if (!dbRecorder.record(bestTransaction, details)) throw ErrorCode::DB_CONNECTION_FAILED;
                break;
            }
            case RecorderType::FILE: {
                FileRecorder fileRecorder;
                if (!fileRecorder.record(bestTransaction, details)) throw ErrorCode::LOG_WRITE_ERROR;
                break;
            }
            case RecorderType::PAYMENT_PROCESSOR: {
                PaymentProcessor paymentProcessor;
                if (!paymentProcessor.verifyTransaction(details, timeout)) throw ErrorCode::API_FAILURE;
                break;
            }
        }

    } catch (ErrorCode error) {
        errorCode = static_cast<int>(error);
    } catch (...) {
        errorCode = static_cast<int>(ErrorCode::TIMEOUT);
    }

    return errorCode;
}

std::vector<Transaction> generateSampleTransactions() {
    std::vector<Transaction> transactions;
    for (int i = 0; i < 5; ++i) {
        Transaction trans{.id = i, .weightedSum = static_cast<double>(rand()) / RAND_MAX * 100,
                          .timestamp = std::chrono::system_clock::now() - std::chrono::seconds(rand() % 15)};
        transactions.push_back(trans);
    }
    return transactions;
}
```

### Key Features:
- **Filtering Logic**: The function filters transactions based on their age and weighted sum.
- **Recorder Modules**: Uses different recording strategies (Database, File, Payment Processor).
- **Concurrency Safety**: Utilizes `std::mutex` for thread safety.
- **Error Handling**: Returns specific error codes for various failure scenarios.
- **Retry Mechanism**: Implements retries with exponential backoff for payment processor verification.

