```python
# Flask app setup with custom logging mechanism

from flask import Flask, request
import logging
from logging.handlers import SMTPHandler, RotatingFileHandler
import os

class CustomLogger:
    def __init__(self, app: Flask):
        self.app = app
        self.logger = logging.getLogger(app.name)
        self.logger.setLevel(logging.DEBUG)  # Default level
        self.formatter = None
        self.setup_default_handlers()

    def setup_default_handlers(self):
        console_handler = logging.StreamHandler()
        console_handler.setFormatter(self.get_formatter())
        self.add_handler(console_handler)

    def get_formatter(self, fmt=None):
        if not fmt:
            fmt = '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        if not self.formatter:
            self.formatter = logging.Formatter(fmt)
        return self.formatter

    def set_log_level(self, level: str):
        levels = {
            'DEBUG': logging.DEBUG,
            'INFO': logging.INFO,
            'WARNING': logging.WARNING,
            'ERROR': logging.ERROR,
            'CRITICAL': logging.CRITICAL
        }
        self.logger.setLevel(levels.get(level.upper(), logging.DEBUG))

    def add_handler(self, handler: logging.Handler):
        if not isinstance(handler, logging.Handler):
            raise ValueError("Invalid handler type")
        handler.setFormatter(self.get_formatter())
        self.logger.addHandler(handler)

    def remove_handler(self, handler: logging.Handler):
        if handler in self.logger.handlers:
            self.logger.removeHandler(handler)

    def add_file_handler(self, filepath: str, max_bytes=10485760, backup_count=5):
        file_handler = RotatingFileHandler(filepath, maxBytes=max_bytes, backupCount=backup_count)
        self.add_handler(file_handler)

    def add_email_handler(self, mailhost: tuple, fromaddr: str, toaddrs: list, subject: str):
        email_handler = SMTPHandler(mailhost, fromaddr, toaddrs, subject)
        self.add_handler(email_handler)

# Flask app initialization

app = Flask(__name__)
custom_logger = CustomLogger(app)

@app.route('/')
def index():
    custom_logger.logger.info("Handling request at root")
    return "Welcome to the logging demo!"

@app.errorhandler(500)
def handle_500(e):
    custom_logger.logger.critical(f"Server error: {e}")
    return "Internal Server Error", 500

if __name__ == '__main__':
    # Example usage
    custom_logger.set_log_level('DEBUG')
    custom_logger.add_file_handler(os.path.join(app.root_path, 'app.log'))
    app.run(debug=True)

# Unit tests for the CustomLogger class

import unittest
from unittest.mock import Mock, patch
import tempfile

class TestCustomLogger(unittest.TestCase):

    def setUp(self):
        self.app = Flask(__name__)
        self.custom_logger = CustomLogger(self.app)

    @patch('logging.StreamHandler.emit')
    def test_add_console_handler(self, mock_emit):
        console_handler = logging.StreamHandler()
        self.custom_logger.add_handler(console_handler)
        self.assertTrue(mock_emit.called)

    @patch.object(logging, 'RotatingFileHandler', Mock())
    def test_add_file_handler(self):
        with tempfile.NamedTemporaryFile() as tmp:
            filepath = tmp.name
            self.custom_logger.add_file_handler(filepath)
            # Verify RotatingFileHandler is called
            logging.RotatingFileHandler.assert_called_with(filepath, maxBytes=10485760, backupCount=5)

    @patch.object(logging.handlers.SMTPHandler, '__init__', Mock())
    def test_add_email_handler(self):
        mailhost = ('localhost', 25)
        fromaddr = 'test@example.com'
        toaddrs = ['admin@example.com']
        subject = 'Test Email'
        self.custom_logger.add_email_handler(mailhost, fromaddr, toaddrs, subject)
        logging.handlers.SMTPHandler.assert_called_with(mailhost, fromaddr, toaddrs, subject)

    def test_set_log_level(self):
        self.custom_logger.set_log_level('INFO')
        self.assertEqual(self.custom_logger.logger.level, logging.INFO)

if __name__ == '__main__':
    unittest.main()
```

This code includes a `CustomLogger` class for managing log handlers in a Flask application and provides unit tests to validate its behavior. The logger supports console, file, and email logging with dynamic addition/removal of handlers, customizable formats, and multiple log levels.

Below is an example C implementation of the described functionality. This code uses OpenSSL's APIs but can be extended to support other backends such as BoringSSL.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/conf.h>

#define MAX_PRIMITIVES 10

typedef struct {
    char name[50];
    int available;
} Primitive;

static pthread_mutex_t library_mutex = PTHREAD_MUTEX_INITIALIZER;
static Primitive primitives[MAX_PRIMITIVES] = {{"AES", 0}, {"Camellia", 0}, {"MD5", 0}, {"SHA-1", 0}, {"SHA-256", 0}};
static int primitive_count = 0;

int check_primitive_availability(const char *name) {
    if (strcmp(name, "AES") == 0) return EVP_aes_128_cbc() != NULL;
    if (strcmp(name, "Camellia") == 0) return EVP_camellia_128_cbc() != NULL;
    if (strcmp(name, "MD5") == 0) return EVP_md5() != NULL;
    if (strcmp(name, "SHA-1") == 0) return EVP_sha1() != NULL;
    if (strcmp(name, "SHA-256") == 0) return EVP_sha256() != NULL;
    return 0;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int add_primitive(const char *name) {
    pthread_mutex_lock(&library_mutex);

    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (strcmp(primitives[i].name, name) == 0 && primitives[i].available) {
            pthread_mutex_unlock(&library_mutex);
            return 1;
        }
    }

    int available = check_primitive_availability(name);
    if (!available) {
        log_error("Primitive not supported");
        pthread_mutex_unlock(&library_mutex);
        return 0;
    }

    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (!primitives[i].available) {
            strncpy(primitives[i].name, name, sizeof(primitives[i].name));
            primitives[i].available = 1;
            pthread_mutex_unlock(&library_mutex);
            return 1;
        }
    }

    log_error("Library full");
    pthread_mutex_unlock(&library_mutex);
    return 0;
}

void remove_primitive(const char *name) {
    pthread_mutex_lock(&library_mutex);

    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (strcmp(primitives[i].name, name) == 0 && primitives[i].available) {
            primitives[i].available = 0;
            break;
        }
    }

    pthread_mutex_unlock(&library_mutex);
}

void verify_primitives() {
    printf("Available Primitives:\n");
    for (int i = 0; i < MAX_PRIMITIVES; i++) {
        if (primitives[i].available) {
            printf("%s\n", primitives[i].name);
        }
    }
}

void load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open config file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        add_primitive(strtok(line, "\n"));
    }

    fclose(file);
}

void unload_config() {
    // In this example we don't dynamically load primitives; unloading is a no-op
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    load_config(argv[1]);

    verify_primitives();

    remove_primitive("MD5");
    verify_primitives();

    unload_config();
    return EXIT_SUCCESS;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Dynamic Configuration**: Reads cryptographic primitives from a config file and manages their addition.
- **Primitive Availability Check**: Ensures primitives are supported before adding them.
- **Logging**: Provides basic error logging through `log_error`.
- **Modular Architecture**: Designed to easily add support for additional cryptographic primitives.

### Notes:

1. **Security Practices**: The code does not handle key management practices directly; this should be implemented as per application needs.
2. **Backends Support**: This example uses OpenSSL, but can be extended for other backends like BoringSSL.
3. **Performance Considerations**: Caching is implicit in checking primitives only once and managing resources efficiently.
4. **Error Handling & Logging**: Basic error logging is included; expand as needed based on application requirements.

For a production implementation, ensure comprehensive testing, consider using more sophisticated logging libraries (like `syslog`), and extend functionality to fully support all described features such as dynamic loading/unloading and secure key management.

