import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class PokemonUtils {

    public static PokemonWeaknessResult getWeaknesses(Pokemon pokemon, String directoryPath) {
        CompletableFuture<Boolean> webConfigFuture = checkWebConfigAsync(directoryPath);

        List<String> weaknesses = determineWeaknesses(pokemon);

        return webConfigFuture.thenApply(webConfigExists -> 
            new PokemonWeaknessResult(
                webConfigExists,
                weaknesses.isEmpty() ? null : weaknesses,
                null
            )
        ).exceptionally(ex -> {
            System.err.println("Error: " + ex.getMessage());
            return new PokemonWeaknessResult(false, null, ex.getMessage());
        }).join();
    }

    private static CompletableFuture<Boolean> checkWebConfigAsync(String directoryPath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                File webConfig = new File(directoryPath, "web.config");
                if (!Files.exists(webConfig.toPath())) {
                    return false;
                }

                ProcessBuilder processBuilder = new ProcessBuilder("cmd.exe", "/c", "cd " + directoryPath);
                processBuilder.redirectErrorStream(true);

                try {
                    processBuilder.start();
                } catch (IOException e) {
                    System.err.println("Process execution error: " + e.getMessage());
                }

            } catch (Exception ex) {
                System.err.println("File check exception: " + ex.getMessage());
            }
            return true;
        });
    }

    private static List<String> determineWeaknesses(Pokemon pokemon) {
        List<String> weaknesses = new ArrayList<>();
        String typeName = pokemon.getTypeName(); // Assuming this method exists in Pokemon class

        switch (typeName.toLowerCase()) {
            case "fire":
                weaknesses.add("Water");
                weaknesses.add("Ground");
                break;
            case "water":
                weaknesses.add("Electric");
                weaknesses.add("Grass");
                break;
            case "grass":
                weaknesses.add("Fire");
                weaknesses.add("Ice");
                weaknesses.add("Poison");
                weaknesses.add("Flying");
                break;
            // Add other types as needed
        }

        return weaknesses;
    }

    public static class PokemonWeaknessResult {
        public boolean webConfigExists;
        public List<String> weaknesses;
        public String errorMessage;

        public PokemonWeaknessResult(boolean webConfigExists, List<String> weaknesses, String errorMessage) {
            this.webConfigExists = webConfigExists;
            this.weaknesses = weaknesses;
            this.errorMessage = errorMessage;
        }
    }

    // Assuming a simple Pokemon class
    public static class Pokemon {
        private final String name;
        private final String type;

        public Pokemon(String name, String type) {
            this.name = name;
            this.type = type;
        }

        public String getName() {
            return name;
        }

        public String getTypeName() {
            return type;
        }
    }
}
