```php
<?php

// Define constants for environments
define('ENV_DEVELOPMENT', 'development');
define('ENV_STAGING', 'staging');
define('ENV_PRODUCTION', 'production');

// Environment configuration class
class ConfigManager {
    private $cache = [];
    private static $instance;

    // Singleton pattern to ensure a single instance
    public static function getInstance() {
        if (self::$instance === null) {
            self::$instance = new ConfigManager();
        }
        return self::$instance;
    }

    private function __construct() {}

    private function getEnvironment() {
        $env = getenv('ENV');
        if (!in_array($env, [ENV_DEVELOPMENT, ENV_STAGING, ENV_PRODUCTION])) {
            throw new Exception("Invalid environment setting");
        }
        return $env;
    }

    public function fetchConfig() {
        $env = $this->getEnvironment();

        // Check cache first
        if (isset($this->cache[$env])) {
            return $this->cache[$env];
        }

        try {
            $config = $this->fetchFromApi($env);
            $this->cache[$env] = $config;
            return $config;
        } catch (\Exception $e) {
            // Log error
            error_log("Failed to fetch config: " . $e->getMessage());

            // Fallback strategy
            if (isset($this->cache['default'])) {
                return $this->cache['default'];
            }

            throw new Exception("No valid configuration available");
        }
    }

    private function fetchFromApi($env) {
        $apiUrl = "https://example.com/api/config?environment=$env";

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $apiUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_TIMEOUT, 5); // Timeout to handle network latency

        $response = curl_exec($ch);

        if (curl_errno($ch)) {
            throw new Exception("API request failed: " . curl_error($ch));
        }

        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

        if ($httpCode !== 200) {
            throw new Exception("Non-200 HTTP response code: $httpCode");
        }

        curl_close($ch);

        $data = json_decode($response, true);

        if (json_last_error() !== JSON_ERROR_NONE) {
            throw new Exception("JSON parsing error: " . json_last_error_msg());
        }

        return $data;
    }
}

