```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
import "argon2"  // Assuming Argon2 is available in your environment

#define KEY_SIZE_DES 8
#define IV_SIZE_DES 8

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB,
    CBC,
    OFB,
    CTR,
    NULL_CIPHER,
    INVALID_MODE
} CipherMode;

EVP_CIPHER_CTX* create_cipher(CipherMode mode, const unsigned char *key, size_t key_len, 
                              const unsigned char *iv, size_t iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    int cipher_type;
    switch (mode) {
        case ECB:
            cipher_type = EVP_des_ede3_ecb();
            break;
        case EDE:
            cipher_type = EVP_des_ede_ecb();
            break;
        case EDE3:
            cipher_type = EVP_des_ede3_ecb();
            break;
        case CFB:
            if (iv_len != IV_SIZE_DES && iv_len != key_len) {
                EVP_CIPHER_CTX_free(ctx);
                return NULL; // Invalid IV length
            }
            cipher_type = EVP_des_cfb64();
            break;
        case CBC:
            if (iv_len != IV_SIZE_DES) {
                EVP_CIPHER_CTX_free(ctx);
                return NULL; // Invalid IV length
            }
            cipher_type = EVP_des_cbc();
            break;
        case OFB:
            if (iv_len != IV_SIZE_DES) {
                EVP_CIPHER_CTX_free(ctx);
                return NULL; // Invalid IV length
            }
            cipher_type = EVP_des_ofb();
            break;
        case CTR:
            if (iv_len != IV_SIZE_DES) {
                EVP_CIPHER_CTX_free(ctx);
                return NULL; // Invalid IV length
            }
            cipher_type = EVP_des_ede3_ctr();
            break;
        case NULL_CIPHER:
            cipher_type = EVP_aes_null_cipher();  // Using AES null cipher for testing
            break;
        default:
            EVP_CIPHER_CTX_free(ctx);
            return NULL; // Invalid mode
    }

    if (!EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void derive_key(const unsigned char *password, size_t password_len,
                const unsigned char *salt, size_t salt_len,
                unsigned char *key_out, size_t key_len) {
    Argon2idState state;
    argon2id_state_init(&state, 1024, 1, 16, ARGON2_VERSION_13);

    if (argon2id_hash(&state, password, password_len, salt, salt_len, 
                      NULL, 0, key_out, key_len) != ARGON2_OK) {
        fprintf(stderr, "Key derivation failed\n");
        exit(1);
    }
}

void secure_zero_memory(void *ptr, size_t len) {
    volatile unsigned char *p = (volatile unsigned char *) ptr;
    while (len--) *p++ = 0;
}

// Example of usage
int main() {
    const unsigned char password[] = "password";
    const unsigned char salt[] = "salt";
    unsigned char key[KEY_SIZE_DES];

    derive_key(password, sizeof(password) - 1, salt, sizeof(salt) - 1, key, KEY_SIZE_DES);

    const unsigned char iv[IV_SIZE_DES];
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate IV\n");
        return 1;
    }

    EVP_CIPHER_CTX *ctx = create_cipher(CFB, key, KEY_SIZE_DES, iv, IV_SIZE_DES);
    if (!ctx) {
        fprintf(stderr, "Cipher creation failed\n");
        return 1;
    }

    // Perform encryption/decryption here...

    secure_zero_memory(key, sizeof(key));
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}
```

### Key Points:
- **Key Derivation**: Uses Argon2 for key stretching.
- **Cipher Modes**: Supports multiple DES modes and a null cipher for testing.
- **IV Handling**: Validates IV length based on mode requirements.
- **Memory Management**: Securely clears sensitive data from memory.
- **Error Handling**: Checks for errors during context creation and initialization.
- **Performance Considerations**: Efficient use of OpenSSL functions.

