```php
<?php
require 'vendor/autoload.php';

use GuzzleHttp\Client;

function authenticateUser($clientId, $clientSecret) {
    session_start();

    // OAuth2 client setup
    $oauthClient = new \League\OAuth2\Client\Provider\GenericProvider([
        'clientId'                => $clientId,
        'clientSecret'            => $clientSecret,
        'redirectUri'             => 'YOUR_REDIRECT_URI',
        'urlAuthorize'            => 'OAUTH_URL_AUTHORIZE',
        'urlAccessToken'          => 'OAUTH_URL_ACCESS_TOKEN',
        'urlResourceOwnerDetails' => 'OAUTH_URL_RESOURCE_OWNER_DETAILS'
    ]);

    // Get access token
    try {
        $accessToken = $oauthClient->getAccessToken('client_credentials');

        // Store encrypted access token in session
        $_SESSION['access_token'] = openssl_encrypt(
            (string)$accessToken,
            'aes-256-cbc',
            hash('sha256', $_SERVER['SECRET_KEY']),
            0,
            substr(hash('sha256', $_SERVER['SECRET_KEY']), 0, 16)
        );

    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        // Failed to get the access token or user details
        exit($e->getMessage());
    }
}

// Usage example
authenticateUser('your-client-id', 'your-client-secret');
