```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;

namespace XmlParserLibrary
{
    public class XmlParsingException : Exception
    {
        public XmlParsingException(string message) : base(message) { }
    }

    public interface IConfigurationLoader
    {
        IDictionary<string, string> LoadConfigurations();
    }

    public class ConfigurationLoader : IConfigurationLoader
    {
        private readonly string _configFilePath;

        public ConfigurationLoader(string configFilePath)
        {
            _configFilePath = configFilePath;
        }

        public IDictionary<string, string> LoadConfigurations()
        {
            var configurations = new Dictionary<string, string>();
            // Assuming the configuration file is in key=value format
            foreach (var line in File.ReadAllLines(_configFilePath))
            {
                if (!string.IsNullOrWhiteSpace(line) && !line.StartsWith("#"))
                {
                    var parts = line.Split('=');
                    if (parts.Length == 2)
                    {
                        configurations[parts[0].Trim()] = parts[1].Trim();
                    }
                }
            }

            return configurations;
        }
    }

    public interface ICacheManager
    {
        XmlDocument GetOrAdd(string key, Func<string, XmlDocument> valueFactory);
        void Remove(string key);
    }

    public class XmlCacheManager : ICacheManager
    {
        private readonly ConcurrentDictionary<string, XmlDocument> _cache = new();
        private const int MaxCacheSize = 100; // Adjust based on memory constraints

        public XmlDocument GetOrAdd(string key, Func<string, XmlDocument> valueFactory)
        {
            if (_cache.TryGetValue(key, out var document))
                return document;

            document = valueFactory(key);
            _cache.TryAdd(key, document);

            if (_cache.Count > MaxCacheSize)
            {
                // Implement an eviction strategy, e.g., remove the oldest entry
                var oldestKey = _cache.Keys.FirstOrDefault();
                _cache.TryRemove(oldestKey, out _);
            }

            return document;
        }

        public void Remove(string key)
        {
            _cache.TryRemove(key, out _);
        }
    }

    public class XmlParser
    {
        private readonly IConfigurationLoader _configLoader;
        private readonly ICacheManager _cacheManager;

        public XmlParser(IConfigurationLoader configLoader, ICacheManager cacheManager)
        {
            _configLoader = configLoader;
            _cacheManager = cacheManager;
        }

        public XmlNode FindFirstElement(string elementName, string documentKey, IDictionary<string, string> namespaces = null)
        {
            var configurations = _configLoader.LoadConfigurations();
            if (!configurations.TryGetValue(documentKey, out var filePath))
                throw new XmlParsingException($"Document not found for key: {documentKey}");

            using (var reader = XmlReader.Create(filePath))
            {
                var document = _cacheManager.GetOrAdd(filePath, path => new XmlDocument());
                var navigator = document.CreateNavigator();

                XPathExpression expression;
                try
                {
                    expression = XPathExpression.Compile($"//{elementName}");
                }
                catch (XPathException)
                {
                    throw new XmlParsingException($"Invalid XPath query for element: {elementName}");
                }

                if (namespaces != null)
                {
                    var namespaceManager = new XmlNamespaceManager(navigator.NameTable);
                    foreach (var ns in namespaces)
                        namespaceManager.AddNamespace(ns.Key, ns.Value);

                    expression.SetContext(namespaceManager);
                }

                var nodes = navigator.Select(expression).Cast<XPathNavigator>().ToList();

                if (!nodes.Any())
                    throw new XmlParsingException($"No elements found with name: {elementName}");
                if (nodes.Count > 1)
                    throw new XmlParsingException($"Multiple elements found with name: {elementName}");

                return document.DocumentElement.SelectSingleNode(elementName);
            }
        }

        public void InvalidateCache(string filePath)
        {
            _cacheManager.Remove(filePath);
        }
    }
}
```

This code provides a scalable and maintainable solution for parsing XML documents using XPath queries. It handles caching, configuration loading, namespace management, error handling, and concurrency considerations. The class `XmlParser` uses dependency injection to integrate with external systems like configuration files and cache storage, allowing it to manage different versions of XML documents efficiently.

