void dynamicTestLoader(int n) {
    if (n > MAX_STRUCTURES) n = MAX_STRUCTURES;

    pthread_mutex_lock(&db_lock);

    db.data = realloc(db.data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!db.data) {
        logMessage("Memory allocation failed");
        pthread_mutex_unlock(&db_lock);
        return;
    }

    db.size = 0;

    for (int i = 0; i < n; ++i) {
