        }

        db.data[db.size++] = structure;

        // Check memory budget periodically
        if ((float)(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1)) / (1024 * 1024) > MEMORY_BUDGET_MB) {
            manageMemoryBudget();
        }
    }

    pthread_mutex_unlock(&db_lock);
    logMessage("DynamicTestLoader completed successfully");
}

