  try {
    const s3 = new AWS.S3();
    const params = { Bucket: 'your-aws-bucket', Key: 'uploaded-file', Body: fileBuffer };

    const response = await Bluebird.promisify(s3.upload.bind(s3))(params);
    return response.Location;
  } catch (error) {
    Logger.error(`AWS Upload Error: ${error.message}`);
    throw new Error('Failed to upload to AWS S3');
  }
};

const uploadToGoogleCloudStorage = async (fileBuffer) => {
  try {
    const storage = new Storage({ keyFilename: providersConfig.google.keyFilename });
    const bucket = storage.bucket('your-gcs-bucket');
    const file = bucket.file('uploaded-file');

    await Bluebird.promisify(file.save.bind(file))(fileBuffer);

    return `https://storage.googleapis.com/your-gcs-bucket/uploaded-file`;
  } catch (error) {
    Logger.error(`Google Cloud Upload Error: ${error.message}`);
    throw new Error('Failed to upload to Google Cloud Storage');
  }
};

const dynamicFileUpload = async (fileBuffer, criteria) => {
  const selectedProvider = evaluateProvider(criteria);

  let uploadPromise;

  switch (selectedProvider) {
    case 'aws':
      uploadPromise = uploadToAWS(fileBuffer);
      break;
    case 'google':
      uploadPromise = uploadToGoogleCloudStorage(fileBuffer);
      break;
    default:
      throw new Error('No valid cloud provider selected');
  }

  return await Bluebird.resolve(uploadPromise)
    .timeout(30000, `Upload to ${selectedProvider} timed out`) // Handling timeouts
    .catch(err => {
      Logger.error(`File Upload Failed: ${err.message}`);
      throw err;
    });
};

// Example usage:
