```javascript
async function manageUnitTests(moduleLabel, testSuites, config) {
  const { maxConcurrency = 5, timeout = 5000, retryAttempts = 2, retryDelay = 1000 } = config;
  let activeResources = new Set();

  async function handleDependencies() {
    // Initialize resources such as database connections or API clients
    console.log(`Initializing dependencies for ${moduleLabel}`);
    // Mock initialization logic
  }

  async function releaseDependencies() {
    // Clean up resources to prevent leaks
    console.log(`Releasing dependencies for ${moduleLabel}`);
    // Mock cleanup logic
    activeResources.clear();
  }

  async function runTestSuite(suiteName, suite) {
    console.log(`Running test suite: ${suiteName} for module: ${moduleLabel}`);

    const results = [];

    for (const testCase of suite) {
      let attempts = 0;
      let passed = false;

      while (!passed && attempts < retryAttempts) {
        try {
          await handleDependencies();

          console.time(`Test Case: ${testCase.name || 'Unnamed'}`);
          const startTime = performance.now();

          // Assume `blueslip` is used for mocking, reset before each test
          blueslip.reset();

          const result = await testCase();
          activeResources.delete(testCase);

          const duration = performance.now() - startTime;
          console.timeEnd(`Test Case: ${testCase.name || 'Unnamed'}`);
          console.log(`Duration: ${duration.toFixed(2)}ms`);

          results.push({ name: testCase.name, status: 'passed', duration });
          passed = true;

        } catch (error) {
          attempts++;
          if (attempts >= retryAttempts) {
            results.push({
              name: testCase.name || 'Unnamed',
              status: 'failed',
              error: error.message || 'Unknown Error',
              attempts
            });
            console.error(`Error in test case ${testCase.name}:`, error);
          }
        } finally {
          await releaseDependencies();
          if (!passed && attempts < retryAttempts) {
            await new Promise(resolve => setTimeout(resolve, retryDelay));
          }
        }
      }
    }

    return results;
  }

  async function runAllSuites() {
    const suiteResults = [];

    for (const [suiteName, suite] of testSuites.entries()) {
      const result = await runTestSuite(suiteName, suite);
      suiteResults.push({ suiteName, result });

      // Handle third-party integration if needed
      integrateThirdPartyRunner(result);

      // Generate and save coverage report
      generateCoverageReport(moduleLabel, result);
    }

    console.log(`Completed all test suites for module: ${moduleLabel}`);
  }

  async function detectCircularDependencies() {
    console.log('Detecting circular dependencies for:', moduleLabel);
    // Mock detection logic
  }

  try {
    await handleDependencies();
    await detectCircularDependencies();

    const sem = new Semaphore(maxConcurrency);

    const tasks = testSuites.map(suite => 
      sem.use(() => runTestSuite(`Suite-${suite[0].name}`, suite))
    );

    await Promise.all(tasks);

  } catch (error) {
    console.error(`Error during execution of ${moduleLabel} tests:`, error);
  } finally {
    await releaseDependencies();
  }

  function generateCoverageReport(module, results) {
    // Mock logic to generate and save coverage report
    console.log(`Generating coverage report for ${module}`);
  }

  function integrateThirdPartyRunner(results) {
    // Mock logic to integrate with third-party test runners
    console.log('Integrating with third-party test runner');
  }
}

class Semaphore {
  constructor(maxConcurrent) {
    this.maxConcurrent = maxConcurrent;
    this.currentCount = 0;
    this.queue = [];
  }

  async use(task) {
    if (this.currentCount < this.maxConcurrent) {
      this.currentCount++;
      try {
        return task();
      } finally {
        this.currentCount--;
        this.next();
      }
    } else {
      await new Promise(resolve => this.queue.push(resolve));
      return this.use(task);
    }
  }

  next() {
    if (this.queue.length > 0) {
      const resolve = this.queue.shift();
      this.currentCount++;
      resolve().then(() => {
        this.currentCount--;
        this.next();
      });
    }
  }
}
