// C++: Insert a string in a forward_list based on another string and timeout

#include <forward_list>
#include <string>
#include <chrono>

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert, int timeout) {
    auto startTime = std::chrono::steady_clock::now();
    auto it = list.begin();

    while (it != list.end()) {
        if ((*it) == target) {
            it = list.insert_after(it, toInsert);
            return;
        }
        ++it;

        // Check for timeout
        auto currentTime = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::milliseconds>(currentTime - startTime).count() > timeout) {
            break; // Exit if operation exceeds the timeout duration
        }
    }

    // If target not found or timeout occurred, insert at end
    list.push_back(toInsert);
}
