# Python script for processing a large log file

import requests
import re
from collections import defaultdict

class LogProcessor:
    def __init__(self, log_file_path):
        self.log_file_path = log_file_path
        self.stats = defaultdict(lambda: {"count": 0, "total_time": 0.0})
        self.alerts_log = "alerts.log"

    def process_chunk(self, chunk):
        for line in chunk.split("\n"):
            match = re.match(r'(\d+\.\d+\.\d+\.\d+) - - \[(.*?)\] ".*?" (\d{3}) .*? "(.*?)" (\d+)', line)
            if match:
                ip, time_str, status_code, _, response_time = match.groups()
                self.stats[ip]["count"] += 1
                self.stats[ip]["total_time"] += int(response_time)

    def aggregate_data(self):
        with open(self.log_file_path, 'r') as file:
            while True:
                chunk = file.read(1024 * 1024)
                if not chunk:
                    break
                self.process_chunk(chunk)

        for ip, data in self.stats.items():
            avg_response_time = data["total_time"] / data["count"]
            print(f"IP: {ip}, Avg Response Time: {avg_response_time}")

    def report_statistics(self):
        try:
            requests.post('https://api.example.com/report', json=self.stats)
        except Exception as e:
            with open(self.alerts_log, 'a') as log_file:
                log_file.write(f"Failed to report stats: {e}\n")

    def monitor_for_alerts(self, threshold_time=1000):
        suspicious_ips = [ip for ip, data in self.stats.items()
                          if data["total_time"] / data["count"] > threshold_time]
        with open(self.alerts_log, 'a') as log_file:
            for ip in suspicious_ips:
                log_file.write(f"Suspicious IP detected: {ip}\n")

log_processor = LogProcessor("server.log")
log_processor.aggregate_data()
log_processor.report_statistics()
log_processor.monitor_for_alerts()
