```python
from flask import Flask, request, jsonify, abort
from flask_jwt_extended import JWTManager, jwt_required, get_jwt_identity
from functools import wraps
import psycopg2
import hashlib
import os
import threading
from rate_limit import RateLimitMiddleware

app = Flask(__name__)

# Configurations
app.config['JWT_SECRET_KEY'] = 'your-secret-key'
jwt = JWTManager(app)
conn_params = "dbname=your_db user=your_user password=your_password host=localhost"

rate_limit_middleware = RateLimitMiddleware(max_requests_per_minute=100, max_requests_per_hour=1000)

# Apply rate limiting
app.wsgi_app = rate_limit_middleware.make_wsgi_app(app.wsgi_app)


def role_required(role):
    def wrapper(fn):
        @wraps(fn)
        @jwt_required()
        def decorated_view(*args, **kwargs):
            claims = get_jwt_identity()
            if claims.get('role') != role:
                abort(403, description="Insufficient permissions")
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper


def log_request(response):
    user_id = get_jwt_identity().get("user_id", "unknown")
    print(f"User: {user_id}, Request: {request.method} {request.path}")
    print(f"Response Status: {response.status_code}")
    return response


@app.after_request
def after_request(response):
    log_request(response)
    return response


@app.route('/resource/<uuid:resource_id>', methods=['PUT'])
@role_required('editor')
def update_resource(resource_id):
    data = request.get_json()
    version_number = request.args.get('version', None)

    with psycopg2.connect(conn_params) as conn:
        with conn.cursor() as cursor:
            try:
                # Versioning check
                cursor.execute("SELECT version FROM resources WHERE id=%s", (resource_id,))
                row = cursor.fetchone()

                if not row:
                    abort(404, description="Resource not found")

                current_version = row[0]
                if version_number and int(version_number) != current_version:
                    abort(409, description="Version conflict")

                # Update resource
                new_data = data.get('data')
                new_version = current_version + 1

                cursor.execute(
                    "UPDATE resources SET data=%s, version=%s WHERE id=%s AND version=%s",
                    (new_data, new_version, resource_id, current_version)
                )

                if cursor.rowcount == 0:
                    abort(409, description="Resource update failed due to concurrent modification")

            except Exception as e:
                print(e)
                abort(500)

    return jsonify({"message": "Resource updated successfully"}), 200


def calculate_file_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()


def calculate_hash_in_chunks(file_path, progress_callback=None):
    def worker():
        hash_md5 = hashlib.md5()
        file_size = os.path.getsize(file_path)
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
                if progress_callback:
                    progress = (f.tell() / file_size) * 100
                    progress_callback(progress)

    return worker


def calculate_hashes_parallel(file_paths):
    threads = []
    results = {}

    def progress_callback(progress, file_path):
        print(f"Progress for {file_path}: {progress:.2f}%")

    for file_path in file_paths:
        thread = threading.Thread(
            target=lambda p: results.update({p: calculate_file_md5(p)}),
            args=(file_path,)
        )
        threads.append(thread)
        t_worker = calculate_hash_in_chunks(file_path, progress_callback=progress_callback)
        t_progress_thread = threading.Thread(target=t_worker)
        t_progress_thread.start()
        thread.start()

    for thread in threads:
        thread.join()

    return results


@app.route('/file-hash', methods=['POST'])
@jwt_required()
def file_hash():
    files = request.get_json().get('files', [])
    if not isinstance(files, list) or not all(isinstance(f, str) for f in files):
        abort(400, description="Invalid file paths")

    result = calculate_hashes_parallel(files)
    return jsonify(result)


if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation:

- **JWT-Based Authentication**: The API uses JWTs to authenticate requests. The `@jwt_required()` decorator is used to protect routes.
- **Role-Based Access Control (RBAC)**: A custom `role_required` decorator ensures that only users with the correct role can access certain endpoints.
- **Rate Limiting**: Integrated using a middleware approach for simplicity.
- **Concurrency and Versioning**: The resource update function uses versioning logic to handle concurrent updates safely.
- **File Hash Calculation with Parallel Processing**: Supports calculating MD5 hashes of multiple files in parallel, reporting progress as it processes each file.
- **Logging**: All requests are logged with user information and response status for auditing and debugging purposes.

