        upload_success = await upload_file_to_cloud(file_name, file_size, metadata)
        if upload_success:
            await notify_clients_via_websocket(file_name)

    # Run the asynchronous function in a thread to prevent blocking
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    loop.run_until_complete(background_upload())

