```javascript
const axios = require('axios');

class Semaphore {
    constructor(maxConcurrency) {
        this.maxConcurrency = maxConcurrency;
        this.currentCount = 0;
        this.queue = [];
    }

    async acquire() {
        return new Promise((resolve, reject) => {
            if (this.currentCount < this.maxConcurrency) {
                this.currentCount++;
                resolve();
            } else {
                this.queue.push(resolve);
            }
        });
    }

    release() {
        this.currentCount--;
        if (this.queue.length > 0) {
            const nextResolve = this.queue.shift();
            this.currentCount++;
            nextResolve();
        }
    }
}

async function asyncArrayReduce(numbers, initialValue, callback) {
    let semaphore = new Semaphore(10); // Example concurrency level
    let accumulator = initialValue;
    let completedOperations = 0;

    for (let i = 0; i < numbers.length; i++) {
        await semaphore.acquire();

        try {
            const token = 'your_auth_token'; // Replace with actual token retrieval logic
            const response = await axios.get('https://api.example.com/data', {
                headers: { Authorization: `Bearer ${token}` },
                params: { number: numbers[i] }
            });

            accumulator = await callback(accumulator, response.data);
        } catch (error) {
            console.error(`Error during API call or reduction: ${error.message}`);
            semaphore.release();
            return Promise.reject(error);

        }

        completedOperations++;
        console.log(`Progress: Completed ${completedOperations} operations. Current value: ${accumulator}`);

        semaphore.release();
    }

    return accumulator;
}

// Example usage
async function main() {
    const numbers = [1, 2, 3, 4, 5];
    try {
        const result = await asyncArrayReduce(numbers, 0, async (acc, num) => acc + num);
        console.log('Final Result:', result);
    } catch (error) {
        console.error('Error in reduction process:', error);
    }
}

main();
