```python
# Python: Fetch Weather Data with Caching

import requests
import time
from datetime import datetime, timedelta

class WeatherCache:
    def __init__(self, expiry_duration=600):
        self.cache = {}
        self.expiry_duration = expiry_duration  # Cache expiry in seconds (10 minutes)

    def get_cached_data(self, key):
        if key in self.cache:
            data, timestamp = self.cache[key]
            if time.time() - timestamp < self.expiry_duration:
                return data
        return None

    def cache_data(self, key, data):
        self.cache[key] = (data, time.time())

def fetch_weather(api_key, location):
    base_url = "http://api.weatherapi.com/v1/current.json"
    params = {'key': api_key, 'q': location}

    # Check cache first
    cached_data = weather_cache.get_cached_data(location)
    if cached_data:
        return cached_data

    response = requests.get(base_url, params=params)
    if response.status_code == 200:
        data = response.json()
        weather_cache.cache_data(location, data)
        return data
    else:
        raise Exception("Failed to fetch weather data")

weather_cache = WeatherCache()

# Example usage
api_key = "your_api_key"
location = "New York"
try:
    weather_data = fetch_weather(api_key, location)
    print(weather_data)
except Exception as e:
    print(e)

