// Java: Asynchronous API Connections using Channels

import java.util.concurrent.*;
import java.nio.channels.AsynchronousSocketChannel;
import java.net.InetSocketAddress;

public class WeatherAPIClient {

    private static final int TIMEOUT = 10; // Seconds

    public interface Callback {
        void onConnectionResult(boolean success, String message);
    }

    public void manageConnections(String[] apiEndpoints, Callback callback) {
        ExecutorService executor = Executors.newCachedThreadPool();

        for (String endpoint : apiEndpoints) {
            executor.submit(() -> {
                AsynchronousSocketChannel channel;
                try {
                    InetSocketAddress address = new InetSocketAddress(endpoint, 80);
                    channel = AsynchronousSocketChannel.open();
                    Future<Void> future = channel.connect(address);

                    if (!future.get(TIMEOUT, TimeUnit.SECONDS)) {
                        callback.onConnectionResult(false, "Timeout connecting to: " + endpoint);
                        return;
                    }

                    // Handle communication (send request and receive response)

                    callback.onConnectionResult(true, "Connected successfully to: " + endpoint);
                } catch (Exception e) {
                    callback.onConnectionResult(false, "Error connecting to: " + endpoint + " - " + e.getMessage());
                }
            });
        }

        executor.shutdown();
    }

    public static void main(String[] args) {
        WeatherAPIClient client = new WeatherAPIClient();
        String[] apiEndpoints = {"api.weatherprovider1.com", "api.weatherprovider2.com"};

        client.manageConnections(apiEndpoints, (success, message) -> {
            System.out.println(message);
        });
    }
}
