```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.util.*;
import java.util.stream.*;

// Import external libraries (e.g., SLF4J, Caffeine)
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;

public class FileHasher {
    private static final Logger logger = LoggerFactory.getLogger(FileHasher.class);
    private final ExecutorService executorService;
    private final Cache<Path, Pair<String, String>> cache;
    private final int maxThreads;
    private final int cacheSize;

    public FileHasher(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.cache = Caffeine.newBuilder()
                .maximumSize(cacheSize)
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .build();
    }

    public CompletableFuture<Pair<String, String>> computeHashes(String filePath) {
        if (filePath == null || filePath.length() > 1000) {
            logger.error("Invalid file path");
            return CompletableFuture.failedFuture(new IllegalArgumentException("Invalid file path"));
        }

        Path path = Paths.get(filePath);
        if (!Files.exists(path) || !Files.isRegularFile(path)) {
            logger.error("File does not exist or is not a regular file");
            return CompletableFuture.failedFuture(new IOException("File does not exist or is not a regular file"));
        }

        return CompletableFuture.supplyAsync(() -> cache.getIfPresent(path), executorService)
                .thenCompose(cacheResult -> cacheResult != null
                        ? CompletableFuture.completedFuture(cacheResult)
                        : computeHashesFromFile(path))
                .whenComplete((result, exception) -> {
                    if (exception != null) {
                        logger.error("Error computing hashes", exception);
                    }
                });
    }

    private Pair<String, String> computeHashesFromFile(Path path) {
        try (InputStream is = Files.newInputStream(path)) {
            MessageDigest md5Digest = MessageDigest.getInstance("MD5");
            MessageDigest sha256Digest = MessageDigest.getInstance("SHA-256");

            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md5Digest.update(buffer, 0, bytesRead);
                sha256Digest.update(buffer, 0, bytesRead);
            }

            String md5Hash = bytesToHex(md5Digest.digest());
            String sha256Hash = bytesToHex(sha256Digest.digest());

            cache.put(path, new Pair<>(md5Hash, sha256Hash));
            return new Pair<>(md5Hash, sha256Hash);

        } catch (Exception e) {
            logger.error("Error computing hash", e);
            throw new CompletionException(e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    // Pair class to hold two values
    private static final class Pair<L, R> {
        private final L left;
        private final R right;

        public Pair(L left, R right) {
            this.left = left;
            this.right = right;
        }

        public L getLeft() {
            return left;
        }

        public R getRight() {
            return right;
        }
    }

    // Unit tests and additional features would be implemented separately
}
```

