```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.IO.Compression;

public interface IHashFactory
{
    Task<string> ComputeHashAsync(byte[] input);
}

public class Md5HashFactory : IHashFactory
{
    public async Task<string> ComputeHashAsync(byte[] input)
    {
        using var md5 = MD5.Create();
        byte[] hashBytes = await Task.Run(() => md5.ComputeHash(input));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public class Sha1HashFactory : IHashFactory
{
    public async Task<string> ComputeHashAsync(byte[] input)
    {
        using var sha1 = SHA1.Create();
        byte[] hashBytes = await Task.Run(() => sha1.ComputeHash(input));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public class Sha256HashFactory : IHashFactory
{
    public async Task<string> ComputeHashAsync(byte[] input)
    {
        using var sha256 = SHA256.Create();
        byte[] hashBytes = await Task.Run(() => sha256.ComputeHash(input));
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }
}

public class SecureDataProcessor
{
    private readonly IHashFactory _md5Factory;
    private readonly IHashFactory _sha1Factory;
    private readonly IHashFactory _sha256Factory;

    public SecureDataProcessor()
    {
        _md5Factory = new Md5HashFactory();
        _sha1Factory = new Sha1HashFactory();
        _sha256Factory = new Sha256HashFactory();
    }

    public async Task<string> GenerateMd5Async(string input) => await GenerateHashAsync(_md5Factory, Encoding.UTF8.GetBytes(input));

    public async Task<string> GenerateMd5Async(byte[] input) => await GenerateHashAsync(_md5Factory, input);

    public async Task<string> GenerateSha1Async(string input) => await GenerateHashAsync(_sha1Factory, Encoding.UTF8.GetBytes(input));

    public async Task<string> GenerateSha1Async(byte[] input) => await GenerateHashAsync(_sha1Factory, input);

    public async Task<string> GenerateSha256Async(string input) => await GenerateHashAsync(_sha256Factory, Encoding.UTF8.GetBytes(input));

    public async Task<string> GenerateSha256Async(byte[] input) => await GenerateHashAsync(_sha256Factory, input);

    private static async Task<string> GenerateHashAsync(IHashFactory hashFactory, byte[] data)
    {
        return await hashFactory.ComputeHashAsync(data);
    }

    public async Task<string> CompressDataAsync(string input) => await CompressDataAsync(Encoding.UTF8.GetBytes(input));

    public async Task<string> CompressDataAsync(byte[] input)
    {
        using var outputStream = new MemoryStream();
        using (var compressionStream = new GZipStream(outputStream, CompressionMode.Compress))
        {
            await compressionStream.WriteAsync(input, 0, input.Length);
        }
        return Convert.ToHexString(outputStream.ToArray());
    }

    public async Task<string> EncryptDataAsync(string input) => await EncryptDataAsync(Encoding.UTF8.GetBytes(input));

    public async Task<string> EncryptDataAsync(byte[] input)
    {
        using var aes = Aes.Create();
        aes.GenerateKey();
        aes.GenerateIV();

        using var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
        using var outputStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(outputStream, encryptor, CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(input, 0, input.Length);
        }

        byte[] encryptedData = outputStream.ToArray();
        byte[] result = aes.IV.Concat(encryptedData).ToArray();
        return Convert.ToHexString(result);
    }
}

public static class Extensions
{
    public static string ConvertToHexString(this byte[] bytes)
    {
        var sb = new StringBuilder(bytes.Length * 2);
        foreach (var b in bytes)
            sb.AppendFormat("{0:x2}", b);
        return sb.ToString();
    }
}
```

### Key Points:

- **Hashing**: Uses `MD5`, `SHA1`, and `SHA256` algorithms with asynchronous operations.
- **Compression**: Uses GZip compression for data compression.
- **Encryption**: Employs AES encryption, returning both IV and encrypted data in hexadecimal format.
- **Asynchronous Operations**: Ensures non-blocking operations using `Task.Run`.
- **Hexadecimal Conversion**: Converts byte arrays to a hex string using an extension method.
- **Factory Pattern**: Allows easy addition of new hash algorithms by implementing the `IHashFactory` interface.

