template <typename Func, typename... Args>
bool tryWithRetry(Func func, Args&&... args, int attempts, const std::chrono::milliseconds& delay) {
    while (attempts-- > 0) {
        if (func(std::forward<Args>(args)...)) return true;
        std::this_thread::sleep_for(delay);
    }
    return false;
}

// Database operations
bool recordToDatabase(const std::string& transactionDetails) {
