        exit(EXIT_FAILURE);
    }
    return ptr;
}

FSA* expandStateList(State **stateList, int numStates, FSA *fsa, const char *dataSource, int lastStateId) {
    pthread_mutex_lock(&fsa->mutex);

    // Fetch new states from the external data source
    State *newStates = NULL;
    if (fetchNewStates(dataSource, &newStates) != 0) {
        fprintf(stderr, "Error fetching new states\n");
        pthread_mutex_unlock(&fsa->mutex);
        return fsa; // Return early in case of failure
    }

    // Expand the state list
    State *current = *stateList;
    for (int i = 0; i < numStates - 1; ++i) {
        current = current->next;
    }

    // Link last original state to the new states
    current->next = newStates;

    // Update the count of total states in FSA if needed

