def update_resource(resource_id):
    data = request.json

    try:
        conn = psycopg2.connect(
            dbname="your_db",
            user="your_user",
            password="your_password",
            host="localhost"
        )

        cur = conn.cursor()

        # Update resource query (simplified)
        cur.execute("UPDATE resources SET data=%s WHERE id=%s RETURNING *", 
                    (json.dumps(data), resource_id))
        updated_resource = cur.fetchone()

        if not updated_resource:
            return jsonify({"error": "Resource not found"}), 404

        conn.commit()

    except psycopg2.DatabaseError as e:
        return jsonify({"error": str(e)}), 500

    finally:
        cur.close()
        conn.close()

    return jsonify({"updatedResource": dict(updated_resource)})

