void print_usage(const char* progname) {
    fprintf(stderr, "Usage: %s <command> <input_files...> [output_file]\n",
            progname);
    fprintf(stderr, "Commands:\n");
    fprintf(stderr, "  compress\n");
    fprintf(stderr, "  decompress\n");
}

int process_file(const char* filename, const char* command) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    FILE *file = fdopen(fd, "r");
    if (!file) {
        perror("Error converting to stream");
        close(fd);
        return -1;
    }

    char line[1024];
    int line_count = 0;

    while (fgets(line, sizeof(line), file)) {
        // Process the line here (e.g., compress or decompress)
        ++line_count;
    }

    fclose(file);

    printf("Processed %d lines from %s\n", line_count, filename);
    return 0; 
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char* command = argv[1];
    if (strcmp(command, "compress") != 0 && strcmp(command, "decompress") != 0) {
        fprintf(stderr, "Invalid command: %s\n", command);
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

#ifdef __cplusplus
    insert_after_occurrence("example", "new");
#endif

    const char* output_file = NULL;
    if (argc > 3 && strcmp(argv[argc - 1], "-o") == 0) {
        output_file = argv[argc - 2];
        argc -= 2;
    }

    for (int i = 2; i < argc; ++i) {
        const char* filename = argv[i];

        if (process_file(filename, command) != 0) {
            fprintf(stderr, "Failed to process file: %s\n", filename);
            return EXIT_FAILURE;
        }
    }

    // Handle output redirection
    if (output_file) {
        int out_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
        if (out_fd == -1) {
            perror("Error opening output file");
            return EXIT_FAILURE;
        }

        // Redirect standard output to the output file
        if (dup2(out_fd, STDOUT_FILENO) == -1) {
            perror("Error redirecting stdout");
            close(out_fd);
            return EXIT_FAILURE;
        }

        close(out_fd);
    }

    return EXIT_SUCCESS;
}
