void extend_openssl_library() {
    // Load AES and Camellia algorithms
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_128_ecb());

    // Load hash functions
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());

    // RSA with SHA1 primitive
    if (EVP_PKEY_assign_RSA(NULL, RSA_new()) != 1) {
        fprintf(stderr, "Failed to assign RSA\n");
        exit(EXIT_FAILURE);
