import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.scheduling.annotation.Async;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;

@SpringBootApplication
@EnableAsync
public class Md5HashServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(Md5HashServiceApplication.class, args);
    }
}

@Service
class Md5HashService {

    @Async
    public Mono<String> computeMd5HashAsync(String filePath) {
        return Mono.just(filePath)
                .flatMap(this::validateFilePath)
                .flatMap(path -> readFileAndComputeHash(path))
                .onErrorMap(e -> new RuntimeException("Failed to compute MD5 hash", e));
    }

    private Mono<Path> validateFilePath(String filePath) {
        Path path = Paths.get(filePath);
        return Mono.fromCallable(() -> {
            if (!Files.exists(path)) {
                throw new IllegalArgumentException("File does not exist: " + path);
            }
            if (!Files.isRegularFile(path)) {
                throw new IllegalArgumentException("Path is not a file: " + path);
            }
            return path;
        }).onErrorMap(e -> new RuntimeException("Invalid file path", e));
    }

    private Mono<String> readFileAndComputeHash(Path path) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            return Mono.fromCallable(() -> {
                Files.lines(path)
                        .forEach(line -> md.update(line.getBytes()));
                byte[] digest = md.digest();
                StringBuilder sb = new StringBuilder();
                for (byte b : digest) {
                    sb.append(String.format("%02x", b));
                }
                return sb.toString();
            });
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        } catch (IOException e) {
            throw new RuntimeException("Failed to read file", e);
        }
    }
}
