import os
import hashlib
import json
from threading import Lock

class FileAggregator:
    def __init__(self, output_file):
        self.output_file = output_file
        self.lock = Lock()
        self.partial_checksums = {}

    def add_file(self, file_path):
        with self.lock:
            try:
                with open(file_path, 'rb') as f:
                    data = f.read()

                checksum = hashlib.sha256(data).hexdigest()
                if checksum not in self.partial_checksums:
                    self._append_to_output(data)
                    self.partial_checksums[checksum] = file_path
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

    def _append_to_output(self, data):
        with open(self.output_file, 'ab') as f:
            f.write(data)

    def validate_aggregated_file(self):
        final_checksum = self._calculate_checksum()
        return final_checksum

    def _calculate_checksum(self):
        sha256_hash = hashlib.sha256()
        with open(self.output_file, 'rb') as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

    def handle_interruption(self):
        # Save state or resume logic
        pass

class OAuth2Validator:
    @staticmethod
    def validate_token_response(json_str):
        try:
            token_data = json.loads(json_str)

            required_fields = ['access_token', 'expires_in', 'token_type']
            for field in required_fields:
                if field not in token_data:
                    return False

            if not isinstance(token_data['expires_in'], int) or token_data['expires_in'] <= 0:
                return False
            if token_data['token_type'].lower() != 'bearer':
                return False

            return True
        except (json.JSONDecodeError, TypeError):
            return False


# Example usage:

aggregator = FileAggregator('combined_output.dat')

files_to_aggregate = ['file1.txt', 'file2.bin']
for file in files_to_aggregate:
    aggregator.add_file(file)

print("Final Checksum:", aggregator.validate_aggregated_file())

token_response = '{"access_token": "abc123", "expires_in": 3600, "token_type": "Bearer"}'
is_valid = OAuth2Validator.validate_token_response(token_response)
print("Token Valid:", is_valid)
