public class PokemonWeaknesses {

    private static final Logger logger = Logger.getLogger(PokemonWeaknesses.class.getName());

    private ApiService apiService;
    private DatabaseService databaseService;

    public PokemonWeaknesses(ApiService apiService, DatabaseService databaseService) {
        this.apiService = apiService;
        this.databaseService = databaseService;
    }

    public CompletableFuture<String> getPokemonWeaknesses(String pokemonName) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                String type = getFromApi(pokemonName);
                if (type == null) {
                    throw new Exception("API request failed");
                }
                List<Weakness> weaknesses = fetchWeaknessDetails(type);
                return formatWeaknesses(weaknesses);

            } catch (Exception e) {
                logger.warning("Fetching from default data: " + e.getMessage());
                return getDefaultWeaknesses(pokemonName);
            }
        });
    }

    private String getFromApi(String pokemonName) {
        try {
            return apiService.getPokemonType(pokemonName);
        } catch (Exception e) {
            logger.warning("API failed for " + pokemonName + ": " + e.getMessage());
            return null;
        }
    }

    private List<Weakness> fetchWeaknessDetails(String type) throws Exception {
        Connection connection = null;
        PreparedStatement statement = null;
        ResultSet resultSet = null;

        int attempts = 0;
        while (attempts < 3) {
            try {
                connection = databaseService.getConnection();
                statement = connection.prepareStatement("SELECT * FROM weaknesses WHERE pokemon_type = ?");
                statement.setString(1, type);
                resultSet = statement.executeQuery();

                // Fetch and return weakness details
                WeaknessProcessor processor = new WeaknessProcessor();
                return processor.process(resultSet);

            } catch (Exception e) {
                logger.warning("Database access failed: " + e.getMessage());
                attempts++;
                Thread.sleep((long) Math.pow(2, attempts) * 1000); // Exponential backoff
            } finally {
                closeResources(resultSet, statement, connection);
            }
        }

        throw new Exception("Failed to fetch from database after retries");
    }

    private void closeResources(AutoCloseable... resources) {
        for (AutoCloseable resource : resources) {
            if (resource != null) {
                try {
                    resource.close();
                } catch (Exception e) {
                    logger.warning("Resource closing failed: " + e.getMessage());
                }
            }
        }
    }

    private String formatWeaknesses(List<Weakness> weaknesses) {
        // Format and return weakness details as a string
        StringBuilder sb = new StringBuilder();
        for (Weakness weakness : weaknesses) {
            sb.append(weakness.toString()).append("\n");
        }
        return sb.toString();
    }

    private String getDefaultWeaknesses(String pokemonName) {
        // Implement fallback mechanism using in-memory data
        return "Default Weaknesses for " + pokemonName;
    }
}

