async function asyncReduce(array, initialValue, callback) {
    try {
        // Helper function to simulate fetching additional data from an external API
        const fetchData = async (number) => {
            return new Promise((resolve, reject) => {
                setTimeout(() => {  // Simulating network delay
                    if (Math.random() < 0.9) {  // Random error simulation
                        resolve({ number: number, dataFromAPI: Math.random() * 100 });
                    } else {
                        reject(new Error(`Failed to fetch data for ${number}`));
                    }
                }, 50);  // Simulating a small delay for rate limiting
            });
        };

        let accumulator = initialValue;

        const reducerFunction = async (acc, current) => {
            try {
                const additionalData = await fetchData(current);
                return callback(acc, current, additionalData.dataFromAPI);
            } catch (error) {
                console.error(`Error fetching data for ${current}:`, error.message);
                // Decide how to handle errors in your reduction logic
                // For example, you might want to return the accumulator as is:
                return acc;
            }
        };

        // Sequentially reduce array to manage resources carefully
        for (const item of array) {
            accumulator = await reducerFunction(accumulator, item);
        }

        return { result: accumulator };
    } catch (error) {
        console.error("Error during reduction:", error.message);
        return { error: error.message };
    }
}

