    NamingConventionResponse response = { .fileType = 1, .numDigits = 4 };
    return response;
}

// Function to generate a unique filename based on metadata and system constraints.
char* generateUniqueFilename(const char* base_filename, int index, const NamingConventionResponse* response) {
    char* new_filename = (char*)malloc(strlen(base_filename) + response->numDigits + 10); // Extra space for digits and extension
    if (!new_filename) return NULL;

    snprintf(new_filename, strlen(base_filename) + response->numDigits + 10, "%s_%0*d.js", base_filename, response->numDigits, index);
    return new_filename;
}

