// Main function to load and execute multiple JavaScript files.
char* loadAndExecuteJSFiles(const char* base_filename, const char* js_files[], int num_files) {
    NamingConventionResponse response = getNamingConvention(base_filename);

    if (response.fileType < 0 || response.numDigits <= 0) {
        return strdup("Error: Invalid naming convention response.");
    }

    for (int i = 0; i < num_files; ++i) {
        char* unique_filename = generateUniqueFilename(base_filename, i + 1, &response);

        if (!unique_filename) {
            return strdup("Error: Failed to allocate memory for new filename.");
        }

        int result = loadAndExecuteJSFile(unique_filename);
        free(unique_filename);

        if (result != 0) {
            char* error_message = (char*)malloc(256);
            snprintf(error_message, 256, "Error: Failed to load or execute file %s", unique_filename);
            return error_message;
        }
    }

    // Return the new base filename as a success indicator
    size_t length = strlen(base_filename) + response.numDigits + 6; // Extra space for underscore and extension
    char* final_filename = (char*)malloc(length);
    snprintf(final_filename, length, "%s_%0*d.js", base_filename, response.numDigits, num_files);

    return final_filename;
}

int main() {
    const char* base_name = "script";
    const char* js_files[] = { "file1.js", "file2.js", "file3.js" };
    int num_js_files = sizeof(js_files) / sizeof(js_files[0]);

    char* result = loadAndExecuteJSFiles(base_name, js_files, num_js_files);

    if (strchr(result, 'E') != NULL) {
        printf("Failure: %s\n", result);
    } else {
        printf("Success: New base filename is %s\n", result);
    }

    free(result); // Free the dynamically allocated memory
    return 0;
}
