```php
<?php

class AdvancedWebSecurityManager {
    private $hashPassword;
    private $saltRoundCount = 12;
    private $recentStringsCache = [];
    private $maxRecentStrings = 100;

    public function generateSecureRandomString($length, $characterSet) {
        if (!validCharacterSet($characterSet)) {
            throw new InvalidArgumentException("Invalid character set.");
        }

        // Use cache to optimize repeated calls with the same length
        $cacheKey = 'random_' . $length;
        if (isset($this->recentStringsCache[$cacheKey])) {
            return $this->recentStringsCache[$cacheKey];
        }

        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $string .= $characterSet[random_int(0, strlen($characterSet) - 1)];
        }

        // Update cache
        if (count($this->recentStringsCache) >= $this->maxRecentStrings) {
            array_shift($this->recentStringsCache);
        }
        $this->recentStringsCache[$cacheKey] = $string;

        return $string;
    }

    public function hashPassword($password, $saltRoundCount = null) {
        if ($saltRoundCount === null) {
            $saltRoundCount = $this->saltRoundCount;
        } else {
            $this->setSaltRoundCount($saltRoundCount);
        }

        return password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($hashedPassword, $password) {
        return password_verify($password, $hashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) ||
            !preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) ||
            !preg_match('/[^a-zA-Z\d]/', $characterSet)) {
            throw new InvalidArgumentException("Character set must include uppercase, lowercase, digits, and special characters.");
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new InvalidArgumentException("Salt round count must be between 12 and 31.");
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        // Invalidate previous password cache (if applicable)

        // Reset internal hashed password
        $newHashedPassword = $this->hashPassword($this->generateSecureRandomString(12, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+[]{}|;:',.<>?/"));
        $this->hashPassword = $newHashedPassword;

        // Clear cache if needed
        array_shift($this->recentStringsCache);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        $logEntry = [
            'timestamp' => time(),
            'ipAddress' => $ipAddress,
            'result' => $result ? 'success' : 'failure'
        ];

        // Log to file (for simplicity)
        file_put_contents('password_attempts.log', json_encode($logEntry) . PHP_EOL, FILE_APPEND);
    }

    private function validCharacterSet($characterSet) {
        return preg_match('/[A-Z]/', $characterSet) &&
               preg_match('/[a-z]/', $characterSet) &&
               preg_match('/\d/', $characterSet) &&
               preg_match('/[^a-zA-Z\d]/', $characterSet);
    }
}
