```rust
use reqwest::Client;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use redis::{AsyncCommands, RedisResult};
use tokio::sync::Mutex;
use std::time::Duration;
use std::env;
use log::{info, warn, error};
use tokio::time::interval;

#[derive(Deserialize)]
struct Config {
    api_key: String,
    update_interval_seconds: u64,
    cache_expiration_seconds: u64,
}

async fn fetch_weather_data(location: &str, config: &Config) -> Result<Value, reqwest::Error> {
    let client = Client::new();
    let url = format!(
        "https://api.weather.com/v1/location/{}/observations/current.json?apiKey={}",
        location, config.api_key
    );

    info!("Fetching weather data for location: {}", location);

    let response = client.get(&url).send().await?;
    if response.status().is_success() {
        let weather_data = response.json::<Value>().await?;
        Ok(weather_data)
    } else {
        error!("Failed to fetch data. Status: {:?}", response.status());
        Err(reqwest::Error::new(
            reqwest::StatusCode::BAD_REQUEST,
            false,
        ))
    }
}

async fn cache_weather_data(redis_client: &mut redis::AsyncClient, location: &str, weather_data: Value) -> RedisResult<()> {
    let key = format!("weather:{}", location);
    info!("Caching data for location: {}", location);

    redis_client
        .set_ex(key.as_str(), serde_json::to_string(&weather_data)?, config.cache_expiration_seconds)
        .await?;

    Ok(())
}

async fn cleanup_expired_cache(redis_client: &mut redis::AsyncClient) -> RedisResult<()> {
    info!("Running cache cleanup task");

    let keys: Vec<String> = redis_client.keys("weather:*").await?;
    for key in keys {
        redis_client.del(&key).await?;
    }

    Ok(())
}

async fn get_weather_data(location: &str, config: Config) -> Result<Value, String> {
    let client = reqwest::Client::new();
    let mut redis_client = redis::AsyncClient::open("redis://127.0.0.1/").unwrap();

    // Check cache first
    if let Ok(cached_data): Option<Value> = redis_client.get(location).await.unwrap() {
        info!("Cache hit for location: {}", location);
        return Ok(cached_data);
    }

    // Fetch data from API
    match fetch_weather_data(location, &config).await {
        Ok(weather_data) => {
            if let Err(err) = cache_weather_data(&mut redis_client, location, weather_data.clone()).await {
                warn!("Failed to cache weather data: {}", err);
            }
            Ok(weather_data)
        },
        Err(e) => {
            error!("Error fetching weather data: {:?}", e);
            Err("Failed to fetch weather data".to_string())
        }
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let config_json = std::fs::read_to_string("config.json").expect("Unable to read config file");
    let config: Config = serde_json::from_str(&config_json).unwrap();

    let redis_client = redis::Client::open("redis://127.0.0.1/").expect("Invalid Redis URL");

    // Spawn background task for cleaning up expired cache entries
    tokio::spawn(async move {
        let mut redis_client = redis_client.get_async_connection().await.unwrap();

        loop {
            if let Err(e) = cleanup_expired_cache(&mut redis_client).await {
                error!("Error during cache cleanup: {:?}", e);
            }

            interval(Duration::from_secs(config.cache_expiration_seconds)).await;
        }
    });

    // Example of handling concurrent requests
    let mut handles = vec![];
    for i in 0..100 {
        let location = format!("New York,US"); // Example location
        handles.push(tokio::spawn(async move {
            match get_weather_data(&location, config).await {
                Ok(data) => info!("Weather data: {:?}", data),
                Err(e) => error!("Failed to get weather data: {}", e),
            }
        }));
    }

    for handle in handles {
        let _ = handle.await;
    }
}
```

