class BibleTextAnalyzer {
    constructor() {
        // Define regex patterns for old and new testament books
        this.oldTestamentBooks = [
            'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
            'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', 
            '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles', 
            'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 
            'Ecclesiastes', 'Song of Solomon', 'Isaiah', 'Jeremiah', 
            'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 
            'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 
            'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'
        ];

        this.newTestamentBooks = [
            'Matthew', 'Mark', 'Luke', 'John', 'Acts', 
            'Romans', '1 Corinthians', '2 Corinthians', 
            'Galatians', 'Ephesians', 'Philippians', 'Colossians', 
            '1 Thessalonians', '2 Thessalonians', 
            '1 Timothy', '2 Timothy', 'Titus', 'Philemon',
            'Hebrews', 'James', '1 Peter', '2 Peter', 
            '1 John', '2 John', '3 John', 'Jude', 'Revelation'
        ];

        this.bookRegex = new RegExp(
            `\\b(${this.oldTestamentBooks.join('|').replace(/ /g, '\\s*')})|` +
            `\\b(${this.newTestamentBooks.join('|').replace(/ /g, '\\s*')})\\b`, 
            'i'
        );

        this.bookCount = new Map();
        this.cache = new Map();
    }

    // Method to extract books from text
    analyzeText(text) {
        if (typeof text !== 'string' || !text.trim()) throw new Error('Invalid input');

        // Check cache first
        const cachedResult = this.cache.get(text);
        if (cachedResult) return cachedResult;

        let matches;
        const bookOccurrences = { oldTestament: {}, newTestament: {} };

        while ((matches = this.bookRegex.exec(text)) !== null) {
            const bookName = matches[0].replace(/\s+/g, ' ').trim();
            if (this.oldTestamentBooks.includes(bookName)) {
                bookOccurrences.oldTestament[bookName] = 
                    (bookOccurrences.oldTestament[bookName] || 0) + 1;
            } else if (this.newTestamentBooks.includes(bookName)) {
                bookOccurrences.newTestament[bookName] =
                    (bookOccurrences.newTestament[bookName] || 0) + 1;
            }

            // Logging frequency
            this.bookCount.set(bookName, 
                (this.bookCount.get(bookName) || 0) + 1);
        }

        const result = {
            oldTestament: bookOccurrences.oldTestament,
            newTestament: bookOccurrences.newTestament,
            totalMatches: Object.values(bookOccurrences.oldTestament)
                            .concat(Object.values(bookOccurrences.newTestament))
                            .reduce((sum, count) => sum + count, 0)
        };

        // Cache the result
        this.cache.set(text, result);

        return result;
    }

    // External API integration placeholder method
    verifyBooks(books) {
        console.log('Verifying books via external API:', books);
        // Implement actual API verification here
    }

    // Generate a report of book occurrences
    generateReport() {
        const summary = {
            mostFrequentBook: null,
            maxFrequency: 0,
            oldTestamentSummary: {},
            newTestamentSummary: {}
        };

        this.bookCount.forEach((count, book) => {
            if (count > summary.maxFrequency) {
                summary.mostFrequentBook = book;
                summary.maxFrequency = count;
            }

            if (this.oldTestamentBooks.includes(book)) {
                summary.oldTestamentSummary[book] = count;
            } else if (this.newTestamentBooks.includes(book)) {
                summary.newTestamentSummary[book] = count;
            }
        });

        return summary;
    }

    // Export the report in various formats
    exportReport(format) {
        const report = this.generateReport();

        switch (format.toLowerCase()) {
            case 'json':
                return JSON.stringify(report, null, 2);
            case 'csv':
                let csvContent = "Book Name,Frequency\n";
                [...report.oldTestamentSummary, ...report.newTestamentSummary].forEach(book => {
                    csvContent += `${book},${report.bookCount.get(book)}\n`;
                });
                return csvContent;
            default:
                throw new Error('Unsupported format');
        }
    }

    // Factory registry for creating subclasses
    static factoryRegistry = {};

    registerFactory(id, factoryFunction) {
        BibleTextAnalyzer.factoryRegistry[id] = factoryFunction;
    }

    createInstance(id, ...args) {
        const factoryFunction = BibleTextAnalyzer.factoryRegistry[id];
        if (!factoryFunction) throw new Error('Invalid factory ID');
        return factoryFunction(...args);
    }
}

// Function to run tests
function runTests(moduleLabel, testLabels, testFunctions) {
    require(`./${moduleLabel}`).then(module => {

        const results = [];

        async function runTest(testFunction) {
            try {
                await testFunction();
                console.log('Test passed');
            } catch (error) {
                console.error('Test failed:', error);
            }
        }

        for (let label of testLabels) {
            if (!testFunctions[label]) throw new Error(`Missing test function: ${label}`);
            results.push(runTest(testFunctions[label]));
        }

        Promise.all(results).then(() => {
            console.log('All tests completed');
            // Reset the mocking library after all tests
            blueslip.reset();
        }).catch(error => {
            console.error('Error running tests:', error);
            blueslip.reset(); // Ensure reset even if errors occur
        });

    }).catch(err => console.error(`Module load error: ${err}`));
}

module.exports = BibleTextAnalyzer;
