```c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <pthread.h>

typedef struct {
    char *name;
    void (*function)();
    void *params; // Add more specific type as needed for each library's API.
} Algorithm;

typedef struct {
    const char *lib_path;
    Algorithm **hash_functions;
    size_t hash_count;
    Algorithm **block_ciphers;
    size_t cipher_count;
} LibraryInfo;

typedef struct {
    pthread_mutex_t lock;
    LibraryInfo *libraries;
    size_t lib_count;
} CryptoLibraryManager;

static void load_library(CryptoLibraryManager *manager, const char *lib_path) {
    pthread_mutex_lock(&manager->lock);

    // Load library
    void *handle = dlopen(lib_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading library %s: %s\n", lib_path, dlerror());
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Example function to load algorithms from the library
    // This is a placeholder; replace with actual API calls of the target libraries
    int (*load_algorithms)(Algorithm **hashes, size_t *hash_count,
                           Algorithm **ciphers, size_t *cipher_count);

    *(void **)(&load_algorithms) = dlsym(handle, "load_algorithms");
    if (!load_algorithms) {
        fprintf(stderr, "Error loading symbols from %s: %s\n", lib_path, dlerror());
        dlclose(handle);
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Allocate memory for the new library info
    LibraryInfo *new_lib_info = malloc(sizeof(LibraryInfo));
    new_lib_info->lib_path = strdup(lib_path);
    new_lib_info->hash_functions = NULL;
    new_lib_info->block_ciphers = NULL;

    load_algorithms(&new_lib_info->hash_functions, &new_lib_info->hash_count,
                    &new_lib_info->block_ciphers, &new_lib_info->cipher_count);

    // Add library info to manager
    size_t new_size = manager->lib_count + 1;
    LibraryInfo **new_libraries = realloc(manager->libraries, new_size * sizeof(LibraryInfo *));
    if (!new_libraries) {
        fprintf(stderr, "Memory allocation failed\n");
        dlclose(handle);
        free(new_lib_info);
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->libraries = new_libraries;
    manager->libraries[manager->lib_count++] = new_lib_info;

    pthread_mutex_unlock(&manager->lock);
}

static void free_manager(CryptoLibraryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->lib_count; ++i) {
        LibraryInfo *info = manager->libraries[i];

        if (info->hash_functions) {
            for (size_t j = 0; j < info->hash_count; ++j)
                free(info->hash_functions[j]->name);
            free(info->hash_functions);
        }

        if (info->block_ciphers) {
            for (size_t j = 0; j < info->cipher_count; ++j)
                free(info->block_ciphers[j]->name);
            free(info->block_ciphers);
        }

        free((void *)info->lib_path);
        free(info);
    }

    free(manager->libraries);

    pthread_mutex_unlock(&manager->lock);
}

static void initialize_manager(CryptoLibraryManager *manager, size_t initial_capacity) {
    manager->libraries = malloc(initial_capacity * sizeof(LibraryInfo *));
    if (!manager->libraries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->lib_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

CryptoLibraryManager *create_crypto_library_manager(size_t initial_capacity) {
    CryptoLibraryManager *manager = malloc(sizeof(CryptoLibraryManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    initialize_manager(manager, initial_capacity);
    return manager;
}

void destroy_crypto_library_manager(CryptoLibraryManager *manager) {
    free_manager(manager);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

This C code provides a structure to dynamically load cryptographic libraries and retrieve available hash functions and block ciphers. It uses the `dlopen` and `dlsym` mechanisms for dynamic loading, ensuring thread safety with mutex locks, and handles errors gracefully while allowing efficient management of multiple libraries at runtime.

