Below is a simplified version of what a Python multi-threaded chat application could look like, integrating with various third-party messaging services. This example uses libraries such as `threading`, `requests`, and `cryptography` for encryption, along with placeholders for user configuration and service-specific logic.

```python
import threading
from queue import Queue
import requests
from cryptography.fernet import Fernet
import logging

# Configuration: Set up encryption keys, API credentials, etc.
CONFIG = {
    'encryption_key': Fernet.generate_key(),
    'services': [
        {'name': 'slack', 'api_url': 'https://slack.com/api/chat.postMessage'},
        {'name': 'discord', 'api_url': 'https://discordapp.com/api/channels/POST'},
        # Add more services here
    ],
}

# Queue for incoming messages
message_queue = Queue()

def encrypt_message(message, key):
    fernet = Fernet(key)
    return fernet.encrypt(message.encode())

def decrypt_message(encrypted_message, key):
    fernet = Fernet(key)
    return fernet.decrypt(encrypted_message).decode()

class MessagingService:
    def __init__(self, config):
        self.config = config

    def send_message(self, message, channel_id):
        encrypted_message = encrypt_message(message, CONFIG['encryption_key'])
        payload = {
            'channel': channel_id,
            'text': decrypt_message(encrypted_message, CONFIG['encryption_key']),
            # Add necessary headers and authentication
        }
        response = requests.post(self.config['api_url'], json=payload)
        if response.status_code != 200:
            logging.error(f"Failed to send message: {response.text}")

def worker():
    while True:
        service_config, message_data = message_queue.get()
        if message_data is None:  # Sentinel for shutdown
            break

        service = MessagingService(service_config)
        try:
            service.send_message(message_data['message'], message_data['channel_id'])
        except Exception as e:
            logging.error(f"Error in worker thread: {e}")
        finally:
            message_queue.task_done()

def start_workers(num_threads):
    threads = []
    for _ in range(num_threads):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)
    return threads

def scale_workers(new_num_threads, existing_threads):
    current_num = len(existing_threads)
    if new_num_threads > current_num:
        for _ in range(new_num_threads - current_num):
            t = threading.Thread(target=worker)
            t.start()
            existing_threads.append(t)
    elif new_num_threads < current_num:
        for _ in range(current_num - new_num_threads):
            message_queue.put((None, None))  # Sentinel to stop threads
            existing_threads.pop().join()

def main():
    logging.basicConfig(level=logging.INFO)

    # Start with a baseline number of worker threads
    num_workers = 5
    workers = start_workers(num_workers)

    try:
        while True:  # This would typically be tied to an event loop or server
            # Simulate incoming messages
            for service in CONFIG['services']:
                message_data = {'message': 'Hello, World!', 'channel_id': '#general'}
                message_queue.put((service, message_data))

            # Example of scaling workers based on some condition
            if message_queue.qsize() > 100:  # Arbitrary condition
                scale_workers(num_workers + 5, workers)
            elif message_queue.qsize() < 20 and num_workers > 5:
                scale_workers(num_workers - 5, workers)

    except KeyboardInterrupt:
        logging.info("Shutting down...")

    finally:
        for _ in workers:
            message_queue.put((None, None))  # Send sentinel to stop threads
        for worker_thread in workers:
            worker_thread.join()

if __name__ == '__main__':
    main()
```

### Key Features:

- **Encryption**: Uses `cryptography`'s Fernet for symmetric encryption of messages.
- **Multi-threading**: Manages a pool of worker threads that dynamically scale based on message queue size.
- **Service Integration**: Sends encrypted messages to various configured services, with placeholders for authentication and headers.
- **Queue Handling**: Uses a thread-safe `Queue` to manage incoming messages.
- **Logging**: Provides logging to handle errors and critical events.

