```python
import os
import threading
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def merge_files(file_paths, dest_path, buffer_size=1024*1024, max_retries=3, backoff_factor=0.5):
    def read_file_in_chunks(file_path, queue, retries=0):
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(buffer_size):
                    queue.put(chunk)
            queue.put(None)  # Signal end of file
        except Exception as e:
            if retries < max_retries:
                time.sleep(backoff_factor * (2 ** retries))
                read_file_in_chunks(file_path, queue, retries + 1)
            else:
                logging.error(f"Failed to read {file_path}: {e}")
                raise

    def write_to_dest(queue):
        with open(dest_path, 'ab') as dest_file:
            while True:
                chunk = queue.get()
                if chunk is None:  # Check for end signal
                    break
                try:
                    retries = 0
                    while retries < max_retries:
                        try:
                            dest_file.write(chunk)
                            break
                        except Exception as e:
                            logging.warning(f"Write failed: {e}")
                            time.sleep(backoff_factor * (2 ** retries))
                            retries += 1
                    if retries == max_retries:
                        logging.error("Max retries reached for writing chunk.")
                finally:
                    queue.task_done()

    def file_segment_reader(file_path, segment_size):
        size = os.path.getsize(file_path)
        with open(file_path, 'rb') as f:
            while offset < size:
                yield f.read(segment_size)

    queue = queue.Queue()

    # Handle large files by breaking into smaller segments
    segment_size = buffer_size * 10  # Customize based on need

    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        futures = []

        for file_path in file_paths:
            logging.info(f"Starting to read {file_path}")
            if os.path.getsize(file_path) > segment_size:
                for segment in file_segment_reader(file_path, segment_size):
                    futures.append(executor.submit(read_file_in_chunks, segment, queue))
            else:
                futures.append(executor.submit(read_file_in_chunks, file_path, queue))

        # Start writer thread
        writer_thread = threading.Thread(target=write_to_dest, args=(queue,))
        writer_thread.start()

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logging.error(f"Error processing file: {e}")

    queue.join()  # Wait until all chunks are written
    writer_thread.join()

    logging.info("Merging process completed successfully.")

# Example usage:
merge_files(['file1.txt', 'file2.txt'], 'merged_file.txt')
```

