<?php

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use Redis;

function authAndCacheUserScripts(array $scriptObjects) {
    session_start();

    // OAuth 2.0 Authentication
    try {
        $oauthClient = new \League\OAuth2\Client\Provider\GenericProvider([
            'clientId'                => 'your-client-id',
            'clientSecret'            => 'your-client-secret',
            'redirectUri'             => 'your-redirect-uri',
            'urlAuthorize'            => 'https://provider.com/oauth/authorize',
            'urlAccessToken'          => 'https://provider.com/oauth/token',
            'urlResourceOwnerDetails' => 'https://provider.com/resource'
        ]);

        if (!isset($_GET['code'])) {
            $authorizationUrl = $oauthClient->getAuthorizationUrl();
            header('Location: ' . $authorizationUrl);
            exit;
        }

        // Try to get an access token using the authorization code grant.
        $accessToken = $oauthClient->getAccessToken('authorization_code', [
            'code' => $_GET['code']
        ]);

        // Store access token in session
        $_SESSION['access_token'] = $accessToken->getToken();

        // Fetch user information using the access token
        $user = $oauthClient->getResourceOwner($accessToken);

        // Cache user data in Redis
        $redis = new Redis();
        $redis->connect('127.0.0.1', 6379);
        $redis->setex("user:{$user->getId()}", 3600, serialize($user));

    } catch (\League\OAuth2\Client\Provider\Exception\IdentityProviderException $e) {
        // Log authentication error
        file_put_contents('auth.log', date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
        exit('Authentication failed: ' . htmlspecialchars($e->getMessage()));
    }

    // Script Management and Rendering
    $client = new Client();
    foreach ($scriptObjects as $script) {
        if (!validateScriptKey($script['key'])) {
            echo "<p>Skipped script with key: {$script['key']}</p>";
            continue;
        }

        $metadata = fetchScriptMetadata($script);
        for ($i = 0; $i < 3; ++$i) { // Retry logic
            try {
                $response = $client->get(is_null($metadata['fallbackSrc']) ? $script['src'] : $metadata['fallbackSrc']);
                if ($response->getStatusCode() === 200) {
                    cacheAndRenderScript($redis, $script['key'], (string)$response->getBody());
                    break;
                }
            } catch (RequestException $e) {
                if ($i < 2) { // Retry up to two more times
                    sleep(5);
                } else {
                    file_put_contents('script_errors.log', date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
                    echo "<p>Failed to fetch script with key: {$script['key']}</p>";
                }
            }
        }
    }

    // Output scripts in the footer
    echo '<div id="footer-scripts"></div>';
}

function validateScriptKey($key) {
    $client = new Client();
    try {
        $response = $client->get("https://api.example.com/validate?script_key=$key");
        return $response->getStatusCode() === 200;
    } catch (RequestException $e) {
        file_put_contents('validation_errors.log', date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
        return false;
    }
}

function fetchScriptMetadata($script) {
    $client = new Client();
    try {
        $response = $client->get("https://config.example.com/scripts/{$script['key']}");
        if ($response->getStatusCode() === 200) {
            return json_decode((string)$response->getBody(), true);
        }
    } catch (RequestException $e) {
        file_put_contents('metadata_errors.log', date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
    }
    return [];
}

function cacheAndRenderScript($redis, $key, $content) {
    // Sanitize content to prevent XSS
    $sanitizedContent = htmlspecialchars($content);

    // Cache script content locally and in Redis
    file_put_contents("cache/$key.js", $sanitizedContent);
    $redis->setex("script:$key", 86400, $sanitizedContent); // Cache for a day

    // Render the <script> tag
    echo "<script type='{$key['type']}' src='cache/{$key}'>{$sanitizedContent}</script>";
}

