        _logger.LogInformation($"Cache Metrics for {cacheKey}: Hits={metrics.Hits}, Misses={metrics.Misses}, Evictions={metrics.Evictions}");
    }

    private void HandleFailureRecovery(string cacheKey, string userId, string configName, object newValue)
