public class DatabaseClient
{
    private readonly string _connectionString;
    private readonly ILogger<DatabaseClient> _logger;
    private readonly HttpClient _httpClient;
    private readonly ConcurrentQueue<Func<Task>> _requestQueue = new();
    private readonly object _lockObject = new();

    public DatabaseClient(string connectionString, ILogger<DatabaseClient> logger)
    {
        _connectionString = connectionString;
        _logger = logger;
        _httpClient = new HttpClient();
    }

    public async Task<DataTableReader> ProcessLargeByteArrayAsync(byte[] byteArray)
    {
        string sqlQuery = GenerateSqlFromBytes(byteArray);

        var policy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)), 
                (exception, timeSpan, context) =>
                {
                    _logger.LogError($"Retrying after {timeSpan.TotalSeconds} seconds due to: {exception.Message}");
                });

        await policy.ExecuteAsync(async () =>
        {
            await QueueRequestAsync(() => ExecuteQueryAsync(sqlQuery));
        });

        return new DataTableReader(await RetrieveResultAsync());
    }

    private async Task QueueRequestAsync(Func<Task> action)
    {
        lock (_lockObject)
        {
            _requestQueue.Enqueue(action);
        }

        await ProcessQueue();
    }

    private async Task ProcessQueue()
    {
        while (_requestQueue.TryDequeue(out var requestAction))
        {
            try
            {
                await requestAction.Invoke();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing queue action");
            }
        }
    }

    private async Task ExecuteQueryAsync(string sqlQuery)
    {
        using var connection = new System.Data.SqlClient.SqlConnection(_connectionString);
        await connection.OpenAsync();

        try
        {
            var result = await connection.QueryMultipleAsync(sqlQuery);
            // Store the result for later retrieval if needed
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing SQL query");
            throw;
        }
