```java
import java.io.File;
import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Logger;
import org.slf4j.LoggerFactory;

// External libraries
import redis.clients.jedis.Jedis;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.hash.Hashing;

public class DirectoryProcessor {

    private static final Logger logger = LoggerFactory.getLogger(DirectoryProcessor.class);
    private final LoadingCache<String, String> cache;
    private final Jedis jedis;

    public DirectoryProcessor() {
        this.jedis = new Jedis("localhost");
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(100)
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .build(new CacheLoader<String, String>() {
                    @Override
                    public String load(String key) throws Exception {
                        // Simulate loading from Redis if not in cache
                        return jedis.get(key);
                    }
                });
    }

    public CompletableFuture<String> processDirectoryContents(String directoryPath, String extension, Charset charset) {
        validateDirectoryPath(directoryPath);

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<CompletableFuture<String>> futures = new ArrayList<>();

        try (Stream<Path> paths = Files.walk(Paths.get(directoryPath))) {
            paths.filter(path -> path.toString().endsWith(extension))
                 .forEach(path -> futures.add(CompletableFuture.supplyAsync(() -> readFileContents(path, charset), executor)));
        } catch (IOException e) {
            logger.error("Error reading directory: {}", e.getMessage());
        }

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(v -> futures.stream()
                        .map(CompletableFuture::join)
                        .reduce((content1, content2) -> content1 + "\n" + content2)
                        .orElse(""));

    }

    private void validateDirectoryPath(String directoryPath) {
        if (directoryPath == null || directoryPath.length() > 1000) {
            throw new IllegalArgumentException("Invalid directory path");
        }
    }

    private String readFileContents(Path path, Charset charset) {
        try {
            String cachedContent = cache.get(path.toString());
            if (cachedContent != null) {
                return cachedContent;
            }

            byte[] fileBytes = Files.readAllBytes(path);
            String content = new String(fileBytes, charset);

            // Cache the file contents
            cache.put(path.toString(), content);

            // Log and compute hashes
            logger.info("File: {} Content Length: {}", path.getFileName(), content.length());
            String md5Hash = generateMD5(content);
            String sha256Hash = Hashing.sha256().hashString(content, charset).toString();

            jedis.setex(path.toString(), 3600, content); // Cache in Redis

            return content;
        } catch (IOException | Exception e) {
            logger.error("Error reading file: {}", path.getFileName(), e);
            return "";
        }
    }

    private String generateMD5(String content) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(content.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        DirectoryProcessor processor = new DirectoryProcessor();

        // Example usage
        CompletableFuture<String> result = processor.processDirectoryContents("your_directory_path_here", ".txt", Charset.forName("UTF-8"));

        result.thenAccept(System.out::println).get();
    }
}
