```csharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text.Json;
using System.Threading.Tasks;

public interface ISerializationStrategy
{
    Task<object> DeserializeAsync(Stream stream);
}

public class BinaryFormatterSerialization : ISerializationStrategy
{
    public async Task<object> DeserializeAsync(Stream stream)
    {
        var formatter = new BinaryFormatter();
        return await Task.Run(() => formatter.Deserialize(stream));
    }
}

public class JsonSerializerStrategy : ISerializationStrategy
{
    public async Task<object> DeserializeAsync(Stream stream)
    {
        using var reader = new StreamReader(stream);
        var jsonText = await reader.ReadToEndAsync();
        return JsonSerializer.Deserialize(jsonText, typeof(object)); // Replace `typeof(object)` with your actual type
    }
}

public class ConfigurationManager
{
    public static string GetSerializationFormat()
    {
        // This method should retrieve the serialization format from a config file or environment variable
        return "BinaryFormatter";  // Example: return "Json"
    }
}

public class LoggerService
{
    public static void LogError(Exception ex)
    {
        // Implement logging logic here, possibly using a third-party service
        Console.WriteLine($"Error: {ex.Message}");
    }

    public static void LogInfo(string message)
    {
        Console.WriteLine(message);
    }
}

public class DataLoader
{
    private readonly ISerializationStrategy _serializationStrategy;

    public DataLoader()
    {
        string format = ConfigurationManager.GetSerializationFormat();
        switch (format)
        {
            case "BinaryFormatter":
                _serializationStrategy = new BinaryFormatterSerialization();
                break;
            case "Json":
                _serializationStrategy = new JsonSerializerStrategy();
                break;
            default:
                throw new InvalidOperationException("Unsupported serialization format");
        }
    }

    public async Task<object> LoadDataAsync(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
            {
                LoggerService.LogError(new FileNotFoundException($"File not found: {filePath}"));
                return null;
            }

            using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read);
            var data = await _serializationStrategy.DeserializeAsync(fileStream);
            LoggerService.LogInfo("Data loaded successfully.");
            return data;
        }
        catch (IOException ex)
        {
            LoggerService.LogError(new IOException($"I/O error: {ex.Message}", ex));
            throw;
        }
        catch (SerializationException ex)
        {
            LoggerService.LogError(new SerializationException($"Deserialization failed: {ex.Message}", ex));
            throw;
        }
        catch (Exception ex)
        {
            LoggerService.LogError(ex);
            throw new InvalidOperationException("An unexpected error occurred", ex);
        }
    }
}
