    public MoSTState fetchAndProcessState(String filePath)
            throws DFSClientNotAvailableException, NetworkConnectivityException, ClassLoadingException {

        if (!isDFSClientAvailable()) {
            throw new DFSClientNotAvailableException("DFS client library is not available.");
        }

        try (ObjectInputStream ois = createObjectInputStream(filePath)) {
            Object obj = ois.readObject();
            return (obj instanceof MoSTState) ? (MoSTState) obj : null;
        } catch (IOException | ClassNotFoundException e) {
            handleException(e);
            throw new ClassLoadingException("Error loading class from file: " + filePath, e);
        }
    }

