            InputStream inputStream = url.openStream();
            return new ObjectInputStream(new BufferedInputStream(inputStream));
        } catch (MalformedURLException e) {
            throw new NetworkConnectivityException("Invalid DFS path: " + filePath);
        } catch (IOException e) {
            if (isNetworkError(e)) {
                // Implement retry logic or fallback mechanism here
                throw new NetworkConnectivityException("Network error accessing file: " + filePath, e);
