```java
import java.util.concurrent.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.logging.*;

public class CacheManager {
    private final ConcurrentHashMap<String, UserSession> cache = new ConcurrentHashMap<>();
    private final ConcurrentLinkedQueue<String> lruQueue = new ConcurrentLinkedQueue<>();
    private final int maxCacheSize;
    private final EvictionPolicy evictionPolicy;
    private static final Logger logger = Logger.getLogger(CacheManager.class.getName());

    public CacheManager(int maxCacheSize, EvictionPolicy evictionPolicy) {
        this.maxCacheSize = maxCacheSize;
        this.evictionPolicy = evictionPolicy;
        configureLogger();
    }

    public synchronized UserSession getSession(String sessionId) {
        UserSession session = cache.get(sessionId);
        if (session != null) {
            logger.log(Level.INFO, "Cache hit for session: {0}", sessionId);
            lruQueue.remove(sessionId); // Move accessed item to the end
            lruQueue.offer(sessionId);
            return session;
        }
        logger.log(Level.WARNING, "Cache miss for session: {0}", sessionId);
        return null;
    }

    public synchronized void putSession(String sessionId, UserSession session) {
        if (cache.size() >= maxCacheSize) {
            evictSessions();
        }
        cache.put(sessionId, session);
        lruQueue.offer(sessionId);
        logger.log(Level.INFO, "Session added: {0}", sessionId);
    }

    public synchronized void invalidateSession(String sessionId) {
        cache.remove(sessionId);
        lruQueue.remove(sessionId);
        logger.log(Level.INFO, "Session invalidated: {0}", sessionId);
    }

    public synchronized void invalidateAll() {
        cache.clear();
        lruQueue.clear();
        logger.log(Level.INFO, "All sessions invalidated.");
    }

    private void evictSessions() {
        while (cache.size() > maxCacheSize) {
            String sessionIdToEvict = evictionPolicy.getEvictionCandidate(lruQueue);
            if (sessionIdToEvict != null) {
                cache.remove(sessionIdToEvict);
                lruQueue.poll();
                logger.log(Level.INFO, "Session evicted: {0}", sessionIdToEvict);
            }
        }
    }

    private void configureLogger() {
        LogManager.getLogManager().reset();
        Logger rootLogger = Logger.getLogger("");
        Handler consoleHandler = new ConsoleHandler();
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);

        // Additional configuration for file logging, if needed
    }

    public enum EvictionPolicy {
        LRU {
            @Override
            String getEvictionCandidate(ConcurrentLinkedQueue<String> queue) {
                return queue.poll(); // FIFO-like behavior of ConcurrentLinkedQueue
            }
        },
        FIFO {
            @Override
            String getEvictionCandidate(ConcurrentLinkedQueue<String> queue) {
                return queue.peek();
            }
        };

        abstract String getEvictionCandidate(ConcurrentLinkedQueue<String> queue);
    }

    public void logMetrics() {
        // Integrate with external monitoring systems, e.g., Prometheus or custom metrics
        logger.log(Level.INFO, "Cache Size: {0}", cache.size());
        // Additional metrics logging
    }
}

class UserSession {
    private final String sessionId;
    private final long creationTime;

    public UserSession(String sessionId) {
        this.sessionId = sessionId;
        this.creationTime = System.currentTimeMillis();
    }

    public String getSessionId() {
        return sessionId;
    }

    public long getCreationTime() {
        return creationTime;
    }
}
```

This implementation provides a basic structure for the `CacheManager` class, supporting configurable eviction policies and thread-safe operations. The use of `ConcurrentHashMap` ensures concurrent access handling, while `ConcurrentLinkedQueue` helps manage LRU order efficiently. Logging is implemented using Java's built-in logging framework, and it includes cache hit/miss notifications and session evictions. Further integration with external monitoring systems can be added in the `logMetrics()` method. The class is designed to support future extensions and additional eviction policies if needed.

