// Define log levels
enum LogLevel {
    INFO,
    WARNING,
    ERROR
};

// Custom logger function type
using LoggerFunction = void(*)(LogLevel, const std::string&);

// Structure for connection settings
struct ConnectionSettings {
    int timeout;         // in seconds
    int maxRetries;
    int concurrencyLevel; // zero indicates no limit
};

// Configuration structure
struct DatabaseConfig {
    std::string* dbURL;
    std::string* username;
    std::string* password;
    ConnectionSettings* settings;
    LoggerFunction logger;
};

// Utility function to log messages using the custom logger
void logMessage(LoggerFunction logger, LogLevel level, const std::string& message) {
    if (logger != nullptr) {
        logger(level, message);
    }
}

bool isValidConnectionSetting(const ConnectionSettings& settings) {
    return settings.timeout > 0 && settings.maxRetries >= 0 &&
           (settings.concurrencyLevel == 0 || settings.concurrencyLevel > 0);
}

void establishDatabaseConnection(DatabaseConfig* config) {
    if (!config || !config->dbURL || !config->username || !config->password ||
        !config->settings || config->logger == nullptr) {
        logMessage(config->logger, ERROR, "Invalid configuration.");
        return;
    }

    std::string dbURL = *config->dbURL;
    std::string username = *config->username;
    std::string password = *config->password;

    if (dbURL.empty() || username.empty() || password.empty()) {
        logMessage(config->logger, ERROR, "Database URL, username or password cannot be empty.");
        return;
    }

    const ConnectionSettings& settings = *config->settings;

    if (!isValidConnectionSetting(settings)) {
        logMessage(config->logger, WARNING, "Invalid connection settings.");
        return;
    }

    std::mutex mtx;
    std::condition_variable cv;
    bool connected = false;
    int attempts = 0;

    // Thread-safe function to attempt database connection
    auto connectWithRetry = [&]() {
        while (!connected && attempts < settings.maxRetries) {
            attempts++;
            try {
                // Simulate connection logic (replace with actual implementation)
                logMessage(config->logger, INFO, "Attempting to establish a database connection...");

                // Example: Fake success or failure
                bool isSuccessful = true; // Replace this condition with actual connection logic

                if (isSuccessful) {
                    connected = true;
                    logMessage(config->logger, INFO, "Database connection established successfully.");
                    return;
                } else {
                    throw std::runtime_error("Failed to connect to the database");
                }
            } catch (const std::exception& e) {
                logMessage(config->logger, ERROR, std::string("Connection attempt failed: ") + e.what());

                // Exponential backoff
                int sleepTime = 1 << attempts; // exponential growth
                if (sleepTime > settings.timeout) { sleepTime = settings.timeout; }
                std::this_thread::sleep_for(std::chrono::seconds(sleepTime));

                logMessage(config->logger, WARNING, "Retrying connection attempt...");
            }
        }

        if (!connected) {
            logMessage(config->logger, ERROR, "Exceeded maximum retries. Could not establish a database connection.");
        }
    };

    // Managing concurrency
    std::vector<std::thread> threads;
    int activeThreads = 0;

    {
        std::unique_lock<std::mutex> lock(mtx);

        while (!connected) {
            if (settings.concurrencyLevel == 0 || activeThreads < settings.concurrencyLevel) {
                threads.emplace_back(connectWithRetry);
                activeThreads++;

                if (connected) break; // Exit loop if connected
            } else {
                cv.wait(lock, [&] { return activeThreads < settings.concurrencyLevel || connected; });
            }
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }
}

