void myCustomLogger(LogLevel level, const std::string& message) {
    switch (level) {
        case INFO: std::cout << "[INFO] " << message << std::endl; break;
        case WARNING: std::cout << "[WARNING] " << message << std::endl; break;
        case ERROR: std::cerr << "[ERROR] " << message << std::endl; break;
    }
}

