```cpp
#include <iostream>
#include <vector>
#include <stdexcept>
#include <mutex>
#include <unordered_map>
#include <chrono>
#include <filesystem>
#include <thread>

namespace fs = std::filesystem;

class OctreeNode {
public:
    // Point structure for 3D coordinates
    struct Point {
        float x, y, z;
    };

private:
    struct NodeData {
        std::vector<Point> points;
        bool isLeaf;
        std::unique_ptr<OctreeNode> children[8];
    };

    NodeData* root = nullptr;
    size_t featureSize;
    size_t maxCapacity;

    static constexpr int MAX_DEPTH = 10; // Set a reasonable maximum depth for the octree
    mutable std::mutex treeMutex; // Mutex for thread safety

public:
    OctreeNode(size_t featureSize, size_t initialLeafNodes, size_t capacity)
        : featureSize(featureSize), maxCapacity(capacity) {

        if (featureSize <= 0 || initialLeafNodes < 1 || capacity < 1) {
            throw std::invalid_argument("Invalid parameters for initializing octree.");
        }

        try {
            root = new NodeData{std::vector<Point>(initialLeafNodes), true, {}};
        } catch (const std::bad_alloc&) {
            throw std::runtime_error("Memory allocation failed during octree initialization.");
        }
    }

    ~OctreeNode() {
        delete root;
    }

    // Insert a point into the octree
    void insert(const Point& point) {
        std::lock_guard<std::mutex> lock(treeMutex);
        insertRec(root, point, 0);
    }

private:
    bool isWithinBounds(const Point& point, float xMin, float yMin, float zMin, float size) const {
        return (point.x >= xMin && point.x <= xMin + size &&
                point.y >= yMin && point.y <= yMin + size &&
                point.z >= zMin && point.z <= zMin + size);
    }

    void insertRec(NodeData* node, const Point& point, int depth) {
        if (!node->isLeaf || depth == MAX_DEPTH) return;

        float halfSize = featureSize / (1 << depth);
        for (int i = 0; i < 8; ++i) {
            float xMin = (i & 4) ? node->points[0].x + halfSize : node->points[0].x;
            float yMin = (i & 2) ? node->points[0].y + halfSize : node->points[0].y;
            float zMin = (i & 1) ? node->points[0].z + halfSize : node->points[0].z;

            if (!node->children[i] && isWithinBounds(point, xMin, yMin, zMin, halfSize)) {
                node->children[i] = std::make_unique<OctreeNode>(featureSize, 1, maxCapacity);
                node->children[i]->insertRec(node->children[i]->root, point, depth + 1);
            }
        }

        if (node->points.size() < static_cast<size_t>(maxCapacity)) {
            node->points.push_back(point);
        } else {
            // Handle node splitting or balancing logic
        }
    }

public:
    // Retrieve points from the octree within a given range
    std::vector<Point> retrieve(const Point& min, const Point& max) const {
        std::lock_guard<std::mutex> lock(treeMutex);
        return retrieveRec(root, min, max, 0);
    }

private:
    std::vector<Point> retrieveRec(NodeData* node, const Point& min, const Point& max, int depth) const {
        if (!node || !isWithinBounds(min, 0, 0, 0, featureSize)) return {};

        std::vector<Point> results;
        for (const auto& point : node->points) {
            if (point.x >= min.x && point.x <= max.x &&
                point.y >= min.y && point.y <= max.y &&
                point.z >= min.z && point.z <= max.z) {
                results.push_back(point);
            }
        }

        float halfSize = featureSize / (1 << depth);
        for (int i = 0; i < 8; ++i) {
            if (!node->children[i]) continue;

            float xMin = (i & 4) ? min.x + halfSize : min.x;
            float yMin = (i & 2) ? min.y + halfSize : min.y;
            float zMin = (i & 1) ? min.z + halfSize : min.z;

            if (isWithinBounds(min, xMin, yMin, zMin, halfSize)) {
                auto childResults = retrieveRec(node->children[i].get(), min, max, depth + 1);
                results.insert(results.end(), childResults.begin(), childResults.end());
            }
        }

        return results;
    }
};

// Compile Rust files in a given directory and measure time
void compileRustFiles(const std::string& dirPath) {
    auto start = std::chrono::high_resolution_clock::now();

    // Use an unordered map to cache compiled file hashes for performance optimization
    std::unordered_map<std::string, std::string> compilationCache;

    try {
        fs::path path(dirPath);
        if (!fs::exists(path) || !fs::is_directory(path)) {
            throw std::invalid_argument("Provided path is not a valid directory.");
        }

        for (const auto& entry : fs::directory_iterator(path)) {
            const auto& filePath = entry.path();
            if (filePath.extension() == ".rs") {
                // Simulate checking the file's hash and caching
                std::string fileHash = "hash_" + filePath.string();  // Placeholder for actual hashing

                if (compilationCache.find(filePath.string()) != compilationCache.end() &&
                    compilationCache[filePath.string()] == fileHash) {
                    continue;  // Skip already compiled files with the same hash
                }

                std::cout << "Compiling: " << filePath << std::endl;

                // Simulate compilation process and potential error handling
                bool compileSuccess = true;  // Placeholder for actual compilation logic

                if (!compileSuccess) {
                    throw std::runtime_error("Compilation failed for file: " + filePath.string());
                }

                // Update cache with new hash after successful compilation
                compilationCache[filePath.string()] = fileHash;
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "Error during compilation process: " << e.what() << std::endl;
    }

    auto end = std::chrono::high_resolution_clock::now();
