using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class SecureDataProcessor : IDisposable
{
    private readonly IMemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    private readonly ConcurrentDictionary<string, object> _lockMap = new();
    private readonly SemaphoreSlim _semaphore = new(10); // Max 10 concurrent operations
    private readonly IConfiguration _configuration;

    public SecureDataProcessor(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public async Task<string> ProcessMessageAsync(string message, string sourceId, int clearanceLevel)
    {
        await _semaphore.WaitAsync();

        try
        {
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();

            // Audit log start
            LogAuditEvent("Start", sourceId, clearanceLevel);

            var context = new ProcessingContext
            {
                SourceId = sourceId,
                ClearanceLevel = clearanceLevel
            };

            using (await _lockMap.GetOrAdd(context.Key(), new object()))
            {
                try
                {
                    // Fetch keys and IVs from CSP
                    var encryptionInfo = await GetEncryptionInfoAsync(sourceId, context);

                    string decryptedMessage = await DecryptMessageAsync(message, encryptionInfo, clearanceLevel);

                    if (decryptedMessage == null)
                        throw new InvalidOperationException("Decryption failed.");

                    bool isValid = ValidateMessage(decryptedMessage);
                    if (!isValid) throw new InvalidDataException("Validation failed.");

                    // Process the message
                    string result = await ProcessDecryptedMessageAsync(decryptedMessage);

                    // Audit log success
                    LogAuditEvent("Success", sourceId, clearanceLevel, stopwatch.ElapsedMilliseconds);

                    return result;
                }
                catch (Exception ex)
                {
                    // Audit log failure
                    LogAuditEvent("Failure", sourceId, clearanceLevel, stopwatch.ElapsedMilliseconds, ex.Message);
                    throw;
                }
            }
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<EncryptionInfo> GetEncryptionInfoAsync(string sourceId, ProcessingContext context)
    {
        var cacheKey = $"Keys_{sourceId}_{context.ClearanceLevel}";
        if (!_cache.TryGetValue(cacheKey, out EncryptionInfo encryptionInfo))
        {
            encryptionInfo = await FetchFromPrimaryCsp(sourceId, context);
            _cache.Set(cacheKey, encryptionInfo);

            if (encryptionInfo == null)
                encryptionInfo = await FetchFromSecondaryCsp(sourceId, context);

            // Validate and update cache
            if (encryptionInfo != null) 
                _cache.Set(cacheKey, encryptionInfo);
        }
        return encryptionInfo;
    }

    private async Task<string> DecryptMessageAsync(string message, EncryptionInfo info, int clearanceLevel)
    {
        switch (info.Algorithm.ToLower())
        {
            case "3des":
                return await TripleDesDecryptAsync(message, info.Key, info.IV);
            case "aes":
                return await AesDecryptAsync(message, info.Key, info.IV);
            case "rsa":
                return RsaDecrypt(message, info.PrivateKey);
            default:
                throw new NotSupportedException("Unsupported algorithm");
        }
    }

    private async Task<string> TripleDesDecryptAsync(string cipherText, byte[] key, byte[] iv)
    {
        using (var tripleDES = TripleDESCryptoServiceProvider.Create())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;

            var decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV);
            return await Task.FromResult(DoDecryption(cipherText, decryptor));
        }
    }

    private async Task<string> AesDecryptAsync(string cipherText, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            return await Task.FromResult(DoDecryption(cipherText, decryptor));
        }
    }

    private string RsaDecrypt(string cipherText, RSAParameters privateKey)
    {
        using (var rsa = new RSACryptoServiceProvider())
        {
            rsa.ImportParameters(privateKey);
            var dataBytes = Convert.FromBase64String(cipherText);
            return Encoding.UTF8.GetString(rsa.Decrypt(dataBytes, false));
        }
    }

    private string DoDecryption(string cipherText, ICryptoTransform decryptor)
    {
        using (var memoryStream = new MemoryStream(Convert.FromBase64String(cipherText)))
        {
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
            {
                using (var reader = new StreamReader(cryptoStream))
                {
                    return reader.ReadToEnd();
                }
            }
        }
    }

    private bool ValidateMessage(string message)
    {
        // Implement signature verification and checksum validation logic
        return true;
    }

    private async Task<string> ProcessDecryptedMessageAsync(string decryptedMessage)
    {
        // Implement actual message processing logic here
        await Task.Delay(100);  // Simulate some processing delay
        return "Processed: " + decryptedMessage;
    }

    private void LogAuditEvent(string status, string sourceId, int clearanceLevel, long duration = 0, string errorMessage = null)
    {
        Console.WriteLine($"[{DateTime.UtcNow}] Source: {sourceId}, Clearance Level: {clearanceLevel}, Status: {status}, Duration: {duration}ms, Error: {errorMessage}");
    }

    private async Task<EncryptionInfo> FetchFromPrimaryCsp(string sourceId, ProcessingContext context)
    {
        // Implement primary CSP key fetching logic here
        return await Task.FromResult(new EncryptionInfo());  // Mock implementation
    }

    private async Task<EncryptionInfo> FetchFromSecondaryCsp(string sourceId, ProcessingContext context)
    {
        // Implement secondary CSP fallback fetching logic here
        return await Task.FromResult(new EncryptionInfo());  // Mock implementation
    }

    public void Dispose()
    {
        _semaphore.Dispose();
        _cache.Dispose();
    }

    private class ProcessingContext
    {
        public string SourceId { get; set; }
        public int ClearanceLevel { get; set; }

        public string Key() => $"{SourceId}_{ClearanceLevel}";
    }

    private class EncryptionInfo
    {
        public string Algorithm { get; set; }
        public byte[] Key { get; set; }
        public byte[] IV { get; set; }
        public RSAParameters PrivateKey { get; set; }  // For RSA decryption
    }
}
