<?php

class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cache = [];
    private $cacheExpiration = 300; // Default expiration time in seconds
    private $characterSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()";
    private const MIN_SALT_ROUNDS = 12;
    private const MAX_SALT_ROUNDS = 31;

    public function generateSecureRandomString($length) {
        if (isset($this->cache[$length]) && (time() - $this->cache[$length]['timestamp'] < $this->cacheExpiration)) {
            return $this->cache[$length]['string'];
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[random_int(0, strlen($this->characterSet) - 1)];
        }

        $this->cache[$length] = [
            'string' => $randomString,
            'timestamp' => time()
        ];

        return $randomString;
    }

    public function hashPassword($password) {
        if (time() - $_SERVER['REQUEST_TIME_FLOAT'] < 2) { // Simple rate limiting
            throw new Exception("Too many requests. Please wait.");
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($password) {
        if (password_verify($password, $this->hashedPassword)) {
            // Simulate 2FA SMS sending
            $this->sendTwoFactorCode();
            return true;
        }
        $this->logPasswordAttempts($_SERVER['REMOTE_ADDR'], false);
        return false;
    }

    private function sendTwoFactorCode() {
        // Placeholder for SMS gateway integration
        echo "Sending 2FA code via SMS...\n";
    }

    public function validateCharacterSet($characterSet) {
        if ($this->hasValidCharacterSet($characterSet)) {
            $this->characterSet = $characterSet;
            return true;
        }
        return false; // Fallback mechanism can be added here
    }

    private function hasValidCharacterSet($charSet) {
        return preg_match('/[a-z]/', $charSet) && preg_match('/[A-Z]/', $charSet)
               && preg_match('/\d/', $charSet) && preg_match('/[^a-zA-Z\d]/', $charSet);
    }

    public function setSaltRoundCount($rounds) {
        if ($this->validateSaltRounds($rounds)) {
            $this->saltRoundCount = $rounds;
        }
    }

    private function validateSaltRounds($rounds) {
        return is_int($rounds) && $rounds >= self::MIN_SALT_ROUNDS && $rounds <= self::MAX_SALT_ROUNDS;
    }

    public function resetPassword() {
        if ($this->hashedPassword) {
            $length = strlen(str_replace('$2y$', '', crypt('')));
            unset($this->cache[$length]);
        }

        $newRandomString = $this->generateSecureRandomString(10);
        $this->hashPassword($newRandomString);

        $this->logResetEvent();
    }

    private function logResetEvent() {
