```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureMessageProcessor {
    private readonly string _masterKey;
    private ConcurrentDictionary<string, byte[]> _keyCache = new ConcurrentDictionary<string, byte[]>();
    private const int KeyRotationIntervalSeconds = 86400; // 24 hours
    private static readonly object _lockObject = new object();

    public SecureMessageProcessor(string masterKey) {
        _masterKey = masterKey;
        StartKeyRotation();
    }

    public async Task<string> DecryptMessageAsync(string base64Encoded, string contextIdentifier) {
        byte[] key = await GetDecryptionKey(contextIdentifier);
        if (key == null) throw new Exception("Failed to retrieve decryption key.");

        try {
            return Decrypt(base64Encoded, key);
        } catch (Exception ex) {
            LogError(ex);
            throw;
        }
    }

    private async Task<byte[]> GetDecryptionKey(string contextIdentifier) {
        return await Task.Run(() => {
            lock (_lockObject) {
                if (!_keyCache.TryGetValue(contextIdentifier, out var key)) {
                    key = DeriveKey(_masterKey, contextIdentifier);
                    _keyCache[contextIdentifier] = key;
                }
                return key;
            }
        });
    }

    private byte[] DeriveKey(string masterKey, string contextIdentifier) {
        using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(masterKey))) {
            return hmac.ComputeHash(Encoding.UTF8.GetBytes(contextIdentifier));
        }
    }

    private string Decrypt(string base64Encoded, byte[] key) {
        byte[] encryptedBytes = Convert.FromBase64String(base64Encoded);

        using (Aes aesAlg = Aes.Create()) {
            aesAlg.Key = key;
            var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            // Decrypt the bytes to a memory stream
            using (var msDecrypt = new System.IO.MemoryStream(encryptedBytes)) {
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) {
                    using (var srDecrypt = new System.IO.StreamReader(csDecrypt)) {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }

    private void StartKeyRotation() {
        Task.Run(async () => {
            while (true) {
                await Task.Delay(KeyRotationIntervalSeconds * 1000);
                lock (_lockObject) {
                    _keyCache.Clear(); // Invalidate all keys
                }
            }
        });
    }

    private void LogError(Exception ex) {
        // Implement logging mechanism here
        Console.WriteLine($"Error: {ex.Message}");
    }
}

// Example usage:
