        executor.shutdown();
    }

    public static void processPayment(String cardNumber, double amount) throws Exception {
        if (!isValidLuhn(cardNumber)) {
            throw new IllegalArgumentException("Invalid card number");
        }

        // Simulate transaction logging
        logTransaction(cardNumber, amount);

        for (int attempt = 0; attempt < 5; attempt++) {
            try {
                executePayment(cardNumber, amount);
                break;
            } catch (TransientNetworkException e) {
                Thread.sleep((long) Math.pow(2, attempt) * 100); // Exponential backoff
                LOGGER.warning("Retrying transaction: " + attempt + " due to network error");
            }
        }

        validateFraud(cardNumber);
    }

    private static boolean isValidLuhn(String cardNumber) {
        int sum = 0;
        boolean alternate = false;

        for (int i = cardNumber.length() - 1; i >= 0; i--) {
            int n = Integer.parseInt(cardNumber.substring(i, i + 1));
            if (alternate) {
                n *= 2;
                if (n > 9) {
                    n -= 9;
                }
            }
            sum += n;
            alternate = !alternate;
        }

        return (sum % 10 == 0);
    }

    private static void logTransaction(String cardNumber, double amount) {
        // Placeholder for logging transaction to an audit log table
        LOGGER.info("Logging transaction: Card Number - " + cardNumber + ", Amount - " + amount);
    }

    private static void executePayment(String cardNumber, double amount) throws TransientNetworkException {
        // Simulated payment gateway integration
        if (Math.random() > 0.8) { // Randomly simulate a network issue
            throw new TransientNetworkException("Simulated network error");
        }
        LOGGER.info("Payment executed: " + cardNumber);
    }

    private static void validateFraud(String cardNumber) {
        // Placeholder for fraud detection logic
        if (cardNumber.startsWith("4000")) { // Example condition
            LOGGER.warning("Potential fraud detected on card number: " + cardNumber);
        }
    }
}

// Custom exception for transient network errors
class TransientNetworkException extends Exception {
    public TransientNetworkException(String message) {
        super(message);
    }
}
```

### Key Points:
- **Weaknesses String:** The `getWeaknessesString` function determines weaknesses using a switch statement based on the Pokemon's type.
- **Payment Processing:** Implements connection pooling, asynchronous processing with an executor service, Luhn validation for card numbers, and logging transactions to an audit log.
- **Retry Mechanism:** Includes exponential backoff strategy in case of transient network errors during payment execution.
- **Fraud Detection:** Basic fraud detection logic placeholder is provided.

Below is a modular C library implementation for converting a batch of image files into a single PDF document using a third-party imaging conversion tool. This example assumes you have access to a command-line tool like `ImageMagick` for image processing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 1024

typedef struct {
    char *input_dir;
    char *output_file;
    int dpi;
    void (*progress_callback)(int, int);
} ConversionConfig;

typedef struct {
    char *file_path;
    int index;
    ConversionConfig *config;
} ThreadData;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* convert_image_to_pdf(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    char command[BUFFER_SIZE];
    snprintf(command, BUFFER_SIZE, "convert -density %d \"%s\" -quality 100 page_%d.jpg",
             data->config->dpi, data->file_path, data->index);

    if (system(command) != 0) {
        fprintf(stderr, "Error converting image: %s\n", data->file_path);
        pthread_exit(NULL);
    }

    snprintf(command, BUFFER_SIZE, "pdfcrop page_%d.jpg page_%d_cropped.pdf",
             data->index, data->index);

    if (system(command) != 0) {
        fprintf(stderr, "Error cropping image: %s\n", data->file_path);
        pthread_exit(NULL);
    }

    pthread_mutex_lock(&lock);
    snprintf(command, BUFFER_SIZE, "pdfunite page_%d_cropped.pdf temp_combined.pdf",
             data->index);

    if (system(command) != 0) {
        fprintf(stderr, "Error uniting PDF: %s\n", data->file_path);
    } else {
        rename("temp_combined.pdf", data->config->output_file);
    }
    pthread_mutex_unlock(&lock);

    if (data->config->progress_callback) {
        data->config->progress_callback(data->index + 1, -1); // Assuming total is unknown
    }

    pthread_exit(NULL);
}

void* list_images(void *arg) {
    ConversionConfig *config = (ConversionConfig *)arg;
    DIR *dir;
    struct dirent *entry;
    char full_path[BUFFER_SIZE];
    int index = 0;

    dir = opendir(config->input_dir);
    if (!dir) {
        fprintf(stderr, "Could not open directory: %s\n", config->input_dir);
        pthread_exit(NULL);
    }

    while ((entry = readdir(dir)) != NULL) {
        char *file_name = entry->d_name;
        if (strstr(file_name, ".jpg") || strstr(file_name, ".jpeg") ||
            strstr(file_name, ".png") || strstr(file_name, ".gif")) {
            snprintf(full_path, BUFFER_SIZE, "%s/%s", config->input_dir, file_name);

            ThreadData *data = malloc(sizeof(ThreadData));
            data->file_path = strdup(full_path);
            data->index = index++;
            data->config = config;

            pthread_t thread;
            if (pthread_create(&thread, NULL, convert_image_to_pdf, data) != 0) {
                fprintf(stderr, "Failed to create thread for file: %s\n", full_path);
            } else {
                pthread_detach(thread);
            }
        }
    }

    closedir(dir);
    pthread_exit(NULL);
}

void convert_images_to_pdf(ConversionConfig *config) {
    pthread_t list_thread;
    if (pthread_create(&list_thread, NULL, list_images, config) != 0) {
        fprintf(stderr, "Failed to create directory listing thread\n");
    } else {
        pthread_join(list_thread, NULL);
    }
}

// Example usage
void progress_update(int current, int total) {
    printf("Progress: %d/%d images processed.\n", current, total);
}

int main() {
    ConversionConfig config;
    config.input_dir = "./images";
    config.output_file = "output.pdf";
    config.dpi = 300;
    config.progress_callback = progress_update;

    convert_images_to_pdf(&config);

    return 0;
}
```

### Key Points:
- **Thread Management**: Uses pthreads to handle concurrent image processing, limiting threads to `MAX_THREADS`.
- **Command Execution**: Utilizes system calls to execute ImageMagick commands for conversion and PDF manipulation.
- **Progress Callback**: Provides a mechanism to update progress via a callback function.
- **Error Handling**: Logs errors from command executions.
- **Resource Management**: Ensures proper memory allocation and deallocation.
- **Thread Safety**: Uses mutex locks where necessary to ensure thread safety.

### Notes:
- Ensure ImageMagick is installed and accessible in your environment.
- Adjust paths and commands as needed for different systems or tools.
- Extend error handling and logging as required for production use.

