### C Function with POSIX Semaphore

#### `convert_images_to_pdf.c`
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <time.h>

#define TIMEOUT 5 // seconds

void* convert_images_to_pdf(void *arg) {
    struct timespec ts;
    sem_t semaphore;

    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Semaphore initialization failed");
        return NULL;
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += TIMEOUT;

    // Attempt to acquire the semaphore with a timeout
    int sem_status = sem_timedwait(&semaphore, &ts);

    if (sem_status == 0) {
        // Successfully acquired the semaphore
        // Conversion logic here

        sem_post(&semaphore);
    } else {
        perror("Failed to acquire semaphore in time");
    }

    sem_destroy(&semaphore);
    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, convert_images_to_pdf, NULL) != 0) {
        perror("Thread creation failed");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    return EXIT_SUCCESS;
}
```

