### 2. C Function for Image to PDF Conversion

Here is a basic implementation of the `convert_images_to_pdf` function in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 100

void* convert_task(void *arg) {
    // Simulate image to PDF conversion task
    printf("Converting %s\n", (char*) arg);
    return NULL;
}

void convert_images_to_pdf(char **image_files, int num_files) {
    sem_t semaphore;
    pthread_t threads[MAX_THREADS];

    if(sem_init(&semaphore, 0, MAX_THREADS) != 0) {
        perror("Semaphore initialization failed");
        exit(1);
    }

    for(int i = 0; i < num_files; i++) {
        if(pthread_create(&threads[i % MAX_THREADS], NULL, convert_task, (void*) image_files[i])) {
            perror("Thread creation failed");
            exit(1);
        }

        sem_wait(&semaphore); // Wait for a slot to become available
    }

    for(int i = 0; i < num_files; i++) {
        pthread_join(threads[i % MAX_THREADS], NULL);
        sem_post(&semaphore); // Signal that the thread has finished
    }

    if(sem_destroy(&semaphore) != 0) {
        perror("Semaphore destruction failed");
        exit(1);
    }
}

int main() {
    char *image_files[] = {"image1.jpg", "image2.png", "image3.gif"};
    int num_files = sizeof(image_files) / sizeof(char*);

    convert_images_to_pdf(image_files, num_files);

    return 0;
}
```

