// Endpoint to calculate SHA-256 hash of a transaction record
app.post('/calculate-sha256', (req, res) => {
  const { transactionRecord } = req.body;

  if (!transactionRecord) {
    return res.status(400).json({ error: 'Transaction record is required' });
  }

  const hash = calculateSHA256(transactionRecord);
  res.json({ sha256Hash: hash });
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

module.exports = { app, processPaymentAndUpdateOrderStatus, calculateSHA256 };
