import threading
from functools import lru_cache
import requests

class ScriptLoader:
    def __init__(self):
        self.lock = threading.Lock()
        self.script_cache = {}
        self.load_status = {}

    @lru_cache(maxsize=128)
    def fetch_script(self, url):
        try:
            response = requests.get(url, timeout=5)
            if response.status_code == 200:
                return response.text
            else:
                raise Exception("Failed to fetch script.")
        except Exception as e:
            external_log(f"Error fetching {url}: {str(e)}")
            return None

    def generate_footer(self, scripts):
        footer_html = '<div id="footer"></div>'
        for priority, (script_url, fallback) in enumerate(sorted(scripts, key=lambda x: x[1])):
            with self.lock:
                if script_url not in self.script_cache:
                    content = self.fetch_script(script_url)
                    self.script_cache[script_url] = content
                    self.load_status[script_url] = 'loaded' if content else 'failed'

                cached_content = self.script_cache.get(script_url)

            if cached_content:
                footer_html += f'<script>{cached_content}</script>'
            elif fallback:
                footer_html += f'<noscript>{fallback}</noscript>'

        return footer_html

    def external_log(self, message):
        # Example log function for demonstration
        print(f"Log: {message}")

    @staticmethod
    def health_check():
        # Placeholder for health check API implementation
        pass

