```rust
use reqwest::{Client, Error as ReqwestError, RequestBuilder, header::HeaderMap};
use std::time::Duration;
use log::{info, error};

pub fn create_http_client_builder(
    url: &str,
    disable_cert_validation: bool,
    custom_headers: Option<HeaderMap>,
    timeout: Option<Duration>,
    allow_redirects: bool
) -> Result<RequestBuilder, ReqwestError> {
    let client = if disable_cert_validation {
        info!("Certificate validation is disabled.");
        Client::builder()
            .danger_accept_invalid_certs(true)
            .build()?
    } else {
        Client::new()
    };

    let request_builder = client
        .get(url)
        .map_err(|e| {
            error!("Failed to create initial request builder: {:?}", e);
            e
        });

    if let Some(timeout) = timeout {
        info!("Setting request timeout to {:?}.", timeout);
        request_builder.timeout(timeout).map_err(|e| {
            error!("Failed to set timeout: {:?}", e);
            e
        })?;
    }

    if let Some(headers) = custom_headers {
        info!("Applying custom headers.");
        request_builder.headers(headers).map_err(|e| {
            error!("Failed to apply headers: {:?}", e);
            e
        })?;
    }

    if allow_redirects {
        info!("Allowing redirects.");
        request_builder.follow_redirects(true).map_err(|e| {
            error!("Failed to set follow redirects: {:?}", e);
            e
        })?;
    }

    Ok(request_builder)
}

#[cfg(test)]
mod tests {
    use super::*;
    use reqwest::header::{HeaderMap, CONTENT_TYPE};
    use std::time::Duration;

    #[tokio::test]
    async fn test_create_http_client_builder() {
        let url = "https://httpbin.org/get";

        // Example usage
        if let Ok(mut builder) = create_http_client_builder(
            url,
            false,
            Some(HeaderMap::new().insert(CONTENT_TYPE, "application/json".parse().unwrap())),
            Some(Duration::from_secs(30)),
            true
        ) {
            match builder.send().await {
                Ok(response) => info!("Response status: {}", response.status()),
                Err(e) => error!("Request failed: {:?}", e),
            }
        }
    }
}
