// Function prototypes for fetching word list, retry logic, etc.
char** fetchWordListWithRetry(int *count);
void trimAndCapitalize(char* input, char** words, int count, size_t limit);

// Thread function to handle concurrent requests
void* dynamicTrimAndCapitalizeThread(void* arg) {
    char* input = (char*)arg;
    int wordCount;
    char** wordList = fetchWordListWithRetry(&wordCount);

    if (!input || !wordList) return NULL;

    size_t adjustedLimit = calculateAdjustedLimit(wordList, wordCount);
    char* result = malloc(adjustedLimit + 1);

    if (result) {
        trimAndCapitalize(input, wordList, wordCount, adjustedLimit);

        // Check length and handle NULL condition
        size_t len = strlen(result);
        if (len > adjustedLimit) {
            free(result);
            return NULL;
        }

        pthread_exit((void*) result);
    } else {
        pthread_exit(NULL);
    }

    free(wordList);  // Ensure proper deallocation after use
}

char* dynamicTrimAndCapitalize(char* input, size_t* limit) {
    pthread_t thread_id;
    void* result;

    if (!input || !limit) return NULL;

    pthread_create(&thread_id, NULL, dynamicTrimAndCapitalizeThread, (void*)input);
    pthread_join(thread_id, &result);

    char* finalResult = (char*) result;
    free(result);  // Clean up the memory allocated by the thread
    *limit = strlen(finalResult) + 1;

    return finalResult ? strdup(finalResult) : NULL;
}

// Example helper function to calculate adjusted limit
size_t calculateAdjustedLimit(char** words, int count) {
    size_t totalLength = 0;
    for (int i = 0; i < count; ++i) {
        totalLength += strlen(words[i]);
    }
    return *limit - totalLength / (count ? count : 1);
}

// Example function to trim and capitalize
void trimAndCapitalize(char* input, char** words, int count, size_t limit) {
