async function asyncArrayReduce(array, initialValue, accumulatorFn, config) {
    const { maxParallelOps = 2, throttleInterval = 1000, cachePolicy, authToken } = config;
    let cache = new Map();
    let semaphore = new Array(maxParallelOps).fill(true);

    async function reduceWithCache(index) {
        if (index >= array.length) return Promise.resolve(initialValue);

        await throttle(throttleInterval);
        const value = array[index];

        if (cachePolicy && cache.has(value)) {
            return cache.get(value);
        }

        for (; !semaphore.includes(true); ) {} // Wait for a slot
        semaphore[semaphore.indexOf(true)] = false;

        try {
            const result = await accumulatorFn(initialValue, value);

            if (config.progressCallback) config.progressCallback(index + 1, array.length, result);

            if (cachePolicy) cache.set(value, result);

            return reduceWithCache(index + 1).then(nextResult => {
                semaphore[semaphore.indexOf(false)] = true;
                return accumulatorFn(result, nextResult);
            });
        } catch (error) {
            semaphore[semaphore.indexOf(false)] = true;
            throw error;
        }
    }

    async function throttle(ms) {
        await new Promise(resolve => setTimeout(resolve, ms));
    }

    try {
        const finalValue = await reduceWithCache(0);
        return finalValue;
    } catch (error) {
        console.error("Error during reduction:", error.message);
        throw error;
    }
}
