        int damage;
        float cost;
        std::string specialEffect;
        int cooldown; // in seconds
    };

    std::vector<AttackProfile> getAttackProfiles() const {
        return { {30, 10.0f, "Fire", 5}, {50, 20.0f, "Ice", 10} };
    }
};

class Character {
public:
    float health;
    float energy;
    float distanceToEnemy;

    void updateState(float newHealth, float newEnergy, float newDistance) {
        std::lock_guard<std::mutex> lock(mutex_);
        health = newHealth;
        energy = newEnergy;
        distanceToEnemy = newDistance;
    }

private:
    mutable std::mutex mutex_;
};

class CombatEngine {
public:
    enum Action { ATTACK, DEFEND, RETREAT };

    Action selectAction(const Character& character, const ExternalData& data) {
        // Determine available attack profiles based on cooldowns and resources
        auto now = std::chrono::system_clock::now().time_since_epoch() / std::chrono::seconds(1);
        std::vector<ExternalData::AttackProfile> validProfiles;

        for (const auto& profile : data.getAttackProfiles()) {
            if (profile.cooldown > 0) continue; // Skip cooldowns
            if (character.energy < profile.cost) continue; // Check energy cost
            validProfiles.push_back(profile);
        }

        if (!validProfiles.empty()) {
            // Choose the best attack based on some criteria (e.g., damage, distance)
            auto it = std::max_element(validProfiles.begin(), validProfiles.end(),
                [&](const ExternalData::AttackProfile& a, const ExternalData::AttackProfile& b) {
                    return character.distanceToEnemy < 10 ? a.damage : a.specialEffect == "Ice" ? a.damage + 20 : a.damage;
                });
            if (it != validProfiles.end()) {
                // Simulate attack action
                std::cout << "Attacking with damage: " << it->damage << "\n";
                return ATTACK;
            }
        }

        // Default action when no attack is possible
        std::cout << "Performing default non-attack action\n";
        return DEFEND; // Or RETREAT, based on strategy
    }
};

void unitTests() {
    Character character;
    ExternalData data;

    CombatEngine engine;
    auto action = engine.selectAction(character, data);
    assert(action == CombatEngine::DEFEND || action == CombatEngine::ATTACK);

    character.updateState(100.0f, 50.0f, 5.0f); // Update state for testing
    action = engine.selectAction(character, data);
    assert(action != CombatEngine::RETREAT);

    std::cout << "All unit tests passed.\n";
}

int main() {
    unitTests();
    return 0;
}
