# json_base.py

import json
import yaml
from abc import ABC, abstractmethod
from threading import Lock
from typing import Type, Dict, Any
from time import time
import os
import importlib.util


class JSONBase(ABC):
    _registry = {}
    _lock = Lock()
    _last_access_times: Dict[str, float] = {}

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONBase':
        data = json.loads(json_str)
        # Add schema validation here if needed
        instance = cls()
        instance.__dict__.update(data)
        return instance

    @classmethod
    def register_factory(cls, subclass: Type['JSONBase'], factory_id: str):
        with cls._lock:
            cls._registry[factory_id] = subclass
            cls._last_access_times[factory_id] = time()

    @classmethod
    def create_instance(cls, factory_id: str, *args, **kwargs) -> 'JSONBase':
        with cls._lock:
            if factory_id not in cls._registry:
                raise ValueError(f"Factory ID '{factory_id}' not registered.")
            subclass = cls._registry[factory_id]
            instance = subclass(*args, **kwargs)
            cls._last_access_times[factory_id] = time()
            return instance

    @classmethod
    def discover_subclasses(cls, directory: str):
        for filename in os.listdir(directory):
            if filename.endswith(".py") and not filename.startswith("_"):
                module_name = filename[:-3]
                module_path = os.path.join(directory, filename)
                spec = importlib.util.spec_from_file_location(module_name, module_path)
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                for attr in dir(module):
                    obj = getattr(module, attr)
                    if isinstance(obj, type) and issubclass(obj, JSONBase) and obj != JSONBase:
                        cls.register_factory(obj, obj.__name__)

    @classmethod
    def load_yaml_registry(cls, file_path: str):
        with open(file_path, 'r') as file:
            yaml_data = yaml.safe_load(file)
            for factory_id, module_name in yaml_data.items():
                spec = importlib.util.find_spec(module_name)
                if spec is None:
                    continue
                module = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(module)
                for attr in dir(module):
                    obj = getattr(module, attr)
                    if isinstance(obj, type) and issubclass(obj, JSONBase) and obj != JSONBase:
                        cls.register_factory(obj, factory_id)

    @classmethod
    def save_registry(cls, file_path: str):
        with open(file_path, 'w') as file:
            yaml_data = {fid: subclass.__module__ for fid, subclass in cls._registry.items()}
            yaml.dump(yaml_data, file)

    @classmethod
    def cleanup_unused_factories(cls, timeout_seconds: int):
        current_time = time()
        with cls._lock:
            to_delete = [fid for fid, last_access in cls._last_access_times.items()
                         if current_time - last_access > timeout_seconds]
            for fid in to_delete:
                del cls._registry[fid]
                del cls._last_access_times[fid]


# subclasses.py

from json_base import JSONBase


class MySubClass(JSONBase):
    def __init__(self, name: str, value: int = 0):
        self.name = name
        self.value = value


# Example usage:

if __name__ == "__main__":
    # Discover subclasses in the current directory
    JSONBase.discover_subclasses(".")

    # Register factory functions from a YAML file (assumed to exist)
    JSONBase.load_yaml_registry("factories.yaml")

    # Create an instance using a registered factory ID
    instance = JSONBase.create_instance("MySubClass", "example", 42)

    # Convert instance to JSON string
    json_str = instance.to_json()
    print(json_str)

    # Parse JSON string back into an object
    parsed_instance = JSONBase.from_json(json_str)
    print(parsed_instance.__dict__)

    # Save the registry state to a file
    JSONBase.save_registry("factories.yaml")

    # Periodically cleanup unused factories
    JSONBase.cleanup_unused_factories(3600)  # Timeout of 1 hour
```

This code defines a base class `JSONBase` and implements subclass registration, JSON conversion, YAML integration for factory management, concurrency-safe registry operations, lazy loading, and periodic cleanup. It also demonstrates how to discover subclasses dynamically within a directory.

