# monitoring.py
import psutil
from threading import Thread
import time

class Monitor:
    def __init__(self, alert_thresholds):
        self.alert_thresholds = alert_thresholds

    def check_performance(self):
        while True:
            cpu_usage = psutil.cpu_percent(interval=1)
            memory_info = psutil.virtual_memory()

            if cpu_usage > self.alert_thresholds['cpu']:
                print(f"Alert: CPU usage high at {cpu_usage}%")

            if memory_info.percent > self.alert_thresholds['memory']:
                print(f"Alert: Memory usage high at {memory_info.percent}%")

            time.sleep(5)

def start_monitoring():
    thresholds = {'cpu': 80, 'memory': 75}
    monitor = Monitor(thresholds)
    Thread(target=monitor.check_performance).start()
