typedef struct {
    int workload;
    // Other fields
} Task;

void* process_task(void* task) {
    // Process the task
    return NULL;
}

void distribute_workload(Task** tasks, size_t count) {
    pthread_t threads[count];
    for (size_t i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, process_task, &tasks[i]);
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}
