```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.KafkaConsumer;

import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;

public class LogProcessor {

    private static final String KAFKA_TOPIC = "logs";
    private static final Properties kafkaProps = new Properties();
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private RedisCache redisCache; // Assume this is a custom implementation of Redis caching

    public LogProcessor(RedisCache cache) {
        this.redisCache = cache;
    }

    public void startProcessing(String[] metrics, Map<String, Double> thresholds, long retryBackoffMs) {
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(kafkaProps);
        consumer.subscribe(Collections.singletonList(KAFKA_TOPIC));

        while (true) {
            List<ConsumerRecord<String, String>> records = pollKafkaRecords(consumer);

            for (ConsumerRecord<String, String> record : records) {
                try {
                    JsonNode logData = objectMapper.readTree(record.value());
                    Map<String, Object> extractedMetrics = extractMetrics(logData, metrics);
                    if (!extractedMetrics.isEmpty()) {
                        saveToCache(extractedMetrics);
                        checkAlerts(extractedMetrics, thresholds);
                    }
                } catch (IOException e) {
                    handleMalformedLog(e, record);
                }
            }
        }
    }

    private List<ConsumerRecord<String, String>> pollKafkaRecords(KafkaConsumer<String, String> consumer) {
        int retries = 3;
        long backoff = 1000;

        while (retries > 0) {
            try {
                return consumer.poll(Duration.ofMillis(500)).records(KAFKA_TOPIC);
            } catch (Exception e) {
                handleFetchError(e);
                retries--;
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                backoff *= 2;
            }
        }

        return Collections.emptyList();
    }

    private Map<String, Object> extractMetrics(JsonNode logData, String[] metrics) throws IOException {
        Map<String, Object> extracted = new HashMap<>();
        for (String metric : metrics) {
            JsonNode value = logData.path(metric);
            if (!value.isMissingNode()) {
                extracted.put(metric, value.asText());
            }
        }
        return extracted;
    }

    private void saveToCache(Map<String, Object> metrics) {
        redisCache.save(metrics);
    }

    private void checkAlerts(Map<String, Object> metrics, Map<String, Double> thresholds) {
        for (Map.Entry<String, Double> threshold : thresholds.entrySet()) {
            if (metrics.containsKey(threshold.getKey())) {
                double metricValue = Double.parseDouble(metrics.get(threshold.getKey()).toString());
                if (metricValue > threshold.getValue()) {
                    triggerAlert(threshold.getKey(), metricValue);
                }
            }
        }
    }

    private void handleMalformedLog(Exception e, ConsumerRecord<String, String> record) {
        System.err.println("Malformed log detected at offset " + record.offset() + ": " + e.getMessage());
    }

    private void handleFetchError(Exception e) {
        System.err.println("Failed to fetch records: " + e.getMessage());
    }

    private void triggerAlert(String metric, double value) {
        System.out.println("ALERT! Metric " + metric + " has exceeded the threshold with value: " + value);
    }
}

class RedisCache {

    // Assume this class is implemented using Jedis or another Redis client
    public void save(Map<String, Object> metrics) {
        // Implement caching logic here
    }

    // Other methods for cache management...
}
```

