    LoggingServiceClient(const std::string& authToken) : authToken_(authToken) {}

    bool authenticate() { return !authToken_.empty(); }
    void shutdown() {}
private:
    std::string authToken_;
};

class RealTimeLogProcessor {
public:
    RealTimeLogProcessor(const std::string& authEndpoint)
        : authEndpoint_(authEndpoint), running_(false) {}

    ~RealTimeLogProcessor() { stopProcessing(); }

    bool initialize() {
        if (!authenticate()) return false;
        return true;
    }

    void startProcessing() {
        running_ = true;
        processingThread_ = std::thread(&RealTimeLogProcessor::processLogs, this);
    }

    void stopProcessing() {
        running_.store(false);
