// BibleTextAnalyzer.js

class BibleTextAnalyzer {
  constructor() {
    this.oldTestamentBooks = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/gi;
    this.newTestamentBooks = /(?:Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)/gi;
  }

  analyzeText(text) {
    if (typeof text !== 'string') throw new Error('Invalid input type');
    if (!text.trim()) throw new Error('Input string cannot be empty');

    const textCleaned = text.replace(/[^\w\s]/g, '').toLowerCase();
    const oldTestamentMatches = [...textCleaned.matchAll(this.oldTestamentBooks)];
    return {
      OldTestamentBooks: this.countMatches(oldTestamentMatches),
    };
  }

  countMatches(matches) {
    return matches.reduce((acc, match) => {
      acc[match[0]] = (acc[match[0]] || 0) + 1;
      return acc;
    }, {});
  }
}

