            int version = json.get("version").asInt();

            // Register factory based on ID and version
            PasswordFactory factory = createPasswordFactory(id, version);
            factoryRegistry.put(id + "_" + version, factory);

            return ResponseEntity.ok("Factory registered");
        } catch (Exception e) {
