```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256
#define LOG_FILE "log.txt"

typedef struct {
    char *extension;
    int digit_count;
} FileType;

// Supported file types with associated digit counts
FileType supported_file_types[] = {
    {"txt", 3},
    {"jpg", 3},
    {"png", 3},
    {"pdf", 5}
};

const size_t num_supported_file_types = sizeof(supported_file_types) / sizeof(FileType);

void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int is_valid_extension(const char *extension) {
    for (size_t i = 0; i < num_supported_file_types; ++i) {
        if (strcasecmp(extension, supported_file_types[i].extension) == 0) {
            return 1;
        }
    }
    return 0;
}

void get_file_extension(char *filename, char *ext) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) {
        strcpy(ext, "");
    } else {
        strncpy(ext, dot + 1, MAX_FILENAME_LENGTH);
    }
}

int determine_digit_count(const char *extension) {
    for (size_t i = 0; i < num_supported_file_types; ++i) {
        if (strcasecmp(extension, supported_file_types[i].extension) == 0) {
            return supported_file_types[i].digit_count;
        }
    }
    return -1;
}

char* modify_filename(const char *filename, int thread_safe) {
    char ext[MAX_FILENAME_LENGTH] = {0};
    get_file_extension(filename, ext);

    if (strlen(ext) == 0 || !is_valid_extension(ext)) {
        log_error("Invalid or unsupported file extension");
        return NULL;
    }

    int digit_count = determine_digit_count(ext);
    if (digit_count < 0) {
        log_error("Unsupported file type");
        return NULL;
    }

    char new_ext[MAX_FILENAME_LENGTH] = {0};
    snprintf(new_ext, sizeof(new_ext), "%03d.%s", rand() % 1000, ext);

    size_t filename_len = strlen(filename);
    size_t dot_pos = filename_len - strlen(ext) - 1;

    if (dot_pos < 0 || thread_safe != 0) {
        log_error("Error in processing file name");
        return NULL;
    }

    char *new_filename = malloc(filename_len + sizeof(new_ext) - strlen(ext) + 1);
    if (!new_filename) {
        log_error("Memory allocation failed");
        return NULL;
    }

    strncpy(new_filename, filename, dot_pos + 1);
    strcpy(&new_filename[dot_pos + 1], new_ext);

    return new_filename;
}

void free_resources(char *resource) {
    if (resource != NULL) {
        free(resource);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *new_filename = modify_filename(argv[1], 1); // Assuming thread-safe mode
    if (new_filename != NULL) {
        printf("New filename: %s\n", new_filename);
        free_resources(new_filename);
    } else {
        fprintf(stderr, "Failed to modify filename.\n");
    }

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Logging**: Errors are logged using the `log_error` function.
- **String Operations**: Uses `strrchr`, `snprintf`, and other functions for efficient string handling.
- **Error Handling**: Checks for invalid extensions, unsupported types, and memory allocation failures.
- **Modularity**: Functions like `get_file_extension`, `determine_digit_count`, and `modify_filename` encapsulate specific tasks.
- **Thread Safety**: A placeholder parameter `thread_safe` is included to illustrate where thread safety mechanisms would be implemented if needed.

