```python
import os
import json
from threading import Lock, RLock
from collections import defaultdict
import time
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes
from cryptography.fernet import Fernet
import logging

# Simulate external KMS and user authentication for illustration purposes.
def fetch_key_from_kms(encryption_type: str) -> bytes:
    # Mock fetching a key from an external KMS based on the encryption type
    if encryption_type == 'AES':
        return os.urandom(32)
    elif encryption_type == 'ChaCha20':
        return os.urandom(32)
    raise ValueError("Unsupported encryption type")

def authenticate_user(username: str, password: str) -> bool:
    # Mock user authentication process
    return username == "authorized_user" and password == "secure_password"

class SecureFileStorage:
    def __init__(self, config_path: str):
        self.config = self._load_config(config_path)
        self.encryption_type = self.config.get('encryption_algorithm', 'AES')
        self.key = fetch_key_from_kms(self.encryption_type)
        self.lock = RLock()
        self.rate_limiter = defaultdict(lambda: (0, time.time()))
        logging.basicConfig(level=logging.INFO)

    def _load_config(self, config_path: str) -> dict:
        with open(config_path, 'r') as f:
            return json.load(f)

    def encrypt_file(self, file_path: str, username: str, password: str):
        if not self._authenticate(username, password):
            logging.error("Unauthorized access attempt.")
            raise PermissionError("Authentication failed.")

        if not self._rate_limit_check():
            logging.warning("Rate limit exceeded.")
            raise Exception("Rate limit exceeded")

        with open(file_path, 'rb') as f:
            data = f.read()

        encrypted_data = self._encrypt(data)
        with open(file_path + '.enc', 'wb') as f:
            f.write(encrypted_data)

    def decrypt_file(self, file_path: str, username: str, password: str):
        if not self._authenticate(username, password):
            logging.error("Unauthorized access attempt.")
            raise PermissionError("Authentication failed.")

        with open(file_path, 'rb') as f:
            encrypted_data = f.read()

        decrypted_data = self._decrypt(encrypted_data)
        with open(file_path[:-4], 'wb') as f:  # Remove '.enc' extension
            f.write(decrypted_data)

    def _encrypt(self, data: bytes) -> bytes:
        if self.encryption_type == 'AES':
            iv = os.urandom(16)
            cipher = Cipher(algorithms.AES(self.key), modes.CFB(iv), backend=default_backend())
            encryptor = cipher.encryptor()
            return iv + encryptor.update(data) + encryptor.finalize()

        elif self.encryption_type == 'ChaCha20':
            nonce = os.urandom(12)
            cipher = Cipher(algorithms.ChaCha20(self.key, nonce), mode=None, backend=default_backend())
            encryptor = cipher.encryptor()
            return nonce + encryptor.update(data) + encryptor.finalize()

        raise ValueError("Unsupported encryption type")

    def _decrypt(self, encrypted_data: bytes) -> bytes:
        if self.encryption_type == 'AES':
            iv = encrypted_data[:16]
            cipher = Cipher(algorithms.AES(self.key), modes.CFB(iv), backend=default_backend())
            decryptor = cipher.decryptor()
            return decryptor.update(encrypted_data[16:]) + decryptor.finalize()

        elif self.encryption_type == 'ChaCha20':
            nonce = encrypted_data[:12]
            cipher = Cipher(algorithms.ChaCha20(self.key, nonce), mode=None, backend=default_backend())
            decryptor = cipher.decryptor()
            return decryptor.update(encrypted_data[12:]) + decryptor.finalize()

        raise ValueError("Unsupported encryption type")

    def _authenticate(self, username: str, password: str) -> bool:
        return authenticate_user(username, password)

    def _rate_limit_check(self):
        # Basic rate limiting logic for demonstration
        user_id = 'example_user'  # In a real scenario, derive this from session or token.
        limit, last_access_time = self.rate_limiter[user_id]

        current_time = time.time()
        if current_time - last_access_time < 1:  # Allow one operation per second
            if limit >= 5:
                return False
            else:
                self.rate_limiter[user_id] = (limit + 1, last_access_time)
                return True

        self.rate_limiter[user_id] = (0, current_time)
        return True

# Example of usage:
# storage = SecureFileStorage('config.json')
# storage.encrypt_file('sensitive_data.txt', 'authorized_user', 'secure_password')
# storage.decrypt_file('sensitive_data.txt.enc', 'authorized_user', 'secure_password')
```

This implementation provides a basic framework for secure file storage with configurable encryption algorithms, user authentication, and rate limiting. It ensures thread safety using a reentrant lock (`RLock`) to manage concurrent access. The use of an external KMS is simulated, as integration details vary depending on the specific service being used. Logging and performance monitoring are also included in this basic setup for tracing operations.

