S3_BUCKET_NAME = 'my-profile-images-bucket'
AWS_ACCESS_KEY_ID = os.getenv('AWS_ACCESS_KEY')
AWS_SECRET_ACCESS_KEY = os.getenv('AWS_SECRET_KEY')

# Initialize Redis connection
redis_cache = redis.StrictRedis(host=REDIS_HOST, port=REDIS_PORT)

# Initialize S3 client
s3_client = boto3.client(
    's3',
    aws_access_key_id=AWS_ACCESS_KEY_ID,
    aws_secret_access_key=AWS_SECRET_ACCESS_KEY
)

# LRU cache configuration
MAX_CACHE_SIZE = 1000

def fetch_image_from_s3(user_id, image_type):
    try:
        response = s3_client.get_object(Bucket=S3_BUCKET_NAME, Key=f'{user_id}/{image_type}')
        return Image.open(BytesIO(response['Body'].read()))
    except Exception as e:
        print(f"Error fetching from S3: {e}")
        return None

def cache_image(user_id, image_type, image):
    key = f"profile_images:{user_id}:{image_type}"
    redis_cache.set(key, image.tobytes(), ex=3600)  # Set expiration to 1 hour

@lru_cache(maxsize=MAX_CACHE_SIZE)
def get_cached_image(user_id, image_type):
    key = f"profile_images:{user_id}:{image_type}"
    cached_data = redis_cache.get(key)

    if cached_data:
        return Image.open(BytesIO(cached_data))

    # If not in cache, fetch from S3
    image = fetch_image_from_s3(user_id, image_type)
    if image:
        cache_image(user_id, image_type, image)

    return image

def invalidate_cache(user_id):
    keys_to_delete = redis_cache.keys(f"profile_images:{user_id}:*")
    for key in keys_to_delete:
        redis_cache.delete(key)

def resize_and_crop(image, size=(128, 128)):
    image.thumbnail(size, Image.ANTIALIAS)
    return image

@app.route('/profile_image/<int:user_id>/<image_type>', methods=['GET'])
def profile_image(user_id, image_type):
    if not request.args.get('authenticated_user') == user_id:
        abort(403)  # Forbidden

    image = get_cached_image(user_id, image_type)

    if image is None:
        return jsonify({'error': 'Image not found'}), 404

    width = int(request.args.get('width', 128))
    height = int(request.args.get('height', 128))
    image = resize_and_crop(image, (width, height))

    buffer = BytesIO()
    image.save(buffer, format="JPEG")
    buffer.seek(0)

    return send_file(buffer, mimetype='image/jpeg')

@app.route('/invalidate_cache/<int:user_id>', methods=['POST'])
def admin_invalidate_cache(user_id):
    if not request.headers.get('Authorization') == 'AdminToken':
        abort(403)  # Forbidden

    invalidate_cache(user_id)

    redis_cache.set(f"audit_log:{user_id}", "Cache invalidated", ex=3600)

    return jsonify({'status': 'success'}), 200

def background_image_update():
    while True:
        for user_id in redis_cache.keys('user:*'):
            for image_type in ['avatar', 'banner']:
                fetch_and_cache(user_id, image_type)

        # Sleep before next run
        time.sleep(86400)  # Run once a day

def fetch_and_cache(user_id, image_type):
    s3_metadata = s3_client.head_object(Bucket=S3_BUCKET_NAME, Key=f'{user_id}/{image_type}')

    cache_key = f"profile_images:{user_id}:{image_type}"
    cached_timestamp = redis_cache.get(f"{cache_key}:timestamp")

    if not cached_timestamp or float(s3_metadata['LastModified']) > float(cached_timestamp):
        image = fetch_image_from_s3(user_id, image_type)

        if image:
            cache_image(user_id, image_type, image)
            redis_cache.set(f"{cache_key}:timestamp", s3_metadata['LastModified'])

if __name__ == '__main__':
    thread = Thread(target=background_image_update)
    thread.daemon = True
    thread.start()

    app.run(debug=True, threaded=True)

