```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>

// Assume these are provided or implemented elsewhere
void parse_chunk(const char *chunk, size_t chunk_size, const char *rules);
int connect_to_database(void);
void store_metadata(int records, double processing_time);
void log_message(const char *message);

#define LOG_FILE "parsing.log"

void process_file(const char *input_filename, const char *output_filename, const char *rules, int chunk_size) {
    FILE *input_file = fopen(input_filename, "rb");
    if (!input_file) {
        log_message("Error: Could not open input file.");
        fprintf(stderr, "Error: Could not open input file (%s).\n", strerror(errno));
        return;
    }

    FILE *output_file = fopen(output_filename, "wb");
    if (!output_file) {
        log_message("Error: Could not create output file.");
        fprintf(stderr, "Error: Could not create output file (%s).\n", strerror(errno));
        fclose(input_file);
        return;
    }

    int db_connection = connect_to_database();
    if (db_connection < 0) {
        log_message("Error: Failed to connect to database.");
        fprintf(stderr, "Error: Failed to connect to database.\n");
        fclose(input_file);
        fclose(output_file);
        return;
    }

    char *buffer = malloc(chunk_size);
    if (!buffer) {
        log_message("Error: Memory allocation failed for buffer.");
        fprintf(stderr, "Error: Memory allocation failed for buffer.\n");
        fclose(input_file);
        fclose(output_file);
        // Assuming close_db_connection is implemented elsewhere
        // close_db_connection(db_connection);
        return;
    }

    size_t records = 0;
    clock_t start_time = clock();

    while (!feof(input_file)) {
        size_t bytes_read = fread(buffer, 1, chunk_size, input_file);
        if (bytes_read > 0) {
            parse_chunk(buffer, bytes_read, rules);
            records += 1; // Assume each read results in one record parsed
        }

        log_message("Processing progress update.");
    }

    double processing_time = ((double)(clock() - start_time)) / CLOCKS_PER_SEC;
    store_metadata(records, processing_time);

    log_message("Parsing completed successfully.");

    free(buffer);
    fclose(input_file);
    fclose(output_file);

    // Assuming close_db_connection is implemented elsewhere
    // close_db_connection(db_connection);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input file> <output file> <rules string> <chunk size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];
    const char *rules = argv[3];
    int chunk_size = atoi(argv[4]);

    if (chunk_size <= 0) {
        fprintf(stderr, "Error: Invalid chunk size.\n");
        return EXIT_FAILURE;
    }

    process_file(input_filename, output_filename, rules, chunk_size);

    return EXIT_SUCCESS;
}

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}
