import os
from PIL import Image
import threading
from concurrent.futures import ThreadPoolExecutor

def extract_metadata_from_jpeg(file_path):
    try:
        with Image.open(file_path) as img:
            metadata = {
                'file_name': os.path.basename(file_path),
                'dimensions': img.size,  # (width, height)
                'color_space': img.mode,
                'compression_method': 'JPEG'
            }
        return metadata
    except Exception as e:
        return {'error': str(e), 'file_name': file_path}

def extract_metadata_from_multiple_jpegs(file_paths):
    results = []

    def process_file(file_path):
        result = extract_metadata_from_jpeg(file_path)
        results.append(result)

    with ThreadPoolExecutor() as executor:
        executor.map(process_file, file_paths)

    return results

# Example usage
if __name__ == "__main__":
    jpeg_files = ['image1.jpg', 'image2.jpg']
    metadata_list = extract_metadata_from_multiple_jpegs(jpeg_files)
    for metadata in metadata_list:
        print(metadata)
```

This code uses the Pillow library to read JPEG files and extract metadata such as dimensions, color space, and compression method. It employs multi-threading via `ThreadPoolExecutor` to handle multiple JPEG files simultaneously. Errors during file reading are caught and reported within each thread's execution, ensuring that all file processing is completed before returning results.

