<?php

class SecurePasswordManager {
    private $hashedPassword;
    private $saltRounds = 12;

    public function __construct($characterSet) {
        if (!$this->validateCharacterSet($characterSet)) {
            throw new InvalidArgumentException("Invalid character set.");
        }
        $this->hashedPassword = null; // Initially no password
    }

    private function generateRandomString($length, $characterSet) {
        $validChars = [];
        $patternMap = [
            'uppercase' => '/[A-Z]/',
            'lowercase' => '/[a-z]/',
            'digit'     => '/\d/',
            'special'   => '/[^a-zA-Z\d]/'
        ];

        foreach ($characterSet as $char) {
            if (preg_match($patternMap['uppercase'], $char)) {
                $validChars[] = $char;
            } elseif (preg_match($patternMap['lowercase'], $char)) {
                $validChars[] = $char;
            } elseif (preg_match($patternMap['digit'], $char)) {
                $validChars[] = $char;
            } elseif (preg_match($patternMap['special'], $char)) {
                $validChars[] = $char;
            }
        }

        if (empty($validChars)) {
            throw new InvalidArgumentException("Character set must contain at least one uppercase, lowercase, digit, and special character.");
        }

        $result = '';
        for ($i = 0; $i < $length; $i++) {
            $randomChar = $validChars[array_rand($validChars)];
            $result .= $randomChar;
        }

        // Ensure all character types are included in the result
        foreach ($patternMap as $type => $pattern) {
            if (!preg_match($pattern, $result)) {
                $additionalChar = $characterSet[array_search(current(array_filter($characterSet, function($c) use ($pattern) { 
                    return preg_match($pattern, $c); 
                })), true)];
                $randomPosition = rand(0, strlen($result) - 1);
                $result[$randomPosition] = $additionalChar;
            }
        }

        return str_shuffle($result);
    }

    public function hashPassword($password) {
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRounds]);
    }

    public function checkPassword($password) {
        if ($this->hashedPassword === null) {
            return false;
        }

        return password_verify($password, $this->hashedPassword);
    }

