            'uppercase' => '/[A-Z]/',
            'lowercase' => '/[a-z]/',
            'digit'     => '/\d/',
            'special'   => '/[^a-zA-Z\d]/'
        ];

        foreach ($requiredPatterns as $pattern) {
            if (!preg_match($pattern, $characterSet)) {
                return false;
            }
        }

        // Add more validation for common patterns if needed
        return true;
    }

    public function setSaltRoundCount($rounds) {
