            throw new InvalidArgumentException("Invalid salt rounds. Must be between 4 and 31.");
        }
        $this->saltRounds = $rounds;
    }

    public function resetPassword() {
        if ($this->hashedPassword === null) {
            return; // No password to reset
        }

        $randomString = $this->generateRandomString(16, ['A'..'Z', 'a'..'z', '0'..'9', '!@#$%^&*']);
        $this->hashPassword($randomString);
