import java.io.*;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final String DB_URL = "jdbc:your_database_url";
    private static final String DB_USER = "your_db_user";
    private static final String DB_PASSWORD = "your_db_password";

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(4); // Optimized for concurrency
        try {
            File fileToDelete = new File("example.txt");
            deleteFile(fileToDelete);

            executeCommandSequence(executor, "mkdir exampleDir", 3);
            executeCommandSequence(executor, "touch exampleDir/exampleFile.txt", 3);
            executeCommandSequence(executor, "ls exampleDir", 3);
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
            }
        }
    }

    private static void deleteFile(File file) {
        if (file.exists()) {
            file.delete();
        }
    }

    private static void executeCommandSequence(ExecutorService executor, String command, int maxRetries) {
        executor.submit(() -> {
            for (int attempt = 0; attempt < maxRetries; attempt++) {
                try {
                    Process process = Runtime.getRuntime().exec(command);
                    logOutput(process.getInputStream(), "OUTPUT");
                    logOutput(process.getErrorStream(), "ERROR");

                    if (process.waitFor() == 0) {
                        storeResultInDB(command, true);
                        System.out.println("Command executed successfully: " + command);
                        return;
                    } else {
                        throw new IOException("Command execution failed.");
                    }
                } catch (IOException | InterruptedException e) {
                    System.err.println("Error executing command '" + command + "' on attempt " + (attempt + 1));
                    if (attempt < maxRetries - 1) {
                        try {
                            Thread.sleep(2000); // Retry delay
                        } catch (InterruptedException ie) {
                            Thread.currentThread().interrupt();
                        }
                    }
                }
            }
            storeResultInDB(command, false);
        });
    }

    private static void logOutput(InputStream stream, String type) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(type + ": " + line);
        }
        reader.close();
    }

    private static void storeResultInDB(String command, boolean success) {
        try (Connection connection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD)) {
            String sql = "INSERT INTO CommandResults (command, success) VALUES (?, ?)";
            PreparedStatement statement = connection.prepareStatement(sql);
            statement.setString(1, command);
            statement.setBoolean(2, success);
            statement.executeUpdate();
        } catch (SQLException e) {
            System.err.println("Failed to store result in database: " + e.getMessage());
        }
    }

    // Unit tests would be written using a testing framework like JUnit.
}
