// Rust code for RequestBuilder

use reqwest::{Client, Url};
use std::time::Duration;
use tokio;

pub struct RequestBuilder {
    client: Client,
}

impl RequestBuilder {
    pub fn new() -> Self {
        let mut builder = Client::builder()
            .danger_accept_invalid_certs(true) // For disabling certificate validation
            .timeout(Duration::from_secs(30)); // Set a custom timeout

        Self { client: builder.build().unwrap() }
    }

    pub async fn build_request(&self, url: &str, headers: Option<Vec<(String, String)>>, follow_redirects: bool) -> Result<(), reqwest::Error> {
        let mut request = self.client.get(url);

        if let Some(headers) = headers {
            for (key, value) in headers {
                request = request.header(key.as_str(), value.as_str());
            }
        }

        if !follow_redirects {
            request = request.redirect(reqwest::redirect::Policy::none());
        }

        let response = request.send().await?;

        println!("Status: {}", response.status());
        Ok(())
    }
}
