```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>

#define MAX_URL_LENGTH 256

typedef struct {
    char urls[MAX_URL_LENGTH][MAX_URL_LENGTH];
    int front;
    int rear;
    int size;
    sem_t full, empty;
    pthread_mutex_t mutex;
} ThreadSafeQueue;

ThreadSafeQueue* createQueue(int capacity) {
    ThreadSafeQueue *queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    if (!queue) return NULL;

    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
    sem_init(&queue->full, 0, 0);
    sem_init(&queue->empty, 0, capacity);
    pthread_mutex_init(&queue->mutex, NULL);

    return queue;
}

int enqueue(ThreadSafeQueue *queue, const char* url) {
    sem_wait(&queue->empty);
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == MAX_URL_LENGTH) {
        pthread_mutex_unlock(&queue->mutex);
        sem_post(&queue->full);
        return -1;
    }

    queue->rear = (queue->rear + 1) % MAX_URL_LENGTH;
    strncpy(queue->urls[queue->rear], url, MAX_URL_LENGTH);
    queue->size++;

    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->full);

    return 0;
}

int dequeue(ThreadSafeQueue *queue, char* url) {
    sem_wait(&queue->full);
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->mutex);
        sem_post(&queue->empty);
        return -1;
    }

    strncpy(url, queue->urls[queue->front], MAX_URL_LENGTH);
    queue->front = (queue->front + 1) % MAX_URL_LENGTH;
    queue->size--;

    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->empty);

    return 0;
}

int isQueueEmpty(ThreadSafeQueue *queue) {
    int empty = 0;
    pthread_mutex_lock(&queue->mutex);
    empty = (queue->size == 0);
    pthread_mutex_unlock(&queue->mutex);
    return empty;
}

void* producer(void* arg) {
    ThreadSafeQueue *queue = (ThreadSafeQueue*)arg;

    char urls[][MAX_URL_LENGTH] = {"http://example.com/file1", "http://example.com/file2"};
    int count = sizeof(urls) / sizeof(urls[0]);

    for (int i = 0; i < count; ++i) {
        if (enqueue(queue, urls[i]) == 0)
            printf("Produced: %s\n", urls[i]);
    }

    return NULL;
}

void* consumer(void* arg) {
    ThreadSafeQueue *queue = (ThreadSafeQueue*)arg;

    char url[MAX_URL_LENGTH];
    while (!isQueueEmpty(queue)) {
        if (dequeue(queue, url) == 0)
            printf("Consumed and uploaded: %s\n", url);
    }

    return NULL;
}

void cleanup(ThreadSafeQueue *queue) {
    sem_destroy(&queue->full);
    sem_destroy(&queue->empty);
    pthread_mutex_destroy(&queue->mutex);
    free(queue);
}

int main() {
    int numProducers = 2, numConsumers = 2;
    ThreadSafeQueue* queue = createQueue(MAX_URL_LENGTH);

    if (!queue) {
        fprintf(stderr, "Failed to create the queue\n");
        return EXIT_FAILURE;
    }

    pthread_t producers[numProducers], consumers[numConsumers];

    for (int i = 0; i < numProducers; ++i)
        pthread_create(&producers[i], NULL, producer, queue);

    for (int i = 0; i < numConsumers; ++i)
        pthread_create(&consumers[i], NULL, consumer, queue);

    for (int i = 0; i < numProducers; ++i)
        pthread_join(producers[i], NULL);

    for (int i = 0; i < numConsumers; ++i)
        pthread_join(consumers[i], NULL);

    cleanup(queue);

    return EXIT_SUCCESS;
}
