```java
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;
import javax.imageio.ImageIO;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;

public class ImageToPdfConverter {
    private static final int DEFAULT_DPI = 300;
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private ConcurrentHashMap<String, BufferedImage> imageCache = new ConcurrentHashMap<>();

    public int convertImagesToPDF(String inputDir, String outputFilePath, String pattern, ProgressCallback progressCallback, int dpi) throws IOException {
        if (!new File(inputDir).isDirectory()) throw new IllegalArgumentException("Invalid input directory.");

        List<File> imageFiles = listImageFiles(inputDir, pattern);
        if (imageFiles.isEmpty()) return 0;

        try (PDDocument document = new PDDocument()) {
            for (int i = 0; i < imageFiles.size(); i++) {
                executorService.submit(() -> processImage(imageFiles.get(i), document, dpi, progressCallback));
            }

            Future<?>[] futures = new Future[imageFiles.size()];
            for (int i = 0; i < imageFiles.size(); i++) {
                futures[i] = executorService.submit(() -> {
                    try {
                        Thread.sleep(100); // Simulate processing delay
                        document.addPage(new PDPage(PDRectangle.A4));
                    } catch (InterruptedException | IOException e) {
                        logError(e, "Failed to add page for image: " + imageFiles.get(i).getName());
                    }
                });
            }

            try {
                for (Future<?> future : futures) {
                    try {
                        future.get();
                    } catch (ExecutionException | InterruptedException e) {
                        logError(e, "Conversion error occurred.");
                    }
                }
                document.save(outputFilePath);
            } catch (IOException e) {
                logError(e, "Failed to save PDF document.");
                return imageFiles.size(); // Failed to save any images
            }

        } catch (Exception e) {
            logError(e, "Error during document processing.");
            return imageFiles.size();
        }

        int failedConversions = countUnsuccessfulConversions(futures);
        executorService.shutdown();

        progressCallback.onComplete("Conversion completed with " + failedConversions + " failures.");
        return failedConversions;
    }

    private List<File> listImageFiles(String inputDir, String pattern) throws IOException {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(Paths.get(inputDir), path -> 
            Pattern.compile(pattern, Pattern.CASE_INSENSITIVE).matcher(path.toString()).find() &&
            ImageIO.read(path.toFile()) != null)) {

            return stream.map(Path::toFile)
                         .stream()
                         .sorted(File::compareToIgnoreCase)
                         .collect(Collectors.toList());
        }
    }

    private void processImage(File imageFile, PDDocument document, int dpi, ProgressCallback progressCallback) {
        BufferedImage bufferedImage = loadImage(imageFile);
        if (bufferedImage == null) return;

        try {
            PDImageXObject pdImage = convertToPDImage(bufferedImage, dpi);
            PDPage page = new PDPage(new PDRectangle(pdImage.getWidth(), pdImage.getHeight()));
            document.addPage(page);

            try (PDDocument tempDoc = new PDDocument()) {
                PDPage tempPage = new PDPage(page.getMediaBox());
                tempDoc.addPage(tempPage);

                try (PDPageContentStream contentStream = new PDPageContentStream(tempDoc, tempPage)) {
                    contentStream.drawImage(pdImage, 0, 0);
                }
            }

            progressCallback.onProgress("Processed: " + imageFile.getName());

        } catch (IOException e) {
            logError(e, "Failed to process image: " + imageFile.getName());
        }
    }

    private BufferedImage loadImage(File imageFile) throws IOException {
        return imageCache.computeIfAbsent(imageFile.getPath(), k -> {
            try {
                return ImageIO.read(imageFile);
            } catch (IOException e) {
                logError(e, "Failed to load image: " + imageFile.getName());
                return null;
            }
        });
    }

    private PDImageXObject convertToPDImage(BufferedImage bufferedImage, int dpi) throws IOException {
        double scale = dpi / 72.0; // PDF standard DPI is 72
        BufferedImage scaledImage = new BufferedImage(
            (int)(bufferedImage.getWidth() * scale),
            (int)(bufferedImage.getHeight() * scale),
            BufferedImage.TYPE_INT_RGB);

        Graphics2D g2d = scaledImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2d.drawImage(bufferedImage, 0, 0, (int)(bufferedImage.getWidth() * scale), (int)(bufferedImage.getHeight() * scale), null);
        g2d.dispose();

        return PDImageXObject.createFromFileByContent(new File(imageFile.getName()), new PDDocument());
    }

    private int countUnsuccessfulConversions(Future<?>[] futures) {
        int failed = 0;
        for (Future<?> future : futures) {
            if (future.isCancelled() || future.isCompletedExceptionally()) {
                failed++;
            }
        }
        return failed;
    }

    private void logError(Exception e, String message) {
        System.err.println(message + " - " + e.getMessage());
        // Optionally implement a logging mechanism
    }

    public interface ProgressCallback {
        void onProgress(String status);
        void onComplete(String finalMessage);
    }

    public static void main(String[] args) throws IOException {
        ImageToPdfConverter converter = new ImageToPdfConverter();

        converter.convertImagesToPDF(
            "input/images", 
            "output/output.pdf",
            "*.jpg",
            (status) -> System.out.println("Progress: " + status),
            300
        );
    }
}
