const express = require('express');
const bodyParser = require('body-parser');
const session = require('express-session');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const WebSocket = require('ws');

const app = express();

// Middleware setup
app.use(helmet());
app.use(bodyParser.json());

// Rate Limiting
const apiLimiterGet = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 200,
  message: 'Too many requests from this IP, please try again after a minute',
});

const apiLimiterPostPut = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  message: 'Too many post/put requests from this IP, please try again after a minute',
});

app.use('/api', apiLimiterGet);
app.post('/api', apiLimiterPostPut);
app.put('/api', apiLimiterPostPut);

// Session Management
app.use(session({
  secret: 'your-secret-key',
  resave: false,
  saveUninitialized: true,
}));

// WebSockets for real-time updates
const wss = new WebSocket.Server({ noServer: true });

wss.on('connection', (ws) => {
  ws.on('message', (message) => {
    // Handle incoming messages and broadcast to all clients
    wss.clients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    });
  });
});

// Health Check Endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'OK' });
});

// Clinic Management Endpoints
const clinics = []; // In-memory store for clinic records

app.post('/api/clinics', (req, res) => {
  const { name, location } = req.body;
  // Validate and sanitize inputs here
  if (!name || !location) {
    return res.status(400).send('Invalid input');
  }
  const newClinic = { id: clinics.length + 1, name, location };
  clinics.push(newClinic);
  // Log the creation for audit
  console.log(`Clinic created by ${req.session.userId}:`, newClinic);
  res.status(201).send(newClinic);
});

app.put('/api/clinics/:id', (req, res) => {
  const { name, location } = req.body;
  // Validate and sanitize inputs here
  if (!name || !location) {
    return res.status(400).send('Invalid input');
  }
  const clinicIndex = clinics.findIndex(c => c.id == req.params.id);
  if (clinicIndex === -1) {
    return res.status(404).send('Clinic not found');
  }

  const oldData = { ...clinics[clinicIndex] };
  clinics[clinicIndex] = { id: clinics[clinicIndex].id, name, location };

  // Log the update for audit
  console.log(`Clinic updated by ${req.session.userId}:`, oldData, clinics[clinicIndex]);
  res.send(clinics[clinicIndex]);
});

app.delete('/api/clinics/:id', (req, res) => {
  const clinicIndex = clinics.findIndex(c => c.id == req.params.id);
  if (clinicIndex === -1) {
    return res.status(404).send('Clinic not found');
  }

  const removedClinic = clinics.splice(clinicIndex, 1)[0];
  // Log the deletion for audit
  console.log(`Clinic deleted by ${req.session.userId}:`, removedClinic);
  res.send({ message: 'Deleted successfully' });
});

// Authentication Middleware (simplified)
const authenticate = (req, res, next) => {
  if (!req.session.userId) {
    return res.status(403).send('Not authorized');
  }
  next();
};

app.use('/api/clinics', authenticate);

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

server.on('upgrade', (request, socket, head) => {
  wss.handleUpgrade(request, socket, head, ws => {
    wss.emit('connection', ws, request);
  });
});
