class EmailValidator {
    private static final Map<String, Pattern> domainRegexMap = new ConcurrentHashMap<>();
    private static final Map<String, String> domainApiUrls = new HashMap<>();

    // Load patterns and API URLs from a configuration file or database
    static {
        // Example configurations (should be loaded dynamically)
        domainRegexMap.put("example.com", Pattern.compile("^[a-zA-Z0-9._%+-]+@example\\.com$"));
        domainApiUrls.put("specialdomain.com", "https://api.specialdomain.com/validate");

        // Load other domains...
    }

    private final String domain;

    private EmailValidator(String domain) {
        this.domain = domain;
    }

    public static EmailValidator createForDomain(String domain) {
        return new EmailValidator(domain);
    }

    public boolean validateEmail(String email) throws IOException {
        Pattern pattern = domainRegexMap.get(domain);
        if (pattern != null && pattern.matcher(email).matches()) {
            return true;
        } else if (domainApiUrls.containsKey(domain)) {
            String apiUrl = domainApiUrls.get(domain);
            ExternalAPIResponse response = callExternalApi(apiUrl, email);
            System.out.println("API Response for " + email + ": " + response.getMessage());
            return response.isValid();
        }
        return false;
    }

    private ExternalAPIResponse callExternalApi(String apiUrl, String email) throws IOException {
        // Mock API interaction
        HttpURLConnection connection = (HttpURLConnection) new URL(apiUrl).openConnection();

        try {
            connection.setRequestMethod("POST");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);

            if (connection.getResponseCode() == 200) {
                JSONObject jsonResponse = new JSONObject("{ \"valid\": true, \"message\": \"Valid email\" }"); // Mock JSON response
                ExternalAPIResponse response = new ExternalAPIResponse();
                response.setValid(jsonResponse.getBoolean("valid"));
                response.setMessage(jsonResponse.getString("message"));
                return response;
            }
        } finally {
            connection.disconnect();
        }

        // Default failure response
        ExternalAPIResponse defaultResponse = new ExternalAPIResponse();
        defaultResponse.setValid(false);
        defaultResponse.setMessage("Failed to validate with API");
        return defaultResponse;
    }

