using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public interface ICspAdapter
{
    Task<(byte[] Key, byte[] Iv)> GetDecryptionKeyAndIvAsync(string contextId);
}

public class SecureMessageHandler
{
    private readonly ConcurrentDictionary<string, ICspAdapter> _cspAdapters = new();

    public SecureMessageHandler()
    {
        // Load configurations and instantiate adapters dynamically based on configuration settings.
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string contextId)
    {
        var (key, iv) = await GetKeyAndIvAsync(contextId);
        using var aes = Aes.Create();

        aes.Key = key;
        aes.IV = iv;

        var cipherTextBytes = Convert.FromBase64String(base64EncodedMessage);
        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        using (var ms = new MemoryStream(cipherTextBytes))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            using var sr = new StreamReader(cs);
            return await sr.ReadToEndAsync();
        }
    }

    public async Task<List<string>> DecryptMessagesAsync(List<string> base64EncodedMessages, string contextId)
    {
        var decryptionTasks = new List<Task<string>>();

        foreach (var message in base64EncodedMessages)
        {
            decryptionTasks.Add(DecryptMessageAsync(message, contextId));
        }

        return await Task.WhenAll(decryptionTasks);
    }

    private async Task<(byte[] Key, byte[] Iv)> GetKeyAndIvAsync(string contextId)
    {
        // Determine which CSP adapter to use based on the configuration or contextId.
        if (!_cspAdapters.TryGetValue(contextId, out var cspAdapter))
        {
            throw new InvalidOperationException("CSP Adapter not found for given context.");
        }

        return await cspAdapter.GetDecryptionKeyAndIvAsync(contextId);
    }

    public void RegisterCspAdapter(string contextId, ICspAdapter adapter)
    {
        if (!_cspAdapters.TryAdd(contextId, adapter))
        {
            throw new InvalidOperationException("A CSP Adapter for this context is already registered.");
        }
    }

    // Additional methods to load configurations, handle errors, logging, retry mechanisms, etc.
}

public class ExampleCspAdapter : ICspAdapter
{
