const axios = require('axios');

// Cache for storing type data to minimize API calls
let typeCache = {};

async function fetchPokemonData(pokemonId) {
    try {
        const response = await axios.get(`https://pokeapi.co/api/v2/pokemon/${pokemonId}`);
        return response.data;
    } catch (error) {
        throw new Error('Failed to fetch Pokemon data');
    }
}

function getPokemonWeakness(type) {
    switch (type.toLowerCase()) {
        case 'fire':
            return ['water', 'rock'];
        case 'water':
            return ['electric', 'grass'];
        case 'grass':
            return ['fire', 'ice', 'poison'];
        // Add additional types as necessary
        default:
            return [];
    }
}

async function asyncReduce(pokemons, reducer, initialValue) {
    let accumulator = initialValue;
    const progressLog = (message) => console.log(message);

    for (let i = 0; i < pokemons.length; i += 20) { // Pagination: Fetch in batches of 20
        const batch = pokemons.slice(i, i + 20);
        const tasks = batch.map(async (pokemonId) => {
            if (!typeCache[pokemonId]) {
                try {
                    const pokemonData = await fetchPokemonData(pokemonId);
                    typeCache[pokemonId] = pokemonData.types.map(t => t.type.name);
                    progressLog(`Fetched data for Pokemon ID: ${pokemonId}`);
                } catch (error) {
                    console.error(`Error fetching data for Pokemon ID ${pokemonId}:`, error.message);
                    return;
                }
            }

            const weaknesses = typeCache[pokemonId].map(getPokemonWeakness).flat();
            accumulator = reducer(accumulator, { name: pokemonData.name, level: pokemonData.level, weaknesses });
        });

        await Promise.all(tasks); // Wait for all tasks in the batch to complete
    }

    return accumulator;
}

// Example usage of asyncReduce with test cases and logging
