    const pokemons = [1, 4, 7, 25]; // Sample Pokemon IDs

    try {
        const result = await asyncReduce(
            pokemons,
            (acc, pokemon) => {
                if (!Array.isArray(acc.weaknesses)) acc.weaknesses = [];
                acc.weaknesses.push(...pokemon.weaknesses);
                return acc;
            },
            { weaknesses: [] }
        );
        console.log('Reduction result:', result);
    } catch (error) {
        console.error(error.message);
    }
})();

