```python
import json
from datetime import datetime
from uuid import UUID
from decimal import Decimal
from typing import Callable, Dict, Type

class JSONSerializable:
    _factory_registry: Dict[str, Callable[[], 'JSONSerializable']] = {}

    def __init__(self):
        self._data = {}

    def to_json(self) -> str:
        def custom_serializer(obj):
            if isinstance(obj, datetime):
                return {'__type__': 'datetime', 'value': obj.isoformat()}
            elif isinstance(obj, UUID):
                return {'__type__': 'uuid', 'value': str(obj)}
            elif isinstance(obj, Decimal):
                return {'__type__': 'decimal', 'value': str(obj)}
            raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")

        try:
            return json.dumps(self._data, default=custom_serializer)
        except (TypeError, ValueError) as e:
            raise RuntimeError("Error serializing object to JSON") from e

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONSerializable':
        def custom_decoder(dct):
            if '__type__' in dct:
                type_ = dct['__type__']
                value = dct['value']
                if type_ == 'datetime':
                    return datetime.fromisoformat(value)
                elif type_ == 'uuid':
                    return UUID(value)
                elif type_ == 'decimal':
                    return Decimal(value)
            return dct

        try:
            data = json.loads(json_str, object_hook=custom_decoder)
            instance = cls()
            instance._data = data
            return instance
        except (json.JSONDecodeError, ValueError) as e:
            raise RuntimeError("Error deserializing JSON to object") from e

    @classmethod
    def add_factory_function(cls, id_: str, factory_func: Callable[[], 'JSONSerializable']):
        if not callable(factory_func):
            raise ValueError("Factory function must be callable")

        cls._factory_registry[id_] = factory_func

    @classmethod
    def create_instance_from_id(cls, id_: str) -> 'JSONSerializable':
        if id_ not in cls._factory_registry:
            raise KeyError(f"No factory registered under ID: {id_}")

        try:
            return cls._factory_registry[id_]()
        except Exception as e:
            raise RuntimeError("Error creating instance from factory") from e

# Example subclass and usage
class CustomData(JSONSerializable):
    def __init__(self, custom_attr=None):
        super().__init__()
        self.custom_attr = custom_attr

def custom_data_factory():
    return CustomData(custom_attr="Example")

# Register the factory function
JSONSerializable.add_factory_function("custom_data", custom_data_factory)

# Create an instance using the registered factory
new_instance = JSONSerializable.create_instance_from_id("custom_data")
print(new_instance.to_json())  # Serializes with custom attributes

# Deserialize a JSON string into a CustomData object
json_str = '{"custom_attr": "Example"}'
deserialized_instance = JSONSerializable.from_json(json_str)
print(deserialized_instance.to_json())
```

```java
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import org.imgscalr.Scalr;

public class ImageCompressor {

    public static void optimizeImageCompression(String inputFilePath, String outputFilePath, long targetFileSizeBytes, double maxQualityReduction) {
        File inputFile = new File(inputFilePath);
        BufferedImage image = null;

        try {
            // Load the original image
            image = ImageIO.read(inputFile);

            if (image == null) {
                System.err.println("Error: Could not read input file.");
                return;
            }

            // Determine initial compression settings based on file format
            String formatName = inputFile.getName().substring(inputFilePath.lastIndexOf('.') + 1).toLowerCase();
            int quality = 100; // Start with maximum quality

            BufferedImage compressedImage = image;
            long currentFileSize = 0;
            boolean isCompressionSuccessful = false;

            while (quality > maxQualityReduction * 100 && !isCompressionSuccessful) {
                try {
                    // Perform compression
                    File tempOutputFile = new File("temp_output." + formatName);

                    if ("jpeg".equals(formatName)) {
                        compressedImage = Scalr.resize(image, Scalr.Method.ULTRA_QUALITY, Scalr.Mode.AUTOMATIC, Scalr.OP_ANTIALIAS);
                        ImageIO.write(compressedImage, "jpg", tempOutputFile);

                        // Simulate JPEG compression quality adjustment
                        ImageWriteParam param = ImageIO.getImageWritersByFormatName("jpeg").next().getDefaultWriteParam();
                        if (param.canWriteCompressionMode()) {
                            param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
                            param.setCompressionQuality(quality / 100.0f);
                            ImageIO.write(compressedImage, "jpg", tempOutputFile); // Re-write with adjusted quality
                        }
                    } else if ("png".equals(formatName)) {
                        compressedImage = Scalr.resize(image, Scalr.Method.ULTRA_QUALITY, Scalr.Mode.AUTOMATIC, Scalr.OP_ANTIALIAS);
                        ImageIO.write(compressedImage, "png", tempOutputFile);
                    }

                    // Check file size
                    currentFileSize = tempOutputFile.length();

                    if (currentFileSize <= targetFileSizeBytes) {
                        isCompressionSuccessful = true;

                        // Copy compressed image to final output location
                        ImageIO.write(compressedImage, formatName, new File(outputFilePath));
                        System.out.println("Compression successful. Output saved to: " + outputFilePath);
                    } else {
                        quality -= 5; // Reduce quality and try again
                    }
                } catch (IOException e) {
                    System.err.println("Error during image compression: " + e.getMessage());
                    break;
                } finally {
                    if (tempOutputFile.exists()) {
                        tempOutputFile.delete(); // Clean up temporary file
                    }
                }
            }

            if (!isCompressionSuccessful) {
                System.err.println("Failed to achieve the target file size with acceptable quality.");
            }

        } catch (IOException e) {
            System.err.println("Error reading image: " + e.getMessage());
        }
    }
}
```

This Java method `optimizeImageCompression` dynamically adjusts compression settings based on the input parameters. It handles JPEG and PNG formats specifically, leveraging external libraries like imgscalr for resizing. The method progressively reduces quality in steps until the target file size is reached or maximum allowable quality reduction is hit. Note that actual image processing complexity might require more sophisticated handling depending on use cases and desired performance characteristics.

Below is an example implementation of a semaphore management system in C, along with integration of OpenSSL for cryptographic operations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <openssl/evp.h>
#include <time.h>

#define MAX_SEMAPHORES 100
#define MAX_WORD_LENGTH 50

typedef struct {
    sem_t sem;
    int value;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
pthread_mutex_t mutexes[MAX_SEMAPHORES];
int semaphore_count = 0;

void log_operation(const char *operation, int index) {
    time_t now = time(NULL);
    printf("[%s] %s operation on semaphore %d\n", ctime(&now), operation, index);
}

Semaphore* create_semaphore(int initial_value) {
    if (semaphore_count >= MAX_SEMAPHORES) return NULL;

    Semaphore *sem = &semaphores[semaphore_count++];
    sem_init(&sem->sem, 0, initial_value);
    pthread_mutex_init(&mutexes[semaphore_count - 1], NULL);
    log_operation("Create", semaphore_count - 1);
    return sem;
}

void delete_semaphore(Semaphore *sem) {
    if (!sem) return;

    int index = (int)(sem - semaphores);
    pthread_mutex_lock(&mutexes[index]);
    sem_destroy(&sem->sem);
    pthread_mutex_unlock(&mutexes[index]);
    log_operation("Delete", index);
}

void increment_semaphore(Semaphore *sem) {
    if (!sem) return;

    int index = (int)(sem - semaphores);
    pthread_mutex_lock(&mutexes[index]);
    sem_post(&sem->sem);
    log_operation("Increment", index);
    pthread_mutex_unlock(&mutexes[index]);
}

void decrement_semaphore(Semaphore *sem) {
    if (!sem) return;

    int index = (int)(sem - semaphores);
    pthread_mutex_lock(&mutexes[index]);
    if (sem_trywait(&sem->sem) == 0) log_operation("Decrement", index);
    pthread_mutex_unlock(&mutexes[index]);
}

char* dynamicTrimAndCapitalize(const char *input, int size_limit) {
    static const char *word_list[] = {"the", "is", "at", "of", "on"};
    int word_count = sizeof(word_list) / sizeof(word_list[0]);

    char *trimmed_input = strdup(input);
    if (!trimmed_input) return NULL;

    // Trim words from beginning and end
    for (int i = 0; i < word_count; ++i) {
        char *start_pos = strstr(trimmed_input, word_list[i]);
        char *end_pos = strstr(start_pos ? start_pos : trimmed_input, " ");

        if (start_pos && end_pos) {
            int len = end_pos - start_pos;
            memmove(start_pos, end_pos + 1, strlen(end_pos + 1) + 1);
        }
    }

    // Capitalize first letter of each word
    char *word_start = trimmed_input;
    while (*trimmed_input) {
        if (isalpha(*trimmed_input)) {
            *trimmed_input = toupper(*trimmed_input);
            word_start = trimmed_input++;
            while (*trimmed_input && isalnum(*trimmed_input)) trimmed_input++;
        } else {
            ++trimmed_input;
        }
    }

    // Check size limit
    int final_length = strlen(trimmed_input) + 1; // +1 for null terminator
    if (final_length > size_limit) {
        free(trimmed_input);
        return NULL;
    }

    return trimmed_input;
}

EVP_CIPHER_CTX* perform_crypto_operation(const char *input, const char *option) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    // Example operation: AES encryption
    if (strcmp(option, "--encrypt") == 0) {
        const unsigned char key[] = "0123456789abcdef"; // Example key
        const unsigned char iv[] = "1234567890abcdef";  // Example IV

        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            fprintf(stderr, "Error initializing encryption\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }

        int len;
        unsigned char encrypted[1024];
        int ciphertext_len = 0;

        if (!EVP_EncryptUpdate(ctx, encrypted, &len, (unsigned char*)input, strlen(input))) {
            fprintf(stderr, "Error during encryption\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        ciphertext_len += len;

        if (!EVP_EncryptFinal_ex(ctx, encrypted + ciphertext_len, &len)) {
            fprintf(stderr, "Error finalizing encryption\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        ciphertext_len += len;

        printf("Encrypted data: %s\n", encrypted);
    } else if (strcmp(option, "--decrypt") == 0) {
        // Similar decryption logic
    }

    return ctx;
}

void cleanup() {
    for (int i = 0; i < semaphore_count; ++i) {
        delete_semaphore(&semaphores[i]);
    }
}

int main() {
    Semaphore *sem1 = create_semaphore(5);
    increment_semaphore(sem1);
    decrement_semaphore(sem1);

    char *result = dynamicTrimAndCapitalize("the quick brown fox jumps over the lazy dog", 50);
    if (result) printf("Result: %s\n", result);
    else printf("Exceeded size limit\n");

    EVP_CIPHER_CTX *ctx = perform_crypto_operation("Hello, World!", "--encrypt");
    if (!ctx) fprintf(stderr, "Crypto operation failed\n");

    cleanup();
    return 0;
}
```

### Key Points:
- **Semaphore Management**: Supports creation, deletion, incrementing, and decrementing of semaphores with logging.
- **Dynamic Trim and Capitalize**: Trims specified words and capitalizes the first letter of each word in a string.
- **Cryptographic Operation**: Uses OpenSSL for AES encryption as an example. Adjust key/IV as needed.
- **Error Handling**: Includes basic error handling for semaphore operations and cryptographic context creation.

Ensure to link with `-lpthread -lcrypto` when compiling due to pthreads and OpenSSL usage.

