  try {
    await axios.post(`https://thirdparty.api/projects/${projectId}/status`, { status });
  } catch (error) {
    console.error('Failed to update project status', error);
  }
}

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// listProjectsWorker.js

const { parentPort, workerData } = require('worker_threads');

async function fetchProjects(userId) {
  // Simulate fetching projects from a database
  return [{ id: '1', name: 'Project One' }, { id: '2', name: 'Project Two' }];
}

parentPort.on('message', async () => {
  const userId = workerData.userId;
  const projects = await fetchProjects(userId);
  parentPort.postMessage(projects);
});
