<?php

function manageClinicOperations($operation, $clinicData) {
    // Configuration
    $maxRate = 100;
    $rateLimitTimeFrame = 3600; // one hour in seconds
    $operationKey = $_SERVER['REMOTE_ADDR'] . '_' . $operation;

    // Rate Limiting
    $cacheKey = "rate_limit_{$operationKey}";
    $currentCount = apcu_fetch($cacheKey, $success);
    if ($success && $currentCount >= $maxRate) {
        throw new Exception("Rate limit exceeded. Try again later.");
    }
    apcu_store($cacheKey, 1 + ($currentCount ?? 0), $rateLimitTimeFrame);

    // Initialize Database Connection
    try {
        $pdo = new PDO('mysql:host=localhost;dbname=hospital', 'username', 'password');
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    } catch (PDOException $e) {
        handleError($e);
    }

    switch ($operation) {
        case 'create':
            createClinicRecord($pdo, $clinicData);
            break;
        case 'update':
            updateClinicRecord($pdo, $clinicData);
            break;
        case 'delete':
            deleteClinicRecord($pdo, $clinicData['id']);
            break;
    }
}

function createClinicRecord($pdo, $data) {
    try {
        $sql = "INSERT INTO clinics (name, status, location, capacity) VALUES (:name, :status, :location, :capacity)";
        $stmt = $pdo->prepare($sql);

        // Unique name check
        if (!isUniqueClinicName($pdo, $data['name'])) {
            throw new Exception("Clinic name must be unique.");
        }

        // Name length constraint
        if (strlen($data['name']) > 50) {
            throw new Exception("Clinic name cannot exceed 50 characters.");
        }

        $stmt->execute([
            ':name' => $data['name'],
            ':status' => $data['status'],
            ':location' => $data['location'],
            ':capacity' => $data['capacity']
        ]);

