```python
# csv_processor.py
import argparse
import pandas as pd

def process_csv(file_path, columns, separator, output_file, filter_condition):
    try:
        chunksize = 10000
        for chunk in pd.read_csv(file_path, sep=separator, usecols=columns, chunksize=chunksize):
            filtered_chunk = chunk.query(filter_condition)
            filtered_chunk.to_csv(output_file, mode='a', header=False, index=False)

    except Exception as e:
        print(f"Error processing {file_path}: {e}")

def main():
    parser = argparse.ArgumentParser(description="Process CSV files")
    parser.add_argument('files', nargs='+', help="CSV file paths")
    parser.add_argument('--columns', required=True, help="Columns to extract, comma-separated")
    parser.add_argument('--separator', default=',', help="Column separator character")
    parser.add_argument('--output', required=True, help="Output CSV file path")
    parser.add_argument('--filter', default='', help="Filter condition for data extraction")

    args = parser.parse_args()

    columns = args.columns.split(',')

    for file_path in args.files:
        process_csv(file_path, columns, args.separator, args.output, args.filter)

if __name__ == "__main__":
    main()
