const fs = require('fs');
const crypto = require('crypto');

class ProcessedTransactionResult {
    constructor(maxWeightedSum, transactionId) {
        this.maxWeightedSum = maxWeightedSum;
        this.transactionId = transactionId;
    }
}

async function asyncReduceArray(numbers, initialValue, callback) {
    let accumulatedValue = initialValue;
    const processedTransactions = [];
    let retryCount = 0;

    for (const number of numbers) {
        await new Promise((resolve, reject) => {
            try {
                // Simulate asynchronous processing with a timeout
                setTimeout(() => {
                    if (retryCount < 5) {
                        accumulatedValue = callback(accumulatedValue, number);
                        processedTransactions.push({ sum: accumulatedValue, id: number });
                        resolve();
                    } else {
                        reject(new Error('Maximum retries reached'));
                    }
                }, Math.random() * 1000); // Random delay to mimic async operations
            } catch (error) {
                retryCount++;
                const backoffTime = Math.pow(2, retryCount) * 100;
                console.error(`Retry ${retryCount}: ${error.message}. Retrying in ${backoffTime}ms...`);
                setTimeout(() => resolve(), backoffTime);
            }
        });
    }

    // Filter valid transactions and handle PEM creation
    const validTransactions = processedTransactions.filter(validateCertificate);
    if (validTransactions.length === 0) {
        throw new Error('No valid transactions found');
    }

    let pemContent = '';
    for (const transaction of validTransactions) {
        try {
            const privateKey = generatePrivateKey();
            const certificate = generateCertificate(transaction.id);

            // Validate and combine PEM files
            if (!validatePem(privateKey, certificate)) {
                throw new Error(`Invalid certificate for transaction ID: ${transaction.id}`);
            }

            pemContent += `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n`;
            pemContent += `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n`;

        } catch (error) {
            console.error(`Failed to process transaction ID: ${transaction.id}. Error: ${error.message}`);
        }
    }

    // Encode combined PEM in base64
    const encodedPem = Buffer.from(pemContent).toString('base64');

    // Find the maximum weighted sum and corresponding transaction ID
    let maxWeightedSum = -Infinity;
    let maxTransactionId = null;

    for (const transaction of validTransactions) {
        if (transaction.sum > maxWeightedSum) {
            maxWeightedSum = transaction.sum;
            maxTransactionId = transaction.id;
        }
    }

    return new ProcessedTransactionResult(maxWeightedSum, maxTransactionId);
}

