}

async fn manage_service_with_random_delay() {
    let mut rng = rand::thread_rng();
    loop {
        let delay = Duration::from_secs(rng.gen_range(1..=5));
        println!("Starting service...");
        std::thread::sleep(delay);
        println!("Stopping service...");

        // Dummy message sending
        println!("Message sent to messaging system: Service stopped.");

        let now = Instant::now();
        while now.elapsed() < delay {
            std::thread::yield_now();
        }
    }
}

#[tokio::main]
async fn main() {
    if let Err(e) = reqwest::block_on(main_logic()) {
        eprintln!("Error: {}", e);
    }
}

async fn main_logic() -> Result<(), Box<dyn std::error::Error>> {
    let client = disable_certificate_validation().await?;

    // Example file path
    let file_path = "example.txt";
    parse_file(file_path)?;

    // Example grammar
    let grammar = "S -> a S b | epsilon";
    let parsed_content = parse_file(file_path)?;
    let llvm_ir_code = generate_llvm_ir(&parsed_content);
