// Dynamic payment processor class
class DynamicPaymentProcessor {
private:
    Encryptor encryptor;
    ConnectionManager connManager;
    BackendFactory backendFactories[3];
    std::map<std::string, int> loadMetrics;

public:
    DynamicPaymentProcessor() {
        backendFactories[0] = [] { return std::make_shared<DatabaseBackend>(); };
        backendFactories[1] = [] { return std::make_shared<LogFileBackend>(); };
        backendFactories[2] = [] { return std::make_shared<ExternalAPIBackend>(); };
    }

    void processTransaction(const std::string& rawData) {
        auto encryptedData = encryptor.encrypt(rawData);
        int selectedBackendIndex = selectBackend();

        if (selectedBackendIndex < 0) {
            std::cerr << "All backends are unavailable.\n";
            return;
        }

        bool success = backendFactories[selectedBackendIndex]()->processTransaction(encryptedData);

        if (!success) {
            retryTransaction(selectedBackendIndex, encryptedData);
        }
    }

private:
    int selectBackend() {
        // Dynamic routing logic based on load and connectivity
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 2);

        for (int i = 0; i < 3; ++i) {
            int backendIndex = dis(gen);
            if (backendFactories[backendIndex]()->processTransaction("test")) { // Simulated check
                return backendIndex;
            }
        }

        return -1; // All failed
    }

    void retryTransaction(int index, const std::string& data) {
        int maxRetries = 3;
        for (int i = 0; i < maxRetries; ++i) {
            if (backendFactories[index]()->processTransaction(data)) {
                return;
            }
        }
        // Fallback to next available backend
        processTransactionFallback(index, data);
    }

    void processTransactionFallback(int failedIndex, const std::string& data) {
        for (int i = 0; i < 3; ++i) {
            if (i != failedIndex && backendFactories[i]()->processTransaction(data)) {
                return;
            }
        }
        std::cerr << "All fallback attempts failed.\n";
    }

    // Extendability with monitoring, logging, etc.
};

int main() {
    DynamicPaymentProcessor processor;

    std::vector<std::string> transactions = {"transaction1", "transaction2", "transaction3"};

    for (const auto& transaction : transactions) {
        processor.processTransaction(transaction);
    }

    return 0;
}
```

