struct Attack {
    std::string name;
    int cooldown;
    int damage;
    int lastUsedTime;

    bool isAvailable(int currentTime) const {
        return (currentTime - lastUsedTime) >= cooldown;
    }

    void use(int currentTime) {
        lastUsedTime = currentTime;
    }
};

class Character {
public:
    int health;
    int energy;
    float distanceToEnemy;
    int weaponDurability;

    std::vector<Attack> attacks;
    std::mutex mtx;

    // Initialize character with default values
    Character() : health(100), energy(50), distanceToEnemy(10.0f), weaponDurability(80) {
        attacks = {
            {"Slash", 5, 20, 0},
            {"Fireball", 10, 30, 0},
            {"Shield Bash", 7, 15, 0},
            {"Poison Dart", 12, 25, 0},
            {"Teleport Strike", 15, 40, 0}
        };
    }

    std::string selectAttack(int currentTime) {
        std::lock_guard<std::mutex> lock(mtx);

        WeatherResponse weather = WeatherService::getCurrentWeather();

        for (auto& attack : attacks) {
            if (attack.isAvailable(currentTime)) {
                // Adjust damage based on weather condition
                int effectiveDamage = attack.damage;
                if (weather.condition == "rainy" && attack.name == "Fireball") {
                    effectiveDamage -= 10; // Example adjustment
                }

                std::cout << "Using " << attack.name << " with damage: " << effectiveDamage << "\n";
                attack.use(currentTime);
                return attack.name;
            }
        }

        std::cout << "All attacks on cooldown, performing default action.\n";
        performDefaultAction();
        return "default_action";
    }

private:
    void performDefaultAction() {
        // Implement a non-attack action
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate action delay
        health -= 5; // Example penalty for doing nothing
    }
};

// Unit tests
void runTests() {
    Character char1;

    int currentTime = std::chrono::system_clock::now().time_since_epoch().count();

    std::cout << "Test 1: Select attack when some are available\n";
    char1.selectAttack(currentTime);

    currentTime += 6; // Simulate time passing
    std::cout << "\nTest 2: Select attack with cooldowns considered\n";
    char1.selectAttack(currentTime);

    std::this_thread::sleep_for(std::chrono::seconds(11)); // Wait for cooldowns

    currentTime = std::chrono::system_clock::now().time_since_epoch().count();
    std::cout << "\nTest 3: All attacks on cooldown\n";
    char1.selectAttack(currentTime);
}

int main() {
