#### `storage_manager.go`

```go
package storage_manager

import (
    "fmt"
    "sync"

    "github.com/pkg/errors"
)

type FileManager struct {
    dataStore map[string]string
    mu        sync.RWMutex
}

func NewFileManager() *FileManager {
    return &FileManager{
        dataStore: make(map[string]string),
    }
}

func (f *FileManager) StoreData(data string, key string) error {
    f.mu.Lock()
    defer f.mu.Unlock()

    // Simulated distributed file system logic
    if _, exists := f.dataStore[key]; exists {
        return errors.New("key already exists")
    }

    f.dataStore[key] = data

    return nil
}

func (f *FileManager) RetrieveData(key string) (string, error) {
    f.mu.RLock()
    defer f.mu.RUnlock()

    data, exists := f.dataStore[key]
    if !exists {
        return "", fmt.Errorf("key not found")
    }

    return data, nil
}
```

