```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DecryptionService
{
    private readonly string _key;
    private readonly byte[] _iv;

    public DecryptionService(string key, string iv)
    {
        if (string.IsNullOrWhiteSpace(key))
            throw new ArgumentException("Key cannot be null or empty", nameof(key));

        if (string.IsNullOrWhiteSpace(iv) || iv.Length != 8)
            throw new ArgumentException("IV must be exactly 8 bytes long", nameof(iv));

        _key = key;
        _iv = Encoding.UTF8.GetBytes(iv);
    }

    public string DecryptAndValidateMessage(string base64EncodedEncryptedMessage, string hmacProvided)
    {
        if (string.IsNullOrWhiteSpace(base64EncodedEncryptedMessage))
            throw new ArgumentException("Encrypted message cannot be null or empty", nameof(base64EncodedEncryptedMessage));

        if (string.IsNullOrWhiteSpace(hmacProvided))
            throw new ArgumentException("HMAC cannot be null or empty", nameof(hmacProvided));

        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
            string decryptedMessage = DecryptTripleDES(encryptedBytes);

            if (!ValidateHMAC(decryptedMessage, hmacProvided))
                throw new AuthenticationException("Failed HMAC validation");

            return decryptedMessage;
        }
        catch (FormatException)
        {
            throw new FormatException("Invalid Base64 encoding.");
        }
    }

    private string DecryptTripleDES(byte[] encryptedBytes)
    {
        using var tripleDes = TripleDESCryptoServiceProvider.Create();
        tripleDes.Key = Encoding.UTF8.GetBytes(_key);
        tripleDes.IV = _iv;
        tripleDes.Mode = CipherMode.CBC;

        using var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

        using var msDecrypt = new MemoryStream(encryptedBytes);
        using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
        using var srDecrypt = new StreamReader(csDecrypt);

        return srDecrypt.ReadToEnd();
    }

    private bool ValidateHMAC(string message, string hmacProvided)
    {
        using var sha256 = new HMACSHA256(Encoding.UTF8.GetBytes(_key));
        byte[] computedHash = sha256.ComputeHash(Encoding.UTF8.GetBytes(message));

        byte[] providedHashBytes = Convert.FromBase64String(hmacProvided);
        return StructuralComparisons.StructuralEqualityComparer.Equals(computedHash, providedHashBytes);
    }
}

public class AuthenticationException : Exception
{
    public AuthenticationException(string message) : base(message)
    {
    }
}
