                                    strlen(plaintext), ciphertext, key, iv)) {
        std::cout << "Encryption succeeded" << std::endl;

        if (SymmetricCipher::decryptAES(ciphertext, sizeof(ciphertext),
                                        decryptedtext, key, iv)) {
