    }
    free(wordList.words);

    pthread_exit(NULL);
}

// Function to handle multiple concurrent requests
void handleConcurrentRequests(char **inputs, size_t inputCount) {
    pthread_t threads[THREAD_POOL_SIZE];
    for (size_t i = 0; i < inputCount; ++i) {
        if (pthread_create(&threads[i % THREAD_POOL_SIZE], NULL, processRequest, inputs[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }

        // Wait to avoid overwhelming resources
        pthread_join(threads[i % THREAD_POOL_SIZE], NULL);
    }
}

