```javascript
class Semaphore {
    constructor(max) {
        this.max = max;
        this.current = 0;
        this.waiting = [];
    }

    async acquire() {
        if (this.current < this.max) {
            this.current++;
            return Promise.resolve();
        }

        return new Promise(resolve => {
            this.waiting.push(resolve);
        });
    }

    release() {
        if (this.waiting.length > 0) {
            const nextResolve = this.waiting.shift();
            nextResolve();
        } else {
            this.current--;
        }
    }
}

async function asyncArrayReduce(array, initialValue, callback, concurrencyLimit) {
    const semaphore = new Semaphore(concurrencyLimit);
    let accumulator = initialValue;
    let index = 0;

    async function processElement() {
        while (index < array.length) {
            await semaphore.acquire();

            const currentIndex = index++;
            try {
                const result = await mockApiCall(array[currentIndex]);
                accumulator = callback(accumulator, result);
            } catch (error) {
                console.error(`Error processing element at index ${currentIndex}:`, error);
                return { error: `Failed to process element at index ${currentIndex}`, details: error.message };
            } finally {
                semaphore.release();
            }
        }
    }

    const promises = Array.from({ length: concurrencyLimit }, () => processElement());

    try {
        await Promise.all(promises);
    } catch (error) {
        return { error: "Reduction failed due to an internal error", details: error.message };
    }

    return accumulator;
}

function mockApiCall(number) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            if (Math.random() < 0.95) { // Simulate a 5% failure rate
                resolve(number);
            } else {
                reject(new Error("Network or server error"));
            }
        }, Math.floor(Math.random() * 100)); // Random delay to simulate network latency
    });
}

// Example usage:
async function exampleUsage() {
    const numbers = Array.from({ length: 1000 }, (_, i) => i + 1);

    try {
        const result = await asyncArrayReduce(numbers, 0, (acc, val) => acc + val, 5);
        console.log("Result:", result);
    } catch (error) {
        console.error("Error in exampleUsage:", error);
    }
}

exampleUsage();

// Testing and validation
function testAsyncArrayReduce() {
    const numbers = [1, 2, 3, 4, 5];

    async function runTest() {
        const result = await asyncArrayReduce(numbers, 0, (acc, val) => acc + val, 2);

        if (result.error) {
            console.error("Test failed:", result);
        } else if (result !== 15) {
            console.error("Unexpected result:", result);
        } else {
            console.log("Test passed");
        }
    }

    runTest();
}

testAsyncArrayReduce();
