Below is a JavaScript implementation of the `renderFooterScripts` function, incorporating performance, scalability, error handling, and maintainability considerations as described:

```javascript
class LRUCache {
  constructor(maxSize = 100) {
    this.maxSize = maxSize;
    this.cache = new Map();
  }

  get(key) {
    if (!this.cache.has(key)) return null;
    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    this.cache.set(key, value);
  }
}

const scriptCache = new LRUCache(50);

async function fetchScriptContent(url) {
  try {
    const cachedContent = scriptCache.get(url);
    if (cachedContent) return cachedContent;

    const response = await fetch(url);
    if (!response.ok) throw new Error(`Network response was not ok for ${url}`);

    const content = await response.text();
    scriptCache.set(url, content);
    return content;
  } catch (error) {
    console.error(error.message);
    return null;
  }
}

function renderScriptTag(scriptObj, scriptContent) {
  if (!scriptObj.src || !scriptObj.type || !scriptObj.key) {
    console.warn(`Missing required properties for script key: ${scriptObj.key}`);
    return '';
  }

  const src = scriptObj.code ? `>${scriptContent}</script>` : `src="${scriptObj.src}"`;
  const priorityAttribute = scriptObj.priority ? `defer="true"` : '';

  return `<script type="${scriptObj.type}"${priorityAttribute} key="${scriptObj.key}" ${src}></script>`;
}

async function renderFooterScripts(scripts) {
  // Sort scripts by priority
  scripts.sort((a, b) => (b.priority || 0) - (a.priority || 0));

  const throttledFetch = async (urls) => {
    const results = [];
    const limit = 5;

    for (const url of urls) {
      if (results.length >= limit) {
        await new Promise((resolve) => setTimeout(resolve, 100)); // throttle
      }

      const content = scriptCache.get(url) || await fetchScriptContent(url);
      results.push(content ? { url, content } : null);
    }

    return results.filter(Boolean); // Remove null entries due to failed fetches
  };

  const urlsToFetch = scripts.filter(s => s.src).map(s => s.src);
  const fetchedScripts = await throttledFetch(urlsToFetch);

  const scriptTags = scripts.map(scriptObj => {
    if (scriptObj.code) return renderScriptTag(scriptObj, scriptObj.code);

    const fetched = fetchedScripts.find(f => f.url === scriptObj.src);
    return renderScriptTag(scriptObj, fetched ? fetched.content : '');
  });

  return scriptTags.filter(tag => tag).join('');
}

// Example usage
(async () => {
  const scripts = [
    { src: 'https://external-script.com/script.js', type: 'text/javascript', key: 'external-script', priority: 1 },
    { code: '<script>alert("Inline Script")</script>', type: 'text/javascript', key: 'inline-script', priority: 2 }
  ];

  const footerContent = await renderFooterScripts(scripts);
  console.log(footerContent);
})();
```

### Explanation:

- **LRUCache Class**: Implements a simple LRU caching mechanism to manage script content.
- **fetchScriptContent Function**: Fetches script content from an external URL and caches it. Handles network errors gracefully.
- **renderScriptTag Function**: Creates a `<script>` tag string, handling both inline scripts (`code` property) and external scripts (`src` property).
- **throttledFetch Function**: Throttles the number of concurrent fetch requests to 5 to avoid overwhelming the server.
- **renderFooterScripts Function**: Main function that sorts scripts by priority, throttles fetches, and renders them as script tags. It ensures robust error handling for missing properties and network errors. 

This modular approach allows easy extension and maintenance while ensuring performance and scalability.

```rust
use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use log::{info, warn, error};
use env_logger;
use std::thread;

lazy_static::lazy_static! {
    static ref CACHE_DIR: Mutex<Option<PathBuf>> = Mutex::new(None);
}

fn manage_cache_directory(cache_dir_name: &str, cleanup_interval_secs: u64) -> io::Result<()> {
    let cache_path = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap_or_else(|_| "."))? / cache_dir_name;

    // Atomic check and creation of the directory
    {
        let mut cache_guard = CACHE_DIR.lock().unwrap();
        if *cache_guard.is_none() || !fs::metadata(&cache_path).is_ok() {
            match fs::create_dir_all(&cache_path) {
                Ok(_) => {
                    info!("Cache directory created at {:?}", cache_path);
                }
                Err(e) => error!("Failed to create cache directory: {}", e),
            }
        }

        *cache_guard = Some(cache_path.clone());
    }

    // Set environment variable atomically
    env::set_var("CACHE_DIR", cache_path.to_str().unwrap());

    // Start a cleanup thread
    let cleanup_interval = Duration::new(cleanup_interval_secs, 0);
    let cleanup_thread = thread::spawn(move || {
        loop {
            thread::sleep(cleanup_interval);

            if let Ok(entries) = fs::read_dir(&cache_path) {
                let mut entries: Vec<_> = entries.filter_map(Result::ok).collect();
                entries.sort_by_key(|entry| entry.metadata().and_then(|metadata| metadata.modified()).unwrap_or(UNIX_EPOCH));

                // Retain only the most recent N files (e.g., keep 100)
                const KEEP_COUNT: usize = 100;
                let excess_count = entries.len() - KEEP_COUNT;

                if excess_count > 0 {
                    for entry in &entries[..excess_count] {
                        match fs::remove_file(entry.path()) {
                            Ok(_) => info!("Deleted old cache file {:?}", entry.path()),
                            Err(e) => warn!("Failed to delete old cache file {:?}: {}", entry.path(), e),
                        }
                    }
                }

                // Log cleanup activity
                info!("Cleanup completed. {} files retained.", KEEP_COUNT);
            } else {
                error!("Failed to read directory for cleanup: {:?}", cache_path);
            }
        }
    });

    Ok(())
}

fn main() -> io::Result<()> {
    env_logger::init();

    let args: Vec<String> = std::env::args().collect();

    // Example: ./program CACHE_DIR_NAME CLEANUP_INTERVAL_IN_SECONDS
    if args.len() < 3 {
        eprintln!("Usage: {} <CACHE_DIR_NAME> <CLEANUP_INTERVAL_IN_SECONDS>", args[0]);
        return Ok(());
    }

    let cache_dir_name = &args[1];
    let cleanup_interval_secs: u64 = args[2].parse().expect("Invalid interval duration");

    manage_cache_directory(cache_dir_name, cleanup_interval_secs)
}
```

