using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class ThreadSafeFileUploadManager : IDisposable
{
    private readonly IConfigurationProvider _configProvider;
    private readonly IKeyManagementService _keyManagementService;
    private readonly ICspClientFactory _cspClientFactory;
    private readonly SemaphoreSlim _rateLimiter;
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> _keyCache = new();
    private readonly ReaderWriterLockSlim _cacheLock = new();

    public ThreadSafeFileUploadManager(IConfigurationProvider configProvider, IKeyManagementService keyManagementService, ICspClientFactory cspClientFactory, int maxConcurrentRequests)
    {
        _configProvider = configProvider ?? throw new ArgumentNullException(nameof(configProvider));
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
        _cspClientFactory = cspClientFactory ?? throw new ArgumentNullException(nameof(cspClientFactory));
        _rateLimiter = new SemaphoreSlim(maxConcurrentRequests);
    }

    public async Task<string> DecryptMessageAsync(string encodedMessage, string sourceIdentifier, int clearanceLevel, CancellationToken cancellationToken)
    {
        await _rateLimiter.WaitAsync(cancellationToken);

        try
        {
            if (!ValidateMessage(encodedMessage))
                return "Invalid message format.";

            var (key, iv) = await GetKeyAndIVAsync(sourceIdentifier, clearanceLevel);

            // Choose encryption method dynamically based on configuration.
            string encryptionMethod = _configProvider.GetEncryptionMethod();
            switch (encryptionMethod)
            {
                case "TripleDES":
                    return DecryptWithTripleDES(encodedMessage, key, iv);

                case "AES":
                    return DecryptWithAES(encodedMessage, key, iv);

                case "RSA":
                    return DecryptWithRSA(encodedMessage, key); // RSA does not use IV

                default:
                    throw new NotSupportedException("Unsupported encryption method.");
            }
        }
        catch (Exception ex)
        {
            LogError(ex, sourceIdentifier, clearanceLevel);
            throw;
        }
        finally
        {
            _rateLimiter.Release();
        }
    }

    public string DecryptMessage(string encodedMessage, string sourceIdentifier, int clearanceLevel)
    {
        return Task.Run(async () => await DecryptMessageAsync(encodedMessage, sourceIdentifier, clearanceLevel, CancellationToken.None)).GetAwaiter().GetResult();
    }

    private async Task<(byte[] Key, byte[] IV)> GetKeyAndIVAsync(string sourceIdentifier, int clearanceLevel)
    {
        if (_keyCache.TryGetValue(sourceIdentifier, out var cachedKeyInfo))
            return (cachedKeyInfo.Key, cachedKeyInfo.IV);

        using (_cacheLock.EnterWriteLock())
        {
            // Double-check locking
            if (_keyCache.TryGetValue(sourceIdentifier, out cachedKeyInfo))
                return (cachedKeyInfo.Key, cachedKeyInfo.IV);

            var cspClient = _cspClientFactory.CreateCSPClient(_configProvider);
            var keyId = _keyManagementService.GetKeyIdForLevel(clearanceLevel);
            var (key, iv) = await cspClient.FetchKeyAsync(keyId, sourceIdentifier);

            _keyCache[sourceIdentifier] = (key, iv);

            return (key, iv);
        }
    }

