$app->post('/user', function (Request $request, Response $response) use ($conn) {
    $data = json_decode($request->getBody()->getContents(), true);

    // Validate email uniqueness and verify via third-party service
    if (!$this->isEmailUniqueAndVerified($data['email'])) {
        return $response->withJson([
            "status" => "error",
