        ], 400);
    }

    // Implement MFA (e.g., send SMS/email for verification)
    if (!$this->verifyMfa($data['email'])) {
        return $response->withJson([
            "status" => "error",
            "message" => "Multi-factor authentication failed",
            "data" => null
        ], 400);
    }

    // Insert user into database
    $stmt = $conn->prepare("INSERT INTO users (name, email, password, role) VALUES (?, ?, ?, ?)");
    $stmt->execute([$data['name'], $data['email'], password_hash($data['password'], PASSWORD_BCRYPT), 'user']);

    return $response->withJson([
        "status" => "success",
        "message" -> "User account created successfully",
        "data" => [
            "id" => $conn->lastInsertId(),
            "name" => $data['name'],
            "email" => $data['email'],
            "role" => 'user'
        ]
    ]);
});

// Route for updating a user account
$app->put('/user/{id}', function (Request $request, Response $response, array $args) use ($conn) {
    $userId = $args['id'];
    $data = json_decode($request->getBody()->getContents(), true);

