// Utility function for asynchronous fetch operation with error handling
async function fetchDataFromDatabase(query) {
    try {
        // Simulate a fetch call to an external database
        const response = await fetch(`https://api.example.com/data?query=${query}`);
        if (!response.ok) throw new Error('Network response was not ok');
        return await response.json();
    } catch (error) {
        console.error("Fetch error:", error.message);
        throw new Error("Failed to fetch data from database");
    }
}

// Recursive function for asynchronous hierarchical reduce with performance optimization
async function asyncHierarchicalReduce(array, callback, initialValue = 0) {
    try {
        const flattenedArray = await flattenArrayAsync(array);

        // Use parallel processing where applicable (e.g., using Promise.all)
        const partialResults = await Promise.all(flattenedArray.map(async (value, index) => {
            if (typeof value !== 'number' || !isFinite(value)) {
                throw new TypeError(`Invalid numeric value at position ${index}`);
            }
            return callback(initialValue, value);
        }));

        // Final reduction step
        const finalResult = partialResults.reduce((acc, curr) => callback(acc, curr), initialValue);

        return finalResult;
    } catch (error) {
        console.error("Reduction error:", error.message);
        throw new Error(`Error during asynchronous reduce operation: ${error.message}`);
    }
}

// Asynchronous function to flatten the array
async function* flattenArrayAsync(array) {
    for (const element of array) {
        if (Array.isArray(element)) {
            yield* await flattenArrayAsync(element); // Recursively yield flattened elements
        } else {
            yield element;
        }
    }
}

// Example callback function for reduction operation
function sumReducer(accumulator, currentValue) {
    return accumulator + currentValue;
}

// Test cases
(async () => {
    try {
        const result = await asyncHierarchicalReduce([1, [2, 3], [[4]], 5], sumReducer);
        console.log("Reduction result:", result); // Expected: 15

        // Testing with non-numeric value handling
        const invalidResult = await asyncHierarchicalReduce([1, 'a', [2, 3]], sumReducer).catch(err => err.message);
        console.log(invalidResult); // Expected error message

        // Testing fetch from database and processing large nested arrays
        const fetchedData = await fetchDataFromDatabase('largeDataset');
        if (fetchedData) {
            const largeArrayResult = await asyncHierarchicalReduce(fetchedData, sumReducer).catch(err => err.message);
            console.log(largeArrayResult); // Expected result or error message
        }
    } catch (err) {
        console.error("Unhandled error:", err.message);
    }
})();
