class ReligiousTextAnalyzer {
  constructor(customRegex = {}) {
    this.bibleRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/i;
    this.quranRegex = /(?:Al-Fatiha|Al-Baqara|Aal-E-Imran|An-Nisa|Al-Ma'idah|Al-An'am|Al-A'raf|Anaam|At-Tawbah|Yunus|Hud|Yusuf|Ar-Ra'd|Ibrahim|Al-Hijr|An-Nahl|Al-Isra'|Al-Kahf|Maryam|Ta-Ha|Al-Anbiya|Al-Hajj|Al-Mu'minun|An-Nur|Al-Furqan|Ash-Shuraa|Az-Zukhruf|Ad-Dhuha|At-Tin|Al-Alaq|Al-Qadr|Al-Bayyina|Az-Zalzala|Abasa|At-Takwir|Al-Infitar|Al-Mutaffifin|Al-Inshiqaq|Al-Burooj|At-Taariq|Al-A'la|Al-Ghashiya|Al-Fajr|Adh-Dhariyat|Ash-Shams|Al-Lail|Ad-duha|Ash-Sharh|At-Tin|Al-Alaq)/i;
    this.torahRegex = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy)/i;
    this.vedasRegex = /(?:Rig Veda|Majabharata,Yajur Veda,Sama Veda,Atharva Veda)/i;

    this.regexMap = {
      Bible: this.bibleRegex,
      Quran: this.quranRegex,
      Torah: this.torahRegex,
      Vedas: this.vedasRegex,
    };

    Object.keys(customRegex).forEach((key) => {
      this.regexMap[key] = new RegExp(customRegex[key], 'i');
    });

    this.bookFrequency = {};
    this.cache = new Map();
    this.apiServiceUrl = "https://api.religioustexts.example.com/verify";
    this.logCache = new Map();
  }

  analyzeText(text) {
    if (typeof text !== 'string' || !text.trim()) {
      throw new Error("Invalid input: Text must be a non-empty string.");
    }

    if (this.cache.has(text)) {
      return this.cache.get(text);
    }

    const results = {};
    for (const [religion, regex] of Object.entries(this.regexMap)) {
      const matches = text.match(regex) || [];
      results[religion] = [...new Set(matches)].map((book) => book.toLowerCase());
      results[religion].forEach((book) => {
        this.bookFrequency[book] = (this.bookFrequency[book] || 0) + 1;
      });
    }

    this.cache.set(text, results);
    return results;
  }

  categorizeBooks(extractedBooks) {
    const categorizedResults = {};
    extractedBooks.forEach((book) => {
      for (const [religion, regex] of Object.entries(this.regexMap)) {
        if (regex.test(book)) {
          categorizedResults[book] = religion;
          break;
        }
      }
    });
    return categorizedResults;
  }

  verifyWithAPI(books) {
    const verificationPromises = books.map((book) => 
      fetch(`${this.apiServiceUrl}?query=${encodeURIComponent(book)}`)
        .then(response => response.json())
        .catch(() => ({ verified: false }))
    );
    return Promise.all(verificationPromises);
  }

  generateReport() {
    const reportData = Object.entries(this.bookFrequency)
      .sort((a, b) => b[1] - a[1])
      .reduce((acc, [book, count]) => {
        acc[book] = { frequency: count };
        return acc;
      }, {});

    return {
      summary: reportData,
      exportToCSV() {
        const csvContent = `Book,Frequency\n${Object.entries(reportData)
          .map(([book, data]) => `${book},${data.frequency}`)
          .join("\n")}`;
        this.exportToFile(csvContent, "report.csv");
      },
      exportToJSON() {
        this.exportToFile(JSON.stringify(reportData), "report.json", "application/json");
      }
    };
  }

  exportToFile(content, filename, contentType = 'text/plain') {
    const blob = new Blob([content], { type: contentType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

  getFactoryFunction(id) {
    if (!this.registry) this.registry = {};
    return this.registry[id] || (() => null);
  }
}

async function runTests(moduleLabel, testLabels, testFunctions) {
  try {
    const module = require(moduleLabel);

    for (const [label, func] of Object.entries(testFunctions)) {
      console.log(`Running test: ${label}`);
      await func();
      blueslip.reset(); // Assume blueslip is a globally available mocking library
    }
  } catch (error) {
    console.error("Test failed:", error);
  } finally {
    if (blueslip) blueslip.reset();
  }

  console.log("All tests completed.");
}
