const axios = require('axios');
const NodeCache = require('node-cache');
const { Queue } = require('bullmq');
const { createLogger, format, transports } = require('winston');
const moment = require('moment');

// Configuration for multiple APIs
const WEATHER_APIS = [
  {
    name: 'WeatherAPI1',
    url: 'https://api.weatherapi1.com/v1',
    apiKey: process.env.WEATHER_API_KEY_1,
    rateLimit: 1000, // Requests per minute
  },
  {
    name: 'WeatherAPI2',
    url: 'https://api.weatherapi2.com/v1',
    apiKey: process.env.WEATHER_API_KEY_2,
    rateLimit: 500, // Requests per minute
  }
];

// Logger setup
const logger = createLogger({
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()]
});

class WeatherDataFetcher {
  constructor() {
    this.cache = new NodeCache({ stdTTL: 300 }); // Cache for 5 minutes
    this.queue = new Queue('weather-fetch', { connection: { host: 'localhost' } });
    this.apiKeys = {};
    this.apiKeyRefreshInterval = moment().add(12, 'hours');
    this.scheduleApiKeyUpdate();
  }

  async fetchWeatherData(location) {
    const cacheKey = `weather:${location}`;
    let weatherData = this.cache.get(cacheKey);

    if (weatherData) return weatherData;

    await this.queue.process(async job => {
      try {
        for (const api of WEATHER_APIS) {
          try {
            weatherData = await this.callWeatherAPI(api, location);
            this.cache.set(cacheKey, weatherData);
            logger.info(`Fetched data from ${api.name}`, { location });
            break;
          } catch (error) {
            logger.error(`Failed to fetch from ${api.name}: ${error.message}`);
          }
        }

        if (!weatherData) throw new Error('All APIs failed');
      } catch (error) {
        logger.warn('Retrying weather data fetch', { error: error.message });
        job.retry();
      }
    }, async job => ({
      attempts: 5,
      backoff: {
        type: 'exponential',
        delay: 1000
      }
    }));

    return await this.queue.add('fetchWeatherData', location);
  }

  async callWeatherAPI(api, location) {
    const response = await axios.get(`${api.url}/current.json`, {
      params: { q: location, key: api.apiKey },
      headers: { 'Rate-Limit': api.rateLimit }
    });

    return this.processApiResponse(response.data);
  }

  processApiResponse(data) {
    // Convert the JSON response to a standardized format
    return {
      temperature: data.current.temp_c,
      condition: data.current.condition.text,
      location: data.location.name
    };
  }

  scheduleApiKeyUpdate() {
    setInterval(async () => {
      logger.info('Refreshing API keys');
      for (const api of WEATHER_APIS) {
        this.apiKeys[api.name] = await this.fetchNewApiKey(api);
      }
    }, moment().diff(this.apiKeyRefreshInterval, 'milliseconds'));
  }

  async fetchNewApiKey(api) {
    // Logic to fetch and update the API key
    return process.env.WEATHER_API_KEY_1; // Example placeholder
  }
}

// Monitoring setup
setInterval(() => {
  const queueLength = this.queue.getJobs('completed').length;
  logger.info('Queue monitoring', { queueLength });
}, 60000);

module.exports = WeatherDataFetcher;
```

