class SecureBinaryFileProcessor;

using FactoryFunction = std::function<std::shared_ptr<SecureBinaryFileProcessor>()>;
using VersionedFactoryFunctionMap = std::unordered_map<int, std::unordered_map<int, FactoryFunction>>;

class SecureBinaryFileProcessor {
public:
    virtual ~SecureBinaryFileProcessor() = default;

    static void registerFactoryFunction(int id, int version, FactoryFunction factory);
    static std::shared_ptr<SecureBinaryFileProcessor> createInstance(int id, int version);

    // Other member functions
    void processFile(const std::string& inputFile, const std::string& outputFile,
                     const std::vector<std::pair<std::string, std::string>>& rules);

private:
    SecureBinaryFileProcessor() = default;

    static VersionedFactoryFunctionMap factoryRegistry;
    static std::mutex registryMutex;
};

// Implementation

SecureBinaryFileProcessor::VersionedFactoryFunctionMap SecureBinaryFileProcessor::factoryRegistry;
std::mutex SecureBinaryFileProcessor::registryMutex;

void SecureBinaryFileProcessor::registerFactoryFunction(int id, int version, FactoryFunction factory) {
    std::lock_guard<std::mutex> lock(registryMutex);
    factoryRegistry[id][version] = factory;
}

std::shared_ptr<SecureBinaryFileProcessor> SecureBinaryFileProcessor::createInstance(int id, int version) {
    std::lock_guard<std::mutex> lock(registryMutex);
    auto it = factoryRegistry.find(id);
    if (it != factoryRegistry.end()) {
        auto versionIt = it->second.find(version);
        if (versionIt != it->second.end()) {
            return versionIt->second();
        }
    }
    throw std::runtime_error("Factory function not found for ID: " + std::to_string(id) + ", Version: " + std::to_string(version));
}

void SecureBinaryFileProcessor::processFile(const std::string& inputFile, const std::string& outputFile,
                                            const std::vector<std::pair<std::string, std::string>>& rules) {
    helpers::log("Processing file: " + inputFile);

    std::ifstream input(inputFile, std::ios::binary);
    if (!input) throw std::runtime_error("Failed to open input file");

    // Read and parse the binary data
    std::vector<char> buffer(std::istreambuf_iterator<char>(input), {});

    // Apply transformation rules (simplified for example)
    for (const auto& rule : rules) {
        helpers::log("Applying rule: " + rule.first);
        // Transformation logic here...
    }

    std::ofstream output(outputFile, std::ios::binary);
    if (!output) throw std::runtime_error("Failed to open output file");

    output.write(buffer.data(), buffer.size());
}

// Example subclass
class MySecureBinaryProcessor : public SecureBinaryFileProcessor {
public:
    void customProcess() {
        helpers::log("Custom processing in MySecureBinaryProcessor");
    }
};

void registerMyProcessorFunctions() {
    SecureBinaryFileProcessor::registerFactoryFunction(1, 0, [] { return std::make_shared<MySecureBinaryProcessor>(); });
}

// Helper function for logging
namespace helpers {
    void log(const std::string& message) {
        std::cout << "LOG: " << message << std::endl;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: <input file> <output file> <rules as JSON array>" << std::endl;
        return 1;
    }

    try {
        std::string inputFile = argv[1];
        std::string outputFile = argv[2];

        // Parsing transformation rules from command-line argument
        nlohmann::json jsonRules = nlohmann::json::parse(argv[3]);

        if (!jsonRules.is_array()) {
            throw std::invalid_argument("Transformation rules must be an array of objects");
        }

        std::vector<std::pair<std::string, std::string>> rules;
        for (const auto& rule : jsonRules) {
            if (rule.contains("field") && rule.contains("value")) {
                rules.emplace_back(rule["field"], rule["value"]);
            }
        }

        registerMyProcessorFunctions();

        auto processor = SecureBinaryFileProcessor::createInstance(1, 0);
        processor->processFile(inputFile, outputFile, rules);

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 2;
    }

    return 0;
}
