# push_notifications.py

import requests
from typing import Dict, Any

class PushNotificationClient:
    def __init__(self, apns_key: str, fcm_server_key: str):
        self.apns_key = apns_key
        self.fcm_server_key = fcm_server_key

    def send_notification(self, device_token: str, message: str, device_type: str) -> bool:
        if device_type == "iOS":
            return self._send_via_apns(device_token, message)
        elif device_type == "Android":
            return self._send_via_fcm(device_token, message)
        else:
            raise ValueError("Unsupported device type")

    def _send_via_apns(self, device_token: str, message: str) -> bool:
        url = "https://api.push.apple.com/3/device/" + device_token
        headers = {
            "apns-push-type": "alert",
            "apns-topic": "com.example.app",
            "authorization": f"bearer {self.apns_key}"
        }
        payload = {"aps": {"alert": message}}

        try:
            response = requests.post(url, json=payload, headers=headers)
            return response.status_code == 200
        except requests.RequestException as e:
            print(f"APNs Error: {e}")
            return False

    def _send_via_fcm(self, device_token: str, message: str) -> bool:
        url = "https://fcm.googleapis.com/fcm/send"
        headers = {
            "Authorization": f"key={self.fcm_server_key}",
            "Content-Type": "application/json"
        }
        payload = {"to": device_token, "notification": {"body": message}}

        try:
            response = requests.post(url, json=payload, headers=headers)
            return response.status_code in (200, 201)
        except requests.RequestException as e:
            print(f"FCM Error: {e}")
            return False

