```rust
use std::{
    collections::HashMap,
    env,
    fs::{self, DirEntry},
    io::{BufWriter, Write},
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
    thread::{self, JoinHandle},
    time::{Duration, Instant},
};
use log::{error, info, warn};
use serde::{Deserialize, Serialize};
use tokio::sync::{mpsc, Semaphore};
use tokio_postgres::{NoTls, Error as PgError};
use reqwest::Client;
use json_config::Config;

#[derive(Serialize, Deserialize)]
struct Config {
    cleanup_interval_secs: u64,
    max_directories_retain: usize,
}

type DirectoryHandle = JoinHandle<()>;

struct WorkspaceManager {
    config: Config,
    db_url: String,
    log_file_path: PathBuf,
    semaphore: Semaphore,
    env_var_name: String,
    directory_paths: Arc<Mutex<HashMap<String, PathBuf>>>,
}

impl WorkspaceManager {
    pub async fn new(config_path: &str, db_url: String) -> Self {
        let config = Config::from_json_file(config_path).expect("Failed to read config file");
        let env_var_name = "PROJECT_WORKSPACE_DIR".to_string();
        let log_file_path = PathBuf::from("workspace_manager.log");

        // Initialize logging
        if !log_file_path.exists() {
            fs::File::create(&log_file_path).unwrap();
        }

        WorkspaceManager {
            config,
            db_url,
            log_file_path,
            semaphore: Semaphore::new(10),  // Limit concurrent directory creations
            env_var_name,
            directory_paths: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn manage_workspace(&self, project_id: String) -> Result<PathBuf, &'static str> {
        let mut path_guard = self.directory_paths.lock().unwrap();

        if let Some(path) = path_guard.get(&project_id) {
            return Ok(path.clone());
        }

        // Acquire a permit for concurrency management
        let _permit = self.semaphore.acquire_owned().await.unwrap();

        let env_var_value = env::var(&self.env_var_name).unwrap_or_default();

        let workspace_dir: PathBuf = if !env_var_value.is_empty() {
            PathBuf::from(env_var_value)
        } else {
            // Create a new directory
            let base_dir = dirs::data_local_dir().unwrap().join("workspaces");
            fs::create_dir_all(&base_dir).expect("Failed to create workspace directories");

            let project_dir = base_dir.join(&project_id);
            if !project_dir.exists() {
                fs::create_dir(&project_dir).expect("Failed to create project directory");
            }

            // Update environment variable atomically
            std::env::set_var(&self.env_var_name, project_dir.to_string_lossy());

            log_to_file(&self.log_file_path, &format!("Created new workspace dir for project: {}", project_id)).unwrap();

            project_dir.clone()
        };

        path_guard.insert(project_id, workspace_dir.clone());

        // Insert metadata into the database
        self.update_db_with_metadata(&project_id, &workspace_dir).await;

        Ok(workspace_dir)
    }

    async fn update_db_with_metadata(&self, project_id: &str, path: &Path) -> Result<(), PgError> {
        let client = reqwest::Client::new();
        match client.get(&format!("{}/metadata/{}", self.db_url, project_id)).send().await {
            Ok(response) if response.status().is_success() => {
                // Update metadata
                info!("Successfully updated metadata for project: {}", project_id);
            },
            Err(err) => {
                error!("Failed to update database with metadata for project {}: {:?}", project_id, err);
                return Err(PgError::new("Database operation failed"));
            }
        }

        Ok(())
    }

    async fn cleanup_unused_directories(&self) {
        let directory_paths = self.directory_paths.lock().unwrap();

        fs::read_dir(".")
            .expect("Failed to read current directory")
            .filter_map(Result::ok)
            .filter(|entry: &DirEntry| entry.is_dir())
            .for_each(|dir_entry| {
                if !directory_paths.contains_key(&dir_entry.file_name().to_string_lossy()) {
                    let _ = fs::remove_dir_all(dir_entry.path());
                    log_to_file(&self.log_file_path, &format!("Deleted unused directory: {:?}", dir_entry.path())).unwrap();
                }
            });

        // Respect maximum directories to retain
        if directory_paths.len() > self.config.max_directories_retain as usize {
            let mut paths: Vec<_> = directory_paths.iter().collect();
            paths.sort_by_key(|(_, path)| path.metadata().unwrap().modified());

            for (_, dir_path) in paths.iter().skip(self.config.max_directories_retain as usize) {
                if let Some(path) = dir_path.clone() {
                    let _ = fs::remove_dir_all(&path);
                    log_to_file(&self.log_file_path, &format!("Deleted old directory: {:?}", path)).unwrap();
                }
            }
        }
    }

    fn run_cleanup_task(&self) -> DirectoryHandle {
        thread::spawn(move || loop {
            // Wait for cleanup interval
            std::thread::sleep(Duration::from_secs(self.config.cleanup_interval_secs));

            let manager = WorkspaceManager { ..* };  // Dummy re-creation to simulate self reference in async context
            tokio::runtime::Runtime::new().unwrap().block_on(async {
                manager.cleanup_unused_directories().await;
            });
        })
    }

    fn log_to_file(path: &Path, message: &str) -> std::io::Result<()> {
        let mut file = BufWriter::new(fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open(path)?);

        writeln!(file, "{}", message)?;
        Ok(())
    }
}

async fn main() {
    // Setup logging
    env_logger::init();

    let manager = WorkspaceManager::new("config.json", "postgres://user:pass@localhost/dbname".to_string()).await;

    let handles: Vec<DirectoryHandle> = (0..10)
        .map(|i| {
            let manager_clone = manager.clone();
            thread::spawn(move || {
                let project_id = format!("project_{}", i);
                match tokio::runtime::Runtime::new().unwrap().block_on(manager_clone.manage_workspace(project_id)) {
                    Ok(_) => info!("Successfully managed workspace for project {}", project_id),
                    Err(e) => warn!("Error managing workspace: {}", e),
                }
            })
        })
        .collect();

    // Start cleanup task
    let _cleanup_handle = manager.run_cleanup_task();

    for handle in handles {
        handle.join().unwrap();
    }
}
```

