```rust
use reqwest::{Client, RequestBuilder, Url, header::HeaderMap};
use std::time::Duration;
use tokio::runtime::Runtime;
use log::{info, error};
use thiserror::Error;

#[derive(Debug, Error)]
enum HttpClientError {
    #[error("invalid URL")]
    InvalidUrl,
    #[error("connection failure: {0}")]
    ConnectionFailure(#[from] reqwest::Error),
}

async fn create_request_builder(
    url_str: &str,
    disable_cert_validation: bool,
    headers: Option<HeaderMap>,
    timeout: Duration,
) -> Result<RequestBuilder, HttpClientError> {
    let client = match Client::builder() {
        builder if disable_cert_validation => {
            builder.danger_accept_invalid_certs(true)
        }
        _ => Client::new(),
    };

    let url = Url::parse(url_str).map_err(|_| HttpClientError::InvalidUrl)?;

    let mut request_builder = client.get(url);

    if let Some(custom_headers) = headers {
        for (key, value) in custom_headers.iter() {
            request_builder = request_builder.header(key.clone(), value.to_str().unwrap_or_default());
        }
    }

    request_builder = request_builder.timeout(timeout).build()?;

    Ok(request_builder)
}

async fn execute_request(req_builder: RequestBuilder, token: Option<String>) -> Result<(), HttpClientError> {
    let client = req_builder.send().await?;
    if let Some(token) = token {
        info!("Setting Authorization header with token.");
        // Normally you would set the Authorization header here.
    }

    match client.text().await {
        Ok(response_text) => {
            info!("Response: {}", response_text);
        },
        Err(e) => error!("Failed to fetch response text: {:?}", e),
    }

    Ok(())
}

fn main() {
    let rt = Runtime::new().unwrap();
    let url = "https://example.com";

    // Set up logging for debugging
    env_logger::init();

    let custom_headers = HeaderMap::new(); // Add headers as needed

    rt.block_on(async {
        match create_request_builder(url, false, Some(custom_headers), Duration::from_secs(10)).await {
            Ok(req_builder) => {
                if let Err(e) = execute_request(req_builder, Some("your_token_here".to_string())).await {
                    error!("Request execution failed: {:?}", e);
                }
            },
            Err(err) => error!("Failed to create request builder: {}", err),
        }
    });
}

#[cfg(test)]
mod tests {
