    use reqwest::header;

    #[tokio::test]
    async fn test_valid_url() {
        let url = "https://httpbin.org/get";
        let custom_headers = HeaderMap::from_iter(vec![(header::USER_AGENT, "reqwest")]);

        match create_request_builder(url, false, Some(custom_headers), Duration::from_secs(5)).await {
            Ok(_) => assert!(true),
            Err(e) => panic!("Test failed with error: {:?}", e),
        }
    }

    #[tokio::test]
    async fn test_invalid_url() {
