class ScriptLoader {
  constructor() {
    this.fileQueue = [];
    this.isProcessing = false;
    this.configEndpoint = 'https://config-server.example.com/files';
  }

  async loadConfig() {
    try {
      const response = await fetch(this.configEndpoint);
      if (!response.ok) throw new Error(`Failed to load config: ${response.statusText}`);
      const files = await response.json();
      this.updateFileQueue(files);
    } catch (error) {
      console.error('Error loading configuration:', error.message);
    }
  }

  updateFileQueue(newFiles) {
    // Deduplicate and maintain the order of new files
    this.fileQueue = [...new Set([...this.fileQueue, ...newFiles])];
    if (!this.isProcessing) {
      this.processScripts();
    }
  }

  async processScripts() {
    this.isProcessing = true;
    while (this.fileQueue.length > 0) {
      const scriptUrl = this.fileQueue.shift();
      try {
        await this.loadAndExecuteScript(scriptUrl);
      } catch (error) {
        console.error(`Error loading or executing script ${scriptUrl}:`, error.message);
      }
    }
    this.isProcessing = false;
  }

  async loadAndExecuteScript(url) {
    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = url;

      scriptTag.onload = () => {
        console.log(`Successfully loaded and executed: ${url}`);
        resolve();
      };

      scriptTag.onerror = (e) => {
        console.error(`Error in loading script: ${url}`, e);
        reject(e);
      };

      document.head.appendChild(scriptTag);

      // Cleanup
      scriptTag.onload = null;
      scriptTag.onerror = null;
    });
  }
}

// Usage
const scriptLoader = new ScriptLoader();
scriptLoader.loadConfig();

// To dynamically update the file list, call:
// scriptLoader.updateFileQueue(['newScript1.js', 'newScript2.js']);
```

```csharp
using System;
using System.IO;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

public class ConfigStructure {
    public string LocalConfigPath { get; set; }
    public string RemoteHostIp { get; set; }
    public int RemotePort { get; set; }
    public string[] CommandList { get; set; }
    public Action<string, string> CallbackFunction { get; set; }
}

public class ScriptProcessor {
    private static readonly object LockObject = new object();

    public async Task ProcessFileAndExecuteRemoteCommands(byte[] fileContent, ConfigStructure configPointer, int timeout) {
        lock (LockObject) {
            if (!File.Exists(configPointer.LocalConfigPath)) throw new FileNotFoundException();

            var configFileContent = await File.ReadAllTextAsync(configPointer.LocalConfigPath);
            // Validate the configuration content
            if (string.IsNullOrWhiteSpace(configFileContent)) throw new InvalidOperationException("Invalid config content");

            using (var client = new TcpClient()) {
                await client.ConnectAsync(configPointer.RemoteHostIp, configPointer.RemotePort);

                using var networkStream = client.GetStream();
                foreach (var command in configPointer.CommandList) {
                    try {
                        await ExecuteCommandWithRetry(networkStream, command, timeout);
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to execute command: {command}, Error: {ex.Message}");
                    }
                }

                if (configPointer.CallbackFunction != null) {
                    configPointer.CallbackFunction("Execution completed", "Success");
                }
            }
        }
    }

    private async Task ExecuteCommandWithRetry(NetworkStream networkStream, string command, int timeout) {
        for (int attempt = 0; attempt < 3; attempt++) {
            try {
                await SendMessageAsync(networkStream, command);
                var response = await ReadMessageAsync(networkStream);

                // Assuming callback function processes output
                configPointer.CallbackFunction?.Invoke(command, response);
                return;
            } catch (Exception) when (attempt < 2) {
                await Task.Delay(TimeSpan.FromSeconds(1));
            }
        }

        throw new TimeoutException("Command execution failed after retries.");
    }

    private async Task SendMessageAsync(NetworkStream networkStream, string message) {
        var buffer = Encoding.UTF8.GetBytes(message);
        await networkStream.WriteAsync(buffer, 0, buffer.Length);
    }

    private async Task<string> ReadMessageAsync(NetworkStream networkStream) {
        byte[] buffer = new byte[1024];
        int bytesRead = await networkStream.ReadAsync(buffer, 0, buffer.Length);
        return Encoding.UTF8.GetString(buffer, 0, bytesRead);
    }
}
