import java.io.File;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

public class XMLMapUpdater {

    public CompletableFuture<Void> updateConcurrentMap(
            ConcurrentHashMap<String, String> map,
            String xmlFilePath,
            String keyPrefix) {
        return CompletableFuture.runAsync(() -> {
            try {
                File xmlFile = new File(xmlFilePath);
                if (!xmlFile.exists()) {
                    System.err.println("XML file not found.");
                    return;
                }

                DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
                DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
                Document doc = dBuilder.parse(xmlFile);

                NodeList nodeList = doc.getDocumentElement().getChildNodes();
                for (int i = 0; i < nodeList.getLength(); i++) {
                    if (nodeList.item(i) instanceof Element) {
                        Element element = (Element) nodeList.item(i);
                        String key = keyPrefix + element.getLocalName();
                        String value = getElementTextContent(element);
                        map.put(key, value); // ConcurrentHashMap handles thread safety
                    }
                }

            } catch (Exception e) {
                System.err.println("Error processing XML file: " + e.getMessage());
            }
        });
    }

    private String getElementTextContent(Element element) {
        StringBuilder sb = new StringBuilder();
        NodeList childNodes = element.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
            if (childNodes.item(i).getNodeType() == org.w3c.dom.Node.TEXT_NODE) {
                sb.append(childNodes.item(i).getNodeValue());
            }
        }
        return sb.toString().trim();
    }

    // Configuration options for memory management and processing speed
    public enum XmlProcessingConfig {
        BALANCED,
        FAST_MEMORY_INTENSIVE,
        MEMORY_EFFICIENT_SLOWER;

        private int maxBufferSize;

        XmlProcessingConfig() {
            switch (this) {
                case BALANCED:
                    this.maxBufferSize = 1024 * 64; // 64KB
                    break;
                case FAST_MEMORY_INTENSIVE:
                    this.maxBufferSize = 1024 * 256; // 256KB
                    break;
                case MEMORY_EFFICIENT_SLOWER:
                    this.maxBufferSize = 1024 * 16; // 16KB
                    break;
            }
        }

        public int getMaxBufferSize() {
            return maxBufferSize;
        }
    }
}
