// JavaScript function for dynamic unit testing

async function runUnitTests(moduleLabel, testSuites, config = {}) {
    const { concurrency = 1, timeout = 3000, retries = 2 } = config;
    const results = [];

    async function executeTestSuite(suite) {
        for (const testName of suite.tests) {
            let attempt = 0;
            while (attempt <= retries) {
                try {
                    console.log(`Running test: ${testName} in module: ${moduleLabel}`);
                    await Promise.race([
                        new Promise((resolve, reject) => {
                            setTimeout(() => reject(new Error("Test timed out")), timeout);
                        }),
                        suite.tests[testName]()
                    ]);
                    console.log(`${testName}: Passed`);
                    results.push({ name: testName, status: 'Passed' });
                    break;
                } catch (error) {
                    attempt++;
                    if (attempt > retries) {
                        console.error(`${testName}: Failed after ${retries} attempts -`, error);
                        results.push({ name: testName, status: 'Failed', reason: error.message });
                    } else {
                        console.warn(`Retrying test: ${testName}, Attempt: ${attempt}`);
                    }
                }
            }
        }
    }

    const testPromises = [];
    for (const suite of testSuites) {
        if (suite.isAsync) {
            testPromises.push(executeTestSuite(suite));
        } else {
            executeTestSuite(suite);
        }
    }

    await Promise.all(testPromises.slice(0, concurrency));

    console.log(`All tests in module ${moduleLabel} completed.`);
    return results;
}

