            case 'create':
                return $this->createClinic($clinicData);
            case 'update':
                return $this->updateClinic($clinicData);
            case 'delete':
                return $this->deleteClinic($clinicData['id']);
            default:
                throw new InvalidArgumentException("Invalid action: $action");
        }
    }

    private function createClinic($data) {
        // Validate input data
        if (!$this->validateClinicData($data)) {
            throw new Exception('Invalid clinic data');
        }

        // Verify location is geographically valid
        if (!$this->geolocationService->isValidLocation($data['location'])) {
            throw new Exception('Invalid geographic location');
        }

        $clinicId = $this->database->insertClinic($data);

        // Log creation in the monitoring service
        $this->monitoringService->logEvent("Clinic created with ID: $clinicId");

        return $clinicId;
    }

    private function updateClinic($data) {
        $statusChanged = isset($data['status']);
        if ($statusChanged && in_array($data['status'], ['closed', 'emergency'])) {
            $this->notificationService->notifyEmergencyTeams($data);
        }

        $this->database->updateClinic($data);

        // Predict occupancy levels and adjust capacity
        $predictedOccupancy = $this->predictOccupancy($data['id']);
        $this->iotSensorSystem->adjustCapacity($data['id'], $predictedOccupancy);

        // Log update in the monitoring service
        $this->monitoringService->logEvent("Clinic updated with ID: {$data['id']}");
    }

    private function deleteClinic($clinicId) {
        $activePatients = $this->patientSchedulingSystem->checkActivePatients($clinicId);

        if (!empty($activePatients)) {
            // Send notification to the scheduling system
            $this->notificationService->notifyReschedule($activePatients, $clinicId);
            throw new Exception('Cannot delete clinic with active patients');
        }

        $this->database->deleteClinic($clinicId);

        // Log deletion in the monitoring service
        $this->monitoringService->logEvent("Clinic deleted with ID: $clinicId");
    }

    private function validateClinicData($data) {
        return isset($data['status'], $data['location'], $data['capacity']);
    }

