    void processFile(const FileMetadata& fileEntry) {
        sem_wait(&semaphore);

        try {
            auto metadata = fetchMetadata(fileEntry);
            if (shouldProcess(metadata)) {
                performOperations(fileEntry, metadata);
            }
            runCommandInBackground(fileEntry.path);
        } catch (...) {
            logError("Failed to process file: " + fileEntry.path);
        }

        sem_post(&semaphore);
