    }

    void runCommandInBackground(const std::string& filePath) {
        pid_t pid = fork();
        if (pid == 0) { // Child process
            execlp("your_command", "your_command", filePath.c_str(), nullptr);
            exit(EXIT_FAILURE); // If exec fails
        } else if (pid > 0) {
            close(STDOUT_FILENO); // Detach child process output
        }
    }

    void waitForAllThreads() {
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Wait for all background processes to finish
    }

    void renameConfigFile() {
        auto timestamp = std::chrono::system_clock::now().time_since_epoch();
        auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(timestamp).count();

        fs::path newFilePath = configFilePath + "." + std::to_string(millis) + ".processed";
        if (fs::exists(newFilePath)) {
            fs::remove(newFilePath);
        }
