```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class LoadBalancer {
    private static final int PORT = 8080;
    private Selector selector;
    private List<Server> serverPool;
    private Map<SocketChannel, Server> clientToServerMap;

    public LoadBalancer(List<String> serverAddresses) throws IOException {
        this.selector = Selector.open();
        this.serverPool = new ArrayList<>();

        for (String address : serverAddresses) {
            String[] parts = address.split(":");
            InetSocketAddress serverAddress = new InetSocketAddress(parts[0], Integer.parseInt(parts[1]));
            Server server = new Server(serverAddress);
            serverPool.add(server);
            connectToServer(server);
        }

        this.clientToServerMap = new ConcurrentHashMap<>();
    }

    private void connectToServer(Server server) {
        try {
            SocketChannel socketChannel = SocketChannel.open();
            socketChannel.configureBlocking(false);
            socketChannel.connect(server.getAddress());

            // Register for connection completion
            SelectionKey key = socketChannel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_WRITE);
            server.addPendingConnection(key);

            System.out.println("Connecting to server: " + server.getAddress());

        } catch (IOException e) {
            System.err.println("Error connecting to server: " + e.getMessage());
        }
    }

    public void start() throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(PORT));
        serverSocketChannel.configureBlocking(false);

        // Accept connections
        SelectionKey acceptKey = serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        while (true) {
            selector.select();

            for (SelectionKey key : selector.selectedKeys()) {
                if (!key.isValid()) continue;

                if (key.isAcceptable() && key.channel() instanceof ServerSocketChannel) {
                    handleNewConnection((ServerSocketChannel) key.channel());
                } else if (key.isConnectable()) {
                    handleConnection(key);
                } else if (key.isWritable()) {
                    handleWrite(key);
                }
            }

            selector.selectedKeys().clear();
        }
    }

    private void handleNewConnection(ServerSocketChannel serverSocketChannel) throws IOException {
        SocketChannel clientChannel = serverSocketChannel.accept();
        if (clientChannel != null) {
            clientChannel.configureBlocking(false);

            // Assign server to this client
            Server targetServer = selectTargetServer();

            SelectionKey key = clientChannel.register(selector, SelectionKey.OP_READ);
            clientToServerMap.put(clientChannel, targetServer);

            System.out.println("Accepted connection from " + clientChannel.getRemoteAddress() +
                    ", forwarding to " + targetServer.getAddress());
        }
    }

    private Server selectTargetServer() {
        // Implement a more advanced load balancing strategy
        return serverPool.stream().min(Comparator.comparing(Server::getLoad)).orElse(null);
    }

    private void handleConnection(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        if (!channel.isConnectionPending()) {
            // Connection established, switch to write mode
            key.interestOps(key.interestOps() | SelectionKey.OP_WRITE);
            System.out.println("Connected to server: " + channel.getRemoteAddress());
            return;
        }

        channel.finishConnect();
    }

    private void handleWrite(SelectionKey key) throws IOException {
        SocketChannel clientChannel = (SocketChannel) key.channel();
        Server targetServer = clientToServerMap.get(clientChannel);

        // Forward data to the server
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int bytesRead = clientChannel.read(buffer);

        if (bytesRead > 0) {
            buffer.flip();

            // Simulate intelligent failover and load balancing
            try {
                targetServer.sendData(buffer);
                System.out.println("Forwarded data to server: " + targetServer.getAddress());
            } catch (IOException e) {
                handleServerFailure(targetServer, clientChannel);
            }
        }

        key.interestOps(key.interestOps() & ~SelectionKey.OP_WRITE);
    }

    private void handleServerFailure(Server failedServer, SocketChannel clientChannel) throws IOException {
        // Implement failover mechanism
        System.err.println("Failed to connect to server: " + failedServer.getAddress());

        // Reconnect or assign a new target server
        Server newTarget = selectTargetServer();
        if (newTarget != null) {
            SelectionKey writeKey = clientChannel.register(selector, SelectionKey.OP_WRITE);
            clientToServerMap.put(clientChannel, newTarget);

            System.out.println("Reassigned to server: " + newTarget.getAddress());
        } else {
            clientChannel.close();
        }
    }

    public static void main(String[] args) throws IOException {
        List<String> servers = Arrays.asList("127.0.0.1:9090", "192.168.1.2:9090");
        LoadBalancer loadBalancer = new LoadBalancer(servers);
        System.out.println("Load balancer started on port " + PORT);
        loadBalancer.start();
    }
}

