using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;

public static class Config
{
    public const string Base64Key = "your-base64-key-here";
    public const string Base64IV = "your-base64-iv-here";
}

public class MessageProcessor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public MessageProcessor(string base64Key, string base64Iv)
    {
        _key = Convert.FromBase64String(base64Key);
        _iv = Convert.FromBase64String(base64Iv);
    }

    public void ProcessMessages(List<string> messages)
    {
        foreach (var message in messages)
        {
            Task.Run(() => ProcessMessage(message));
        }
    }

    private void ProcessMessage(string base64EncodedMessage)
    {
        try
        {
            var (encryptedPart, hmacPart) = SplitMessage(base64EncodedMessage);
            var decryptedMessage = DecryptMessage(encryptedPart);
            if (ValidateHmac(hmacPart, encryptedPart + decryptedMessage))
            {
                LogMessage(decryptedMessage, "Success");
            }
            else
            {
                LogMessage(null, "Authentication Failure");
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
        }
    }

    private (string EncryptedPart, string HmacPart) SplitMessage(string base64EncodedMessage)
    {
        var messageParts = base64EncodedMessage.Split(new[] { '|' }, 2);
        if (messageParts.Length != 2)
        {
            throw new FormatException("Invalid Base64 encoded message format.");
        }
        return (messageParts[0], messageParts[1]);
    }

    private string DecryptMessage(string encryptedPart)
    {
        var encryptedBytes = Convert.FromBase64String(encryptedPart);
        using var tripleDes = TripleDESCryptoServiceProvider.Create();
        tripleDes.Key = _key;
        tripleDes.IV = _iv;

        using var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
        var decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

        return Encoding.UTF8.GetString(decryptedBytes);
    }

    private bool ValidateHmac(string hmacPart, string message)
    {
        using var hmacSha256 = new HMACSHA256(_key);
        var computedHash = hmacSha256.ComputeHash(Encoding.UTF8.GetBytes(message));
        var providedHmac = Convert.FromBase64String(hmacPart);

        return StructuralComparisons.StructuralEqualityComparer.Equals(computedHash, providedHmac);
    }

    private void LogMessage(string message, string status)
    {
        var logEntry = $"{DateTime.UtcNow}: {status} - Message: {message}";
        SendMessageToQueue(logEntry);
    }

    private void LogError(string error)
    {
        var errorMessage = $"{DateTime.UtcNow}: Error - {error}";
        SendMessageToQueue(errorMessage);
    }

    private void SendMessageToQueue(string message)
    {
        var factory = new ConnectionFactory() { HostName = "localhost" };
        using (var connection = factory.CreateConnection())
        using (var channel = connection.CreateModel())
        {
            channel.QueueDeclare(queue: "message_logs", durable: false, exclusive: false, autoDelete: false, arguments: null);
            var body = Encoding.UTF8.GetBytes(message);

            channel.BasicPublish(exchange: "", routingKey: "message_logs", basicProperties: null, body: body);
        }
    }
}

