import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.ResourceLoader;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.web.client.RestTemplate;

import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.Key;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

@Configuration
public class JwtService {

    @Autowired
    private ResourceLoader resourceLoader;

    @Autowired
    private RedisConnectionFactory redisConnectionFactory;

    private final ObjectMapper objectMapper = new ObjectMapper();
    private Key jwtKey; // Initialize with your actual JWT signing key

    public JwtService() {
        try {
            this.jwtKey = Keys.hmacShaKeyFor("your-256-bit-secret".getBytes()); // Replace with your secret key
        } catch (Exception e) {
            throw new RuntimeException("Failed to initialize JWT key", e);
        }
    }

    @Bean
    public RedisTemplate<String, JwtData> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, JwtData> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        return template;
    }

    public Map<String, Claims> loadAndValidateJwt(List<String> configFilePaths, String expectedIssuer, String expectedAudience, List<String> scopes) {
        for (String path : configFilePaths) {
            try {
                String json = new String(Files.readAllBytes(Paths.get(path)));
                Jws<Claims> claims = Jwts.parserBuilder().setSigningKey(jwtKey).build()
                        .parseClaimsJws(json);

                validateToken(claims.getBody(), expectedIssuer, expectedAudience, scopes);

                JwtData jwtData = new JwtData();
                jwtData.setUsername(claims.getBody().getSubject());
                jwtData.setRoles((List<String>) claims.getBody().get("roles"));
                jwtData.setExpirationTime(Instant.ofEpochMilli(claims.getBody().getExpiration().toMillis()));

                redisTemplate.opsForValue().set(claims.getBody().getId(), jwtData, 10, TimeUnit.MINUTES);

            } catch (Exception e) {
                handleTokenError(e);
            }
        }
        return null; // Placeholder for JWT metadata if needed
    }

    private void validateToken(Claims claims, String expectedIssuer, String expectedAudience, List<String> scopes) throws Exception {
        if (!expectedIssuer.equals(claims.getIssuer())) {
            throw new IllegalArgumentException("Invalid issuer");
        }

        if (claims.getAudience() == null || !claims.getAudience().contains(expectedAudience)) {
            throw new IllegalArgumentException("Invalid audience");
        }

        if (!scopes.containsAll((List<String>) claims.get("scope"))) {
            throw new IllegalArgumentException("Missing required scopes");
        }
    }

    private void handleTokenError(Exception e) {
        // Implement logging and error handling
        System.err.println("Error processing token: " + e.getMessage());
        // Add retry or fallback logic if necessary
    }

    public class JwtData {
        private String username;
        private List<String> roles;
        private Instant expirationTime;

        // Getters and setters
    }
}
