using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
import System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicTextProcessor
{
    private readonly ConcurrentDictionary<string, Func<byte[], string>> _hashAlgorithms = new();
    private readonly ILogger _logger;
    private readonly IApiClient _apiClient; // Assume this is an interface for API interaction

    public DynamicTextProcessor(ILogger logger, IApiClient apiClient)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _apiClient = apiClient ?? throw new ArgumentNullException(nameof(apiClient));

        InitializeHashAlgorithms();
    }

    private void InitializeHashAlgorithms()
    {
        _hashAlgorithms["MD5"] = input => ComputeHash(input, MD5.Create());
        _hashAlgorithms["SHA1"] = input => ComputeHash(input, SHA1.Create());
        _hashAlgorithms["SHA256"] = input => ComputeHash(input, SHA256.Create());
    }

    public void AddHashAlgorithm(string name, Func<byte[], string> hashFunction)
    {
        if (string.IsNullOrEmpty(name)) throw new ArgumentException("Name cannot be null or empty", nameof(name));
        if (_hashAlgorithms.ContainsKey(name)) throw new InvalidOperationException($"Hash algorithm '{name}' already exists.");
        _hashAlgorithms[name] = hashFunction ?? throw new ArgumentNullException(nameof(hashFunction));
    }

    public string GenerateHash(string input, string algorithm)
    {
        ValidateInput(input);

        var stopwatch = Stopwatch.StartNew();
        if (!_hashAlgorithms.TryGetValue(algorithm, out var hashFunc))
            throw new ArgumentException($"Unknown hash algorithm: {algorithm}");

        var result = hashFunc(Encoding.UTF8.GetBytes(input));
        _logger.Log($"Hash computation took {stopwatch.ElapsedMilliseconds} ms", LogLevel.Info);

        return result;
    }

    public async Task<string> GenerateHashAsync(string input, string algorithm)
    {
        ValidateInput(input);

        if (!_hashAlgorithms.TryGetValue(algorithm, out var hashFunc))
            throw new ArgumentException($"Unknown hash algorithm: {algorithm}");

        var stopwatch = Stopwatch.StartNew();
        var task = Task.Run(() => hashFunc(Encoding.UTF8.GetBytes(input)));

        var result = await task;
        _logger.Log($"Async Hash computation took {stopwatch.ElapsedMilliseconds} ms", LogLevel.Info);

        return result;
    }

    private string ComputeHash(byte[] input, HashAlgorithm algorithm)
    {
        using (algorithm)
            return BitConverter.ToString(algorithm.ComputeHash(input)).Replace("-", "").ToLowerInvariant();
    }

    private void ValidateInput(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));
        if (input.Length > 1_073_741_824) // 1 GB
            throw new ArgumentException("Input size exceeds the maximum limit of 1GB.");
    }

    public void ProcessUserInput(string inputData, UserSettings settings)
    {
        ValidateInput(inputData);

        var adjustedInput = AdjustInput(dataInput, settings);

        Task.Run(() => ParseAndAggregateLogs(adjustedInput))
            .ContinueWith(task =>
            {
                if (task.Exception != null)
                    _logger.Log($"Error processing input: {task.Exception.Message}", LogLevel.Error);

                ReportStatisticsAsync();
            });
    }

    private string AdjustInput(string inputData, UserSettings settings)
    {
        var data = inputData;

        if (settings.TrimFlag) data = data.Trim();
        if (settings.CapitalizeFlag) data = data.ToUpperInvariant();

        return data.Length > settings.MaxAllowedLength ? data.Substring(0, settings.MaxAllowedLength) : data;
    }

    private void ParseAndAggregateLogs(string logs)
    {
        // Implementation to parse logs and aggregate statistics
        var lines = logs.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);

        var ipStats = new ConcurrentDictionary<string, List<double>>();

        foreach (var line in lines)
        {
            if (!TryParseHttpRequest(line, out var httpRequest)) continue;

            var key = httpRequest.IPAddress;
            ipStats.AddOrUpdate(key, k => new List<double> { httpRequest.ResponseTime },
                                (k, existingList) =>
                                    {
                                        lock (existingList)
                                            existingList.Add(httpRequest.ResponseTime);
                                        return existingList;
                                    });
        }

        _logger.Log("Log parsing completed.", LogLevel.Info);

        // Generate averages
        var averageResponseTimes = ipStats.ToDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.Average()
        );

        _logger.Log($"Average response times calculated for {averageResponseTimes.Count} IPs.", LogLevel.Info);
    }

    private async Task ReportStatisticsAsync()
    {
        try
        {
            await _apiClient.ReportStatisticsAsync(/* aggregated data */);
            _logger.Log("Statistics reported successfully.", LogLevel.Info);
        }
        catch (Exception ex)
        {
            _logger.Log($"Failed to report statistics: {ex.Message}", LogLevel.Error);
        }
    }

    private bool TryParseHttpRequest(string line, out HttpRequestInfo httpRequest)
    {
        // Parse the HTTP request information from each log line
        httpRequest = null;

        try
        {
            var parts = line.Split(';');
            if (parts.Length < 3) return false;

            httpRequest = new HttpRequestInfo
            {
                IPAddress = parts[0],
                RequestTime = DateTime.Parse(parts[1]),
                StatusCode = int.Parse(parts[2])
            };

            // Calculate response time hypothetically, assuming part[3] is a timestamp for response
            if (parts.Length > 3)
                httpRequest.ResponseTime = (DateTime.Now - DateTime.Parse(parts[3])).TotalMilliseconds;

            return true;
        }
        catch (Exception ex)
        {
            _logger.Log($"Failed to parse HTTP request: {ex.Message}", LogLevel.Warning);
            return false;
        }
    }

    private class HttpRequestInfo
    {
        public string IPAddress { get; set; }
        public DateTime RequestTime { get; set; }
        public int StatusCode { get; set; }
        public double ResponseTime { get; set; }
    }

    // Placeholder interface for logging
