import os
import sys
import logging
import argparse
from concurrent.futures import ProcessPoolExecutor
from time import sleep
from functools import wraps

import requests
from flask import Flask, jsonify, request

# Configure Logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Retry Decorator for API calls
def retry(max_retries=3, delay=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            retries = 0
            while retries < max_retries:
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RequestException as e:
                    logger.error(f"API call failed: {e}")
                    retries += 1
                    sleep(delay)
            raise Exception("Max retries reached for API call")
        return wrapper
    return decorator

# Mock function to fetch data from an external API
@retry(max_retries=5, delay=3)
def fetch_data_from_api(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()

# File merging logic
def merge_files(file_list, dest_path):
    with open(dest_path, 'wb') as merged_file:
        for file_name in file_list:
            with open(file_name, 'rb') as f:
                merged_file.write(f.read())
            os.remove(file_name)  # Clean up after merge

# CLI Argument Parsing
def parse_arguments():
    parser = argparse.ArgumentParser(description="File Merging Tool")
    parser.add_argument('--files', nargs='+', required=True, help='List of files to merge')
    parser.add_argument('--destination', required=True, help='Destination path for merged file')
    parser.add_argument('--api-url', required=True, help='URL for the external API')
    return parser.parse_args()

# Concurrent File Processing
def process_files_concurrently(file_list, destination):
    with ProcessPoolExecutor() as executor:
        # Split files into chunks for concurrent processing
        chunk_size = 10  # Adjust based on system capabilities
        file_chunks = [file_list[i:i + chunk_size] for i in range(0, len(file_list), chunk_size)]

        futures = [
            executor.submit(fetch_data_from_api, args.api_url) 
            for _ in range(len(file_chunks))
        ]

        api_results = [future.result() for future in futures]

        # Process each file chunk
        for chunk in file_chunks:
            merge_files(chunk, destination)

# Web-based Dashboard using Flask
app = Flask(__name__)
merge_status = {}

@app.route('/status', methods=['GET'])
def get_status():
    return jsonify(merge_status)

@app.route('/start_merge', methods=['POST'])
def start_merge():
    data = request.json
    files = data.get('files')
    destination = data.get('destination')

    if not files or not destination:
        return "Invalid input", 400

    merge_thread = ProcessPoolExecutor().submit(process_files_concurrently, files, destination)
    merge_status['task_id'] = id(merge_thread)
    return jsonify({"message": "Merge started", "task_id": merge_status['task_id']}), 202

if __name__ == "__main__":
    if '--web' in sys.argv:
        app.run(port=5000)
    else:
        args = parse_arguments()
        process_files_concurrently(args.files, args.destination)
