    if not authenticate_user(request.headers.get('Authorization')):
        return jsonify({"error": "Unauthorized"}), 401

    user_id = request.json.get('user_id')

    # Retrieve preferences from cache or store new ones
    if request.method == 'GET':
        cached_data = cache_layer.get(user_id)
        if cached_data:
            return jsonify(cached_data), 200

        preferences = redis_client.hgetall(f"user:{user_id}:preferences")
        cache_layer.set(user_id, dict(preferences))
        return jsonify(dict(preferences)), 200

    elif request.method == 'POST':
        new_preferences = request.json.get('preferences')
        redis_client.hmset(f"user:{user_id}:preferences", new_preferences)
        cache_layer.set(user_id, new_preferences)
        return jsonify({"message": "Preferences updated"}), 200

# Rate Limiting Mechanism
from functools import wraps
import time

def rate_limiter(max_calls, period):
    def decorator(func):
        call_times = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()
            while call_times and current_time - call_times[0] > period:
                call_times.pop(0)

            if len(call_times) < max_calls:
                call_times.append(current_time)
                return func(*args, **kwargs)

            return jsonify({"error": "Too Many Requests"}), 429

        return wrapper
    return decorator

@app.route('/limited-endpoint', methods=['GET'])
@rate_limiter(max_calls=5, period=60)  # Limit to 5 requests per minute
def limited_endpoint():
    return jsonify({"message": "This is a rate-limited endpoint"}), 200

