#define BUFFER_SIZE 4096

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signum) {
    keep_running = 0;
}

void log_message(const char *log_file, const char *message) {
    FILE *logfile = fopen(log_file, "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", message);
        fclose(logfile);
    }
}

void print_usage(const char *program_name) {
    printf("Usage: %s <input_file> [--help] [--verbose] [-cs] [-o output_file]\n", program_name);
    printf("Options:\n");
    printf("  --help          Display this help message and exit\n");
    printf("  --verbose       Enable verbose mode\n");
    printf("  -c              Option placeholder\n");
    printf("  -s              Option placeholder\n");
    printf("  -o <output_file> Specify output log file\n");
}

int parse_arguments(int argc, char *argv[], char **input_file, int *verbose, char **log_file) {
    if (argc == 1 || strcmp(argv[1], "--help") == 0) {
        print_usage(argv[0]);
        return 1;
    }

    *verbose = 0;
    *log_file = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            print_usage(argv[0]);
            return 1;
        } else if (strcmp(argv[i], "--verbose") == 0) {
            *verbose = 1;
        } else if (argv[i][0] == '-') {
            for (char *p = argv[i] + 1; *p != '\0'; ++p) {
                switch (*p) {
                    case 'c': // Placeholder functionality
                        break;
                    case 's': // Placeholder functionality
                        break;
                    case 'o':
                        if (++i < argc) *log_file = argv[i];
                        break;
                    default:
                        fprintf(stderr, "Unknown option: -%c\n", *p);
                        return 1;
                }
            }
        } else {
            *input_file = argv[i];
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);

    char *input_file = NULL;
    int verbose = 0;
    char *log_file = "program.log";

    if (parse_arguments(argc, argv, &input_file, &verbose, &log_file)) {
        return EXIT_FAILURE;
    }

    if (input_file == NULL) {
        fprintf(stderr, "No input file provided. Use --help for usage information.\n");
        log_message(log_file, "Error: No input file provided.");
        return EXIT_FAILURE;
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        char error_msg[256];
        snprintf(error_msg, sizeof(error_msg), "Failed to open %s: %s", input_file, strerror(errno));
        fprintf(stderr, "%s\n", error_msg);
        log_message(log_file, error_msg);
        return EXIT_FAILURE;
    }

    size_t line_count = 0;
    char buffer[BUFFER_SIZE];

    while (keep_running && fgets(buffer, sizeof(buffer), file)) {
        ++line_count;
    }

    if (!feof(file) && ferror(file)) {
        fprintf(stderr, "Error reading from %s: %s\n", input_file, strerror(errno));
        log_message(log_file, "Error reading from the input file.");
        fclose(file);
        return EXIT_FAILURE;
    }

    printf("Number of lines in '%s': %zu\n", input_file, line_count);

    if (verbose) {
        fprintf(stderr, "Finished processing the file '%s'.\n", input_file);
    }

    fclose(file);
    log_message(log_file, "Program executed successfully.");

    return EXIT_SUCCESS;
}
