Here's a Java class that fulfills your requirements using ExecutorService for non-blocking execution, Caffeine for caching, SLF4J for logging, and Jedis for Redis integration. It includes methods to hash strings with MD5 and SHA-256, handle large inputs efficiently, and manage the cache dynamically.

```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.Charset;
import java.util.concurrent.*;
import java.io.InputStream;
import java.io.FileInputStream;
import java.io.IOException;
import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import redis.clients.jedis.Jedis;

public class HashingService {

    private static final Logger logger = LoggerFactory.getLogger(HashingService.class);
    private final ExecutorService executorService;
    private final Cache<String, String> cache;
    private final Jedis jedis;

    public HashingService(int maxThreads, int cacheSize, String redisHost) {
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.cache = Caffeine.newBuilder()
            .maximumSize(cacheSize)
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build();
        this.jedis = new Jedis(redisHost);

        // Periodic cache update task
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(this::updateCacheFromBatchJob, 0, 1, TimeUnit.HOURS);
    }

    public Future<HashResult> computeHash(String input, Charset charset) {
        if (input == null || input.length() > 1000) {
            logger.error("Invalid input string");
            throw new IllegalArgumentException("Input must be non-null and <= 1000 characters");
        }

        // Check cache
        String cacheKey = input + ":" + charset.name();
        String cachedResult = cache.getIfPresent(cacheKey);
        if (cachedResult != null) {
            return CompletableFuture.completedFuture(parseHashResult(cachedResult));
        }

        return executorService.submit(() -> {
            try {
                HashResult result = hashString(input, charset);

                // Cache the result
                String resultStr = formatHashResult(result);
                cache.put(cacheKey, resultStr);
                jedis.setex(cacheKey, 600, resultStr);

                return result;
            } catch (Exception e) {
                logger.error("Error computing hash for input: {}", input, e);
                throw new RuntimeException(e);
            }
        });
    }

    private HashResult hashString(String input, Charset charset) throws NoSuchAlgorithmException, IOException {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        try (InputStream is = new FileInputStream(input)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md5.update(buffer, 0, bytesRead);
                sha256.update(buffer, 0, bytesRead);
            }
        }

        return new HashResult(md5.digest().toString(), sha256.digest().toString());
    }

    private String formatHashResult(HashResult result) {
        return "MD5:" + result.md5 + "|SHA-256:" + result.sha256;
    }

    private HashResult parseHashResult(String cachedResult) {
        String[] parts = cachedResult.split("\\|");
        String md5Part = parts[0].substring("MD5:".length());
        String sha256Part = parts[1].substring("SHA-256:".length());
        return new HashResult(md5Part, sha256Part);
    }

    private void updateCacheFromBatchJob() {
        // Implement batch processing logic to pre-compute and update cache
    }

    public void invalidateCacheEntry(String input, Charset charset) {
        String cacheKey = input + ":" + charset.name();
        cache.invalidate(cacheKey);
        jedis.del(cacheKey);
    }

    public static class HashResult {
        final String md5;
        final String sha256;

        HashResult(String md5, String sha256) {
            this.md5 = md5;
            this.sha256 = sha256;
        }
    }
}
