```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class DynamicServiceManager {

    private final Map<String, TenantRegistry> tenantRegistries = new ConcurrentHashMap<>();
    private final ObjectMapper objectMapper = new ObjectMapper();

    public String convertToJSON(Object serviceConfig) throws IOException {
        return objectMapper.writeValueAsString(serviceConfig);
    }

    public Object createServiceInstance(String tenantId, String jsonConfig) throws Exception {
        JsonNode configNode = objectMapper.readTree(jsonConfig);

        TenantRegistry registry = tenantRegistries.computeIfAbsent(tenantId, k -> new TenantRegistry());

        // Resolve dependencies
        resolveDependencies(configNode, tenantId);

        // Check and apply versioning
        String serviceType = configNode.get("type").asText();
        String version = configNode.has("version") ? configNode.get("version").asText() : "latest";
        ServiceFactory factory = registry.getServiceFactory(serviceType, version);

        if (factory == null) {
            throw new IllegalArgumentException("Service type or version not found: " + serviceType + ", Version: " + version);
        }

        // Check resource limits
        enforceResourceLimits(tenantId, serviceType);

        return factory.create(configNode);
    }

    private void resolveDependencies(JsonNode configNode, String tenantId) throws Exception {
        JsonNode dependencies = configNode.get("dependencies");
        if (dependencies != null) {
            for (JsonNode dep : dependencies) {
                String depServiceType = dep.get("type").asText();
                ServiceFactory factory = getTenantRegistry(tenantId).getServiceFactory(depServiceType, "latest");
                if (factory == null || !factory.isRunning()) {
                    throw new IllegalStateException("Dependency not satisfied for service type: " + depServiceType);
                }
            }
        }
    }

    private void enforceResourceLimits(String tenantId, String serviceType) {
        TenantRegistry registry = getTenantRegistry(tenantId);
        int currentCount = registry.getServiceInstanceCount(serviceType);

        // Assume some resource limit value
        if (currentCount >= 5) { // Example limit
            throw new IllegalStateException("Resource limit exceeded for " + serviceType);
        }
    }

    private TenantRegistry getTenantRegistry(String tenantId) {
        return tenantRegistries.get(tenantId);
    }

    public void performHealthCheck(String tenantId, String serviceId) {
        TenantRegistry registry = getTenantRegistry(tenantId);
        Object serviceInstance = registry.getServiceInstance(serviceId);
        if (serviceInstance != null) {
            // Perform health check logic
            System.out.println("Performing health check on " + serviceId);
        }
    }

    public void scaleService(String tenantId, String serviceType, int desiredCount) {
        TenantRegistry registry = getTenantRegistry(tenantId);

        int currentCount = registry.getServiceInstanceCount(serviceType);
        if (desiredCount > currentCount) {
            for (int i = 0; i < desiredCount - currentCount; i++) {
                // Logic to start a new instance
                System.out.println("Scaling up " + serviceType);
            }
        } else if (desiredCount < currentCount) {
            for (int i = 0; i < currentCount - desiredCount; i++) {
                // Logic to stop an existing instance
                System.out.println("Scaling down " + serviceType);
            }
        }
    }

    private static class TenantRegistry {

        private final Map<String, ServiceFactory> factories = new HashMap<>();
        private final Map<String, Object> services = new ConcurrentHashMap<>();

        public void registerService(String type, String version, ServiceFactory factory) {
            factories.put(type + ":" + version, factory);
        }

        public ServiceFactory getServiceFactory(String type, String version) {
            return factories.get(type + ":" + version);
        }

        public int getServiceInstanceCount(String serviceType) {
            return (int) services.values().stream()
                .filter(service -> service.getClass().getSimpleName().equals(serviceType))
                .count();
        }

        public void registerServiceInstance(String serviceId, Object service) {
            services.put(serviceId, service);
        }

        public Object getServiceInstance(String serviceId) {
            return services.get(serviceId);
        }
    }

    @FunctionalInterface
    public interface ServiceFactory {
        Object create(JsonNode config);

        boolean isRunning();
    }
}
