// Constants
const DB_CONFIG = {
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
};

const CACHE_TTL = parseInt(process.env.CACHE_TTL) || 3600;
const RATE_LIMIT_MAX = parseInt(process.env.RATE_LIMIT_MAX) || 100;
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000;

// Redis client
const redisClient = new Redis();

// Database client
const pgClient = new Client(DB_CONFIG);
pgClient.connect();

// Logger configuration
winston.configure({
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Express setup
const app = express();
app.use(helmet());
app.use(bodyParser.json());
app.use(bodyParser.text());

// Rate limiter middleware
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX,
});
app.use(limiter);

// Fetch Old Testament book names from DB with caching
async function getOldTestamentBooks() {
  const cachedBooks = await redisClient.get('old_testament_books');
  if (cachedBooks) return JSON.parse(cachedBooks);

  const { rows } = await pgClient.query('SELECT name FROM old_testament_books;');
  await redisClient.setex('old_testament_books', CACHE_TTL, JSON.stringify(rows.map(row => row.name)));
  return rows.map(row => row.name);
}

// Process incoming text data stream
function processTextData(text) {
  const bookNames = getOldTestamentBooks();
  const regex = new RegExp(`\\b(${bookNames.join('|')})\\b`, 'gi');

  let count = {};
  bookNames.forEach(bookName => { count[bookName] = 0; });

  text.replace(regex, (match) => {
    if (count.hasOwnProperty(match)) count[match]++;
  });

  return count;
}

// API endpoints
app.post('/process', async (req, res) => {
  try {
    let data = req.body;

    if (typeof data === 'string' && data.trim().startsWith('<')) {
      xml2js.parseString(data, (err, result) => {
        if (err) return res.status(400).json({ error: 'Invalid XML format.' });
        data = result.root.text[0];
        handleRequest(req, res, data);
      });
    } else if (typeof data === 'object' && data.text) {
      handleRequest(req, res, data.text);
    } else {
      return res.status(400).json({ error: 'Invalid input format.' });
    }
  } catch (error) {
    winston.error(error.message);
    sendNotification(`Error processing request: ${error.message}`);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

function handleRequest(req, res, textData) {
  const worker = new Worker('./worker.js', { workerData: textData });

  worker.on('message', (result) => {
    res.json(result);
  });

  worker.on('error', (err) => {
    winston.error(err.message);
    sendNotification(`Worker error: ${err.message}`);
    res.status(500).json({ error: 'Internal Server Error' });
  });

  worker.on('exit', (code) => {
    if (code !== 0)
      winston.error(new Error(`Worker stopped with exit code ${code}`));
  });
}

// Worker thread processing
if (!isMainThread) {
  const textData = workerData;
  parentPort.postMessage(processTextData(textData));
}

// Notification system
function sendNotification(message) {
  nodemailer.createTransport({
    service: 'gmail',
    auth: {
      user: process.env.EMAIL_USER,
      pass: process.env.EMAIL_PASSWORD,
    },
  }).sendMail({
    from: process.env.EMAIL_USER,
    to: process.env.ADMIN_EMAIL,
    subject: 'Service Alert',
    text: message,
  });
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'UP' });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  winston.info(`Server running on port ${PORT}`);
});

