#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 4096

void handleError(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

char* readLine(FILE *file) {
    size_t bufferSize = BUFFER_SIZE;
    char *line = malloc(bufferSize);
    if (!line) handleError("Memory allocation failed");

    while (fgets(line, bufferSize, file)) {
        return line;
    }

    free(line);
    return NULL;
}

void processFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) handleError("Could not open file");

    char *line;
    while ((line = readLine(file))) {
        int count = 0;
        char *token = strtok(line, " \t\n");
        double values[3] = {0.0};

        while (token != NULL) {
            if (count >= 3) {
                sscanf(token, "%lf", &values[count % 3]);
            }
            token = strtok(NULL, " \t\n");
            count++;
        }

        if (count < 3) {
            fprintf(stderr, "Line with insufficient fields: %s", line);
            free(line);
            continue;
        }

        double sum = values[0] + values[1] + values[2];
        double average = sum / 3.0;

        printf("%.6f,", average);

        free(line);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processFile(argv[1]);

    return EXIT_SUCCESS;
}
