```python
import subprocess
import os
import json
from cryptography.fernet import Fernet

def modify_kickstart(config_path, params, modules):
    try:
        with open(config_path, 'r') as file:
            config = file.read()

        for key, value in params.items():
            command = f"sed -i 's/{key}/ {value}/g' {config_path}"
            if subprocess.run(command, shell=True).returncode != 0:
                raise RuntimeError(f"Sed command failed for placeholder: {key}")

        # Add new line with encrypted password
        encrypted_password = encrypt_password(params['password'])
        config += f"\nssh_pwauth yes\nrootpw --plaintext {encrypted_password}\n"

        with open(config_path, 'w') as file:
            file.write(config)

    except Exception as e:
        rollback_kickstart(config_path)
        raise RuntimeError(f"Failed to modify Kickstart: {str(e)}")

def encrypt_password(password):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_pw = cipher_suite.encrypt(password.encode())
    return encrypted_pw.decode()

def rollback_kickstart(config_path):
    # Implement rollback logic, e.g., restore backup
    if os.path.exists(f"{config_path}.bak"):
        subprocess.run(f"mv {config_path}.bak {config_path}", shell=True)

if __name__ == "__main__":
    config_file = "path/to/kickstart.cfg"
    parameters = {"hostname": "example.com", "password": "secretpassword"}
    modules_to_test = ["module1", "module2"]

    try:
        modify_kickstart(config_file, parameters, modules_to_test)
        print("Kickstart configuration modified successfully.")
    except RuntimeError as e:
        print(e)
