using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public interface ICryptoServiceProviderAdapter
{
    Task<string> DecryptMessageAsync(string base64EncodedMessage, string keyId, string iv);
}

public interface IKeyManagementServiceAdapter
{
    Task<(string Key, string IV)> RetrieveKeyAndIVAsync(string keyId);
}

public class SecureMessageHandler
{
    private readonly ICryptoServiceProviderAdapter _cryptoServiceProvider;
    private readonly IKeyManagementServiceAdapter _keyManagementService;
    private readonly SemaphoreSlim _semaphore;

    public SecureMessageHandler(ICryptoServiceProviderAdapter cryptoServiceProvider, 
                                IKeyManagementServiceAdapter keyManagementService,
                                int maxConcurrentOperations = 10)
    {
        _cryptoServiceProvider = cryptoServiceProvider ?? throw new ArgumentNullException(nameof(cryptoServiceProvider));
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
        _semaphore = new SemaphoreSlim(maxConcurrentOperations);
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string keyId)
    {
        if (string.IsNullOrEmpty(base64EncodedMessage) || string.IsNullOrEmpty(keyId))
            throw new ArgumentException("Base64-encoded message and Key ID must not be null or empty.");

        await _semaphore.WaitAsync();
        try
        {
            var (key, iv) = await _keyManagementService.RetrieveKeyAndIVAsync(keyId);
            if (string.IsNullOrEmpty(key) || string.IsNullOrEmpty(iv))
                throw new InvalidOperationException("Failed to retrieve key and/or IV from KMS.");

            return await _cryptoServiceProvider.DecryptMessageAsync(base64EncodedMessage, keyId, iv);
        }
        catch (Exception ex)
        {
            // Log exception details for troubleshooting
            Console.WriteLine($"Error decrypting message: {ex.Message}");
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public void Dispose()
    {
        _semaphore?.Dispose();
    }
}

