    private function executeWithRetry($operation) {
        for ($attempt = 0; $attempt < $this->retryAttempts; $attempt++) {
            try {
                $operation();
                break;
            } catch (Exception $e) {
                if ($attempt == $this->retryAttempts - 1) throw $e;
            }
            usleep(500000); // Wait before retry
        }
    }
