        $operation = function () use (&$retryCount) {
            if ($retryCount++ < 2) {
                throw new Exception("Transient failure");
            }
        };

        try {
            $scheduler->executeWithRetry($operation);
        } catch (Exception $e) {
            $this->fail('Operation failed after retries');
        }

        $this->assertEquals(3, $retryCount);
