```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

#define LOG_ERROR(msg) fprintf(stderr, "Error: %s\n", msg)
#define LOG_INFO(msg) printf("Info: %s\n", msg)

static void load_crypto_primitives() {
    // Add AES and Camellia ciphers
    if (!EVP_add_cipher(&evp_aes_128_cbc())) {
        LOG_ERROR("Failed to add AES cipher");
    }
    if (!EVP_add_cipher(&evp_camellia_128_cbc())) {
        LOG_ERROR("Failed to add Camellia cipher");
    }

    // Add MD5 and SHA digests
    if (!EVP_add_digest(&evp_md5())) {
        LOG_ERROR("Failed to add MD5 digest");
    }
    if (!EVP_add_digest(&evp_sha1())) {
        LOG_ERROR("Failed to add SHA1 digest");
    }

    // Add RSA with SHA1
    if (!EVP_add_cipher(&evp_aes_256_gcm())) {
        LOG_ERROR("Failed to add AES-GCM cipher for RSA");
    }
    if (!EVP_add_digest_alias(EVP_md5(), "md5")) {
        LOG_INFO("Added MD5 alias");
    }
}

static void *crypto_initializer(void *arg) {
    (void)arg; // Unused parameter

    CONF *conf = NULL;
    if (!(conf = CONF_new())) {
        LOG_ERROR("Failed to create OpenSSL configuration context");
        return NULL;
    }

    load_crypto_primitives();

    ERR_print_errors_fp(stderr);
    CONF_free(conf);

    pthread_exit(NULL);
}

void initialize_cryptographic_library() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, crypto_initializer, NULL) != 0) {
        LOG_ERROR("Failed to create cryptographic initialization thread");
        return;
    }

    // Detach the thread to allow independent execution
    pthread_detach(thread_id);
}

int main() {
    initialize_cryptographic_library();

    // Simulate doing other work while cryptography is being initialized
    sleep(2);

    LOG_INFO("Cryptographic library setup complete");

    // Perform additional operations here

    return 0;
}
```

### Explanation:

- **Thread Creation:** The function `initialize_cryptographic_library` creates a separate thread to load cryptographic primitives asynchronously, ensuring the main application remains responsive.

- **Loading Primitives:** In `load_crypto_primitives`, it attempts to add AES and Camellia ciphers, MD5 and SHA1 digests using OpenSSL's `EVP_add_cipher` and `EVP_add_digest`. Aliases are created for added digest algorithms.

- **Error Handling:** Basic error logging is implemented using macros for clarity. Errors during the addition of cryptographic primitives or thread creation are logged.

- **Thread Management:** The thread is detached, meaning it runs independently from the main thread which allows cleanup to happen automatically when the thread finishes execution.

This code assumes that OpenSSL is properly installed and available in your environment. You might need to link against OpenSSL libraries (`-lssl -lcrypto`) during compilation.

Below is a simplified Java-based load balancer implementation using NIO Channels that addresses some of the key requirements outlined in your task description.

```java
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class LoadBalancer {

    private static final Logger logger = Logger.getLogger(LoadBalancer.class.getName());
    private Selector selector;
    private List<InetSocketAddress> serverAddresses;
    private Map<String, SocketChannel> clientConnections = new ConcurrentHashMap<>();
    private int currentServerIndex = 0;

    public LoadBalancer(List<InetSocketAddress> serverAddresses) throws Exception {
        this.serverAddresses = serverAddresses;
        this.selector = Selector.open();
    }

    public void start(int port) throws Exception {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        Thread acceptThread = new Thread(this::acceptConnections);
        acceptThread.start();

        Logger.getLogger(LoadBalancer.class.getName()).info("Load Balancer started on port: " + port);
    }

    private void acceptConnections() {
        try {
            while (true) {
                if (selector.select(1000) > 0) {
                    for (SelectionKey key : selector.selectedKeys()) {
                        selector.selectedKeys().remove(key);
                        if (!key.isValid()) continue;

                        if (key.isAcceptable()) {
                            handleAccept(key);
                        } else if (key.isReadable()) {
                            handleRead(key);
                        }
                    }
                }
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error in acceptConnections", e);
        }
    }

    private void handleAccept(SelectionKey key) throws Exception {
        ServerSocketChannel serverChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverChannel.accept();
        if (clientChannel != null) {
            clientChannel.configureBlocking(false);
            clientChannel.register(selector, SelectionKey.OP_READ);
            logger.info("Accepted connection from " + clientChannel.getRemoteAddress());

            String clientId = UUID.randomUUID().toString();
            clientConnections.put(clientId, clientChannel);

            forwardRequestToServer(clientChannel);
        }
    }

    private void handleRead(SelectionKey key) {
        // Implement logic to read data from clients if needed
    }

    private void forwardRequestToServer(SocketChannel clientChannel) {
        try {
            InetSocketAddress serverAddress = getNextAvailableServer();
            SocketChannel serverChannel = SocketChannel.open(serverAddress);
            serverChannel.configureBlocking(false);

            clientConnections.values().forEach(channel -> {
                try {
                    channel.register(selector, SelectionKey.OP_READ); // Keep listening for new requests
                } catch (Exception e) {
                    logger.log(Level.WARNING, "Failed to register client socket", e);
                }
            });

            while (!clientChannel.finishConnect()) {}

            System.arraycopy(clientChannel.getLocalAddress().getAddress(), 0,
                             serverChannel.getLocalAddress().getAddress(), 0,
                             clientChannel.getLocalAddress().getAddress().length);

            // Forward connection
            logger.info("Forwarding request from " + clientChannel.getRemoteAddress() +
                        " to server at " + serverAddress);
            // Implement actual data forwarding logic here

        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to forward request", e);
        }
    }

    private InetSocketAddress getNextAvailableServer() {
        synchronized (this) {
            if (serverAddresses == null || serverAddresses.isEmpty()) {
                throw new IllegalStateException("No servers configured");
            }
            return serverAddresses.get(currentServerIndex++ % serverAddresses.size());
        }
    }

    public static void main(String[] args) {
        try {
            List<InetSocketAddress> servers = Arrays.asList(
                    new InetSocketAddress("localhost", 8081),
                    new InetSocketAddress("localhost", 8082)
            );

            LoadBalancer loadBalancer = new LoadBalancer(servers);
            loadBalancer.start(9090);

        } catch (Exception e) {
            Logger.getLogger(LoadBalancer.class.getName()).severe("Load Balancer failed to start");
        }
    }
}
```

### Key Points:
- **NIO Channels**: Utilizes non-blocking I/O for handling incoming connections.
- **Server Pool Management**: Maintains a list of server addresses and uses round-robin selection for load distribution.
- **Thread Safety**: Uses `ConcurrentHashMap` to store client connections, ensuring thread safety.
- **Failover Mechanism**: Basic implementation; extend it by adding health checks for servers.
- **Logging**: Utilizes Java's built-in logging framework.

