// Define a 3D vector class for spatial data
struct Vec3 {
    float x, y, z;
};

// Define a ray structure for ray tracing
struct Ray {
    Vec3 origin, direction;
};

// OctreeNode class representing each node in the octree
class OctreeNode {
public:
    Vec3 center;
    float halfSize;
    std::vector<OctreeNode*> children;
    bool isLeaf;

    OctreeNode(const Vec3& c, float hs) : center(c), halfSize(hs), isLeaf(true) {
        children.resize(8, nullptr);
    }

    ~OctreeNode() {
        for (auto child : children) {
            delete child;
        }
    }

    void subdivide();
};

// Function to subdivide a node into 8 children
void OctreeNode::subdivide() {
    isLeaf = false;
    float newSize = halfSize / 2.0f;

    for (int i = 0; i < 8; ++i) {
        Vec3 newCenter = center;
        if (i & 1) newCenter.x += newSize;
        else newCenter.x -= newSize;
        if (i & 2) newCenter.y += newSize;
        else newCenter.y -= newSize;
        if (i & 4) newCenter.z += newSize;
        else newCenter.z -= newSize;

        children[i] = new OctreeNode(newCenter, newSize);
    }
}

