```python
import os
import hashlib
import boto3
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import threading
import queue
import time

class FileAggregator:
    def __init__(self, config):
        self.config = config
        self.file_queue = queue.Queue()
        self.observer = None
        self.cloud_clients = {}
        self.checksum_algorithms = {
            'md5': hashlib.md5,
            'sha256': hashlib.sha256
        }
        self.connect_cloud_services()

    def connect_cloud_services(self):
        if self.config.get('aws_s3'):
            self.cloud_clients['s3'] = boto3.client(
                's3',
                aws_access_key_id=self.config['aws_s3']['access_key'],
                aws_secret_access_key=self.config['aws_s3']['secret_key']
            )

        if self.config.get('google_cloud_storage'):
            self.cloud_clients['gcs'] = gcs.Client.from_service_account_json(
                self.config['google_cloud_storage']['credentials_path']
            )

        if self.config.get('azure_blob_storage'):
            self.cloud_clients['blob'] = BlobServiceClient(
                account_url=self.config['azure_blob_storage']['account_url'],
                credential=self.config['azure_blob_storage']['credential']
            )

    def checksum(self, file_path, algorithm='sha256'):
        hash_func = self.checksum_algorithms.get(algorithm)
        if not hash_func:
            raise ValueError(f"Unsupported algorithm: {algorithm}")

        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                hash_func.update(chunk)
        return hash_func.hexdigest()

    def validate_and_aggregate_file(self, file_info):
        try:
            checksum = self.checksum(file_info['path'], algorithm=self.config.get('checksum_algorithm', 'sha256'))
            if checksum == file_info['expected_checksum']:
                # Implement the logic for uploading to cloud services and metadata management
                pass  # Placeholder for upload logic
            else:
                raise ValueError("Checksum mismatch")
        except Exception as e:
            print(f"Error processing file {file_info['path']}: {str(e)}")

    def process_files(self):
        while True:
            try:
                file_info = self.file_queue.get(timeout=1)
                self.validate_and_aggregate_file(file_info)
            except queue.Empty:
                break

    def watch_directory(self, path):
        event_handler = FileSystemEventHandler()

        class WatcherHandler(FileSystemEventHandler):
            def on_created(self, event):
                if not event.is_directory:
                    file_info = {
                        'path': event.src_path,
                        'expected_checksum': None  # Placeholder for actual checksum calculation
                    }
                    self.file_queue.put(file_info)

        event_handler = WatcherHandler()
        self.observer = Observer()
        self.observer.schedule(event_handler, path=path, recursive=True)
        self.observer.start()

    def start(self):
        directory_paths = self.config.get('watch_directories', [])
        for path in directory_paths:
            watcher_thread = threading.Thread(target=self.watch_directory, args=(path,))
            watcher_thread.start()

        while True:
            worker_threads = [threading.Thread(target=self.process_files) for _ in range(self.config.get('concurrency_level', 5))]

            for t in worker_threads:
                t.start()

            for t in worker_threads:
                t.join()

if __name__ == "__main__":
