#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// FSA Structure Definition (simplified)
typedef struct {
    int *transitions; // Example transition data
    int num_transitions;
} Fsa;

// Thread-safe lock for state list manipulation
pthread_mutex_t state_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Logging Function
void log_message(const char* message) {
    printf("%s\n", message);
}

// Pool Allocator (simplified)
#define POOL_SIZE 1024

typedef struct {
    int data[POOL_SIZE];
    size_t next;
} MemoryPool;

MemoryPool pool = { .next = 0 };

int* allocate_from_pool(size_t size) {
    if (pool.next + size > POOL_SIZE) return NULL; // Out of memory
    int* ptr = &pool.data[pool.next];
    pool.next += size;
    return ptr;
}

void free_all() {
    pool.next = 0;
}

// Function to validate state before adding it
int validate_state(int state, Fsa* fsa) {
    for (int i = 0; i < fsa->num_transitions; ++i) {
        if (fsa->transitions[i] == state)
            return 1; // Valid state
    }
    return 0;
}

// Function to expand the state list
void expandStateList(int** current_states, int* num_states, Fsa* fsa, void* file_data, void* network_data) {
    pthread_mutex_lock(&state_list_lock);

    time_t start_time = time(NULL);

    // Example of using external data sources (simplified)
    char* primary_source = (char*)file_data; // Simulate file-based source
    char* secondary_source = (char*)network_data; // Simulate network-based source

    char* data_to_use = NULL;
    if (primary_source && strlen(primary_source) > 0) {
        data_to_use = primary_source;
    } else if (secondary_source && strlen(secondary_source) > 0) {
        data_to_use = secondary_source;
    }

    if (!data_to_use) {
        log_message("Error: No valid data source found.");
        pthread_mutex_unlock(&state_list_lock);
        return;
    }

    // Simulate reading new states from the chosen data
    char new_states[] = "2 3 4";
    int temp_state;
    int* expanded_states = (int*)allocate_from_pool((*num_states + 3) * sizeof(int));
    if (!expanded_states) {
        log_message("Error: Memory allocation failed.");
        pthread_mutex_unlock(&state_list_lock);
        return;
    }

    memcpy(expanded_states, *current_states, (*num_states) * sizeof(int));

    int state_index = *num_states;
    for (char* token = strtok(new_states, " "); token != NULL; token = strtok(NULL, " ")) {
        temp_state = atoi(token);
        if (validate_state(temp_state, fsa)) {
            expanded_states[state_index++] = temp_state;
        } else {
            log_message("Warning: Invalid state encountered and skipped.");
        }
    }

    free(*current_states); // Free the old list
    *current_states = expanded_states;
    *num_states = state_index;

    time_t end_time = time(NULL);
    char* log_msg = (char*)malloc(256 * sizeof(char));
    snprintf(log_msg, 256, "Expansion completed. Time taken: %ld seconds.", difftime(end_time, start_time));
    log_message(log_msg);

    free(log_msg);
    pthread_mutex_unlock(&state_list_lock);
}

// Cleanup function
void finalize() {
    pthread_mutex_destroy(&state_list_lock);
    free_all();
}
