# Python: Weather Data Fetching with Distributed Caching using Redis

import os
import json
import logging
from datetime import timedelta
import redis
import requests
import time

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class WeatherCache:
    def __init__(self, expiry=600):
        self.cache = redis.StrictRedis(host='localhost', port=6379, db=0)
        self.expiry = expiry  # Cache expiry in seconds (e.g., 10 minutes)

    def get_weather_data(self, location):
        cache_key = f"weather:{location}"

        # Check if data is available in cache
        cached_data = self.cache.get(cache_key)
        if cached_data:
            logger.info(f"Cache hit for {location}")
            return json.loads(cached_data)

        logger.info(f"Cache miss for {location}, fetching from API")
        weather_data = self.fetch_weather_from_api(location)

        # Store the data in cache
        self.cache.setex(cache_key, timedelta(seconds=self.expiry), json.dumps(weather_data))

        return weather_data

    def fetch_weather_from_api(self, location):
        api_url = f"https://api.weather.com/v3/wx/conditions/current?apiKey=YOUR_API_KEY&format=json&language=en-US&location={location}"
        response = requests.get(api_url)
        if response.status_code == 200:
            return response.json()
        else:
            logger.error(f"Error fetching data from API for {location}: {response.status_code}")
            return None

    def invalidate_cache_on_alert(self, location):
        cache_key = f"weather:{location}"
        self.cache.delete(cache_key)
        logger.info(f"Cache invalidated for {location} due to alert")

if __name__ == "__main__":
    weather_service = WeatherCache()
    city = "New York"

    # Fetch weather data
    weather_data = weather_service.get_weather_data(city)
    print(weather_data)

    # Simulate a geographical alert that invalidates the cache
    time.sleep(10)  # Delay to simulate time passing
    weather_service.invalidate_cache_on_alert(city)

    # Fetch again after invalidation
    updated_weather_data = weather_service.get_weather_data(city)
    print(updated_weather_data)
