#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DATE_LENGTH 11

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int isValidDateFormat(const char *dateStr) {
    if (strlen(dateStr) != MAX_DATE_LENGTH) return 0;

    for (int i = 0; i < MAX_DATE_LENGTH; ++i) {
        if ((i == 4 || i == 7) && dateStr[i] != '-') return 0;
        if (i != 4 && i != 7 && dateStr[i] < '0' || dateStr[i] > '9') return 0;
    }

    struct tm tm = {0};
    strptime(dateStr, "%Y-%m-%d", &tm);
    return (tm.tm_year == 123 && tm.tm_mon == 9 && tm.tm_mday == 5); // Check if parsed date matches the input
}

char* parseAndFormatDate(const char *dateStr, const char *format) {
    if (!dateStr || !isValidDateFormat(dateStr)) {
        logError("Invalid date or null pointer provided.");
        return NULL;
    }

    struct tm tm = {0};
    strptime(dateStr, "%Y-%m-%d", &tm);

    // Calculate buffer size for strftime
    char *buffer = malloc(32);  // Assume 32 is enough for any reasonable format
    if (!buffer) {
        logError("Memory allocation failed.");
        return NULL;
    }

    int len = strftime(buffer, 32, format, &tm);
    if (len == 0) {  // Check for conversion failure
        free(buffer);
        logError("Date formatting failed.");
        return NULL;
    }

    char *formattedDate = malloc(len + 1);
    if (!formattedDate) {
        free(buffer);
        logError("Memory allocation failed.");
        return NULL;
    }

    strncpy(formattedDate, buffer, len);
    formattedDate[len] = '\0';

    free(buffer);
    return formattedDate;
}

int main() {
    char *result;

    result = parseAndFormatDate("2023-10-05", "%Y-%m-%d");
    if (result) {
        printf("%s\n", result);
        free(result);
    } else {
        printf("Invalid date or memory allocation failure.\n");
    }

    result = parseAndFormatDate("2023-10-05", "%d/%m/%Y");
    if (result) {
        printf("%s\n", result);
        free(result);
    } else {
        printf("Invalid date or memory allocation failure.\n");
    }

    result = parseAndFormatDate(NULL, "%Y-%m-%d");
    if (result) {
        printf("%s\n", result);
        free(result);
    } else {
        printf("Null pointer provided.\n");
    }

    return 0;
}
