Below is a simplified version of a C-based semaphore management library that meets your described requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_TENANTS 1000
#define SEMAPHORE_NAME_LEN 256

typedef struct {
    char name[SEMAPHORE_NAME_LEN];
    int count;
    pthread_mutex_t mutex;
} Semaphore;

typedef struct {
    Semaphore* semaphores;
    int semaphore_count;
    pthread_rwlock_t lock;
} Tenant;

Tenant tenants[MAX_TENANTS];
int tenant_count = 0;
pthread_rwlock_t global_lock = PTHREAD_RWLOCK_INITIALIZER;

Semaphore* create_semaphore(char* name, int initial_value) {
    if (strlen(name) >= SEMAPHORE_NAME_LEN) {
        fprintf(stderr, "Error: Semaphore name too long.\n");
        return NULL;
    }

    Semaphore* sem = malloc(sizeof(Semaphore));
    if (!sem) {
        perror("Failed to allocate memory for semaphore.");
        return NULL;
    }

    strncpy(sem->name, name, SEMAPHORE_NAME_LEN);
    sem->count = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);

    return sem;
}

Tenant* create_tenant() {
    Tenant* tenant = malloc(sizeof(Tenant));
    if (!tenant) {
        perror("Failed to allocate memory for tenant.");
        return NULL;
    }

    tenant->semaphores = NULL;
    tenant->semaphore_count = 0;
    pthread_rwlock_init(&tenant->lock, NULL);

    pthread_rwlock_wrlock(&global_lock);
    tenants[tenant_count++] = *tenant;
    pthread_rwlock_unlock(&global_lock);

    return tenant;
}

void add_semaphore_to_tenant(Tenant* tenant, Semaphore* sem) {
    if (!tenant || !sem) return;

    pthread_rwlock_wrlock(&tenant->lock);
    tenant->semaphores = realloc(tenant->semaphores, (tenant->semaphore_count + 1) * sizeof(Semaphore));
    tenant->semaphores[tenant->semaphore_count++] = *sem;
    pthread_rwlock_unlock(&tenant->lock);
}

int acquire_semaphore(Tenant* tenant, char* name) {
    if (!tenant || !name) return -1;

    pthread_rwlock_rdlock(&global_lock);

    for (int i = 0; i < tenant_count; ++i) {
        Tenant* t = &tenants[i];
        pthread_rwlock_rdlock(&t->lock);

        for (int j = 0; j < t->semaphore_count; ++j) {
            Semaphore* sem = &t->semaphores[j];

            if (strcmp(sem->name, name) == 0) {
                pthread_mutex_lock(&sem->mutex);

                if (sem->count > 0) {
                    sem->count--;
                    pthread_mutex_unlock(&sem->mutex);
                    pthread_rwlock_rdunlock(&t->lock);
                    pthread_rwlock_unlock(&global_lock);

                    return 0;
                }

                pthread_mutex_unlock(&sem->mutex);
            }
        }

        pthread_rwlock_rdunlock(&t->lock);
    }

    pthread_rwlock_unlock(&global_lock);
    return -1; // Semaphore not found or unavailable
}

int release_semaphore(Tenant* tenant, char* name) {
    if (!tenant || !name) return -1;

    pthread_rwlock_wrlock(&global_lock);

    for (int i = 0; i < tenant_count; ++i) {
        Tenant* t = &tenants[i];
        pthread_rwlock_wrlock(&t->lock);

        for (int j = 0; j < t->semaphore_count; ++j) {
            Semaphore* sem = &t->semaphores[j];

            if (strcmp(sem->name, name) == 0) {
                pthread_mutex_lock(&sem->mutex);
                sem->count++;
                pthread_mutex_unlock(&sem->mutex);

                pthread_rwlock_wrunlock(&t->lock);
                pthread_rwlock_unlock(&global_lock);

                return 0;
            }
        }

        pthread_rwlock_wrunlock(&t->lock);
    }

    pthread_rwlock_unlock(&global_lock);
    return -1; // Semaphore not found
}

void destroy_tenant(Tenant* tenant) {
    if (!tenant) return;

    pthread_rwlock_wrlock(&global_lock);

    for (int i = 0; i < tenant_count; ++i) {
        if (&tenants[i] == tenant) {
            pthread_rwlock_destroy(&tenant->lock);

            for (int j = 0; j < tenant->semaphore_count; ++j) {
                pthread_mutex_destroy(&tenant->semaphores[j].mutex);
                free(tenant->semaphores[j].name); // Assuming dynamic allocation
            }

            free(tenant->semaphores);
            tenants[i] = tenants[--tenant_count];
            break;
        }
    }

    pthread_rwlock_unlock(&global_lock);

    free(tenant);
}

void destroy_semaphore(Semaphore* sem) {
    if (!sem) return;

    pthread_mutex_destroy(&sem->mutex);
    free(sem);
}
```

### Key Features:
- **Tenant and Semaphore Management:** Supports multiple tenants with independent semaphore sets.
- **Thread-Safe Operations:** Uses `pthread` for mutexes, read-write locks, ensuring safe concurrent operations.
- **Dynamic Resource Allocation:** Allows dynamic addition of semaphores to tenants.
- **Error Handling:** Checks for system limitations (e.g., memory allocation failures) and handles potential concurrency issues.
- **Scalability Considerations:** Designed to be scalable with minimal overhead using efficient locking mechanisms.

### Logging & Performance:
For logging, integrate a thread-safe logging mechanism. For performance optimization, consider implementing caching strategies or adjusting the granularity of locks based on profiling results.

