}

impl ConfigManager {
    fn new(base_path: &str, remote_path: &str) -> Self {
        Self {
            config_service: ConfigService::new(remote_path),
            local_base_path: base_path.into(),
        }
    }

    async fn get_config_dir(&self, app_name: &str) -> Result<PathBuf> {
        let config_dir = self.local_base_path.join(app_name);

        if config_dir.exists() {
            return Ok(config_dir);
        }

        // Mutex to handle concurrent directory creation
        static CONFIG_DIR_MUTEX: Lazy<Mutex<()>> = Lazy::new(|| Mutex::new(()));

        let _guard = CONFIG_DIR_MUTEX.lock().await;

        if !config_dir.exists() {
            match fs::create_dir(&config_dir) {
                Ok(_) => info!("Created local config directory {}", config_dir.display()),
                Err(e) => {
                    error!(
                        "Failed to create local configuration directory {}: {}",
                        config_dir.display(),
                        e
                    );
                    return Err(anyhow::anyhow!("Permission denied or invalid path"));
                }
            }

            match self.config_service.directory_exists().await.context("Checking remote directory existence")? {
                true => {
                    info!(
                        "Configuration directory already exists in the remote repository"
                    );
                },
                false => {
                    if let Err(e) = self.config_service.sync_with_remote(&config_dir).await {
                        error!("Failed to sync with remote: {}", e);
                    }
                },
            };
        }

        Ok(config_dir)
    }
}

