typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    // Additional fields as required by the specification
} NFAPI_CRC_INDICATION_PDU_T;

// Function to fetch sequence values from external data source
void fetch_sequence_values(const char *url, int *rx_ue_info_tag_seq, int *rnti_seq) {
    // Hypothetical function to get sequence values from a URL
    network_fetch_sequences(url, rx_ue_info_tag_seq, rnti_seq);
}

// Thread worker function for populating and transmitting structures
void* process_structure(void *arg) {
    struct {
        NFAPI_CRC_INDICATION_PDU_T **nfalist;
        int *crc_flag_rules;
        char *ip_address;
        int port;
        int index;
    } *data = (struct *)arg;

    // Populate structure with sequence values and CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *pdu = &(*data->nfalist)[data->index];
    pdu->RX_UE_INFORMATION_TAG = data->rx_ue_info_tag_seq[data->index];  // Example value
    pdu->RNTI = data->rnti_seq[data->index];                              // Example value
    pdu->CRCFLAG = data->crc_flag_rules[data->index];

    // Log the creation of structure
    log_structure_operation(pdu);

    // Send structure over network
    if (network_send(ip_address, port, pdu) != 0) {
        fprintf(stderr, "Network transmission failed for index %d\n", data->index);
    }

    free(arg);  // Clean up allocated memory for argument
    return NULL;
}

int transmitNFAPIData(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, int *crc_flag_rules, int max_threads, char *ip_address, int port, const char *data_source_url, size_t max_memory_allocation) {
    // Check memory allocation constraints
    if (num_structures > 0 && max_memory_allocation < num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Insufficient memory allocation\n");
        return -1;
    }

    // Allocate memory for the list of structures
    *nfalist = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfalist == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int rx_ue_info_tag_seq[num_structures];
    int rnti_seq[num_structures];

    // Fetch sequence values from the external data source
    fetch_sequence_values(data_source_url, rx_ue_info_tag_seq, rnti_seq);

    pthread_t threads[max_threads];
    int active_threads = 0;

    for (int i = 0; i < num_structures; ++i) {
        if (active_threads >= max_threads) {
            // Wait for any thread to complete before continuing
            pthread_join(threads[0], NULL);
            memmove(&threads[0], &threads[1], sizeof(pthread_t) * (--max_threads));
            --active_threads;
        }

        struct {
            NFAPI_CRC_INDICATION_PDU_T **nfalist;
            int *crc_flag_rules;
            char *ip_address;
            int port;
            int index;
        } *thread_data = malloc(sizeof(*thread_data));

        if (thread_data == NULL) {
            perror("Memory allocation for thread data failed");
            free(*nfalist);
            return -1;
        }

        thread_data->nfalist = nfalist;
        thread_data->crc_flag_rules = crc_flag_rules;
        thread_data->ip_address = ip_address;
        thread_data->port = port;
        thread_data->index = i;

        pthread_create(&threads[max_threads - active_threads], NULL, process_structure, (void *)thread_data);
        ++active_threads;
    }

    // Wait for all threads to complete
    while (active_threads > 0) {
        pthread_join(threads[--max_threads], NULL);
        --active_threads;
    }

    return 0;
}
