using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.Linq;
using System.Xml.Schema;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XmlParserService
{
    private readonly IMemoryCache _cache;
    private readonly ILogger<XmlParserService> _logger;
    private readonly Configuration _config;

    public XmlParserService(IMemoryCache cache, ILogger<XmlParserService> logger, IConfiguration config)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _config = config ?? throw new ArgumentNullException(nameof(config));
    }

    public XElement FindElementByXPath(string xpathExpression, string namespaceName = null, string schemaVersion = null)
    {
        var xmlPath = GetXmlDocumentPath();

        if (!_cache.TryGetValue(xmlPath, out XDocument xdoc))
        {
            xdoc = LoadAndValidateXml(xmlPath, schemaVersion);
            _cache.Set(xmlPath, xdoc, TimeSpan.FromMinutes(10)); // Caching for 10 minutes
        }

        var namespaces = GetNamespaces(xdoc.Root);

        var result = (namespaceName != null)
            ? xdoc.XPathSelectElements(xpathExpression, namespaces[namespaceName])
            : xdoc.XPathSelectElements(xpathExpression, namespaces.Values.ToArray());

        if (!result.Any())
        {
            throw new Exception($"No elements found with XPath: {xpathExpression}");
        }

        if (result.Count() > 1)
        {
            throw new Exception($"Multiple elements found with XPath: {xpathExpression}");
        }

        return result.First();
    }

    private XDocument LoadAndValidateXml(string path, string schemaVersion)
    {
        var xdoc = XDocument.Load(path);

        // Assume schema validation logic is implemented
        ValidateAgainstSchema(xdoc, schemaVersion);

        return xdoc;
    }

    private void ValidateAgainstSchema(XDocument doc, string schemaVersion)
    {
        // Fetch and validate with the specified version's XML Schema
        _logger.LogInformation($"Validating against schema version: {schemaVersion}");
        var schemas = GetSchemasForVersion(schemaVersion);

        foreach (var schema in schemas)
        {
            doc.Validate(schema, validationEventHandler);
        }
    }

    private void validationEventHandler(object sender, ValidationEventArgs e)
    {
        if (e.Severity == XmlSeverityType.Error || e.Severity == XmlSeverityType.Warning)
        {
            _logger.LogError(e.Message);
            throw new Exception($"XML validation error: {e.Message}");
        }
    }

    private ConcurrentDictionary<string, XNamespace> GetNamespaces(XNode root)
    {
        var namespaces = new ConcurrentDictionary<string, XNamespace>();

        foreach (var ns in root.AncestorsAndSelf())
        {
            foreach (XAttribute attr in ns.Attributes())
            {
                if (attr.IsNamespaceDeclaration)
                {
                    namespaces[attr.Name.LocalName] = attr.Value;
                }
            }
        }

        return namespaces;
    }

    private string GetXmlDocumentPath()
    {
        // Assume path is read from external configuration
        return _config["xmlDocumentPath"];
    }

    private IEnumerable<XmlSchema> GetSchemasForVersion(string version)
    {
        // Fetch schemas from a database or file system based on the version
        throw new NotImplementedException();
    }
}

public class Configuration : IConfiguration
{
    public string this[string key] => System.IO.File.ReadAllText($"{key}.config");
}
```

