# json_base.py

import json
import threading
from abc import ABC, abstractmethod
from typing import Type, Dict, Any
from pathlib import Path
from functools import wraps
import yaml


class JSONBase(ABC):
    _registry_lock = threading.Lock()
    _factories: Dict[str, Type['JSONBase']] = {}

    def to_json(self) -> str:
        return json.dumps(self.__dict__, default=str)

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        # Validate against schema if needed
        return cls(**data)

    @classmethod
    def register_factory(cls, subclass: Type['JSONBase']):
        def decorator(func):
            with cls._registry_lock:
                cls._factories[subclass.__name__] = func

            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)

            return wrapper

        return decorator(subclass)

    @classmethod
    def discover_subclasses(cls, directory: str):
        for file in Path(directory).rglob('*.py'):
            if file.is_file():
                module_name = file.stem
                try:
                    __import__(module_name)
                    module = sys.modules[module_name]
                    for attribute_name in dir(module):
                        attribute = getattr(module, attribute_name)
                        if isinstance(attribute, type) and issubclass(attribute, cls) and attribute != cls:
                            with cls._registry_lock:
                                cls._factories[attribute.__name__] = attribute
                except Exception as e:
                    print(f"Error importing {module_name}: {e}")

    @classmethod
    def get_instance(cls, name: str, json_str: str):
        factory = cls._factories.get(name)
        if not factory:
            raise ValueError(f"No factory found for class '{name}'")
        try:
            return factory.from_json(json_str)
        except Exception as e:
            print(f"Error creating instance of {name}: {e}")
            raise

    @classmethod
    def load_from_yaml(cls, yaml_path: str):
        with open(yaml_path, 'r') as file:
            config = yaml.safe_load(file)
            for class_name, func in config.get('factories', {}).items():
                module_name, method_name = func.rsplit('.', 1)
                try:
                    module = __import__(module_name, fromlist=[method_name])
                    factory_func = getattr(module, method_name)
                    cls._factories[class_name] = factory_func
                except Exception as e:
                    print(f"Error loading {func} from YAML: {e}")

    @classmethod
    def save_to_file(cls, file_path: str):
        with open(file_path, 'w') as file:
            yaml.dump({'factories': cls._factories}, file)

# registry.py

