using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

public interface ICryptoServiceProvider
{
    (byte[] Key, byte[] IV) GetDecryptionCredentials(string context);
}

public class SecureMessageProcessor
{
    private readonly ILogger<SecureMessageProcessor> _logger;
    private readonly List<ICryptoServiceProvider> _cryptoServiceProviders = new();
    private readonly int _maxConcurrentRequests;

    public SecureMessageProcessor(ILogger<SecureMessageProcessor> logger, IEnumerable<ICryptoServiceProvider> providers, int maxConcurrentRequests)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        if (providers == null || !providers.Any())
            throw new ArgumentException("At least one Crypto Service Provider is required.", nameof(providers));

        _cryptoServiceProviders.AddRange(providers);
        _maxConcurrentRequests = maxConcurrentRequests;
    }

    public List<string> DecryptMessages(string context, List<string> encodedMessages)
    {
        if (encodedMessages == null || encodedMessages.Count == 0) return new List<string>();

        var decryptedMessages = new List<string>();
        var semaphore = new SemaphoreSlim(_maxConcurrentRequests);

        foreach (var message in encodedMessages)
        {
            semaphore.Wait();
            _ = Task.Run(async () =>
            {
                try
                {
                    string decryptedMessage = await DecryptMessageAsync(context, message);
                    if (!string.IsNullOrEmpty(decryptedMessage))
                        decryptedMessages.Add(decryptedMessage);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error decrypting message in context {Context}.", context);
                    AuditSecurityEvent("Decryption error", context, ex.Message);
                }
                finally
                {
                    semaphore.Release();
                }
            });
        }

        // Wait for all tasks to complete
        Task.WaitAll(Task.WhenAll(decryptedMessages).Result);

        return decryptedMessages;
    }

    private async Task<string> DecryptMessageAsync(string context, string encodedMessage)
    {
        foreach (var provider in _cryptoServiceProviders)
        {
            try
            {
                var (key, iv) = await Task.Run(() => provider.GetDecryptionCredentials(context));
                if (key == null || iv == null)
                    continue;

                return DecryptTripleDes(encodedMessage, key, iv);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Failed to retrieve credentials from CSP for context {Context}.", context);
            }
        }

        throw new InvalidOperationException("All service providers failed.");
    }

    private string DecryptTripleDes(string base64EncodedData, byte[] key, byte[] iv)
    {
        using var tripleDES = TripleDESCryptoServiceProvider.Create();
        tripleDES.Key = key;
        tripleDES.IV = iv;

        var cipherBytes = Convert.FromBase64String(base64EncodedData);
        using var decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV);

        using var ms = new MemoryStream(cipherBytes);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
        using var sr = new StreamReader(cs);

        return sr.ReadToEnd();
    }

    private void AuditSecurityEvent(string eventType, string context, string details)
    {
        // Implement security audit logging
        _logger.LogInformation("Security event {EventType} in context {Context}: {Details}", eventType, context, details);
    }
}

