```javascript
class AsyncReducer {
  constructor(limit = 5) {
    this.limit = limit;
    this.cache = new Map();
    this.activeTasks = 0;
    this.queue = [];
    this.isProcessingQueue = false;
  }

  async reduce(array, reducer, initialValue) {
    if (!Array.isArray(array)) throw new TypeError('Input must be an array');

    const numbers = array.map(item => {
      const parsedItem = parseInt(item, 10);
      if (isNaN(parsedItem)) throw new TypeError(`Invalid number: ${item}`);
      return parsedItem;
    });

    const asyncReduce = async (arr, initial) => {
      if (!Array.isArray(arr) || arr.length === 0) return initial;

      if (this.cache.has(JSON.stringify(arr))) {
        console.log('Cache hit for subarray', JSON.stringify(arr));
        return this.cache.get(JSON.stringify(arr));
      }

      const task = async () => {
        try {
          while (arr.length > 1 && this.activeTasks < this.limit) {
            this.activeTasks++;
            await this.processBatch(arr);
          }
          if (arr.length === 1) {
            return arr[0];
          } else {
            throw new Error('Reduction incomplete');
          }
        } finally {
          this.activeTasks--;
          this.processQueue();
        }
      };

      return task().then(result => {
        this.cache.set(JSON.stringify(arr), result);
        console.log('Reduced subarray', JSON.stringify(arr));
        return result;
      });
    };

    async function processBatch(subArray) {
      for (let i = 0; i < subArray.length - 1; i += 2) {
        const [a, b] = subArray.slice(i, i + 2);
        if (!reducer(a, b)) throw new Error('Reduction failed due to invalid operation');
        subArray[i] = reducer(a, b);
      }
      subArray.splice(subArray.length - Math.floor((subArray.length + 1) / 2));
    }

    this.processQueue = () => {
      if (!this.isProcessingQueue && this.queue.length > 0) {
        this.isProcessingQueue = true;
        this.queue.shift()().then(() => {
          this.isProcessingQueue = false;
          this.processQueue();
        });
      }
    };

    const initialPromise = asyncReduce(numbers, initialValue);

    return initialPromise.catch(error => {
      console.error('Reduction error:', error.message);
      throw error;
    });
  }

  queueTask(task) {
    this.queue.push(task);
    if (!this.isProcessingQueue && this.activeTasks < this.limit) {
      this.processQueue();
    }
  }
}

// Usage Example
const reducer = new AsyncReducer(10);

async function runExample() {
  const numbersArray = ['1', '2', '3', '4', '5'];
  try {
    const result = await reducer.reduce(numbersArray, (a, b) => a + b, 0);
    console.log('Final Result:', result);
  } catch (error) {
    console.error('Error during reduction:', error.message);
  }
}

runExample();

// Test Cases
function testCases() {
  const tests = [
    { input: ['1', '2', '3'], initialValue: 0, expected: 6 },
    { input: ['1000000000000000', '2000000000000000'], initialValue: 0, expected: 3000000000000000 },
    { input: [], initialValue: 10, expected: 10 },
    { input: ['1', '2', 'three'], initialValue: 0 } // Should throw error
  ];

  tests.forEach(({ input, initialValue, expected }, index) => {
    (async () => {
      try {
        const result = await reducer.reduce(input, (a, b) => a + b, initialValue);
        console.assert(result === expected, `Test ${index} failed: Expected ${expected}, got ${result}`);
        console.log(`Test ${index} passed.`);
      } catch (error) {
        if (input.includes('three')) {
          console.log(`Test ${index} correctly threw an error for invalid input.`);
        } else {
          console.error(`Test ${index} failed with error:`, error.message);
        }
      }
    })();
