```python
import json
from datetime import datetime
from decimal import Decimal
from uuid import UUID

class JSONSerializable:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, type_name, factory_func):
        cls._factory_registry[type_name] = factory_func

    @classmethod
    def unregister_factory(cls, type_name):
        if type_name in cls._factory_registry:
            del cls._factory_registry[type_name]

    @staticmethod
    def _custom_encoder(obj):
        if isinstance(obj, datetime):
            return {'_type': 'datetime', 'value': obj.isoformat()}
        elif isinstance(obj, Decimal):
            return {'_type': 'decimal', 'value': str(obj)}
        elif isinstance(obj, UUID):
            return {'_type': 'uuid', 'value': str(obj)}
        raise TypeError(f"Object of type {obj.__class__.__name__} is not JSON serializable")

    @staticmethod
    def _custom_decoder(dct):
        if '_type' in dct:
            type_name = dct['_type']
            value = dct['value']
            factory_func = JSONSerializable._factory_registry.get(type_name)
            if factory_func:
                return factory_func(value)
            raise ValueError(f"Unsupported type: {type_name}")
        return dct

    @classmethod
    def to_json(cls, obj):
        try:
            return json.dumps(obj, default=cls._custom_encoder)
        except (TypeError, ValueError) as e:
            raise ValueError(f"Error serializing object: {e}")

    @classmethod
    def from_json(cls, json_str):
        try:
            return json.loads(json_str, object_hook=cls._custom_decoder)
        except (json.JSONDecodeError, ValueError) as e:
            raise ValueError(f"Error deserializing JSON string: {e}")

# Factory functions for custom types
def datetime_factory(value):
    return datetime.fromisoformat(value)

def decimal_factory(value):
    return Decimal(value)

def uuid_factory(value):
    return UUID(value)

# Register factory functions
JSONSerializable.register_factory('datetime', datetime_factory)
JSONSerializable.register_factory('decimal', decimal_factory)
JSONSerializable.register_factory('uuid', uuid_factory)

# Example usage:
if __name__ == "__main__":
    data = {
        "timestamp": datetime.now(),
        "price": Decimal("123.45"),
        "transaction_id": UUID('12345678123456781234567812345678')
    }

    json_str = JSONSerializable.to_json(data)
    print(json_str)

    deserialized_data = JSONSerializable.from_json(json_str)
    print(deserialized_data)
