// Define the available cryptographic primitives.
#define PRIMITIVE_AES 1
#define PRIMITIVE_CAMELLIA 2
#define PRIMITIVE_MD5 3
#define PRIMITIVE_SHA1 4
#define PRIMITIVE_SHA256 5
#define PRIMITIVE_CHACHA20 6
#define PRIMITIVE_POLY1305 7
#define PRIMITIVE_BLAKE2B 8

typedef struct {
    int primitive_id;
    char *name;
    void *handle; // Handle for the cryptographic module.
} CryptoPrimitive;

// Global variables and mutex for thread safety.
static pthread_mutex_t crypto_lib_lock = PTHREAD_MUTEX_INITIALIZER;
static CryptoPrimitive **crypto_primitives = NULL;
static size_t num_primitives = 0;

// Function to check if a primitive is already added.
int is_primitive_added(int id) {
    for (size_t i = 0; i < num_primitives; ++i) {
        if (crypto_primitives[i]->primitive_id == id)
            return 1;
    }
    return 0;
}

// Function to add a cryptographic primitive.
void add_crypto_primitive(CryptoPrimitive *new_primitive) {
    pthread_mutex_lock(&crypto_lib_lock);

    // Check for existing primitive
    if (!is_primitive_added(new_primitive->primitive_id)) {
        crypto_primitives = realloc(crypto_primitives, (num_primitives + 1) * sizeof(CryptoPrimitive *));
        if (crypto_primitives == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&crypto_lib_lock);
            return;
        }
        crypto_primitives[num_primitives] = new_primitive;
        num_primitives++;
    }

    pthread_mutex_unlock(&crypto_lib_lock);
}

// Function to remove a cryptographic primitive.
void remove_crypto_primitive(int id) {
    pthread_mutex_lock(&crypto_lib_lock);

    for (size_t i = 0; i < num_primitives; ++i) {
        if (crypto_primitives[i]->primitive_id == id) {
            free(crypto_primitives[i]);
            memmove(&crypto_primitives[i], &crypto_primitives[i + 1], (num_primitives - i - 1) * sizeof(CryptoPrimitive *));
            num_primitives--;
            crypto_primitives = realloc(crypto_primitives, num_primitives * sizeof(CryptoPrimitive *));
            break;
        }
    }

    pthread_mutex_unlock(&crypto_lib_lock);
}

// Function to load configuration file and update primitives.
void load_config_and_update() {
    // Placeholder for loading and decrypting the config file securely
    // Implement secure key exchange mechanism here

    // Example: Add ChaCha20 if available
    #ifdef CHACHA20_AVAILABLE
        CryptoPrimitive *chacha20 = malloc(sizeof(CryptoPrimitive));
        chacha20->primitive_id = PRIMITIVE_CHACHA20;
        chacha20->name = "ChaCha20";
        chacha20->handle = NULL; // Initialize the handle with actual library call
        add_crypto_primitive(chacha20);
    #endif

    // Similar checks and additions for other primitives...
}

// Function to initialize the cryptographic library.
void init_crypto_library() {
    pthread_mutex_init(&crypto_lib_lock, NULL);

    // Add existing primitives.
    CryptoPrimitive *aes = malloc(sizeof(CryptoPrimitive));
    aes->primitive_id = PRIMITIVE_AES;
    aes->name = "AES";
    aes->handle = NULL; // Initialize with actual library call
    add_crypto_primitive(aes);

    // Add other default primitives...
}

// Function to clean up the cryptographic library.
void cleanup_crypto_library() {
    pthread_mutex_lock(&crypto_lib_lock);

    for (size_t i = 0; i < num_primitives; ++i) {
        free(crypto_primitives[i]);
    }
    free(crypto_primitives);
    crypto_primitives = NULL;
    num_primitives = 0;

    pthread_mutex_unlock(&crypto_lib_lock);
    pthread_mutex_destroy(&crypto_lib_lock);
}

// Main function to demonstrate usage.
int main() {
    init_crypto_library();

    // Simulate loading configuration and updating primitives.
    load_config_and_update();

    cleanup_crypto_library();
    return 0;
}
