```java
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class ConfigurationManager {
    private static final Logger logger = LoggerFactory.getLogger(ConfigurationManager.class);

    private final ObjectMapper objectMapper = new ObjectMapper();
    private final Map<String, ConfigurationParser> parserRegistry = new ConcurrentHashMap<>();
    private final ExecutorService hashExecutor;
    private final ConcurrentMap<String, String> configurationCache;
    private final int maxThreads;
    private final int cacheSize;

    public ConfigurationManager(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.hashExecutor = Executors.newFixedThreadPool(maxThreads);
        this.configurationCache = new ConcurrentMapBuilder()
                .initialCapacity(cacheSize)
                .concurrencyLevel(16)
                .loadFactor(0.75f)
                .build(ConcurrentLinkedQueue::new, () -> new LinkedHashMap<>(16, 0.75f, true) {
                    @Override
                    protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                        return size() > cacheSize;
                    }
                });
    }

    public void addConfigurationParser(String type, ConfigurationParser parser) {
        parserRegistry.put(type, parser);
    }

    public <T> T parseConfiguration(String type, byte[] configData, Class<T> clazz) throws Exception {
        ConfigurationParser parser = parserRegistry.get(type);
        if (parser == null) {
            throw new IllegalArgumentException("No parser registered for configuration type: " + type);
        }
        String configJson = new String(configData, StandardCharsets.UTF_8);
        return objectMapper.readValue(parser.parse(configJson), clazz);
    }

    public Future<String> computeHash(String algorithm, String data) {
        Objects.requireNonNull(data, "Configuration string cannot be null");
        if (data.length() > 1000) {
            logger.warn("Configuration string is very large. Efficient handling applied.");
        }
        return hashExecutor.submit(() -> {
            try {
                MessageDigest digest = MessageDigest.getInstance(algorithm);
                byte[] encodedhash = digest.digest(data.getBytes(StandardCharsets.UTF_8));
                StringBuilder hexString = new StringBuilder();
                for (byte b : encodedhash) {
                    String hex = Integer.toHexString(0xff & b);
                    if (hex.length() == 1) hexString.append('0');
                    hexString.append(hex);
                }
                return hexString.toString();
            } catch (Exception e) {
                logger.error("Error computing hash: ", e);
                throw new RuntimeException(e);
            }
        });
    }

    public void updateConfiguration(String key, String value) {
        configurationCache.put(key, value);
        notifyServicesAboutUpdate(key, value);
    }

    private void notifyServicesAboutUpdate(String key, String value) {
        // Logic to notify connected services about the updated configuration
        logger.info("Configuration for {} has been updated.", key);
    }

    public String getConfiguration(String key) {
        return configurationCache.get(key);
    }

    public int getMaxThreads() {
        return maxThreads;
    }

    public void setMaxThreads(int maxThreads) {
        this.maxThreads = maxThreads;
        this.hashExecutor.shutdown();
        try {
            if (!this.hashExecutor.awaitTermination(800, TimeUnit.MILLISECONDS)) {
                this.hashExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            this.hashExecutor.shutdownNow();
        }
        this.hashExecutor = Executors.newFixedThreadPool(maxThreads);
    }

    public int getCacheSize() {
        return cacheSize;
    }

    public void setCacheSize(int cacheSize) {
        this.cacheSize = cacheSize;
        // Rebuild the cache with new size
        configurationCache = new ConcurrentMapBuilder()
                .initialCapacity(cacheSize)
                .concurrencyLevel(16)
                .loadFactor(0.75f)
                .build(ConcurrentLinkedQueue::new, () -> new LinkedHashMap<>(16, 0.75f, true) {
                    @Override
                    protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                        return size() > cacheSize;
                    }
                });
    }

    public interface ConfigurationParser<T> {
        String parse(String json);
    }
}

