const exec = require('child_process').exec;
const crypto = require('crypto');

// Setup Redis client with thread-safe operations and cache eviction policies
const redisClient = redis.createClient({ no_ready_check: true });
const getAsync = promisify(redisClient.get).bind(redisClient);
const setAsync = promisify(redisClient.set).bind(redisClient);

redisClient.on('error', (err) => console.error('Redis error:', err));

// Configuration file and logging setup
const CONFIG_FILE = './config.json';
let processedFilesCount = 0;
const logFile = fs.createWriteStream('./server.log', { flags: 'a' });

function log(message) {
    const timestamp = new Date().toISOString();
    logFile.write(`${timestamp} - ${message}\n`);
}

// Rate-limiting mechanism
const rateLimits = {
    default: { limit: 10, period: 60 },
    // Add role-specific and location-based limits as needed
};

function checkRateLimit(clientAddress) {
    const now = Date.now();
    let requestTimes = rateLimits.default;

    getAsync(`rate:${clientAddress}`)
        .then((data) => {
            if (data) {
                requestTimes = JSON.parse(data);
            }

            const currentTime = now / 1000;
            requestTimes.timestamps = requestTimes.timestamps.filter(ts => ts > currentTime - requestTimes.period);

            if (requestTimes.timestamps.length >= requestLimits.limit) {
                throw new Error('Rate limit exceeded');
            }

            requestTimes.timestamps.push(currentTime);
            setAsync(`rate:${clientAddress}`, JSON.stringify(requestTimes), 'EX', requestLimits.period + 1);
        })
        .catch(err => log(`Error in rate limiting for ${clientAddress}: ${err.message}`));
}

// Load configuration file
let config;
try {
    const configData = fs.readFileSync(CONFIG_FILE, 'utf-8');
    config = JSON.parse(configData);
} catch (error) {
    log(`Failed to load configuration: ${error.message}`);
}

// Function to process files and handle symbolic links
async function processFiles() {
    for (const entry of config.files) {
        const filePath = path.resolve(entry.path);

        if (fs.lstatSync(filePath).isSymbolicLink()) {
            if (!entry.followSymlinks) continue;
        }

        try {
            await new Promise((resolve, reject) => {
                exec(entry.command, { cwd: path.dirname(filePath) }, (error, stdout, stderr) => {
                    if (error) return reject(error);
                    console.log(stdout);
                    resolve();
                });
            });

            processedFilesCount++;
        } catch (err) {
            log(`Error processing file ${filePath}: ${err.message}`);
        }
    }

    const timestamp = Date.now().toString();
    fs.renameSync(CONFIG_FILE, `${CONFIG_FILE}.${timestamp}-${processedFilesCount}.bak`);
}

// Server setup using net
const server = net.createServer((socket) => {
    const clientAddress = socket.remoteAddress + ':' + socket.remotePort;

    log(`Connection from ${clientAddress}`);

    checkRateLimit(clientAddress).catch(err => {
        socket.write(`${err.message}\n`);
        socket.end();
    });

    socket.on('data', async (data) => {
        try {
            const command = data.toString().trim();

            switch (command) {
                case 'getMetadata':
                    // Retrieve metadata from Redis
                    const key = `${clientAddress}:metadata`;
                    const metadata = await getAsync(key);
                    if (!metadata) throw new Error('No metadata found');

                    socket.write(metadata + '\n');
                    break;
                case 'setMetadata':
                    // Set metadata in Redis, ensuring thread safety
                    const metadataValue = data.slice(13).toString().trim();  // Assuming key is fixed length
                    await setAsync(`${clientAddress}:metadata`, metadataValue);
                    log(`Metadata set for ${clientAddress}`);
                    socket.write('Metadata updated\n');
                    break;
                default:
                    throw new Error('Unknown command');
            }
        } catch (err) {
            log(`Error handling client data: ${err.message}`);
            socket.write(`${err.message}\n`);
        }

    });

    socket.on('end', () => log(`Connection closed for ${clientAddress}`));
    socket.on('error', (err) => log(`Socket error: ${err.message}`));

}).on('error', (err) => log(`Server error: ${err.message}`))
  .listen(8080, () => log('Server listening on port 8080'));

