const dbStoreFinalResult = async (result) => console.log(`Storing result: ${result}`);

// Rate limiter configuration
const maxConcurrentQueries = 5;
const limiter = rateLimit(maxConcurrentQueries);

async function reduceAsync(array, initialValueCallback, reducerCallback, errorCallback) {
    try {
        // Fetch initial value from database asynchronously
        const initialValue = await promisify(initialValueCallback)();

        let accumulatedValue = initialValue;

        // Process array elements in parallel with error handling and concurrency control
        const processElement = async (element) => {
            return limiter(async () => {
                if (typeof element !== 'number') throw new Error('Non-numeric value encountered');
                return promisify(reducerCallback)(accumulatedValue, element);
            });
        };

        for (const number of array) {
            try {
                accumulatedValue = await processElement(number);
            } catch (error) {
                errorCallback(error.message);
                // Optionally handle specific logic on error
                break;
            }
        }

        // Store the final result in database
        await promisify(dbStoreFinalResult)(accumulatedValue);

        return accumulatedValue;

    } catch (err) {
        errorCallback(`Error during processing: ${err.message}`);
        throw err;  // Rethrow or handle as appropriate for your use case
    }
}

// Test cases
