Below is a high-level implementation outline in C for the described semaphore management system. This code provides a basic structure and does not cover all details due to complexity constraints but gives you a starting point.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <json-c/json.h>
#include <unistd.h>

#define MAX_SEMAPHORES 100
#define LOG_FILE "semaphore_log.txt"

typedef struct {
    sem_t semaphore;
    int value;
    int max_value;
    int priority;
    pthread_mutex_t lock;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int num_semaphores = 0;

// Utility function to log operations
void log_operation(const char* operation, int sem_id, pid_t pid, pthread_t tid, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "[%ld] Operation: %s, Semaphore ID: %d, PID: %d, TID: %lu\n",
                (long)timestamp, operation, sem_id, pid, tid);
        fclose(log_file);
    }
}

// Configuration loading
void load_configuration(const char* config_path) {
    // Load JSON configuration and populate semaphores array
    FILE *file = fopen(config_path, "r");
    if (!file) return;

    struct json_object *parsed_json;
    struct json_object *sem_array;
    size_t n_sems;
    parsed_json = json_object_from_file(file);
    json_object_object_get_ex(parsed_json, "semaphores", &sem_array);

    n_sems = json_object_array_length(sem_array);
    for (size_t i = 0; i < n_sems && num_semaphores < MAX_SEMAPHORES; ++i) {
        struct json_object *sem_obj;
        sem_obj = json_object_array_get_idx(sem_array, i);

        const char* name;
        int value, max_value, priority;
        json_object_object_get_ex(sem_obj, "name", &json_str);
        name = json_object_get_string(json_str);

        json_object_object_get_ex(sem_obj, "value", &json_int);
        value = json_object_get_int(json_int);

        json_object_object_get_ex(sem_obj, "max_value", &json_int);
        max_value = json_object_get_int(json_int);

        json_object_object_get_ex(sem_obj, "priority", &json_int);
        priority = json_object_get_int(json_int);

        if (num_semaphores < MAX_SEMAPHORES) {
            semaphores[num_semaphores].value = value;
            semaphores[num_semaphores].max_value = max_value;
            semaphores[num_semaphores].priority = priority;
            sem_init(&semaphores[num_semaphores].semaphore, 0, value);
            pthread_mutex_init(&semaphores[num_semaphores].lock, NULL);
            num_semaphores++;
        }
    }

    fclose(file);
}

// Semaphore operations with timeout and logging
int semaphore_wait(int sem_id, int timeout_ms) {
    if (sem_id < 0 || sem_id >= num_semaphores) return -1;

    time_t start_time = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        pthread_mutex_lock(&semaphores[sem_id].lock);
        if (semaphores[sem_id].value > 0) {
            semaphores[sem_id].value--;
            pthread_mutex_unlock(&semaphores[sem_id].lock);
            log_operation("wait", sem_id, getpid(), pthread_self(), time(NULL));
            return 0;
        }
        pthread_mutex_unlock(&semaphores[sem_id].lock);

        ts.tv_sec += timeout_ms / 1000;
        ts.tv_nsec += (timeout_ms % 1000) * 1000000;

        if (ts.tv_nsec >= 1000000000) {
            ts.tv_nsec -= 1000000000;
            ts.tv_sec++;
        }

        int ret = sem_timedwait(&semaphores[sem_id].semaphore, &ts);
        if (ret != -1 || time(NULL) - start_time > timeout_ms / 1000) break;
    }
    log_operation("timeout_wait", sem_id, getpid(), pthread_self(), time(NULL));
    return -1;
}

int semaphore_post(int sem_id) {
    if (sem_id < 0 || sem_id >= num_semaphores) return -1;

    pthread_mutex_lock(&semaphores[sem_id].lock);
    if (semaphores[sem_id].value < semaphores[sem_id].max_value) {
        semaphores[sem_id].value++;
        pthread_mutex_unlock(&semaphores[sem_id].lock);
        log_operation("post", sem_id, getpid(), pthread_self(), time(NULL));
        return 0;
    }
    pthread_mutex_unlock(&semaphores[sem_id].lock);
    return -1;
}

// Further implementation required for distributed support, failover, and dynamic scaling

int main() {
    load_configuration("config.json");

    // Example usage
    semaphore_wait(0, 5000); // Wait with timeout
    semaphore_post(0);

    // Cleanup
    for (int i = 0; i < num_semaphores; ++i) {
        sem_destroy(&semaphores[i].semaphore);
        pthread_mutex_destroy(&semaphores[i].lock);
    }

    return 0;
}
```

