<?php

class FileStorageManager {

    private $maxFileSize = 10485760; // Example: 10 MB max size
    private $logFilePath = '/path/to/log/file.log';

    public function validateFileExtension($file, $allowedExtensions) {
        $fileExt = pathinfo($file['name'], PATHINFO_EXTENSION);
        return in_array('.' . strtolower($fileExt), array_map('strtolower', $allowedExtensions));
    }

    public function resizeImage($file, $maxWidth, $maxHeight) {
        list($origWidth, $origHeight) = getimagesize($file['tmp_name']);

        $ratio = min($maxWidth / $origWidth, $maxHeight / $origHeight);
        $newWidth  = $origWidth * $ratio;
        $newHeight = $origHeight * $ratio;

        $imageResized = imagecreatetruecolor($newWidth, $newHeight);

        switch ($file['type']) {
            case 'image/jpeg':
                $imageOriginal = imagecreatefromjpeg($file['tmp_name']);
                break;
            case 'image/png':
                $imageOriginal = imagecreatefrompng($file['tmp_name']);
                break;
            default:
                throw new Exception("Unsupported image type.");
        }

        imagecopyresampled($imageResized, $imageOriginal, 0, 0, 0, 0, $newWidth, $newHeight, $origWidth, $origHeight);

        switch ($file['type']) {
            case 'image/jpeg':
                imagejpeg($imageResized, $file['tmp_name']);
                break;
            case 'image/png':
                imagepng($imageResized, $file['tmp_name']);
                break;
        }
    }

    public function uploadFile($file, $destinationPath) {
        if ($file['size'] > $this->maxFileSize) {
            throw new Exception("File exceeds maximum size.");
        }

        $filePath = rtrim($destinationPath, '/') . '/' . basename($file['name']);

        if (file_exists($filePath)) {
            throw new Exception("File already exists.");
        }

        $uploadAttempts = 3;
        while ($uploadAttempts > 0) {
            try {
                if (!move_uploaded_file($file['tmp_name'], $filePath)) {
                    throw new Exception("Upload failed.");
                }
                break;
            } catch (Exception $e) {
                $uploadAttempts--;
                sleep(1); // Wait a bit before retrying
                if ($uploadAttempts === 0) {
                    throw $e;
                }
            }
        }

        $this->logUploadAttempt($file, "Success");
    }

    public function downloadFile($filePath, $mimeType, $attachmentName) {
        if (!file_exists($filePath)) {
            throw new Exception("File not found.");
        }

        header('Content-Description: File Transfer');
        header('Content-Type: ' . $mimeType);
        header('Content-Disposition: attachment; filename="' . basename($attachmentName) . '"');
        header('Expires: 0');
        header('Cache-Control: must-revalidate');
        header('Pragma: public');
        header('Content-Length: ' . filesize($filePath));

        readfile($filePath);
    }

    public function deleteFile($filePath) {
        if (!file_exists($filePath)) {
            throw new Exception("File not found.");
        }

        if (!unlink($filePath)) {
            throw new Exception("Failed to delete file.");
        }
    }

    public function moveFile($sourcePath, $destinationPath) {
        if (!rename($sourcePath, $destinationPath)) {
            throw new Exception("Move failed.");
        }
    }

    public function renameFile($oldFilePath, $newFilePath) {
        if (file_exists($newFilePath)) {
            throw new Exception("File already exists at destination.");
        }

        if (!rename($oldFilePath, $newFilePath)) {
            throw new Exception("Rename failed.");
        }
    }

    public function secureFileUpload($file) {
        $allowedExtensions = ['jpg', 'png', 'pdf'];
        if (!$this->validateFileExtension($file, $allowedExtensions)) {
            throw new Exception("Invalid file extension.");
        }

        if (in_array(strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)), ['jpeg', 'jpg', 'png'])) {
            $this->resizeImage($file, 800, 600); // Example dimensions
        }

        $destinationPath = '/path/to/destination';
        $this->uploadFile($file, $destinationPath);
    }

    public function logUploadAttempt($fileDetails, $status) {
        $logEntry = date('Y-m-d H:i:s') . " - File: " . basename($fileDetails['name']) . 
                    ", Size: " . $fileDetails['size'] . " bytes, Status: " . $status . PHP_EOL;

        file_put_contents($this->logFilePath, $logEntry, FILE_APPEND);
    }

    public function updateFilePolicy($newPolicies) {
        // Assume implementation for updating policies
    }
}

