import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class JsonParser {
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Map<String, JsonNode> cache = new HashMap<>();

    public static Optional<JsonNode> extractData(String jsonDocument, String... path) throws IOException {
        try {
            if (cache.containsKey(pathToString(path))) {
                return Optional.ofNullable(cache.get(pathToString(path)));
            }

            JsonNode rootNode = mapper.readTree(jsonDocument);
            JsonNode resultNode = parseNode(rootNode, path);

            cache.put(pathToString(path), resultNode);
            return Optional.of(resultNode);
        } catch (IOException e) {
            System.err.println("Error parsing JSON: " + e.getMessage());
            return Optional.empty();
        }
    }

    private static JsonNode parseNode(JsonNode node, String[] path) throws IOException {
        if (path.length == 0 || !node.isObject()) {
            return null;
        }

        String key = path[0];
        JsonNode childNode = node.get(key);
        if (childNode == null && !key.contains("[")) {
            throw new IllegalArgumentException("Key not found: " + key);
        }

        // Handle array indices
        int indexStart = key.indexOf('[');
        if (indexStart != -1) {
            int indexEnd = key.indexOf(']', indexStart);
            String indexStr = key.substring(indexStart + 1, indexEnd);
            int index = Integer.parseInt(indexStr.trim());
            childNode = childNode.get(index);
        }

        return path.length > 1 ? parseNode(childNode, java.util.Arrays.copyOfRange(path, 1, path.length)) : childNode;
    }

    private static String pathToString(String[] path) {
        StringBuilder sb = new StringBuilder();
        for (String p : path) {
            sb.append(p).append("->");
        }
        return sb.toString();
    }

