public class FileUploadService
{
    private readonly IAuthenticationService _authService;
    private readonly IDataStorageService _storageService;
    private readonly ICachingService _cachingService;
    private readonly IDistributedQueue _queue;

    public FileUploadService(IAuthenticationService authService, IDataStorageService storageService,
                             ICachingService cachingService, IDistributedQueue queue)
    {
        _authService = authService;
        _storageService = storageService;
        _cachingService = cachingService;
        _queue = queue;
    }

    public async Task UploadFileAsync(string userId, string filePath, byte[] fileData)
    {
        // Implement chunking and parallel processing
        var chunks = ChunkFile(fileData);
        foreach (var chunk in chunks)
        {
            await _storageService.StoreChunkAsync(userId, Path.GetFileName(filePath), chunk);
        }

        // Notify background tasks for indexing
        _queue.Enqueue(new BackgroundTask { TaskType = "Index", FilePath = filePath });
    }

    private IEnumerable<byte[]> ChunkFile(byte[] data)
    {
        const int chunkSize = 1024 * 1024; // 1MB
        for (int i = 0; i < data.Length; i += chunkSize)
        {
            yield return data[i..Math.Min(i + chunkSize, data.Length)];
        }
    }

    public async Task<IEnumerable<string>> ListFilesAsync(string userId)
    {
        var metadataKeys = await _cachingService.GetCachedMetadataKeysAsync(userId);
        if (metadataKeys != null)
        {
            return metadataKeys;
        }

        var files = await _storageService.ListUserFilesAsync(userId);
        foreach (var file in files)
        {
            _cachingService.CacheMetadataKey(file);
        }

        return files;
    }
}

