Below is a simplified implementation of the `ImageProcessor` class based on your requirements:

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <memory>
#include <dlfcn.h> // For dynamic loading

class ImageProcessor {
public:
    struct ConversionTask {
        std::string inputPath;
        std::string outputPath;
        std::string format;
        int quality;
    };

    ImageProcessor(const std::string& logConfig)
        : logToFile(logConfig == "file"), logger(logToFile ? logFile : &std::cout) {}

    ~ImageProcessor() {
        if (logToFile) logFile.close();
    }

    void batchConvertAndSave(const std::vector<ConversionTask>& tasks, int numThreads);

private:
    bool loadLibrary(const std::string& libraryPath);
    void unloadLibrary();

    void convertImages(const std::vector<ConversionTask>& tasks);
    void workerFunction(const std::vector<ConversionTask>& taskBatch);

    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        logger << message << std::endl;
    }

    void* libraryHandle = nullptr;
    bool logToFile = false;
    std::ofstream logFile;
    std::ostream* logger;
    std::mutex logMutex;

    // Example third-party function pointers
    typedef int (*convertImageFunction)(const char*, const char*, const char*, int);
    convertImageFunction convertImage;
};

bool ImageProcessor::loadLibrary(const std::string& libraryPath) {
    libraryHandle = dlopen(libraryPath.c_str(), RTLD_LAZY);
    if (!libraryHandle) {
        log("Failed to load library: " + std::string(dlerror()));
        return false;
    }
    convertImage = (convertImageFunction)dlsym(libraryHandle, "convert_image");
    if (!convertImage) {
        log("Failed to find function 'convert_image': " + std::string(dlerror()));
        unloadLibrary();
        return false;
    }
    return true;
}

void ImageProcessor::unloadLibrary() {
    if (libraryHandle) {
        dlclose(libraryHandle);
        libraryHandle = nullptr;
    }
}

void ImageProcessor::batchConvertAndSave(const std::vector<ConversionTask>& tasks, int numThreads) {
    log("Batch conversion started.");

    std::vector<std::thread> threads;
    size_t batchSize = tasks.size() / numThreads + (tasks.size() % numThreads != 0);

    for (size_t i = 0; i < numThreads && i * batchSize < tasks.size(); ++i) {
        auto taskBatch = std::vector<ConversionTask>(tasks.begin() + i * batchSize,
                                                     tasks.begin() + std::min((i + 1) * batchSize, tasks.size()));
        threads.emplace_back(&ImageProcessor::workerFunction, this, taskBatch);
    }

    for (auto& thread : threads) {
        if (thread.joinable()) thread.join();
    }

    log("Batch conversion completed.");
}

void ImageProcessor::convertImages(const std::vector<ConversionTask>& tasks) {
    for (const auto& task : tasks) {
        log("Converting: " + task.inputPath);
        int result = convertImage(task.inputPath.c_str(), task.outputPath.c_str(), task.format.c_str(), task.quality);
        if (result == 0) {
            log("Conversion successful: " + task.outputPath);
        } else {
            log("Conversion failed for: " + task.inputPath);
        }
    }
}

void ImageProcessor::workerFunction(const std::vector<ConversionTask>& taskBatch) {
    convertImages(taskBatch);
}
```

### Key Points:
- **Dynamic Library Loading**: Uses `dlopen` and `dlsym` to dynamically load the third-party library.
- **Multi-threading**: Splits tasks into batches processed by separate threads.
- **Logging**: Logs messages either to a file or console, ensuring thread safety with mutexes.
- **RAII**: Manages resources like library handles using RAII principles.

