- This is a simplified version and assumes the presence of a `convert_image` function in the third-party library.
- Error handling and network considerations (e.g., remote image access) are not fully implemented here but should be considered in a complete solution.

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;

public class MessageProcessor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly IConnection _connection;
    private readonly IModel _channel;

    public MessageProcessor(string key, string iv)
    {
        _key = Convert.FromBase64String(key);
        _iv = Convert.FromBase64String(iv);

        var factory = new ConnectionFactory() { HostName = "localhost" };
        _connection = factory.CreateConnection();
        _channel = _connection.CreateModel();
        _channel.QueueDeclare(queue: "logs", durable: false, exclusive: false, autoDelete: false, arguments: null);
    }

    public void ProcessMessages(IEnumerable<string> encodedMessages)
    {
        Parallel.ForEach(encodedMessages, (encodedMessage) =>
        {
            try
            {
                var decryptedMessage = DecryptAndValidate(encodedMessage);

                if (!string.IsNullOrEmpty(decryptedMessage))
                {
                    LogMessage($"Decryption successful: {decryptedMessage}");
                }
                else
                {
                    LogMessage("Authentication failure.");
                }
            }
            catch (Exception ex)
            {
                LogMessage($"Error processing message: {ex.Message}");
            }
        });
    }

    private string DecryptAndValidate(string encodedMessage)
    {
        if (!Base64EncodedIsMultipleOfFour(encodedMessage))
        {
            throw new InvalidDataException("Invalid Base64 encoding.");
        }

        var encryptedBytes = Convert.FromBase64String(encodedMessage);

        using (var decryptor = TripleDES.Create().CreateDecryptor(_key, _iv))
        {
            var decryptedBytes = PerformCryptography(encryptedBytes, decryptor);

            if (!ValidateHmac(decryptedBytes, encryptedBytes))
                throw new InvalidDataException("HMAC validation failed.");

            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using var memoryStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))
        {
            cryptoStream.Write(data, 0, data.Length);
        }
        return memoryStream.ToArray();
    }

    private bool ValidateHmac(byte[] message, byte[] encrypted)
    {
        var hmac = new HMACSHA256(_key);

        var computedHash = hmac.ComputeHash(message);
        var embeddedHash = encrypted.Take(computedHash.Length).ToArray();

        return computedHash.SequenceEqual(embeddedHash);
    }

    private void LogMessage(string logEntry)
    {
        var body = Encoding.UTF8.GetBytes(logEntry + Environment.NewLine);
        _channel.BasicPublish(exchange: "", routingKey: "logs", basicProperties: null, body: body);
    }

    public static bool Base64EncodedIsMultipleOfFour(string base64)
    {
        return (base64.Length % 4) == 0;
    }

    public void InsertAfterFirstOccurrence(ConcurrentQueue<string> queue, string firstString, string secondString)
    {
        var tempQueue = new ConcurrentQueue<string>();

        bool found = false;

        while (!queue.IsEmpty && !found)
        {
            if (queue.TryDequeue(out var item) && item == firstString)
            {
                tempQueue.Enqueue(item);
                tempQueue.Enqueue(secondString);
                found = true;
            }
            else
            {
                tempQueue.Enqueue(item);
            }
        }

        while (!tempQueue.IsEmpty && !queue.IsEmpty)
        {
            if (!queue.TryDequeue(out _))
            {
                break;
            }
        }

        while (tempQueue.TryDequeue(out var dequeuedItem))
        {
            queue.Enqueue(dequeuedItem);
        }

        if (!found)
        {
            queue.Enqueue(secondString);
        }
    }

    ~MessageProcessor()
    {
        _channel?.Dispose();
        _connection?.Close();
    }
}

// Unit tests can be written using a testing framework like NUnit or xUnit.
```

