// A simple caching mechanism using an object
const elementCache = {};

/**
 * Recursively traverses the DOM tree and returns elements matching the selector.
 *
 * @param {HTMLElement} root - The root node for traversal.
 * @param {string} selector - CSS selector to match elements.
 * @param {Object} [attributes={}] - Additional attributes for filtering (e.g., `{ 'data-type': 'example', 'aria-label': 'label' }`).
 * @returns {Promise<Array>} A list of matching elements.
 */
async function findElements(root, selector, attributes = {}) {
  if (!root || !selector) return [];

  // Check cache first
  const cacheKey = `${root.tagName}-${selector}-${JSON.stringify(attributes)}`;
  if (elementCache[cacheKey]) {
    console.log('Returning cached result');
    return elementCache[cacheKey];
  }

  let elements = [];

  function traverse(node) {
    try {
      if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

      // Check for selector match and additional attributes
      const matchesSelector = node.matches(selector);
      const matchesAttributes = Object.keys(attributes).every(key =>
        node.getAttribute(key) === attributes[key]
      );

      if (matchesSelector && matchesAttributes) {
        elements.push(node);

        // Fetch external data asynchronously
        try {
          const apiData = await fetchExternalDataForElement(node);
          console.log('Fetched API data:', apiData);

          // Incorporate fetched data into element object, if necessary
          node.customApiData = apiData;
        } catch (apiError) {
          console.error('Failed to fetch external data:', apiError);
        }
      }

      // Traverse child nodes
      node.childNodes.forEach(traverse);
    } catch (error) {
      console.error(`Error traversing node: ${node.tagName}`, error);
    }
  }

  traverse(root);

  // Cache the result for future requests
  elementCache[cacheKey] = elements;
  return elements;
}

/**
 * Simulates an asynchronous fetch request to get data related to an element.
 *
 * @param {HTMLElement} element - The DOM element.
 * @returns {Promise<Object>} A promise that resolves with fetched data.
 */
function fetchExternalDataForElement(element) {
  // Mock implementation of a network request
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() > 0.8) { // Simulate occasional network failure
        reject(new Error('Network error'));
      } else {
        resolve({ id: element.id, moreData: 'sample' }); // Mocked API response data
      }
    }, 100);
  });
}

// Unit tests to validate the implementation

function testFindElements() {
  // Create a mock DOM structure for testing
  const container = document.createElement('div');

  const div1 = document.createElement('div');
  div1.id = 'test1';
  div1.setAttribute('data-type', 'example');
  div1.textContent = 'Test Element 1';

  const div2 = document.createElement('div');
  div2.id = 'test2';
  div2.textContent = 'Test Element 2';

  container.appendChild(div1);
  container.appendChild(div2);

  // Run tests
  findElements(container, 'div', { 'data-type': 'example' })
    .then(result => {
      console.assert(result.length === 1, 'Test failed: Expected 1 match');
      console.assert(result[0].id === 'test1', 'Test failed: Incorrect element matched');
      console.log('All tests passed!');
    })
    .catch(error => console.error('Test encountered an error:', error));
}

// Run the test
testFindElements();
