// Import required modules
const express = require('express');
const jwt = require('jsonwebtoken');
const redis = require('redis');
const axios = require('axios');
const { RateLimiterMemory } = require('rate-limiter-flexible');

// Load configuration
require('dotenv').config();

// Initialize Express app
const app = express();
app.use(express.json());

// Redis client for caching
const redisClient = redis.createClient({ url: process.env.REDIS_URL });
redisClient.connect().catch(console.error);

// Rate limiter setup
const rateLimiter = new RateLimiterMemory({
  points: Number(process.env.RATE_LIMIT_POINTS),
  duration: Number(process.env.RATE_LIMIT_DURATION)
});

// JWT verification middleware
async function authenticate(req, res, next) {
  try {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) throw new Error('No token provided');

    // Verify the token (client-side authentication)
    jwt.verify(token, process.env.JWT_SECRET);

    // Optionally verify with backend services
    // const decoded = jwt.decode(token);
    // Validate the token with your backend service

    next();
  } catch (error) {
    res.status(401).json({ message: 'Unauthorized' });
  }
}

// Load balancer with health check and dynamic weighting
const backends = [
  { url: 'http://backend1.example.com', weight: 5, healthy: true },
  { url: 'http://backend2.example.com', weight: 3, healthy: true }
];

function getNextBackend() {
  const availableBackends = backends.filter(backend => backend.healthy);
  if (availableBackends.length === 0) throw new Error('No healthy backends');

  // Simple round-robin load balancing with weights
  let totalWeight = availableBackends.reduce((sum, backend) => sum + backend.weight, 0);

  const randomPoint = Math.random() * totalWeight;
  for (let backend of availableBackends) {
    if (randomPoint < backend.weight) return axios.create({ baseURL: backend.url });
    randomPoint -= backend.weight;
  }
}

// Health check mechanism
async function checkHealth(backend) {
  try {
    const response = await axios.get(`${backend.url}/health`);
    backend.healthy = response.status === 200;
  } catch (error) {
    backend.healthy = false;
  }
}

setInterval(() => backends.forEach(checkHealth), process.env.HEALTH_CHECK_INTERVAL);

// Middleware for caching
async function cacheMiddleware(req, res, next) {
  const key = `cache:${req.originalUrl}`;
  const cachedData = await redisClient.get(key);

  if (cachedData !== null) {
    return res.json(JSON.parse(cachedData));
  }

  res.sendResponse = res.json;
  res.json = async (body) => {
    await redisClient.set(key, JSON.stringify(body), { EX: process.env.CACHE_TTL });
    res.sendResponse(body);
  };

  next();
}

// Rate limiting middleware
async function rateLimitMiddleware(req, res, next) {
  const key = req.ip || req.headers['x-forwarded-for'] || 'unknown';

  try {
    await rateLimiter.consume(key);
    next();
  } catch (error) {
    res.status(429).json({ message: 'Too many requests' });
  }
}

// Example route with all middleware applied
app.get('/api/data', authenticate, rateLimitMiddleware, cacheMiddleware, async (req, res) => {
  try {
    const client = getNextBackend();

    const response = await client.get('/data');
    return res.json(response.data);
  } catch (error) {
    console.error('Service unavailable:', error.message);
    return res.status(502).json({ message: 'Bad Gateway' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`API Gateway running on port ${PORT}`));
```

### Key Points:

1. **Authentication**: Uses JWT for client-side authentication with an option to extend it for backend verification.
2. **Load Balancing**: Implements a basic round-robin load balancing strategy considering weights and health checks.
3. **Caching**: Integrates Redis to cache responses, reducing the need to hit backend services repeatedly.
4. **Rate Limiting**: Uses `rate-limiter-flexible` to manage requests per client IP or key.
5. **Health Checks**: Periodically checks each backend service's availability and excludes unhealthy ones from load balancing.
6. **Error Handling**: Provides basic error handling for unauthorized access, rate limits, and backend failures.

