// C# Code: ConfigLoader.cs

using System;
using System.Collections.Concurrent;
using System.IO;
using System.Xml.Linq;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace ConfigApp
{
    public interface IConfigurationProvider
    {
        ConcurrentDictionary<string, string> LoadConfigurations(string[] filePaths);
    }

    public class XmlConfigurationProvider : IConfigurationProvider
    {
        private readonly ILogger<XmlConfigurationProvider> _logger;

        public XmlConfigurationProvider(ILogger<XmlConfigurationProvider> logger)
        {
            _logger = logger;
        }

        public ConcurrentDictionary<string, string> LoadConfigurations(string[] filePaths)
        {
            var configurations = new ConcurrentDictionary<string, string>();
            foreach (var file in filePaths)
            {
                try
                {
                    if (!File.Exists(file))
                        throw new FileNotFoundException($"Configuration file not found: {file}");

                    var doc = XDocument.Load(file);
                    foreach (var element in doc.Root.Elements())
                    {
                        configurations[element.Name.LocalName] = element.Value;
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Error loading configuration from {file}");
                }
            }

            return configurations;
        }
    }

    public class ConfigUpdater
    {
        private readonly IConfigurationProvider _configProvider;
        private readonly ILogger<ConfigUpdater> _logger;

        public ConfigUpdater(IConfigurationProvider configProvider, ILogger<ConfigUpdater> logger)
        {
            _configProvider = configProvider;
            _logger = logger;
        }

        public void UpdateConfigs(string[] filePaths)
        {
            var updatedConfigs = _configProvider.LoadConfigurations(filePaths);
            // Handle updates to the running application
        }
    }

    public class Program
    {
        static async Task Main(string[] args)
        {
            var services = new ServiceCollection();
            ConfigureServices(services);

            var serviceProvider = services.BuildServiceProvider();

            using (var scope = serviceProvider.CreateScope())
            {
                var updater = scope.ServiceProvider.GetRequiredService<ConfigUpdater>();

                // Schedule periodic updates
                while (true)
                {
                    updater.UpdateConfigs(Directory.GetFiles("ConfigPath", "*.xml"));
                    await Task.Delay(TimeSpan.FromMinutes(5)); // Update interval
                }
            }
        }

        private static void ConfigureServices(IServiceCollection services)
        {
            services.AddSingleton<IConfigurationProvider, XmlConfigurationProvider>();
            services.AddScoped<ConfigUpdater>();
            services.AddLogging(configure => configure.AddConsole());
        }
    }
}
