use std::env;
use std::fs;
use std::sync::{Arc, Mutex};
use tokio::sync::RwLock;

pub async fn setup_environment_directory(env_var_name: &str) -> Result<String, String> {
    let existing_path = env::var(env_var_name).unwrap_or_default();

    if !existing_path.is_empty() && PathBuf::from(existing_path).exists() {
        return Ok(existing_path);
    }

    let new_dir = tempdir::TempDir::new("config_directory").map_err(|e| e.to_string())?;
    let dir_path = new_dir.path().to_str().ok_or("Invalid directory path")?.to_owned();

    env::set_var(env_var_name, &dir_path);
    Ok(dir_path)
}

pub async fn concurrent_access_example() {
    let shared_data: Arc<RwLock<i32>> = Arc::new(RwLock::new(0));

    // Simulate concurrent access with multiple tasks
    let mut handles = vec![];

    for _ in 0..10 {
        let data_clone = Arc::clone(&shared_data);

        let handle = tokio::spawn(async move {
            let mut num = data_clone.write().await;
            *num += 1;
        });

        handles.push(handle);
    }

    for handle in handles {
        if let Err(e) = handle.await {
            eprintln!("Task error: {:?}", e);
        }
    }
}

#[tokio::main]
async fn main() {
    match setup_environment_directory("CONFIG_DIR").await {
        Ok(dir) => println!("Config directory set to: {}", dir),
        Err(err) => eprintln!("Error setting up environment variable: {}", err),
    }

    concurrent_access_example().await;
}
```

