```rust
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use crossbeam_channel::{unbounded, Sender};
use std::sync::{Arc, Mutex};

struct Logger {
    sender: Sender<LogMessage>,
}

enum LogMessage {
    StartCompiling,
    EndCompiling { duration: Duration },
    PeakRSS(u64),
    Error(String),
}

impl Logger {
    fn new() -> Arc<Mutex<Self>> {
        let (sender, receiver) = unbounded();
        std::thread::spawn(move || {
            for message in receiver.iter() {
                match message {
                    LogMessage::StartCompiling => println!("Compilation started."),
                    LogMessage::EndCompiling { duration } => {
                        println!("Compilation ended. Duration: {:?}", duration);
                    }
                    LogMessage::PeakRSS(rss) => {
                        println!("Peak RSS: {} bytes", rss);
                    }
                    LogMessage::Error(err) => eprintln!("Error: {}", err),
                }
            }
        });

        Arc::new(Mutex::new(Logger { sender }))
    }

    fn log_start(&self, _logger: &Arc<Mutex<Self>>) {
        self.sender.send(LogMessage::StartCompiling).unwrap();
    }

    fn log_end(&self, duration: Duration) {
        self.sender.send(LogMessage::EndCompiling { duration }).unwrap();
    }

    fn log_peak_rss(&self, rss: u64) {
        self.sender.send(LogMessage::PeakRSS(rss)).unwrap();
    }

    fn log_error(&self, error: &str) {
        self.sender.send(LogMessage::Error(error.to_string())).unwrap();
    }
}

fn run_compiler_with_logging() -> i32 {
    let logger = Logger::new();

    rustc_driver::catch_with_exit_code(move || {
        let start_time = Instant::now();

        logger.lock().unwrap().log_start(&logger);

        let output = Command::new("rustc")
            .arg("--emit=dep-info,link")
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .map_err(|e| format!("Failed to start rustc: {}", e))?;

        if let Some(status) = output.wait_with_output() {
            if !status.success() {
                logger.lock().unwrap().log_error(&format!(
                    "Compilation failed with status: {}",
                    status
                ));
                return status.code().unwrap_or(1);
            }
        }

        // Simulated peak RSS measurement (replace with actual memory usage tracking)
        let peak_rss = 1024 * 1024; // Example value in bytes

        logger.lock().unwrap().log_peak_rss(peak_rss);

        let duration = start_time.elapsed();

        logger.lock().unwrap().log_end(duration);

        0
    }).expect("Unexpected error during compilation")
}

fn main() {
    std::process::exit(run_compiler_with_logging());
}
