    async fn process(&self, json: &str) -> Result<Value, Box<dyn std::error::Error>>;
}

// Implement dynamic registration of processors
pub struct JsonParser {
    processors: RwLock<HashMap<String, Box<dyn JsonProcessor + Send>>>,
}

impl JsonParser {
    pub fn new() -> Self {
        JsonParser {
            processors: RwLock::new(HashMap::new()),
        }
    }

    // Register a custom JSON processor
    pub async fn register_processor<T>(&self, name: &str)
    where
        T: JsonProcessor + Send + 'static,
    {
        let mut processors = self.processors.write().await;
        processors.insert(name.to_string(), Box::new(T));
    }

    // Fetch and execute configurations asynchronously
    pub async fn fetch_and_execute_configs(&self, config_url: &str) -> Result<(), Box<dyn std::error::Error>> {
        let configs = self.fetch_configs(config_url).await?;

        let tasks: Vec<_> = configs.into_iter().map(|(name, json)| {
            let parser_clone = self.clone();
            tokio::spawn(async move {
                if let Some(processor) = parser_clone.processors.read().await.get(name) {
                    processor.process(&json).await.map_err(|e| e.to_string())
                } else {
                    Err("Processor not found".into())
                }
            })
        }).collect();

        join_all(tasks).await.into_iter().for_each(|res| {
            if let Err(e) = res {
                eprintln!("Error processing config: {}", e);
            }
        });

