public class TripleDesDecryptor
{
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> _keyCache = new();
    private readonly string _primaryCspUrl;
    private readonly string _backupCspUrl;
    private readonly object _lockObject = new();

    public TripleDesDecryptor(string primaryCspUrl, string backupCspUrl)
    {
        _primaryCspUrl = primaryCspUrl;
        _backupCspUrl = backupCspUrl;
    }

    public async Task<string> DecryptMessageAsync(string base64EncodedMessage, string source, int clearanceLevel)
    {
        try
        {
            ValidateMessageStructure(base64EncodedMessage);

            var keyIvPair = await FetchKeyAndIVAsync(clearanceLevel);

            var decryptedData = PerformDecryption(base64EncodedMessage, keyIvPair.Key, keyIvPair.IV);

            LogAudit(source, clearanceLevel, "Success", decryptedData);

            return decryptedData;
        }
        catch (Exception ex)
        {
            LogError(source, ex.Message);
            return "Decryption failed due to validation or processing error.";
        }
    }

    private void ValidateMessageStructure(string message)
    {
        // Example schema validation logic
        if (!message.Contains("timestamp") || !message.Contains("clearanceLevel") || !message.Contains("checksum"))
        {
            throw new InvalidOperationException("Invalid message structure.");
        }
    }

    private async Task<(byte[] Key, byte[] IV)> FetchKeyAndIVAsync(int clearanceLevel)
    {
        try
        {
            return await TryFetchFromCspAsync(_primaryCspUrl);
        }
        catch (Exception ex)
        {
            LogError("Primary CSP", ex.Message);
            return await TryFetchFromCspAsync(_backupCspUrl);
        }
    }

    private async Task<(byte[] Key, byte[] IV)> TryFetchFromCspAsync(string cspUrl)
    {
        // Simulate fetching keys from a CSP
        await Task.Delay(100);  // Simulating network delay

        string cacheKey = $"clearance_{cspUrl}";

        lock (_lockObject)
        {
            if (_keyCache.TryGetValue(cacheKey, out var cachedValue))
            {
                return cachedValue;
            }
        }

        var (key, iv) = FetchKeysFromCSP(cspUrl);  // Simulated key fetching logic

        _keyCache[cacheKey] = (key, iv);

        return (key, iv);
    }

    private (byte[] Key, byte[] IV) FetchKeysFromCSP(string cspUrl)
    {
        // Placeholder for actual CSP communication
        var key = Encoding.UTF8.GetBytes("dummykey1234567");  // Dummy key for illustration
        var iv = Encoding.UTF8.GetBytes("dummyiv12345");      // Dummy IV for illustration

