#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <sys/stat.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>

#define MAX_IMAGES 100

typedef struct {
    char *image_path;
    char *metadata; // Metadata string (e.g., author, creation date)
} ImageInfo;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void generate_thumbnail(const char *image_path) {
    // Dummy function for generating thumbnails
    printf("Thumbnail generated for: %s\n", image_path);
}

int process_images(const char *dir_path, const char *output_name, const char **images, int img_count, sem_t *sem, const char *format, const char **custom_order) {
    char command[1024];

    for (int i = 0; i < img_count; ++i) {
        sem_wait(sem);

        snprintf(command, sizeof(command), "convert %s/%s -thumbnail 100x100 thumbnail_%d.jpg", dir_path, images[i], i);
        if (system(command) != 0) {
            log_error("Failed to generate thumbnail");
            sem_post(sem);
            return 1;
        }

        // Add metadata (dummy operation)
        snprintf(command, sizeof(command), "convert %s/%s -set comment \"%s\" %s_with_metadata.jpg", dir_path, images[i], "Sample Metadata", images[i]);
        if (system(command) != 0) {
            log_error("Failed to embed metadata");
            sem_post(sem);
            return 1;
        }

        snprintf(command, sizeof(command), "composite -geometry +10+10 thumbnail_%d.jpg %s_with_metadata.jpg combined_%d.jpg", i, images[i], i);
        if (system(command) != 0) {
            log_error("Failed to composite image");
            sem_post(sem);
            return 1;
        }

        snprintf(command, sizeof(command), "convert combined_%d.jpg %s.%s", i, output_name, format);
        if (system(command) != 0) {
            log_error("Failed to convert final image");
            sem_post(sem);
            return 1;
        }

        // Clean up intermediate files
        snprintf(command, sizeof(command), "rm %s_with_metadata.jpg thumbnail_%d.jpg combined_%d.jpg", images[i], i, i);
        system(command);

        sem_post(sem);
    }

    return 0;
}

int convert_images_to_pdf(const char *dir_path, const char *output_name, const char **images, int img_count, const char *format) {
    sem_t semaphore;
    if (sem_init(&semaphore, 0, 4) != 0) { // Concurrency limit: 4
        log_error("Semaphore initialization failed");
        return 1;
    }

    int result = process_images(dir_path, output_name, images, img_count, &semaphore, format, NULL);

    sem_destroy(&semaphore);

    if (result != 0) {
        log_error("Image processing failed");
    }

    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <directory_path> <output_name> <image1> <image2> ... [format]\n", argv[0]);
        return 1;
    }

    const char *dir_path = argv[1];
    const char *output_name = argv[2];
    int img_count = argc - 3;
    const char **images = &argv[3];

    const char *format = (argc == 5) ? "pdf" : argv[4]; // Default to PDF if no format specified

    return convert_images_to_pdf(dir_path, output_name, images, img_count, format);
}
