// OctreeNode class definition
class OctreeNode {
public:
    struct Point {
        float x, y, z;
    };

    OctreeNode(float size);
    ~OctreeNode();

    void insert(const Point& point);
    bool retrieve(const Point& point) const;
    std::vector<Point> rangeQuery(const Point& center, float radius) const;
    Point nearestNeighbor(const Point& queryPoint) const;

private:
