    float size_;
    float halfSize_;
    Point center_;
    std::unique_ptr<OctreeNode> children_[8];
    bool isLeaf_;
    std::vector<Point> points_;

    mutable std::mutex mutex_;
};

// SpatialPartitionManager class definition
class SpatialPartitionManager {
public:
    SpatialPartitionManager(const std::string& label, float featureSize, size_t maxCapacity);
    ~SpatialPartitionManager();

    void insertPoint(float x, float y, float z);
    bool retrievePoint(float x, float y, float z) const;
    std::vector<OctreeNode::Point> queryRange(float cx, float cy, float cz, float radius) const;
    OctreeNode::Point nearestNeighbor(float qx, float qy, float qz) const;

    void clear();

private:
    class Impl;
    std::unique_ptr<Impl> pimpl_;
};

// Implementation of SpatialPartitionManager
class SpatialPartitionManager::Impl {
public:
    Impl(const std::string& label, float featureSize, size_t maxCapacity)
        : root_(featureSize), maxCapacity_(maxCapacity) {

        if (featureSize < 0.1f) throw FeatureSizeTooSmallException();
        if (maxCapacity <= 100) throw CapacityInsufficientException();

        // Initialization logic
    }

    void insertPoint(float x, float y, float z) { root_.insert({x, y, z}); }

    bool retrievePoint(float x, float y, float z) const {
        return root_.retrieve({x, y, z});
    }

    std::vector<OctreeNode::Point> queryRange(float cx, float cy, float cz, float radius) const {
        return root_.rangeQuery({cx, cy, cz}, radius);
    }

    OctreeNode::Point nearestNeighbor(float qx, float qy, float qz) const {
        return root_.nearestNeighbor({qx, qy, qz});
    }

    void clear() { root_ = OctreeNode(maxCapacity_); }

private:
    OctreeNode root_;
    size_t maxCapacity_;
};

SpatialPartitionManager::SpatialPartitionManager(const std::string& label, float featureSize, size_t maxCapacity)
    : pimpl_(std::make_unique<Impl>(label, featureSize, maxCapacity)) {}

SpatialPartitionManager::~SpatialPartitionManager() = default;

void SpatialPartitionManager::insertPoint(float x, float y, float z) {
    pimpl_->insertPoint(x, y, z);
}

bool SpatialPartitionManager::retrievePoint(float x, float y, float z) const {
    return pimpl_->retrievePoint(x, y, z);
}

std::vector<OctreeNode::Point> SpatialPartitionManager::queryRange(float cx, float cy, float cz, float radius) const {
    return pimpl_->queryRange(cx, cy, cz, radius);
}

OctreeNode::Point SpatialPartitionManager::nearestNeighbor(float qx, float qy, float qz) const {
    return pimpl_->nearestNeighbor(qx, qy, qz);
}

void SpatialPartitionManager::clear() {
    pimpl_->clear();
}
