<?php

class PasswordManager {
    private $hashedPassword;
    private $saltRoundCount;

    public function __construct() {
        $this->saltRoundCount = 12; // Default salt round count
    }

    public function generateRandomString($length, $characterSet) {
        if (!$this->validateCharacterSet($characterSet)) {
            throw new InvalidArgumentException("Character set does not meet security requirements.");
        }

        $randomString = '';
        $characterSetLength = strlen($characterSet);

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[random_int(0, $characterSetLength - 1)];
        }

        return $randomString;
    }

    public function hashPassword($password) {
        if (!is_numeric($this->saltRoundCount) || 
            $this->saltRoundCount < 8 || 
            $this->saltRoundCount > 31) {
            throw new InvalidArgumentException("Invalid salt round count.");
        }

        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
    }

    public function checkPassword($providedPassword, $storedHashedPassword) {
        return password_verify($providedPassword, $storedHashedPassword);
    }

    private function validateCharacterSet($characterSet) {
        if (!preg_match('/[A-Z]/', $characterSet) ||
            !preg_match('/[a-z]/', $characterSet) ||
            !preg_match('/\d/', $characterSet) ||
            !preg_match('/[\W_]/', $characterSet)) {
            return false;
        }
        return true;
    }

    public function setSaltRoundCount($rounds) {
        if (is_numeric($rounds) && $rounds >= 8 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            throw new InvalidArgumentException("Invalid salt round count.");
        }
    }

    public function externalPolicyCheck($characterSet) {
        try {
            // Simulated check with an external service
            return $this->mockExternalServiceCall($characterSet);
        } catch (Exception $e) {
            error_log('Error during external policy check: ' . $e->getMessage());
            return false;
        }
    }

    private function mockExternalServiceCall($characterSet) {
        // Simulate network latency and potential failure
        sleep(0.1); // Simulating delay

        // Example condition for compliance, in reality this would be a real service call.
        return strlen($characterSet) >= 10;
    }

    public function resetPassword() {
        if (!isset($this->hashedPassword)) {
            throw new RuntimeException("No password is currently set to reset.");
        }

        $newRandomString = $this->generateRandomString(12, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*');
        $this->hashPassword($newRandomString);
    }

    public function getHashedPassword() {
        return $this->hashedPassword;
    }
}
