using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Configuration;

public class XmlParserService
{
    private readonly IMemoryCache _cache;
    private readonly IConfiguration _configuration;

    public XmlParserService(IMemoryCache cache, IConfiguration configuration)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _configuration = configuration ?? throw new ArgumentNullException(nameof(configuration));
    }

    public IEnumerable<(string ElementName, IDictionary<string, string> Attributes)> GetMatchingElements(string xpath, string elementName, int maxLimit)
    {
        var configPath = _configuration["XmlFilePath"];
        if (string.IsNullOrWhiteSpace(configPath))
            throw new InvalidOperationException("Configuration path for XML file is not set.");

        XmlDocument xmlDoc = LoadDocumentWithCaching(configPath);

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathExpression expr = navigator.Compile(xpath);

        navigator.MoveToRoot();
        var results = navigator.Select(expr);

        if (!results.MoveNext())
            throw new InvalidOperationException("No elements found matching the specified XPath expression.");

        int count = 0;
        var matchedElements = new List<(string, IDictionary<string, string>)>();

        while (results.MoveNext() && count < maxLimit)
        {
            if (results.Current.Name.Equals(elementName, StringComparison.OrdinalIgnoreCase))
            {
                var attributes = ExtractAttributes(results.Current);
                matchedElements.Add((elementName, attributes));
                count++;
            }
        }

        if (count == 0)
            throw new InvalidOperationException("No elements found with the specified name.");

        if (count > maxLimit)
            throw new InvalidOperationException($"The number of matching elements exceeded the maximum limit of {maxLimit}.");

        return matchedElements;
    }

    private XmlDocument LoadDocumentWithCaching(string filePath)
    {
        if (!_cache.TryGetValue(filePath, out XmlDocument doc))
        {
            var stream = new System.IO.FileStream(filePath, System.IO.FileMode.Open);
            doc = new XmlDocument();
            doc.Load(stream);
            _cache.Set(filePath, doc, TimeSpan.FromMinutes(10)); // Adjust cache duration as needed
            stream.Close();
        }

        return doc;
    }

    private IDictionary<string, string> ExtractAttributes(XPathNavigator navigator)
    {
        var attributes = new Dictionary<string, string>();

        for (int i = 0; i < navigator.MoveToFirstAttribute(); i++)
        {
            attributes[navigator.Name] = navigator.Value;
            navigator.MoveToNextAttribute();
        }

        return attributes;
    }
}

// Usage example
public class Program
{
    public static void Main(string[] args)
    {
        var configuration = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json")
            .Build();

        var memoryCache = new MemoryCache(new MemoryCacheOptions());

        var xmlParserService = new XmlParserService(memoryCache, configuration);

        try
        {
            var elements = xmlParserService.GetMatchingElements("//ns:Element", "ElementName", 5); // Customize XPath and element name as needed

            foreach (var element in elements)
            {
                Console.WriteLine($"Element Name: {element.ElementName}");
                foreach (var attribute in element.Attributes)
                {
                    Console.WriteLine($" - Attribute: {attribute.Key}, Value: {attribute.Value}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
```

### Key Features:
1. **Caching**: Uses `IMemoryCache` for caching XML documents to enhance performance.
2. **Configuration Management**: Loads the configuration dynamically using `IConfiguration`.
3. **Namespace Support**: Supports XPath queries with namespaces by ensuring correct usage of namespace prefixes in the XPath expression.
4. **Error Handling**: Throws exceptions if elements are not found or exceed a specified limit, providing clear error messages.
5. **Resource Management**: Ensures that file streams and XML documents are properly disposed to prevent memory leaks.

