```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
import hiredis/hiredis.h;
#include "slf4j/slf4j.h"
#include "crypto/crypto.h"

#define MAX_PATH_LENGTH 1000
#define CACHE_SIZE 1024

typedef struct {
    int sequence_number;
    unsigned char flags[16];
    // Additional packet metadata can be added here
} NCP_Packet;

typedef struct CacheEntry {
    char *filename;
    size_t content_length;
    char *content;
    time_t last_accessed;
    struct CacheEntry *next;
} CacheEntry;

CacheEntry *cache = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
redisContext *redis_ctx = NULL;
const int redis_port = 6379;
const char *redis_host = "127.0.0.1";

// Function prototypes
void initializeRedis();
void shutdownRedis();
void handlePacketGeneration();
void *readFileContents(void *arg);
CacheEntry* getFromCache(const char *filename);
void addToCache(CacheEntry *entry);
CacheEntry* evictLRU();

void packetGenerator(char *directoryPath, const char *extension) {
    if (strlen(directoryPath) > MAX_PATH_LENGTH || directoryPath == NULL) {
        fprintf(stderr, "Invalid directory path\n");
        return;
    }

    initializeRedis();

    pthread_t thread_pool[100];
    int thread_count = 0;

    // Directory reading and processing logic
    DIR *dir = opendir(directoryPath);
    if (!dir) {
        perror("Unable to open directory");
        shutdownRedis();
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, extension)) {
            pthread_create(&thread_pool[thread_count++], NULL, readFileContents, entry->d_name);

            if (thread_count == 100) {
                for (int i = 0; i < thread_count; ++i)
                    pthread_join(thread_pool[i], NULL);
                thread_count = 0;
            }
        }
    }

    for (int i = 0; i < thread_count; ++i)
        pthread_join(thread_pool[i], NULL);

    closedir(dir);

    handlePacketGeneration();
    shutdownRedis();
}

void *readFileContents(void *arg) {
    char filename[] = "/file/to/read/";
    strncat(filename, (char *) arg, sizeof(filename) - strlen("/file/to/read/") - 1);

    CacheEntry* cache_entry = getFromCache(filename);

    if (!cache_entry) {
        FILE *file = fopen(filename, "r");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", filename);
            return NULL;
        }

        fseek(file, 0, SEEK_END);
        size_t length = ftell(file);
        fseek(file, 0, SEEK_SET);

        char *content = (char *)malloc(length + 1);
        if (!content) {
            fprintf(stderr, "Memory allocation failed for file content\n");
            fclose(file);
            return NULL;
        }

        fread(content, 1, length, file);
        content[length] = '\0';
        fclose(file);

        // Calculate hashes
        unsigned char sha256_hash[32];
        unsigned char md5_hash[16];
        calculateSHA256((unsigned char *)content, length, sha256_hash);
        calculateMD5((unsigned char *)content, length, md5_hash);

        SLF4J_log_info("File: %s, Length: %zu", filename, length);

        cache_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
        if (!cache_entry) {
            fprintf(stderr, "Memory allocation failed for cache entry\n");
            free(content);
            return NULL;
        }

        cache_entry->filename = strdup(filename);
        cache_entry->content_length = length;
        cache_entry->content = content;
        cache_entry->last_accessed = time(NULL);

        addToCache(cache_entry);

        // Store in Redis
        redisReply *reply = (redisReply *)redisCommand(redis_ctx, "SET %s %b", filename, content, length);
        freeReplyObject(reply);
    } else {
        SLF4J_log_info("Using cached file: %s, Length: %zu", cache_entry->filename, cache_entry->content_length);
    }

    return NULL;
}

CacheEntry* getFromCache(const char *filename) {
    pthread_mutex_lock(&cache_lock);

    CacheEntry *entry = cache;
    while (entry) {
        if (strcmp(entry->filename, filename) == 0) {
            entry->last_accessed = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return entry;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void addToCache(CacheEntry *entry) {
    if (!cache) {
        cache = entry;
        return;
    }

    CacheEntry *last_entry = cache;
    while (last_entry->next)
        last_entry = last_entry->next;

    last_entry->next = entry;

    // If the cache exceeds CACHE_SIZE, evict LRU
    if (/* Cache size logic */) {
        CacheEntry *lru_entry = evictLRU();
        free(lru_entry->filename);
        free(lru_entry->content);
        free(lru_entry);
    }
}

CacheEntry* evictLRU() {
    pthread_mutex_lock(&cache_lock);

    CacheEntry **prev = &cache;
    CacheEntry *entry = cache;

    while (entry && entry->next) {
        if (entry->last_accessed < (*prev)->last_accessed)
            prev = &(entry->next);
        entry = entry->next;
    }

    CacheEntry *lru_entry = *prev;
    *prev = lru_entry->next;

    pthread_mutex_unlock(&cache_lock);

    return lru_entry;
}

void initializeRedis() {
    redis_ctx = redisConnect(redis_host, redis_port);
    if (redis_ctx->err) {
        fprintf(stderr, "Error connecting to Redis: %s\n", redis_ctx->errstr);
        exit(1);
    }
}

void shutdownRedis() {
    if (redis_ctx)
        redisFree(redis_ctx);
}

void handlePacketGeneration() {
    // NCP packet generation logic here
}
```

This code defines the `packetGenerator` function, integrating a thread pool for reading file contents, handling Redis caching, and generating NCP packets. It includes logging with SLF4J, error management, and encryption using placeholders (`calculateSHA256`, `calculateMD5`). Adjust specific cryptographic implementations and database communication as necessary.

Here's an example implementation in C that manages a named semaphore with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

#ifdef _WIN32
#include <windows.h>
#else
#include <time.h>
#endif

#define SEM_NAME_MAX 256
#define LOG_FILE "semaphore_log.txt"

typedef struct {
    sem_t *sem;
    char name[SEM_NAME_MAX];
    pthread_mutex_t lock;
    int init_value;
    unsigned long acquire_count, release_count, failed_acquire_count;
} Semaphore;

Semaphore *create_semaphore(const char *name, unsigned int initial_value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    if (!s) return NULL;

    strncpy(s->name, name, SEM_NAME_MAX);
    s->init_value = initial_value;
    pthread_mutex_init(&s->lock, NULL);

#ifdef _WIN32
    s->sem = CreateSemaphoreA(NULL, initial_value, ULONG_MAX, name);
    if (s->sem == NULL) {
        perror("CreateSemaphore");
        free(s);
        return NULL;
    }
#else
    int fd = sem_open(name, O_CREAT | O_EXCL, 0666, initial_value);
    if (fd == -1) {
        perror("sem_open");
        free(s);
        return NULL;
    }
    s->sem = mmap(NULL, sizeof(sem_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);
#endif

    s->acquire_count = 0;
    s->release_count = 0;
    s->failed_acquire_count = 0;

    return s;
}

void delete_semaphore(Semaphore *s) {
#ifdef _WIN32
    if (CloseHandle(s->sem)) {
        s->sem = NULL;
    }
#else
    if (munmap(s->sem, sizeof(sem_t))) {
        perror("munmap");
    }

    char sem_name[SEM_NAME_MAX];
    snprintf(sem_name, SEM_NAME_MAX, "/%s", s->name);
    if (sem_unlink(sem_name)) {
        perror("sem_unlink");
    }
#endif
    pthread_mutex_destroy(&s->lock);
    free(s);
}

int acquire_semaphore(Semaphore *s, unsigned int timeout) {
#ifdef _WIN32
    DWORD start_time = GetTickCount();
#else
    struct timespec ts;
#endif

    pthread_mutex_lock(&s->lock);

#ifdef _WIN32
    while (true) {
        if (WaitForSingleObject(s->sem, timeout) == WAIT_OBJECT_0) {
            s->acquire_count++;
            log_semaphore_activity("Acquired");
            pthread_mutex_unlock(&s->lock);
            return 0;
        }

        DWORD elapsed = GetTickCount() - start_time;
        if (elapsed >= timeout || GetLastError() != WAIT_TIMEOUT) {
            s->failed_acquire_count++;
            log_semaphore_activity("Failed to acquire");
            pthread_mutex_unlock(&s->lock);
            return -1;
        }
    }
#else
    clock_gettime(CLOCK_REALTIME, &ts);

    while (true) {
        if (sem_timedwait(s->sem, &ts) == 0) {
            s->acquire_count++;
            log_semaphore_activity("Acquired");
            pthread_mutex_unlock(&s->lock);
            return 0;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += timeout / 1000000;
        ts.tv_nsec += (timeout % 1000000) * 1000;

        if ((ts.tv_nsec >= 1000000000)) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }

        if (errno != EINTR && errno != ETIMEDOUT) {
            s->failed_acquire_count++;
            log_semaphore_activity("Failed to acquire");
            pthread_mutex_unlock(&s->lock);
            return -1;
        }
    }
#endif
}

int release_semaphore(Semaphore *s) {
    pthread_mutex_lock(&s->lock);

#ifdef _WIN32
    if (!ReleaseSemaphore(s->sem, 1, NULL)) {
#else
    if (sem_post(s->sem) == -1) {
#endif
        perror("Failed to release semaphore");
        pthread_mutex_unlock(&s->lock);
        return -1;
    }

    s->release_count++;
    log_semaphore_activity("Released");

    pthread_mutex_unlock(&s->lock);
    return 0;
}

void log_semaphore_activity(const char *message) {
#ifdef _WIN32
    HANDLE hFile = CreateFileA(LOG_FILE, GENERIC_WRITE, FILE_SHARE_READ, NULL, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    if (hFile != INVALID_HANDLE_VALUE) {
        DWORD written;
        SYSTEMTIME st;
        GetLocalTime(&st);

        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                 st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, message);

        WriteFile(hFile, log_entry, strlen(log_entry), &written, NULL);
        CloseHandle(hFile);
    }
#else
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        time_t now;
        struct tm *tm_info;
        char buffer[80];

        time(&now);
        tm_info = localtime(&now);

        strftime(buffer, sizeof(buffer), "[%Y-%m-%d %H:%M:%S] ", tm_info);
        fprintf(file, "%s%s\n", buffer, message);

        fclose(file);
    }
#endif
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <semaphore_name> <initial_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *name = argv[1];
    unsigned int initial_value = strtoul(argv[2], NULL, 10);

    Semaphore *s = create_semaphore(name, initial_value);
    if (!s) {
        fprintf(stderr, "Failed to create semaphore\n");
        return EXIT_FAILURE;
    }

    // Example usage
    if (acquire_semaphore(s, 5000) == 0) {
        printf("Semaphore acquired successfully.\n");
        release_semaphore(s);
    } else {
        printf("Failed to acquire semaphore.\n");
    }

    delete_semaphore(s);

    return EXIT_SUCCESS;
}
```

### Explanation:

- **Cross-platform Compatibility**: The code uses conditional compilation (`#ifdef _WIN32`) to handle platform-specific differences between Windows and POSIX systems.
- **Semaphore Management**: Functions are provided for creating, deleting, acquiring, and releasing a semaphore. These functions include error handling and logging.
- **Logging**: Logs semaphore activity with timestamps and messages to a file.
- **Concurrency**: Uses mutexes to ensure thread-safe operations on shared data structures.
- **Timeouts**: Implements timeouts for semaphore acquisition using platform-specific mechanisms.

