$rateLimiter = new RateLimiter();

// Middleware for authentication and rate-limiting
function authenticateAndRateLimit(Request $request): bool {
    global $rateLimiter;

    $ip = $request->getClientIp();

    if (!$rateLimiter->allowRequest($ip)) {
        return false;
    }

    // Authenticate request logic here, possibly using a token or session check

    return true; // Return false if authentication fails
}

function handleUserAccount(Request $request): ResponseInterface {
    global $conn;

    if (!authenticateAndRateLimit($request)) {
        return new JsonResponse(['status' => 'error', 'message' => 'Unauthorized access']);
    }

    $data = json_decode($request->getContent(), true);

    // Validate and process user account management
    $email = $data['email'] ?? '';
    $password = $data['password'] ?? '';
    $confirmPassword = $data['confirm_password'] ?? '';

    if ($password !== $confirmPassword) {
        return new JsonResponse(['status' => 'error', 'message' => 'Passwords do not match']);
    }

    // Check for email uniqueness
    $stmt = $conn->prepare('SELECT COUNT(*) FROM users WHERE email = :email');
    $stmt->execute([':email' => $email]);
    if ($stmt->fetchColumn() > 0) {
        return new JsonResponse(['status' => 'error', 'message' => 'Email already exists']);
    }

    // Assume user creation is successful
    $userId = rand(1, 10000); // Simulating database insert

    return new JsonResponse([
        'status' => 'success',
        'message' => 'User account created successfully',
        'data' => [
            'id' => $userId,
            'name' => $data['name'] ?? '',
            'email' => $email
        ]
    ]);
}

function handleTransaction(Request $request): ResponseInterface {
    if (!authenticateAndRateLimit($request)) {
        return new JsonResponse(['status' => 'error', 'message' => 'Unauthorized access']);
    }

    // Logic for handling transaction event recording

    return new JsonResponse([
        'status' => 'success',
        'message' => 'Transaction recorded successfully',
        'data' => null
    ]);
}

function hashFile($filePath): string {
    $hash = '';
    $chunkSize = 8192;

    if (file_exists($filePath)) {
        $handle = fopen($filePath, "rb");

        while (!feof($handle)) {
            $buffer = fread($handle, $chunkSize);
            $hash = hash('md5', $buffer . $hash, true);
        }

        fclose($handle);
    }

    return hash_final($hash, false); // Return the final MD5 hash
}

function handleFileHash(Request $request): ResponseInterface {
    if (!authenticateAndRateLimit($request)) {
        return new JsonResponse(['status' => 'error', 'message' => 'Unauthorized access']);
    }

    $data = json_decode($request->getContent(), true);
    $filePath = $data['file_path'] ?? '';

    try {
        $hash = hashFile($filePath);

        return new JsonResponse([
            'status' => 'success',
            'message' => 'File hashed successfully',
            'data' => ['hash' => $hash]
        ]);
    } catch (\Exception $e) {
        return new JsonResponse(['status' => 'error', 'message' => "Failed to hash file: {$e->getMessage()}"]);
    }
}

$request = Request::createFromGlobals();
$pathInfo = $request->getPathInfo();

if (strpos($pathInfo, '/user') === 0) {
    $response = handleUserAccount($request);
} elseif (strpos($pathInfo, '/transaction') === 0) {
    $response = handleTransaction($request);
} elseif (strpos($pathInfo, '/hashfile') === 0) {
    $response = handleFileHash($request);
} else {
    $response = new JsonResponse(['status' => 'error', 'message' => 'Invalid endpoint'], 404);
}

$response->withHeader('Content-Type', 'application/json');

\Zend\Diactoros\Response\SapiEmitter::emit($response);

