### 2. Implementing Real-Time Chat

#### Create a Service for WebSocket Communication:

```typescript
// chat.service.ts
import { Injectable } from '@angular/core';
import * as io from 'socket.io-client';

@Injectable({
  providedIn: 'root',
})
export class ChatService {
  private socket;

  constructor() {
    this.socket = io('http://your-server-url');
  }

  sendMessage(channel, message) {
    this.socket.emit('message', { channel, message });
  }

  receiveMessages(callback) {
    this.socket.on('newMessage', callback);
  }
}
```

#### Create a Component for Chat Interface:

```typescript
// chat.component.ts
import { Component, OnInit } from '@angular/core';
import { ChatService } from './chat.service';

@Component({
  selector: 'app-chat',
  templateUrl: './chat.component.html',
})
export class ChatComponent implements OnInit {
  messages = [];

  constructor(private chatService: ChatService) {}

  ngOnInit() {
    this.chatService.receiveMessages((message) => {
      this.messages.push(message);
    });
  }

  sendMessage(channel, message) {
    this.chatService.sendMessage(channel, message);
  }
}
```

