### 5. Implementing Directory Management

#### Directory Management Functionality:

```typescript
// directory-manager.js
const fs = require('fs');
const path = require('path');

function manageDirectories(fields, refreshInterval) {
  fields.forEach(field => {
    setInterval(() => {
      try {
        const dirPath = `./data/${field}`;
        if (!fs.existsSync(dirPath)) {
          fs.mkdirSync(dirPath);
          console.log(`Directory ${dirPath} created.`);
        } else {
          console.log(`Directory ${dirPath} already exists.`);
        }

        // Cleanup logic
        const files = fs.readdirSync(dirPath);
        files.forEach(file => {
          const filePath = path.join(dirPath, file);
          if (fs.statSync(filePath).ctimeMs < Date.now() - refreshInterval) {
            fs.unlinkSync(filePath);
            console.log(`File ${file} deleted.`);
          }
        });
      } catch (error) {
        console.error('Error managing directories:', error);
      }
    }, refreshInterval);
  });
}

module.exports = manageDirectories;
```

