    {
        _httpClient.Dispose();
        _semaphore.Dispose();
    }
}

public interface ICryptoServiceProvider
{
    byte[] Key { get; }
    byte[] IV { get; }
    SymmetricAlgorithm CreateDecryptor(byte[] key, byte[] iv);
    Task<ICryptoServiceProvider> GetServiceInstance(string contextId);
}
