    public async Task ConvertImagesToPdfAsync(string directoryPath, string outputFileName, List<string> imageFilenames, int concurrencyLimit)
    {
        // Create a semaphore to manage concurrent processing limits
        using var semaphoreSlim = new SemaphoreSlim(concurrencyLimit);

        try
        {
            // Log start time
            Log("Conversion process started.");

            // Ensure directory exists
