            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, location = ?, capacity = ? WHERE id = ?");
            $stmt->execute([$clinicData['status'], $clinicData['location'], $clinicData['capacity'], $clinicData['id']]);

            // Update cache
            $this->cache->set($clinicData['id'], $clinicData);

            $this->db->commit();

            // Notify systems based on priority
            $this->notifySystems($clinicData['id'], 'updated', $clinicData);
        } catch (\Exception $e) {
            $this->db->rollBack();
            $this->logger->error("Failed to update clinic: " . $e->getMessage());
            throw $e;
        }
    }

    private function deleteClinic($clinicId) {
        $this->db->beginTransaction();

        try {
            // Retrieve associated appointments, supplies, and staff schedules
            $appointments = $this->db->fetchAll("SELECT * FROM appointments WHERE clinic_id = ?", [$clinicId]);
            $supplies = $this->db->fetchAll("SELECT * FROM supplies WHERE clinic_id = ?", [$clinicId]);
            $staffSchedules = $this->db->fetchAll("SELECT * FROM staff_schedules WHERE clinic_id = ?", [$clinicId]);

