// JavaScript: testRunner.js

async function dynamicTestRunner(moduleLabel, testSuites, config) {
    const { concurrency, timeout, retries, retryDelay } = config;
    let results = [];

    async function runSuite(suiteName, suiteTests) {
        console.log(`Running suite: ${suiteName}`);
        for (let i = 0; i < suiteTests.length; i++) {
            await executeTestWithRetry(suiteName, suiteTests[i], retries, retryDelay);
        }
    }

    async function executeTestWithRetry(suiteName, testFunc, retriesLeft, delay) {
        try {
            const result = await runTest(testFunc, timeout);
            console.log(`Test: ${testFunc.name} - Suite: ${suiteName} - Status: ${result ? 'Passed' : 'Failed'}`);
            results.push({ suite: suiteName, test: testFunc.name, status: result });
        } catch (error) {
            if (retriesLeft > 0) {
                console.log(`Retrying Test: ${testFunc.name} - Suite: ${suiteName}. Attempts left: ${retriesLeft}`);
                await new Promise(res => setTimeout(res, delay));
                await executeTestWithRetry(suiteName, testFunc, retriesLeft - 1, delay);
            } else {
                console.error(`Test: ${testFunc.name} - Suite: ${suiteName} - Status: Failed with error: ${error.message}`);
                results.push({ suite: suiteName, test: testFunc.name, status: false, error: error.message });
            }
        }
    }

    async function runTest(testFunc, timeout) {
        return new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => reject(new Error('Timeout')), timeout);

            try {
                const result = testFunc();
                if (result instanceof Promise) {
                    result.then(resolve).catch(reject);
                } else {
                    resolve(!!result); // Assuming truthy means pass
                }
            } catch (error) {
                reject(error);
            } finally {
                clearTimeout(timeoutId);
            }
        });
    }

    const promises = testSuites.map((suite, index) => 
        new Promise(resolve => setTimeout(() => runSuite(suite.name, suite.tests), index * delay))
    );

    await Promise.all(promises);

    console.log('All suites completed.');
    return results;
}

// PHP: SecurePasswordManager.php

class SecurePasswordManager {
    const CHARSET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_-+=<>?';

    public function generateRandomString($length) {
        $randomBytes = openssl_random_pseudo_bytes($length);
        $string = '';

        for ($i = 0; $i < $length; $i++) {
            $charIndex = ord($randomBytes[$i]) % strlen(self::CHARSET);
            $string .= self::CHARSET[$charIndex];
        }

        return $string;
    }

    public function hashPassword($password, $salt, $algorithm = 'bcrypt') {
        switch (strtolower($algorithm)) {
            case 'argon2':
                return password_hash($password . $salt, PASSWORD_ARGON2I);
            case 'bcrypt':
            default:
                return crypt($password . $salt, '$2y$12$' . $this->generateRandomString(22));
        }
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        switch (strtolower(explode('$', $hashedPassword)[1])) {
            case 'argon2i':
                return password_verify($password . $salt, $hashedPassword);
            case '2y':
            default:
                return crypt($password . $salt, $hashedPassword) === $hashedPassword;
        }
    }

    private function generateRandomString($length) {
        $randomBytes = openssl_random_pseudo_bytes($length / 4); // Each byte can represent up to 16 base64 characters
        $string = '';

        for ($i = 0; $i < strlen($randomBytes); $i++) {
            $charIndex = ord($randomBytes[$i]) % 64;
            $string .= base64_encode(chr($charIndex));
        }

        return substr($string, 0, $length);
    }
}
