import asyncio
import aiohttp
from collections import defaultdict
import time
import logging
import jsonschema

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class RateLimiter:
    def __init__(self, max_concurrent_requests):
        self.semaphore = asyncio.Semaphore(max_concurrent_requests)

    async def acquire(self):
        await self.semaphore.acquire()

    def release(self):
        self.semaphore.release()


class AsynchronousDataAggregator:
    def __init__(self, csp_providers, max_concurrent_requests=5):
        self.csp_providers = csp_providers
        self.rate_limiter = RateLimiter(max_concurrent_requests)
        self.key_cache = defaultdict(dict)  # Cache keys and IVs per provider

    async def fetch(self, session, url, method):
        try:
            await self.rate_limiter.acquire()
            async with session.request(method, url) as response:
                response.raise_for_status()
                data = await response.json()
        except Exception as e:
            logging.error(f"Error fetching {url}: {str(e)}")
            return None
        finally:
            self.rate_limiter.release()
        return data

    async def aggregate_data(self, api_sources, initial_dict, aggregation_callback):
        async with aiohttp.ClientSession() as session:
            tasks = [
                asyncio.create_task(
                    aggregation_callback(api['source'], url, method, await self.fetch(session, url, method))
                )
                for api in api_sources
                for key, value in api.items()
                if key == 'endpoint'
                for url, method in [(value['url'], value['method'])]
            ]
            results = await asyncio.gather(*tasks)
            for result in results:
                if result:
                    initial_dict.update(result)

    async def decryption(self, message, clearance_level):
        provider_key_details = self.get_provider_key(clearance_level)
        key, iv = self.retrieve_cached_keys(provider_key_details)

        # Validate message structure
        try:
            jsonschema.validate(instance=message, schema={"type": "object", "properties": {"data": {"type": "string"}}})
        except jsonschema.exceptions.ValidationError as e:
            logging.error(f"Message validation error: {str(e)}")
            return None

        start_time = time.time()
        # Decryption logic here (mocked for example)
        decrypted_message = self.mock_decrypt(message['data'], key, iv)

        decryption_time = time.time() - start_time
        logging.info(f"Decrypted message from source: {message.get('source', 'unknown')} with clearance level: "
                     f"{clearance_level}. Time taken: {decryption_time}s. Result: {'Success' if decrypted_message else 'Failure'}")

        return decrypted_message

    def get_provider_key(self, clearance_level):
        # Logic to determine the CSP provider and key details based on clearance level
        for provider in self.csp_providers:
            if provider.supports_clearance(clearance_level):
                return provider.get_key_details(clearance_level)
        raise ValueError(f"No valid provider found for clearance level: {clearance_level}")

    def retrieve_cached_keys(self, provider_key_details):
        # Fetch keys from cache or CSP
        if provider_key_details['key_id'] not in self.key_cache[provider_key_details['provider_name']]:
            key_data = provider_key_details['csp'].fetch_key(provider_key_details['key_id'])
            self.key_cache[provider_key_details['provider_name']][provider_key_details['key_id']] = key_data
        return self.key_cache[provider_key_details['provider_name']][provider_key_details['key_id']]['key'], \
               self.key_cache[provider_key_details['provider_name']][provider_key_details['key_id']]['iv']

    def mock_decrypt(self, data, key, iv):
        # Placeholder for actual decryption logic
        return f"Decrypted({data}) with Key:{key} and IV:{iv}"

# Mock CSP provider class for testing purposes
class MockCSP:
    def supports_clearance(self, clearance_level):
        # Example condition
        return clearance_level <= 5

    def fetch_key(self, key_id):
        # Return a mock key and IV
        return {'key': f"Key-{key_id}", 'iv': f"IV-{key_id}"}

# Usage example (without actually running the async functions)
async def main():
    csp_providers = [MockCSP()]
    aggregator = AsynchronousDataAggregator(csp_providers)

    api_sources = [
        {'source': 'API1', 'endpoint': {'url': 'https://api1.example.com/data', 'method': 'GET'}},
        {'source': 'API2', 'endpoint': {'url': 'https://api2.example.com/info', 'method': 'POST'}}
    ]

    def aggregation_callback(source, url, method, data):
        # Mock callback function to process and merge API responses
        if data:
            return {source: data}
        return {}

    initial_dict = {}
    await aggregator.aggregate_data(api_sources, initial_dict, aggregation_callback)
    print(initial_dict)

# To run the async main function in a script or test suite
if __name__ == "__main__":
    asyncio.run(main())
