// Assume these are defined elsewhere in your project.
extern char** fetchTrimWords(); // Fetch list of words to trim.
extern int getWordListSize();

char* dynamicTrimAndCapitalize(const char *input, size_t initial_limit) {
    if (!input) return NULL;

    char **trim_words = fetchTrimWords();
    if (!trim_words) return NULL;

    int word_list_size = getWordListSize();
    if (word_list_size <= 0) return NULL;

    // Calculate the adjusted limit
    size_t total_word_length = 0;
    for (int i = 0; i < word_list_size; i++) {
        total_word_length += strlen(trim_words[i]);
    }
    size_t average_word_length = total_word_length / word_list_size;
    size_t adjusted_limit = initial_limit + (word_list_size * average_word_length);

    // Trim the input string
    char *trimmed_input = strdup(input);
    if (!trimmed_input) {
        free(trim_words);
        return NULL;
    }

    for (int i = 0; i < word_list_size; i++) {
        char *pos = strstr(trimmed_input, trim_words[i]);
        while (pos) {
            memmove(pos, pos + strlen(trim_words[i]), strlen(pos + strlen(trim_words[i])) + 1);
            pos = strstr(pos, trim_words[i]);
        }
    }

    // Capitalize the first letter of each word
    char *result = malloc(adjusted_limit);
    if (!result) {
        free(trimmed_input);
        free(trim_words); // Assume dynamic allocation; handle accordingly.
        return NULL;
    }

    size_t result_len = 0;
    int in_word = 0;
    for (size_t i = 0; trimmed_input[i] && result_len < adjusted_limit - 1; i++) {
        if (!isspace((unsigned char)trimmed_input[i])) {
            if (!in_word) {
                result[result_len++] = toupper(trimmed_input[i]);
                in_word = 1;
            } else {
                result[result_len++] = trimmed_input[i];
            }
        } else {
            in_word = 0;
            if (result_len < adjusted_limit - 1) result[result_len++] = ' ';
        }
    }

    result[result_len] = '\0';

    // Check length constraint
    if (strlen(result) > adjusted_limit - 1) {
        free(trimmed_input);
        free(result);
        free(trim_words); 
        return NULL;
    }

    free(trimmed_input);
    free(trim_words);

    return result;
}
