pub fn compile_rust_files_in_directory(dir: &Path) -> Result<(u64, u64), String> {
    let start_time = Instant::now();

    let mut peak_memory_usage = 0;
    let mut total_warnings = 0;
    let mut total_errors = 0;

    for entry in fs::read_dir(dir).map_err(|e| e.to_string())? {
        let path = entry.map_err(|e| e.to_string())?.path();

        if path.is_file() && path.extension().and_then(std::ffi::OsStr::to_str) == Some("rs") {
            let output = Command::new("rustc")
                .arg(path.to_str().unwrap())
                .output()
                .map_err(|e| e.to_string())?;

            if !output.status.success() {
                total_errors += 1;
            }

            // Assume this function fetches peak memory usage for the process
            let rss = get_resident_set_size(); 
            peak_memory_usage = peak_memory_usage.max(rss);

            // Log warnings or errors from the output
            if !output.stderr.is_empty() {
                total_warnings += 1;
                println!("Warning/Error: {:?}", String::from_utf8_lossy(&output.stderr));
            }
        }
    }

    let duration = start_time.elapsed();
    println!("Total time taken: {:?}", duration);

    Ok((peak_memory_usage, total_errors + total_warnings))
}

