import json
import threading
from collections import namedtuple, defaultdict
import logging
import concurrent.futures

logging.basicConfig(filename='crypto_errors.log', level=logging.ERROR)

CryptoInfo = namedtuple('CryptoInfo', ['name', 'function_reference', 'params'])

class CryptoModule:
    def __init__(self, config_path):
        self.config_path = config_path
        self.crypto_data = []
        self.load_configuration()

    def load_configuration(self):
        try:
            with open(self.config_path, 'r') as file:
                configs = json.load(file)
                sorted_configs = sorted(configs, key=lambda x: x['name'])
                self.crypto_data = [CryptoInfo(cfg['name'], getattr(__import__(cfg['module']), cfg['function_name']),
                                               cfg.get('params', {})) for cfg in sorted_configs]

            sequence_number = len(self.crypto_data) - 1 if self.crypto_data else None
            print(f"Sequence Number of Last Entry: {sequence_number}")

        except Exception as e:
            logging.error("Error loading configuration", exc_info=True)

    def verify_crypto_functions(self):
        results = {}
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.verify_function, crypto) for crypto in self.crypto_data]

            for future in concurrent.futures.as_completed(futures):
                try:
                    result = future.result()
                    results[result.name] = result.function_reference is not None
                except Exception as e:
                    logging.error("Error verifying function", exc_info=True)

        return results

    def verify_function(self, crypto_info):
        try:
            # Simulate verification process
            if hasattr(crypto_info.function_reference, '__call__'):
                return crypto_info
            else:
                raise ValueError(f"Function {crypto_info.name} is not callable.")
        except Exception as e:
            logging.error(f"Error verifying {crypto_info.name}", exc_info=True)
            raise

if __name__ == "__main__":
    crypto_module = CryptoModule('config.json')
    verification_results = crypto_module.verify_crypto_functions()
    print(verification_results)
