// Dependencies
const axios = require('axios');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

class TextAnalysisModule {
  constructor(settings) {
    this.settings = settings;
    this.regexPatterns = this.initializeRegexPatterns();
  }

  initializeRegexPatterns() {
    const patterns = {};
    if (this.settings.religions.includes('Bible')) {
      patterns.Bible = /\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|\w+ \d+:?\d*-\d*:\d*\)?)/gi;
    }
    if (this.settings.religions.includes('Quran')) {
      patterns.Quran = /\b(?:Al-Fatiha|Al-Baqarah|Aal-E-Imran|An-Nisa'|\w+\s\d+(:?\.\d*)?)/gi;
    }
    if (this.settings.religions.includes('Torah')) {
      patterns.Torah = /\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy \d+:?\d*-\d*:\d*\)?)/gi;
    }
    if (this.settings.religions.includes('Vedas')) {
      patterns.Vedas = /\b(?:Rigveda|Samaveda|Yajurveda|Atharvaveda|\w+\s\d+(:?\.\d*)?)/gi;
    }
    return patterns;
  }

  async analyzeText(text) {
    if (typeof text !== 'string') {
      throw new Error('Invalid input: Text must be a string.');
    }

    const references = {};
    for (const [religion, pattern] of Object.entries(this.regexPatterns)) {
      const matches = text.match(pattern);
      if (matches) {
        references[religion] = [...new Set(matches)];
      }
    }

    await this.verifyReferences(references);
    return references;
  }

  async verifyReferences(references) {
    for (const [religion, refs] of Object.entries(references)) {
      for (const ref of refs) {
        try {
          const response = await axios.get(`https://api.example.com/${religion}/verify?reference=${encodeURIComponent(ref)}`);
          if (!response.data.valid) {
            console.warn(`Invalid reference found: ${ref} in ${religion}`);
          }
        } catch (error) {
          console.error(`Error verifying reference: ${ref}`, error);
        }
      }
    }
  }

  static processLargeText(text, settings) {
    const numWorkers = require('os').cpus().length;
    const chunkSize = Math.ceil(text.length / numWorkers);

    return new Promise((resolve, reject) => {
      let completed = 0;
      let results = [];

      for (let i = 0; i < numWorkers; i++) {
        const start = i * chunkSize;
        const end = start + chunkSize > text.length ? text.length : start + chunkSize;

        const worker = new Worker(__filename, { workerData: { text: text.slice(start, end), settings } });

        worker.on('message', (result) => {
          results.push(result);
          completed += 1;
          if (completed === numWorkers) {
            resolve(results.flat());
          }
        });

        worker.on('error', reject);
      }
    });
  }
}

if (!isMainThread && typeof workerData !== 'undefined') {
  const { text, settings } = workerData;
  const module = new TextAnalysisModule(settings);

  module.analyzeText(text).then((references) => {
    parentPort.postMessage(references);
  }).catch(err => {
    parentPort.postMessage({ error: err.message });
  });
}

module.exports = TextAnalysisModule;

