using json = nlohmann::json;

class ConfigManager {
public:
    using ObserverCallback = std::function<void(const std::string&, const std::string&)>;

    ConfigManager(const std::vector<std::string>& file_paths) {
        loadSettings(file_paths);
    }

    std::shared_ptr<ConfigManager> getInstance(const std::vector<std::string>& file_paths) {
        static std::shared_ptr<ConfigManager> instance;
        if (!instance) {
            std::lock_guard<std::mutex> lock(initMutex);
            if (!instance) {
                instance = std::make_shared<ConfigManager>(file_paths);
            }
        }
        return instance;
    }

    std::string getSetting(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = settings_.find(key);
        if (it != settings_.end()) {
            validateSetting(it->first, it->second);
            notifyObservers(it->first, it->second.get<std::string>());
            return it->second.get<std::string>();
        }
        throw std::runtime_error("Key not found");
    }

    void setSetting(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        settings_[key] = value;
        validateSetting(key, value);
        notifyObservers(key, value);
        saveSettings();
    }

    void addObserver(ObserverCallback callback) {
        std::lock_guard<std::mutex> lock(observerMutex);
        observers_.push_back(callback);
    }

private:
    void loadSettings(const std::vector<std::string>& file_paths) {
        for (const auto& path : file_paths) {
            std::ifstream i(path);
            if (!i.is_open()) continue;
            json j;
            try {
                i >> j;
                for (auto it = j.begin(); it != j.end(); ++it) {
                    settings_[it.key()] = it.value();
                }
            } catch (...) {
                std::cerr << "Error reading JSON from file: " << path << '\n';
            }
        }
    }

    void saveSettings() {
        for (const auto& [key, value] : settings_) {
            // Implement saving logic
        }
    }

    void validateSetting(const std::string& key, const json& value) {
        if (!value.is_string()) {
            throw std::runtime_error("Invalid type for setting: " + key);
        }
        // Add range validation as needed
    }

    void notifyObservers(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(observerMutex);
        for (const auto& observer : observers_) {
            observer(key, value);
        }
    }

private:
    mutable std::mutex mutex_;
    mutable std::mutex initMutex;
    mutable std::mutex observerMutex;

    std::map<std::string, json> settings_;
    std::vector<ObserverCallback> observers_;
};

// Usage example
int main() {
    std::vector<std::string> file_paths = {"device1.json", "device2.json"};
    auto configManager = ConfigManager::getInstance(file_paths);

    configManager->addObserver([](const std::string& key, const std::string& value) {
        std::cout << "Setting changed: " << key << " = " << value << '\n';
    });

