import java.io.*;
import java.sql.Connection;
import java.sql.DriverManager;
import java.util.concurrent.*;
import org.json.JSONObject;  // Assume using an external library for JSON handling

// Main class to manage command execution and database integration
public class CommandExecutor {
    private static final String DB_URL_SQL = "jdbc:sqlserver://localhost;databaseName=myDB";
    private static final String DB_URL_NOSQL = "mongodb://localhost:27017/myDatabase";
    private static final int MAX_RETRIES = 3;
    private static ExecutorService executorService = Executors.newFixedThreadPool(10); // Thread pool for concurrency
    private static Connection sqlConnection;
    private static MongoClient noSqlClient;

    public static void main(String[] args) {
        try (final Server server = new RESTServer()) {
            server.start();
        }
    }

    public static void executeCommands() {
        File fileToDelete = new File("path/to/file.txt");
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }

        String[] commands = {"mkdir /tmp/testdir", "touch /tmp/testdir/testfile.txt", "ls -l /tmp/testdir"};

        for (String command : commands) {
            executorService.submit(() -> runCommandWithRetries(command));
        }
    }

    private static void runCommandWithRetries(String command) {
        int attempt = 0;
        boolean success = false;

        while (attempt < MAX_RETRIES && !success) {
            try {
                processCommand(command);
                success = true;
            } catch (IOException e) {
                handleTransientError(e, attempt);
                attempt++;
                sleepWithExponentialBackoff(attempt); // Exponential backoff strategy
            }
        }

        if (!success) {
            logError("Failed to execute command: " + command);
        }
    }

    private static void processCommand(String command) throws IOException {
        Process process = Runtime.getRuntime().exec(command);
        handleStreams(process);

        logResult(command, "Success");
    }

    private static void handleStreams(Process process) throws IOException {
        try (BufferedReader stdOut = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader stdErr = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            String line;
            while ((line = stdOut.readLine()) != null) {
                System.out.println(line);
                logResult(command, line);
            }

            if ((line = stdErr.readLine()) != null) {
                throw new IOException("Error executing command: " + line);
            }
        }
    }

    private static void handleTransientError(Exception e, int attempt) {
        // Implement logic to determine if the error is transient
        System.err.println("Attempt " + (attempt + 1) + ": " + e.getMessage());
    }

    private static void sleepWithExponentialBackoff(int attempt) {
        try {
            long delay = Math.min(1000L * (1 << attempt), 16000); // Max delay of 16 seconds
            Thread.sleep(delay);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
        }
    }

    private static void logResult(String command, String result) {
        try (Connection sqlConn = DriverManager.getConnection(DB_URL_SQL)) {
            sqlConn.createStatement().executeUpdate("INSERT INTO CommandLog (command, result) VALUES (?, ?)", command, result);
        } catch (Exception e) {
            noSqlClient.getDatabase("myDatabase").getCollection("CommandLog")
                .insertOne(new Document("command", command).append("result", result));
        }
    }

    private static void logError(String error) {
        System.err.println(error);
        // Log to database or external logging service
    }
}

// REST API Server implementation using a simple framework
class RESTServer {
    public void start() {
        // Assume we have an embedded HTTP server, like Jetty or Undertow
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);

        server.createContext("/start-job", (exchange -> {
            if ("GET".equals(exchange.getRequestMethod())) {
                CommandExecutor.executeCommands();
                sendResponse(exchange, "Job started");
            }
            exchange.close();
        }));

        server.setExecutor(executorService); // Use the executor service for handling requests
        server.start();
    }

    private void sendResponse(HttpExchange exchange, String response) throws IOException {
        exchange.sendResponseHeaders(200, response.length());
        OutputStream os = exchange.getResponseBody();
        os.write(response.getBytes());
        os.close();
    }
}

