<?php

use GuzzleHttp\Client;
use Psr\Log\LoggerInterface;

class ClinicStatusUpdater
{
    private $redisClient;
    private $httpClient;
    private $logger;
    private $sessionHandler;

    public function __construct($redisClient, LoggerInterface $logger)
    {
        $this->redisClient = $redisClient;
        $this->httpClient = new Client();
        $this->logger = $logger;
        $this->sessionHandler = session_save_path(session_save_path());
    }

    private function authenticate()
    {
        if (!isset($_SESSION['access_token'])) {
            $tokenResponse = $this->httpClient->post('https://auth.example.com/oauth/token', [
                'form_params' => [
                    'grant_type' => 'client_credentials',
                    'client_id' => 'your_client_id',
                    'client_secret' => 'your_client_secret',
                ],
                'headers' => ['Content-Type' => 'application/x-www-form-urlencoded'],
            ]);

            $tokenData = json_decode($tokenResponse->getBody(), true);
            $_SESSION['access_token'] = openssl_encrypt($tokenData['access_token'], 'AES-256-CBC', 'encryption_key');
        }
    }

    private function authorize($clinicId)
    {
        $ipValidationUrl = "https://geo-service.example.com/validate?ip=" . $_SERVER['REMOTE_ADDR'];
        $validationResponse = $this->httpClient->get($ipValidationUrl);

        if (!in_array($_SERVER['REMOTE_ADDR'], json_decode($validationResponse->getBody(), true))) {
            throw new Exception('Unauthorized IP address.');
        }

        $activeClinics = $this->getCachedActiveClinics();
        if (!in_array($clinicId, $activeClinics)) {
            throw new Exception('Clinic not authorized.');
        }
    }

    private function getCachedActiveClinics()
    {
        $cachedClinics = $this->redisClient->get('active_clinic_ids');
        if ($cachedClinics) {
            return json_decode($cachedClinics, true);
        }

        $response = $this->httpClient->get('https://api.example.com/clinics/active');
        $clinicIds = json_decode($response->getBody(), true);

        $this->redisClient->setex('active_clinic_ids', 3600, json_encode($clinicIds));

        return $clinicIds;
    }

    private function updateClinicStatus($clinicId, $status)
    {
        try {
            $pdo = new PDO("mysql:host=dynamic_host_based_on_clinic_id;dbname=database_for_$clinicId", 'username', 'password');
            $pdo->beginTransaction();

            $stmt = $pdo->prepare('UPDATE clinic_status SET status = :status WHERE id = :id');
            $stmt->execute([':status' => $status, ':id' => $clinicId]);

            // Log the operation
            $logEntryId = uniqid();
            $this->logger->info("Update log entry ID: $logEntryId for clinicId: $clinicId", ['status' => $status]);

            $pdo->commit();

        } catch (PDOException $e) {
            $pdo->rollBack();
            throw new Exception('Database error occurred.');
        }
    }

    private function deleteData($clinicId)
    {
        try {
            $pdo = new PDO("mysql:host=dynamic_host_based_on_clinic_id;dbname=database_for_$clinicId", 'username', 'password');
            $stmt = $pdo->prepare('DELETE FROM clinic_data WHERE clinic_id = :id');
            $stmt->execute([':id' => $clinicId]);
        } catch (PDOException $e) {
            throw new Exception('Data deletion error.');
        }
    }

    public function handleRequest($clinicId, $status)
    {
        try {
            session_start();
            $this->authenticate();
            openssl_decrypt($_SESSION['access_token'], 'AES-256-CBC', 'encryption_key');

            $this->authorize($clinicId);
            $this->updateClinicStatus($clinicId, $status);

            return "-----BEGIN SUCCESS MESSAGE-----
SUCCESSFUL OPERATION
-----END SUCCESS MESSAGE-----";

        } catch (Exception $e) {
            $this->logger->error('Error: ' . $e->getMessage());
            throw new Exception($e->getMessage(), 0, $e);
        }
    }

    public function deleteClinicData($clinicId)
    {
        try {
            session_start();
            $this->authenticate();
            openssl_decrypt($_SESSION['access_token'], 'AES-256-CBC', 'encryption_key');

            $this->authorize($clinicId);

            $this->deleteData($clinicId);

            return "-----BEGIN SUCCESS MESSAGE-----
DATA DELETED SUCCESSFULLY
-----END SUCCESS MESSAGE-----";

        } catch (Exception $e) {
            $this->logger->error('Error: ' . $e->getMessage());
            throw new Exception($e->getMessage(), 0, $e);
        }
    }
}

