// JavaScript Program: Dynamic File Loader

class DynamicFileLoader {
    constructor(apiEndpoint) {
        this.apiEndpoint = apiEndpoint;
        this.fileCache = new Map();
        this.fileDependencies = {};
        this.loadingQueue = [];
        this.isUpdating = false;

        // Periodically check for updates from the API
        setInterval(() => this.checkForUpdates(), 5000);
    }

    async fetchFileList() {
        try {
            const response = await fetch(this.apiEndpoint);
            if (!response.ok) throw new Error('Failed to fetch file list');
            return await response.json();
        } catch (error) {
            console.error('Error fetching file list:', error);
        }
    }

    async checkForUpdates() {
        this.isUpdating = true;
        const fileList = await this.fetchFileList();

        // Update dependencies and files if the list has changed
        for (const { url, dependencies } of fileList) {
            if (!this.fileDependencies[url] || JSON.stringify(this.fileDependencies[url]) !== JSON.stringify(dependencies)) {
                this.fileDependencies[url] = dependencies;
                if (!this.loadingQueue.includes(url)) {
                    this.loadingQueue.push(url);
                }
            }
        }

        await this.processLoadingQueue();
        this.isUpdating = false;
    }

    async processLoadingQueue() {
        while (this.loadingQueue.length > 0) {
            const url = this.loadingQueue.shift();

            // Check for dependencies first
            if (!this.areDependenciesLoaded(url)) continue;

            try {
                await this.loadAndExecuteFile(url);
            } catch (error) {
                console.error(`Error loading/executing file ${url}:`, error);
            }
        }
    }

    async loadAndExecuteFile(url) {
        if (this.fileCache.has(url)) return; // Already loaded

        const response = await fetch(url);
        if (!response.ok) throw new Error('Failed to load script');

        const scriptText = await response.text();
        this.fileCache.set(url, scriptText);

        try {
            const scriptElement = document.createElement('script');
            scriptElement.textContent = scriptText;
            document.body.appendChild(scriptElement).parentNode.removeChild(scriptElement);
            console.log(`Successfully executed: ${url}`);
        } catch (error) {
            throw new Error(`Error executing script from ${url}: ${error.message}`);
        }
    }

    areDependenciesLoaded(url) {
        const dependencies = this.fileDependencies[url] || [];
        return dependencies.every(dep => this.fileCache.has(dep));
    }

    addFileToLoad(url, dependencies = []) {
        if (!this.fileDependencies[url]) {
            this.fileDependencies[url] = dependencies;
            this.loadingQueue.push(url);
        }
    }

    removeFileFromLoad(url) {
        delete this.fileDependencies[url];
        this.loadingQueue = this.loadingQueue.filter(item => item !== url);
        this.fileCache.delete(url); // Cleanup cache
    }
}

// Example usage:
const fileLoader = new DynamicFileLoader('https://example.com/api/files');
fileLoader.addFileToLoad('script1.js', []);
fileLoader.addFileToLoad('script2.js', ['script1.js']);
