using System;
using System.IO;
using System.Net.Security;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

public struct ConfigStructure {
    public string LocalConfigPath;
    public (string IP, int Port) RemoteHost;
    public string[] CommandList;
    public Action<string> Callback;
}

public class FileProcessor {
    private static readonly object LockObject = new();

    public async Task ProcessFileAndExecuteRemoteCommands(byte[] fileData, ConfigStructure config, int timeoutInSeconds) {
        var localConfigPath = config.LocalConfigPath;

        // Read and validate local configuration
        string configContent = await ReadLocalConfigurationAsync(localConfigPath);

        using (var client = new TcpClient()) {
            try {
                await ConnectToRemoteHostAsync(client, config.RemoteHost.IP, config.RemoteHost.Port, timeoutInSeconds);

                using var sslStream = new SslStream(client.GetStream(), false,
                    async (sender, certificate, chain, sslPolicyErrors) => await Task.FromResult(true)); // Accept all certificates
                sslStream.AuthenticateAsClient(config.RemoteHost.IP);

                foreach (var command in config.CommandList) {
                    try {
                        string output = await ExecuteRemoteCommandAsync(sslStream, command);
                        config.Callback?.Invoke(output);
                    } catch (Exception ex) {
                        Console.WriteLine($"Error executing command '{command}': {ex.Message}");
                        // Retry logic could be added here
                    }
                }
            } finally {
                client.Close();
            }
        }
    }

    private async Task<string> ReadLocalConfigurationAsync(string filePath) {
        if (!File.Exists(filePath)) throw new FileNotFoundException("Config file not found");

        using var reader = new StreamReader(filePath);
        return await reader.ReadToEndAsync();
    }

    private async Task ConnectToRemoteHostAsync(TcpClient client, string ip, int port, int timeoutInSeconds) {
        var cts = new System.Threading.CancellationTokenSource(timeoutInSeconds * 1000);
        try {
            await client.ConnectAsync(ip, port).ConfigureAwait(false);
            cts.Token.ThrowIfCancellationRequested();
        } catch (Exception ex) when (!(ex is TaskCanceledException)) {
            throw new TimeoutException("Connection to remote host timed out", ex);
        }
    }

    private async Task<string> ExecuteRemoteCommandAsync(SslStream sslStream, string command) {
        var buffer = Encoding.UTF8.GetBytes(command + "\n");
        await sslStream.WriteAsync(buffer, 0, buffer.Length).ConfigureAwait(false);

        var responseBuffer = new byte[4096];
        int bytesRead;
        using (var ms = new MemoryStream()) {
            do {
                bytesRead = await sslStream.ReadAsync(responseBuffer, 0, responseBuffer.Length).ConfigureAwait(false);
                if (bytesRead > 0) ms.Write(responseBuffer, 0, bytesRead);
            } while (bytesRead != 0);

            return Encoding.UTF8.GetString(ms.ToArray());
        }
    }
}

