Below is a JavaScript module that implements the requested functionality. This solution uses modern ES6+ features and Node.js APIs to efficiently handle buffered data chunks, files, and streams.

```javascript
const fs = require('fs');
const { Readable } = require('stream');

/**
 * Copies specified byte ranges from various sources into a new buffer.
 *
 * @param {Array} sources - An array of source objects. Each object has:
 *   - type: 'buffer', 'file', or 'stream'
 *   - data: For 'buffer' and 'stream', the actual Buffer or Readable instance
 *           For 'file', a string representing the file path
 *   - byteRanges: An array of {start, end} objects specifying byte ranges to copy
 * @returns {Promise<Buffer>} A promise that resolves with the combined buffer.
 */
async function copyByteRanges(sources) {
  const buffers = [];

  for (const source of sources) {
    switch (source.type) {
      case 'buffer': {
        const { data, byteRanges } = source;
        for (const range of byteRanges) {
          if (range.start < 0 || range.end >= data.length || range.start > range.end) {
            throw new Error('Invalid byte range');
          }
          buffers.push(data.slice(range.start, range.end + 1));
        }
        break;
      }

      case 'file': {
        const { path, byteRanges } = source;
        const fileStats = await fs.promises.stat(path);

        for (const range of byteRanges) {
          if (range.start < 0 || range.end >= fileStats.size || range.start > range.end) {
            throw new Error('Invalid byte range');
          }

          buffers.push(await readFileRange(path, range));
        }
        break;
      }

      case 'stream': {
        const { data: stream, byteRanges } = source;

        for (const range of byteRanges) {
          if (range.start < 0 || range.end < range.start) {
            throw new Error('Invalid byte range');
          }

          buffers.push(await readStreamRange(stream, range));
        }

        break;
      }

      default:
        throw new Error('Unsupported source type');
    }
  }

  return Buffer.concat(buffers);
}

async function readFileRange(filePath, { start, end }) {
  const fileStats = await fs.promises.stat(filePath);

  if (end >= fileStats.size) {
    end = fileStats.size - 1;
  }

  return new Promise((resolve, reject) => {
    let bytesRead = 0;
    const buffer = Buffer.alloc(end - start + 1);

    const fd = fs.openSync(filePath, 'r');

    try {
      fs.read(fd, buffer, 0, end - start + 1, start, (err, bytes) => {
        if (err) {
          return reject(err);
        }
        resolve(buffer.slice(0, bytes));
      });
    } finally {
      fs.closeSync(fd);
    }
  });
}

async function readStreamRange(stream, { start, end }) {
  const skipBytes = start;

  stream.readable = true; // Ensure the stream is readable
  let bytesRead = 0;
  const buffer = Buffer.alloc(end - start + 1 || 1024);

  return new Promise((resolve, reject) => {
    if (skipBytes > 0) {
      for (let i = 0; i < skipBytes && !stream.readableEnded; i++) {
        stream.read(1);
      }
    }

    const readLoop = () => {
      let bytesReadNow;

      do {
        bytesReadNow = stream.read(buffer, bytesRead, buffer.length - bytesRead);
        if (bytesReadNow === null) break;
        bytesRead += bytesReadNow;

        if (end !== undefined && bytesRead >= end - start + 1) {
          resolve(buffer.slice(0, bytesRead));
          return;
        }
      } while (!stream.readableEnded);

      if (!stream.readableEnded) {
        stream.once('readable', readLoop);
      } else {
        reject(new Error('Stream ended unexpectedly'));
      }
    };

    readLoop();
  });
}

// Example usage
(async () => {
  try {
    const sources = [
      { type: 'buffer', data: Buffer.from('Hello, World!'), byteRanges: [{ start: 0, end: 4 }] },
      { type: 'file', path: './example.txt', byteRanges: [{ start: 5, end: 10 }] },
      // Stream example
      {
        type: 'stream',
        data: Readable.from('Streamed Data Chunk'),
        byteRanges: [{ start: 0, end: 14 }],
      }
    ];

    const resultBuffer = await copyByteRanges(sources);
    console.log(resultBuffer.toString());
  } catch (error) {
    console.error(error.message);
  }
})();
```

