    private AtomicInteger filteredPacketsCount = new AtomicInteger(0);
    private AtomicInteger totalPacketCount = new AtomicInteger(0);
    private AtomicLong totalPacketSize = new AtomicLong(0);

    public void processPacket(Packet packet) {
        if (packet == null) return;

        updateMetrics(packet, false);

        boolean shouldFilter = shouldFilterPacket(packet);
        if (shouldFilter) {
            filteredPacketsCount.incrementAndGet();
        } else {
            addToWindow(packet);
        }
    }

    private void updateMetrics(Packet packet, boolean isFiltered) {
        totalPacketCount.incrementAndGet();
        totalPacketSize.addAndGet(packet.getSize());

        if (isFiltered) {
            filteredPacketsCount.incrementAndGet();
        }
    }

    private void addToWindow(Packet packet) {
        if (packetWindow.size() >= MAX_WINDOW_SIZE) {
            Packet removed = packetWindow.poll();
            totalPacketSize.addAndGet(-removed.getSize());
        }
        packetWindow.offer(packet);
    }

