class OctreeNode {
public:
    struct Bounds {
        float x, y, z; // Center coordinates
        float size; // Size of the node (assuming a cube)
    };

private:
    std::unique_ptr<OctreeNode> children[8];
    std::vector<void*> objects;
    Bounds bounds;
    const static int MAX_OBJECTS = 10;
    const static int MAX_DEPTH = 5;

public:
    OctreeNode(const Bounds& b, int depth) : bounds(b), depth(depth) {}

    void insert(void* obj);
    bool remove(void* obj);
    std::vector<void*> query(const Bounds& range);

private:
    int getOctantIndex(float x, float y, float z);
    void subdivide();
};

void OctreeNode::insert(void* obj) {
    if (depth == MAX_DEPTH || children[0] == nullptr) {
        objects.push_back(obj);
        return;
    }

    // Subdivision logic here
    int index = getOctantIndex(...); // Calculate based on object position
    std::shared_lock lock(mutex);
    children[index]->insert(obj);
}

bool OctreeNode::remove(void* obj) {
    for (auto it = objects.begin(); it != objects.end(); ++it) {
        if (*it == obj) {
            objects.erase(it);
            return true;
        }
    }

    // Check in child nodes
    std::shared_lock lock(mutex);
    for (auto& child : children) {
        if (child && child->remove(obj)) {
            return true;
        }
    }

    return false;
}

std::vector<void*> OctreeNode::query(const Bounds& range) {
    std::vector<void*> result;

    // Query logic here

    return result;
}

