using System;
using System.IO;
using System.Xml.Linq;

namespace RTSGameConfigLoader
{
    public class GameConfiguration
    {
        public int TileSize { get; set; }
        public (int, int) WorldDimensions { get; set; }
        public float CameraSpeed { get; set; }

        public static GameConfiguration LoadFromXml(string filePath)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("The configuration XML file was not found.");

            XDocument doc = XDocument.Load(filePath);

            var tileSize = int.Parse(doc.Root.Element("TileSize").Value);
            var worldWidth = int.Parse(doc.Root.Element("WorldDimensions").Element("Width").Value);
            var worldHeight = int.Parse(doc.Root.Element("WorldDimensions").Element("Height").Value);
            var cameraSpeed = float.Parse(doc.Root.Element("CameraSpeed").Value);

            return new GameConfiguration
            {
                TileSize = tileSize,
                WorldDimensions = (worldWidth, worldHeight),
                CameraSpeed = cameraSpeed
            };
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                var config = GameConfiguration.LoadFromXml("config.xml");
                Console.WriteLine($"Tile Size: {config.TileSize}");
                Console.WriteLine($"World Dimensions: {config.WorldDimensions.Item1} x {config.WorldDimensions.Item2}");
                Console.WriteLine($"Camera Speed: {config.CameraSpeed}");
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error loading configuration: {ex.Message}");
            }
        }
    }
}
