use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn create_directory_with_env_var(dir_name: &str) -> Result<PathBuf, String> {
    // Check if environment variable is already set
    match env::var("GAME_DIR_PATH") {
        Ok(path_str) => {
            let path = PathBuf::from(path_str);
            if path.exists() && path.is_dir() {
                return Ok(path);
            } else {
                eprintln!("Environment variable points to an invalid directory.");
            }
        },
        Err(_) => {}
    }

    // Create a new directory
    let new_dir_path = Path::new(&dir_name).to_path_buf();
    match fs::create_dir_all(&new_dir_path) {
        Ok(()) => {
            env::set_var("GAME_DIR_PATH", new_dir_path.to_str().unwrap_or_default());
            Ok(new_dir_path)
        },
        Err(e) => Err(format!("Failed to create directory: {}", e)),
    }
}

fn main() -> Result<(), String> {
    match create_directory_with_env_var("new_game_directory") {
        Ok(path) => println!("Directory path is set to environment variable: {:?}", path),
        Err(e) => eprintln!("Error: {}", e),
    }

    Ok(())
}
