```javascript
class ScriptLoader {
  constructor(dependencies) {
    this.dependencies = dependencies;
    this.loadedScripts = {};
    this.scriptQueue = [];
    this.loadAttempts = new Map();
  }

  loadScripts(entryPoints) {
    entryPoints.forEach(entry => {
      if (!this.isLoaded(entry)) {
        this.enqueueScriptLoad(entry, 0);
      }
    });

    this.processQueue();
  }

  enqueueScriptLoad(scriptName, attemptNumber) {
    const dependencies = this.dependencies[scriptName] || [];
    const areDependenciesLoaded = dependencies.every(dep => this.isLoaded(dep));

    if (areDependenciesLoaded) {
      this.scriptQueue.push(scriptName);
    } else {
      dependencies.forEach(dep => this.enqueueScriptLoad(dep, 0));
    }

    if (!this.loadAttempts.has(scriptName)) {
      this.loadAttempts.set(scriptName, attemptNumber + 1);
    }
  }

  isLoaded(scriptName) {
    return !!this.loadedScripts[scriptName];
  }

  processQueue() {
    while (this.scriptQueue.length > 0) {
      const scriptName = this.scriptQueue.shift();

      if (!this.loadAttempts.has(scriptName)) continue;

      const attemptNumber = this.loadAttempts.get(scriptName);

      loadScriptAsync(scriptName, () => {
        this.loadedScripts[scriptName] = true;
        console.log(`Successfully loaded: ${scriptName}`);
      }, error => {
        if (attemptNumber < 3) {
          setTimeout(() => {
            console.warn(`Retrying to load ${scriptName}, attempt ${attemptNumber + 1}...`);
            this.enqueueScriptLoad(scriptName, attemptNumber);
          }, Math.pow(2, attemptNumber));
        } else {
          console.error(`Failed to load ${scriptName} after ${attemptNumber} attempts.`);
        }
      });
    }
  }
}

function loadScriptAsync(src, successCallback, errorCallback) {
  const cachedScript = document.querySelector(`script[src="${src}"]`);

  if (cachedScript) {
    successCallback();
    return;
  }

  const scriptElement = document.createElement('script');
  scriptElement.src = src;

  scriptElement.onload = () => {
    successCallback();
  };

  scriptElement.onerror = () => {
    errorCallback();
  };

  document.head.appendChild(scriptElement);
}

