function handleUserRequest($request) {
    // Rate limiting setup
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $rateLimitKey = "user_request_limit_{$ipAddress}";
    if (!checkRateLimit($rateLimitKey)) {
        return jsonResponse(['message' => 'error', 'status_code' => 429]);
    }

    // Basic input validation using regex
    if (!validateInputFormat($request['name'], $request['email'])) {
        logOperation('Failed Validation', ['ip_address' => $ipAddress, 'details' => 'Invalid name or email format']);
        return jsonResponse(['message' => 'error', 'status_code' => 400]);
    }

    // Check if passwords match and meet complexity requirements
    if ($request['password'] !== $request['confirm_password']) {
        logOperation('Failed Password Match', ['ip_address' => $ipAddress]);
        return jsonResponse(['message' => 'error', 'status_code' => 400]);
    }

    if (!validatePasswordComplexity($request['password'])) {
        logOperation('Failed Password Complexity', ['ip_address' => $ipAddress]);
        return jsonResponse(['message' => 'error', 'status_code' => 400]);
    }

    // Validate with external authentication service
    if (!externalAuthServiceValidatePassword($request['email'], $request['password'])) {
        logOperation('External Auth Service Failure', ['ip_address' => $ipAddress, 'details' => 'Invalid password']);
        return jsonResponse(['message' => 'error', 'status_code' => 400]);
    }

    // Connect to the database
    $pdo = new PDO($dsn, $username, $password);
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    try {
        if (isset($request['sub_action']) && $request['sub_action'] === 'delete') {
            return deleteUserAccount($request['id'], $pdo);
        }

        // Check for existing user with same email and tenant
        $tenantId = isset($request['tenant_id']) ? $request['tenant_id'] : null;
        if (checkUserExists($request['email'], $tenantId, $pdo)) {
            logOperation('Email Exists', ['ip_address' => $ipAddress]);
            return jsonResponse(['message' => 'error', 'status_code' => 400]);
        }

        // Check for existing user with same name and tenant
        if (checkUserNameExists($request['name'], $tenantId, $pdo)) {
            logOperation('Name Exists', ['ip_address' => $ipAddress]);
            return jsonResponse(['message' => 'error', 'status_code' => 400]);
        }

        if (isset($request['id'])) { // Update existing user
            return updateUserAccount($request, $pdo);
        } else { // Create new user
            return createUserAccount($request, $pdo);
        }
    } catch (Exception $e) {
        logOperation('Database Error', ['ip_address' => $ipAddress, 'details' => $e->getMessage()]);
        return jsonResponse(['message' => 'error', 'status_code' => 500]);
    } finally {
        // Cleanup database connection
        $pdo = null;
    }
}

function createUserAccount($request, $pdo) {
