            // Process incoming messages
            processIncomingMessages(kafkaConsumer, sensorConfigs);

            // Step 4: Connect to PostgreSQL database
            Connection dbConnection = connectToDatabase("jdbc:postgresql://localhost:5432/sensor_data");

            // Step 5: Batch processing for anomaly detection and alerts
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
            scheduler.scheduleAtFixedRate(() -> processBatchData(dbConnection), 0, 10, TimeUnit.MINUTES);

            // Step 7: Console interface to monitor health/status
            startConsoleInterface();

