// Define structures for configuration and storage nodes
typedef struct {
    long min_key;
    long max_key;
} KeyRange;

typedef struct {
    char *key;
    int value;
    long offset;
} Record;

typedef struct {
    const char *service_url;
    // Add more fields as needed for metadata retrieval or other configurations
} StorageNode;

// Global variables and mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
StorageNode *nodes;  // Assume this is populated elsewhere with node details

// Function prototypes
KeyRange parse_key_range(const char *json_config);
char *get_md5_hash(const char *input);
void distribute_keys_and_assign_values(KeyRange range, Record **records, int num_records);
int interact_with_storage_service(StorageNode *node, const char *key, int value, int attempt);

// Main function to process the JSON configuration and keys
void process_configuration(const char *json_config, Record **keys, int num_keys) {
    pthread_t threads[num_keys];
    KeyRange range = parse_key_range(json_config);
    distribute_keys_and_assign_values(range, keys, num_keys);

    // Launch threads for concurrent processing of key assignments
    for (int i = 0; i < num_keys; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))interact_with_storage_service, (void *)keys[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    // Join threads
    for (int i = 0; i < num_keys; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Get MD5 hash of the JSON configuration string
    char *md5_hash = get_md5_hash(json_config);
    printf("MD5 Hash: %s\n", md5_hash);

    // Cleanup memory
    free(md5_hash);
}

// Parse JSON configuration to determine key range
KeyRange parse_key_range(const char *json_config) {
    KeyRange range;
    json_error_t error;
    json_t *root = json_loads(json_config, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    const char *key_min = json_string_value(json_object_get(root, "min_key"));
    const char *key_max = json_string_value(json_object_get(root, "max_key"));

    if (key_min && key_max) {
        range.min_key = strtol(key_min, NULL, 10);
        range.max_key = strtol(key_max, NULL, 10);
    } else {
        fprintf(stderr, "Invalid JSON configuration\n");
        exit(EXIT_FAILURE);
    }

    json_decref(root);
    return range;
}

// Generate MD5 hash of input string
char *get_md5_hash(const char *input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)input, strlen(input), (unsigned char *)&digest);

    // Convert to hex string
    static char md5string[33];
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(&md5string[i*2], "%02x", (int)digest[i]);

    return strdup(md5string);
}

// Distribute keys and assign values within the specified range
void distribute_keys_and_assign_values(KeyRange range, Record **records, int num_records) {
    pthread_mutex_lock(&lock);

    // Logic to determine values based on key range
    long total_range = range.max_key - range.min_key + 1;
    for (int i = 0; i < num_records; ++i) {
        records[i]->offset = (records[i]->value % total_range) + range.min_key;
    }

    pthread_mutex_unlock(&lock);
}

