}

static void cache_results(SecureCommLib *lib, CryptoAlgorithm **algorithms, size_t count) {
    pthread_mutex_lock(&lib->lock);

    if (count > lib->capacity) {
        lib->capacity = count;
        lib->algorithms = realloc(lib->algorithms, sizeof(CryptoAlgorithm *) * lib->capacity);
        if (!lib->algorithms) {
            handle_error(ERROR_THREAD_SAFETY, "Memory allocation failed during caching.");
            pthread_mutex_unlock(&lib->lock);
            return;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        add_algorithm_to_lib(lib, algorithms[i]);
    }

    pthread_mutex_unlock(&lib->lock);
}

static int add_algorithm_to_lib(SecureCommLib *lib, CryptoAlgorithm *algorithm) {
    for (size_t i = 0; i < lib->count; ++i) {
        if (strcmp(lib->algorithms[i]->name, algorithm->name) == 0) {
            handle_error(DUPLICATE_NAME_ERROR, "Duplicate algorithm name detected.");
            return DUPLICATE_NAME_ERROR;
        }
    }

    lib->algorithms[lib->count++] = algorithm;
    return SUCCESS;
}

static int handle_error(int error_code, const char *message) {
    // Log the error message
    fprintf(stderr, "Error [%d]: %s\n", error_code, message);
    return error_code;
}
