```javascript
function extractBibleBooks(text, ignoreList = []) {
    // Regular expressions to match Old and New Testament books
    const oldTestamentBooksRegex = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon)\b/gi;
    const newTestamentBooksRegex = /\b(Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonicians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)\b/gi;
    const combinedRegex = new RegExp(`\\b(${oldTestamentBooksRegex.source}|${newTestamentBooksRegex.source})\\b`, 'gi');

    // List of all Bible books, to filter out non-Bible and apocryphal books
    const bibleBooks = [
        "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
        "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel", "1 Kings",
        "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra", "Nehemiah",
        "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "Song of Solomon",
        "Matthew", "Mark", "Luke", "John", "Acts", "Romans", 
        "1 Corinthians", "2 Corinthians", "Galatians", "Ephesians", "Philippians",
        "Colossians", "1 Thessalonians", "2 Thessalonians", "1 Timothy", 
        "2 Timothy", "Titus", "Philemon", "Hebrews", "James", "1 Peter",
        "2 Peter", "1 John", "2 John", "3 John", "Jude", "Revelation"
    ];

    // Filter books based on ignoreList
    const validBooks = bibleBooks.filter(book => !ignoreList.includes(book));

    if (typeof text !== 'string') {
        throw new Error("Invalid input: Text must be a string.");
    }

    // Object to store the count of each book found
    const bookCount = {};

    // Find matches and count occurrences
    let match;
    while ((match = combinedRegex.exec(text))) {
        const bookName = match[0].replace(/\s+/g, ' ').trim(); // Normalize whitespace
        if (validBooks.includes(bookName)) {
            if (!bookCount[bookName]) {
                bookCount[bookName] = 1;
            } else {
                bookCount[bookName]++;
            }
        }
    }

    // Return the result or a message if no books were found
    return Object.keys(bookCount).length > 0 ? bookCount : "No Bible books found in the text.";
}
