#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    int case_sensitive;
    int verbose;
    char *input_file;
    char *output_file;
} Options;

Options options = {0, 0, NULL, "report.txt"};

FILE *log_file;

void log_message(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

void handle_signal(int signal) {
    log_message("Received termination signal. Exiting...");
    exit(0);
}

void parse_arguments(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "cso:hv")) != -1) {
        switch (opt) {
            case 'c':
                options.case_sensitive = 1;
                break;
            case 's':
                options.verbose = 1;
                break;
            case 'o':
                options.output_file = optarg;
                break;
            case 'h':
                printf("Usage: %s [options] input_file\n"
                       "Options:\n"
                       "  -c, --cs       Case-sensitive mode.\n"
                       "  -s, --verbose  Enable verbose output.\n"
                       "  -o <file>      Specify output file.\n"
                       "  -h, --help     Display this help message.\n", argv[0]);
                exit(0);
            case 'v':
                options.verbose = 1;
                break;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: No input file specified.\n");
        printf("Usage: %s [options] input_file\n", argv[0]);
        exit(1);
    }

    options.input_file = argv[optind];
}

void process_line(char *line) {
    // Example pattern processing
    if (strstr(line, "pattern") != NULL) {
        log_message("Pattern found in line.");
    }
}

void* thread_func(void *arg) {
    char line[MAX_LINE_LENGTH];

    FILE *input_file = fopen(options.input_file, "r");
    if (!input_file) {
        log_message("Error: Cannot open input file.");
        return NULL;
    }

    while (fgets(line, sizeof(line), input_file)) {
        process_line(line);
    }

    fclose(input_file);
    return NULL;
}

int main(int argc, char **argv) {
    signal(SIGINT, handle_signal);

    log_file = fopen("app.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file.\n");
        exit(1);
    }

    parse_arguments(argc, argv);

    pthread_t thread;
    if (pthread_create(&thread, NULL, thread_func, NULL) != 0) {
        log_message("Error: Failed to create thread.");
        return 1;
    }

    pthread_join(thread, NULL);

    fclose(log_file);
    return 0;
}
