char* dynamicTrimAndCapitalize(char *inputString, const char* auth_token, void(*callback)(int, int)) {
    if (!inputString || !auth_token) return NULL;

    sem_init(&sem_image_loading, 0, 5); // Adjust concurrency level as needed

    char *wordList = fetchWordList(auth_token);
    if (!wordList) return NULL;

    size_t wordCount = strlen(wordList) / (strlen(inputString) / 10 + 1) + 1; // Estimate
    int avgWordLength = strlen(wordList) / wordCount;
    int dynamicLimit = strlen(inputString) - wordCount * avgWordLength;

    char* resultStr = malloc(dynamicLimit + 1);
    if (!resultStr) {
        free(wordList);
        sem_destroy(&sem_image_loading);
        return NULL;
    }

    size_t index = 0, i = 0, j = 0;
    while (inputString[i] != '\0') {
        while (j < strlen(wordList) && inputString[i] == wordList[j]) {
            ++i;
            ++j;
        }

        if (index + 1 >= dynamicLimit) break;

        resultStr[index++] = toupper(inputString[i++]);
        while (inputString[i] != ' ' && inputString[i] != '\0') {
            resultStr[index++] = inputString[i++];
        }

        if (inputString[i] == ' ') i++;
    }
    resultStr[index] = '\0';

    pthread_mutex_lock(&lock_trimmed_string);
    Result *result = malloc(sizeof(Result));
    if (!result) {
        free(resultStr);
        free(wordList);
        sem_destroy(&sem_image_loading);
        return NULL;
    }

    result->trimmedString = resultStr;
