package com.example.jsonparser;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.charset.Charset;

public class JsonParserService {

    private final ObjectMapper objectMapper = new ObjectMapper();
    private final CacheManager cacheManager;

    public JsonParserService(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
    }

    public JsonNode parseJson(String json, Charset charset) throws IOException {
        return objectMapper.readTree(json.getBytes(charset));
    }

    public JsonNode queryJson(JsonNode rootNode, String path) {
        if (cacheManager.contains(path)) {
            return cacheManager.get(path);
        }
        JsonNode result = rootNode.at(path);
        cacheManager.put(path, result);
        return result;
    }
}
```

#### CacheManager.java

```java
package com.example.jsonparser;

import java.util.LinkedHashMap;
import java.util.Map;

public class CacheManager {

    private final int capacity;
    private final Map<String, JsonNode> cacheMap = new LinkedHashMap<String, JsonNode>() {
        @Override
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > capacity;
        }
    };

    public CacheManager(int capacity) {
        this.capacity = capacity;
    }

    public synchronized void put(String key, JsonNode value) {
        cacheMap.put(key, value);
    }

    public synchronized JsonNode get(String key) {
        return cacheMap.get(key);
    }

    public boolean contains(String key) {
        return cacheMap.containsKey(key);
    }
}
```

