package com.example.jsonparser;

import org.springframework.web.client.RestTemplate;
import org.springframework.web.client.HttpStatusCodeException;
import java.util.concurrent.TimeUnit;

public class ApiClient {

    private final RestTemplate restTemplate = new RestTemplate();
    private final int retryAttempts = 3;

    public boolean validateData(String apiUrl, Object data) {
        for (int i = 0; i < retryAttempts; i++) {
            try {
                // Assuming POST request for validation
                return restTemplate.postForObject(apiUrl, data, Boolean.class);
            } catch (HttpStatusCodeException e) {
                logError(e);
                if (!isTransientFailure(e)) {
                    break;
                }
            }
        }
        return false;
    }

    private boolean isTransientFailure(HttpStatusCodeException e) {
        // Check for transient status codes like 503
        int statusCode = e.getRawStatusCode();
        return statusCode == 500 || statusCode == 503;
    }

    private void logError(Exception e) {
        // Log error details
    }
}
