```rust
use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::PathBuf;
use std::time::{Duration, Instant};
use reqwest::{Client, Error as ReqwestError};
use tokio::sync::Semaphore;
use tokio::task;

const MAX_RETRIES: usize = 3;
const DISK_SPACE_LIMIT_BYTES: u64 = 500 * 1024 * 1024; // 500 MB

async fn fetch_and_process_data(
    base_url: &str,
    formats: &[&str],
    log_dir_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let log_dir = PathBuf::from(env::var("LOG_DIR")?).join(log_dir_name);

    create_log_directory(&log_dir)?;

    let client = Client::new();
    let semaphore = Semaphore::new(10); // Limit concurrent tasks

    for format in formats {
        match format {
            "json" | "xml" | "csv" => {},
            _ => return Err("Unsupported data format".into()),
        }
    }

    let fetch_tasks: Vec<_> = formats.iter().map(|&format| {
        let client = client.clone();
        let log_dir = log_dir.clone();
        let base_url = base_url.to_string();
        let semaphore = semaphore.clone();

        tokio::spawn(async move {
            let _permit = semaphore.acquire().await.unwrap();
            process_format(&client, format, &base_url, &log_dir).await
        })
    }).collect();

    for task in fetch_tasks {
        task.await??; // Handle errors from each task
    }

    Ok(())
}

async fn process_format(
    client: &Client,
    format: &str,
    base_url: &str,
    log_dir: &PathBuf,
) -> Result<(), Box<dyn std::error::Error>> {
    let url = format!("{}/{}", base_url, format);
    fetch_with_retry(client, url, format, log_dir).await?;

    Ok(())
}

async fn fetch_with_retry(
    client: &Client,
    url: String,
    format: &str,
    log_dir: &PathBuf,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut attempts = 0;
    loop {
        match download_data(client, &url, format, log_dir).await {
            Ok(_) => return Ok(()),
            Err(err) if attempts < MAX_RETRIES => {
                attempts += 1;
                let backoff_duration = Duration::from_secs(2u64.pow(attempts));
                tokio::time::sleep(backoff_duration).await;
            }
            Err(err) => {
                log_error(format, &url, err)?;
                return Err(Box::new(err));
            }
        }
    }
}

async fn download_data(
    client: &Client,
    url: &str,
    format: &str,
    log_dir: &PathBuf,
) -> Result<(), ReqwestError> {
    let start = Instant::now();

    let response = client.get(url).send().await?;
    if !response.status().is_success() {
        return Err(ReqwestError::new(
            reqwest::StatusCode::BAD_REQUEST,
            true,
            false,
            None,
        ));
    }

    let data = response.bytes().await?;

    if let Ok(current_disk_usage) = get_disk_usage(log_dir.parent().unwrap()) {
        if current_disk_usage + data.len() as u64 > DISK_SPACE_LIMIT_BYTES {
            return Err(ReqwestError::new(
                reqwest::StatusCode::INTERNAL_SERVER_ERROR,
                true,
                false,
                None,
            ));
        }
    }

    let file_path = log_dir.join(format!("{}.{}", format, url.split('/').last().unwrap()));
    File::create(&file_path)?.write_all(&data)?;

    log_info(format, &url, start.elapsed()).ok();

    Ok(())
}

fn create_log_directory(log_dir: &PathBuf) -> Result<(), io::Error> {
    if !log_dir.exists() {
        fs::create_dir_all(log_dir).map_err(|e| e.context("Failed to create log directory"))?;
    }
    Ok(())
}

fn get_disk_usage(path: &std::path::Path) -> io::Result<u64> {
    let metadata = fs::metadata(path)?;
    Ok(metadata.len())
}

fn log_info(format: &str, url: &str, duration: Duration) {
    println!("Successfully fetched {} from {} in {:?}", format, url, duration);
}

fn log_error(format: &str, url: &str, err: &ReqwestError) {
    eprintln!(
        "Failed to fetch {} from {}: {:?}",
        format,
        url,
        err
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio;

    #[tokio::test]
    async fn test_fetch_and_process_data() -> Result<(), Box<dyn std::error::Error>> {
        let base_url = "https://example.com/data";
        fetch_and_process_data(base_url, &["json", "xml"], "logs").await?;

        Ok(())
    }
}
```

