### C Semaphore Management System

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <string.h>
#include <json-c/json.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t semaphore;
    int max_value;
    int current_value;
    int priority;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
pthread_mutex_t semaphore_lock = PTHREAD_MUTEX_INITIALIZER;
int active_operations = 0;

void log_operation(const char *message) {
    printf("[%ld] %s\n", time(NULL), message);
}

Semaphore* create_semaphore(int index, int initial_value, int max_value, int priority) {
    pthread_mutex_lock(&semaphore_lock);

    if (index < 0 || index >= MAX_SEMAPHORES) {
        log_operation("Invalid semaphore index");
        return NULL;
    }

    semaphores[index].current_value = initial_value;
    semaphores[index].max_value = max_value;
    semaphores[index].priority = priority;

    if (sem_init(&semaphores[index].semaphore, 0, initial_value) != 0) {
        log_operation("Failed to initialize semaphore");
        pthread_mutex_unlock(&semaphore_lock);
        return NULL;
    }

    log_operation("Semaphore created successfully");
    pthread_mutex_unlock(&semaphore_lock);
    return &semaphores[index];
}

void delete_semaphore(int index) {
    pthread_mutex_lock(&semaphore_lock);

    if (index < 0 || index >= MAX_SEMAPHORES) {
        log_operation("Invalid semaphore index");
        pthread_mutex_unlock(&semaphore_lock);
        return;
    }

    sem_destroy(&semaphores[index].semaphore);

    log_operation("Semaphore deleted successfully");
    pthread_mutex_unlock(&semaphore_lock);
}

void increment_semaphore(int index, int count) {
    pthread_mutex_lock(&semaphore_lock);

    if (index < 0 || index >= MAX_SEMAPHORES) {
        log_operation("Invalid semaphore index");
        pthread_mutex_unlock(&semaphore_lock);
        return;
    }

    for (int i = 0; i < count; ++i) {
        sem_post(&semaphores[index].semaphore);
        if (semaphores[index].current_value >= semaphores[index].max_value) break;
    }

    log_operation("Semaphore incremented");
    pthread_mutex_unlock(&semaphore_lock);
}

void decrement_semaphore(int index, int count) {
    pthread_mutex_lock(&semaphore_lock);

    if (index < 0 || index >= MAX_SEMAPHORES) {
        log_operation("Invalid semaphore index");
        pthread_mutex_unlock(&semaphore_lock);
        return;
    }

    for (int i = 0; i < count; ++i) {
        sem_wait(&semaphores[index].semaphore);
    }

    log_operation("Semaphore decremented");
    pthread_mutex_unlock(&semaphore_lock);
}

void load_configuration(const char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) return;

    struct json_object *parsed_json;
    struct json_object *sems;
    struct json_object *initial_value;
    struct json_object *max_value;
    struct json_object *priority;

    char buffer[1024];
    fread(buffer, 1, sizeof(buffer), fp);
    fclose(fp);

    parsed_json = json_tokener_parse(buffer);
    json_object_object_get_ex(parsed_json, "semaphores", &sems);

    for (int i = 0; i < MAX_SEMAPHORES && json_object_array_length(sems) > i; ++i) {
        struct json_object *sem;
        json_object_array_get_idx(sems, i, &sem);

        const char *name;
        int initial_val, max_val, prio;

        json_object_object_get_ex(sem, "name", &json_obj_str);
        name = (const char *)json_obj_str->str;

        json_object_object_get_ex(sem, "initial_value", &initial_value);
        initial_val = json_object_get_int(initial_value);

        json_object_object_get_ex(sem, "max_value", &max_value);
        max_val = json_object_get_int(max_value);

        json_object_object_get_ex(sem, "priority", &priority);
        prio = json_object_get_int(priority);

        // Assuming name maps to index for simplicity
        int index = atoi(name + 1);  // example conversion: semaphore1 -> 0

        create_semaphore(index, initial_val, max_val, prio);
    }

    json_object_put(parsed_json);
}

int main() {
    load_configuration("config.json");
    return 0;
}
```

