```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SUPPORTED_TYPES 5
#define MAX_FILENAME_LENGTH 256

// Predefined supported file types and their digit count
typedef struct {
    const char* extension;
    int digit_count;
} FileType;

FileType supported_file_types[MAX_SUPPORTED_TYPES] = {
    {".txt", 5},
    {".jpg", 3},
    {".png", 3},
    {".pdf", 5},
    {NULL, 0}
};

// External logging system placeholder
void log_error(const char* message) {
    // Implement logging to an external system here
    fprintf(stderr, "Error: %s\n", message);
}

// Thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int parse_filename(const char* filename, char** base_name, char** extension) {
    pthread_mutex_lock(&lock);

    const char* dot_position = strrchr(filename, '.');
    if (!dot_position || dot_position == filename) {
        log_error("Filename is invalid or does not contain an extension.");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *extension = strdup(dot_position);
    size_t base_name_length = dot_position - filename;
    *base_name = strndup(filename, base_name_length);

    pthread_mutex_unlock(&lock);
    return 0;
}

int determine_digits(const char* extension) {
    pthread_mutex_lock(&lock);

    for (int i = 0; supported_file_types[i].extension != NULL; ++i) {
        if (strcmp(extension, supported_file_types[i].extension) == 0) {
            int digits = supported_file_types[i].digit_count;
            pthread_mutex_unlock(&lock);
            return digits;
        }
    }

    log_error("Unsupported file type.");
    pthread_mutex_unlock(&lock);
    return -1;
}

int validate_file_type(const char* extension) {
    for (int i = 0; supported_file_types[i].extension != NULL; ++i) {
        if (strcmp(extension, supported_file_types[i].extension) == 0) {
            return 0; // Valid file type
        }
    }
    return -1; // Invalid file type
}

void set_file_type(char** extension, const char* new_extension) {
    pthread_mutex_lock(&lock);

    size_t ext_len = strlen(*extension);
    if (ext_len < 2 || (*extension)[0] != '.') {
        log_error("Malformed extension detected.");
        pthread_mutex_unlock(&lock);
        return;
    }

    free(*extension);
    *extension = strdup(new_extension);

    pthread_mutex_unlock(&lock);
}

void create_new_filename(const char* base_name, const char* digits_str, const char* extension) {
    pthread_mutex_lock(&lock);

    static char new_filename[MAX_FILENAME_LENGTH];
    snprintf(new_filename, sizeof(new_filename), "%s%s%s", base_name, digits_str, extension);

    printf("New Filename: %s\n", new_filename);

    free((void*)base_name);
    free((void*)digits_str);
    pthread_mutex_unlock(&lock);
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        log_error("Usage: program <filename> <new_extension>");
        return -1;
    }

    const char* filename = argv[1];
    const char* new_extension = argv[2];

    if (!validate_file_type(new_extension)) {
        log_error("New extension is not supported.");
        return -1;
    }

    char *base_name, *extension;

    if (parse_filename(filename, &base_name, &extension) != 0) {
        return -1; // Error already logged
    }

    int digit_count = determine_digits(extension);
    if (digit_count < 0) {
        free(base_name);
        free(extension);
        return -1;
    }

    char digits_str[10];
    snprintf(digits_str, sizeof(digits_str), "%0*d", digit_count, rand()); // Random number for demonstration

    set_file_type(&extension, new_extension);

    create_new_filename(base_name, digits_str, extension);

    pthread_mutex_destroy(&lock);
    return 0;
}
