import threading
from queue import Queue, Empty
import yaml
import time
import json
import hashlib
import zlib
import requests
from concurrent.futures import ThreadPoolExecutor
from collections import defaultdict

class SensorDataProcessor:
    def __init__(self, config_path):
        self.load_config(config_path)
        self.executor = ThreadPoolExecutor(max_workers=self.config['max_threads'])
        self.data_queue = Queue()
        self.lock = threading.Lock()
        self.event_thresholds = self.config['event_detection']['thresholds']
        self.sensor_streams = defaultdict(list)

    def load_config(self, path):
        with open(path, 'r') as file:
            self.config = yaml.safe_load(file)

    def start_processing(self):
        for _ in range(self.config['max_threads']):
            thread = threading.Thread(target=self.process_data)
            thread.start()

    def process_data(self):
        while True:
            try:
                data_packet = self.data_queue.get(timeout=1)
                sensor_id, data = data_packet
                validated_data = self.validate_and_clean(data)

                if validated_data:
                    transformed_data = self.transform_data(sensor_id, validated_data)
                    self.aggregate_data(sensor_id, transformed_data)

                    # Event detection
                    if self.detect_event(transformed_data):
                        self.alert_event(sensor_id, transformed_data)

                    # Store data optimally
                    compressed_data = zlib.compress(json.dumps(transformed_data).encode())
                    self.store_data(sensor_id, compressed_data)
                self.data_queue.task_done()
            except Empty:
                continue

    def validate_and_clean(self, data):
        if not self.is_valid(data):
            return None
        return self.clean_data(data)

    def is_valid(self, data):
        # Perform validation logic (e.g., checking for required fields, range checks)
        return 'sensor_id' in data and 'value' in data

    def clean_data(self, data):
        # Clean erroneous or corrupted data packets
        cleaned_data = {k: v for k, v in data.items() if self.is_valid_field(v)}
        return cleaned_data

    def is_valid_field(self, field_value):
        # Custom logic to determine if a field value is valid
        return True 

    def transform_data(self, sensor_id, data):
        # Apply any necessary transformations based on sensor type or other criteria
        return data

    def aggregate_data(self, sensor_id, data):
        with self.lock:
            self.sensor_streams[sensor_id].append(data)

    def detect_event(self, data):
        for key, threshold in self.event_thresholds.items():
            if data[key] > threshold:
                return True
        return False

    def alert_event(self, sensor_id, data):
        # Logic to handle event alerts (e.g., send notifications, log events)
        print(f"Critical Event Detected: {sensor_id} - {data}")

    def store_data(self, sensor_id, compressed_data):
        try:
            # Simulate storing in a distributed file system
            encrypted_data = self.encrypt_data(compressed_data)
            storage_url = f"{self.config['storage']['url']}/{sensor_id}"
            requests.post(storage_url, data=encrypted_data, headers={'Content-Type': 'application/octet-stream'})
        except Exception as e:
            # Switch to backup storage on failure
            self.backup_store(sensor_id, compressed_data)

    def encrypt_data(self, data):
        return hashlib.sha256(data).hexdigest()

    def backup_store(self, sensor_id, data):
        # Logic for storing in a backup system
        print(f"Backup Storage: {sensor_id} - Data Size: {len(data)} bytes")

    def add_sensor_data(self, sensor_id, data):
        if self.config['throttling']['enabled']:
            with self.lock:
                current_load = len(self.data_queue.queue)
                allowed_rate = self.config['throttling']['rate']
                if current_load >= allowed_rate:
                    time.sleep(1 / allowed_rate)

        self.data_queue.put((sensor_id, data))

    def stop_processing(self):
        self.executor.shutdown(wait=True)

# Example of starting the processor
if __name__ == "__main__":
    config_path = 'config.yaml'
    processor = SensorDataProcessor(config_path)
    processor.start_processing()

    # Simulate incoming sensor data
    for i in range(1000):
        sensor_id = f"sensor_{i % 10}"
        data = {'sensor_id': sensor_id, 'value': i}
        processor.add_sensor_data(sensor_id, data)

    processor.data_queue.join()
    processor.stop_processing()
