import os
import mimetypes
from flask import Flask, request, send_file, abort, jsonify
from werkzeug.utils import secure_filename
from functools import wraps

app = Flask(__name__)

# Constants for supported types and configurations
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf', 'doc', 'docx', 'zip', 'tar'}
MAX_FILE_SIZE_MB = 100
UPLOAD_FOLDER = '/path/to/upload/folder'
DOWNLOAD_LINK_EXPIRY_SECONDS = 3600

# Dummy storage for demonstration purposes
file_storage = {}
user_files = {} # user_id -> list of file_ids
file_permissions = {} # file_id -> set of user_ids with access


def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_user(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not request.headers.get('Authorization'):
            abort(401)  # Unauthorized
        user_id = request.headers.get('Authorization')
        return f(user_id, *args, **kwargs)
    return decorated_function

class FileStorageManager:

    @staticmethod
    def validateFileType(file_type):
        mime_type, _ = mimetypes.guess_type(file_type)
        if not mime_type or not any(mime_type.startswith(prefix) for prefix in ['image/', 'application/pdf', 'application/msword']):
            raise ValueError('Unsupported file type')

    @staticmethod
    def sanitizeFileName(fileName):
        return secure_filename(fileName)

    @validate_user
    def uploadFile(self, user_id, filePath, destinationPath):
        if not os.path.exists(filePath) or not allowed_file(filePath):
            raise FileNotFoundError('Invalid file path')

        # Ensure the destination directory exists
        os.makedirs(destinationPath, exist_ok=True)
        filename = self.sanitizeFileName(os.path.basename(filePath))
        dest_path = os.path.join(destinationPath, filename)

        if os.path.getsize(filePath) > MAX_FILE_SIZE_MB * 1024 * 1024:
            raise ValueError('File size exceeds the maximum limit')

        # Multipart upload logic placeholder
        with open(filePath, 'rb') as f:
            with open(dest_path, 'wb') as dest_file:
                while chunk := f.read(8192):
                    dest_file.write(chunk)

        file_id = len(file_storage) + 1
        file_storage[file_id] = {
            'path': dest_path,
            'size': os.path.getsize(dest_path),
            'upload_date': '2023-10-01'  # Example date
        }

        if user_id not in user_files:
            user_files[user_id] = []
        user_files[user_id].append(file_id)

    @validate_user
    def downloadFile(self, user_id, fileId):
        file_info = file_storage.get(fileId)
        if not file_info or user_id not in file_permissions.get(fileId, set()):
            abort(403)  # Forbidden

        return send_file(file_info['path'], as_attachment=True)

    @validate_user
    def listUserFiles(self, user_id, page=1, per_page=10):
        files = user_files.get(user_id, [])
        start = (page - 1) * per_page
        end = start + per_page
        return jsonify([file_storage[fileId] for fileId in files[start:end]])

    @validate_user
    def deleteFile(self, user_id, fileId):
        if fileId not in file_storage or user_id not in file_permissions.get(fileId, set()):
            abort(403)  # Forbidden

        os.remove(file_storage[fileId]['path'])
        del file_storage[fileId]

        for files in user_files.values():
            if fileId in files:
                files.remove(fileId)

    def generateDownloadLink(self, fileId):
        token = f"securetoken_{fileId}"  # Simplified example
        return f"https://yourapp.com/download/{fileId}?token={token}"

    @validate_user
    def manageFilePermissions(self, user_id, fileId, permissions):
        if fileId not in file_storage:
            raise ValueError("File does not exist")

        if fileId not in file_permissions:
            file_permissions[fileId] = set()

        # Example: Add users from permissions list to the access set of this file
        for perm_user_id in permissions:
            file_permissions[fileId].add(perm_user_id)

    @validate_user
    def logUploadAndDownloadActivity(self, user_id, fileId, activityType):
        print(f"User {user_id} performed '{activityType}' on file {fileId}")

# Endpoints to interact with the FileStorageManager
file_manager = FileStorageManager()

@app.route('/upload', methods=['POST'])
def upload():
    user_id = request.headers.get('Authorization')
    filePath = request.files['file'].filename
    destinationPath = UPLOAD_FOLDER
    try:
        file_manager.uploadFile(user_id, filePath, destinationPath)
        return jsonify({'message': 'Upload successful'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/download/<int:fileId>', methods=['GET'])
@validate_user
def download(fileId):
    user_id = request.headers.get('Authorization')
    try:
        return file_manager.downloadFile(user_id, fileId)
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/files', methods=['GET'])
@validate_user
def list_files():
    user_id = request.headers.get('Authorization')
    page = int(request.args.get('page', 1))
    per_page = int(request.args.get('per_page', 10))
    try:
        return file_manager.listUserFiles(user_id, page, per_page)
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/delete/<int:fileId>', methods=['DELETE'])
@validate_user
def delete(fileId):
    user_id = request.headers.get('Authorization')
    try:
        file_manager.deleteFile(user_id, fileId)
        return jsonify({'message': 'Deletion successful'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/permissions/<int:fileId>', methods=['POST'])
@validate_user
def set_permissions(fileId):
    user_id = request.headers.get('Authorization')
    permissions = request.json.get('permissions', [])
    try:
        file_manager.manageFilePermissions(user_id, fileId, permissions)
        return jsonify({'message': 'Permissions updated successfully'})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True)
