void *fill_random_data(void *arg);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    pthread_t threads[4];
    Record *records = NULL;
    int record_count = fetch_record_count_from_db();

    // Allocate memory for the records array
    if ((records = malloc(record_count * sizeof(Record))) == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    initialize_records(&records, record_count);

    // Test the function under various conditions (not implemented here)

    free(records);
    pthread_mutex_destroy(&mutex);

    return 0;
}

void initialize_records(Record **records, int count) {
    if (count <= 0) {
        fprintf(stderr, "Invalid record count.\n");
        exit(EXIT_FAILURE);
    }

    // Launch threads to fill the records with random data
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, fill_random_data, (void *)(intptr_t)i) != 0) {
            fprintf(stderr, "Thread creation failed.\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void *fill_random_data(void *arg) {
    int thread_id = (intptr_t)arg;
    int segment_size = 1000 / 4; // Adjust based on the number of threads
    int start_index = thread_id * segment_size;
    int end_index = (thread_id + 1) * segment_size;

    if (thread_id == 3) {
        end_index = 1000; // Ensure last segment covers any remainder
    }

    for (int i = start_index; i < end_index; ++i) {
        pthread_mutex_lock(&mutex);

        time_t now = time(NULL);
        long one_year_later = now + 365 * 24 * 60 * 60;

        (*records)[i].key = rand() % 10001;
        (*records)[i].timestamp = (long)(now + ((double)rand() / RAND_MAX * (one_year_later - now)));
        char description[256];
        snprintf(description, sizeof(description), "Description for key %d", (*records)[i].key);
        (*records)[i].description = strdup(description);
        (*records)[i].value = -10000.0 + ((double)rand() / RAND_MAX * 20000.0);

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}
