public class SecureDataProcessor
{
    private readonly IKeyManagementService _keyManagementService;
    private readonly IAuditLogger _auditLogger;
    private readonly SemaphoreSlim _rateLimitSemaphore;
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> _keyCache = new();
    private static readonly object CacheLock = new();

    public SecureDataProcessor(IKeyManagementService keyManagementService, IAuditLogger auditLogger, int maxConcurrentRequests)
    {
        _keyManagementService = keyManagementService;
        _auditLogger = auditLogger;
        _rateLimitSemaphore = new SemaphoreSlim(maxConcurrentRequests);
    }

    public async Task<string> ProcessMessageAsync(string sourceId, string encryptedMessage, int clearanceLevel, CancellationToken cancellationToken = default)
    {
        await _rateLimitSemaphore.WaitAsync(cancellationToken);

        try
        {
            (byte[] key, byte[] iv) = await RetrieveKeyAndIVAsync(sourceId, clearanceLevel);

            using var cryptoTransform = GetCryptoTransform(sourceId, encryptedMessage, key, iv);
            var decryptedData = Decrypt(encryptedMessage, cryptoTransform);

            bool isValid = ValidateMessage(decryptedData, sourceId);
            await _auditLogger.LogAuditAsync(new AuditLogEntry
            {
                SourceId = sourceId,
                ClearanceLevel = clearanceLevel,
                Algorithm = GetAlgorithm(sourceId),
                Result = isValid ? "Success" : "Failure",
                Timestamp = DateTime.UtcNow
            });

            return isValid ? decryptedData : throw new InvalidOperationException("Message validation failed.");
        }
        finally
        {
            _rateLimitSemaphore.Release();
        }
    }

    private async Task<(byte[] Key, byte[] IV)> RetrieveKeyAndIVAsync(string sourceId, int clearanceLevel)
    {
        if (!_keyCache.TryGetValue(sourceId, out var cachedKeys))
