        _cache.Set($"{tenantId}:{configName}", value, TimeSpan.FromMinutes(30));
    }

    private string EncryptData(object data)
    {
        // Implement encryption logic here
        return Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(data.ToString()));
    }
}

