```javascript
// app.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const { OAuth2Client } = require('google-auth-library'); // Example for OAuth2

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Middleware for OAuth2 authentication
app.use(async (req, res, next) => {
  const token = req.headers.authorization.split(' ')[1];
  const client = new OAuth2Client(YOUR_CLIENT_ID); // Configure with your client ID
  try {
    await client.verifyIdToken({
      idToken: token,
      audience: YOUR_CLIENT_ID,
    });
    next();
  } catch (err) {
    res.status(401).send('Unauthorized');
  }
});

io.on('connection', (socket) => {
  console.log('A user connected');

  socket.on('joinChannel', (channelId) => {
    socket.join(channelId);
    console.log(`User joined channel ${channelId}`);
  });

  socket.on('sendMessage', (message) => {
    io.to(message.channelId).emit('newMessage', message);
  });

  // Handle disconnect
  socket.on('disconnect', () => {
    console.log('A user disconnected');
  });
});

server.listen(3000, () => {
  console.log('Server is running on port 3000');
});
