using System;
using System.IO;
using System.Xml.Linq;

class RTSGameConfig
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }

    public static RTSGameConfig LoadFromXml(string xmlFilePath)
    {
        try
        {
            if (!File.Exists(xmlFilePath))
                throw new FileNotFoundException("Configuration XML file not found.");

            XDocument doc = XDocument.Load(xmlFilePath);

            return new RTSGameConfig
            {
                TileSize = int.Parse(doc.Root.Element("TileSize")?.Value ?? "32"),
                WorldWidth = int.Parse(doc.Root.Element("WorldWidth")?.Value ?? "1000"),
                WorldHeight = int.Parse(doc.Root.Element("WorldHeight")?.Value ?? "800"),
                CameraSpeed = float.Parse(doc.Root.Element("CameraSpeed")?.Value ?? "5.0")
            };
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            return null;
        }
    }

    public void SaveToXml(string xmlFilePath)
    {
        try
        {
            XDocument doc = new XDocument(
                new XElement("Configuration",
                    new XElement("TileSize", TileSize),
                    new XElement("WorldWidth", WorldWidth),
                    new XElement("WorldHeight", WorldHeight),
                    new XElement("CameraSpeed", CameraSpeed)));

            doc.Save(xmlFilePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error saving configuration: {ex.Message}");
        }
    }

    public static void Main(string[] args)
    {
        string configPath = "config.xml";
        RTSGameConfig config = LoadFromXml(configPath);

        if (config != null)
        {
            Console.WriteLine($"Tile Size: {config.TileSize}, World Dimensions: {config.WorldWidth}x{config.WorldHeight}, Camera Speed: {config.CameraSpeed}");
        }
    }
}
