use std::env;
use std::fs;
use std::path::Path;

fn set_directory_path(env_var_name: &str, dir_name: &str) -> Result<(), String> {
    let current_dir = env::current_dir().map_err(|e| e.to_string())?;
    let target_path = current_dir.join(dir_name);

    if Path::new(&env::var(env_var_name).unwrap_or_default()).exists() {
        println!("Using existing directory path.");
        return Ok(());
    }

    match fs::create_dir(&target_path) {
        Ok(_) => env::set_var(env_var_name, target_path.to_string_lossy().to_string()),
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => env::set_var(
            env_var_name,
            Path::new(&env::var(env_var_name).unwrap_or_default()).to_string_lossy().to_string(),
        ),
        Err(e) => return Err(format!("Failed to create directory: {}", e)),
    }

    println!("Directory created and environment variable set.");
    Ok(())
}

fn main() {
    match set_directory_path("GAME_DIR_PATH", "game_assets") {
        Ok(_) => println!("Operation successful."),
        Err(e) => eprintln!("Error: {}", e),
    }
}
