# microservices_architecture.py

from flask import Flask, request, jsonify
import jwt
import time
from redis import Redis
from functools import wraps
from requests.exceptions import RequestException
import logging
from pymongo import MongoClient, errors
from ratelimit import limits, sleep_and_retry
from prometheus_flask_exporter import PrometheusMetrics
from threading import Lock

app = Flask(__name__)
metrics = PrometheusMetrics(app)
redis_cache = Redis(host='localhost', port=6379, db=0)

# Configuration Management
CONFIG = {
    "api_key": "your_api_key",
    "jwt_secret": "your_jwt_secret"
}
config_lock = Lock()

@app.route('/configure', methods=['POST'])
def configure():
    global CONFIG
    with config_lock:
        new_config = request.json
        CONFIG.update(new_config)
    return jsonify({"status": "Configuration updated"}), 200

# JWT Authentication Decorator
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403

        try:
            jwt.decode(token.split(" ")[1], CONFIG['jwt_secret'], algorithms=["HS256"])
        except Exception as e:
            return jsonify({'message': 'Token is invalid!', 'error': str(e)}), 403

        return f(*args, **kwargs)
    return decorated

# API Rate Limiting
@sleep_and_retry
@limits(calls=100, period=60)
def call_external_api(url):
    try:
        # Simulate an external API call
        response = {"data": "Sample data"}
        return response
    except RequestException as e:
        logging.error(f"API call failed: {str(e)}")
        raise

# Caching Layer with Redis
def cache(key, ttl=300):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if redis_cache.exists(key):
                return json.loads(redis_cache.get(key))

            result = func(*args, **kwargs)
            redis_cache.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator

@cache("product_info")
def get_product_info():
    response = call_external_api('https://api.example.com/product')
    return response

# Error Handling and Retries
def retry_on_failure(retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(retries):
                try:
                    return func(*args, **kwargs)
                except RequestException as e:
                    logging.error(f"Retrying due to error: {str(e)}")
                    time.sleep(1)
            raise
        return wrapper
    return decorator

