```php
<?php

class SecureWebFileManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $characterSetCache = [];
    private $passwordAttemptsLogFile = 'password_attempts.log';

    public function generateSecureRandomString($length) {
        if (isset($this->characterSetCache[$length])) {
            return $this->characterSetCache[$length];
        }

        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*()_-+=<>?';
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, strlen($characters) - 1)];
        }

        $this->characterSetCache[$length] = $randomString;
        return $randomString;
    }

    public function hashPassword($password) {
        $options = ['cost' => $this->saltRoundCount];
        $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (preg_match('/[A-Z]/', $characterSet) && preg_match('/[a-z]/', $characterSet)
            && preg_match('/\d/', $characterSet) && preg_match('/[\W_]/', $characterSet)) {
            return true;
        }

        // Suggest a corrected character set
        return 'A-Za-z0-9!@#$%^&*()_-+=' . (false !== strpos($characterSet, '.'));
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            throw new InvalidArgumentException('Invalid salt round count.');
        }
    }

    public function resetPassword() {
        unset($this->characterSetCache);
        $newRandomString = $this->generateSecureRandomString(16); // Example length
        $this->hashPassword($newRandomString);
    }

    public function logPasswordAttempts($ipAddress, $result) {
        $logEntry = sprintf("[%s] IP: %s Result: %s\n", date('Y-m-d H:i:s'), $ipAddress, $result ? 'Success' : 'Failure');
        file_put_contents($this->passwordAttemptsLogFile, $logEntry, FILE_APPEND);
    }

    public function sanitizeInput($input) {
        return htmlspecialchars(trim(filter_var($input, FILTER_SANITIZE_STRING)));
    }

    public function validateFileExtension($file, $allowedExtensions) {
        $extension = pathinfo($file, PATHINFO_EXTENSION);
        return in_array('.' . $extension, $allowedExtensions);
    }

    public function resizeImage($file, $maxWidth, $maxHeight) {
        list($origWidth, $origHeight) = getimagesize($file);
        $ratio = $origWidth / $origHeight;

        if ($maxWidth / $maxHeight > $ratio) {
            $newWidth = $maxHeight * $ratio;
            $newHeight = $maxHeight;
        } else {
            $newHeight = $maxWidth / $ratio;
            $newWidth = $maxWidth;
        }

        $imageResource = imagecreatefromjpeg($file);
        $resizedImage = imagescale($imageResource, $newWidth, $newHeight);

        header('Content-Type: image/jpeg');
        imagejpeg($resizedImage);
        imagedestroy($imageResource);
        imagedestroy($resizedImage);
    }
}
