// Service class to represent a dynamic service with dependencies
class Service {
    String name;
    String version;
    List<String> dependencies = new ArrayList<>();
    boolean isRunning = false;

    public Service(String name, String version) {
        this.name = name;
        this.version = version;
    }
}

// HealthCheck interface for implementing different health checks
interface HealthCheck {
    boolean performHealthCheck(Service service);
}

// Example implementation of a basic health check
class BasicHealthCheck implements HealthCheck {
    @Override
    public boolean performHealthCheck(Service service) {
        // Logic to check if the service is healthy
        return service.isRunning;
    }
}

// Configuration class for multi-tenant settings and resource limits
class TenantConfiguration {
    String tenantId;
    Map<String, List<Service>> services = new HashMap<>();
    Map<String, Integer> resourceLimits = new HashMap<>();

    public void addService(String serviceName, Service service) {
        services.computeIfAbsent(serviceName, k -> new ArrayList<>()).add(service);
    }

    public boolean canAddMoreInstances(String serviceName) {
        int limit = resourceLimits.getOrDefault(serviceName, 10); // Default to 10 if not set
        return services.getOrDefault(serviceName, Collections.emptyList()).size() < limit;
    }
}

// Manager class for managing services across multiple tenants
public class DynamicServiceManager {
    private final Logger logger = Logger.getLogger(DynamicServiceManager.class.getName());
    private final Map<String, TenantConfiguration> tenantConfigurations = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);

    // Method to load configurations from an external storage system (stubbed)
    public void loadConfigurations() {
        // Implement loading logic here
    }

    // Start a service for a specific tenant, considering dependencies and resource limits
    public boolean startService(String tenantId, String serviceName, String version) {
        TenantConfiguration config = tenantConfigurations.computeIfAbsent(tenantId, k -> new TenantConfiguration());
        if (!config.canAddMoreInstances(serviceName)) {
            logger.warning("Resource limit reached for service: " + serviceName);
            return false;
        }

        List<Service> services = config.services.getOrDefault(serviceName, Collections.emptyList());
        Service service = findService(services, version);

        // Resolve dependencies before starting
        if (!resolveDependencies(service)) {
            logger.warning("Failed to resolve dependencies for service: " + serviceName);
            return false;
        }

        // Start the service (stubbed)
        startServiceImpl(service);
        services.add(service);
        config.services.put(serviceName, services);
        return true;
    }

    private Service findService(List<Service> services, String version) {
        for (Service s : services) {
            if (s.version.equals(version)) {
                return s;
            }
        }
        // Fallback to latest version
        return services.stream().max(Comparator.comparing(Service::getVersion)).orElse(null);
    }

    private boolean resolveDependencies(Service service) {
        for (String depName : service.dependencies) {
            // Resolve dependencies recursively
            if (!startService(service.tenantId, depName, null)) {  // Assume latest version for dependencies
                return false;
            }
        }
        return true;
    }

    private void startServiceImpl(Service service) {
        // Logic to actually start the service (stubbed)
        service.isRunning = true;
    }

    // Periodic health check mechanism
    public void scheduleHealthChecks(String tenantId, long delay, TimeUnit timeUnit) {
        List<Service> servicesToCheck = getAllServices(tenantId);

        Runnable healthCheckTask = () -> servicesToCheck.forEach(this::performHealthCheck);

        scheduler.scheduleAtFixedRate(healthCheckTask, 0, delay, timeUnit);
    }

    private void performHealthCheck(Service service) {
        HealthCheck healthCheck = new BasicHealthCheck();
        if (!healthCheck.performHealthCheck(service)) {
            logger.warning("Service " + service.name + " version " + service.version + " is unhealthy");
        }
    }

    private List<Service> getAllServices(String tenantId) {
        return tenantConfigurations.get(tenantId).services.values().stream()
                .flatMap(List::stream)
                .collect(Collectors.toList());
    }

    // Dynamic scaling based on load (stubbed)
    public void adjustServiceScaling(String tenantId, String serviceName, int newCount) {
        TenantConfiguration config = tenantConfigurations.get(tenantId);

        List<Service> services = config.services.get(serviceName);

        if (services != null && services.size() < newCount) {
            for (int i = 0; i < newCount - services.size(); i++) {
                startService(tenantId, serviceName, null); // Start latest version
            }
        } else if (services != null && services.size() > newCount) {
            services.subList(newCount, services.size()).forEach(s -> stopService(s));  // Stop excess instances
        }
    }

    private void stopService(Service service) {
        // Logic to actually stop the service (stubbed)
        service.isRunning = false;
    }

    // Method to switch configuration sources dynamically (stubbed)
    public void switchConfigurationSource(String sourceType) {
        // Implement switching logic here
    }

    // Save configurations back to external storage system (stubbed)
    public void saveConfigurations() {
        // Implement saving logic here
    }
}
