Below is a high-level implementation outline for the semaphore management system in C. This code focuses on core functionalities and integrates logging and configuration as described.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

#define MAX_SEMAPHORES 100
#define SEM_MAX_VALUE 1000

typedef struct {
    char name[256];
    sem_t sem;
    int value;
    pthread_mutex_t lock;
    int timeout_ms; // Timeout in milliseconds for semaphore operations
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log_operation(const char *operation, const char *name, int result, int value) {
    FILE *log_file = fopen("semaphore.log", "a");
    if (log_file == NULL) return;

    time_t now;
    time(&now);
    fprintf(log_file, "%s - PID: %d - Operation: %s - Semaphore: %s - Result: %d - Value: %d\n",
            ctime(&now), getpid(), operation, name, result, value);

    fclose(log_file);
}

// Create a semaphore
int create_semaphore(const char *name, int initial_value, int timeout) {
    pthread_mutex_lock(&config_lock);

    if (semaphore_count >= MAX_SEMAPHORES) {
        log_operation("Create", name, -1, 0);
        pthread_mutex_unlock(&config_lock);
        return -ENOMEM;
    }

    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            log_operation("Create", name, -EEXIST, 0);
            pthread_mutex_unlock(&config_lock);
            return -EEXIST;
        }
    }

    Semaphore *sem = &semaphores[semaphore_count++];
    strncpy(sem->name, name, sizeof(sem->name));
    sem_init(&sem->sem, 0, initial_value);
    sem->value = initial_value;
    pthread_mutex_init(&sem->lock, NULL);
    sem->timeout_ms = timeout;

    log_operation("Create", name, 0, initial_value);
    pthread_mutex_unlock(&config_lock);

    return 0;
}

// Delete a semaphore
int delete_semaphore(const char *name) {
    pthread_mutex_lock(&config_lock);

    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            sem_destroy(&semaphores[i].sem);
            pthread_mutex_unlock(&semaphores[i].lock);
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(Semaphore) * (--semaphore_count - i));
            log_operation("Delete", name, 0, 0);
            pthread_mutex_unlock(&config_lock);
            return 0;
        }
    }

    log_operation("Delete", name, -ENOENT, 0);
    pthread_mutex_unlock(&config_lock);

    return -ENOENT;
}

// Increment semaphore with timeout
int increment_semaphore(const char *name) {
    pthread_mutex_lock(&config_lock);

    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += semaphores[i].timeout_ms / 1000;
            ts.tv_nsec += (semaphores[i].timeout_ms % 1000) * 1000000;

            if (pthread_mutex_lock(&semaphores[i].lock) != 0) {
                log_operation("Increment", name, -errno, semaphores[i].value);
                pthread_mutex_unlock(&config_lock);
                return -errno;
            }

            int result = sem_timedwait(&semaphores[i].sem, &ts);
            if (result == 0) {
                semaphores[i].value++;
                log_operation("Increment", name, 0, semaphores[i].value);
            } else {
                log_operation("Increment", name, -errno, semaphores[i].value);
            }

            pthread_mutex_unlock(&semaphores[i].lock);

            pthread_mutex_unlock(&config_lock);
            return result;
        }
    }

    log_operation("Increment", name, -ENOENT, 0);
    pthread_mutex_unlock(&config_lock);

    return -ENOENT;
}

// Decrement semaphore with timeout
int decrement_semaphore(const char *name) {
    pthread_mutex_lock(&config_lock);

    for (int i = 0; i < semaphore_count; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += semaphores[i].timeout_ms / 1000;
            ts.tv_nsec += (semaphores[i].timeout_ms % 1000) * 1000000;

            if (pthread_mutex_lock(&semaphores[i].lock) != 0) {
                log_operation("Decrement", name, -errno, semaphores[i].value);
                pthread_mutex_unlock(&config_lock);
                return -errno;
            }

            if (semaphores[i].value > 0) {
                sem_post(&semaphores[i].sem);
                semaphores[i].value--;
                log_operation("Decrement", name, 0, semaphores[i].value);
            } else {
                int result = sem_timedwait(&semaphores[i].sem, &ts);
                if (result == 0) {
                    semaphores[i].value--;
                    log_operation("Decrement", name, 0, semaphores[i].value);
                } else {
                    log_operation("Decrement", name, -errno, semaphores[i].value);
                }
            }

            pthread_mutex_unlock(&semaphores[i].lock);

            pthread_mutex_unlock(&config_lock);
            return result;
        }
    }

    log_operation("Decrement", name, -ENOENT, 0);
    pthread_mutex_unlock(&config_lock);

    return -ENOENT;
}

// Load configuration from a file
void load_config(const char *filename) {
    // Implementation for loading configuration settings
}

int main() {
    // Example usage of the semaphore system

    // Load configuration
    load_config("semaphore.conf");

    // Create semaphores
    create_semaphore("sem1", 10, 5000);
    create_semaphore("sem2", 5, 3000);

    // Perform operations
    increment_semaphore("sem1");
    decrement_semaphore("sem2");

    // Delete semaphore
    delete_semaphore("sem1");

    return 0;
}
```

### Key Points:
- **Thread Safety:** Mutexes are used to ensure thread-safe access to semaphores.
- **Timeouts:** `sem_timedwait` is used for operations with timeout support.
- **Logging:** Operations and errors are logged with timestamps and process IDs.
- **Configuration Management:** Placeholder for loading configurations from a file.
- **Resource Limits:** Implemented checks for semaphore count and value limits.

