```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, SystemTime};

use serde::{Deserialize, Serialize};
use log::{info, warn, error};
use tokio::sync::RwLock;
use warp::{Filter, Rejection, Reply, http::StatusCode, filters::body::json as body_json};
use jsonwebtoken::{encode, Header};
use chrono::prelude::*;
use parking_lot::Mutex as ParkingLotMutex;

#[derive(Debug)]
struct DirectoryConfig {
    retention_count: usize,
}

impl Default for DirectoryConfig {
    fn default() -> Self {
        Self { retention_count: 5 }
    }
}

// Mock external metadata store
#[derive(Serialize, Deserialize)]
struct MetadataStore {
    directories: Vec<String>,
}

type Store = Arc<RwLock<MetadataStore>>;

const ENV_VAR_NAME: &str = "MY_DIR_PATH";
const CLEANUP_INTERVAL: Duration = Duration::from_secs(300);
const RETRY_DELAY: Duration = Duration::from_millis(100);

// Function to create a directory and set environment variable
async fn create_directory_with_env_var(config: DirectoryConfig, store: Store) -> Result<(), String> {
    let env_path = env::var(ENV_VAR_NAME).unwrap_or_default();

    if !env_path.is_empty() {
        info!("Using existing environment variable path.");
        return Ok(());
    }

    let dir_path = generate_directory_name()?;
    let _ = create_dir(&dir_path);

    // Set the environment variable
    std::env::set_var(ENV_VAR_NAME, &dir_path);

    store.write().await.directories.push(dir_path.clone());
    info!("Directory created and environment variable set: {}", dir_path);
    Ok(())
}

fn generate_directory_name() -> Result<String, String> {
    let now = Utc::now();
    let path = format!("/tmp/directory/{}", now.format("%Y-%m-%d_%H-%M-%S"));

    Ok(path)
}

fn create_dir(path: &str) -> Result<(), String> {
    for _ in 0..5 { // Retry mechanism
        match DirBuilder::new().create(path) {
            Ok(_) => return Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                info!("Directory already exists: {}", path);
                return Ok(());
            }
            Err(e) => {
                warn!("Failed to create directory: {}. Retrying...", e);
                thread::sleep(RETRY_DELAY);
            },
        }
    }

    error!("Could not create directory after retries: {}", path);
    Err(format!("Could not create directory: {}", path))
}

async fn cleanup_old_directories(config: DirectoryConfig, store: Store) {
    loop {
        let now = SystemTime::now();
        let mut entries: Vec<_> = store.read().await.directories.iter().collect();

        // Sort by access time (for simplicity, assume all have equal access)
        entries.sort_by(|a, b| a.cmp(b));

        if entries.len() > config.retention_count {
            for old_dir in &entries[config.retention_count..] {
                let _ = fs::remove_dir_all(old_dir);
                info!("Cleaned up directory: {}", old_dir);

                store.write().await.directories.retain(|x| x != old_dir);
            }
        }

        thread::sleep(CLEANUP_INTERVAL);
    }
}

async fn rest_api_endpoint(config: DirectoryConfig, store: Store) -> Result<impl Reply, Rejection> {
    let dir_creation = warp::post()
        .and(warp::path("create_directory"))
        .and_then(move || create_directory_with_env_var(config.clone(), store.clone()).await);

    let cleanup = warp::post()
        .and(warp::path("cleanup_directories"))
        .and_then(move || {
            thread::spawn(|| {
                cleanup_old_directories(config, store).await;
            });
            Ok::<_, Rejection>(warp::reply::with_status(
                "Cleanup initiated",
                StatusCode::ACCEPTED,
            ))
        });

    warp::serve(dir_creation.or(cleanup)).run(([127, 0, 0, 1], 3030)).await
}

fn main() {
    env_logger::init();

    let config = DirectoryConfig { retention_count: 3 };
    let metadata_store = Arc::new(RwLock::new(MetadataStore { directories: Vec::new() }));

    tokio::spawn(async move {
        create_directory_with_env_var(config.clone(), metadata_store.clone()).await;
        cleanup_old_directories(config, metadata_store).await;
    });

    if cfg!(feature = "api") {
        let config_clone = Arc::new(config);
        let store_clone = metadata_store.clone();

        tokio::spawn(async move {
            rest_api_endpoint(config_clone, store_clone).await;
        });
    }
}
```

