{
    private readonly object lockObj = new();
    private int _minInt;
    private int _maxInt;
    private float _minFloat;
    private float _maxFloat;

    public RandomValueGenerator(int minInt, int maxInt, float minFloat, float maxFloat)
    {
        if (minInt > maxInt || minFloat > maxFloat)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        _minInt = minInt;
        _maxInt = maxInt;
        _minFloat = minFloat;
        _maxFloat = maxFloat;

        // Seed for reproducibility
        UnityEngine.Random.InitState(DateTime.Now.Millisecond);
    }

    public int GetRandomInt(bool inclusive = true)
    {
        lock (lockObj)
        {
            return inclusive 
                ? UnityEngine.Random.Range(_minInt, _maxInt + 1) 
                : UnityEngine.Random.Range(_minInt, _maxInt);
        }
    }

    public float GetRandomFloat()
    {
        lock (lockObj)
        {
            return UnityEngine.Random.Range(_minFloat, _maxFloat);
        }
    }

    public Vector3 GetRandomVector3()
    {
        lock (lockObj)
        {
            return new Vector3(
                UnityEngine.Random.Range(_minFloat, _maxFloat),
                UnityEngine.Random.Range(_minFloat, _maxFloat),
                UnityEngine.Random.Range(_minFloat, _maxFloat));
        }
    }

    public Quaternion GetRandomQuaternion(float angleDegrees, Vector3 axis)
    {
        lock (lockObj)
        {
            float angle = Mathf.Deg2Rad * angleDegrees;
            return Quaternion.AngleAxis(UnityEngine.Random.value * angle, axis);
        }
    }

    public override string ToString()
    {
