        {
            Debug.LogError($"Logging failed: {ex.Message}");
        }
    }

    public void CompressLog(string sourceFilePath, string destinationFilePath)
    {
        try
        {
            lock (lockObj)
            {
                // Placeholder logic for compression; implement actual file compression here.
                System.IO.File.Copy(sourceFilePath, destinationFilePath);
            }
        }
        catch (IOException ex)
        {
            Debug.LogError($"Compression failed: {ex.Message}");
        }
    }

    public bool ValidateRandomInt(int value, int tolerance)
    {
        return value >= _minInt - tolerance && value <= _maxInt + tolerance;
    }

