Below is an example C code that demonstrates how to initialize an AES-256-CBC cipher using OpenSSL, incorporating a password-based key derivation function (PBKDF2) with salting. This includes error handling and provides functions for initialization and cleanup.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <string.h>

#define SALT_LEN 16
#define KEY_LEN 32 // AES-256 requires a 32-byte key
#define IV_LEN 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char salt[SALT_LEN];
} CipherContext;

CipherContext* initialize_aes_cipher(const char *password, int iterations) {
    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    if (!cipher_ctx) return NULL;

    cipher_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx->ctx) {
        free(cipher_ctx);
        return NULL;
    }

    // Generate a random salt
    if (!RAND_bytes(cipher_ctx->salt, SALT_LEN)) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    // Derive key using PBKDF2 with the password and salt
    unsigned char key[KEY_LEN];
    if (1 != PKCS5_PBKDF2_HMAC(
            password,
            strlen(password),
            cipher_ctx->salt, SALT_LEN,
            iterations,
            EVP_sha256(),
            KEY_LEN,
            key)) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    // Initialize the encryption operation with AES-256-CBC
    if (1 != EVP_EncryptInit_ex(
            cipher_ctx->ctx, 
            EVP_aes_256_cbc(), 
            NULL,
            key, 
            NULL)) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    // Generate a random IV and initialize it
    unsigned char iv[IV_LEN];
    if (!RAND_bytes(iv, IV_LEN) || 
        1 != EVP_EncryptInit_ex(cipher_ctx->ctx, NULL, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    return cipher_ctx;
}

void cleanup_cipher_context(CipherContext *cipher_ctx) {
    if (cipher_ctx) {
        if (cipher_ctx->ctx)
            EVP_CIPHER_CTX_free(cipher_ctx->ctx);

        free(cipher_ctx);
    }
}
```

### Explanation:
- **Initialization:** The `initialize_aes_cipher` function creates a new AES-256-CBC cipher context using the given password. It generates a random salt, derives an encryption key from the password using PBKDF2 with HMAC-SHA256, and initializes the encryption operation.
- **Salt Management:** The salt is stored within the `CipherContext` struct for later use (e.g., during decryption).
- **Key Derivation:** Uses OpenSSL's `PKCS5_PBKDF2_HMAC` to derive a key from the password.
- **Error Handling:** Checks for errors at each step, cleaning up resources if something goes wrong.
- **Cleanup Function:** The `cleanup_cipher_context` function safely frees memory associated with the cipher context.

Make sure to link against OpenSSL when compiling this code by using `-lssl -lcrypto`. Adjust `SALT_LEN`, `KEY_LEN`, and `IV_LEN` as needed for different configurations.

