const fs = require('fs');
const path = require('path');

// Utility for logging
function log(message) {
  console.log(new Date().toISOString() + ": " + message);
}

/**
 * Reads all files within a specified directory with a given extension,
 * concatenates their contents into a single string, and returns the string.
 *
 * @param {string} dirPath - The path to the directory to read from.
 * @param {string} fileExtension - The extension of files to filter (e.g., '.txt').
 * @param {number} maxConcurrentReads - Maximum number of concurrent file reads.
 * @param {number} buffer_size - Buffer size for reading file contents.
 * @param {number} maxRetries - Maximum number of retries for failed reads.
 */
async function readDirectoryFiles(dirPath, fileExtension, maxConcurrentReads = 5, bufferSize = 1024, maxRetries = 3) {
  const queue = [];
  const results = [];

  // Helper to process files
  async function readFile(filePath, retryCount = 0) {
    try {
      return new Promise((resolve, reject) => {
        let content = '';
        const readStream = fs.createReadStream(filePath, { highWaterMark: bufferSize });

        readStream.on('data', chunk => {
          content += chunk;
        });

        readStream.on('end', () => {
          log(`File processed: ${filePath}, Content length: ${content.length}`);
          resolve(content);
        });

        readStream.on('error', reject);

        readStream.on('close', () => {
          if (readStream.bytesRead === 0 && retryCount < maxRetries) {
            log(`Retry reading file: ${filePath}, Attempt: ${retryCount + 1}`);
            readFile(filePath, retryCount + 1).then(resolve).catch(reject);
          }
        });
      });
    } catch (error) {
      if (retryCount < maxRetries) {
        log(`Error reading file: ${filePath}, Retrying... (${retryCount + 1})`);
        return readFile(filePath, retryCount + 1);
      } else {
        log(`Failed to read file after ${maxRetries} attempts: ${filePath}`);
      }
    }
  }

  // Helper function to process files in queue
  async function worker() {
    while (queue.length) {
      const filePath = queue.shift();
      try {
        const content = await readFile(filePath);
        results.push(content);
      } catch (error) {
        log(`Failed processing file: ${filePath}`);
      }
    }
  }

  // Populate queue with files to read
  fs.readdir(dirPath, (err, files) => {
    if (err) throw err;

    for (const file of files) {
      const fullPath = path.join(dirPath, file);
      const stat = fs.statSync(fullPath);

      if (stat.isFile() && path.extname(file).toLowerCase() === fileExtension.toLowerCase()) {
        queue.push(fullPath);
      }
    }

    // Limit concurrent reads
    for (let i = 0; i < maxConcurrentReads; i++) {
      worker();
    }

    // Wait until all workers have completed
    return Promise.all(results.map(p => p)).then(() => results.join(''));
  });
}

// Example usage:
readDirectoryFiles('./myDir', '.txt').then(result => console.log(result));
```

