function renderScriptsFooter(scripts) {
    const footerContainer = document.createElement('footer');

    // Clear any existing scripts in the footer
    while (footerContainer.firstChild) {
        footerContainer.removeChild(footerContainer.lastChild);
    }

    function createScriptElement(scriptObj) {
        const scriptTag = document.createElement('script');

        if (!scriptObj || typeof scriptObj !== 'object') {
            console.error("Invalid script object:", scriptObj);
            return null;
        }

        // Handle inline scripts
        if (scriptObj.type === 'inline' && typeof scriptObj.code === 'string') {
            try {
                scriptTag.innerHTML = scriptObj.code;
            } catch (error) {
                console.error("Error setting innerHTML for script:", error);
                return null;
            }
        }

        // Handle external scripts
        else if (scriptObj.type === 'external' && typeof scriptObj.src === 'string') {
            try {
                scriptTag.src = scriptObj.src;
                scriptTag.async = true; // Load asynchronously
            } catch (error) {
                console.error("Error setting src for script:", error);
                return null;
            }
        }

        // Assign a unique key if available
        if (scriptObj.key && typeof scriptObj.key === 'string') {
            scriptTag.setAttribute('data-key', scriptObj.key);
        }

        return scriptTag;
    }

    scripts.forEach(scriptObj => {
        const scriptElement = createScriptElement(scriptObj);

        if (scriptElement) {
            footerContainer.appendChild(scriptElement);
        }
    });

    // Append the newly created footer to the body or a specific element
    document.body.appendChild(footerContainer);

    return footerContainer.outerHTML;
}

// Example usage:
const scriptsArray = [
    { type: 'inline', code: "console.log('Inline Script');", key: 'script1' },
    { type: 'external', src: 'https://example.com/external.js', key: 'script2' }
];

renderScriptsFooter(scriptsArray);
```

