const axios = require('axios');

/**
 * Asynchronous reduce function that calculates combined weaknesses of Pokemon.
 *
 * @param {Array} pokemons - Array of Pokemon objects each containing "name", "type", and "level".
 * @param {Function} callback - A callback to determine weaknesses based on type and level.
 * @returns {Promise<string>} - A promise resolving to a string of combined weaknesses or error message.
 */
async function asyncReducePokemons(pokemons, callback) {
    let combinedWeaknesses = '';

    // Function to handle API requests with retry logic
    const fetchPokemonData = async (name) => {
        const apiUrl = `https://pokeapi.co/api/v2/pokemon/${encodeURIComponent(name.toLowerCase())}`;

        for (let attempt = 0; attempt < 3; attempt++) {
            try {
                const response = await axios.get(apiUrl, { timeout: 5000 });
                return response.data;
            } catch (error) {
                if (attempt === 2 || error.response?.status !== 429) {
                    throw new Error(`Failed to fetch data for ${name}: ${error.message}`);
                }
                await new Promise(resolve => setTimeout(resolve, 1000)); // Backoff
            }
        }
    };

    for (let index = 0; index < pokemons.length; index++) {
        try {
            const { name, type, level } = pokemons[index];

            if (typeof level !== 'number') {
                throw new Error(`Invalid level value for ${name}`);
            }

            const pokemonData = await fetchPokemonData(name);
            combinedWeaknesses += callback(type, level, pokemonData) + ', ';
        } catch (error) {
            return `Error processing Pokemon at index ${index}: ${error.message}`;
        }
    }

    // Remove trailing comma and space if present
    return combinedWeaknesses.trim();
}

// Example of a callback function to determine weaknesses based on type and level
const weaknessCallback = (type, level, pokemonData) => {
    let weaknesses = '';

    switch(type.toLowerCase()) {
        case 'fire':
            weaknesses += level > 50 ? 'water, grass' : 'water';
            break;
        case 'water':
            weaknesses += level > 50 ? 'electric, grass' : 'electric';
            break;
        // Add more cases for other types
        default:
            weaknesses += 'unknown';
    }

    return weaknesses;
};

// Test cases to validate correctness and performance
(async () => {
    const pokemons = [
        { name: "Charizard", type: "Fire", level: 75 },
        { name: "Blastoise", type: "Water", level: 60 },
        // Add more Pokemon objects for testing...
    ];

    try {
        const result = await asyncReducePokemons(pokemons, weaknessCallback);
        console.log(result); // Example output based on weaknesses
    } catch (error) {
        console.error(error.message);
    }
})();
