        // For example:
        // parseJsonResponse(chunk.memory, &settings);

        free(chunk.memory);
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    return (void*)&settings;
}

static void processText(char** text, const UserSettings* settings) {
    if(settings->trim_capitalize) {
        // Trim and capitalize logic
    }

    if(strlen(*text) > settings->max_length) {
        *text = strndup(*text, settings->max_length);
    }
}

static int validateDirectory(const char* directory) {
    struct stat st;
    if (stat(directory, &st) == 0 && S_ISDIR(st.st_mode)) {
        return 1; // Valid directory
    }
    return 0; // Invalid directory
}

static void readFile(const char* filepath, MemoryStruct* mem_struct) {
    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        handleError(1);
        return;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    mem_struct->memory = malloc(length + 1);
    if (!mem_struct->memory) {
        fclose(file);
        handleError(2);
        return;
    }

    fread(mem_struct->memory, 1, length, file);
    mem_struct->memory[length] = '\0';
    mem_struct->size = length;

    fclose(file);

    // Cache the content
    cacheFileContent(redis_conn, filepath, mem_struct->memory, mem_struct->size);
}

static void handleError(int error_code) {
    switch(error_code) {
        case 1:
            slf4j_log_error("Failed to open file.");
            break;
        case 2:
            slf4j_log_error("Memory allocation failed for file content.");
            break;
        default:
            slf4j_log_error("An unknown error occurred.");
    }
}

static void cacheFileContent(redisContext *context, const char* filename, const char* content, size_t length) {
    redisReply *reply = (redisReply*) redisCommand(context, "SET %b %b", filename, strlen(filename), content, length);
    if(reply->type == REDIS_REPLY_ERROR) {
        slf4j_log_error("Redis error: %s", reply->str);
    }
    freeReplyObject(reply);
}

void processUserInput(const char* inputDirectory, char** outputText) {
    if (!validateDirectory(inputDirectory)) {
        handleError(3); // Invalid directory
        return;
    }

    UserSettings settings = {0};

    ThreadPool pool;
    initializeThreadPool(&pool);

    // Fetch user settings asynchronously
    pthread_t fetch_thread;
    pthread_create(&fetch_thread, NULL, fetchUserSettings, &settings);
    pthread_join(fetch_thread, NULL);

    // Simulate reading files from the directory (asynchronously in a real scenario)
    for(int i = 0; i < THREAD_POOL_SIZE; ++i) {
        MemoryStruct mem_struct = { .memory = NULL, .size = 0 };

        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/file%d.txt", inputDirectory, i);

        if(validateInputPath(filepath)) {
            readFile(filepath, &mem_struct);

            // Log file content length using SLF4J
            slf4j_log_info("Processed file: %s, Content Length: %zu", filepath, mem_struct.size);

            processText(outputText, &settings);

            free(mem_struct.memory);
        } else {
            handleError(4); // Invalid input path
        }
    }

    destroyThreadPool(&pool);

    // Redis connection cleanup if necessary
    if (redis_conn != NULL) {
        redisFree(redis_conn);
    }
}

int main() {
    char* processedText = NULL;

    processUserInput("/path/to/input", &processedText);

    printf("Processed Text: %s\n", processedText);

    free(processedText);

    return 0;
}
```

