import json
from abc import ABC, abstractmethod
import logging
import threading
import time
from typing import Callable, Dict, Any

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class InvalidResourceConfiguration(Exception):
    pass

class ResourceAllocationError(Exception):
    pass

class CloudProviderAPI(ABC):
    @abstractmethod
    def allocate_resource(self, config: dict) -> dict:
        pass

    @abstractmethod
    def deallocate_resource(self, resource_id: str):
        pass

# Factory functions registry
factory_functions = {}

def register_factory(resource_type: str) -> Callable[[Callable], Callable]:
    def wrapper(func: Callable) -> Callable:
        factory_functions[resource_type] = func
        return func
    return wrapper

class CloudResourceOrchestrator:
    def __init__(self):
        self.resources = {}
        self.cloud_providers = {}

    def add_cloud_provider(self, name: str, api: CloudProviderAPI):
        self.cloud_providers[name] = api

    def to_json(self, resource_config: dict) -> str:
        return json.dumps(resource_config)

    def from_json(self, json_str: str) -> dict:
        try:
            return json.loads(json_str)
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON string: {e}")
            raise InvalidResourceConfiguration("The provided configuration is not a valid JSON.")

    @register_factory('generic_resource')
    def create_generic_resource(self, config: dict):
        # Implement specific logic for creating a generic resource
        return {'id': 'gen123', 'config': config}

    def allocate(self, json_config: str) -> str:
        try:
            config = self.from_json(json_config)
            # Validate configuration against provider schema (not implemented here)
            resource_id = config.get('id')
            if not factory_functions.get(config['type']):
                raise InvalidResourceConfiguration("Factory function for this type is missing.")

            # Use the appropriate factory function to allocate
            resource_factory = factory_functions[config['type']]
            allocated_resource = resource_factory(self, config)

            self.resources[resource_id] = {
                'config': config,
                'allocated': True,
                'provider': config.get('cloud_provider')
            }
            logger.info(f"Resource {resource_id} allocated successfully.")
            return resource_id
        except InvalidResourceConfiguration as e:
            logger.error(e)
            raise

    def deallocate(self, resource_id: str):
        if resource_id not in self.resources:
            logger.error("Resource ID not found.")
            raise ResourceAllocationError(f"Resource with ID {resource_id} does not exist.")

        resource = self.resources[resource_id]
        cloud_provider_name = resource['provider']

        try:
            provider_api = self.cloud_providers.get(cloud_provider_name)
            if not provider_api:
                raise ResourceAllocationError("Cloud provider API is missing.")

            # Deallocate using the cloud provider's API
            provider_api.deallocate_resource(resource_id)
            del self.resources[resource_id]
            logger.info(f"Resource {resource_id} deallocated successfully.")
        except Exception as e:
            logger.error(e)
            raise ResourceAllocationError(f"Failed to deallocate resource with ID {resource_id}: {str(e)}")

    def periodic_allocation(self):
        while True:
            # Logic for automated resource allocation based on rules
            time.sleep(60)  # For example, run every minute

def main():
    orchestrator = CloudResourceOrchestrator()

    # Add cloud providers (implement specific APIs)
    orchestrator.add_cloud_provider('AWS', CloudProviderAPI())
    orchestrator.add_cloud_provider('Azure', CloudProviderAPI())

    # Example of allocating a resource
    config_json = '{"id": "res1", "type": "generic_resource", "config": {"size": "large"}, "cloud_provider": "AWS"}'

    try:
        res_id = orchestrator.allocate(config_json)
        logger.info(f"Allocated Resource ID: {res_id}")

        # Simulate resource lifecycle
        time.sleep(5)

        orchestrator.deallocate(res_id)
    except Exception as e:
        logger.error(e)

    # Start periodic allocation thread
    threading.Thread(target=orchestrator.periodic_allocation, daemon=True).start()

if __name__ == "__main__":
    main()
