import os
from PIL import Image
import io
import boto3
from google.cloud import storage as gcs_storage
from azure.storage.blob import BlobServiceClient, BlobClient

class CloudStorageManager:
    def __init__(self, allowed_extensions=None):
        self.allowed_extensions = allowed_extensions or ['jpg', 'png', 'gif']

        # Initialize cloud clients
        self.s3_client = boto3.client('s3')
        self.gcs_client = gcs_storage.Client()
        self.azure_blob_service_client = BlobServiceClient.from_connection_string("<your-azure-connection-string>")

    def validateFileExtension(self, file, allowed_extensions=None):
        ext = os.path.splitext(file.name)[1][1:].lower()
        allowed = allowed_extensions if allowed_extensions else self.allowed_extensions
        return ext in allowed

    def resizeImage(self, file, maxWidth, maxHeight):
        image = Image.open(file)
        ratio = min(maxWidth / image.width, maxHeight / image.height)
        new_size = (int(image.width * ratio), int(image.height * ratio))
        resized_image = image.resize(new_size, Image.ANTIALIAS)

        buffer = io.BytesIO()
        resized_image.save(buffer, format=image.format)
        buffer.seek(0)

        return buffer

    def uploadFile(self, file, destinationPath):
        if not self.validateFileExtension(file):
            raise ValueError("Invalid file extension.")

        # Implement retry logic
        retries = 3
        while retries > 0:
            try:
                bucket_name = "<your-bucket-name>"

                # Example with S3
                self.s3_client.upload_fileobj(
                    file,
                    bucket_name,
                    destinationPath
                )

                return True
            except Exception as e:
                print(f"Upload failed: {e}")
                retries -= 1

        raise RuntimeError("File upload failed after multiple attempts.")

    def downloadFile(self, filePath, mimeType, attachmentName):
        # Example with S3
        bucket_name = "<your-bucket-name>"

        file_stream = io.BytesIO()
        self.s3_client.download_fileobj(bucket_name, filePath, file_stream)
        file_stream.seek(0)

        response = {
            'file': file_stream,
            'mimeType': mimeType,
            'attachmentName': attachmentName
        }

        return response

    def deleteFile(self, filePath):
        bucket_name = "<your-bucket-name>"

        try:
            self.s3_client.delete_object(Bucket=bucket_name, Key=filePath)
        except Exception as e:
            print(f"Deletion failed: {e}")
            raise RuntimeError("File deletion failed.")

    def moveFile(self, sourcePath, destinationPath):
        bucket_name = "<your-bucket-name>"

        copy_source = {
            'Bucket': bucket_name,
            'Key': sourcePath
        }

        self.s3_client.copy_object(
            CopySource=copy_source,
            Bucket=bucket_name,
            Key=destinationPath
        )

        try:
            self.deleteFile(sourcePath)
        except Exception as e:
            print(f"Move failed: {e}")
            raise RuntimeError("File move failed.")

    def renameFile(self, oldFilePath, newFilePath):
        bucket_name = "<your-bucket-name>"

        if not self.validateFileExtension(newFilePath):
            raise ValueError("Invalid file extension for renaming.")

        copy_source = {
            'Bucket': bucket_name,
            'Key': oldFilePath
        }

        try:
            self.s3_client.copy_object(
                CopySource=copy_source,
                Bucket=bucket_name,
                Key=newFilePath
            )

            self.deleteFile(oldFilePath)
        except Exception as e:
            print(f"Rename failed: {e}")
            raise RuntimeError("File renaming failed.")

    def secureFileUpload(self, file):
        if not self.validateFileExtension(file):
            raise ValueError("Invalid file extension.")

        buffer = None
        if file.size > 5 * 1024 * 1024:
            buffer = self.resizeImage(file, 800, 600)

        destinationPath = f"uploads/{file.name}"

        # Optionally compress the file here

        return self.uploadFile(buffer or file, destinationPath)

    def uploadAttempt(self, fileDetails, status):
        log_entry = {
            'fileDetails': fileDetails,
            'status': status
        }
        print(f"Log: {log_entry}")

    def updateAllowedExtensions(self, new_extensions):
        self.allowed_extensions = new_extensions

# Example usage:
manager = CloudStorageManager()
with open("example.jpg", "rb") as f:
    manager.secureFileUpload(f)
