```python
from cachetools import TTLCache, LRUCache
from redis import Redis
import time

# Create a distributed cache using Redis
redis_cache = Redis(host='localhost', port=6379, db=0)

class CacheLayer:
    def __init__(self):
        # Local caches for demonstration
        self.ttl_cache = TTLCache(maxsize=100, ttl=300)  # Entries expire after 5 minutes
        self.lru_cache = LRUCache(maxsize=200)

    def get(self, key):
        # Try to fetch from Redis first
        value = redis_cache.get(key)
        if value:
            return value.decode('utf-8')

        # Fallback to local caches
        value = self.ttl_cache.get(key) or self.lru_cache.get(key)
        if value:
            # Update Redis on a cache hit
            redis_cache.setex(key, 300, value)
            return value

        return None

    def set(self, key, value):
        self.ttl_cache[key] = value
        self.lru_cache[key] = value
        redis_cache.setex(key, 300, value)

cache_layer = CacheLayer()
