```python
import time
from threading import Lock

class TokenBucket:
    def __init__(self, tokens, fill_rate):
        self.capacity = tokens
        self.tokens = tokens
        self.fill_rate = fill_rate
        self.timestamp = time.monotonic()
        self.lock = Lock()

    def consume(self, tokens=1):
        with self.lock:
            now = time.monotonic()
            elapsed = now - self.timestamp
            self.timestamp = now
            self.tokens += elapsed * self.fill_rate

            if self.tokens > self.capacity:
                self.tokens = self.capacity

            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            return False

rate_limiter = TokenBucket(tokens=10, fill_rate=1)  # e.g., 10 requests per second

def api_call():
    if rate_limiter.consume():
        # Perform API call
        pass
    else:
        print("Rate limit exceeded, try again later")
```

### 3. Error Handling and Retries

```python
import logging
from requests.exceptions import RequestException
from time import sleep
import random

logger = logging.getLogger(__name__)

class CircuitBreaker:
    def __init__(self, max_failures=5, reset_timeout=60):
        self.max_failures = max_failures
        self.reset_timeout = reset_timeout
        self.failure_count = 0
        self.last_failure_time = None

    def call(self, func, *args, **kwargs):
        if self.failure_count >= self.max_failures:
            if time.monotonic() - self.last_failure_time > self.reset_timeout:
                # Allow retry after timeout
                self.failure_count = 0
            else:
                raise Exception("Circuit breaker open. Call blocked.")

        try:
            response = func(*args, **kwargs)
            self._reset()
            return response
        except RequestException as e:
            logger.error(f"API request failed: {e}")
            self._record_failure()
            sleep(random.uniform(1, 3))  # Exponential backoff can be implemented here
            return self.call(func, *args, **kwargs)

    def _record_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.monotonic()

    def _reset(self):
        self.failure_count = 0

def fetch_data():
    # Simulate an API call
    response = requests.get("https://api.example.com/data")
    return response.json()

circuit_breaker = CircuitBreaker()

try:
    data = circuit_breaker.call(fetch_data)
except Exception as e:
    logger.error(f"Data fetching failed: {e}")
```

