from pymongo import MongoClient, ReadPreference

class InventoryDatabase:
    def __init__(self):
        client = MongoClient('mongodb://localhost:27017/')
        self.db = client['inventory_db']
        self.collection = self.db['products']

    def get_product(self, product_id):
        # Use read preference for high availability
        return self.collection.find_one({'_id': product_id}, read_preference=ReadPreference.SECONDARY_PREFERRED)

    def update_stock(self, product_id, stock_level):
        result = self.collection.update_one(
            {'_id': product_id},
            {'$set': {'stock': stock_level}}
        )
        return result.modified_count > 0

