JWT_SECRET_KEY = os.getenv('JWT_SECRET_KEY')

engine = create_engine(DATABASE_URL)
metadata = MetaData(bind=engine)

resources_table = Table('resources', metadata, autoload=True)

RATE_LIMIT = 5  # Max number of requests per minute

# JWT Authentication Decorator
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403

        try:
            data = jwt.decode(token, JWT_SECRET_KEY, algorithms=["HS256"])
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        request.user = data['user']
        return f(*args, **kwargs)
    return decorated

# Rate Limiting Decorator
def rate_limiter(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        user_id = request.user['id']
        ip_address = request.remote_addr

        # Simulated storage for simplicity
        if not hasattr(decorated_function, "access_count"):
            decorated_function.access_count = {}

        key = (user_id, ip_address)
        current_time = time.time()

        if key in decorated_function.access_count:
            accesses, first_access_time = decorated_function.access_count[key]

            # Allow new request only if within rate limit
            if accesses < RATE_LIMIT and (current_time - first_access_time) < 60:
                decorated_function.access_count[key] = (accesses + 1, first_access_time)
            else:
                return jsonify({'message': 'Rate limit exceeded!'}), 429

        # Initialize for a new key
        if key not in decorated_function.access_count:
            decorated_function.access_count[key] = (1, current_time)

        return f(*args, **kwargs)
    return decorated_function

@app.route('/resources/<int:id>', methods=['PUT'])
@token_required
def update_resource(id):
    data = request.json

    try:
        version = data.get('version')

        # Fetch current resource to check version consistency
        with engine.connect() as conn:
            s = select([resources_table]).where(resources_table.c.id == id, resources_table.c.version == version)
            result = conn.execute(s).fetchone()

            if not result:
                return jsonify({'message': 'Resource not found or version mismatch!'}), 404

            # Update resource
            u = sql_update(resources_table).where(resources_table.c.id == id).values(data, version=version + 1)
            conn.execute(u)

        return jsonify({'message': 'Resource updated successfully!'}), 200

    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/hash', methods=['POST'])
@token_required
@rate_limiter
def calculate_hash():
    file_path = request.json.get('file_path')

    if not os.path.exists(file_path):
        return jsonify({'message': 'File does not exist!'}), 404

    try:
        hash_md5 = md5()
        with open(file_path, "rb") as f:
            while chunk := f.read(4096):
                hash_md5.update(chunk)

        # Simulate progress tracking
        print("Calculating MD5 Hash... Done.")

        return jsonify({'hash': hash_md5.hexdigest()}), 200

    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True)
```

### Notes:

- The code uses Flask to create a simple RESTful API.
- SQLAlchemy and psycopg2 are used for database interactions with PostgreSQL.
- JWT is utilized for authentication and authorization via the `token_required` decorator.
- A basic rate limiting mechanism is implemented using a function decorator.
- MD5 hashing reads files in chunks, simulating progress tracking by printing to console.
- Error handling provides informative responses with appropriate HTTP status codes.
- Environment variables are used to configure sensitive information such as database URL and JWT secret key.
- Logging and auditing can be enhanced further using a logging library like `logging` or external services for real-world applications.

```javascript
class ScriptLoader {
  constructor(maxConcurrentRequests = 3) {
    this.maxConcurrentRequests = maxConcurrentRequests;
    this.loadingQueue = [];
  }

  loadScripts(scripts, callback) {
    const pendingScripts = scripts.filter(script => script.type === 'external');
    let activeRequests = 0;

    const executeNextScript = () => {
      if (activeRequests < this.maxConcurrentRequests && pendingScripts.length > 0) {
        const script = pendingScripts.shift();
        activeRequests++;

        fetch(script.src)
          .then(response => response.text())
          .then(data => {
            document.write(`<script>${data}</script>`);
            activeRequests--;
            executeNextScript();
          })
          .catch(error => {
            console.error(`Failed to load script: ${script.src}`, error);
            document.write('<div class="error">A script failed to load, but the application should still function.</div>');
            activeRequests--;
            executeNextScript();
          });
      } else if (pendingScripts.length === 0 && inlineScripts.length > 0) {
        inlineScripts.forEach(inline => {
          document.write(`<script>${inline.code}</script>`);
        });
        callback(); // All scripts loaded, execute callback
      }
    };

    const inlineScripts = scripts.filter(script => script.type === 'inline');

    if (pendingScripts.length > 0) {
      pendingScripts.forEach(executeNextScript);
    } else {
      inlineScripts.forEach(inline => {
        document.write(`<script>${inline.code}</script>`);
      });
      callback();
    }
  }
}

function renderScriptsFooter(scripts) {
  const loader = new ScriptLoader();

  return new Promise((resolve, reject) => {
    loader.loadScripts(scripts, () => {
      resolve('Scripts rendered');
    });
  });
}

