```c
// C Code: loadResourceBundle.c

#include "loadResourceBundle.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CACHE_SIZE 10

typedef struct {
    const char *path;
    ResourceBundle *bundle;
} CachedBundle;

static CachedBundle cache[CACHE_SIZE];
static int cacheIndex = 0;

int loadFromCache(const char *filePath, ResourceBundle **bundle) {
    for (int i = 0; i < cacheSize; ++i) {
        if (strcmp(cache[i].path, filePath) == 0 && cache[i].bundle != NULL) {
            *bundle = cache[i].bundle;
            return 1;
        }
    }
    return 0;
}

void addToCache(const char *filePath, ResourceBundle *bundle) {
    cache[cacheIndex % CACHE_SIZE] = (CachedBundle){ filePath, bundle };
    cacheIndex++;
}

int loadResourceBundle(const char *filePath, ResourceBundle **bundle) {
    if (!loadFromCache(filePath, bundle)) {
        FILE *file = fopen(filePath, "r");
        if (!file) {
            fprintf(stderr, "Error: File not found.\n");
            return -1;
        }

        ResourceBundle *resBundle = malloc(sizeof(ResourceBundle));
        if (!resBundle) {
            fclose(file);
            fprintf(stderr, "Error: Memory allocation failed for bundle.\n");
            return -2;
        }
        resBundle->count = 0;
        resBundle->items = NULL;

        char line[256];
        while (fgets(line, sizeof(line), file)) {
            char *key = strtok(line, "=");
            if (!key || !*key) {
                fprintf(stderr, "Error: Invalid data format.\n");
                freeResourceBundle(resBundle);
                fclose(file);
                return -3;
            }
            key[strcspn(key, "\n")] = '\0';

            char *valueStr = strtok(NULL, "=");
            if (!valueStr || !*valueStr) {
                fprintf(stderr, "Error: Invalid data format.\n");
                freeResourceBundle(resBundle);
                fclose(file);
                return -3;
            }
            valueStr[strcspn(valueStr, "\n")] = '\0';

            ResourceItem *item = malloc(sizeof(ResourceItem));
            if (!item) {
                fprintf(stderr, "Error: Memory allocation failed for resource item.\n");
                freeResourceBundle(resBundle);
                fclose(file);
                return -4;
            }

            item->key = strdup(key);
            char *endptr;
            long int intValue = strtol(valueStr, &endptr, 10);
            if (*endptr == '\0') {
                item->value = malloc(sizeof(long));
                *(long *)item->value = intValue;
            } else {
                double floatValue = strtod(valueStr, &endptr);
                if (*endptr == '\0') {
                    item->value = malloc(sizeof(double));
                    *(double *)item->value = floatValue;
                } else if (valueStr[0] == '"' && valueStr[strlen(valueStr) - 1] == '"') {
                    item->value = strdup(valueStr + 1);
                    item->value[strlen(item->value)] = '\0';
                } else {
                    fprintf(stderr, "Error: Invalid data format.\n");
                    freeResourceItem(item);
                    freeResourceBundle(resBundle);
                    fclose(file);
                    return -3;
                }
            }

            resBundle->items = realloc(resBundle->items, sizeof(ResourceItem *) * (resBundle->count + 1));
            if (!resBundle->items) {
                fprintf(stderr, "Error: Memory allocation failed for items.\n");
                freeResourceItem(item);
                freeResourceBundle(resBundle);
                fclose(file);
                return -5;
            }
            resBundle->items[resBundle->count++] = item;
        }

        fclose(file);

        *bundle = resBundle;
        addToCache(filePath, resBundle);
    }

    return 0;
}

void freeResourceItem(ResourceItem *item) {
    if (item->key) free(item->key);
    if (item->value) {
        if (*(char **)item->value == item->value) { // String value
            free(item->value);
        } else {
            free(item->value); // Int/Float
        }
    }
    free(item);
}

void freeResourceBundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        freeResourceItem(bundle->items[i]);
    }
    if (bundle->items) free(bundle->items);
    free(bundle);
}
