// Rust Code: create_config_dir_and_set_env_var.rs

use std::env;
use std::fs;
use std::path::Path;

fn createConfigDirAndSetEnvVar(dir_name: &str, env_var_name: &str) -> Result<(), String> {
    match env::var(env_var_name) {
        Ok(path) => {
            if Path::new(&path).exists() && Path::new(&path).is_dir() {
                println!("Using existing directory at path: {}", path);
            } else {
                return Err(format!("Environment variable {} is set but points to an invalid directory.", env_var_name));
            }
        },
        Err(_) => {
            match fs::create_dir(dir_name) {
                Ok(_) => {
                    let new_path = Path::new(dir_name).canonicalize().map_err(|_| format!("Failed to canonicalize path for {}", dir_name))?;
                    env::set_var(env_var_name, new_path.to_str().ok_or("Path conversion to string failed")?);
                    println!("Created directory and set environment variable: {:?}", new_path);
                },
                Err(e) => return Err(format!("Error creating directory {}: {}", dir_name, e)),
            }
        }
    }

    Ok(())
}

fn main() {
    match createConfigDirAndSetEnvVar("my_config_dir", "MY_CONFIG_DIR") {
        Ok(_) => println!("Configuration directory is ready."),
        Err(err) => eprintln!("Error: {}", err),
    }
}
