void log_message(int level, const char *message) {
    if (level >= LOG_DEBUG && level <= LOG_ERROR) {
        printf("Log [%d]: %s\n", level, message);
    }
}

int validate_date(const char *date_string) {
    struct tm tm;
    memset(&tm, 0, sizeof(struct tm));
    return strptime(date_string, "%Y-%m-%d", &tm) != NULL && mktime(&tm) == time(NULL);
}

void* external_date_validation_service(void *arg) {
    // Simulate an external service call with authentication and rate limit handling
    ParseDateRequest *request = (ParseDateRequest *)arg;
    sleep(1);  // Simulate network delay
    return NULL;
}

char* parseAndFormatDate(const char *date_string, const char *format, int log_level, const char *time_zone) {
    if (!date_string || !format) {
        log_message(log_level, "Invalid input: null date string or format");
        return NULL;
    }

    pthread_mutex_lock(&global_mutex);

    ParseDateRequest request = {strdup(date_string), format, log_level};
    void *service_thread_result;
    pthread_t service_thread;
    pthread_create(&service_thread, NULL, external_date_validation_service, &request);

    // Wait for the thread to finish
    pthread_join(service_thread, &service_thread_result);

    if (!validate_date(request.date_string)) {
        log_message(log_level, "Invalid date format");
        free(request.date_string);
        pthread_mutex_unlock(&global_mutex);
        return NULL;
    }

    struct tm tm = {0};
    strptime(request.date_string, "%Y-%m-%d", &tm);

    // Handle time zone conversion (mock implementation)
    if (strcmp(time_zone, "UTC") != 0) {
        log_message(log_level, "Time zone conversion not implemented");
    }

    char *buffer = malloc(100);
    if (!buffer) {
        log_message(LOG_ERROR, "Memory allocation failed for buffer");
        free(request.date_string);
        pthread_mutex_unlock(&global_mutex);
        return NULL;
    }

    strftime(buffer, 100, format, &tm);

    // Use a simple hash to cache the result
    unsigned int hash = (unsigned int)strtol(date_string, NULL, 10) ^ (unsigned int)strtol(format, NULL, 10);
    if (cache[hash].formatted_date) {
        pthread_mutex_lock(&cache[hash].mutex);
        char *cached_result = strdup(cache[hash].formatted_date);
        free(buffer);
        buffer = cached_result;
        pthread_mutex_unlock(&cache[hash].mutex);
    } else {
        pthread_mutex_init(&cache[hash].mutex, NULL);
        cache[hash].formatted_date = buffer;
    }

    free(request.date_string);

    pthread_mutex_unlock(&global_mutex);

    return buffer;
}

void freeFormattedDate(char *date) {
    unsigned int hash = (unsigned int)strtol(date, NULL, 10); // Simple mock for demonstration
    if (cache[hash].formatted_date) {
        pthread_mutex_lock(&cache[hash].mutex);
        free(cache[hash].formatted_date);
        cache[hash].formatted_date = NULL;
        pthread_mutex_unlock(&cache[hash].mutex);
        pthread_mutex_destroy(&cache[hash].mutex);
    }
}

int main() {
    char *date = parseAndFormatDate("2023-10-01", "%d/%m/%Y", LOG_INFO, "UTC");
    if (date) {
        printf("Formatted Date: %s\n", date);
        freeFormattedDate(date);
    }
    return 0;
}
