```javascript
const axios = require('axios');
const NodeCache = require('node-cache');

// Initialize cache with default TTL of 1 hour (3600 seconds)
const textCache = new NodeCache({ stdTTL: 3600 });

async function fetchBookNames() {
    try {
        const response = await axios.get('https://example.com/api/bible-books');
        return response.data.map(book => book.toLowerCase());
    } catch (error) {
        console.error('Error fetching book names:', error);
        throw new Error('Failed to retrieve book names from API.');
    }
}

async function extractBookNames(text) {
    // Check cache
    const cachedResult = textCache.get(text);
    if (cachedResult) {
        console.log('Returning cached result');
        return cachedResult;
    }

    try {
        const bookNames = await fetchBookNames();
        const regexPatterns = bookNames.map(book => new RegExp(`\\b${book}\\b`, 'gi'));

        // Remove punctuation and special characters
        const cleanedText = text.replace(/[^a-z0-9\s]/gi, '');

        let bookCount = {};
        regexPatterns.forEach(pattern => {
            const matches = cleanedText.match(pattern);
            if (matches) {
                const normalizedBookName = matches[0].toLowerCase();
                bookCount[normalizedBookName] = (bookCount[normalizedBookName] || 0) + matches.length;
            }
        });

        // Cache the result
        textCache.set(text, bookCount);

        console.log('Processed and cached new result');
        return bookCount;
    } catch (error) {
        console.error('Error processing text:', error);
        throw new Error('Failed to extract book names.');
    }
}

