### Explanation:

1. **API Integration**: The function `fetchBookNames` fetches a list of valid Bible book names from an external REST API.

2. **Caching**: Uses `node-cache` to store previously processed texts, reducing redundant processing and improving performance.

3. **Regex Matching**: Constructs regex patterns dynamically based on the fetched book names, ensuring case-insensitivity and whole-word matching.

4. **Text Cleaning**: Removes punctuation and special characters from the input text for accurate matching.

5. **Error Handling & Logging**: Includes error handling with logging to aid debugging and maintainability.

6. **Performance Metrics**: Logs cache hits and new processing events to help monitor performance.

This implementation balances accuracy, efficiency, and robustness, making it suitable for large-scale text analysis.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>
#include <time.h>

#define BUFFER_SIZE 4096

typedef struct {
    int start_line;
    int end_line;
    const char *file_path;
    FILE *output_file;
} ThreadData;

void* process_lines(void* arg);
double parse_and_compute(double* fields, int num_fields);
int is_number(const char* str);
void log_message(const char* level, const char* message);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input_file> <start_line> <end_line> [output_file]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* file_path = argv[1];
    int start_line = atoi(argv[2]);
    int end_line = atoi(argv[3]);
    FILE *output_file = (argc > 4) ? fopen(argv[4], "w") : stdout;

    if (!output_file || output_file == stderr) {
        log_message("ERROR", "Failed to open output file.");
        return EXIT_FAILURE;
    }

    ThreadData data = {start_line, end_line, file_path, output_file};

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_lines, &data)) {
        log_message("ERROR", "Thread creation failed.");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    fclose(output_file);
    return EXIT_SUCCESS;
}

void* process_lines(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    FILE *file = fopen(data->file_path, "r");
    if (!file) {
        log_message("ERROR", "Failed to open input file.");
        pthread_exit(NULL);
    }

    char buffer[BUFFER_SIZE];
    int line_number = 0;
    double sum, avg;

    while (fgets(buffer, BUFFER_SIZE, file)) {
        line_number++;

        if (line_number < data->start_line) continue;
        if (line_number > data->end_line) break;

        char *token = strtok(buffer, " \t\n");
        double fields[1000];
        int count = 0;

        while (token) {
            if (is_number(token)) {
                fields[count++] = atof(token);
            }
            token = strtok(NULL, " \t\n");
        }

        if (count >= 3) {
            avg = parse_and_compute(&fields[count - 3], 3);
            pthread_mutex_lock(&lock);
            fprintf(data->output_file, "%lf,", avg);
            pthread_mutex_unlock(&lock);
        }
    }

    fclose(file);
    pthread_exit(NULL);
}

double parse_and_compute(double* fields, int num_fields) {
    double sum = 0;
    for (int i = 0; i < num_fields; ++i) {
        sum += fields[i];
    }
    return sum / num_fields;
}

int is_number(const char* str) {
    while (*str) {
        if (!isdigit(*str) && *str != '.' && *str != '-' && *str != '+') return 0;
        str++;
    }
    return 1;
}

void log_message(const char* level, const char* message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(stderr, "[%s] [%s]: %s\n", timestamp, level, message);
}
```

