import * as dotenv from 'dotenv';
import axios from 'axios';
import { parse } from 'yaml';
import fs from 'fs';
import path from 'path';
import { Queue } from 'bull';
import { promisify } from 'util';
import { createLogger, format, transports } from 'winston';

// Load environment variables
dotenv.config();

const configPath = path.resolve(__dirname, './config.yaml');
const configFile = fs.readFileSync(configPath, 'utf8');
const config = parse(configFile);

// Logger setup
const logger = createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: format.combine(format.timestamp(), format.json()),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'application.log' })
  ]
});

interface PaymentGatewayConfig {
  apiKey: string;
  apiUrl: string;
}

const paymentGatewayConfig: PaymentGatewayConfig = config.paymentGateway;

// Queue setup
const paymentQueue = new Queue('payments', 'redis://localhost:6379');

class TransactionHandler {
  private readonly maxRetries: number;
  private readonly backoffStrategy: (attempt: number) => Promise<void>;

  constructor(maxRetries: number, backoffStrategy: (attempt: number) => Promise<void>) {
    this.maxRetries = maxRetries;
    this.backoffStrategy = backoffStrategy;
  }

  async createTransaction(payload: any): Promise<any> {
    return this.executeWithRetry(async () => {
      const response = await axios.post(paymentGatewayConfig.apiUrl, payload, {
        headers: { 'Authorization': `Bearer ${paymentGatewayConfig.apiKey}` }
      });
      return response.data;
    }, 'create');
  }

  async captureTransaction(transactionId: string): Promise<any> {
    return this.executeWithRetry(async () => {
      const response = await axios.post(`${paymentGatewayConfig.apiUrl}/capture`, { id: transactionId }, {
        headers: { 'Authorization': `Bearer ${paymentGatewayConfig.apiKey}` }
      });
      return response.data;
    }, 'capture');
  }

  async authorizeTransaction(payload: any): Promise<any> {
    return this.executeWithRetry(async () => {
      const response = await axios.post(`${paymentGatewayConfig.apiUrl}/authorize`, payload, {
        headers: { 'Authorization': `Bearer ${paymentGatewayConfig.apiKey}` }
      });
      return response.data;
    }, 'authorize');
  }

  async voidTransaction(transactionId: string): Promise<any> {
    return this.executeWithRetry(async () => {
      const response = await axios.post(`${paymentGatewayConfig.apiUrl}/void`, { id: transactionId }, {
        headers: { 'Authorization': `Bearer ${paymentGatewayConfig.apiKey}` }
      });
      return response.data;
    }, 'void');
  }

  private async executeWithRetry<T>(operation: () => Promise<T>, operationName: string, attempt = 1): Promise<T> {
    try {
      return await operation();
    } catch (error) {
      if (attempt > this.maxRetries) throw error;

      logger.error(`Error during ${operationName}, retrying... Attempt ${attempt}`, { error });
      const delay = this.backoffStrategy(attempt);
      await delay;
      return this.executeWithRetry(operation, operationName, attempt + 1);
    }
  }

  private static exponentialBackoff(attempt: number): Promise<void> {
    const delay = Math.pow(2, attempt) * 100; // Exponential backoff
    return new Promise((resolve) => setTimeout(resolve, delay));
  }
}

// Payment processing logic
paymentQueue.process(async (job, done) => {
  const transactionHandler = new TransactionHandler(3, TransactionHandler.exponentialBackoff);
  try {
    const result = await transactionHandler.createTransaction(job.data);
    logger.info('Payment processed successfully', { jobId: job.id });
    done(null, result);
  } catch (error) {
    logger.error('Failed to process payment', { error, jobId: job.id });
    done(error);
  }
});

// Example of adding a job to the queue
async function addPaymentToQueue(paymentData: any) {
  await paymentQueue.add(paymentData);
}

// Export for testing or external use
export { TransactionHandler, addPaymentToQueue };
