<?php

class PasswordUpdateException extends Exception {}

interface RateLimiterInterface {
    public function increment($userId): void;
    public function isAllowed($userId): bool;
}

interface LoggerInterface {
    public function log(string $message): void;
}

interface MFAProviderInterface {
    public function verifyMfaCode($userId, $code): bool;
    public function isMfaEnabled($userId): bool;
}

class RedisRateLimiter implements RateLimiterInterface {
    private $redis;
    private $maxAttempts = 5;
    private $timeWindow = 60; // seconds

    public function __construct(PDO $pdo) {
        $this->redis = new Redis();
        $this->redis->connect('127.0.0.1', 6379);
    }

    public function increment($userId): void {
        $key = "user:{$userId}:password_update_attempts";
        $this->redis->incr($key);
        $this->redis->expire($key, $this->timeWindow);
    }

    public function isAllowed($userId): bool {
        $key = "user:{$userId}:password_update_attempts";
        return $this->redis->get($key) < $this->maxAttempts;
    }
}

class AuditLogger implements LoggerInterface {
    private $pdo;

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function log(string $message): void {
        // Assume `audit_logs` table with columns: id, message, created_at
        $stmt = $this->pdo->prepare("INSERT INTO audit_logs (message, created_at) VALUES (:message, NOW())");
        $stmt->execute(['message' => $message]);
    }
}

class UserDAO {
    private $pdo;

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function updateUserPassword($userId, $newPasswordHash): bool {
        try {
            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
            return $stmt->execute(['password' => $newPasswordHash, 'id' => $userId]);
        } catch (Exception $e) {
            throw new PasswordUpdateException('Database error: ' . $e->getMessage());
        }
    }

    public function getUserData($userId) {
        // Assume `users` table with columns: id, username
        $stmt = $this->pdo->prepare("SELECT username FROM users WHERE id = :id");
        $stmt->execute(['id' => $userId]);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }
}

function validatePassword(string $password, string $username): bool {
    if (strlen($password) < 8) return false;
    if (!preg_match('/[A-Z]/', $password)) return false;
    if (!preg_match('/[a-z]/', $password)) return false;
    if (!preg_match('/\d/', $password)) return false;
    if (!preg_match('/[\!\@\#\$\%\^\&\*]/', $password)) return false;
    if (strpos($password, $username) !== false || strpos(strtolower($password), strtolower($username)) !== false) {
        return false;
    }
    return true;
}

function updateUserPassword(
    PDO $pdo,
    RateLimiterInterface $rateLimiter,
    LoggerInterface $logger,
    UserDAO $userDao,
    MFAProviderInterface $mfaProvider,
    int $userId,
    string $newPassword,
    string $username,
    array $requestDetails
) {
    if (!$rateLimiter->isAllowed($userId)) {
        throw new PasswordUpdateException('Too many attempts. Please try again later.');
    }

    $user = $userDao->getUserData($userId);
    if ($user['username'] !== $username) {
        throw new PasswordUpdateException('Username mismatch.');
    }

    if (!validatePassword($newPassword, $username)) {
        throw new PasswordUpdateException('Password validation failed.');
    }

    if ($mfaProvider->isMfaEnabled($userId)) {
        // Assume `requestDetails` contains MFA code
        $mfaCode = $requestDetails['mfa_code'] ?? null;
        if (!$mfaProvider->verifyMfaCode($userId, $mfaCode)) {
            throw new PasswordUpdateException('Invalid MFA code.');
        }
    }

    $attempts = 0;
    while ($attempts < 3) {
        try {
            $newPasswordHash = password_hash($newPassword, PASSWORD_BCRYPT);
            if ($userDao->updateUserPassword($userId, $newPasswordHash)) {
                $logger->log("Password update successful for user ID: {$userId}, IP: " . $requestDetails['ip'] . ", UserAgent: " . $requestDetails['user_agent']);
                return true;
            }
        } catch (PasswordUpdateException $e) {
            $attempts++;
            sleep(pow(2, $attempts)); // Exponential backoff
            continue 2;
        }
    }

    throw new PasswordUpdateException('Failed to update password after multiple attempts.');
}

// Unit tests can be added using PHPUnit or similar frameworks.
