import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DatabaseConnectionManager {
    private int initialSize;
    private int maxSize;
    private String connectionString;
    private Queue<Connection> availableConnections = new LinkedList<>();
    private Lock lock = new ReentrantLock();
    private Condition notEmpty = lock.newCondition();
    private long maxIdleTime = 300000; // Default to 5 minutes
    private boolean testOnBorrow = true;

    public void initializePool(int initialSize, int maxSize, String connectionString) {
        if (initialSize <= 0 || maxSize < initialSize || maxSize <= 0 || connectionString == null || connectionString.isEmpty()) {
            throw new IllegalArgumentException("Invalid parameters for initializing the connection pool.");
        }

        this.initialSize = initialSize;
        this.maxSize = maxSize;
        this.connectionString = connectionString;

        try {
            for (int i = 0; i < initialSize; i++) {
                availableConnections.offer(createConnection());
            }
        } catch (SQLException e) {
            throw new RuntimeException("Error initializing database connection pool.", e);
        }
    }

    public Connection getConnection() throws InterruptedException {
        lock.lock();
        try {
            while (availableConnections.isEmpty()) {
                notEmpty.await();
            }
            Connection conn = availableConnections.poll();
            if (testOnBorrow && !testConnection(conn)) {
                conn.close();
                return getConnection(); // Retry
            }
            return conn;
        } finally {
            lock.unlock();
        }
    }

    public void releaseConnection(Connection conn) {
        lock.lock();
        try {
            if (testConnection(conn)) {
                availableConnections.offer(conn);
                notEmpty.signalAll();
            } else {
                try {
                    conn.close();
                } catch (SQLException e) {
                    // Log and handle the error
                }
            }
        } finally {
            lock.unlock();
        }
    }

    private boolean testConnection(Connection conn) {
        try {
            return conn.isValid(5);
        } catch (SQLException e) {
            try {
                conn.close();
            } catch (SQLException ex) {
                // Log and handle the error
            }
            return false;
        }
    }

    public void resetPool() {
        lock.lock();
        try {
            for (Connection conn : availableConnections) {
                try {
                    conn.close();
                } catch (SQLException e) {
                    // Log and handle the error
                }
            }
            availableConnections.clear();
            initializePool(initialSize, maxSize, connectionString);
        } finally {
            lock.unlock();
        }
    }

    public void setMaxIdleTime(long maxIdleTime) {
        if (maxIdleTime < 0 || maxIdleTime > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("Invalid max idle time.");
        }
        this.maxIdleTime = maxIdleTime;
    }

    public void setTestOnBorrow(boolean testOnBorrow) {
        this.testOnBorrow = testOnBorrow;
    }

    public void logConnectionUsage(String ipAddress, String action, String databaseName) {
        // Implement logging logic using a preferred logging framework
    }

    public void monitorPoolStatus() {
        lock.lock();
        try {
            System.out.println("Active Connections: " + (maxSize - availableConnections.size()));
            System.out.println("Idle Connections: " + availableConnections.size());
            System.out.println("Total Connections: " + maxSize);
        } finally {
            lock.unlock();
        }
    }

    public String sanitizeSQLQuery(String query) {
        // Implement parameterized queries to prevent SQL injection
        // For demonstration, this is a placeholder for actual sanitization logic
        return query.replaceAll("'", "''"); // Example of basic escaping
    }

    private Connection createConnection() throws SQLException {
        return DriverManager.getConnection(connectionString);
    }
}
