# json_base.py

import json
from abc import ABC, abstractmethod
from typing import Any, Dict, Callable
import threading
import time


class BaseClass(ABC):
    registry: Dict[str, Callable] = {}
    _registry_lock = threading.Lock()

    def __init__(self):
        self._last_access_time = time.time()

    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    def from_json(cls, json_str: str) -> 'BaseClass':
        try:
            data = json.loads(json_str)
            # Validate against schema (simplified here for brevity)
            required_keys = ['type', 'attributes']
            if not all(key in data for key in required_keys):
                raise ValueError("Invalid JSON structure")

            factory = cls.registry.get(data['type'])
            if not factory:
                raise ValueError(f"No registered factory found for type {data['type']}")

            instance = factory(**data['attributes'])
            return instance
        except (json.JSONDecodeError, KeyError) as e:
            # Handle JSON errors gracefully
            print(f"Error decoding JSON: {e}")
            return None

    @classmethod
    def register_factory(cls, name: str):
        def decorator(factory_function: Callable):
            with cls._registry_lock:
                if name in cls.registry:
                    raise ValueError(f"Factory '{name}' already registered.")
                cls.registry[name] = factory_function
                # Update last access time to prevent cleanup
                for entry in cls.registry.values():
                    entry._last_access_time = time.time()
            return factory_function
        return decorator

    @classmethod
    def discover_subclasses(cls, directory: str):
        import os
        import importlib.util

        with cls._registry_lock:
            for filename in os.listdir(directory):
                if filename.endswith('.py'):
                    module_name = filename[:-3]
                    file_path = os.path.join(directory, filename)

                    spec = importlib.util.spec_from_file_location(module_name, file_path)
                    module = importlib.util.module_from_spec(spec)
                    spec.loader.exec_module(module)

                    for attr in dir(module):
                        obj = getattr(module, attr)
                        if isinstance(obj, type) and issubclass(obj, cls) and obj is not cls:
                            if hasattr(obj, 'factory_name'):
                                cls.register_factory(obj.factory_name)(obj)

    @classmethod
    def cleanup_registry(cls, timeout: int):
        current_time = time.time()
        with cls._registry_lock:
            to_remove = [name for name, func in cls.registry.items()
                         if (current_time - getattr(func, '_last_access_time', 0)) > timeout]
            for name in to_remove:
                del cls.registry[name]

    @classmethod
    def load_from_yaml(cls, yaml_path: str):
        import yaml

        with open(yaml_path, 'r') as file:
            data = yaml.safe_load(file)

        for entry in data.get('factories', []):
            factory_name = entry['name']
            # Assume we have a way to locate these classes dynamically
            cls.register_factory(factory_name)(eval(entry['class']))

    @classmethod
    def save_to_file(cls, file_path: str):
        import json

        with open(file_path, 'w') as file:
            json.dump(list(cls.registry.keys()), file)

# registry.py

import threading
from typing import Callable

_registry_lock = threading.Lock()
factory_cache: Dict[str, Callable] = {}

def register_factory(name: str) -> Callable:
    def decorator(factory_function: Callable):
        with _registry_lock:
            if name in factory_cache:
                raise ValueError(f"Factory '{name}' already registered.")
            factory_cache[name] = factory_function
        return factory_function
    return decorator

def get_cached_factory(name: str) -> Callable:
    with _registry_lock:
        return factory_cache.get(name)

def cleanup_inactive_factories(timeout: int):
    current_time = time.time()
    to_remove = [name for name, func in factory_cache.items() 
                 if (current_time - getattr(func, '_last_access_time', 0)) > timeout]

    with _registry_lock:
        for name in to_remove:
            del factory_cache[name]

# subclasses.py

from json_base import BaseClass
import yaml


class ExampleSubclass(BaseClass):
    factory_name = "example"

    def __init__(self, attr1: str, attr2: int):
        super().__init__()
        self.attr1 = attr1
        self.attr2 = attr2

    def to_json(self) -> str:
        return json.dumps({
            'type': 'example',
            'attributes': {
                'attr1': self.attr1,
                'attr2': self.attr2
            }
        })

# Usage example in main.py or similar entry point

if __name__ == "__main__":
    # Discover subclasses and register them
    BaseClass.discover_subclasses('path_to_your_directory')

    # Register ExampleSubclass explicitly
    BaseClass.register_factory("example")(ExampleSubclass)

    # Convert to/from JSON
    example = ExampleSubclass(attr1="test", attr2=42)
    json_str = example.to_json()
    new_example = BaseClass.from_json(json_str)

    # Load factories from YAML file
    BaseClass.load_from_yaml('config.yaml')

    # Save current registry state
    BaseClass.save_to_file('registry_state.json')

    # Cleanup inactive factories every 60 seconds (example)
    import threading

    def periodic_cleanup():
        while True:
            time.sleep(60)
            BaseClass.cleanup_registry(timeout=300)  # Timeout after 5 minutes of inactivity

    cleanup_thread = threading.Thread(target=periodic_cleanup, daemon=True)
    cleanup_thread.start()
