#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include "sqlite3.h"
#include "zlib.h" // Include zlib for compression

// Define the record structure
typedef struct {
    int key;
    long timestamp;
    char *description;
    double value;
} Record;

// Function prototypes
int initialize_records(Record **records, size_t *record_count);
void compress_memory(void *data, size_t data_size, void **compressed_data, size_t *compressed_size, int level);
void decompress_memory(const void *compressed_data, size_t compressed_size, void **decompressed_data, size_t original_size);

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initialize_records(Record **records, size_t *record_count) {
    sqlite3 *db;
    char *err_msg = NULL;
    int rc = sqlite3_open("database.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Query to get the number of records
    const char *sql_query = "SELECT COUNT(*) FROM Records;";
    sqlite3_stmt *stmt;

    rc = sqlite3_prepare_v2(db, sql_query, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to fetch record count: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    // Execute the query
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        *record_count = sqlite3_column_int(stmt, 0);
    } else {
        fprintf(stderr, "Failed to execute query: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return -1;
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);

    if (*record_count == 0) {
        *records = NULL;
        return 0;
    }

    pthread_mutex_lock(&mutex); // Ensure thread safety

    // Allocate memory for records
    *records = (Record *)malloc(*record_count * sizeof(Record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    char **descriptions = (char **)malloc(*record_count * sizeof(char *));
    if (!descriptions) {
        fprintf(stderr, "Memory allocation for descriptions failed\n");
        free(*records);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand((unsigned int)time(NULL));

    // Initialize each record with random values
    for (size_t i = 0; i < *record_count; ++i) {
        (*records)[i].key = rand() % 10001;
        time_t now = time(NULL);
        long seconds_in_year = 365.25 * 24 * 60 * 60;
        (*records)[i].timestamp = (long)(now + (rand() % (int)seconds_in_year));

        // Allocate memory for description
        descriptions[i] = (char *)malloc(256);
        if (!descriptions[i]) {
            fprintf(stderr, "Memory allocation for description failed\n");
            while (--i >= 0) free(descriptions[i]);
            free(descriptions);
            free(*records);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        snprintf(descriptions[i], 256, "Description %zu", i + 1);

        (*records)[i].description = descriptions[i];
        (*records)[i].value = (double)(rand() % 20001) - 10000.0;
    }

    pthread_mutex_unlock(&mutex); // Release the mutex

    // Compress memory
    void *compressed_data = NULL;
    size_t compressed_size = 0;

    compress_memory(*records, *record_count * sizeof(Record), &compressed_data, &compressed_size, Z_BEST_COMPRESSION);

    if (compressed_data) {
        free(compressed_data); // Clean up after demonstration of compression
    }

    return 0;
}

void compress_memory(void *data, size_t data_size, void **compressed_data, size_t *compressed_size, int level) {
    uLongf compressed_len = compressBound(data_size);
    *compressed_data = malloc(compressed_len);

    if (*compressed_data) {
        if (compress2((Bytef *)*compressed_data, &compressed_len, (const Bytef *)data, data_size, level) == Z_OK) {
            *compressed_size = compressed_len;
        } else {
            free(*compressed_data);
            *compressed_data = NULL;
            *compressed_size = 0;
        }
    }
}

void decompress_memory(const void *compressed_data, size_t compressed_size, void **decompressed_data, size_t original_size) {
    *decompressed_data = malloc(original_size);

    if (*decompressed_data) {
        if (uncompress((Bytef *)*decompressed_data, &original_size, (const Bytef *)compressed_data, compressed_size) == Z_OK) {
            // Decompression successful
        } else {
            free(*decompressed_data);
            *decompressed_data = NULL;
        }
    }
}
```

This code provides a function `initialize_records` that initializes and manages an array of `Record` structures. It interacts with a SQLite database to determine the number of records, allocates memory dynamically for these records and their fields, sets random values within specified ranges, handles thread safety using mutexes, includes error handling, and demonstrates compression/decompression of allocated memory. The code is designed to be extensible for future modifications.

