Below is a C implementation using OpenSSL that initializes an AES-256-CBC cipher with a given password. It uses PBKDF2 for key derivation, generates a random IV, and includes cleanup functionality. Proper error handling is implemented to ensure thread safety and resource optimization.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

#define KEY_LEN 32  // AES-256 key length in bytes
#define IV_LEN   16 // IV length for AES

// Function to initialize an AES-256-CBC cipher context with a given password
EVP_CIPHER_CTX* init_aes_256_cbc_cipher(const char *password, int iter_count) {
    if (password == NULL || strlen(password) < 8) { // Ensure minimum password length
        return NULL;
    }

    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Error generating random salt\n");
        return NULL;
    }

    unsigned char key[KEY_LEN], iv[IV_LEN];

    // Derive the key and IV using PBKDF2
    int key_len = KEY_LEN;
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), 
                          salt, sizeof(salt), iter_count,
                          EVP_sha256(), key_len, key) != 1) {
        fprintf(stderr, "Error deriving key\n");
        return NULL;
    }

    // Generate a random IV
    if (!RAND_bytes(iv, IV_LEN)) {
        fprintf(stderr, "Error generating random IV\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    // Initialize the encryption operation with AES-256-CBC
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx; // Return the initialized context
}

// Function to clean up and disable the cipher when no longer needed
void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
```

### Explanation:

1. **Password Validation**: The function checks for a minimum password length to ensure security.
2. **Salt and IV Generation**: Random bytes are generated using `RAND_bytes` for both salt and IV, ensuring uniqueness and unpredictability.
3. **Key Derivation**: PBKDF2 with HMAC-SHA256 is used for deriving the key from the password, with configurable iterations (`iter_count`) to enhance security against brute-force attacks.
4. **Cipher Context Initialization**: An `EVP_CIPHER_CTX` is created and initialized with AES-256-CBC using the derived key and random IV.
5. **Error Handling**: The function includes error handling for memory allocation failures, random byte generation errors, and key derivation issues.
6. **Cleanup Function**: A separate function (`cleanup_cipher`) is provided to properly free resources when the cipher context is no longer needed.

This implementation ensures that the AES-256-CBC cipher is securely initialized with a derived key and random IV, while also providing robust error handling and resource management.

Here is a Java method named `OptimizeImageUploadAndResize` that integrates with AWS S3 for uploading images, resizing them based on predefined dimensions from a configuration file, applying compression techniques, and returning the URL of the resized image.

```java
import com.amazonaws.auth.AWSStaticCredentialsProvider;
import com.amazonaws.auth.BasicAWSCredentials;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.services.s3.model.PutObjectRequest;
import javax.imageio.ImageIO;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Properties;

public class ImageOptimizer {

    private static final int MAX_CONCURRENT_OPS = 5; // Max parallel operations
    private Semaphore semaphore;

    public ImageOptimizer() {
        semaphore = new Semaphore(MAX_CONCURRENT_OPS);
    }

    public String OptimizeImageUploadAndResize(byte[] imageData, Callback callback) throws IOException {
        try {
            semaphore.acquire();

            Properties config = loadConfig();
            int maxWidth = Integer.parseInt(config.getProperty("maxWidth"));
            int maxHeight = Integer.parseInt(config.getProperty("maxHeight"));
            float compressionQuality = Float.parseFloat(config.getProperty("compressionQuality"));

            BufferedImage originalImage = ImageIO.read(new ByteArrayInputStream(imageData));
            if (originalImage == null) {
                throw new IOException("Invalid image data.");
            }

            BufferedImage resizedImage = resizeImage(originalImage, maxWidth, maxHeight);
            ByteArrayOutputStream compressedStream = compressImage(resizedImage, compressionQuality);

            String keyName = generateUniqueKey();
            AmazonS3 s3Client = createS3Client();

            PutObjectRequest request = new PutObjectRequest("your-bucket-name", keyName, compressedStream.toByteArray(), null);
            s3Client.putObject(request);

            callback.onProgress("Upload complete");

            return "https://your-bucket-name.s3.amazonaws.com/" + keyName;

        } catch (IOException | InterruptedException e) {
            throw new IOException("Error in optimizing image upload and resize: " + e.getMessage());
        } finally {
            semaphore.release();
        }
    }

    private Properties loadConfig() throws IOException {
        Properties prop = new Properties();
        prop.load(Files.newInputStream(Paths.get("config.properties")));
        return prop;
    }

    private BufferedImage resizeImage(BufferedImage originalImage, int maxWidth, int maxHeight) {
        int width = originalImage.getWidth();
        int height = originalImage.getHeight();

        double aspectRatio = (double) width / height;
        if (width > maxWidth || height > maxHeight) {
            if (aspectRatio >= 1.0) { // Width is greater
                width = maxWidth;
                height = (int) (maxWidth / aspectRatio);
            } else {
                height = maxHeight;
                width = (int) (maxHeight * aspectRatio);
            }
        }

        Image tmp = originalImage.getScaledInstance(width, height, Image.SCALE_SMOOTH);
        BufferedImage resizedImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        Graphics2D g2d = resizedImage.createGraphics();
        g2d.drawImage(tmp, 0, 0, null);
        g2d.dispose();

        return resizedImage;
    }

    private ByteArrayOutputStream compressImage(BufferedImage image, float quality) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(image, "jpg", baos);

        // Apply compression with specified quality
        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        BufferedImage compressedImage = ImageIO.read(bais);
        baos.reset();

        ImageWriteParam param = ImageIO.getImageWritersByFormatName("jpg").next().getDefaultWriteParam();
        param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        param.setCompressionQuality(quality);

        ImageOutputStream ios = new ByteArrayOutputStreamImageOutputStream(baos);
        ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
        writer.setOutput(ios);
        writer.write(null, new IIOMetadata(), param);

        writer.dispose();
        ios.close();

        return baos;
    }

    private String generateUniqueKey() {
        // Generate a unique key for the S3 object
        return "image-" + System.currentTimeMillis() + ".jpg";
    }

    private AmazonS3 createS3Client() {
        BasicAWSCredentials awsCreds = new BasicAWSCredentials("YOUR_ACCESS_KEY", "YOUR_SECRET_KEY");
        return AmazonS3ClientBuilder.standard()
                .withCredentials(new AWSStaticCredentialsProvider(awsCreds))
                .withRegion(com.amazonaws.regions.Regions.DEFAULT_REGION)
                .build();
    }

    public interface Callback {
        void onProgress(String message);
    }
}
```

### Key Points:
- **Concurrency Control:** The `Semaphore` is used to control the number of concurrent operations.
- **Configuration Loading:** Loads target dimensions and compression quality from a properties file.
- **Image Processing:** Resizes images while maintaining aspect ratio, then compresses them to reduce file size.
- **AWS S3 Integration:** Uploads the processed image to an S3 bucket using AWS credentials for authentication.
- **Error Handling:** Includes basic exception handling and reporting via callback. 

