```python
import json
from datetime import datetime
from uuid import UUID
from decimal import Decimal
import logging

class JSONSerializable:
    def __init__(self, **kwargs):
        self.__dict__.update(kwargs)

    @staticmethod
    def _custom_encoder(obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        elif isinstance(obj, UUID):
            return str(obj)
        elif isinstance(obj, Decimal):
            return float(obj)  # or str(obj) for precision
        raise TypeError(f"Type {type(obj)} not serializable")

    def to_json(self):
        try:
            return json.dumps(self.__dict__, default=self._custom_encoder)
        except Exception as e:
            logging.error("Serialization error", exc_info=e)
            raise

    @classmethod
    def from_json(cls, json_str):
        try:
            data = json.loads(json_str)
            instance = cls(**data)
            return instance
        except json.JSONDecodeError as e:
            logging.error("Deserialization error", exc_info=e)
            raise

    @staticmethod
    def create_instance(data_type, *args, **kwargs):
        factory_functions = {
            'datetime': lambda: datetime(*args),
            'uuid': lambda: UUID(**kwargs),
            'decimal': lambda: Decimal(*args, **kwargs),
        }

        if data_type in factory_functions:
            return factory_functions[data_type]()
        raise ValueError(f"Unknown data type {data_type}")

