import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.*;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.io.IOException;
import java.time.Duration;

public class WeatherDataIntegrator {

    private final Map<String, String> tokens = new HashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final ConcurrentHashMap<String, CachedWeatherData> cache = new ConcurrentHashMap<>();

    // Load tokens from a secure source
    public void loadTokens(Map<String, String> tokenMap) {
        this.tokens.putAll(tokenMap);
    }

    public CompletableFuture<WeatherData> fetchWeatherData(String location) {
        return fetchFromSourcesAsync(location)
                .thenApply(this::aggregateWeatherData)
                .exceptionally(ex -> handleException(ex));
    }

    private CompletableFuture<Map<String, WeatherData>> fetchFromSourcesAsync(String location) {
        Map<String, CompletableFuture<WeatherData>> futures = new HashMap<>();

        // Add OpenWeatherMap
        futures.put("OpenWeatherMap", fetchFromOpenWeatherMap(location));

        // Add WeatherAPI
        futures.put("WeatherAPI", fetchFromWeatherAPI(location));

        return CompletableFuture.allOf(futures.values().toArray(new CompletableFuture[0]))
                .thenApply(v -> {
                    Map<String, WeatherData> result = new HashMap<>();
                    for (Map.Entry<String, CompletableFuture<WeatherData>> entry : futures.entrySet()) {
                        try {
                            result.put(entry.getKey(), entry.getValue().get());
                        } catch (InterruptedException | ExecutionException e) {
                            throw new RuntimeException(e);
                        }
                    }
                    return result;
                });
    }

    private CompletableFuture<WeatherData> fetchFromOpenWeatherMap(String location) {
        String token = tokens.get("OpenWeatherMap");
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("https://api.openweathermap.org/data/2.5/weather?q=" + location + "&appid=" + token))
                .timeout(Duration.ofSeconds(10))
                .build();

        return sendRequest(request, "OpenWeatherMap");
    }

    private CompletableFuture<WeatherData> fetchFromWeatherAPI(String location) {
        String token = tokens.get("WeatherAPI");
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("http://api.weatherapi.com/v1/current.json?key=" + token + "&q=" + location))
                .timeout(Duration.ofSeconds(10))
                .build();

        return sendRequest(request, "WeatherAPI");
    }

    private CompletableFuture<WeatherData> sendRequest(HttpRequest request, String source) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
                if (response.statusCode() == 200) {
                    WeatherData data = parseWeatherResponse(response.body(), source);
                    cacheData(location, data); // Cache the data
                    return data;
                } else if (isRateLimitError(response)) {
                    throw new RateLimitException("Rate limit exceeded for " + source);
                } else {
                    throw new IOException("Failed to fetch weather data from " + source);
                }
            } catch (IOException | InterruptedException e) {
                handleNetworkIssue(e, source);
                return null;
            }
        }).handle((result, ex) -> {
            if (ex != null || result == null) {
                // Retry logic or fallback handling
                return fetchFromCache(location).orElseGet(() -> fetchFromSourcesAsync(location).join());
            } else {
                return result;
            }
        });
    }

    private WeatherData parseWeatherResponse(String responseBody, String source) {
        // Parse response based on the source format and return a WeatherData object
        return new WeatherData(responseBody, source);
    }

    private boolean isRateLimitError(HttpResponse<String> response) {
        // Implement logic to check for rate limit errors based on status codes or headers
        return false;
    }

    private void handleNetworkIssue(Exception e, String source) {
        System.err.println("Network issue with " + source + ": " + e.getMessage());
        // Additional logging and handling
    }

    private WeatherData aggregateWeatherData(Map<String, WeatherData> dataMap) {
        // Aggregate the weather data from different sources ensuring consistency
        return new AggregatedWeatherData(dataMap);
    }

    private void cacheData(String location, WeatherData data) {
        cache.put(location, new CachedWeatherData(System.currentTimeMillis(), data));
        scheduler.schedule(() -> cache.remove(location), 10, TimeUnit.MINUTES); // Cache for 10 minutes
    }

    private CompletableFuture<WeatherData> fetchFromCache(String location) {
        CachedWeatherData cached = cache.get(location);
        return CompletableFuture.completedFuture(cached != null ? cached.data : null);
    }

    private WeatherData handleException(Throwable ex) {
        System.err.println("Error fetching weather data: " + ex.getMessage());
        // Fallback logic or default response
        return new DefaultWeatherData();
    }
}

