#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Mock function to simulate fetching words from an external source
char* fetchWordsFromExternalSource() {
    // Simulated word list: "the", "an", "a"
    return strdup("the,an,a");
}

void callback(int completedOperations, const char *currentResult) {
    printf("Completed Operations: %d\nCurrent Result: %s\n", completedOperations, currentResult);
}

char* dynamicTrimAndCapitalize(const char *input, int sizeLimit, void (*progressCallback)(int, const char*)) {
    if (!input || !sizeLimit) return NULL;

    char *words = fetchWordsFromExternalSource();
    if (!words) return NULL;

    // Tokenize and trim words
    char buffer[1024];
    strcpy(buffer, input);
    char *token;
    char delimiters[] = ", ";
    int completedOperations = 0;

    token = strtok(words, delimiters);
    while (token != NULL) {
        size_t len = strlen(input);
        if (strncmp(input, token, strlen(token)) == 0 && (input[strlen(token)] == ' ' || input[strlen(token)] == '\0')) {
            memmove(input, input + strlen(token), len - strlen(token) + 1);
        }
        completedOperations++;
        progressCallback(completedOperations, input);

        token = strtok(NULL, delimiters);
    }

    // Calculate new size limit
    int averageWordLength = (strlen(words)) / 3;
    sizeLimit -= averageWordLength;

    char *result = strdup(input);
    if (!result) {
        free(words);
        return NULL;
    }

    // Capitalize each word in the result string
    char *start = result;
    for (char *ptr = result; *ptr; ptr++) {
        if (*ptr == ' ') {
            start++;
            *ptr = toupper(*ptr);
            if (*(ptr + 1)) *(ptr + 1) = tolower(*(ptr + 1));
            start = ptr + 1;
        } else {
            *start++ = tolower(*ptr);
        }
    }

    // Ensure result does not exceed size limit
    if (strlen(result) > sizeLimit) {
        free(result);
        free(words);
        return NULL;
    }

    progressCallback(completedOperations, result);
    free(words);
    return result;
}
