async function asyncArrayReduce(numbers, initialValue, callback, concurrencyLimit = 2) {
    const semaphore = new Semaphore(concurrencyLimit);

    let accumulator = initialValue;

    for (let i = 0; i < numbers.length; i++) {
        await semaphore.runExclusive(async () => {
            try {
                // Simulate an external API call with caching
                const cacheKey = `apiCall-${numbers[i]}`;
                if (!global[cacheKey]) {
                    global[cacheKey] = await axios.get(`https://api.example.com/data/${numbers[i]}`);
                }

                accumulator = callback(accumulator, numbers[i], i);
            } catch (error) {
                console.error('Error in reduction:', error);
                throw new Error('Reduction failed');
            }
        });
    }

    return accumulator;
}

