import time
import random
import logging
from cachetools import TTLCache
import stripe
import paypalrestsdk
import braintree
import sqlite3

# Configure logging
logging.basicConfig(level=logging.INFO)

# Initialize cache with a TTL of 300 seconds (5 minutes)
cache = TTLCache(maxsize=100, ttl=300)

# Database setup for storing tokens securely
conn = sqlite3.connect('transactions.db')
c = conn.cursor()
c.execute('''CREATE TABLE IF NOT EXISTS transaction_tokens 
             (id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT)''')

def process_payment(user_id, amount, currency='usd', gateway_preference=None):
    gateways = {
        'stripe': process_stripe,
        'paypal': process_paypal,
        'braintree': process_braintree
    }

    # Determine which gateway to use based on preference or availability
    if not gateway_preference:
        available_gateways = [name for name in gateways if is_gateway_available(name)]
        gateway_preference = random.choice(available_gateways)

    transaction_id = f"{user_id}-{int(time.time())}"
    cache_key = f"payment-{transaction_id}"

    # Check cache first
    if cache_key in cache:
        logging.info("Using cached response.")
        return cache[cache_key]

    for attempt in range(5):
        try:
            result = gateways[gateway_preference](user_id, amount, currency)

            if validate_transaction(result):
                store_token(transaction_id, result['token'])
                cache[cache_key] = result
                logging.info("Transaction successful.")
                return result

        except Exception as e:
            logging.error(f"Error processing payment: {e}")
            time.sleep(min(2 ** attempt + random.random(), 32)) # Exponential backoff

    raise RuntimeError("All retries failed.")

def is_gateway_available(gateway_name):
    # Simulated check for gateway availability
    return True

def process_stripe(user_id, amount, currency):
    stripe.api_key = 'sk_test_yourkey'
    try:
        charge = stripe.Charge.create(
            amount=int(amount * 100),  # Stripe amounts are in cents
            currency=currency,
            description=f"Charge for user {user_id}"
        )
        return {'token': charge['id']}
    except stripe.error.StripeError as e:
        logging.error(f"Stripe error: {e}")
        raise

def process_paypal(user_id, amount, currency):
    paypalrestsdk.configure({
        'mode': 'sandbox',
        'client_id': 'your_client_id',
        'client_secret': 'your_client_secret'
    })

    payment = paypalrestsdk.Payment({
        "intent": "sale",
        "payer": {
            "payment_method": "paypal"
        },
        "transactions": [{
            "amount": {
                "total": str(amount),
                "currency": currency
            }
        }]
    })

    if payment.create():
        logging.info("Payment created successfully.")
        return {'token': payment.id}
    else:
        raise RuntimeError("Failed to create PayPal payment.")

def process_braintree(user_id, amount, currency):
    braintree.Configuration.configure(
        environment=braintree.Environment.Sandbox,
        merchant_id='your_merchant_id',
        public_key='your_public_key',
        private_key='your_private_key'
    )

    result = braintree.Transaction.sale({
        "amount": str(amount),
        "payment_method_nonce": "fake-valid-nonce",
        "options": {
            "submit_for_settlement": True
        }
    })

    if result.is_success:
        return {'token': result.transaction.id}
    else:
        raise RuntimeError("Braintree transaction failed.")

def validate_transaction(response):
    # Placeholder for response validation logic
    return 'token' in response

def store_token(transaction_id, token):
    c.execute('INSERT INTO transaction_tokens (id, token) VALUES (?, ?)', (transaction_id, token))
    conn.commit()

# Example usage:
try:
    result = process_payment(user_id=12345, amount=100.00)
except RuntimeError as e:
    logging.error(f"Transaction failed: {e}")

conn.close()
