use anyhow::{Result, Context};

const RATE_LIMIT_SLEEP_DURATION: u64 = 500; // milliseconds

#[derive(Debug)]
struct Config {
    repository_url: String,
    branch_name: String,
    config_params: HashMap<String, String>,
}

impl Config {
    fn new(repository_url: &str, branch_name: &str) -> Self {
        Self {
            repository_url: repository_url.to_string(),
            branch_name: branch_name.to_string(),
            config_params: HashMap::new(),
        }
    }

    fn add_param(&mut self, key: &str, value: &str) {
        self.config_params.insert(key.to_string(), value.to_string());
    }
}

async fn sync_config_directory(config: Config) -> Result<()> {
    let client = Client::builder()
        .build()?
        .with_retry(|| async { Ok(()) })
        .with_rate_limit_sleep(RATE_LIMIT_SLEEP_DURATION);

    clone_repository(&config.repository_url, &config.branch_name)?;

    let config_files_path = PathBuf::from("path/to/config/files");
    let sorted_files = sort_config_files(&config_files_path)?;

    for file in sorted_files {
        if let Some(sequence_number) = extract_sequence_number_from_file(&file)? {
            println!("Sequence number: {}", sequence_number);
        }
        decrypt_and_validate_file(&file)?;
    }

    Ok(())
}

fn clone_repository(repository_url: &str, branch_name: &str) -> Result<()> {
    Command::new("git")
        .args(["clone", "--branch", branch_name, repository_url, "."])
        .status()
        .context("Failed to clone the repository")?;

    Ok(())
}

fn sort_config_files(config_files_path: &Path) -> Result<Vec<PathBuf>> {
    let mut files = fs::read_dir(config_files_path)?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .collect::<Vec<_>>();
    files.sort();
    Ok(files)
}

fn extract_sequence_number_from_file(file_path: &Path) -> Result<Option<usize>> {
    if file_path.is_file() {
        let file = File::open(file_path)?;
        let reader = BufReader::new(file);

        for (index, line) in reader.lines().enumerate() {
            if let Ok(line_content) = line {
                if line_content.contains("sequence_number") {
                    return Ok(Some(index));
                }
            }
        }
    }

    Ok(None)
}

fn decrypt_and_validate_file(file_path: &Path) -> Result<()> {
    let file = File::open(file_path)?;
    let mut reader = BufReader::new(file);

    let mut data = Vec::new();
    reader.read_to_end(&mut data)?;

    // Example decryption and validation
    let key = b"an_example_very_secure_key__"; // 32 bytes for AES256GCM-SIV
    let nonce = Nonce::from_slice(b"unique_nonce_12"); // Must be unique per message

    let cipher = Aes256GcmSiv::new_from_slice(key).unwrap();

    match cipher.decrypt(nonce, data.as_ref()) {
        Ok(decrypted_data) => {
            let mut hasher = Sha256::new();
            hasher.update(&decrypted_data);
            let result_hash = hasher.finalize();

            // Validate the decrypted content by comparing hashes or other means
            println!("Decryption successful: {:?}", result_hash);

            Ok(())
        }
        Err(_) => Err(anyhow::anyhow!("Failed to decrypt file")),
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let mut config = Config::new("https://example.com/repo.git", "main");
    config.add_param("param1", "value1");

    sync_config_directory(config).await
}
