// Abstract class for common cloud storage functionality
abstract class BaseCloudStorage implements ICloudStorage {
    protected final Logger logger = Logger.getLogger(getClass().getName());

    @Override
    public void uploadFile(String filePath, String destination) throws StorageException {
        // Implement with retry strategy and exponential backoff
    }

    @Override
    public void downloadFile(String source, String destination) throws StorageException {
        // Implement with similar strategies as above
    }

    protected void executeWithRetry(Runnable task) throws StorageException {
        int retries = 3;
        long delay = 1000; // Initial backoff delay in milliseconds

        for (int i = 0; i < retries; i++) {
            try {
                task.run();
                return;
            } catch (Exception e) {
                if (i == retries - 1) throw new StorageException("Max retries reached", e);
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new StorageException("Interrupted during retry wait", ie);
                }
                delay *= 2; // Exponential backoff
            }
        }
    }

    @Override
    public void setVersioningPolicy(VersioningPolicy policy) throws StorageException {
        // Implement versioning logic
    }
}

