```python
import json
import logging
import threading
from hashlib import md5, sha256
from collections import OrderedDict
from concurrent.futures import ThreadPoolExecutor
import boto3
import botocore.exceptions
import requests

# Set up basic logging with timestamps
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ConfigurationCache:
    def __init__(self, max_size=100):
        self.cache = OrderedDict()
        self.lock = threading.Lock()
        self.max_size = max_size

    def get(self, key):
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
                return self.cache[key]
            return None

    def put(self, key, value):
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
            else:
                if len(self.cache) >= self.max_size:
                    self.cache.popitem(last=False)
            self.cache[key] = value

class ConfigManager:
    def __init__(self, local_file_path='config.json', ssm_parameter_name='/app/config', max_cache_size=100):
        self.local_file_path = local_file_path
        self.ssm_client = boto3.client('ssm')
        self.parameter_name = ssm_parameter_name
        self.cache = ConfigurationCache(max_cache_size)

    def load_local_config(self):
        try:
            with open(self.local_file_path, 'r') as file:
                return json.load(file)
        except Exception as e:
            logging.error(f"Failed to read local config: {e}")
            return None

    def fetch_remote_config(self):
        try:
            response = self.ssm_client.get_parameter(Name=self.parameter_name, WithDecryption=True)
            return json.loads(response['Parameter']['Value'])
        except botocore.exceptions.BotoCoreError as e:
            logging.error(f"SSM API error: {e}")
            return None

    def get_configuration(self):
        config = self.load_local_config()
        if config is not None:
            return config
        remote_config = self.fetch_remote_config()
        if remote_config is not None:
            return remote_config
        logging.warning("Both local and remote configurations failed. Returning empty configuration.")
        return {}

class HashCalculator:
    def __init__(self, max_cache_size=100):
        self.cache = ConfigurationCache(max_cache_size)
        self.executor = ThreadPoolExecutor()

    def compute_hash(self, string, algorithm='md5'):
        if not string or len(string) > 1_000_000:
            raise ValueError("Invalid input string")

        cache_key = (string, algorithm)
        cached_result = self.cache.get(cache_key)
        if cached_result is not None:
            return cached_result

        future = self.executor.submit(self._compute_hash_task, string, algorithm)
        result = future.result()
        self.cache.put(cache_key, result)
        return result

    def _compute_hash_task(self, string, algorithm):
        hasher = md5() if algorithm == 'md5' else sha256()
        for chunk in iter(lambda: string[:4096], ''):
            hasher.update(chunk.encode('utf-8'))
            string = string[4096:]
        return hasher.hexdigest()

def unit_tests():
    # Example Unit Test Cases
    assert HashCalculator().compute_hash("test", "md5") == md5("test".encode('utf-8')).hexdigest()
    assert HashCalculator().compute_hash("test", "sha256") == sha256("test".encode('utf-8')).hexdigest()

if __name__ == "__main__":
    unit_tests()  # Run the tests
```

