import time
import random
from functools import wraps

# Simulated Payment Gateway Interface
class PaymentGateway:
    def __init__(self, name, rate_limit):
        self.name = name
        self.rate_limit = rate_limit
        self.success_count = 0
        self.failure_count = 0

    def process_transaction(self, transaction):
        # Simulate processing with random success/failure
        if random.choice([True, False]):
            return {"status": "success", "transaction_id": f"{self.name}_txn_{random.randint(1000, 9999)}"}
        else:
            raise Exception(f"Transaction failed for {self.name}")

def retry_with_exponential_backoff(max_attempts=5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            delay = 1
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Attempt {attempts + 1} failed: {e}")
                    time.sleep(delay)
                    delay *= 2
                    attempts += 1
            raise Exception("Max retry attempts reached")
        return wrapper
    return decorator

def rate_limited(rate_limit):
    def decorator(func):
        last_called = [0.0]
        @wraps(func)
        def wrapper(*args, **kwargs):
            elapsed = time.perf_counter() - last_called[0]
            wait_time = max(1 / rate_limit - elapsed, 0)
            if wait_time > 0:
                time.sleep(wait_time)
            ret = func(*args, **kwargs)
            last_called[0] = time.perf_counter()
            return ret
        return wrapper
    return decorator

class TransactionManager:
    def __init__(self):
        self.gateways = [
            PaymentGateway("GatewayA", rate_limit=5),
            PaymentGateway("GatewayB", rate_limit=3)
        ]
        self.failed_gateways = set()

    @retry_with_exponential_backoff()
    @rate_limited(1)  # Global API limit
    def process_transactions(self, transactions):
        max_weighted_sum = float('-inf')
        corresponding_transaction_id = None

        for transaction in transactions:
            if not self.is_valid_transaction(transaction):
                continue

            gateway = self.get_gateway_for_transaction(transaction)

            try:
                response = gateway.process_transaction(transaction)
                print(f"Transaction successful: {response}")

                # Update success metrics
                gateway.success_count += 1

                weighted_sum = transaction['amount'] * transaction['priority']
                if weighted_sum > max_weighted_sum:
                    max_weighted_sum = weighted_sum
                    corresponding_transaction_id = response["transaction_id"]

            except Exception as e:
                print(f"Error processing transaction: {e}")

                # Update failure metrics and handle failover
                gateway.failure_count += 1
                if gateway.name in self.failed_gateways:
                    continue

                if attempts >= max_attempts:
                    self.failed_gateways.add(gateway.name)

        return corresponding_transaction_id, max_weighted_sum

    def is_valid_transaction(self, transaction):
        # Example criteria: Transaction age < 30 days, no more than 3 transactions per IP in the past 5 seconds
        if transaction['age'] > 30 or self.transaction_rate_exceeded(transaction['ip_address']):
            return False
        return True

    def transaction_rate_exceeded(self, ip_address):
        # Check rate limit logic here (omitted for brevity)
        return False

    def get_gateway_for_transaction(self, transaction):
        available_gateways = [g for g in self.gateways if g.name not in self.failed_gateways]
        if not available_gateways:
            raise Exception("No gateways available")

        # Simple round-robin load balancing
        gateway_index = hash(transaction['id']) % len(available_gateways)
        return available_gateways[gateway_index]

    def monitor_health(self):
        for gateway in self.gateways:
            print(f"{gateway.name} - Success: {gateway.success_count}, Failures: {gateway.failure_count}")

# Example usage
manager = TransactionManager()
transactions = [
    {"id": "txn1", "amount": 100, "priority": 2, "age": 10, "ip_address": "192.168.1.1"},
    # More transactions...
]
try:
    max_txn_id, max_weighted_sum = manager.process_transactions(transactions)
    print(f"Max weighted sum: {max_weighted_sum}, Transaction ID: {max_txn_id}")
except Exception as e:
    print(f"Processing failed: {e}")

manager.monitor_health()
```

This code provides a basic structure to handle transactions with multiple payment gateways, including retry mechanisms with exponential backoff, rate limiting, and failover. You may need to adapt the logic for actual integration with specific third-party APIs and database systems.

