// ImageConverter.h

#ifndef IMAGE_CONVERTER_H
#define IMAGE_CONVERTER_H

#include <string>
#include <vector>
#include <mutex>

class ImageConverter {
public:
    explicit ImageConverter(const std::string& outputPath);

    void convertImage(const std::string& inputPath, const std::string& formatType, int quality = 75);
    void batchConvertAndSave(const std::vector<std::string>& filePaths, const std::string& formatType, int quality = 75);

    void setLoggingOutput(bool toConsole, bool toFile);
    void setLogLevel(int level); // e.g., 0 for INFO, 1 for DEBUG

private:
    std::string outputPath;
    bool logToConsole;
    bool logToFile;
    int logLevel;

    static std::mutex conversionMutex; // For thread safety in batch conversions

    void logMessage(const std::string& message);
    void convertAndSave(const std::string& inputPath, const std::string& formatType, int quality);
};

#endif
