```cpp
// ImageConverter.cpp

#include "ImageConverter.h"
#include <Magick++.h>
#include <iostream>
#include <fstream>
#include <thread>

std::mutex ImageConverter::conversionMutex;

ImageConverter::ImageConverter(const std::string& outputPath) : outputPath(outputPath), logToConsole(true), logToFile(false), logLevel(0) {
    Magick::InitializeMagick(nullptr);
}

void ImageConverter::convertImage(const std::string& inputPath, const std::string& formatType, int quality) {
    convertAndSave(inputPath, formatType, quality);
}

void ImageConverter::batchConvertAndSave(const std::vector<std::string>& filePaths, const std::string& formatType, int quality) {
    std::vector<std::thread> threads;
    for (const auto& filePath : filePaths) {
        threads.emplace_back(&ImageConverter::convertAndSave, this, filePath, formatType, quality);
    }
    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void ImageConverter::setLoggingOutput(bool toConsole, bool toFile) {
    std::lock_guard<std::mutex> guard(conversionMutex);
    logToConsole = toConsole;
    logToFile = toFile;
}

void ImageConverter::setLogLevel(int level) {
    std::lock_guard<std::mutex> guard(conversionMutex);
    logLevel = level;
}

void ImageConverter::logMessage(const std::string& message) {
    if (logToConsole) {
        std::cout << message << std::endl;
    }
    if (logToFile) {
        std::ofstream logFile(outputPath + "/conversion.log", std::ios_base::app);
        logFile << message << std::endl;
    }
}

void ImageConverter::convertAndSave(const std::string& inputPath, const std::string& formatType, int quality) {
    try {
        std::lock_guard<std::mutex> guard(conversionMutex);

        Magick::Image image;
        image.read(inputPath);

        // Set the compression quality if applicable
        image.compressionQuality(quality);

        std::string outputFilePath = outputPath + "/" + inputPath.substr(inputPath.find_last_of("/\\") + 1) + "." + formatType;
        image.write(outputFilePath + "." + formatType);

        logMessage("Converted and saved: " + inputPath + " to " + outputFilePath);
    } catch (const std::exception& ex) {
        logMessage("Error converting image: " + std::string(ex.what()));
    }
}
