### C Function (`convert_images_to_pdf.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <time.h>

#define TIMEOUT_SECONDS 5

void *convert_images_to_pdf(void *arg) {
    sem_t semaphore;
    sem_init(&semaphore, 0, 1);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += TIMEOUT_SECONDS;

    if (sem_timedwait(&semaphore, &ts) == -1 && errno == ETIMEDOUT) {
        printf("Semaphore wait timed out\n");
        return NULL;
    }

    // Conversion logic here

    sem_post(&semaphore);
    sem_destroy(&semaphore);

    return NULL;
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, convert_images_to_pdf, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}
```

