use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::time::Duration;

#[derive(Serialize)]
pub struct RequestData {
    pub text: String,
}

#[derive(Deserialize)]
pub struct SentimentResponse {
    pub sentiment: String,
}

pub async fn fetch_sentiment_analysis(text: &str) -> Result<SentimentResponse, reqwest::Error> {
    let client = Client::builder()
        .timeout(Duration::from_secs(5))
        .danger_accept_invalid_certs(true)
        .build()?;

    let response = client.post("https://api.sentimentanalysis.com/analyze")
        .json(&RequestData { text: text.to_string() })
        .send()
        .await?;

    Ok(response.json::<SentimentResponse>().await?)
}
