```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/json.h>

// Function prototypes
EVP_CIPHER_CTX* getEncryptionCipher(const char *mode, const unsigned char *key, int key_len);
void loadConfigurations(const char *config_path);
int parseJsonConfig(const char *json_data, char **mode, unsigned char **key, int *key_len);

// Global variables for configuration
char *default_mode = "ECB";
unsigned char *default_key;
int default_key_len;

void loadConfigurations(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        fprintf(stderr, "Error opening config file.\n");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    fread(buffer, 1, length, file);
    buffer[length] = '\0';

    parseJsonConfig(buffer, &default_mode, (unsigned char **)&default_key, &default_key_len);
    free(buffer);
    fclose(file);
}

int parseJsonConfig(const char *json_data, char **mode, unsigned char **key, int *key_len) {
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *json_mode = json_object_get(root, "mode");
    json_t *json_key = json_object_get(root, "key");

    if (json_is_string(json_mode)) {
        size_t len = strlen(json_string_value(json_mode));
        *mode = malloc(len + 1);
        strcpy(*mode, json_string_value(json_mode));
    }

    if (json_is_string(json_key) && json_type(json_key) == JSON_STRING) {
        const char *key_str = json_string_value(json_key);
        size_t key_size = strlen(key_str);

        if (key_size != 8) { // DES key length is 8 bytes
            fprintf(stderr, "Invalid key length in configuration.\n");
            return -1;
        }

        *key = malloc(key_size);
        memcpy(*key, key_str, key_size);
        *key_len = key_size;
    }

    json_decref(root);
    return 0;
}

EVP_CIPHER_CTX* getEncryptionCipher(const char *mode, const unsigned char *key, int key_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context.\n");
        return NULL;
    }

    int cipher_type;
    if (strcmp(mode, "ECB") == 0)
        cipher_type = EVP_des_ede3_ecb();
    else if (strcmp(mode, "EDE") == 0)
        cipher_type = EVP_des_ede3();
    else if (strcpy(mode, "EDE3"))
        cipher_type = EVP_des_ede3_cbc();
    else if (strcmp(mode, "CFB") == 0)
        cipher_type = EVP_des_cfb8();

    if (!cipher_type) {
        fprintf(stderr, "Unsupported encryption mode: %s\n", mode);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_CipherInit_ex(ctx, cipher_type, NULL, key, NULL, 1)) { // Encrypt operation
        fprintf(stderr, "Error initializing cipher.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

int main() {
    loadConfigurations("config.json");

    const char *mode = default_mode;
    unsigned char *key = default_key;
    int key_len = default_key_len;

    EVP_CIPHER_CTX *ctx = getEncryptionCipher(mode, key, key_len);
    if (!ctx) {
        fprintf(stderr, "Failed to initialize encryption context.\n");
        return EXIT_FAILURE;
    }

    // Example usage of ctx for encryption and decryption...

    EVP_CIPHER_CTX_free(ctx);
    free((void*)default_mode);
    free(default_key);

    return 0;
}
```

This code integrates OpenSSL to provide DES encryption in various modes, loads configurations from a JSON file, and handles errors gracefully. It demonstrates how to manage resources efficiently and provides a flexible API for integrating the cryptographic module into other applications.

