DataTableReader processByteArrayAsync(const std::vector<uint8_t>& byteArray) {
    std::string key = json(byteArray).dump(); // Serialize the array to JSON string as a key for caching

    auto it = cache.find(key);
    if (it != cache.end()) {
        return it->second;
    }

    try {
