                reader.read("Processed data from API: " + jsonString);

                promise.set_value(reader);
            } catch (const std::exception& e) {
                cerr << "Exception during API processing: " << e.what() << endl;
                promise.set_exception(std::current_exception());
            }
        }).detach();

        DataTableReader response = future.get(); // Wait for the result
        cache[key] = response; // Store in cache

        return response;
    } catch (const std::exception& e) {
        cerr << "Exception: " << e.what() << endl;
    }

    return DataTableReader();
}

