// Custom exception for memory allocation failures
class MemoryAllocationException : public std::runtime_error {
public:
    explicit MemoryAllocationException(const std::string& message)
        : std::runtime_error("Memory Allocation Error: " + message) {}
};

// Octree Node Structure
struct OctreeNode {
    bool isLeaf;
    int childCount;
    std::vector<std::unique_ptr<OctreeNode>> children;

    OctreeNode() : isLeaf(true), childCount(0) {}

    void subdivide();
};

void OctreeNode::subdivide() {
    if (!isLeaf) return; // Already subdivided

    isLeaf = false;
    childCount = 8;
    for (int i = 0; i < 8; ++i) {
        children.emplace_back(std::make_unique<OctreeNode>());
    }
}

// Octree Class
class Octree {
public:
    Octree(float featureSize, int initialLeafNodes, size_t maxDataCapacity);

private:
    std::unique_ptr<OctreeNode> root;
    float featureSize;
    size_t maxDataCapacity;
    mutable std::mutex mutex;

    void initialize();
};

Octree::Octree(float featureSize, int initialLeafNodes, size_t maxDataCapacity)
    : featureSize(featureSize), maxDataCapacity(maxDataCapacity) {

    try {
        initialize();
    } catch (const std::bad_alloc&) {
        throw MemoryAllocationException("Failed to allocate memory for Octree initialization.");
    }
}

void Octree::initialize() {
    root = std::make_unique<OctreeNode>();

    // Initial setup
    if (initialLeafNodes > 0) {
        for (int i = 0; i < initialLeafNodes; ++i) {
            root->subdivide();
        }
    }

    std::lock_guard<std::mutex> lock(mutex);

    // Additional initialization and logging can be performed here
    std::cout << "Octree initialized with feature size: " 
              << featureSize << ", max data capacity: " 
              << maxDataCapacity << std::endl;
}

