CACHE_SIZE = int(os.getenv('CACHE_SIZE', 100))
RATE_LIMIT = int(os.getenv('RATE_LIMIT', 5))  # requests per second
RETRY_MAX_ATTEMPTS = int(os.getenv('RETRY_MAX_ATTEMPTS', 3))

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class URLValidator:
    ALLOWED_DOMAINS = {'example.com', 'anotherdomain.org'}

    @staticmethod
    def is_valid(url):
        try:
            parsed_url = urlparse(url)
            return all([parsed_url.scheme, parsed_url.netloc]) and parsed_url.netloc in URLValidator.ALLOWED_DOMAINS
        except Exception:
            return False

class HTTPFetcher:
    def __init__(self, max_connections=MAX_CONNECTIONS):
        self.session = requests.Session()
        adapter = requests.adapters.HTTPAdapter(pool_maxsize=max_connections)
        self.session.mount('http://', adapter)
        self.session.mount('https://', adapter)

    @retry(stop_max_attempt_number=RETRY_MAX_ATTEMPTS, wait_exponential_multiplier=1000)
    def fetch_url(self, url):
        try:
            response = self.session.head(url, timeout=5)  # Use HEAD to get headers
            return {
                'url': url,
                'headers': dict(response.headers),
                'content_length': response.headers.get('Content-Length', None)
            }
        except requests.RequestException as e:
            logger.error(f"Error fetching URL {url}: {e}")
            raise

class CacheManager:
    def __init__(self, size=CACHE_SIZE):
        self.cache = LRUCache(maxsize=size)

    @cachedmethod(lambda self: hashkey('fetch_url'), key=lambda url, cm=self.cache: (cm, url), lock=lambda _: True)
    def cache_response(self, response_data):
        return response_data

class URLProcessor:
    def __init__(self, rate_limit=RATE_LIMIT):
        self.rate_limiter = self._create_rate_limiter(rate_limit)

    @retry(stop_max_attempt_number=RETRY_MAX_ATTEMPTS, wait_exponential_multiplier=1000)
    def process_url(self, url, http_fetcher, cache_manager):
        if URLValidator.is_valid(url):
            response_data = cache_manager.cache_response(http_fetcher.fetch_url(url))
            return response_data
        else:
            logger.warning(f"Invalid URL: {url}")
            return None

    def _create_rate_limiter(self, rate_limit):
        interval = 1.0 / float(rate_limit)
        last_called = [0.0]

        def rate_limited_function():
            elapsed = time.perf_counter() - last_called[0]
            left_to_wait = interval - elapsed
            if left_to_wait > 0:
                time.sleep(left_to_wait)
            last_called[0] = time.perf_counter()

        return rate_limited_function

def main():
    http_fetcher = HTTPFetcher()
    cache_manager = CacheManager()
    url_processor = URLProcessor()

    consumer = KafkaConsumer('urls', bootstrap_servers='localhost:9092')

    with ThreadPoolExecutor(max_workers=MAX_CONNECTIONS) as executor:
        futures = []

        for message in consumer:
            urls = message.value.decode('utf-8').split(',')

            for url in urls:
                url_processor.rate_limiter()
                futures.append(executor.submit(url_processor.process_url, url, http_fetcher, cache_manager))

        for future in as_completed(futures):
            result = future.result()
            if result:
                logger.info(f"Fetched data: {result}")

if __name__ == "__main__":
    main()
```

### Notes:

1. **Kafka Integration**: The code uses `kafka-python` library to consume URLs from a Kafka topic named "urls".
2. **Connection Pooling**: Managed using `requests.adapters.HTTPAdapter`.
3. **Cache Mechanism**: Implemented with `cachetools.LRUCache`.
4. **Retries and Backoff**: Utilizes the `retrying` library for retry logic.
5. **URL Validation**: Checks if URLs belong to allowed domains and are well-formed.
6. **Rate Limiting**: Simple function ensures rate limiting between requests.
7. **Logging**: Basic logging setup with Python's built-in `logging` module.

