#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <curl/curl.h>

// Helper function to format message using va_list
static char *format_message(const char *message, va_list args) {
    size_t buffer_size = 512;
    char *buffer = malloc(buffer_size);
    if (!buffer) return NULL;

    while (1) {
        va_list args_copy;
        va_copy(args_copy, args);

        int length = vsnprintf(buffer, buffer_size, message, args_copy);

        if (length >= 0 && length < buffer_size) {
            free(va_end(args_copy));
            return buffer;
        }

        if (length < 0) { // Buffer size is too small
            free(buffer);
            buffer_size *= 2; 
            buffer = realloc(buffer, buffer_size);
            if (!buffer) {
                perror("Failed to allocate memory for formatted message");
                return NULL;
            }
        } else {
            free(va_end(args_copy));
            buffer_size = length + 1;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                perror("Failed to reallocate memory for formatted message");
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
}

// Function to log messages to a remote server
int log_to_server(const char *url, int level, const char *message, va_list args) {
    CURL *curl;
    CURLcode res;

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) return -1;

    char *formatted_message = format_message(message, args);
    if (!formatted_message) {
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return -1;
    }

    // Construct the JSON payload
    char payload[1024];
    snprintf(payload, sizeof(payload), 
             "{\"level\":%d,\"message\":\"%s\"}", level, formatted_message);

    free(formatted_message);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    // Add more custom headers if needed
    // headers = curl_slist_append(headers, "Custom-Header: value");

    // Set CURL options
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Retry mechanism for failed HTTP requests
    int retries = 3;
    while (retries > 0) {
        res = curl_easy_perform(curl);

        if (res == CURLE_OK) break;

        printf("CURL error: %s\n", curl_easy_strerror(res));
        retries--;

        // Sleep before retrying to avoid excessive CPU usage
        sleep(1); 
    }

    // Cleanup
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to log message after %d attempts\n", 3 - retries);
    }

    curl_global_cleanup();

    return res == CURLE_OK ? 0 : -1;
}
```

