#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <future>
#include <fstream>
#include <chrono>

// Mockup for third-party image library functions
namespace ImageLib {
    bool Convert(const std::string& inputPath, const std::string& outputPath, int quality) {
        // Simulate conversion process
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        return true; // Return false to simulate failure
    }
}

class Logger {
public:
    enum class Output { CONSOLE, FILE };

    static void Configure(Output output, const std::string& filePath = "") {
        currentOutput = output;
        if (output == Output::FILE) {
            logFile.open(filePath);
        }
    }

    static void Log(const std::string& message) {
        std::lock_guard<std::mutex> lock(logMutex);
        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::string timeStr = std::ctime(&now);

        if (currentOutput == Output::CONSOLE) {
            std::cout << "[" << timeStr.substr(0, timeStr.length() - 1) << "] " << message << std::endl;
        } else if (logFile.is_open()) {
            logFile << "[" << timeStr.substr(0, timeStr.length() - 1) << "] " << message << std::endl;
        }
    }

private:
    static Output currentOutput;
    static std::ofstream logFile;
    static std::mutex logMutex;
};

Logger::Output Logger::currentOutput = Logger::Output::CONSOLE;
std::ofstream Logger::logFile;
std::mutex Logger::logMutex;

class ImageConverter {
public:
    ImageConverter(int quality, int maxThreads)
        : imageQuality(quality), maxConversions(maxThreads) {}

    void ConvertImages(const std::vector<std::pair<std::string, std::string>>& filePaths) {
        std::vector<std::future<void>> futures;

        for (const auto& [inputPath, outputPath] : filePaths) {
            futures.emplace_back(std::async(std::launch::async, &ImageConverter::ConvertSingleImage, this, inputPath, outputPath));
        }

        for (auto& future : futures) {
            try {
                future.get();
            } catch (const std::exception& e) {
                Logger::Log("Error during conversion: " + std::string(e.what()));
            }
        }
    }

private:
    int imageQuality;
    int maxConversions;

    void ConvertSingleImage(const std::string& inputPath, const std::string& outputPath) {
        auto startTime = std::chrono::system_clock::now();

        Logger::Log("Starting conversion: " + inputPath);
        bool success = ImageLib::Convert(inputPath, outputPath, imageQuality);

        if (success) {
            Logger::Log("Successfully converted: " + inputPath);
        } else {
            Logger::Log("Failed to convert: " + inputPath);
        }

        auto endTime = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();

        Logger::Log("Finished conversion in " + std::to_string(duration) + "ms");
    }
};

int main(int argc, char* argv[]) {
    // Parse command-line arguments to set quality, logging configuration, and max threads
    int quality = 90; // Default quality level
    int maxThreads = std::thread::hardware_concurrency(); // Use all available cores by default

    Logger::Configure(Logger::Output::CONSOLE); // Default to console logging

    if (argc > 1) {
        quality = std::stoi(argv[1]); // Assume first argument is quality level
    }

    if (argc > 2) {
        maxThreads = std::stoi(argv[2]); // Assume second argument is max threads
    }

    std::vector<std::pair<std::string, std::string>> filePaths = {
        {"input1.jpg", "output1.png"},
        {"input2.jpg", "output2.png"}
        // Add more file paths as needed
    };

    ImageConverter converter(quality, maxThreads);
    converter.ConvertImages(filePaths);

    return 0;
}
```

### Key Features Implemented:

1. **Quality Control**: Controlled via the constructor parameter `imageQuality`.
2. **Logging**: Configurable to log to console or a file with timestamps.
3. **Performance Optimization**: Utilizes multi-threading for concurrent conversions.
4. **Resource Management**: Simulated through mock functions; ensure proper cleanup in real implementations.
5. **Command-line Interface**: Parses quality level and max threads from command-line arguments.
6. **Integration Testing**: Not included here but can be implemented using a testing framework like Google Test.
7. **Error Handling and Recovery**: Continues processing other images even if one fails.
8. **User Experience**: Logs detailed information about each conversion process.
9. **Memory and File I/O Management**: Uses efficient logging and resource management practices.
10. **Maintainability and Code Organization**: Separated concerns into `Logger` and `ImageConverter` classes.

This code is a basic framework and can be expanded with actual image processing libraries like OpenCV or similar, along with more robust error handling and testing.
